local SCRIPT_NAME = "TrackMatic"

-- ═══════════════════════════════════════════════════════════════════════════════════
-- shared helpers (v1.1.0)
-- ═══════════════════════════════════════════════════════════════════════════════════
-- purpose: a few small helpers used by the builders and the ui.
-- note: trackmatic has no protected calls. every cherax api call is a direct call to a
--       documented function, so a real error shows up in the cherax log at the
--       line that caused it instead of being swallowed.

-- true when a tooltip was opened (EndTooltip is then due). older cherax builds
-- return nothing from BeginTooltip, newer ones return a bool.
function tg_ui_tooltip()
    return ImGui.BeginTooltip() ~= false
end

-- ground height from cherax (nil when it doesn't know)
function tg_ground_z(x, y)
    local found, z = GTA.GetGroundZ(x, y)
    if found and z and z > -200 then return z end
    return nil
end

-- read a text file (nil when it isn't there)
function tg_file_read(path)
    if not path or not FileMgr.DoesFileExist(path) then return nil end
    local content = FileMgr.ReadFileContent(path)
    if type(content) == "string" then return content end
    return nil
end

-- write a text file. true when it was written
function tg_file_write(path, data)
    if not path then return false end
    return FileMgr.WriteFileContent(path, data, false) == true
end

-- delete one entity
function tg_delete(h)
    if not h or h == 0 then return false end
    entities.delete_by_handle(h)
    return true
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.8.8 prime crash diagnostics
-- ═══════════════════════════════════════════════════════════════════════════════════
-- purpose: prime can hard-crash before lua errors are printed. these functions
-- write a step-by-step breadcrumb file so the last successful phase is visible
-- after restarting the game.
TG_PRIME_DIAG_ENABLED = true
TG_PRIME_DIAG_CONSOLE = false -- normal startup breadcrumbs stay off the Cherax console
TG_PRIME_DIAG_TEXT = ""
TG_PRIME_DIAG_STEP = 0
TG_PRIME_DIAG_BOOT_ID = tostring(os.time and os.time() or 0)

function tg_prime_diag_file_path()
    local root = FileMgr.GetMenuRootPath()
    if not root or root == "" then return nil end
    return tostring(root) .. "\\Lua\\TrackMatic\\prime_crash_diag.log", tostring(root) .. "\\Lua\\TrackMatic"
end

function tg_prime_diag_write_file(line)
    if not TG_PRIME_DIAG_ENABLED then return end
    local path, dir = tg_prime_diag_file_path()
    if not path then return end
    FileMgr.CreateDir(dir)
    TG_PRIME_DIAG_TEXT = tostring(TG_PRIME_DIAG_TEXT or "") .. tostring(line or "") .. "\n"
    FileMgr.WriteFileContent(path, TG_PRIME_DIAG_TEXT, false)
end

function tg_prime_diag(phase, msg)
    if not TG_PRIME_DIAG_ENABLED then return end
    TG_PRIME_DIAG_STEP = (tonumber(TG_PRIME_DIAG_STEP or 0) or 0) + 1
    local line = "[PRIME_DIAG][" .. tostring(TG_PRIME_DIAG_STEP) .. "][" .. tostring(phase or "PHASE") .. "] " .. tostring(msg or "")
    tg_prime_diag_write_file(line)
    if TG_PRIME_DIAG_CONSOLE then Logger.LogInfo("[TrackMatic] " .. line) end
end

function tg_prime_diag_reset()
    TG_PRIME_DIAG_TEXT = ""
    TG_PRIME_DIAG_STEP = 0
    tg_prime_diag_write_file("=== TrackMatic Prime Crash Diagnostic ===")
    tg_prime_diag_write_file("boot_id=" .. tostring(TG_PRIME_DIAG_BOOT_ID))
    tg_prime_diag_write_file("note=If the game hard-crashes, the final PRIME_DIAG line below is the last completed phase.")
end

tg_prime_diag_reset()
tg_prime_diag("BOOT_TOP", "script file reached top; SCRIPT_NAME=" .. tostring(SCRIPT_NAME))


