local 
-- Production console policy: only player-launched build/game/save summaries are informational.
-- Critical errors continue through tg_error / Logger.LogError independently.
TG_PM_VERBOSE_LOGS = false
function tg_should_suppress_log(msg)
    if TG_PM_VERBOSE_LOGS == true then return false end
    msg = tostring(msg or "")
    return not (msg:find("[BUILD_SUMMARY]", 1, true) == 1 or
                msg:find("[BUILD]", 1, true) == 1 or
                msg:find("[START_MARKERS]", 1, true) == 1 or
                msg:find("[GAME_SUMMARY]", 1, true) == 1 or
                msg:find("[SAVE_SUMMARY]", 1, true) == 1)
end

function tg_log(msg)
    if tg_should_suppress_log(msg) then return end
    msg = tostring(msg or "")
    tg_prime_diag_write_file("[LOG] " .. msg)
    Logger.LogInfo("[TrackMatic] " .. msg)
end

local function tg_error(msg)
    msg = tostring(msg or "")
    tg_prime_diag_write_file("[ERROR] " .. msg)
    Logger.LogError("[TrackMatic] " .. msg)
end

local function tg_toast(msg, ms)
    GUI.AddToast("TrackMatic", tostring(msg or ""), ms or 3500, eToastPos.TOP_RIGHT)
end


