-- v0.6.1 Generation cancellation token.
-- Clear Track / Test Objects increments this token; all long-running builders check it after yields/previews.
TG_GENERATION_TOKEN = TG_GENERATION_TOKEN or 0
TG_CANCEL_GENERATION = false
TG_CANCEL_REASON = ""

function tg_generation_start(label)
    TG_GENERATION_TOKEN = (tonumber(TG_GENERATION_TOKEN or 0) or 0) + 1
    TG_CANCEL_GENERATION = false
    TG_CANCEL_REASON = ""
    TG_WORLD_OBSTACLE_PROBE_CACHE = {}
    TG_WORLD_OBSTACLE_STATS = { checked = 0, blocked = 0, cache_hits = 0, native_fail = 0 }
    tg_log("[CANCEL][START] token=" .. tostring(TG_GENERATION_TOKEN) .. " label=" .. tostring(label or "generation"))
    return TG_GENERATION_TOKEN
end

function tg_generation_cancel(reason)
    TG_GENERATION_TOKEN = (tonumber(TG_GENERATION_TOKEN or 0) or 0) + 1
    TG_CANCEL_GENERATION = true
    TG_CANCEL_REASON = tostring(reason or "cancelled")
    tg_log("[WARN][CANCEL] generation cancelled token=" .. tostring(TG_GENERATION_TOKEN) .. " reason=" .. TG_CANCEL_REASON)
    return TG_GENERATION_TOKEN
end

function tg_generation_should_stop(token, label)
    if TG_CANCEL_GENERATION then
        tg_log("[WARN][CANCEL] stop requested label=" .. tostring(label or "") .. " reason=" .. tostring(TG_CANCEL_REASON or ""))
        return true
    end
    if token and token ~= TG_GENERATION_TOKEN then
        tg_log("[WARN][CANCEL] stale generation token label=" .. tostring(label or "") .. " old=" .. tostring(token) .. " current=" .. tostring(TG_GENERATION_TOKEN))
        return true
    end
    return false
end

