TG_WORLD_OBSTACLE_NATIVE_WARNED = TG_WORLD_OBSTACLE_NATIVE_WARNED or false

-- v1.0.6 Camera-directed true Angle-of-Attack launch with the entry deliberately below the player/vehicle.
-- The track model's long axis is local X, so banking it around local X tilts the road sideways.
-- We instead rotate around the model's local Y axis and combine that with yaw using a quaternion.
-- Result: three climbing pieces with zero side bank, followed by one flat exit piece.
TG_START_FOLLOWS_CAMERA = (TG_START_FOLLOWS_CAMERA ~= false)
TG_START_LAUNCH_RAMP = (TG_START_LAUNCH_RAMP ~= false)
TG_START_RAMP_AOA_DEG = math.abs(tonumber(TG_START_RAMP_AOA_DEG or 10.0) or 10.0)
TG_START_RAMP_UP_PIECES = math.max(1, math.floor(tonumber(TG_START_RAMP_UP_PIECES or 3) or 3))
TG_START_RAMP_SEGMENT_LENGTH = tonumber(TG_START_RAMP_SEGMENT_LENGTH or 53.0) or 53.0
TG_START_RAMP_FORWARD_OFFSET = tonumber(TG_START_RAMP_FORWARD_OFFSET or 18.0) or 18.0
-- Put the rear/start edge of piece 1 BELOW the player/vehicle anchor rather than merely near it.
-- GTA ped/vehicle Position is usually above the road surface, so -1.60 m intentionally buries
-- the ramp entry. This avoids a raised lip even when the local entity origin itself is above ground.
-- This value is the rear edge height relative to the player/vehicle position. Negative = below player.
TG_START_RAMP_BASE_HEIGHT = tonumber(TG_START_RAMP_BASE_HEIGHT or -1.60) or -1.60

-- v1.1.1 TrackMatic Minigames.
-- Every mode reuses the proven Smart Random connector path so normal road pieces stay
-- edge-connected to the prior floor piece. Elevation changes use a zero-bank AoA transition
-- whose first edge is aligned to the current flat track edge, then return to a flat exit.
TG_MINIGAME_ACTIVE = TG_MINIGAME_ACTIVE or false
TG_MINIGAME_MODE = TG_MINIGAME_MODE or "none"
TG_MINIGAME_STATE = TG_MINIGAME_STATE or "idle"
TG_MINIGAME_RUN_ID = tonumber(TG_MINIGAME_RUN_ID or 0) or 0
TG_MINIGAME_LEVELS = TG_MINIGAME_LEVELS or {}
TG_MINIGAME_CURRENT_LEVEL = tonumber(TG_MINIGAME_CURRENT_LEVEL or 0) or 0
TG_MINIGAME_SPIRAL_DIRECTION = TG_MINIGAME_SPIRAL_DIRECTION or "left"

-- Eliminator: create one complete level, wait until the driver crosses its midpoint,
-- then grow the front while deleting the rear one piece at a time. Each new level starts
-- with a three-piece AoA climb and a flat exit, creating the rising survival tower.
TG_ELIMINATOR_LEVEL_PIECES = math.max(14, math.floor(tonumber(TG_ELIMINATOR_LEVEL_PIECES or 20) or 20))
TG_ELIMINATOR_HALF_RATIO = tonumber(TG_ELIMINATOR_HALF_RATIO or 0.50) or 0.50
TG_ELIMINATOR_PROGRESS_RADIUS = tonumber(TG_ELIMINATOR_PROGRESS_RADIUS or 42.0) or 42.0
TG_ELIMINATOR_MONITOR_MS = math.max(80, math.floor(tonumber(TG_ELIMINATOR_MONITOR_MS or 180) or 180))
TG_ELIMINATOR_BUILD_DELAY_MS = math.max(45, math.floor(tonumber(TG_ELIMINATOR_BUILD_DELAY_MS or 95) or 95))
TG_ELIMINATOR_CULL_DELAY_MS = math.max(45, math.floor(tonumber(TG_ELIMINATOR_CULL_DELAY_MS or 105) or 105))
TG_ELIMINATOR_LEVEL_AOA = math.abs(tonumber(TG_ELIMINATOR_LEVEL_AOA or 10.0) or 10.0)
TG_ELIMINATOR_LEVEL_RAMP_PIECES = math.max(1, math.floor(tonumber(TG_ELIMINATOR_LEVEL_RAMP_PIECES or 3) or 3))
TG_ELIMINATOR_MAX_ALTITUDE = tonumber(TG_ELIMINATOR_MAX_ALTITUDE or 1200.0) or 1200.0
TG_ELIMINATOR_MIN_REAR_BUFFER = math.max(2, math.floor(tonumber(TG_ELIMINATOR_MIN_REAR_BUFFER or 4) or 4))

-- Static minigame course lengths. They keep the same camera-facing/below-player launch.
-- Sky Climb is intentionally different: it never flattens. Every piece keeps exactly
-- the same zero-bank AoA used by the Smart Random Loop launch ramp and climbs until
-- the configured altitude/piece ceiling.
TG_MINIGAME_SKYCLIMB_MAX_ALTITUDE = tonumber(TG_MINIGAME_SKYCLIMB_MAX_ALTITUDE or 1200.0) or 1200.0
TG_MINIGAME_SKYCLIMB_MAX_PIECES = math.max(24, math.floor(tonumber(TG_MINIGAME_SKYCLIMB_MAX_PIECES or 140) or 140))
TG_MINIGAME_SKYCLIMB_BUILD_DELAY_MS = math.max(35, math.floor(tonumber(TG_MINIGAME_SKYCLIMB_BUILD_DELAY_MS or 70) or 70))

TG_MINIGAME_DRIFTER_PIECES = math.max(24, math.floor(tonumber(TG_MINIGAME_DRIFTER_PIECES or 42) or 42))
