local function tg_now_ms()
    return Time.GetEpocheMs()
end

local function tg_debug(tag, msg, throttle_key)
    if not TG_DEBUG then return end
    if throttle_key then
        local now = tg_now_ms()
        local last = __tg_last_debug_by_key[throttle_key] or 0
        if now - last < TG_DEBUG_TICK_THROTTLE_MS then return end
        __tg_last_debug_by_key[throttle_key] = now
    end
    tg_log("[DEBUG][" .. tostring(tag or "GEN") .. "] " .. tostring(msg or ""))
end

local function tg_warn(tag, msg)
    tg_log("[WARN][" .. tostring(tag or "GEN") .. "] " .. tostring(msg or ""))
end

local function tg_trace_err(tag, err)
    local trace = debug and debug.traceback and debug.traceback(tostring(err), 2) or tostring(err)
    tg_error("[" .. tostring(tag or "ERROR") .. "] " .. trace)
end

