TG_TM_STARTUP_BANNER_PRINTED = false
local function tg_print_version_banner(reason)
    reason = tostring(reason or "INIT")
    -- Automatic planning previously invoked the version banner again.
    -- Print it only on launch, or on an explicit user-requested print action.
    local manual = (reason == "MANUAL" or reason == "prime_safe_button")
    if TG_TM_STARTUP_BANNER_PRINTED and not manual then return end
    TG_TM_STARTUP_BANNER_PRINTED = true

    local divider = "============================================================"
    local grey = "\27[38;5;247m"
    local white = "\27[97m"
    local reset = "\27[0m"
    local artwork = "\n\n" .. divider .. "\n\n" .. TG_ASCII_BANNER .. "\n"
    local details =
        "TrackMatic - Build the Impossible\n" ..
        "Developed By: Public_Urinal\n" ..
        "Discord: Public_Urinal\n" ..
        "Version: " .. tostring(TG_VERSION or "v1.0.0") .. " Production\n" ..
        "Build: 2026.10.26.101\n" ..
        "Last Updated: 2026-10-26\n"
    local footer = "\n" .. divider .. "\n\n"
    tg_banner_raw_log(grey .. artwork .. white .. details .. grey .. footer .. white .. "Happy Building " .. grey .. "ツ\n" .. reset)
end

tg_print_version_banner("INIT")

local function tg_handle(entity)
    if not entity then return "nil" end
    return tostring(entity)
end

local function tg_vec_str(v)
    if type(v) ~= "table" then return tostring(v) end
    return string.format("x=%.3f,y=%.3f,z=%.3f", tonumber(v.x) or 0, tonumber(v.y) or 0, tonumber(v.z) or 0)
end

local function tg_entity_key(entity)
    return tostring(entity or 0)
end

local function tg_set_meta(entity, meta)
    if entity and entity ~= 0 and meta then
        meta.handle = entity
        __tg_entity_meta[tg_entity_key(entity)] = meta
    end
end

local function tg_get_meta(entity)
    if not entity or entity == 0 then return nil end
    return __tg_entity_meta[tg_entity_key(entity)]
end

function tg_normalize_heading(h)
    h = tonumber(h) or 0.0
    h = h % 360.0
    if h < 0.0 then h = h + 360.0 end
    return h
end

local function tg_rotated_offset(base_heading, ox, oy, oz)
    local h = math.rad(tg_normalize_heading(base_heading))
    ox, oy, oz = tonumber(ox) or 0.0, tonumber(oy) or 0.0, tonumber(oz) or 0.0
    local c, s = math.cos(h), math.sin(h)
    return (c * ox - s * oy), (s * ox + c * oy), oz
end

local function tg_world_from_parent(parent_obj, ox, oy, oz, child_rot_z)
    local pm = tg_get_meta(parent_obj)
    if not pm then
        tg_warn("ATTACH", "missing parent meta for handle=" .. tg_handle(parent_obj) .. "; using 0,0,72 fallback")
        pm = { x = 0.0, y = 0.0, z = 72.0, heading = 0.0 }
    end
    local rx, ry, rz = tg_rotated_offset(pm.heading or 0.0, ox, oy, oz)
    return {
        x = (pm.x or 0.0) + rx,
        y = (pm.y or 0.0) + ry,
        z = (pm.z or 0.0) + rz,
        heading = tg_normalize_heading((pm.heading or 0.0) + (tonumber(child_rot_z) or 0.0)),
        parent = parent_obj,
    }
end

local function tg_v3_from_any(v)
    if v == nil then return nil end
    local x, y, z = nil, nil, nil
    local t = type(v)

    -- cherax V3 (userdata) and plain {x=,y=,z=} / {1,2,3} tables
    if t ~= "table" and t ~= "userdata" then return nil end
    x, y, z = v.x, v.y, v.z

    if (x == nil or y == nil or z == nil) and t == "table" then
        x = x or v[1]
        y = y or v[2]
        z = z or v[3]
    end

    if x == nil or y == nil or z == nil then return nil end
    return {x = tonumber(x) or 0.0, y = tonumber(y) or 0.0, z = tonumber(z) or 0.0}
end

local function tg_try_obj_position(obj, label)
    if not obj then return nil end
    local pos = tg_v3_from_any(obj.Position)
    if pos then if TG_DEBUG_POS then tg_debug("POS", tostring(label or "object") .. ".Position=" .. tg_vec_str(pos)) end; return pos end
    return nil
end

local function tg_get_local_position_heading(label)
    label = label or "local"
    local pos = nil
    local heading = 0.0

    -- GetLocalPed / GetLocalVehicle can be nil (loading screens, transitions)
    pos = tg_try_obj_position(GTA.GetLocalPed(), label .. ":GTA.GetLocalPed")
    if not pos then pos = tg_try_obj_position(GTA.GetLocalVehicle(), label .. ":GTA.GetLocalVehicle") end
    if not pos then pos = tg_try_obj_position(Players.GetCPed(GTA.GetLocalPlayerId()), label .. ":Players.GetCPed") end

    if not pos then
        pos = {x = 0.0, y = 0.0, z = 72.0}
        tg_warn("POS", label .. ": could not read local ped/vehicle Position safely; using fallback " .. tg_vec_str(pos))
    end

    if TG_START_FOLLOWS_CAMERA ~= false and type(tg_get_camera_track_heading) == "function" then
        local camera_heading = tg_get_camera_track_heading(heading, label)
        if camera_heading ~= nil then heading = tonumber(camera_heading) or heading end
    end

    return pos, heading
end

local function tg_noop_native(label, ...)
    if TG_DEBUG_NATIVE_ERRORS then tg_warn("NATIVE-LITE", tostring(label) .. " skipped") end
    return true
end

local function tg_report_state(reason)
    tg_log("[STATE][" .. tostring(reason or "manual") .. "] version=" .. TG_VERSION ..
        " objects=" .. tostring(objects and #objects or 0) ..
        " tintable=" .. tostring(entity_can_tint and #entity_can_tint or 0) ..
        " spawns=" .. tostring(__tg_spawn_success) .. "/" .. tostring(__tg_spawn_attempts) ..
        " failed=" .. tostring(__tg_spawn_fail) ..
        " native_fail=" .. tostring(__tg_native_fail) ..
        " mode=" .. tostring(construction_mode) ..
        " current_max=" .. tostring(current_max_fragement) ..
        " online=" .. tostring(util.is_session_started()))
end

-- Lightweight JSON fallback. The map_data file is optional for this first port;
-- if unavailable, the script falls back to native ground-Z checks and zero height.
package = package or {}
package.preload = package.preload or {}
if not package.preload["json"] then
    package.preload["json"] = function()
        return {
            decode = function(_)
                return nil
            end
        }
    end
end

filesystem = filesystem or {}
filesystem.stand_dir = filesystem.stand_dir or function()
    return ""
end

if not io.contents then
    io.contents = function(path)
        local f = io.open(path, "rb")
        if not f then return nil end
        local s = f:read("*a")
        f:close()
        return s
    end
end

-- Vector shim: original script uses v3.new() and v3(x,y,z).
v3 = v3 or {}
v3.new = v3.new or function(x, y, z)
    return V3.New(x or 0.0, y or 0.0, z or 0.0)
end
setmetatable(v3, {
    __call = function(_, x, y, z)
        return v3.new(x, y, z)
    end
})

-- Memory shim.
memory = memory or {}
memory.alloc = memory.alloc or function(size)
    return Memory.Alloc(size or 24)
end
memory.read_float = memory.read_float or function(ptr)
    return Memory.ReadFloat(ptr)
end

tg_prime_diag("NATIVE_HASHES", "about to define native hash table and invoke wrappers")
-- Native hash helper.
local N = {}
local function invoke_void(hash, ...)
    return Natives.InvokeVoid(hash, ...)
end
local function invoke_bool(hash, ...)
    return Natives.InvokeBool(hash, ...) == true
end
local function invoke_int(hash, ...)
    return Natives.InvokeInt(hash, ...) or 0
end
local function invoke_float(hash, ...)
    return Natives.InvokeFloat(hash, ...) or 0.0
end
local function invoke_v3(hash, ...)
    local a, b, c = Natives.InvokeV3(hash, ...)
    if type(a) == "table" or type(a) == "userdata" then return a end
    return v3.new(a or 0.0, b or 0.0, c or 0.0)
end
local function invoke_string(hash, ...)
    return Natives.InvokeString(hash, ...) or ""
end

-- Native hashes used by the original script.
