-- Camera yaw -> TrackMatic heading. The generator uses 0=+X / 90=+Y,
-- while GTA gameplay camera yaw maps through (-sin(yaw), cos(yaw)).
function tg_get_camera_track_heading(fallback_heading, label)
    fallback_heading = tonumber(fallback_heading or 0.0) or 0.0
    if TG_START_FOLLOWS_CAMERA == false then return tg_normalize_heading(fallback_heading) end

    local pitch, yaw = nil, nil
    local a, b, c = Natives.InvokeV3(N.GET_GAMEPLAY_CAM_ROT, 2)
    if type(a) == "number" then
        pitch, yaw = tonumber(a), tonumber(c)
    else
        local v = tg_v3_from_any(a)
        if v then pitch, yaw = v.x, v.z end
    end

    if yaw == nil then
        tg_warn("START_DIRECTION", tostring(label or "start") .. ": gameplay camera rotation unavailable; fallback heading=" .. string.format("%.1f", fallback_heading))
        return tg_normalize_heading(fallback_heading)
    end

    local track_heading = tg_normalize_heading((tonumber(yaw) or 0.0) + 90.0)
    tg_log("[START_DIRECTION][CAMERA] label=" .. tostring(label or "start") ..
        " cameraYaw=" .. string.format("%.1f", tonumber(yaw) or 0.0) ..
        " trackHeading=" .. string.format("%.1f", track_heading) ..
        " cameraPitch=" .. string.format("%.1f", tonumber(pitch) or 0.0))
    return track_heading
end

