tg_prime_diag("COMPAT", "about to define entities/stable-spawn compatibility helpers")
entities = entities or {}
-- v0.8.1 stable spawn helpers: one-shot direct calls only.
-- No background keepalive, no quarantine/hide retry queue.
TG_STABLE_SPAWN_METHOD = true
TG_STABLE_SPAWN_DYNAMIC_OBJECTS = true
TG_STABLE_SPAWN_LOD_DIST = TG_STABLE_SPAWN_LOD_DIST or 0xFFFF
TG_STABLE_SPAWN_NETWORK = (TG_STABLE_SPAWN_NETWORK ~= false)

function tg_direct_entity_exists(entity)
    if not entity or entity == 0 then return false end
    return Natives.InvokeBool(N.DOES_ENTITY_EXIST, entity) == true
end

function tg_direct_entity_void(hash, ...)
    if not hash then return nil end
    return Natives.InvokeVoid(hash, ...)
end

function tg_direct_entity_int(hash, ...)
    if not hash then return 0 end
    return tonumber(Natives.InvokeInt(hash, ...) or 0) or 0
end

function tg_stable_spawn_finalize(entity, x, y, z, label)
    if not entity or entity == 0 then return false end
    label = tostring(label or "spawn")
    if not tg_direct_entity_exists(entity) then
        tg_warn("STABLE_SPAWN", label .. " failed exists check handle=" .. tostring(entity))
        return false
    end

    -- BiggerScript-style correction: CreateObject may apply a small Z/placement offset, so force exact coords.
    tg_direct_entity_void(N.SET_ENTITY_AS_MISSION_ENTITY, entity, true, false)
    tg_direct_entity_void(N.SET_ENTITY_COORDS_NO_OFFSET, entity, x or 0.0, y or 0.0, z or 0.0, false, false, false)
    tg_direct_entity_void(N.SET_ENTITY_VISIBLE, entity, true, false)
    tg_direct_entity_void(N.SET_ENTITY_ALPHA, entity, 255, false)
    tg_direct_entity_void(N.SET_ENTITY_COLLISION, entity, true, true)
    tg_direct_entity_void(N.SET_ENTITY_LOAD_COLLISION_FLAG, entity, true, 0)
    tg_direct_entity_void(N.SET_ENTITY_LOD_DIST, entity, TG_STABLE_SPAWN_LOD_DIST or 0xFFFF)
    tg_direct_entity_void(N.SET_ENTITY_HAS_GRAVITY, entity, false)
    tg_direct_entity_void(N.SET_ENTITY_SHOULD_FREEZE_WAITING_ON_COLLISION, entity, false)
    return true
end

function tg_stable_migrate_bits(entity, can_migrate)
    local ptr = GTA.HandleToPointer(entity)
    local addr = ptr and ptr:GetAddress() or 0
    if not addr or addr == 0 then return end
    local node = Memory.ReadLong(addr + 0xD0)
    if not node or node == 0 then return end
    local bits = Memory.ReadByte(node + 0x4E)
    if can_migrate == false then
        if (bits & 1) == 0 then Memory.WriteByte(node + 0x4E, bits | 1) end
    else
        if (bits & 1) == 1 then Memory.WriteByte(node + 0x4E, bits & ~1) end
    end
end

function tg_stable_set_can_migrate(entity, can_migrate)
    if not entity or entity == 0 then return false end
    tg_stable_migrate_bits(entity, can_migrate)

    local net_id = tg_direct_entity_int(N.OBJ_TO_NET, entity)
    if net_id == 0 then net_id = tg_direct_entity_int(N.NETWORK_GET_NETWORK_ID_FROM_ENTITY, entity) end
    if net_id and net_id ~= 0 then
        tg_direct_entity_void(N.SET_NETWORK_ID_CAN_MIGRATE, net_id, can_migrate ~= false)
        tg_direct_entity_void(N.SET_NETWORK_ID_CAN_BE_REASSIGNED, net_id, can_migrate ~= false)
    end
    return true
end

function tg_stable_make_entity_networked(entity, reason)
    if not entity or entity == 0 then return false end
    reason = tostring(reason or "stable")
    tg_debug("STABLE_SPAWN", "make_networked handle=" .. tg_handle(entity) .. " reason=" .. reason)

    tg_direct_entity_void(N.SET_ENTITY_AS_MISSION_ENTITY, entity, false, true)
    tg_direct_entity_void(N.SET_ENTITY_SHOULD_FREEZE_WAITING_ON_COLLISION, entity, false)

    if TG_STABLE_SPAWN_NETWORK and NETWORK and NETWORK.NETWORK_IS_SESSION_STARTED and NETWORK.NETWORK_IS_SESSION_STARTED() then
        tg_direct_entity_void(N.NETWORK_REQUEST_CONTROL_OF_ENTITY, entity)
        tg_direct_entity_void(N.NETWORK_REGISTER_ENTITY_AS_NETWORKED, entity)

        local net_id = tg_direct_entity_int(N.OBJ_TO_NET, entity)
        if net_id == 0 then net_id = tg_direct_entity_int(N.NETWORK_GET_NETWORK_ID_FROM_ENTITY, entity) end
        if net_id and net_id ~= 0 then
            tg_direct_entity_void(N.SET_NETWORK_ID_EXISTS_ON_ALL_MACHINES, net_id, true)
            tg_direct_entity_void(N.SET_NETWORK_ID_CAN_MIGRATE, net_id, false)
            tg_direct_entity_void(N.SET_NETWORK_ID_CAN_BE_REASSIGNED, net_id, false)
            local pid = tg_direct_entity_int(N.PLAYER_ID)
            if pid and pid >= 0 then tg_direct_entity_void(N.SET_NETWORK_ID_ALWAYS_EXISTS_FOR_PLAYER, net_id, pid, true) end
        end

        tg_stable_set_can_migrate(entity, false)
    end

    tg_stable_spawn_finalize(entity, tg_get_meta(entity) and tg_get_meta(entity).x, tg_get_meta(entity) and tg_get_meta(entity).y, tg_get_meta(entity) and tg_get_meta(entity).z, "network_" .. reason)
    return true
end

entities.create_object = entities.create_object or function(hash, pos)
    -- Clear Track stops a build: a cancelled build job never spawns another piece
    if tg_rs_job_cancelled() then return nil end
    local parsed_pos = tg_v3_from_any(pos)
    local x, y, z = 0.0, 0.0, 0.0
    if parsed_pos then
        x, y, z = parsed_pos.x or 0.0, parsed_pos.y or 0.0, parsed_pos.z or 0.0
    elseif pos ~= nil then
        tg_warn("SPAWN", "could not parse spawn position type=" .. tostring(type(pos)) .. "; using 0,0,0")
    end

    __tg_spawn_attempts = __tg_spawn_attempts + 1
    if TG_DEBUG_SPAWN then
        tg_debug("STABLE_SPAWN", "attempt #" .. tostring(__tg_spawn_attempts) .. " hash=" .. tostring(hash) .. " pos=" .. string.format("%.3f, %.3f, %.3f", x, y, z))
    end

    local obj = 0
    -- v0.8.1: match the proven script-22/BiggerScript pattern: dynamic=true, networked=true.
    local result = GTA.CreateObject(hash, x, y, z, true, true)

    if result and result ~= 0 and tg_direct_entity_exists(result) then
        obj = result
        if TG_DEBUG_SPAWN then tg_debug("STABLE_SPAWN", "GTA.CreateObject success handle=" .. tg_handle(obj)) end
    else
        if TG_DEBUG_SPAWN then tg_warn("STABLE_SPAWN", "GTA.CreateObject failed/zero hash=" .. tostring(hash) .. " err=" .. tostring(result)) end
        result = GTA.CreateWorldObject(hash, x, y, z, true, true)
        if result and result ~= 0 and tg_direct_entity_exists(result) then
            obj = result
            if TG_DEBUG_SPAWN then tg_debug("STABLE_SPAWN", "GTA.CreateWorldObject success handle=" .. tg_handle(obj)) end
        else
            if TG_DEBUG_SPAWN then tg_warn("STABLE_SPAWN", "GTA.CreateWorldObject failed/zero hash=" .. tostring(hash) .. " err=" .. tostring(result)) end
        end
    end

    if not obj or obj == 0 or not tg_stable_spawn_finalize(obj, x, y, z, "entities.create_object") then
        __tg_spawn_fail = __tg_spawn_fail + 1
        tg_error("[STABLE_SPAWN] Object spawn failed hash=" .. tostring(hash) .. " pos=" .. string.format("%.3f, %.3f, %.3f", x, y, z))
        tg_report_state("stable_spawn_failed")
        return nil
    end

    __tg_spawn_success = __tg_spawn_success + 1
    return obj
end
entities.delete_by_handle = entities.delete_by_handle or function(entity)
    if entity and entity ~= 0 then
        ENTITY.SET_ENTITY_AS_MISSION_ENTITY(entity, true, true)
        local ptr = Memory.AllocInt()
        Memory.WriteInt(ptr, entity)
        invoke_void(N.DELETE_ENTITY, ptr)
        Memory.Free(ptr)
    end
end
entities.delete = entities.delete or entities.delete_by_handle
entities.set_can_migrate = entities.set_can_migrate or function(entity, toggle) return tg_stable_set_can_migrate(entity, toggle) end
