-- Stand menu shim -> Cherax FeatureMgr + ClickGUI tab.
-- v0.2.3: Do NOT use ListGUI.GetRootTab/AddSubTab/AddFeature during init.
-- The working UniversalDrifting_Cherax pattern creates FeatureMgr features first,
-- then renders them inside a ClickGUI.AddTab callback.
local __tg_feature_by_command = {}
local __tg_ui_groups = {}
local __tg_group_order = {}

local function feature_hash(name)
    local base = "LUA_TrackMatic_" .. tostring(name or "") .. "_" .. tostring(math.random(100000, 999999))
    return Utils.Joaat(base)
end

local function tg_group_new(name, desc, parent)
    local g = { __is_tg_group = true, name = tostring(name or "TrackMatic"), desc = tostring(desc or ""), parent = parent, items = {} }
    table.insert(__tg_group_order, g)
    __tg_ui_groups[g.name .. "_" .. tostring(#__tg_group_order)] = g
    return g
end

local function add_feature_to_parent(parent, feature)
    if not feature then return end
    local hash = nil
    hash = feature:GetHash()
    if not hash then return end

    local g = parent
    if not (g and g.__is_tg_group) then
        g = __tg_root_group
    end
    if g and g.items then
        table.insert(g.items, hash)
        if TG_DEBUG_MENU then tg_debug("MENU", "queued feature for ClickGUI group=" .. tostring(g.name) .. " hash=" .. tostring(hash)) end
    end
end


-- v0.6.0 Clean UI filter hotfix.
-- Globals only: avoids Lua/Cherax 200-local main-chunk limit.
TG_CLEAN_UI = true
function tg_clean_menu_allow(name)
    if not TG_CLEAN_UI then return true end
    name = tostring(name or "")
    if name:find("Print Track Size", 1, true) then return true end
    if name:find("Tube Shapes:", 1, true) or name:find("Tube Build:", 1, true) or name:find("Tube Circuit:", 1, true) or name:find("Tube Course:", 1, true) or name:find("Tube Race:", 1, true) or name:find("Tube Net:", 1, true) or name:find("Parkour:", 1, true) or name:find("Hybrid:", 1, true) or name:find("Arcade:", 1, true) or name:find("TrackMatic:", 1, true) or name:find("Lab:", 1, true) or name:find("Creator:", 1, true) then return true end
    return name == "Print Version Banner"
        or name == "Connector: Spawn Start Piece"
        or name == "Tetris: Preview Add 1 Piece"
        or name == "Tetris: Preview 5-Piece Chain"
        or name == "Tetris: Preview 10-Piece Chain"
        or name == "Tetris: Preview 50-Piece Loop Attempt"
        or name == "Tetris: Preview Random Loop Attempt"
        or name == "Tetris: Smart Random Loop"
        or name == "Tetris: Smart Random Loop 15 Max"
        or name == "Tetris: Planned Smart Loop 15 Max"
        or name == "Stunt Tubes: Test Straight Row"
        or name == "Stunt Tubes: Next Tube Model"
        or name == "Stunt Tubes: Model Sweep Row"
        or name == "Stunt Tubes: Unique 3D Grid Track"
        or name == "Stunt Tubes: 3D Corkscrew Climb"
        or name == "Stunt Tubes: Ordered 3D Snake"
        or name == "Stunt Tubes: Ordered Sky Bridge"
        or name == "Stunt Tubes: Connected Sky Bridge"
        or name == "Stunt Tubes: Connected 3D Snake"
        or name == "TrackMatic Compact Logs" or
        name == "Print Track Size Memory" or
        name == "Clear Track / Test Objects"
        or name == "Saved Tracks"
        or name == "Save Current Track"
        or name == "Saved Track File"
        or name == "Refresh Saved Track List"
        or name == "Next Saved Track"
        or name == "Previous Saved Track"
        or name == "Load Selected Save"
        or name == "Print Selected Save Stats"
        or name == "Delete Selected Save"
