menu = menu or {}
menu.my_root = menu.my_root or function()
    if TG_DEBUG_MENU then tg_debug("MENU", "creating ClickGUI root group (no ListGUI)") end
    __tg_root_group = __tg_root_group or tg_group_new("TrackMatic", "Procedural road tracks, stunt tube races, parkour, hybrid courses and minigames")
    return __tg_root_group
end

menu.divider = menu.divider or function(parent, text)
    if not tg_clean_divider_allow(text) then return nil end
    local g = parent
    if not (g and g.__is_tg_group) then g = __tg_root_group end
    if g and g.items then table.insert(g.items, { __divider = true, text = tostring(text or "") }) end
end

menu.list = menu.list or function(parent, name, _commands, desc)
    if not tg_clean_menu_allow(name) then return nil end
    if TG_DEBUG_MENU then tg_debug("MENU", "list/group: " .. tostring(name)) end
    return tg_group_new(name, desc, parent)
end

-- menu callbacks and unload hooks run through here
function tg_callback(label, cb, ...)
    if not cb then return end
    cb(...)
end

local function tg_add_feature(hash, name, type_id, desc, callback)
    local f = FeatureMgr.AddFeature(hash, name, type_id, desc or "", callback)
    if f then return f end
    tg_error("FeatureMgr.AddFeature failed for " .. tostring(name))
    return nil
end

menu.action = menu.action or function(parent, name, commands, desc, cb)
    if not tg_clean_menu_allow(name) then return nil end
    if TG_DEBUG_MENU then tg_debug("MENU", "action: " .. tostring(name)) end
    local f = tg_add_feature(feature_hash(name), name, eFeatureType.Button, desc or "", function(feature)
        tg_callback("ACTION " .. tostring(name), cb, 0, 0)
    end)
    add_feature_to_parent(parent, f)
    if commands then
        for _, cmd in ipairs(commands) do
            if cmd and cmd ~= "" then __tg_feature_by_command[cmd] = f end
        end
    end
    return f
end

menu.toggle = menu.toggle or function(parent, name, commands, desc, cb, default_on)
    if not tg_clean_menu_allow(name) then return nil end
    if TG_DEBUG_MENU then tg_debug("MENU", "toggle: " .. tostring(name) .. " default=" .. tostring(default_on)) end
    local f = tg_add_feature(feature_hash(name), name, eFeatureType.Toggle, desc or "", function(feature)
        local value = false
        if feature and feature.IsToggled then value = feature:IsToggled() == true
        elseif feature and feature.GetBoolValue then value = feature:GetBoolValue() == true end
        tg_callback("TOGGLE " .. tostring(name), cb, value, 0)
    end)
    if f then
        f:SetDefaultValue(default_on == true)
        f:SetBoolValue(default_on == true)
        f:Reset()
    end
    add_feature_to_parent(parent, f)
    if commands then
        for _, cmd in ipairs(commands) do
            if cmd and cmd ~= "" then __tg_feature_by_command[cmd] = f end
        end
    end
    return f
end

menu.slider = menu.slider or function(parent, name, commands, desc, minv, maxv, defaultv, step, cb)
    if not tg_clean_menu_allow(name) then return nil end
    if TG_DEBUG_MENU then tg_debug("MENU", "slider: " .. tostring(name) .. " range=" .. tostring(minv) .. "-" .. tostring(maxv) .. " default=" .. tostring(defaultv)) end
    local f = tg_add_feature(feature_hash(name), name, eFeatureType.SliderInt, desc or "", function(feature)
        local value = defaultv or minv or 0
        if feature and feature.GetIntValue then value = feature:GetIntValue() end
        tg_callback("SLIDER " .. tostring(name), cb, value, nil, 0)
    end)
    if f then
        f:SetLimitValues(minv, maxv)
        f:SetStepSize(step or 1)
        f:SetFastStepSize((step or 1) * 10)
        f:SetDefaultValue(defaultv or minv or 0)
        f:SetIntValue(defaultv or minv or 0)
        f:Reset()
    end
    add_feature_to_parent(parent, f)
    if commands then
        for _, cmd in ipairs(commands) do
            if cmd and cmd ~= "" then __tg_feature_by_command[cmd] = f end
        end
    end
    return f
end

menu.slider_float = menu.slider_float or function(parent, name, commands, desc, minv, maxv, defaultv, step, cb)
    if not tg_clean_menu_allow(name) then return nil end
    -- Stand stores slider_float values as scaled ints in many scripts; keep int slider for Cherax test build.
    return menu.slider(parent, name, commands, desc, minv, maxv, defaultv, step, cb)
end

menu.list_select = menu.list_select or function(parent, name, commands, desc, options, default_value, cb)
    if not tg_clean_menu_allow(name) then return nil end
    if TG_DEBUG_MENU then tg_debug("MENU", "combo: " .. tostring(name) .. " options=" .. tostring(options and #options or 0)) end
    local names = {}
    local values = {}
    local default_index = 0
    for i, opt in ipairs(options or {}) do
        values[i] = opt[1]
        names[i] = tostring(opt[2] or opt[1])
        if opt[1] == default_value then default_index = i - 1 end
    end
    local f = tg_add_feature(feature_hash(name), name, eFeatureType.Combo, desc or "", function(feature)
        local idx = 1
        if feature and feature.GetListIndex then idx = (feature:GetListIndex() or 0) + 1 end
        local value = values[idx]
        local label = names[idx]
        tg_callback("LIST " .. tostring(name), cb, value, label, nil, 0)
    end)
    if f then
        f:SetList(names)
        f:SetListIndex(default_index)
        f:SetDefaultValue(default_index)
        f:Reset()
    end
    add_feature_to_parent(parent, f)
    if commands then
        for _, cmd in ipairs(commands) do
            if cmd and cmd ~= "" then __tg_feature_by_command[cmd] = f end
        end
    end
    return f
end

menu.readonly = menu.readonly or function(parent, name, value)
    if not tg_clean_menu_allow(name) then return nil end
    if TG_DEBUG_MENU then tg_debug("MENU", "readonly: " .. tostring(name) .. " value=" .. tostring(value)) end
    local f = tg_add_feature(feature_hash(name), name, eFeatureType.Button, tostring(value or ""), function() end)
    add_feature_to_parent(parent, f)
    return f
end

menu.set_visible = menu.set_visible or function(obj, visible)
    if obj then obj:SetVisible(visible == true) end
end
menu.set_value = menu.set_value or function(obj, value)
    if not obj then return end
    if type(value) == "number" then obj:SetIntValue(value)
    elseif type(value) == "boolean" then obj:SetBoolValue(value)
    else obj:SetStringValue(tostring(value)) end
end
menu.set_max_value = menu.set_max_value or function(obj, value)
    if obj then obj:SetMaxValue(value) end
end
menu.trigger_commands = menu.trigger_commands or function(command)
    command = tostring(command or "")
    local cmd = command:match("^(%S+)")
    local f = __tg_feature_by_command[cmd]
    if f then
        f:OnClick()
    else
        tg_log("Unsupported Stand command skipped: " .. command)
    end
end

local function tg_render_feature(hash)
    if hash then
        ClickGUI.RenderFeature(hash)
    end
end


-- v0.9.8 DriftGod-inspired UI shell. Keep FeatureMgr controls underneath so sliders/toggles
-- retain Cherax-native behavior, but organize them behind a clean tab bar and accent styling.
TG_UI_ACTIVE_TAB = "Home"

-- v1.2.0 perf: colour sets are built once (not 3 new tables per button per frame) and the
-- "is this a BUILD / START GAME button" check is remembered per label
TG_UI_BTN_COLS = {
    launch = { {0.10,0.39,0.87}, {0.17,0.52,1.00}, {0.07,0.29,0.72} },
    active = { {0.58,0.13,0.77}, {0.68,0.23,0.87}, {0.44,0.11,0.60} },
    idle   = { {0.24,0.17,0.30}, {0.38,0.24,0.47}, {0.44,0.11,0.60} },
}
TG_UI_LAUNCH_LABEL = {}
function tg_ui_push_button_colors(active, button_label)
    local is_launch = false
    if button_label then
        is_launch = TG_UI_LAUNCH_LABEL[button_label]
        if is_launch == nil then
            local primary = tostring(button_label):upper()
            is_launch = (primary:match("^BUILD") ~= nil) or (primary:match("^START GAME") ~= nil)
            TG_UI_LAUNCH_LABEL[button_label] = is_launch
        end
    end
    local set = is_launch and TG_UI_BTN_COLS.launch or (active and TG_UI_BTN_COLS.active or TG_UI_BTN_COLS.idle)
    local bg, hover, held = set[1], set[2], set[3]
    ImGui.PushStyleColor(ImGuiCol.Button,bg[1],bg[2],bg[3],1.0)
    ImGui.PushStyleColor(ImGuiCol.ButtonHovered,hover[1],hover[2],hover[3],1.0)
    ImGui.PushStyleColor(ImGuiCol.ButtonActive,held[1],held[2],held[3],1.0)
    return 3
end

function tg_ui_pop_colors(n)
    if n and n > 0 then ImGui.PopStyleColor(n) end
end

-- v1.0.0: ClickGUI render callbacks are NOT native script threads.
-- Any action that can call Script.Yield/util.yield must be dispatched through
-- Script.QueueJob instead of running inline from ImGui.Button. Running a builder
-- inline can poison Cherax's tab render coroutine and produce:
--   cannot resume non-suspended coroutine
TG_UI_ACTION_SEQUENCE = 0
TG_UI_LAST_ACTION = "none"

function tg_ui_queue_action(label, callback)
    if type(callback) ~= "function" then return false end
    TG_UI_ACTION_SEQUENCE = (tonumber(TG_UI_ACTION_SEQUENCE) or 0) + 1
    local seq = TG_UI_ACTION_SEQUENCE
    TG_UI_LAST_ACTION = tostring(label or "action")

    local job = Script.QueueJob(function()
        tg_log("[CLICKGUI][ACTION_BEGIN] #" .. tostring(seq) .. " " .. tostring(label))
        callback()
        tg_log("[CLICKGUI][ACTION_DONE] #" .. tostring(seq) .. " " .. tostring(label))
    end)
    tg_log("[CLICKGUI][ACTION_QUEUED] #" .. tostring(seq) .. " " .. tostring(label) .. " job=" .. tostring(job))
    return true
end

function tg_ui_button(label, width, active, callback)
    local n = tg_ui_push_button_colors(active == true, label)
    local clicked = ImGui.Button(label, tg_pm_button_width(label, width or 132) or (width or 132), 36)
    tg_ui_pop_colors(n)
    if clicked and callback then
        tg_ui_queue_action(label, callback)
    end
    return clicked == true
end

-- Tab switching itself is deliberately kept synchronous because it never yields.
-- This avoids unnecessarily queueing a native job just to change a UI string.
function tg_ui_tab(label)
    local n = tg_ui_push_button_colors(TG_UI_ACTIVE_TAB == label)
    local clicked = ImGui.Button(label, 105, 36)
    tg_ui_pop_colors(n)
    if clicked then TG_UI_ACTIVE_TAB = label end
    return clicked == true
end

function tg_ui_same_line()
    ImGui.SameLine()
end

function tg_ui_title(title, subtitle)
    ImGui.TextColored(0.74,0.45,1.0,1.0,tostring(title))
    if subtitle then ImGui.Text(tostring(subtitle)) end
    ImGui.Separator()
end

TG_UI_MINIMAL_GROUPS = { ["Stunt Tubes"] = true, ["Parkour"] = true, ["Hybrid"] = true, ["Creator"] = true, ["Lab"] = true }
function tg_render_group(group)
    if not group then return end
    local title = tostring(group.name or "TrackMatic")
    if ClickGUI.BeginCustomChildWindow(title) then
        tg_render_group_body(group, title); ClickGUI.EndCustomChildWindow()
    end
end
function tg_render_group_body(group, title)
            local minimal = TG_UI_MINIMAL_GROUPS and TG_UI_MINIMAL_GROUPS[title]
            if not minimal then
                ImGui.TextColored(0.74,0.45,1.0,1.0,title)
                if group.desc and group.desc ~= "" then ImGui.Text(group.desc) end
                ImGui.Separator()
            end
            TG_UI_MORE = TG_UI_MORE or {}
            local more_drawn = false
            for _, item in ipairs(group.items or {}) do
                if minimal and not (type(item) == "table" and item.__custom_render) and not more_drawn then
                    more_drawn = true
                    ImGui.Separator()
                    if ImGui.Button((TG_UI_MORE[title] and "Less##more_" or "More##more_") .. title, 80, 22) then TG_UI_MORE[title] = not TG_UI_MORE[title] end
                end
                if minimal and more_drawn and not TG_UI_MORE[title] then break end
                if type(item) == "table" and item.__divider then
                    ImGui.Separator()
                    if item.text ~= "" then ImGui.Text(item.text) end
                elseif type(item) == "table" and item.__track_save_dropdown then
                    tg_render_track_save_dropdown()
                elseif type(item) == "table" and item.__custom_render then
                    item.__custom_render()
                else
                    local style_n = tg_ui_push_button_colors(false)
                    tg_render_feature(item)
                    tg_ui_pop_colors(style_n)
                end
            end
end


-- v2.3.7: three difficulty lanes, equivalent to the ranked generation pickers.
-- Suggested difficulty represents how demanding a game mode is for players.
TG_GAMES_DIFFICULTIES = {
