        {"Drifter","tg_minigame_drifter","Free-flow drift lines and approachable corners"},
        {"Spiral","tg_minigame_spiral","Follow an ascending, continuous spiral"}}},
    { name="MEDIUM", r=1.00,g=0.73,b=0.22, games={
        {"Switchback","tg_minigame_switchback","Navigate frequent direction changes"},
        {"Sky Sprint","tg_minigame_skysprint","Fast aerial route with little room for error"}}},
    { name="HARD", r=1.00,g=0.37,b=0.37, games={
        {"Sky Climb","tg_minigame_skyclimb","Climb continuously without a level track"},
        {"Eliminator","tg_minigame_eliminator","Keep driving as the course disappears behind you"}}}
}
function tg_games_render_lane(lane)
    ImGui.TextColored(lane.r,lane.g,lane.b,1.0,lane.name)
    ImGui.Separator()
