-- v2.3.7: prime-safe saved manager, 3-column workspace and credits.
-- Folder scans/parsing occur only through Script.QueueJob, never in ImGui draw.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_SAVED_UI_FILTER = TG_SAVED_UI_FILTER or "All"
TG_SAVED_UI_DELETE_PATH = nil
TG_SAVED_UI_PREVIEW_PATH = nil
TG_SAVED_UI_LAST_TAB = TG_SAVED_UI_LAST_TAB or ""

function tg_saved_ui_preview_current_selection(force)
    local selected = TG_TRACK_SAVE_FILES and TG_TRACK_SAVE_FILES[TG_TRACK_SAVE_SELECTED_INDEX or 1]
    if not force and TG_SAVED_UI_PREVIEW_PATH == selected then return end
    TG_SAVED_UI_PREVIEW_PATH = selected
    if not selected then
        TG_GRAPH_DATA,TG_GRAPH_SOURCE,TG_GRAPH_PATH = nil,"",nil
        return
    end
    if tg_ui_queue_action then
        tg_ui_queue_action("TrackMatic preview selected save",function()
            -- The user may have clicked another file while this job was queued.
            if TG_SAVED_UI_PREVIEW_PATH ~= selected then return end
            tg_graph_load_selected()
        end)
    end
end

function tg_saved_ui_refresh_enter()
    TG_SAVED_UI_PREVIEW_PATH = nil
    TG_SAVED_UI_DELETE_PATH = nil
    if tg_ui_queue_action then
        tg_ui_queue_action("TrackMatic saved auto refresh",function()
            tg_track_save_refresh_list(true)
            local path = TG_TRACK_SAVE_FILES and TG_TRACK_SAVE_FILES[TG_TRACK_SAVE_SELECTED_INDEX or 1]
            TG_SAVED_UI_PREVIEW_PATH = path
            if path and tg_graph_load_selected then
                tg_graph_load_selected()
            else
                TG_GRAPH_DATA,TG_GRAPH_SOURCE,TG_GRAPH_PATH = nil,"",nil
            end
        end)
    end
end

function tg_saved_ui_combo()
    TG_TRACK_SAVE_FILES = TG_TRACK_SAVE_FILES or {}
    TG_TRACK_SAVE_NAMES = TG_TRACK_SAVE_NAMES or {}
    local files,names = TG_TRACK_SAVE_FILES,TG_TRACK_SAVE_NAMES
    local counts={All=#files}
    for i=1,#files do
        local cat = tg_rs_save_cat_of(names[i]) or "Other"
        counts[cat]=(counts[cat] or 0)+1
    end
    ImGui.Text("Category")
    local cats={"All","Road","Tubes","Track","Parkour","Hybrid","Lab","Other"}
    if ImGui.BeginCombo("##TM_SavedCategory",TG_SAVED_UI_FILTER) then
        for _,cat in ipairs(cats) do
            if cat=="All" or (counts[cat] or 0)>0 then
                if ImGui.Selectable(cat.." ("..tostring(counts[cat] or 0)..")",cat==TG_SAVED_UI_FILTER) then
                    TG_SAVED_UI_FILTER=cat
                    if cat~="All" and tg_rs_save_cat_of then
                        for j,nm in ipairs(names) do
                            if files[j] and tg_rs_save_cat_of(nm)==cat then
                                TG_TRACK_SAVE_SELECTED_INDEX=j
                                TG_SAVED_UI_DELETE_PATH=nil
                                tg_saved_ui_preview_current_selection(true)
                                break
                            end
                        end
                    end
                end
            end
        end
      ImGui.EndCombo()
    end
    local filtered={}
    for i,name in ipairs(names) do
        if files[i] and (TG_SAVED_UI_FILTER=="All" or
            (tg_rs_save_cat_of(name)==TG_SAVED_UI_FILTER)) then
            filtered[#filtered+1]=i
        end
    end
    ImGui.Text("Saved courses ("..tostring(#filtered)..")")
    local idx = math.max(1,math.min(tonumber(TG_TRACK_SAVE_SELECTED_INDEX or 1) or 1,#files>0 and #files or 1))
    local display = #files>0 and tostring(names[idx] or "-") or "No saved courses"
    if ImGui.BeginCombo("##TM_SavedSelection",display) then
        for _,i in ipairs(filtered) do
            if ImGui.Selectable(tostring(names[i]),i==idx) then
                TG_TRACK_SAVE_SELECTED_INDEX=i
                TG_SAVED_UI_DELETE_PATH=nil
                tg_saved_ui_preview_current_selection(true)
            end
        end
      ImGui.EndCombo()
    end
end

function tg_saved_ui_actions()
    local path=TG_TRACK_SAVE_FILES and TG_TRACK_SAVE_FILES[TG_TRACK_SAVE_SELECTED_INDEX or 1]
    tg_ui_button("Save Current Course",178,false,function()
        if tg_track_save_current() then
            tg_track_save_refresh_list(true)
            local selected=TG_TRACK_SAVE_FILES and TG_TRACK_SAVE_FILES[TG_TRACK_SAVE_SELECTED_INDEX or 1]
            TG_SAVED_UI_PREVIEW_PATH=selected
            if selected then tg_graph_load_selected() end
        end
    end)
    tg_ui_button("Load Selected Course",178,false,function()
        if path and tg_track_save_load_selected then tg_track_save_load_selected() end
    end)
    tg_ui_button("Preview Current Course",178,false,function()
        tg_graph_load_current()
    end)
    ImGui.Separator()
    -- Two-click delete, scoped to exact selected filename.
    if TG_SAVED_UI_DELETE_PATH and TG_SAVED_UI_DELETE_PATH ~= path then TG_SAVED_UI_DELETE_PATH=nil end
    local is_confirm=path and TG_SAVED_UI_DELETE_PATH==path
    local label=is_confirm and "CONFIRM DELETE##TMDelete" or "Delete Selected##TMDelete"
    local pressed=ImGui.Button(label,178,30)
    if pressed and path then
        if is_confirm then
            TG_SAVED_UI_DELETE_PATH=nil
            tg_ui_queue_action("TrackMatic delete selected save",function()
                if TG_TRACK_SAVE_FILES and TG_TRACK_SAVE_FILES[TG_TRACK_SAVE_SELECTED_INDEX or 1]==path then
                    tg_track_save_delete_selected()
                    TG_SAVED_UI_PREVIEW_PATH=nil
                    local nextpath=TG_TRACK_SAVE_FILES and TG_TRACK_SAVE_FILES[TG_TRACK_SAVE_SELECTED_INDEX or 1]
                    if nextpath then tg_graph_load_selected();TG_SAVED_UI_PREVIEW_PATH=nextpath
                    else TG_GRAPH_DATA,TG_GRAPH_SOURCE,TG_GRAPH_PATH=nil,"",nil end
                end
            end)
        else TG_SAVED_UI_DELETE_PATH=path end
    end
    if is_confirm then ImGui.TextColored(1.0,0.39,0.35,1.0,"Click again to permanently delete") end
    if ImGui.CollapsingHeader("Advanced hover example") then
        ImGui.TextWrapped("Assign selected saved course to the last hovered generator preset.")
        tg_ui_button("Use as Hover Example",178,false,tg_hp_capture_selected_saved)
    end
end

