-- v2.3.9: official profile PNG with binary-safe, self-repairing cache.
-- The previous generic file-content writer could leave an unreadable PNG.
-- A cache hit now requires a complete PNG, not simply an existing filename.
TG_TM_CREDITS_LOGO_URL = "https://raw.githubusercontent.com/xReVoLTiThemeDev/GTAV-Cherax/main/Public_Urinal.png"
TG_TM_CREDITS_IMAGE_STATE = "idle"
TG_TM_CREDITS_IMAGE_TEX = nil
TG_TM_CREDITS_IMAGE_SRV = nil
TG_TM_CREDITS_TEXTURE_ATTEMPTED = false
TG_TM_CREDITS_IMAGE_ERROR = nil
TG_TM_CREDITS_FORCE_REPAIR = false

function tg_tm_credits_portrait_path()
    local root=FileMgr.GetMenuRootPath()
    if not root or tostring(root)=="" then return nil end
    return tostring(root).."\\Lua\\TrackMatic\\assets\\Public_Urinal_GitHub.png"
end

-- Verify that we actually have a complete PNG. 1024x1024 is the official
-- source image's resolution. A file exists check alone is insufficient.
function tg_tm_credits_png_valid(data)
    if type(data)~="string" or #data<250000 or #data>16000000 then return false end
    if data:sub(1,8)~="\137PNG\r\n\26\n" then return false end
    local function be32(pos)
        local a,b,c,d=data:byte(pos,pos+3)
        if not d then return nil end
        return ((a*256+b)*256+c)*256+d
    end
    if be32(9)~=13 or data:sub(13,16)~="IHDR" then return false end
    if be32(17)~=1024 or be32(21)~=1024 then return false end
    local pos=9
    local seen_idat=false
    while pos+11<=#data do
        local n=be32(pos)
        if not n or n>16000000 or pos+n+11>#data then return false end
        local tag=data:sub(pos+4,pos+7)
        if tag=="IDAT" then seen_idat=true end
        if tag=="IEND" then
            return seen_idat and n==0 and pos+11==#data
        end
        pos=pos+12+n
    end
    return false
end

function tg_tm_credits_read_binary(path)
    if not path then return nil end
    -- Open in binary mode to preserve embedded NUL bytes in the PNG.
    local file=io.open(path,"rb")
    if not file then return nil end
    local bytes=file:read("*a")
    file:close()
    return bytes
end

function tg_tm_credits_image_exists(path)
    return tg_tm_credits_png_valid(tg_tm_credits_read_binary(path))
end

function tg_tm_credits_write_binary(path,data)
    if not path or not tg_tm_credits_png_valid(data) then return false,"invalid PNG response" end
    -- do not use FileMgr.WriteFileContent for binary PNG content.
    local file,openerr=io.open(path,"wb")
    if not file then return false,tostring(openerr or "io.open failed") end
    local good,writeerr=file:write(data)
    file:close()
    if not good then return false,tostring(writeerr or "write failed") end
    local saved=tg_tm_credits_read_binary(path)
    if not tg_tm_credits_png_valid(saved) or saved~=data then
        return false,"binary round-trip verification failed"
    end
    return true
end

function tg_tm_credits_report_error(message)
    TG_TM_CREDITS_IMAGE_ERROR=tostring(message or "Unknown error")
    TG_TM_CREDITS_IMAGE_STATE="unavailable"
    tg_log("[CREDITS][LOGO] "..TG_TM_CREDITS_IMAGE_ERROR)
end

-- check the cached logo and download it when it is missing or broken.
-- returns nil when the logo is ready, otherwise why it isn't (shown in Credits).
function tg_tm_credits_fetch_logo()
    local path=tg_tm_credits_portrait_path()
    if not path then return "Could not locate TrackMatic assets folder" end
    if not TG_TM_CREDITS_FORCE_REPAIR and tg_tm_credits_image_exists(path) then return nil end
    local root=path:match("^(.*)\\assets\\[^\\]+$")
    if root then
        FileMgr.CreateDir(root)
        FileMgr.CreateDir(root.."\\assets")
    end
    local curl=Curl.Easy()
    curl:Setopt(eCurlOption.CURLOPT_URL,TG_TM_CREDITS_LOGO_URL)
    curl:Setopt(eCurlOption.CURLOPT_USERAGENT,"TrackMatic/2.3.9-Cherax")
    curl:Perform()
    local tries=0
    while not curl:GetFinished() and tries<200 do
        Script.Yield(60)
        tries=tries+1
    end
    if not curl:GetFinished() then return "Logo download timed out" end
    local code,data=curl:GetResponse()
    if not (code==0 or code==true or code==eCurlCode.CURLE_OK) then return "Logo HTTP request failed (Curl: "..tostring(code)..")" end
    if not tg_tm_credits_png_valid(data) then return "Downloaded PNG incomplete or invalid; cache not updated" end
    local wrote,why=tg_tm_credits_write_binary(path,data)
    if not wrote then return "Logo write failed: "..tostring(why) end
    TG_TM_CREDITS_FORCE_REPAIR=false
    return nil
end

function tg_tm_credits_prepare_portrait()
    if TG_TM_CREDITS_IMAGE_STATE~="idle" then return end
    TG_TM_CREDITS_IMAGE_STATE="loading"
    tg_ui_queue_action("TrackMatic logo validation / repair",function()
        local err=tg_tm_credits_fetch_logo()
        if err then tg_tm_credits_report_error(err) else TG_TM_CREDITS_IMAGE_STATE="ready" end
    end)
end

function tg_tm_credits_repair_portrait()
    TG_TM_CREDITS_IMAGE_TEX=nil
    TG_TM_CREDITS_IMAGE_SRV=nil
    TG_TM_CREDITS_TEXTURE_ATTEMPTED=false
    TG_TM_CREDITS_IMAGE_ERROR=nil
    TG_TM_CREDITS_FORCE_REPAIR=true
    TG_TM_CREDITS_IMAGE_STATE="idle"
    tg_tm_credits_prepare_portrait()
end

function tg_tm_credits_portrait()
    if TG_TM_CREDITS_IMAGE_STATE=="idle" then tg_tm_credits_prepare_portrait() end
    if TG_TM_CREDITS_IMAGE_STATE=="ready" and not TG_TM_CREDITS_IMAGE_SRV
       and not TG_TM_CREDITS_TEXTURE_ATTEMPTED then
        TG_TM_CREDITS_TEXTURE_ATTEMPTED=true
        local path=tg_tm_credits_portrait_path()
        -- Validate again before entering the native texture loader.
        if tg_tm_credits_image_exists(path) then
            local id=Texture.LoadTexture(path)
            if type(id)=="number" and id>0 and Texture.IsTextureValid(id)~=false then
                TG_TM_CREDITS_IMAGE_TEX=id
                local tex=Texture.GetTexture(id)
                if tex then TG_TM_CREDITS_IMAGE_SRV=tex:GetCurrent() end
            end
            if not TG_TM_CREDITS_IMAGE_SRV then
                tg_tm_credits_report_error("Cherax could not decode the verified PNG (try Repair Logo)")
            end
        else
            tg_tm_credits_report_error("Logo on disk is incomplete; use Repair Logo")
        end
    end
    if TG_TM_CREDITS_IMAGE_SRV then
        local posx=tonumber(ImGui.GetCursorPosX())
        local posy=tonumber(ImGui.GetCursorPosY())
        if posx and posy then
            local w=460
            w=ImGui.GetContentRegionAvail() or w
            local size=138
            local targetx=posx+math.max(250,w-size-38)
            ImGui.SetCursorPosX(targetx)
            ImGui.SetCursorPosY(posy+8)
            local x,y=0,0
            local px,py=ImGui.GetCursorScreenPos()
            if px then x,y=px,py or 0 end
            ImGui.Dummy(size,size)
            if x>0 and y>0 then ImGui.AddImage(TG_TM_CREDITS_IMAGE_SRV, x, y, x+size, y+size) end
            ImGui.SetCursorPosX(posx)
            ImGui.SetCursorPosY(posy)
        end
    end
    if TG_TM_CREDITS_IMAGE_STATE=="loading" then
        ImGui.TextDisabled("Loading official logo...")
    elseif TG_TM_CREDITS_IMAGE_STATE=="unavailable" then
        ImGui.TextColored(1.0,0.52,0.20,1.0,"Credits logo: "..tostring(TG_TM_CREDITS_IMAGE_ERROR or "unavailable"))
    end
    if (TG_TM_CREDITS_IMAGE_STATE=="unavailable") then
        if ImGui.Button("Repair Logo##TM_CreditsLogoRepair",160,28) then
            tg_tm_credits_repair_portrait()
        end
        ImGui.TextDisabled("Or download the official PNG manually to Lua\\TrackMatic\\assets\\")
    end
end
