TG_UI_TAB_TONES = { { 1.0, 0.85, 0.10, 1.0 }, { 1.0, 0.55, 0.10, 1.0 }, { 1.0, 0.28, 0.22, 1.0 }, { 0.78, 0.45, 1.0, 1.0 } }
function tg_ui_render_tab_body(name)
    -- not the host (online): home shows only the host message
    if not tg_is_session_host() then tg_ui_render_host_lock(); return end
    -- Reset paged presets only when entering the tab, never on every render frame.
    if TG_TM_LAST_SUBTAB ~= name then
        -- Save edits immediately when leaving the Saved graph workspace.
        if TG_TM_LAST_SUBTAB=="Saved" and tg_tm_prefs_flush then tg_tm_prefs_flush(true) end
        TG_TM_LAST_SUBTAB=name
        if name=="Tubes" or name=="Track" or name=="Parkour" then TG_RS_PAGES={} end
    end
    -- Called by both tab-bar and button fallback; scan only on entering Saved.
    if TG_SAVED_UI_LAST_TAB ~= name then
        TG_SAVED_UI_LAST_TAB=name
        if name=="Saved" then tg_saved_ui_refresh_enter()
        else TG_SAVED_UI_DELETE_PATH=nil end
    end
    if name == "Home" then
        tg_ui_render_home()
    elseif name == "Games" then
        tg_ui_render_games()
    elseif name == "Tubes" then
        tg_ui_render_named_groups({["Stunt Tubes"]=true})
    elseif name == "Parkour" then
        tg_ui_render_named_groups({["Parkour"]=true})
    elseif name == "Hybrid" then
        tg_ui_render_named_groups({["Hybrid"]=true})
    elseif name == "Track" or name == "Creator" then
        tg_ui_render_named_groups({["Creator"]=true})
    elseif name == "Lab" then
        tg_ui_render_named_groups({["Lab"]=true})
    elseif name == "Saved" then
        tg_saved_ui_workspace()
    elseif name == "Credits" then
        tg_ui_render_credits()
    else
        tg_ui_render_named_groups({["TrackMatic"]=true,["Tools / Debug"]=true,["Debug / Tests"]=true})
    end
end
function tg_render_tab_items()
    for i, name in ipairs(tg_ui_visible_tabs()) do
        local tone = TG_UI_TAB_TONES[((i - 1) % #TG_UI_TAB_TONES) + 1]
        ImGui.PushStyleColor(ImGuiCol.Text, tone[1], tone[2], tone[3], tone[4])
        local sel = ImGui.BeginTabItem(name)
        ImGui.PopStyleColor(1)
        if sel == true then
            TG_UI_ACTIVE_TAB = name
            tg_ui_render_tab_body(name)
            ImGui.EndTabItem()
        end
    end
end
-- ═══════════════════════════════════════════════════════════════════════════════════
-- host lock
-- ═══════════════════════════════════════════════════════════════════════════════════
-- purpose: online, every tab except home is hidden unless you are the host of the session.
-- note: same check as minigames / startup - your player id vs NETWORK_GET_HOST_PLAYER_INDEX.
--       story mode has no session (and no host), so nothing is locked there.
TG_HOST_NATIVE = { HOST_PLAYER_INDEX = 0x8251FB94DC4FDFC8, PLAYER_ID = 0x4F8644AF03D0E0D6 }
TG_HOST_CACHE = { at = nil, host = true }
TG_HOST_ONLY_TABS = { "Home" }
TG_HOST_LOCK_TEXT = "In order to use TrackMatic, you must be Host of the session."

function tg_host_player_id(hash)
    local v = tonumber(Natives.InvokeInt(hash))
    if v == nil or v < 0 or v > 31 then return nil end
    return math.floor(v)
end

-- true when trackmatic is unlocked: you host the session, or you are not in one.
-- checked at most twice a second, not every frame.
function tg_is_session_host()
    local c = TG_HOST_CACHE
    local now = tg_tn_now() or 0
    if c.at and now - c.at < 500 and now >= c.at then return c.host end
    c.at = now
    if not tg_tn_in_session() then
        c.host = true
    else
        local me = tg_host_player_id(TG_HOST_NATIVE.PLAYER_ID)
        local host = tg_host_player_id(TG_HOST_NATIVE.HOST_PLAYER_INDEX)
        c.host = (me ~= nil and host ~= nil and me == host)
    end
    return c.host
end

function tg_ui_visible_tabs()
    if tg_is_session_host() then return TG_UI_TABS end
    return TG_HOST_ONLY_TABS
end

function tg_ui_render_host_lock()
    ImGui.TextColored(1.0, 0.27, 0.27, 1.0, TG_HOST_LOCK_TEXT)
end

-- v2.1.0: real ImGui tabs (TG_UI_BUTTON_TABS = true draws the old button row instead)
function tg_render_tab()
    local now=tg_now_ms()
    local appearing=ImGui.IsWindowAppearing()==true
    if TG_TM_SELECT_HOME_ON_NEXT_RENDER~=true and
        (appearing or (now>0 and (TG_TM_OUTER_LAST_RENDER_MS or 0)>0
                    and now-TG_TM_OUTER_LAST_RENDER_MS>1100)) then
        tg_tm_on_open_home()
    end
    TG_TM_OUTER_LAST_RENDER_MS=now
    if TG_UI_ACTIVE_TAB == "Build" then TG_UI_ACTIVE_TAB = "Home" end
    if TG_UI_ACTIVE_TAB == "Creator" then TG_UI_ACTIVE_TAB = "Track" end
    if TG_UI_BUTTON_TABS ~= true then
        if ImGui.BeginTabBar("TrackMaticTabs") then
            tg_render_tab_items()
            ImGui.EndTabBar()
        end
        TG_TM_SELECT_HOME_ON_NEXT_RENDER=false
        tg_tm_prefs_flush(false)
        return
    end
    local visible = tg_ui_visible_tabs()
    if visible ~= TG_UI_TABS then TG_UI_ACTIVE_TAB = "Home" end
    for i, name in ipairs(visible) do
        if i > 1 then tg_ui_same_line() end
        tg_ui_tab(name)
    end
    ImGui.Separator()
    TG_TM_SELECT_HOME_ON_NEXT_RENDER=false
    tg_ui_render_tab_body(TG_UI_ACTIVE_TAB)
    tg_tm_prefs_flush(false)
end

-- v1.0.0 ClickGUI lifecycle + native-thread action safety.
-- Remove any stale callback on reload, and never execute yielding gameplay/build work
-- directly inside the render callback. ImGui actions are queued to Script.QueueJob.
TG_CLICKGUI_TAB_TITLE = "TrackMatic"
TG_CLICKGUI_TAB_REGISTERED = false

function tg_cleanup_clickgui_tab(reason)
    tg_tm_prefs_flush(true)
    -- Remove any previous-brand tab without keeping that text in this release.
    -- This is UI cleanup only; it never modifies a previous script on disk.
    ClickGUI.RemoveTab(string.char(82,97,99,101,83,99,97,112,101))
    ClickGUI.RemoveTab(TG_CLICKGUI_TAB_TITLE)
    tg_log("[CLICKGUI][CLEANUP] removed stale/current tab reason=" .. tostring(reason or "unknown"))
    TG_CLICKGUI_TAB_REGISTERED = false
end

function tg_register_clickgui_tab(reason)
    -- Always remove by title first. This is intentionally done even when our local flag
    -- says false because the stale callback may belong to the previous Lua reload.
    tg_cleanup_clickgui_tab("pre_register:" .. tostring(reason or "unknown"))
    ClickGUI.AddTab(TG_CLICKGUI_TAB_TITLE, tg_render_tab)
    TG_CLICKGUI_TAB_REGISTERED = true
    tg_log("[CLICKGUI][REGISTER] TrackMatic tab registered cleanly reason=" .. tostring(reason or "unknown"))
    return true, nil
end

-- Register unload cleanup once so the callback cannot survive this script instance.
do
    util.on_stop(function()
        if tg_minigame_stop and TG_MINIGAME_ACTIVE then tg_callback("STOP minigame", tg_minigame_stop, "script_stop", true) end
        tg_cleanup_clickgui_tab("script_stop")
    end)
end

