function getHeightFromJson(x, y)
    local x1 = math.floor(x / 50) * 50
    local y1 = math.floor(y / 50) * 50
    local x2 = x1 + 50
    local y2 = y1 + 50

    local q11 = map_datas[tostring(x1) .. "," .. tostring(y1)] or 0.0
    local q21 = map_datas[tostring(x2) .. "," .. tostring(y1)] or 0.0
    local q12 = map_datas[tostring(x1) .. "," .. tostring(y2)] or 0.0
    local q22 = map_datas[tostring(x2) .. "," .. tostring(y2)] or 0.0

    local height = (q11 * (x2 - x) * (y2 - y) +
                    q21 * (x - x1) * (y2 - y) +
                    q12 * (x2 - x) * (y - y1) +
                    q22 * (x - x1) * (y - y1)) / ((x2 - x1) * (y2 - y1))

    return height
end

