local function apply_tint_to_entity(entity, tint)   
    tg_debug("TINT", "apply tint=" .. tostring(tint) .. " entity=" .. tg_handle(entity))
    if not entity or entity == 0 then tg_warn("TINT", "skip nil/zero entity"); return end
    -- v1.2.0: the OBJECT wrapper is a no-op under TG_NATIVE_LITE, so colours never showed.
    -- Only colour new fragments once the tint slider has been used, so default tracks look the same as before.
    if TG_TRACK_TINT_USER then tg_direct_entity_void(N.SET_OBJECT_TINT_INDEX, entity, tint) end
    table.insert(entity_can_tint, entity)
end

local function apply_tint_to_objects(tint)
    for _, obj in ipairs(entity_can_tint) do
        tg_direct_entity_void(N.SET_OBJECT_TINT_INDEX, obj, tint)
      
    end
end

local function is_colliding_with_any_other_parent(child_obj, parent_obj)
    if not child_obj or not parent_obj then
        return false
    end
    for _, obj in ipairs(objects) do
        if obj ~= child_obj and obj ~= parent_obj and ENTITY.IS_ENTITY_TOUCHING_ENTITY(obj, child_obj) then
            return true
        end
    end
    return false
end


local function is_collision_with_ground(entity)
    util.yield()
    if not entity then
        return false
    end
    local min, max = v3.new(), v3.new()
    local model = ENTITY.GET_ENTITY_MODEL(entity)
    MISC.GET_MODEL_DIMENSIONS(model, min, max)

    local dims = {
        x = max.x - min.x,
        y = max.y - min.y,
        z = max.z - min.z
    }

    local half_dims = {
        x = dims.x / 2,
        y = dims.y / 2,
        z = dims.z / 2
    }

    local corners = {}
    for i = -1, 1, 2 do
        for j = -1, 1, 2 do
            for k = -1, 1, 2 do
                table.insert(corners, v3.new(i * half_dims.x, j * half_dims.y, k * half_dims.z))
            end
        end
    end

    for _, corner in ipairs(corners) do
        local worldCorner = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(entity, corner.x, corner.y, corner.z)
        local ground_z = getHeightFromJson(worldCorner.x, worldCorner.y)

        if worldCorner.z <= ground_z + 10 then
            return true
        end

        local ground_z_ptr = memory.alloc(4) 
        if MISC.GET_GROUND_Z_FOR_3D_COORD(worldCorner.x, worldCorner.y, worldCorner.z, ground_z_ptr, false) then
            local ground_z_coord = memory.read_float(ground_z_ptr)
            
            if worldCorner.z <= ground_z_coord then
                return true
            end
        end
    end

    return false
end


local function networked_entity(obj)
    if not obj or obj == 0 then tg_warn("NETWORK", "skip nil/zero entity"); return end
    tg_stable_make_entity_networked(obj, "trackmatic")
end



local function update_networked_objects()
        for _, obj in ipairs(objects) do
                networked_entity(obj)    
        end
end

local function create_track_object(model, x, y, z, heading)
    x, y, z = tonumber(x) or 0.0, tonumber(y) or 0.0, tonumber(z) or 0.0
    z = z + (tonumber(TG_TRACK_HEIGHT_OFFSET or 0.0) or 0.0)
    heading = tg_normalize_heading(heading)
    tg_debug("TRACK_OBJECT", "create model=" .. tostring(model) .. " pos=" .. string.format("%.3f, %.3f, %.3f", x, y, z) .. " heading=" .. string.format("%.2f", heading))
    util.request_model(util.joaat(model))
    local obj = entities.create_object(util.joaat(model), v3(x, y, z))
    if not obj or obj == 0 then tg_warn("TRACK_OBJECT", "create failed model=" .. tostring(model)); return nil end
    local meta = { model = model, x = x, y = y, z = z, heading = heading }
    if connector_apply_track_size_meta then connector_apply_track_size_meta(meta, model) end
    tg_set_meta(obj, meta)
    networked_entity(obj)
    ENTITY.SET_ENTITY_HEADING(obj, heading)
    tg_debug("ROTATE", "applied heading=" .. string.format("%.2f", heading) .. " entity=" .. tg_handle(obj))
    apply_tint_to_entity(obj, current_tint)
    tg_stable_spawn_finalize(obj, x, y, z, "post_track_create")
    table.insert(objects, obj)
    return obj
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.8.3 stunt tubes test buttons
-- ═══════════════════════════════════════════════════════════════════════════════════
-- keep these global, not local, so cherax/lua does not hit the 200-local main chunk limit.
TG_STUNT_TUBE_MODEL_INDEX = TG_STUNT_TUBE_MODEL_INDEX or 1
TG_STUNT_TUBE_SPACING = TG_STUNT_TUBE_SPACING or 47.0
TG_STUNT_TUBE_COUNT = TG_STUNT_TUBE_COUNT or 5
TG_STUNT_TUBE_SIDE_OFFSET = TG_STUNT_TUBE_SIDE_OFFSET or 0.0
TG_STUNT_TUBE_FORWARD_OFFSET = TG_STUNT_TUBE_FORWARD_OFFSET or 25.0
TG_STUNT_TUBE_HEIGHT_OFFSET = TG_STUNT_TUBE_HEIGHT_OFFSET or 1.2
TG_STUNT_TUBE_MODELS = TG_STUNT_TUBE_MODELS or {
    "stt_prop_stunt_tube_l",
    "stt_prop_stunt_tube_m",
    "stt_prop_stunt_tube_s",
    "stt_prop_stunt_tube_xs",
    "stt_prop_stunt_tube_xxs",
    "stt_prop_stunt_tube_fn_01",
    "stt_prop_stunt_tube_fn_02",
    "stt_prop_stunt_tube_fn_03",
    "stt_prop_stunt_tube_crn",
    "stt_prop_stunt_tube_crn2",
    "stt_prop_stunt_tube_jmp",
    "stt_prop_stunt_tube_qg"
    -- v1.1.7: end caps / entrance funnels (stt_prop_stunt_tube_ent, _end) are never spawned
    -- v1.1.8: speed-boost tubes are never spawned (players fell through their floor)
}

function tg_stunt_tube_model_at(index)
    index = tonumber(index or TG_STUNT_TUBE_MODEL_INDEX or 1) or 1
    if index < 1 then index = 1 end
    if index > #TG_STUNT_TUBE_MODELS then index = ((index - 1) % #TG_STUNT_TUBE_MODELS) + 1 end
    TG_STUNT_TUBE_MODEL_INDEX = index
    return TG_STUNT_TUBE_MODELS[index], index
end

function tg_try_create_stunt_tube_model(model, x, y, z, heading, label)
    label = tostring(label or "tube")
    model = tostring(model or "")
    if model == "" then return nil end
    tg_log("[TUBE][TRY] label=" .. label .. " model=" .. model .. " pos=" .. string.format("%.2f,%.2f,%.2f", x or 0.0, y or 0.0, z or 0.0) .. " heading=" .. string.format("%.1f", heading or 0.0))
    local obj = create_track_object(model, x, y, z, heading)
    if obj and obj ~= 0 then
        local meta = tg_get_meta(obj) or {}
        meta.tube_test = true
        meta.model = model
        meta.x = x
        meta.y = y
        meta.z = z
        meta.heading = heading
        tg_set_meta(obj, meta)
        tg_log("[TUBE][OK] label=" .. label .. " model=" .. model .. " obj=" .. tg_handle(obj))
        return obj
    end
    tg_warn("TUBE", "failed model=" .. model .. " label=" .. label)
    return nil
end

function tg_try_create_any_stunt_tube(x, y, z, heading, label)
    label = tostring(label or "tube_any")
    local start_index = tonumber(TG_STUNT_TUBE_MODEL_INDEX or 1) or 1
    for step = 0, (#TG_STUNT_TUBE_MODELS - 1) do
        local index = ((start_index + step - 1) % #TG_STUNT_TUBE_MODELS) + 1
        local model = TG_STUNT_TUBE_MODELS[index]
        local obj = tg_try_create_stunt_tube_model(model, x, y, z, heading, label .. "_idx" .. tostring(index))
        if obj then
            TG_STUNT_TUBE_MODEL_INDEX = index
            TG_STUNT_TUBE_LAST_MODEL = model
            return obj, model, index
        end
    end
    tg_error("[TUBE] all known stunt tube models failed")
    return nil, nil, nil
end

function tg_spawn_stunt_tube_row(opts)
    opts = opts or {}
    clear_race_track("stunt_tube_row")
    local pos, heading = tg_get_local_position_heading("stunt_tube_row")
    heading = tonumber(opts.heading or heading or 0.0) or 0.0
    local count = tonumber(opts.count or TG_STUNT_TUBE_COUNT or 5) or 5
    local spacing = tonumber(opts.spacing or TG_STUNT_TUBE_SPACING or 47.0) or 47.0
    local model = opts.model
    if not model or model == "" then model = TG_STUNT_TUBE_LAST_MODEL or tg_stunt_tube_model_at(TG_STUNT_TUBE_MODEL_INDEX) end

    local base_x, base_y, base_z = calculate_new_position(pos, heading, TG_STUNT_TUBE_FORWARD_OFFSET or 25.0, TG_STUNT_TUBE_SIDE_OFFSET or 0.0, TG_STUNT_TUBE_HEIGHT_OFFSET or 1.2)
    local placed = 0
    local used_model = nil

    tg_log("[TUBE][ROW_BEGIN] count=" .. tostring(count) .. " spacing=" .. string.format("%.1f", spacing) .. " startModel=" .. tostring(model) .. " heading=" .. string.format("%.1f", heading))
    for i = 1, count do
        util.yield(opts.delay_ms or 80)
        local x, y, z = calculate_new_position({x=base_x, y=base_y, z=base_z}, heading, (i - 1) * spacing, 0.0, 0.0)
        local obj = nil
        if used_model then
            obj = tg_try_create_stunt_tube_model(used_model, x, y, z, heading, "row_" .. tostring(i))
        else
            obj, used_model = tg_try_create_any_stunt_tube(x, y, z, heading, "row_" .. tostring(i))
        end
        if obj then placed = placed + 1 end
    end

    tg_log("[TUBE][ROW_DONE] placed=" .. tostring(placed) .. "/" .. tostring(count) .. " model=" .. tostring(used_model or model or "none"))
    tg_report_state("stunt_tube_row_done")
    return placed > 0
end

function tg_spawn_stunt_tube_model_sweep()
    clear_race_track("stunt_tube_model_sweep")
    local pos, heading = tg_get_local_position_heading("stunt_tube_model_sweep")
    heading = heading or 0.0
    local spacing = TG_STUNT_TUBE_SPACING or 47.0
    local side_spacing = 36.0
    local placed = 0

    tg_log("[TUBE][SWEEP_BEGIN] models=" .. tostring(#TG_STUNT_TUBE_MODELS) .. " heading=" .. string.format("%.1f", heading))
    for i, model in ipairs(TG_STUNT_TUBE_MODELS) do
        util.yield(70)
        local row = math.floor((i - 1) / 7)
        local col = (i - 1) % 7
        local bx, by, bz = calculate_new_position(pos, heading, TG_STUNT_TUBE_FORWARD_OFFSET + (col * spacing), (row * side_spacing), TG_STUNT_TUBE_HEIGHT_OFFSET)
        local obj = tg_try_create_stunt_tube_model(model, bx, by, bz, heading, "sweep_" .. tostring(i))
        if obj then placed = placed + 1 end
    end

    tg_log("[TUBE][SWEEP_DONE] placed=" .. tostring(placed) .. "/" .. tostring(#TG_STUNT_TUBE_MODELS))
    tg_report_state("stunt_tube_sweep_done")
    return placed > 0
end

function tg_stunt_tube_next_model()
    TG_STUNT_TUBE_MODEL_INDEX = (tonumber(TG_STUNT_TUBE_MODEL_INDEX or 1) or 1) + 1
    if TG_STUNT_TUBE_MODEL_INDEX > #TG_STUNT_TUBE_MODELS then TG_STUNT_TUBE_MODEL_INDEX = 1 end
    local model = tg_stunt_tube_model_at(TG_STUNT_TUBE_MODEL_INDEX)
    TG_STUNT_TUBE_LAST_MODEL = model
    tg_log("[TUBE][MODEL] index=" .. tostring(TG_STUNT_TUBE_MODEL_INDEX) .. "/" .. tostring(#TG_STUNT_TUBE_MODELS) .. " model=" .. tostring(model))
    return model
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.8.4 stunt tubes 3d grid builders
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_TUBE3D_SEGMENT_LEN = TG_TUBE3D_SEGMENT_LEN or 46.0
TG_TUBE3D_GRID_SCALE = TG_TUBE3D_GRID_SCALE or 46.0
TG_TUBE3D_HEIGHT_STEP = TG_TUBE3D_HEIGHT_STEP or 23.0
TG_TUBE3D_DEFAULT_ROLL = TG_TUBE3D_DEFAULT_ROLL or 0.0
TG_TUBE3D_BANK_ROLL = TG_TUBE3D_BANK_ROLL or 12.0
TG_TUBE3D_SPAWN_DELAY_MS = TG_TUBE3D_SPAWN_DELAY_MS or 90

function tg_atan2_safe(y, x)
    y = tonumber(y or 0.0) or 0.0
    x = tonumber(x or 0.0) or 0.0

    if math.atan2 then
        return math.atan2(y, x)
    end

    if math.atan then
        local result = math.atan(y, x)
        if result then return result end
    end

    if x > 0.0 then return math.atan(y / x) end
    if x < 0.0 and y >= 0.0 then return math.atan(y / x) + math.pi end
    if x < 0.0 and y < 0.0 then return math.atan(y / x) - math.pi end
    if x == 0.0 and y > 0.0 then return math.pi / 2.0 end
    if x == 0.0 and y < 0.0 then return -math.pi / 2.0 end
    return 0.0
end

function tg_tube3d_apply_rotation(obj, pitch, roll, yaw, label)
    if not obj or obj == 0 then return false end
    pitch = tonumber(pitch or 0.0) or 0.0
    roll = tonumber(roll or 0.0) or 0.0
    yaw = tg_normalize_heading(yaw or 0.0)
    label = tostring(label or "tube3d_rot")
    Natives.InvokeVoid(N.SET_ENTITY_ROTATION, obj, pitch, roll, yaw, 2, true)
    tg_direct_entity_void(N.FREEZE_ENTITY_POSITION, obj, true)
    local meta = tg_get_meta(obj)
    if meta then meta.pitch, meta.roll, meta.heading = pitch, roll, yaw end
    return true
end

function tg_tube3d_create_segment(model, x, y, z, yaw, pitch, roll, label)
    model = tostring(model or TG_STUNT_TUBE_LAST_MODEL or tg_stunt_tube_model_at(TG_STUNT_TUBE_MODEL_INDEX))
    label = tostring(label or "tube3d_segment")
    local obj = tg_try_create_stunt_tube_model(model, x, y, z, yaw, label)
    if not obj then
        obj, model = tg_try_create_any_stunt_tube(x, y, z, yaw, label .. "_fallback")
    end
    if obj then
        tg_tube3d_apply_rotation(obj, pitch or 0.0, roll or 0.0, yaw or 0.0, label)
        local meta = tg_get_meta(obj) or {}
        meta.tube3d = true
        meta.pitch = pitch or 0.0
        meta.roll = roll or 0.0
        meta.heading = yaw or 0.0
        tg_set_meta(obj, meta)
    end
    return obj, model
end

function tg_tube3d_world_point(origin, base_heading, point)
    point = point or {}
    local f = tonumber(point[1] or point.f or 0.0) or 0.0
    local r = tonumber(point[2] or point.r or 0.0) or 0.0
    local u = tonumber(point[3] or point.u or 0.0) or 0.0
    local x, y, z = calculate_new_position(origin, base_heading or 0.0, f, r, u)
    return { x = x, y = y, z = z, f = f, r = r, u = u }
end

function tg_tube3d_spawn_path(points, opts)
    opts = opts or {}
    points = points or {}
    if #points < 2 then tg_warn("TUBE3D", "not enough points"); return false end

    clear_race_track(opts.clear_label or "tube3d_path")
    local origin, base_heading = tg_get_local_position_heading(opts.label or "tube3d_path")
    base_heading = tonumber(opts.base_heading or base_heading or 0.0) or 0.0
    local model = opts.model or TG_STUNT_TUBE_LAST_MODEL or tg_stunt_tube_model_at(TG_STUNT_TUBE_MODEL_INDEX)
    local placed = 0
    local last_side_delta = 0.0

    tg_log("[TUBE3D][BEGIN] label=" .. tostring(opts.label or "tube3d") ..
        " points=" .. tostring(#points) ..
        " segments=" .. tostring(#points - 1) ..
        " model=" .. tostring(model) ..
        " baseHeading=" .. string.format("%.1f", base_heading))

    for i = 1, (#points - 1) do
        util.yield(opts.delay_ms or TG_TUBE3D_SPAWN_DELAY_MS or 90)
        local a = tg_tube3d_world_point(origin, base_heading, points[i])
        local b = tg_tube3d_world_point(origin, base_heading, points[i + 1])

        local df = (b.f or 0.0) - (a.f or 0.0)
        local dr = (b.r or 0.0) - (a.r or 0.0)
        local du = (b.u or 0.0) - (a.u or 0.0)
        local horiz = math.sqrt((df * df) + (dr * dr))
        if horiz < 0.01 then horiz = 0.01 end

        local mid = {
            x = (a.x + b.x) * 0.5,
            y = (a.y + b.y) * 0.5,
            z = (a.z + b.z) * 0.5,
            f = ((a.f or 0.0) + (b.f or 0.0)) * 0.5,
            r = ((a.r or 0.0) + (b.r or 0.0)) * 0.5,
            u = ((a.u or 0.0) + (b.u or 0.0)) * 0.5
        }

        local yaw = tg_normalize_heading(base_heading + math.deg(tg_atan2_safe(dr, df)))
        local pitch = -math.deg(tg_atan2_safe(du, horiz))
        local side_delta = dr
        local roll = tonumber(points[i].roll or 0.0) or 0.0
        if roll == 0.0 and side_delta ~= 0.0 then
            roll = (side_delta > 0.0) and (TG_TUBE3D_BANK_ROLL or 12.0) or -(TG_TUBE3D_BANK_ROLL or 12.0)
        end
        if (last_side_delta ~= 0.0) and (side_delta ~= 0.0) and ((last_side_delta > 0) ~= (side_delta > 0)) then
            roll = roll * 0.5
        end
        last_side_delta = side_delta

        local obj = tg_tube3d_create_segment(model, mid.x, mid.y, mid.z, yaw, pitch, roll, "tube3d_seg_" .. tostring(i))
        if obj then placed = placed + 1 end

        if i % 4 == 0 then
            tg_log("[TUBE3D][PROGRESS] placed=" .. tostring(placed) ..
                "/" .. tostring(i) ..
                " yaw=" .. string.format("%.1f", yaw) ..
                " pitch=" .. string.format("%.1f", pitch) ..
                " roll=" .. string.format("%.1f", roll))
        end
    end

    tg_log("[TUBE3D][DONE] placed=" .. tostring(placed) .. "/" .. tostring(#points - 1) .. " label=" .. tostring(opts.label or "tube3d"))
    tg_report_state("tube3d_done")
    return placed > 0
end

function tg_tube3d_unique_grid_points()
    local g = TG_TUBE3D_GRID_SCALE or 46.0
    local h = TG_TUBE3D_HEIGHT_STEP or 23.0
    return {
        {0*g, 0*g, 0*h},
        {1*g, 0*g, 0*h},
        {2*g, 0*g, 1*h},
        {3*g, 1*g, 2*h},
        {3*g, 2*g, 3*h},
        {2*g, 3*g, 4*h},
        {1*g, 3*g, 5*h},
        {0*g, 2*g, 6*h},
        {-1*g, 1*g, 5*h},
        {-2*g, 1*g, 4*h},
        {-3*g, 2*g, 3*h},
        {-3*g, 3*g, 2*h},
        {-2*g, 4*g, 1*h},
        {-1*g, 4*g, 0*h},
        {0*g, 3*g, 0*h},
        {1*g, 2*g, 1*h},
        {2*g, 1*g, 2*h},
        {3*g, 0*g, 1*h},
        {4*g, 0*g, 0*h}
    }
end

function tg_tube3d_corkscrew_points()
    local g = TG_TUBE3D_GRID_SCALE or 46.0
    local h = TG_TUBE3D_HEIGHT_STEP or 23.0
    return {
        {0*g, 0*g, 0*h},
        {1*g, 0*g, 0*h},
        {2*g, 1*g, 1*h},
        {2*g, 2*g, 2*h},
        {1*g, 3*g, 3*h},
        {0*g, 3*g, 4*h},
        {-1*g, 2*g, 5*h},
        {-1*g, 1*g, 6*h},
        {0*g, 0*g, 7*h},
        {1*g, -1*g, 6*h},
        {2*g, -1*g, 5*h},
        {3*g, 0*g, 4*h},
        {3*g, 1*g, 3*h},
        {2*g, 2*g, 2*h},
        {1*g, 2*g, 1*h},
        {0*g, 1*g, 0*h}
    }
end

function tg_spawn_tube3d_unique_grid_track()
    return tg_tube3d_spawn_path(tg_tube3d_unique_grid_points(), { label = "unique_3d_grid_track", clear_label = "tube3d_unique_grid", delay_ms = TG_TUBE3D_SPAWN_DELAY_MS })
end

function tg_spawn_tube3d_corkscrew_climb()
    return tg_tube3d_spawn_path(tg_tube3d_corkscrew_points(), { label = "corkscrew_climb", clear_label = "tube3d_corkscrew", delay_ms = TG_TUBE3D_SPAWN_DELAY_MS })
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.8.6 ordered 3d tube snake builders
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_TUBE_ORDERED_MODEL = TG_TUBE_ORDERED_MODEL or "stt_prop_stunt_tube_l"
TG_TUBE_ORDERED_STEP = TG_TUBE_ORDERED_STEP or 37.5
TG_TUBE_ORDERED_HEIGHT_STEP = TG_TUBE_ORDERED_HEIGHT_STEP or 12.0
TG_TUBE_ORDERED_LANE = TG_TUBE_ORDERED_LANE or 54.0
TG_TUBE_ORDERED_Z_BASE = TG_TUBE_ORDERED_Z_BASE or 8.0

function tg_tube3d_ordered_points_snake()
    local s = TG_TUBE_ORDERED_STEP or 37.5
    local z = TG_TUBE_ORDERED_Z_BASE or 8.0
    local h = TG_TUBE_ORDERED_HEIGHT_STEP or 12.0
    local lane = TG_TUBE_ORDERED_LANE or 54.0

    -- This is intentionally ordered like a readable route:
    -- out -> right lane -> climb -> left return -> drop -> final straight.
    return {
        {0*s,     0,       z},
        {1*s,     0,       z},
        {2*s,     0,       z},
        {3*s,     0,       z + h},
        {4*s,     lane,    z + h},
        {5*s,     lane,    z + h * 2},
        {6*s,     lane,    z + h * 2},
        {7*s,     lane,    z + h},
        {8*s,     0,       z + h},
        {9*s,     0,       z},
        {10*s,   -lane,    z},
        {11*s,   -lane,    z - h * 0.5},
        {12*s,   -lane,    z - h * 0.5},
        {13*s,    0,       z},
        {14*s,    0,       z}
    }
end

function tg_tube3d_ordered_points_bridge()
    local s = TG_TUBE_ORDERED_STEP or 37.5
    local z = TG_TUBE_ORDERED_Z_BASE or 8.0
    local h = TG_TUBE_ORDERED_HEIGHT_STEP or 12.0
    local lane = TG_TUBE_ORDERED_LANE or 54.0

    -- Simpler / more readable for first multiplayer test:
    -- straight bridge -> climb -> S bend -> straight exit.
    return {
        {0*s,    0,      z},
        {1*s,    0,      z},
        {2*s,    0,      z + h},
        {3*s,    0,      z + h * 2},
        {4*s,    lane,   z + h * 2},
        {5*s,    lane,   z + h * 2},
        {6*s,    0,      z + h},
        {7*s,   -lane,   z + h},
        {8*s,   -lane,   z},
        {9*s,    0,      z},
        {10*s,   0,      z}
    }
end

function tg_tube3d_spawn_ordered_path(points, opts)
    opts = opts or {}
    points = points or {}
    if #points < 2 then tg_warn("TUBE_ORDER", "not enough points"); return false end

    clear_race_track(opts.clear_label or "ordered_tube_path")
    local origin, base_heading = tg_get_local_position_heading(opts.label or "ordered_tube_path")
    base_heading = tonumber(opts.base_heading or base_heading or 0.0) or 0.0
    local model = opts.model or TG_TUBE_ORDERED_MODEL or TG_STUNT_TUBE_LAST_MODEL or tg_stunt_tube_model_at(TG_STUNT_TUBE_MODEL_INDEX)
    local placed = 0

    tg_log("[TUBE_ORDER][BEGIN] label=" .. tostring(opts.label or "ordered") ..
        " segments=" .. tostring(#points - 1) ..
        " model=" .. tostring(model) ..
        " baseHeading=" .. string.format("%.1f", base_heading))

    for i = 1, (#points - 1) do
        util.yield(opts.delay_ms or TG_TUBE3D_SPAWN_DELAY_MS or 90)

        local a = tg_tube3d_world_point(origin, base_heading, points[i])
        local b = tg_tube3d_world_point(origin, base_heading, points[i + 1])
        local df = (b.f or 0.0) - (a.f or 0.0)
        local dr = (b.r or 0.0) - (a.r or 0.0)
        local du = (b.u or 0.0) - (a.u or 0.0)
        local horiz = math.sqrt((df * df) + (dr * dr))
        if horiz < 0.01 then horiz = 0.01 end

        local mid = {
            x = (a.x + b.x) * 0.5,
            y = (a.y + b.y) * 0.5,
            z = (a.z + b.z) * 0.5
        }

        local yaw = tg_normalize_heading(base_heading + math.deg(tg_atan2_safe(dr, df)))
        local pitch = -math.deg(tg_atan2_safe(du, horiz))
        local roll = 0.0
        if math.abs(dr) > 1.0 then
            roll = (dr > 0.0) and 8.0 or -8.0
        end

        local obj = tg_tube3d_create_segment(model, mid.x, mid.y, mid.z, yaw, pitch, roll, "ordered_tube_" .. tostring(i))
        if obj then
            placed = placed + 1
            local meta = tg_get_meta(obj) or {}
            meta.order_index = i
            meta.order_total = #points - 1
            tg_set_meta(obj, meta)
        end

        tg_log("[TUBE_ORDER][SEGMENT] i=" .. tostring(i) ..
            "/" .. tostring(#points - 1) ..
            " placed=" .. tostring(obj ~= nil) ..
            " yaw=" .. string.format("%.1f", yaw) ..
            " pitch=" .. string.format("%.1f", pitch) ..
            " roll=" .. string.format("%.1f", roll))
    end

    tg_log("[TUBE_ORDER][DONE] placed=" .. tostring(placed) .. "/" .. tostring(#points - 1) .. " label=" .. tostring(opts.label or "ordered"))
    tg_report_state("ordered_tube_done")
    return placed > 0
end

function tg_spawn_tube3d_ordered_snake()
    return tg_tube3d_spawn_ordered_path(tg_tube3d_ordered_points_snake(), {
        label = "ordered_3d_snake",
        clear_label = "ordered_3d_snake",
        model = TG_TUBE_ORDERED_MODEL,
        delay_ms = TG_TUBE3D_SPAWN_DELAY_MS
    })
end

function tg_spawn_tube3d_ordered_bridge()
    return tg_tube3d_spawn_ordered_path(tg_tube3d_ordered_points_bridge(), {
        label = "ordered_sky_bridge",
        clear_label = "ordered_sky_bridge",
        model = TG_TUBE_ORDERED_MODEL,
        delay_ms = TG_TUBE3D_SPAWN_DELAY_MS
    })
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.8.7 connected tube chain builders
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_TUBE_CONNECTED_SPACING = TG_TUBE_CONNECTED_SPACING or 22.0
TG_TUBE_CONNECTED_MODEL = TG_TUBE_CONNECTED_MODEL or "stt_prop_stunt_tube_l"

function tg_tube3d_lerp_point(a, b, t)
    a = a or {0,0,0}
    b = b or {0,0,0}
    t = tonumber(t or 0.0) or 0.0
    local af = tonumber(a[1] or a.f or 0.0) or 0.0
    local ar = tonumber(a[2] or a.r or 0.0) or 0.0
    local au = tonumber(a[3] or a.u or 0.0) or 0.0
    local bf = tonumber(b[1] or b.f or 0.0) or 0.0
    local br = tonumber(b[2] or b.r or 0.0) or 0.0
    local bu = tonumber(b[3] or b.u or 0.0) or 0.0
    return { af + (bf - af) * t, ar + (br - ar) * t, au + (bu - au) * t }
end

function tg_tube3d_dist_points(a, b)
    a = a or {0,0,0}
    b = b or {0,0,0}
    local af = tonumber(a[1] or a.f or 0.0) or 0.0
    local ar = tonumber(a[2] or a.r or 0.0) or 0.0
    local au = tonumber(a[3] or a.u or 0.0) or 0.0
    local bf = tonumber(b[1] or b.f or 0.0) or 0.0
    local br = tonumber(b[2] or b.r or 0.0) or 0.0
    local bu = tonumber(b[3] or b.u or 0.0) or 0.0
    local df, dr, du = bf - af, br - ar, bu - au
    return math.sqrt(df * df + dr * dr + du * du)
end

function tg_tube3d_resample_polyline(points, spacing)
    points = points or {}
    spacing = tonumber(spacing or TG_TUBE_CONNECTED_SPACING or 22.0) or 22.0
    local sampled = {}
    if #points < 2 then return sampled end
    table.insert(sampled, points[1])

    for i = 1, (#points - 1) do
        local a = points[i]
        local b = points[i + 1]
        local dist = tg_tube3d_dist_points(a, b)
        local steps = math.max(1, math.floor(dist / spacing + 0.5))
        for j = 1, steps do
            table.insert(sampled, tg_tube3d_lerp_point(a, b, j / steps))
        end
    end
    return sampled
end

function tg_tube3d_connected_path(points, opts)
    opts = opts or {}
    points = points or {}
    if #points < 2 then tg_warn("TUBE_CONNECTED", "not enough points"); return false end

    local spacing = tonumber(opts.spacing or TG_TUBE_CONNECTED_SPACING or 22.0) or 22.0
    local sampled = tg_tube3d_resample_polyline(points, spacing)
    if #sampled < 2 then tg_warn("TUBE_CONNECTED", "resample failed"); return false end

    clear_race_track(opts.clear_label or "connected_tube_path")
    local origin, base_heading = tg_get_local_position_heading(opts.label or "connected_tube_path")
    base_heading = tonumber(opts.base_heading or base_heading or 0.0) or 0.0
    local model = opts.model or TG_TUBE_CONNECTED_MODEL or TG_TUBE_ORDERED_MODEL or "stt_prop_stunt_tube_l"
    local placed = 0

    tg_log("[TUBE_CONNECTED][BEGIN] label=" .. tostring(opts.label or "connected") ..
        " waypoints=" .. tostring(#points) ..
        " sampled=" .. tostring(#sampled) ..
        " spacing=" .. string.format("%.1f", spacing) ..
        " model=" .. tostring(model))

    for i = 1, (#sampled - 1) do
        util.yield(opts.delay_ms or 35)
        local a = tg_tube3d_world_point(origin, base_heading, sampled[i])
        local b = tg_tube3d_world_point(origin, base_heading, sampled[i + 1])
        local df = (b.f or 0.0) - (a.f or 0.0)
        local dr = (b.r or 0.0) - (a.r or 0.0)
        local du = (b.u or 0.0) - (a.u or 0.0)
        local horiz = math.sqrt((df * df) + (dr * dr))
        if horiz < 0.01 then horiz = 0.01 end

        local mid = { x = (a.x + b.x) * 0.5, y = (a.y + b.y) * 0.5, z = (a.z + b.z) * 0.5 }
        local yaw = tg_normalize_heading(base_heading + math.deg(tg_atan2_safe(dr, df)))
        local pitch = -math.deg(tg_atan2_safe(du, horiz))
        local roll = 0.0
        if math.abs(dr) > 1.0 then roll = (dr > 0.0) and 5.0 or -5.0 end

        local obj = tg_tube3d_create_segment(model, mid.x, mid.y, mid.z, yaw, pitch, roll, "connected_tube_" .. tostring(i))
        if obj then
            placed = placed + 1
            local meta = tg_get_meta(obj) or {}
            meta.connected_tube = true
            meta.connected_index = i
            meta.connected_total = #sampled - 1
            tg_set_meta(obj, meta)
        end

        if i % 8 == 0 then
            tg_log("[TUBE_CONNECTED][PROGRESS] placed=" .. tostring(placed) ..
                "/" .. tostring(i) ..
                " yaw=" .. string.format("%.1f", yaw) ..
                " pitch=" .. string.format("%.1f", pitch))
        end
    end

    tg_log("[TUBE_CONNECTED][DONE] placed=" .. tostring(placed) .. "/" .. tostring(#sampled - 1) .. " label=" .. tostring(opts.label or "connected"))
    tg_report_state("connected_tube_done")
    return placed > 0
end

function tg_spawn_tube3d_connected_bridge()
    return tg_tube3d_connected_path(tg_tube3d_ordered_points_bridge(), {
        label = "connected_sky_bridge",
        clear_label = "connected_sky_bridge",
        model = TG_TUBE_CONNECTED_MODEL,
        spacing = TG_TUBE_CONNECTED_SPACING,
        delay_ms = 35
    })
end

function tg_spawn_tube3d_connected_snake()
    return tg_tube3d_connected_path(tg_tube3d_ordered_points_snake(), {
        label = "connected_3d_snake",
        clear_label = "connected_3d_snake",
        model = TG_TUBE_CONNECTED_MODEL,
        spacing = TG_TUBE_CONNECTED_SPACING,
        delay_ms = 35
    })
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.1.3 tube pieces: race-creator style snapping for stunt tubes
-- ═══════════════════════════════════════════════════════════════════════════════════
-- every tube piece has two ports (a position + travel direction in the prop's local frame).
-- A new piece is rotated so its entry port faces the previous piece's exit port, then moved
-- so the two ports coincide - exactly how the race creator / Stunt Race Map Editor snap.
-- The bend direction at each joint can be rolled around the tube axis (left / right / up /
-- down / any angle), which is what makes the 3D loops, knots and corkscrews possible.
--
-- Port data: exact, solved from snapped joints in 129 official Rockstar stunt races (v1.1.5).
--   Bends are circular arcs: crn 90 deg R51.2, crn2 45 deg R51.9, crn_30d R181.65, crn_15d R351, crn_5d R1027.
--   Straights run along local X with port-to-port lengths xxs/speed 18.71, xs 53.71, s 88.71, m 176.19, l 263.6.
--   Rotations use SET_ENTITY_ROTATION order 2 (world = Rz(yaw) * Rx(pitch) * Ry(roll)).
-- Keep everything GLOBAL here (Cherax 200-local main chunk limit).

TG_TUBEP_MODE = (TG_TUBEP_MODE ~= false)                 -- false = old v1.1.1 tube builders
TG_TUBEP_SEAM = TG_TUBEP_SEAM or 0.0                     -- metres each piece is pulled back into the last one
TG_TUBEP_START_FORWARD = TG_TUBEP_START_FORWARD or 18.0  -- first port distance in front of you
TG_TUBEP_START_LIFT = TG_TUBEP_START_LIFT or 7.5         -- tube centre height above your feet
TG_TUBEP_CLEARANCE = TG_TUBEP_CLEARANCE or 24.0          -- min centre-line distance between non-neighbour pieces
TG_TUBEP_MAX_RISE = TG_TUBEP_MAX_RISE or 450.0
TG_TUBEP_DELAY_MS = TG_TUBEP_DELAY_MS or 70
TG_TUBEP_RANDOM_PIECES = TG_TUBEP_RANDOM_PIECES or 24

TG_TUBEP_PIECES = TG_TUBEP_PIECES or {
    -- Exact port-to-port lengths, solved from snapped joints in 129 official Rockstar races (v1.1.5).
    -- straights: entry port (-len/2,0,0), exit port (+len/2,0,0)
    xxs   = { model = "stt_prop_stunt_tube_xxs",   kind = "straight", len = 18.71 },
    fn1   = { model = "stt_prop_stunt_tube_fn_01", kind = "straight", len = 36.2 },
    fn2   = { model = "stt_prop_stunt_tube_fn_02", kind = "straight", len = 88.8 },
    jmp   = { model = "stt_prop_stunt_tube_jmp",   kind = "straight", len = 36.1 },
    xs    = { model = "stt_prop_stunt_tube_xs",    kind = "straight", len = 53.71 },
    s     = { model = "stt_prop_stunt_tube_s",     kind = "straight", len = 88.71 },
    m     = { model = "stt_prop_stunt_tube_m",     kind = "straight", len = 176.19 },
    l     = { model = "stt_prop_stunt_tube_l",     kind = "straight", len = 263.6 },
    gap   = { model = "stt_prop_stunt_tube_gap_03", kind = "straight", len = 53.71 },
    hg    = { model = "stt_prop_stunt_tube_hg",    kind = "straight", len = 36.21 },
    qg    = { model = "stt_prop_stunt_tube_qg",    kind = "straight", len = 36.21 },
    -- bends: entry port at `a` travelling +X, curving toward local +Y by `angle` with radius `r`
    crn   = { model = "stt_prop_stunt_tube_crn",     kind = "bend", angle = 90, r = 51.2,   a = { -31.6, -19.6, 0.0 } },
    crn2  = { model = "stt_prop_stunt_tube_crn2",    kind = "bend", angle = 45, r = 51.9,   a = { -22.6, -5.8, 0.0 } },
    c30   = { model = "stt_prop_stunt_tube_crn_30d", kind = "bend", angle = 30, r = 181.65, a = { -48.4, -11.35, 0.0 } },
    c15   = { model = "stt_prop_stunt_tube_crn_15d", kind = "bend", angle = 15, r = 351.0,  a = { -47.0, -5.8, 0.0 } },
    c5    = { model = "stt_prop_stunt_tube_crn_5d",  kind = "bend", angle = 5,  r = 1027.0, a = { -45.3, -1.9, 0.0 } }
}

-- End caps / entrance funnels and speed-boost tubes are NEVER placed by any tube builder.
TG_TUBEP_BANNED = {
    stt_prop_stunt_tube_end = true, stt_prop_stunt_tube_ent = true, sr_prop_sr_tube_end = true,
    -- v1.1.8: speed-boost tubes are never placed (players fell through their floor)
    stt_prop_stunt_tube_speed = true, stt_prop_stunt_tube_speeda = true, stt_prop_stunt_tube_speedb = true,
    ar_prop_ar_tube_speed = true, ar_prop_ar_tube_2x_speed = true, ar_prop_ar_tube_4x_speed = true
}

-- v1.1.8: colour variants removed (they did not spawn reliably) - every piece uses its standard model.
function tg_tp_model_for(key, pc) return pc.model end

-- Bend direction at a joint, relative to the current "up": 0 = left, 90 = up, 180 = right, 270 = down.
TG_TUBEP_LEFT, TG_TUBEP_UP, TG_TUBEP_RIGHT, TG_TUBEP_DOWN = 0, 90, 180, 270

-- ---------- vector helpers ----------
function tg_tp_v(x, y, z) return { x = x or 0.0, y = y or 0.0, z = z or 0.0 } end
function tg_tp_add(a, b) return tg_tp_v(a.x + b.x, a.y + b.y, a.z + b.z) end
function tg_tp_sub(a, b) return tg_tp_v(a.x - b.x, a.y - b.y, a.z - b.z) end
function tg_tp_mul(a, s) return tg_tp_v(a.x * s, a.y * s, a.z * s) end
function tg_tp_dot(a, b) return a.x * b.x + a.y * b.y + a.z * b.z end
function tg_tp_cross(a, b) return tg_tp_v(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x) end
function tg_tp_len(a) return math.sqrt(tg_tp_dot(a, a)) end
function tg_tp_norm(a)
    local l = tg_tp_len(a)
    if l < 0.000001 then return tg_tp_v(1.0, 0.0, 0.0) end
    return tg_tp_mul(a, 1.0 / l)
end
function tg_tp_dist(a, b) return tg_tp_len(tg_tp_sub(a, b)) end
-- Rodrigues: rotate v around unit axis k by deg degrees.
function tg_tp_rotate(v, k, deg)
    local t = math.rad(deg)
    local c, s = math.cos(t), math.sin(t)
    return tg_tp_add(tg_tp_add(tg_tp_mul(v, c), tg_tp_mul(tg_tp_cross(k, v), s)), tg_tp_mul(k, tg_tp_dot(k, v) * (1.0 - c)))
end
-- Columns X/Y/Z of the piece's world rotation applied to a local vector.
function tg_tp_apply(R, l)
    return tg_tp_v(R.X.x * l.x + R.Y.x * l.y + R.Z.x * l.z,
                   R.X.y * l.x + R.Y.y * l.y + R.Z.y * l.z,
                   R.X.z * l.x + R.Y.z * l.y + R.Z.z * l.z)
end
-- Rotation matrix -> SET_ENTITY_ROTATION (pitch=X, roll=Y, yaw=Z) for order 2 (Rz*Rx*Ry).
function tg_tp_euler(R)
    local m32 = R.Y.z
    if m32 > 1.0 then m32 = 1.0 end
    if m32 < -1.0 then m32 = -1.0 end
    local a = math.asin(m32)
    local b, c
    if math.cos(a) > 0.0001 then
        b = tg_atan2_safe(-R.X.z, R.Z.z)
        c = tg_atan2_safe(-R.Y.x, R.Y.y)
    else
        b = 0.0
        c = tg_atan2_safe(R.X.y, R.X.x)
    end
    return math.deg(a), math.deg(b), tg_normalize_heading(math.deg(c))
end

-- ---------- piece geometry ----------
function tg_tp_geo(pc)
    if pc.kind == "straight" then
        local h = pc.len * 0.5
        return tg_tp_v(-h, 0.0, 0.0), tg_tp_v(h, 0.0, 0.0), tg_tp_v(1.0, 0.0, 0.0), 0.0
    end
    local a = tg_tp_v(pc.a[1], pc.a[2], pc.a[3])
    local t = math.rad(pc.angle)
    local b = tg_tp_add(a, tg_tp_v(pc.r * math.sin(t), pc.r * (1.0 - math.cos(t)), 0.0))
    return a, b, tg_tp_v(math.cos(t), math.sin(t), 0.0), pc.angle
end

function tg_tp_local_samples(pc)
    local pts = {}
    if pc.kind == "straight" then
        local n = math.max(2, math.ceil(pc.len / 8.0))
        for i = 0, n do table.insert(pts, tg_tp_v(-pc.len * 0.5 + pc.len * i / n, 0.0, 0.0)) end
        return pts
    end
    local a = tg_tp_v(pc.a[1], pc.a[2], pc.a[3])
    local arc = pc.r * math.rad(pc.angle)
    local n = math.max(2, math.ceil(arc / 8.0))
    for i = 0, n do
        local t = math.rad(pc.angle) * i / n
        table.insert(pts, tg_tp_add(a, tg_tp_v(pc.r * math.sin(t), pc.r * (1.0 - math.cos(t)), 0.0)))
    end
    return pts
end

-- Plan one piece from a port state {P, D (travel dir), U (up)}. No spawning.
-- `roll` is degrees relative to the tube's own up (0 left, 90 up, 180 right, 270 down),
-- or a function(state, pc) returning the bend direction vector directly (world steering).
function tg_tp_plan(state, key, roll, light)
    local pc = TG_TUBEP_PIECES[key]
    if not pc or TG_TUBEP_BANNED[pc.model] then return nil end
    local D = tg_tp_norm(state.D)
    local left = tg_tp_norm(tg_tp_cross(state.U, D))
    local up = tg_tp_norm(tg_tp_cross(D, left))
    local B
    if type(roll) == "function" then
        B = roll(state, pc)
        B = tg_tp_sub(B, tg_tp_mul(D, tg_tp_dot(B, D))) -- keep it perpendicular to travel
        if tg_tp_len(B) < 0.0001 then B = left end
        B = tg_tp_norm(B)
        roll = 0.0
    else
        local r = math.rad(tonumber(roll or 0.0) or 0.0)
        B = tg_tp_norm(tg_tp_add(tg_tp_mul(left, math.cos(r)), tg_tp_mul(up, math.sin(r))))
    end
    local R = { X = D, Y = B, Z = tg_tp_cross(D, B) }
    local a, b, exit_local, bend = tg_tp_geo(pc)
    local P = tg_tp_sub(state.P, tg_tp_mul(D, tonumber(TG_TUBEP_SEAM or 0.0) or 0.0))
    local origin = tg_tp_sub(P, tg_tp_apply(R, a))
    local nextP = tg_tp_add(origin, tg_tp_apply(R, b))
    local nextD = tg_tp_norm(tg_tp_apply(R, exit_local))
    local nextU = up
    if bend ~= 0.0 then nextU = tg_tp_norm(tg_tp_rotate(up, tg_tp_norm(R.Z), bend)) end
    if light then return { next = { P = nextP, D = nextD, U = nextU } } end
    local samples = {}
    for _, l in ipairs(tg_tp_local_samples(pc)) do table.insert(samples, tg_tp_add(origin, tg_tp_apply(R, l))) end
    local pitch, rollY, yaw = tg_tp_euler(R)
    local arc = (pc.kind == "straight") and pc.len or (pc.r * math.rad(pc.angle))
    return {
        key = key, model = tg_tp_model_for(key, pc), roll = roll or 0.0, arc = arc, R = R,
        origin = origin, pitch = pitch, rollY = rollY, yaw = yaw,
        samples = samples,
        next = { P = nextP, D = nextD, U = nextU }
    }
end

-- true when the planned piece stays clear of everything except the piece it attaches to.
function tg_tp_fits(plan, placed, ctx)
    ctx = ctx or {}
    for _, s in ipairs(plan.samples) do
        if ctx.floor_z and s.z < ctx.floor_z then return false, "floor" end
        if ctx.ceil_z and s.z > ctx.ceil_z then return false, "ceiling" end
    end
    local clear = tonumber(ctx.clearance or TG_TUBEP_CLEARANCE or 20.0) or 20.0
    local clear2 = clear * clear
    -- Skip the pieces right behind this one (measured along the tube), they touch by design.
    local skip_until = #placed
    local along = 0.0
    while skip_until >= 1 and along < clear * 1.5 do
        along = along + (placed[skip_until].arc or 0.0)
        skip_until = skip_until - 1
    end
    for i = 1, skip_until do
        if not (tg_rs_far(plan, placed[i], clear)) then
        for _, s in ipairs(plan.samples) do
            for _, q in ipairs(placed[i].samples) do
                local dx, dy, dz = s.x - q.x, s.y - q.y, s.z - q.z
                if dx * dx + dy * dy + dz * dz < clear2 then return false, "overlap#" .. tostring(i) end
            end
        end
    end
    end
    return true, "ok"
end

-- Steering that holds a target pitch while turning left (+1) or right (-1) in world terms.
function tg_tp_steer_pitch(side, target_pitch_deg)
    return function(state, pc)
        local D = tg_tp_norm(state.D)
        local Z = tg_tp_v(0.0, 0.0, 1.0)
        local leftW = tg_tp_cross(Z, D)
        if tg_tp_len(leftW) < 0.05 then leftW = tg_tp_cross(state.U, D) end
        leftW = tg_tp_norm(leftW)
        local upW = tg_tp_norm(tg_tp_cross(D, leftW))
        local th = math.rad(pc.angle or 0.0)
        local p = math.asin(math.max(-1.0, math.min(1.0, D.z)))
        local sp = (math.sin(math.rad(target_pitch_deg or 0.0)) - math.sin(p) * math.cos(th)) / math.max(0.0001, math.sin(th) * math.cos(p))
        if sp > 1.0 then sp = 1.0 end
        if sp < -1.0 then sp = -1.0 end
        local cp = math.sqrt(1.0 - sp * sp) * ((side or 1) >= 0 and 1.0 or -1.0)
        return tg_tp_add(tg_tp_mul(leftW, cp), tg_tp_mul(upW, sp))
    end
end

-- ---------- start frame ----------
function tg_tp_start_state(label)
    local pos, heading = tg_get_local_position_heading(label or "tube_pieces")
    heading = tonumber(heading or 0.0) or 0.0
    local fx, fy = calculate_new_position({ x = 0.0, y = 0.0, z = 0.0 }, heading, 1.0, 0.0, 0.0)
    local D = tg_tp_norm(tg_tp_v(fx, fy, 0.0))
    local sx, sy, sz = calculate_new_position(pos, heading, TG_TUBEP_START_FORWARD or 18.0, 0.0, TG_TUBEP_START_LIFT or 7.5)
    return { P = tg_tp_v(sx, sy, sz), D = D, U = tg_tp_v(0.0, 0.0, 1.0) }
end

-- ---------- spawning ----------
function tg_tp_spawn(plan, label)
    local o = plan.origin
    local obj = tg_try_create_stunt_tube_model(plan.model, o.x, o.y, o.z, plan.yaw, label)
    if not obj then return nil end
    tg_tube3d_apply_rotation(obj, plan.pitch, plan.rollY, plan.yaw, label)
    local meta = tg_get_meta(obj) or {}
    meta.tube3d = true
    meta.tube_piece = plan.key
    meta.pitch = plan.pitch
    meta.roll = plan.rollY
    meta.heading = plan.yaw
    tg_set_meta(obj, meta)
    if plan.tint and tg_pk_tint then tg_pk_tint(obj, plan.tint) end
    if tg_tn_harden then
        tg_tn_harden(obj, { x = o.x, y = o.y, z = o.z + (tonumber(TG_TRACK_HEIGHT_OFFSET or 0.0) or 0.0),
            pitch = plan.pitch, roll = plan.rollY, yaw = plan.yaw, model = plan.model })
    end
    return obj
end

function tg_tp_spawn_all(plans, label)
    if tg_rs_build_start and not TG_RS_RUN_GEN then tg_rs_build_start("Tubes") end
    tg_rs_preload("Tubes", plans)
    local token = tg_generation_start(label) or nil
    local placed = 0
    local missed = nil
    for i, plan in ipairs(plans) do
        if tg_generation_should_stop(token, label) then break end
        if tg_rs_spawn_progress("Tubes", i, #plans, "Spawning tube") then break end
        util.yield(TG_TUBEP_DELAY_MS or 70)
        if tg_tp_spawn(plan, label .. "_" .. tostring(i)) then placed = placed + 1 else missed = missed or {}; table.insert(missed, plan) end
        if i % 5 == 0 then
            tg_log("[TUBE_PIECES][PROGRESS] " .. label .. " " .. tostring(i) .. "/" .. tostring(#plans) .. " key=" .. tostring(plan.key) ..
                " rot=" .. string.format("%.1f,%.1f,%.1f", plan.pitch, plan.rollY, plan.yaw))
        end
    end
    if tg_rs_check_cancel() then return placed end
    if missed and tg_rs_repair then placed = placed + tg_rs_repair("Tubes", missed, function(plan, k) return tg_tp_spawn(plan, label .. "_fix_" .. tostring(k)) end) end
    tg_log("[TUBE_PIECES][DONE] " .. label .. " placed=" .. tostring(placed) .. "/" .. tostring(#plans))
    tg_tn_settle_all(label)
    tg_report_state("tube_pieces_done")
    tg_rs_progress_done(string.format("%d / %d tubes placed", placed, #plans))
    return placed
end

-- Plan a fixed sequence {{key, roll}, ...}; stops early if a piece would collide.
function tg_tp_plan_sequence(state, seq, ctx)
    local plans = {}
    for i, step in ipairs(seq) do
        local plan = tg_tp_plan(state, step[1], step[2])
        if not plan then break end
        local ok, why = tg_tp_fits(plan, plans, ctx)
        if not ok then
            tg_log("[TUBE_PIECES][PLAN] stopped at step " .. tostring(i) .. " reason=" .. tostring(why))
            break
        end
        table.insert(plans, plan)
        state = plan.next
    end
    return plans, state
end

function tg_tp_build_sequence(seq, label, ctx)
    clear_race_track(label)
    local start = tg_tp_start_state(label)
    ctx = ctx or {}
    ctx.floor_z = ctx.floor_z or (start.P.z - 1.0)
    ctx.ceil_z = ctx.ceil_z or (start.P.z + (TG_TUBEP_MAX_RISE or 450.0))
    local plans = tg_tp_plan_sequence(start, seq, ctx)
    local placed = tg_tp_spawn_all(plans, label)
    if tg_rs_check_cancel() then return false end
    tg_toast("Tube shape: " .. tostring(placed) .. " pieces snapped.", 3000)
    return placed > 0
end

-- ---------- random generator (plans with backtracking, then spawns) ----------
TG_TUBEP_RANDOM_MENU = TG_TUBEP_RANDOM_MENU or {
    { "s", 0, 5 }, { "m", 0, 2 }, { "l", 0, 0.6 },
    { "c30", 0, 2 }, { "c30", 180, 2 }, { "c30", 90, 1.2 }, { "c30", 270, 1.2 },
    { "c15", 0, 0.8 }, { "c15", 180, 0.8 }, { "c15", 90, 0.6 }, { "c15", 270, 0.6 },
    { "crn2", 0, 1.2 }, { "crn2", 180, 1.2 }, { "crn2", 90, 0.8 }, { "crn2", 270, 0.8 },
    { "crn", 0, 1.2 }, { "crn", 180, 1.2 }, { "crn", 90, 0.9 }, { "crn", 270, 0.9 },
    { "crn", 45, 0.5 }, { "crn", 135, 0.5 }, { "crn", 225, 0.5 }, { "crn", 315, 0.5 }
}

function tg_tp_shuffled_options(menu_list)
    local pool = {}
    for _, o in ipairs(menu_list) do table.insert(pool, { o[1], o[2], o[3] }) end
    local out = {}
    while #pool > 0 do
        local total = 0.0
        for _, o in ipairs(pool) do total = total + o[3] end
        local pick = math.random() * total
        local idx = #pool
        for i, o in ipairs(pool) do
            pick = pick - o[3]
            if pick <= 0.0 then idx = i; break end
        end
        table.insert(out, pool[idx])
        table.remove(pool, idx)
    end
    return out
end

function tg_tp_plan_random(start, count, menu_list, ctx, prefix)
    local plans = {}
    prefix = prefix or {}
    local function fits_all(plan)
        local all = {}
        for _, p in ipairs(prefix) do table.insert(all, p) end
        for _, p in ipairs(plans) do table.insert(all, p) end
        return tg_tp_fits(plan, all, ctx)
    end
    local states = { start }
    local tried = {}
    local budget = 600
    while #plans < count and budget > 0 do
        budget = budget - 1
        local depth = #plans + 1
        tried[depth] = tried[depth] or tg_tp_shuffled_options(menu_list)
        local placed_one = false
        while #tried[depth] > 0 do
            local opt = table.remove(tried[depth], 1)
            local plan = tg_tp_plan(states[depth], opt[1], opt[2])
            if plan and fits_all(plan) then
                table.insert(plans, plan)
                states[depth + 1] = plan.next
                tried[depth + 1] = nil
                placed_one = true
                break
            end
        end
        if not placed_one then
            -- dead end: back up one piece and try something else there
            tried[depth] = nil
            if #plans == 0 then break end
            table.remove(plans)
            states[depth] = nil
        end
    end
    return plans
end

function tg_tp_build_random(label, count, menu_list, first_seq)
    clear_race_track(label)
    TG_TUBEP_SEED_BUMP = (TG_TUBEP_SEED_BUMP or 0) + 7919
    if math.randomseed then math.randomseed(((os.time and os.time()) or 1) + TG_TUBEP_SEED_BUMP) end
    local start = tg_tp_start_state(label)
    local ctx = { floor_z = start.P.z - 1.0, ceil_z = start.P.z + (TG_TUBEP_MAX_RISE or 450.0) }
    local lead, state = tg_tp_plan_sequence(start, first_seq or { { "s", 0 } }, ctx)
    local rest = tg_tp_plan_random(state, count or TG_TUBEP_RANDOM_PIECES or 24, menu_list or TG_TUBEP_RANDOM_MENU, ctx, lead)
    local plans = {}
    for _, p in ipairs(lead) do table.insert(plans, p) end
    for _, p in ipairs(rest) do table.insert(plans, p) end
    tg_log("[TUBE_PIECES][RANDOM] " .. label .. " planned=" .. tostring(#plans))
    local placed = tg_tp_spawn_all(plans, label)
    if tg_rs_check_cancel() then return false end
    tg_toast("Tube course: " .. tostring(placed) .. " pieces snapped.", 3000)
    return placed > 0
end

-- ---------- preset shapes ----------
function tg_tube_shape_random_course()
    return tg_tp_build_random("tube_random_course", TG_TUBEP_RANDOM_PIECES or 24, TG_TUBEP_RANDOM_MENU, { { "s", 0 } })
end

-- Only tight corners with free roll at every joint: the twisted "knot" look.
TG_TUBEP_KNOT_MENU = TG_TUBEP_KNOT_MENU or {
    { "crn", 0, 1 }, { "crn", 45, 1 }, { "crn", 90, 1 }, { "crn", 135, 1 },
    { "crn", 180, 1 }, { "crn", 225, 1 }, { "crn", 270, 1 }, { "crn", 315, 1 },
    { "crn2", 0, 0.6 }, { "crn2", 90, 0.6 }, { "crn2", 180, 0.6 }, { "crn2", 270, 0.6 },
    { "xxs", 0, 0.5 }
}
function tg_tube_shape_knot()
    return tg_tp_build_random("tube_knot", 16, TG_TUBEP_KNOT_MENU, { { "s", 0 }, { "crn", TG_TUBEP_UP } })
end

-- Vertical loop: up, over the top, a sideways jog, back down beside the entry.
function tg_tube_shape_loop()
    return tg_tp_build_sequence({
        { "s", 0 },
        { "crn", TG_TUBEP_UP }, { "crn", TG_TUBEP_UP },
        { "crn2", TG_TUBEP_LEFT }, { "crn2", TG_TUBEP_RIGHT },
        { "crn", TG_TUBEP_UP }, { "crn", TG_TUBEP_UP },
        { "s", 0 }
    }, "tube_loop", { clearance = 18.0 })
end

-- Corkscrew: the bend direction twists a fixed amount every joint (constant torsion = helix).
-- The 60-degree lead-in lines the coil's axis up with the direction you are facing.
TG_TUBEP_CORK_TWIST = TG_TUBEP_CORK_TWIST or 25
function tg_tube_shape_corkscrew()
    local seq = { { "s", 0 }, { "crn2", TG_TUBEP_LEFT }, { "c15", TG_TUBEP_LEFT } }
    for i = 1, 14 do table.insert(seq, { "crn2", (TG_TUBEP_UP + (i - 1) * TG_TUBEP_CORK_TWIST) % 360 }) end
    table.insert(seq, { "s", 0 })
    return tg_tp_build_sequence(seq, "tube_corkscrew")
end

-- Spiral climb: 45-degree corners steered to hold a steady climb, then level out.
TG_TUBEP_SPIRAL_PITCH = TG_TUBEP_SPIRAL_PITCH or 10.0
function tg_tube_shape_spiral()
    local seq = { { "s", 0 } }
    for i = 1, 20 do table.insert(seq, { "crn2", tg_tp_steer_pitch(1, TG_TUBEP_SPIRAL_PITCH) }) end
    table.insert(seq, { "crn2", tg_tp_steer_pitch(1, 0.0) })
    table.insert(seq, { "s", tg_tp_steer_pitch(1, 0.0) })
    return tg_tp_build_sequence(seq, "tube_spiral")
end

-- Sky bridge: climb, S-bend, drop.
function tg_tube_shape_sky_bridge()
    return tg_tp_build_sequence({
        { "s", 0 }, { "c15", TG_TUBEP_UP }, { "c15", TG_TUBEP_UP }, { "s", 0 },
        { "c15", TG_TUBEP_DOWN }, { "c15", TG_TUBEP_DOWN },
        { "c30", TG_TUBEP_LEFT }, { "c30", TG_TUBEP_RIGHT }, { "c30", TG_TUBEP_RIGHT }, { "c30", TG_TUBEP_LEFT },
        { "s", 0 }, { "c15", TG_TUBEP_DOWN }, { "c15", TG_TUBEP_UP }, { "s", 0 }
    }, "tube_sky_bridge")
end

-- Snake: random gentle bends only (left/right/up/down), always unique.
TG_TUBEP_SNAKE_MENU = TG_TUBEP_SNAKE_MENU or {
    { "s", 0, 3 }, { "m", 0, 1 },
    { "c30", 0, 2 }, { "c30", 180, 2 }, { "c30", 90, 0.8 }, { "c30", 270, 0.8 },
    { "c15", 0, 1 }, { "c15", 180, 1 }, { "c15", 90, 0.8 }, { "c15", 270, 0.8 },
    { "crn2", 0, 0.8 }, { "crn2", 180, 0.8 }
}
function tg_tube_shape_snake()
    return tg_tp_build_random("tube_snake", 20, TG_TUBEP_SNAKE_MENU, { { "s", 0 } })
end

-- ---------- interactive builder (place one piece at a time, auto-snapped) ----------
TG_TUBEP_BUILD = TG_TUBEP_BUILD or nil

function tg_tube_build_start()
    clear_race_track("tube_build_start")
    local start = tg_tp_start_state("tube_build_start")
    TG_TUBEP_BUILD = { start = start, state = start, stack = {} }
    tg_toast("Tube Builder ready: add pieces. Each one snaps to the last.", 3500)
    tg_log("[TUBE_BUILD][START] P=" .. string.format("%.1f,%.1f,%.1f", start.P.x, start.P.y, start.P.z))
end

function tg_tube_build_add(key, roll)
    if not TG_TUBEP_BUILD then tg_tube_build_start() end
    local b = TG_TUBEP_BUILD
    local plan = tg_tp_plan(b.state, key, roll)
    if not plan then return end
    local placed_plans = {}
    for _, e in ipairs(b.stack) do table.insert(placed_plans, e.plan) end
    local ok, why = tg_tp_fits(plan, placed_plans, { floor_z = b.start.P.z - 1.0 })
    if not ok then
        tg_toast("That piece would hit the course (" .. tostring(why) .. "). Try another.", 3000)
        return
    end
    local obj = tg_tp_spawn(plan, "tube_build_" .. tostring(#b.stack + 1))
    if not obj then tg_toast("Piece failed to spawn: " .. tostring(plan.model), 3000); return end
    table.insert(b.stack, { obj = obj, plan = plan, prev = b.state })
    b.state = plan.next
end

function tg_tube_build_undo()
    local b = TG_TUBEP_BUILD
    if not b or #b.stack == 0 then tg_toast("Nothing to undo.", 2000); return end
    local e = table.remove(b.stack)
    tg_delete(e.obj)
    for i = #objects, 1, -1 do
        if objects[i] == e.obj then table.remove(objects, i); break end
    end
    b.state = e.prev
end

-- ---------- settings ----------
function tg_tube_shapes_seam(delta)
    local v = (tonumber(TG_TUBEP_SEAM or 0.0) or 0.0) + (tonumber(delta or 0.0) or 0.0)
    if v < -2.0 then v = -2.0 end
    if v > 4.0 then v = 4.0 end
    TG_TUBEP_SEAM = v
    tg_toast("Tube seam overlap: " .. string.format("%.2f", v) .. " m (negative = spread apart).", 3000)
end

function tg_tube_shapes_toggle_legacy()
    TG_TUBEP_MODE = not TG_TUBEP_MODE
    tg_toast(TG_TUBEP_MODE and "Tube buttons: SNAP pieces (new)." or "Tube buttons: LEGACY v1.1.1 builders.", 3500)
end

