TG_TUBE_LEGACY_BUILDERS = {
    connected_bridge = tg_spawn_tube3d_connected_bridge,
    connected_snake = tg_spawn_tube3d_connected_snake,
    ordered_bridge = tg_spawn_tube3d_ordered_bridge,
    ordered_snake = tg_spawn_tube3d_ordered_snake,
    unique_grid = tg_spawn_tube3d_unique_grid_track,
    corkscrew = tg_spawn_tube3d_corkscrew_climb
}
function tg_spawn_tube3d_connected_bridge()
    if not TG_TUBEP_MODE then return TG_TUBE_LEGACY_BUILDERS.connected_bridge() end
    return tg_tube_shape_sky_bridge()
end
function tg_spawn_tube3d_connected_snake()
    if not TG_TUBEP_MODE then return TG_TUBE_LEGACY_BUILDERS.connected_snake() end
    return tg_tube_shape_snake()
end
function tg_spawn_tube3d_ordered_bridge()
    if not TG_TUBEP_MODE then return TG_TUBE_LEGACY_BUILDERS.ordered_bridge() end
    return tg_tube_shape_sky_bridge()
end
function tg_spawn_tube3d_ordered_snake()
    if not TG_TUBEP_MODE then return TG_TUBE_LEGACY_BUILDERS.ordered_snake() end
    return tg_tube_shape_snake()
end
function tg_spawn_tube3d_unique_grid_track()
    if not TG_TUBEP_MODE then return TG_TUBE_LEGACY_BUILDERS.unique_grid() end
    return tg_tube_shape_knot()
end
function tg_spawn_tube3d_corkscrew_climb()
    if not TG_TUBEP_MODE then return TG_TUBE_LEGACY_BUILDERS.corkscrew() end
    return tg_tube_shape_corkscrew()
end
