for _, m in ipairs(TG_TUBE_MODULES) do TG_TUBE_MODULE_BY_ID[m.id] = m end

-- 30 piece types offered in the Tubes tab (mix of level, climbing, twisting and diving shapes)
TG_TUBE_PIECE_TYPES = { "loop", "dloop", "bigloop", "cobra", "sbendl", "chicl", "zigzag", "hairl", "wideul", "hump",
    "dip", "camel", "wave", "stepup", "stepdn", "climb", "drop", "overpass", "sclimb", "diags",
    "twist", "barrel", "cork", "helixup", "helixdn", "spiral", "knot", "pretzel", "bankl", "dropturn" }
-- 30 level-returning shapes offered in the Hybrid tab (they hand back onto a flat track)
TG_HY_TUBE_SHAPE_IDS = { "loop", "loopr", "dloop", "bigloop", "dip", "sbendl", "sbendr", "sweepl", "sweepr", "chicl",
    "chicr", "zigzag", "hairl", "hairr", "cornl", "cornr", "wideul", "wideur", "hump", "camel",
    "wave", "overpass", "diags", "diags2", "kink", "longsweep", "tunnel", "longtunnel", "gapjump", "jumptube" }

-- mirror a relative roll left<->right (up/down unchanged)
function tg_tm_mirror_roll(r)
    if type(r) ~= "number" then return r end
    return (180 - r) % 360
end

-- module -> menu template for a tube family prefix; nil if a piece is missing/banned/not allowed
function tg_tm_template(mod, pre, allowed, mirror)
    if mod.needs and allowed and not allowed["__" .. mod.needs] then return nil end
    local steps = {}
    for _, st in ipairs(mod.seq) do
        local k = (pre or "") .. st[1]
        local pc = TG_TUBEP_PIECES[k]
        if not pc or TG_TUBEP_BANNED[pc.model] then return nil end
        table.insert(steps, { k, mirror and tg_tm_mirror_roll(st[2]) or st[2] })
    end
    return steps
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.1.4 tube circuits: closed stunt courses with a start/finish line
-- ═══════════════════════════════════════════════════════════════════════════════════
-- a circuit is 4 corners with a "side" between each. every module on a side leaves the
-- tube pointing the same way it came in. Opposite sides hold the SAME modules (shuffled),
-- so their displacements cancel exactly and the last piece always lands on the first.
-- Total objects stay under TG_TUBEC_MAX_OBJECTS (lobby object limit ~70).

TG_TUBEC_MAX_OBJECTS = TG_TUBEC_MAX_OBJECTS or 66
TG_TUBEC_START_LIFT = TG_TUBEC_START_LIFT or 20.0   -- circuit floats this high (teleport in)
TG_TUBEC_GATE_RADIUS = TG_TUBEC_GATE_RADIUS or 16.0
TG_TUBEC_ATTEMPTS = TG_TUBEC_ATTEMPTS or 60


-- name, piece list, weight. Every module keeps heading and "up" unchanged and ends at its start height.
TG_TUBEC_MODULES = TG_TUBEC_MODULES or {
    { "straight S",   { { "s", 0 } }, 3 },
    { "straight M",   { { "m", 0 } }, 1.2 },
    { "gap jump",     { { "xxs", 0 }, { "gap", 0 }, { "xxs", 0 } }, 0.8 },
    { "hill",         { { "c15", 90 }, { "c15", 270 }, { "c15", 270 }, { "c15", 90 } }, 1.4 },
    { "big hill",     { { "c30", 90 }, { "c30", 270 }, { "c30", 270 }, { "c30", 90 } }, 0.8 },
    { "s-bend",       { { "c30", 0 }, { "c30", 180 }, { "c30", 180 }, { "c30", 0 } }, 1.2 },
    { "chicane",      { { "crn2", 0 }, { "crn2", 180 }, { "crn2", 180 }, { "crn2", 0 } }, 1.0 },
    -- the loop exits ~75 m behind its entry, beside its own run-up straight, so it carries that straight
    { "loop",         { { "s", 0 }, { "crn", 90 }, { "crn", 90 }, { "crn2", 0 }, { "crn2", 180 }, { "crn", 90 }, { "crn", 90 } }, 1.8 }
}

function tg_tc_pick_module(budget_left)
    local pool, total = {}, 0.0
    for _, m in ipairs(TG_TUBEC_MODULES) do
        if #m[2] * 2 <= budget_left then table.insert(pool, m); total = total + m[3] end
    end
    if #pool == 0 then return nil end
    local r = math.random() * total
    for _, m in ipairs(pool) do
        r = r - m[3]
        if r <= 0.0 then return m end
    end
    return pool[#pool]
end

function tg_tc_shuffle(list)
    local out = {}
    for _, v in ipairs(list) do table.insert(out, v) end
    for i = #out, 2, -1 do
        local j = math.random(1, i)
        out[i], out[j] = out[j], out[i]
    end
    return out
end

-- Global self-intersection check for a closed loop (wraps around at the start line).
-- open = true for start-to-finish courses (the ends are NOT joined, so no wrap-around skip)
function tg_tc_clear(plans, floor_z, clearance, open, new_from)
    if new_from and new_from > 1 and tg_rs_far then return tg_tc_clear_new(plans, floor_z, clearance, open, new_from) end
    local samples = {}
    local s_acc = 0.0
    for pi, p in ipairs(plans) do
        local n = #p.samples
        for si, pt in ipairs(p.samples) do
            if floor_z and pt.z < floor_z then return false, "floor" end
            table.insert(samples, { p = pt, s = s_acc + (p.arc or 0.0) * ((si - 1) / math.max(1, n - 1)), piece = pi })
        end
        s_acc = s_acc + (p.arc or 0.0)
    end
    local total = s_acc
    local c2 = clearance * clearance
    local skip = clearance * 2.0
    for i = 1, #samples do
        local a = samples[i]
        for j = i + 1, #samples do
            local b = samples[j]
            local ds = math.abs(b.s - a.s)
            if not open and ds > total - ds then ds = total - ds end
            if ds > skip then
                local dx, dy, dz = a.p.x - b.p.x, a.p.y - b.p.y, a.p.z - b.p.z
                if dx * dx + dy * dy + dz * dz < c2 then return false, "overlap " .. a.piece .. "/" .. b.piece end
            end
        end
    end
    return true, "ok"
end

function tg_tc_plan_circuit(start, opts)
    opts = opts or {}
    local max_obj = tonumber(opts.max_objects or TG_TUBEC_MAX_OBJECTS or 48) or 48
    local turn = (math.random() < 0.5) and TG_TUBEP_LEFT or TG_TUBEP_RIGHT
    -- side A (starts with the boost start line) and side B; opposite sides repeat them shuffled
    local budget = max_obj - 4
    local sideA = { { "start", { { "xxs", 0 } }, 0 } }
    budget = budget - 2
    local sideB = {}
    local wantA = math.random(2, 4)
    local wantB = math.random(1, 3)
    for i = 1, wantA do
        local m = tg_tc_pick_module(budget)
        if not m then break end
        table.insert(sideA, m); budget = budget - #m[2] * 2
    end
    for i = 1, wantB do
        local m = tg_tc_pick_module(budget)
        if not m then break end
        table.insert(sideB, m); budget = budget - #m[2] * 2
    end
    local first_rest = {}
    for i = 2, #sideA do table.insert(first_rest, sideA[i]) end
    local sideC = tg_tc_shuffle(sideA)
    local sideD = tg_tc_shuffle(sideB)

    local seq, names = {}, {}
    local function add_side(side)
        for _, m in ipairs(side) do
            table.insert(names, m[1])
            for _, step in ipairs(m[2]) do table.insert(seq, step) end
        end
    end
    add_side(sideA); table.insert(seq, { "crn", turn }); table.insert(names, "corner")
    add_side(sideB); table.insert(seq, { "crn", turn }); table.insert(names, "corner")
    add_side(sideC); table.insert(seq, { "crn", turn }); table.insert(names, "corner")
    add_side(sideD); table.insert(seq, { "crn", turn }); table.insert(names, "corner")

    local plans, state = {}, start
    for _, step in ipairs(seq) do
        local p = tg_tp_plan(state, step[1], step[2])
        if not p then return nil, "bad piece " .. tostring(step[1]) end
        table.insert(plans, p)
        state = p.next
    end
    local close_err = tg_tp_dist(state.P, start.P)
    local dir_err = tg_tp_dist(state.D, start.D)
    if close_err > 0.5 or dir_err > 0.01 then return nil, string.format("not closed (%.2f m)", close_err) end
    local ok, why = tg_tc_clear(plans, start.P.z - 1.0, opts.clearance or TG_TUBEP_CLEARANCE or 24.0)
    if not ok then return nil, why end
    return plans, table.concat(names, " > ")
end

-- ---------- lap timer ----------
TG_TUBEC_TIMER = TG_TUBEC_TIMER or { active = false }

function tg_tc_timer_tick()
    local t = TG_TUBEC_TIMER
    if not t.active then util.yield(400); return end
    local now = util.current_time_millis()
    if (now - (t.last_check or 0)) > 1000 then
        t.last_check = now
        local alive = false
        for _, o in ipairs(objects) do if o == t.obj then alive = true; break end end
        if not alive then t.active = false; tg_log("[TUBE_CIRCUIT][TIMER] stopped: course cleared"); return end
    end
    local p = tg_minigame_player_position() or nil
    if not p then util.yield(100); return end
    local rel = tg_tp_sub(tg_tp_v(p.x, p.y, p.z), t.P)
    local s = tg_tp_dot(rel, t.D)
    local lat = tg_tp_len(tg_tp_sub(rel, tg_tp_mul(t.D, s)))
    if t.prev_s and t.prev_s < 0.0 and s >= 0.0 and lat < (TG_TUBEC_GATE_RADIUS or 16.0) and (s - t.prev_s) < 60.0 then
        if not t.lap_start then
            t.lap_start = now
            tg_toast("GO! Lap timer started.", 2000)
        else
            local lap = (now - t.lap_start) / 1000.0
            t.lap_start = now
            t.laps = (t.laps or 0) + 1
            local best_txt = ""
            if not t.best or lap < t.best then t.best = lap; best_txt = "  NEW BEST!" else best_txt = string.format("  (best %.2fs)", t.best) end
            tg_toast(string.format("Lap %d: %.2fs%s", t.laps, lap, best_txt), 4000)
            tg_log(string.format("[TUBE_CIRCUIT][LAP] lap=%d time=%.2f best=%.2f", t.laps, lap, t.best))
        end
    end
    t.prev_s = s
    if tg_tp_len(rel) > 600.0 then util.yield(200) else util.yield(0) end
end

function tg_tc_timer_arm(start, obj)
    TG_TUBEC_TIMER = { active = true, P = start.P, D = start.D, U = start.U, obj = obj, laps = 0 }
    if not TG_TUBEC_TICK_REGISTERED then
        TG_TUBEC_TICK_REGISTERED = true
        util.create_tick_handler(function()
            tg_tc_timer_tick()
            return true
        end)
    end
end


-- ---------- builder ----------
function tg_tube_circuit_build()
    clear_race_track("tube_circuit")
    TG_TUBEP_SEED_BUMP = (TG_TUBEP_SEED_BUMP or 0) + 7919
    if math.randomseed then math.randomseed(((os.time and os.time()) or 1) + TG_TUBEP_SEED_BUMP) end
    local lift = TG_TUBEP_START_LIFT
    TG_TUBEP_START_LIFT = TG_TUBEC_START_LIFT or 20.0
    local start = tg_tp_start_state("tube_circuit")
    TG_TUBEP_START_LIFT = lift

    local plans, info = nil, ""
    for attempt = 1, (TG_TUBEC_ATTEMPTS or 60) do
        plans, info = tg_tc_plan_circuit(start)
        if plans then break end
        if attempt % 10 == 0 then util.yield(0) end
    end
    if not plans then
        tg_toast("Couldn't fit a circuit here (" .. tostring(info) .. "). Try again or move to open space.", 4500)
        tg_warn("TUBE_CIRCUIT", "planning failed: " .. tostring(info))
        return false
    end
    tg_log("[TUBE_CIRCUIT][PLAN] pieces=" .. tostring(#plans) .. " layout=" .. tostring(info))
    local placed = tg_tp_spawn_all(plans, "tube_circuit")
    if tg_rs_check_cancel() then return false end
    local first = nil
    for _, o in ipairs(objects) do first = o; break end
    tg_tc_timer_arm(start, objects[#objects] or first)
    tg_toast("Tube circuit: " .. tostring(placed) .. " pieces. Use 'Go To Start Line' to drop in.", 5000)
    return placed > 0
end

-- v2.0: only check the NEW pieces (index >= new_from) against everything; the rest was already
-- validated. Far-apart pieces are skipped with a bounding-sphere test. Same result, O(new x all).
function tg_tc_clear_new(plans, floor_z, clearance, open, new_from)
    local starts, s_acc = {}, 0.0
    for pi, p in ipairs(plans) do starts[pi] = s_acc; s_acc = s_acc + (p.arc or 0.0) end
    local total = s_acc
    local c2 = clearance * clearance
    local skip = clearance * 2.0
    for pi = new_from, #plans do
        local p = plans[pi]
        local n = #p.samples
        for _, pt in ipairs(p.samples) do if floor_z and pt.z < floor_z then return false, "floor" end end
        for qi = 1, pi do
            local q = plans[qi]
            if qi == pi or not tg_rs_far(p, q, clearance) then
                local m = #q.samples
                for si, a in ipairs(p.samples) do
                    local sa = starts[pi] + (p.arc or 0.0) * ((si - 1) / math.max(1, n - 1))
                    for sj, b in ipairs(q.samples) do
                        if qi < pi or sj > si then
                            local sb = starts[qi] + (q.arc or 0.0) * ((sj - 1) / math.max(1, m - 1))
                            local ds = math.abs(sb - sa)
                            if not open and ds > total - ds then ds = total - ds end
                            if ds > skip then
                                local dx, dy, dz = a.x - b.x, a.y - b.y, a.z - b.z
                                if dx * dx + dy * dy + dz * dz < c2 then return false, "overlap " .. qi .. "/" .. pi end
                            end
                        end
                    end
                end
            end
        end
    end
    return true, "ok"
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.1.5 tube courses: free-form random courses that loop back to the start
-- ═══════════════════════════════════════════════════════════════════════════════════
-- 1) out:   random snapped pieces wander away from the start line (collision + world-obstacle checked).
-- 2) HOME:  pieces are steered back toward a point behind the start line.
-- 3) CLOSE: the last 5-9 pieces are SOLVED. Every joint's roll angle is a free number, so a
--           least-squares solver bends them until the last exit lands exactly on the first
--           entry (<0.25 m, <0.4 deg). Nothing is fudged: every joint is a real snapped joint.
-- 4) BUILD: pieces spawn in order with the Tetris-style spin-and-drop animation.
-- Rule sets ("Tubes: Mixed / Flow / Stunt") pick which pieces the course may use.

TG_TUBECO_MAX_OBJECTS = TG_TUBECO_MAX_OBJECTS or 75      -- lobby object limit (hard cap 75; builders keep 2 spare)
TG_TUBECO_TARGET_MIN = TG_TUBECO_TARGET_MIN or 58
TG_TUBECO_TARGET_MAX = TG_TUBECO_TARGET_MAX or 66        -- leaves room for the animation piece
TG_TUBECO_MAX_RADIUS = TG_TUBECO_MAX_RADIUS or 700.0     -- how far from the start a course may roam
TG_TUBECO_MAX_RISE = TG_TUBECO_MAX_RISE or 320.0
TG_TUBECO_START_LIFT = TG_TUBECO_START_LIFT or 16.0
TG_TUBECO_TUBE_RADIUS = TG_TUBECO_TUBE_RADIUS or 7.5     -- used for world-obstacle probes
TG_TUBECO_ATTEMPTS = TG_TUBECO_ATTEMPTS or 10
TG_TUBECO_ANIMATE = (TG_TUBECO_ANIMATE ~= false)
TG_TUBECO_ANIM_LIFT = TG_TUBECO_ANIM_LIFT or 18.0
TG_TUBECO_RULES = TG_TUBECO_RULES or "mixed"

-- Rule sets: { steps, weight }. A roll of "any" = random multiple of 45 deg; "free" = any angle.
TG_TUBECO_RULESETS = TG_TUBECO_RULESETS or {
    mixed = {
        name = "Tubes: Mixed",
        menu = {
            { { { "s", 0 } }, 3 }, { { { "xs", 0 } }, 2 }, { { { "m", 0 } }, 1 },
            { { { "gap", 0 } }, 0.7 },
            { { { "c30", "side" } }, 3 }, { { { "c15", "side" } }, 1.5 }, { { { "c30", "vert" } }, 1.4 },
            { { { "crn2", "any" } }, 2 }, { { { "crn", "side" } }, 1.5 }, { { { "crn", "any" } }, 1 },
            { { { "s", 0 }, { "crn", 90 }, { "crn", 90 }, { "crn2", 0 }, { "crn2", 180 }, { "crn", 90 }, { "crn", 90 } }, 0.8, "loop" }
        },
        close = { "crn2", "c30", "crn", "c15" }
    },
    flow = {
        name = "Tubes: Flow",
        menu = {
            { { { "s", 0 } }, 3 }, { { { "m", 0 } }, 1.5 }, { { { "xs", 0 } }, 1 },
            { { { "c30", "side" } }, 4 }, { { { "c15", "side" } }, 3 }, { { { "c15", "vert" } }, 1.5 },
            { { { "crn2", "side" } }, 1 }
        },
        close = { "c30", "crn2", "crn2", "crn" }
    },
    stunt = {
        name = "Tubes: Stunt",
        menu = {
            { { { "xs", 0 } }, 1.5 }, { { { "s", 0 } }, 1 },
            { { { "gap", 0 } }, 1 },
            { { { "crn", "free" } }, 3 }, { { { "crn2", "free" } }, 3 }, { { { "c30", "free" } }, 1.5 },
            { { { "s", 0 }, { "crn", 90 }, { "crn", 90 }, { "crn2", 0 }, { "crn2", 180 }, { "crn", 90 }, { "crn", 90 } }, 1.2, "loop" }
        },
        close = { "crn", "crn2", "c30" }
    }
}

-- World-referenced steering for race types: "wside" = a truly level turn, "wvert" = a climb or
-- dive chosen to pull the tube back toward level and toward a comfortable height (hills, not
-- runaway climbs), "wdiag" = both at once.
TG_TCO_CTX = TG_TCO_CTX or nil
function tg_tco_world_frame(state)
    local D = tg_tp_norm(state.D)
    local Zw = tg_tp_v(0.0, 0.0, 1.0)
    local leftW = tg_tp_cross(Zw, D)
    if tg_tp_len(leftW) < 0.15 then leftW = tg_tp_cross(state.U, D) end
    leftW = tg_tp_norm(leftW)
    local upW = tg_tp_norm(tg_tp_cross(D, leftW))
    return D, leftW, upW
end
function tg_tco_vertical_sign(state)
    local pitch = math.deg(math.asin(math.max(-1.0, math.min(1.0, state.D.z))))
    if pitch > 12.0 then return -1.0 end
    if pitch < -12.0 then return 1.0 end
    local ctx = TG_TCO_CTX
    local up_chance = 0.5
    if ctx and ctx.floor_z and ctx.ceil_z then
        local h = (state.P.z - ctx.floor_z) / math.max(1.0, ctx.ceil_z - ctx.floor_z)
        up_chance = 0.75 - h * 1.1
        if up_chance < 0.1 then up_chance = 0.1 elseif up_chance > 0.9 then up_chance = 0.9 end
    end
    return (math.random() < up_chance) and 1.0 or -1.0
end
function tg_tco_roll(spec)
    if type(spec) == "number" then return spec end
    if spec == "wside" then
        local sgn = (math.random() < 0.5) and 1.0 or -1.0
        return function(state)
            local _, l = tg_tco_world_frame(state)
            -- far from home: level turns bend back toward home instead of a coin flip
            local ctx = TG_TCO_CTX
            if ctx and ctx.home_P and ctx.max_radius then
                local to = tg_tp_sub(ctx.home_P, state.P)
                to.z = 0.0
                if tg_tp_len(to) > ctx.max_radius * 0.4 then
                    sgn = (tg_tp_dot(to, l) >= 0.0) and 1.0 or -1.0
                end
            end
            return tg_tp_mul(l, sgn)
        end
    end
    if spec == "wvert" then
        return function(state) local _, _, u = tg_tco_world_frame(state); return tg_tp_mul(u, tg_tco_vertical_sign(state)) end
    end
    if spec == "wdiag" then
        local sgn = (math.random() < 0.5) and 1.0 or -1.0
        return function(state)
            local _, l, u = tg_tco_world_frame(state)
            return tg_tp_add(tg_tp_mul(l, sgn), tg_tp_mul(u, tg_tco_vertical_sign(state)))
        end
    end
    if spec == "side" then return (math.random() < 0.5) and TG_TUBEP_LEFT or TG_TUBEP_RIGHT end
    if spec == "vert" then return (math.random() < 0.5) and TG_TUBEP_UP or TG_TUBEP_DOWN end
    if spec == "any" then return 45 * math.random(0, 7) end
    if spec == "free" then return math.random() * 360.0 end
    if spec == "diag" then return 45 + 90 * math.random(0, 3) end
    return 0
end

-- ---------- world obstacle probes along a tube ----------
function tg_tco_world_blocked(plan, ctx)
    if TG_WORLD_OBSTACLE_AVOIDANCE == false then return false end
    local s = plan.samples
    if not s or #s < 2 then return false end
    -- v2.0: only the buried mouth section near the ground is exempt (used to be a 130 m bubble around
    -- the entrance and exit at ANY height - that's how tubes ended up inside buildings near the start)
    local function exempt(q)
        if not (ctx and ctx.noprobe) then return false end
        for _, z in ipairs(ctx.noprobe) do
            if tg_tp_dist(q, z.P) < z.r and (not z.zmax or q.z < z.zmax) then return true end
        end
        return false
    end
    -- v2.0.3: height map check first (works far from the player where collision isn't loaded)
    local tr = (ctx and ctx.tube_radius) or TG_TUBECO_TUBE_RADIUS or 7.5
    -- v2.0.4: Standard tubes only (ctx.heightmap), and a little looser: the lower part of the tube may
    -- clip the edge of a building; the centre line and upper half must be clear
    if tg_rs_below_world and ctx and ctx.heightmap then
        for _, q in ipairs(s) do
            if exempt(q) then
                if tg_rs_below_world(q, 0.0, -2.0) then return true end
            elseif tg_rs_below_world(q, tr * 0.35, 0.0) then return true end
        end
    end
    if not tg_world_obstacle_line_probe then return false end
    local r = tr + (tonumber(TG_WORLD_OBSTACLE_MARGIN or 2.5) or 2.5)
    local B = plan.R and plan.R.Y or tg_tp_v(0, 1, 0)
    local Z = plan.R and plan.R.Z or tg_tp_v(0, 0, 1)
    local d = r * 0.7071
    local offsets = { tg_tp_v(0, 0, 0), tg_tp_mul(B, r), tg_tp_mul(B, -r), tg_tp_mul(Z, r), tg_tp_mul(Z, -r),
        tg_tp_add(tg_tp_mul(B, d), tg_tp_mul(Z, d)), tg_tp_add(tg_tp_mul(B, -d), tg_tp_mul(Z, d)),
        tg_tp_add(tg_tp_mul(B, d), tg_tp_mul(Z, -d)), tg_tp_add(tg_tp_mul(B, -d), tg_tp_mul(Z, -d)) }
    local step = math.max(1, math.floor(#s / 4))
    local i = 1
    while i < #s do
        local j = math.min(#s, i + step)
        if not (exempt(s[i]) and exempt(s[j])) then
            for _, o in ipairs(offsets) do
                local a, b = tg_tp_add(s[i], o), tg_tp_add(s[j], o)
                local hit, _, ent, status = tg_world_obstacle_line_probe(a.x, a.y, a.z, b.x, b.y, b.z, 0, "tube_course")
                if status == "unavailable" or status == "probe_error" then return false end
                if hit and not (tg_world_obstacle_is_own_entity(ent)) then return true end
            end
        end
        i = j
    end
    return false
end

-- ---------- closing solver ----------
function tg_tco_solve_eval(state, keys, rolls)
    local s = state
    local ri = 0
    for _, k in ipairs(keys) do
        local roll = 0
        if TG_TUBEP_PIECES[k].kind == "bend" then ri = ri + 1; roll = rolls[ri] end
        s = tg_tp_plan(s, k, roll, true).next
    end
    return s
end

function tg_tco_residual(s, target)
    local W = 80.0
    return { s.P.x - target.P.x, s.P.y - target.P.y, s.P.z - target.P.z,
             W * (s.D.x - target.D.x), W * (s.D.y - target.D.y), W * (s.D.z - target.D.z) }
end

function tg_tco_sumsq(r) local t = 0.0 for _, v in ipairs(r) do t = t + v * v end return t end

-- Solve (A) x = b, small dense system, Gaussian elimination with partial pivoting.
function tg_tco_linsolve(A, b)
    local n = #b
    local M = {}
    for i = 1, n do M[i] = {} for j = 1, n do M[i][j] = A[i][j] end M[i][n + 1] = b[i] end
    for c = 1, n do
        local p = c
        for r = c + 1, n do if math.abs(M[r][c]) > math.abs(M[p][c]) then p = r end end
        if math.abs(M[p][c]) < 1e-12 then return nil end
        M[c], M[p] = M[p], M[c]
        for r = c + 1, n do
            local f = M[r][c] / M[c][c]
            for k = c, n + 1 do M[r][k] = M[r][k] - f * M[c][k] end
        end
    end
    local x = {}
    for i = n, 1, -1 do
        local s = M[i][n + 1]
        for k = i + 1, n do s = s - M[i][k] * x[k] end
        x[i] = s / M[i][i]
    end
    return x
end

-- Levenberg-Marquardt over the bend rolls of a connector template.
function tg_tco_solve(state, target, keys, init, iters)
    local x = {}
    for i, v in ipairs(init) do x[i] = v end
    local n = #x
    local r = tg_tco_residual(tg_tco_solve_eval(state, keys, x), target)
    local cost = tg_tco_sumsq(r)
    local lambda = 1e-2
    for it = 1, (iters or 40) do
        if cost < 0.02 then break end
        -- hopeless starts rarely recover; give the next template a turn instead
        if (it == 8 and cost > 2500.0) or (it == 18 and cost > 60.0) then break end
        local J = {}
        for j = 1, n do
            local xs = {}
            for i, v in ipairs(x) do xs[i] = v end
            xs[j] = xs[j] + 0.25
            local rj = tg_tco_residual(tg_tco_solve_eval(state, keys, xs), target)
            for i = 1, #r do J[i] = J[i] or {}; J[i][j] = (rj[i] - r[i]) / 0.25 end
        end
        local A, g = {}, {}
        for a = 1, n do
            A[a] = {}
            g[a] = 0.0
            for i = 1, #r do g[a] = g[a] + J[i][a] * r[i] end
            for b = 1, n do
                local s = 0.0
                for i = 1, #r do s = s + J[i][a] * J[i][b] end
                A[a][b] = s
            end
        end
        local improved = false
        for _ = 1, 6 do
            local Al = {}
            for a = 1, n do Al[a] = {} for b = 1, n do Al[a][b] = A[a][b] end Al[a][a] = A[a][a] * (1.0 + lambda) + 1e-6 end
            local negg = {}
            for a = 1, n do negg[a] = -g[a] end
            local d = tg_tco_linsolve(Al, negg)
            if d then
                local xn = {}
                for i = 1, n do
                    local step = d[i]
                    if step > 60 then step = 60 elseif step < -60 then step = -60 end
                    xn[i] = x[i] + step
                end
                local rn = tg_tco_residual(tg_tco_solve_eval(state, keys, xn), target)
                local cn = tg_tco_sumsq(rn)
                if cn < cost then x, r, cost = xn, rn, cn; lambda = lambda * 0.3; improved = true; break end
            end
            lambda = lambda * 5.0
        end
        if not improved then break end
    end
    return x, cost
end

function tg_tco_random_template(close_keys, straights)
    local keys = {}
    local nb = math.random(5, 7)
    for i = 1, nb do table.insert(keys, close_keys[math.random(#close_keys)]) end
    local ns = math.random(0, 2)
    straights = straights or { "xxs", "xs", "s", "s", "m" }
    for i = 1, ns do table.insert(keys, math.random(1, #keys + 1), straights[math.random(#straights)]) end
    return keys
end

-- Try to close from `state` to `target`. Returns list of plans or nil.
function tg_tco_try_close(state, target, placed, ctx, close_keys, tries, close_straights)
    local dist = tg_tp_dist(state.P, target.P)
    local slack = 250.0 * ((ctx and ctx.scale) or 1.0)
    for t = 1, (tries or 30) do
        local keys = tg_tco_random_template(close_keys, close_straights)
        local reach = 0.0
        for _, k in ipairs(keys) do
            local pc = TG_TUBEP_PIECES[k]
            reach = reach + ((pc.kind == "straight") and pc.len or pc.r * math.rad(pc.angle))
        end
        if reach > dist * 1.05 and reach < dist * 3.0 + slack then
            local nb = 0
            for _, k in ipairs(keys) do if TG_TUBEP_PIECES[k].kind == "bend" then nb = nb + 1 end end
            for init_try = 1, 3 do
                local init = {}
                for i = 1, nb do init[i] = math.random() * 360.0 end
                local x, cost = tg_tco_solve(state, target, keys, init, 45)
                if cost < 0.06 then
                    local plans, s, ri = {}, state, 0
                    for _, k in ipairs(keys) do
                        local roll = 0
                        if TG_TUBEP_PIECES[k].kind == "bend" then ri = ri + 1; roll = x[ri] % 360.0 end
                        local p = tg_tp_plan(s, k, roll)
                        table.insert(plans, p)
                        s = p.next
                    end
                    local all = {}
                    for _, p in ipairs(placed) do table.insert(all, p) end
                    for _, p in ipairs(plans) do table.insert(all, p) end
                    local ok = tg_tc_clear(all, ctx.floor_z, ctx.clearance, ctx.open, #placed + 1)
                    if ok and ctx.ceil_z then
                        for _, p in ipairs(plans) do for _, q in ipairs(p.samples) do if q.z > ctx.ceil_z then ok = false end end end
                    end
                    if ok and ctx.world then
                        for _, p in ipairs(plans) do if tg_tco_world_blocked(p, ctx) then ok = false; break end end
                    end
                    if ok then return plans, keys end
                end
            end
        end
        if t % 2 == 0 then util.yield(0); if tg_rs_check_cancel() then return nil end end
    end
    return nil
end

-- ---------- planner ----------
-- opts (all optional): lead = {{key,roll},...} start pieces, home = closing target state,
-- approach = distance of the homing point behind `home`, min/max = piece targets,
-- max_objects = total piece budget, max_radius = roaming limit.
function tg_tco_plan_course(start, rules, ctx, opts)
    opts = opts or {}
    TG_TCO_CTX = ctx
    local TT = rules.tt
    ctx.tt = TT
    if TT and tg_tt_tube_begin then tg_tt_tube_begin(TT, ctx, opts, start) end
    local scale = ctx.scale or 1.0
    local plans = {}
    local function add_step(state, step)
        local p = tg_tp_plan(state, step[1], tg_tco_roll(step[2]))
        return p
    end
    -- start line: boost pair
    local state = start
    for _, step in ipairs(opts.lead or { { "xs", 0 } }) do
        local p = tg_tp_plan(state, step[1], tg_tco_roll(step[2]))
        table.insert(plans, p)
        state = p.next
    end
    local lead_count = #plans
    local home = opts.home or { P = start.P, D = start.D, U = start.U }
    local max_objects = opts.max_objects or ((TG_TUBECO_MAX_OBJECTS or 70) - 2)
    local max_radius = opts.max_radius or TG_TUBECO_MAX_RADIUS or 700.0
    -- the corridor behind the finish must stay free for the closing pieces to arrive
    local corridor = { samples = {}, arc = 0.0 }
    for d = 60, 220, 10 do table.insert(corridor.samples, tg_tp_sub(home.P, tg_tp_mul(home.D, d * scale))) end

    local target_count = math.random(opts.min or TG_TUBECO_TARGET_MIN or 50, opts.max or TG_TUBECO_TARGET_MAX or 66)
    local approach = tg_tp_sub(home.P, tg_tp_mul(home.D, (opts.approach or 200.0) * scale))
    ctx.home_P = home.P
    ctx.max_radius = max_radius
    local reserve = 10
    local fails = 0

    local function fits(cand, with_corridor)
        for _, p in ipairs(cand) do
            local list = {}
            if with_corridor then table.insert(list, corridor) end
            for _, q in ipairs(plans) do table.insert(list, q) end
            for i = 1, #cand do if cand[i] == p then break end table.insert(list, cand[i]) end
            if not tg_tp_fits(p, list, ctx) then return false end
            local far = tg_tp_dist(tg_tp_v(p.next.P.x, p.next.P.y, start.P.z), start.P)
            if far > max_radius then return false end
            -- v2.3.0 user radius: every sample of the piece inside the circle round the player
            if ctx.user_r and ctx.rc then
                local lim = ctx.user_r - (ctx.tube_radius or 7.5)
                for _, q in ipairs(p.samples or {}) do
                    local dx, dy = q.x - ctx.rc.x, q.y - ctx.rc.y
                    if dx * dx + dy * dy > lim * lim then return false end
                end
            end
        end
        if ctx.world then
            for _, p in ipairs(cand) do if tg_tco_world_blocked(p, ctx) then return false end end
        end
        return true
    end

    local function build_candidate(entry)
        local cand, s = {}, plans[#plans].next
        for _, step in ipairs(entry[1]) do
            local p = add_step(s, step)
            if not p then return nil end
            table.insert(cand, p)
            s = p.next
        end
        return cand
    end

    -- OUT + HOME phases
    local loops_done = 0
    local fail_cap = 25 + math.floor(target_count / 4)
    while #plans < target_count - reserve do
        loops_done = loops_done + 1
        if tg_rs_check_cancel() then return nil, "cancelled" end
        if opts.progress and loops_done % 2 == 0 then opts.progress(#plans, target_count) end
        local homing = #plans > (target_count - reserve) * 0.55
        local options = {}
        for i = 1, 10 do
            local entry = nil
            local total = 0.0
            for _, e in ipairs(rules.menu) do total = total + e[2] end
            local r = math.random() * total
            for _, e in ipairs(rules.menu) do r = r - e[2]; if r <= 0 then entry = e; break end end
            entry = entry or rules.menu[1]
            if TT and tg_tt_tube_allow and not tg_tt_tube_allow(TT, entry, plans) then entry = nil end
            if entry and #plans + #entry[1] <= target_count - reserve + 2 then
                local cand = build_candidate(entry)
                if cand then
                    -- leash: past half the roaming radius, prefer pieces that turn back toward the start
                    local endP = cand[#cand].next.P
                    local far = tg_tp_dist(tg_tp_v(endP.x, endP.y, start.P.z), start.P)
                    local score = math.random() * 100.0 * (TT and TT.rk or 1.0) + math.max(0.0, far - max_radius * 0.5) * 1.5
                    if far > max_radius * 0.45 then
                        -- far out and pointing away: any piece that turns the nose back toward home wins
                        local cur = plans[#plans].next
                        local function home_cos(P, D)
                            local to = tg_tp_sub(home.P, P); to.z = 0.0
                            local hd = tg_tp_v(D.x, D.y, 0.0)
                            if tg_tp_len(to) < 1.0 or tg_tp_len(hd) < 0.01 then return 1.0 end
                            return tg_tp_dot(tg_tp_norm(to), tg_tp_norm(hd))
                        end
                        local c_now = home_cos(cur.P, cur.D)
                        local c_end = home_cos(endP, cand[#cand].next.D)
                        if c_now < 0.7 then
                            if c_end > c_now + 0.02 then score = score - 1000.0 + (1.0 - c_end) * 50.0 else score = score + 300.0 end
                        end
                    end
                    -- comfort: avoid ending steep or hugging the floor/ceiling (gentle pieces can't recover fast)
                    local endD = cand[#cand].next.D
                    local pitch = math.abs(math.deg(math.asin(math.max(-1.0, math.min(1.0, endD.z)))))
                    score = score + math.max(0.0, pitch - (TT and TT.pitch_ok or 15.0)) * 6.0 * (TT and TT.pitch_k or 1.0)
                    if ctx.ceil_z then score = score + math.max(0.0, endP.z - (ctx.ceil_z - 80.0 * scale)) * 3.0 end
                    if ctx.floor_z then score = score + math.max(0.0, (ctx.floor_z + 25.0 * scale) - endP.z) * 2.0 end
                    if homing then
                        local endP = cand[#cand].next.P
                        score = tg_tp_dist(endP, approach) + math.random() * 60.0
                    end
                    local meta = nil
                    if TT and tg_tt_tube_score then score, meta = tg_tt_tube_score(TT, entry, cand, plans, ctx, score, homing) end
                    if score then table.insert(options, { cand = cand, score = score, meta = meta }) end
                end
            end
        end
        table.sort(options, function(a, b) return a.score < b.score end)
        local took = false
        for _, o in ipairs(options) do
            if fits(o.cand, true) then
                if o.meta then o.cand[1].tt_meta = o.meta end
                for _, p in ipairs(o.cand) do table.insert(plans, p) end
                took = true
                break
            end
        end
        if not took then
            fails = fails + 1
            if fails > fail_cap or #plans <= lead_count then
                local lp = plans[#plans].next
                tg_log(string.format("[TUBE_COURSE][DEADEND] pieces=%d options=%d fails=%d last=(%.0f,%.0f,%.0f) pitch=%.1f", #plans, #options, fails,
                    lp.P.x - start.P.x, lp.P.y - start.P.y, lp.P.z - start.P.z, math.deg(math.asin(math.max(-1, math.min(1, lp.D.z))))))
                return nil, "dead end"
            end
            -- back up a couple of pieces and try something else
            for _ = 1, math.min(2, #plans - lead_count) do table.remove(plans) end
        end
        if loops_done % 4 == 0 then util.yield(0) end
    end

    -- CLOSE phase: keep homing one piece at a time until the solver connects
    for extra = 0, 10 do
        local state_now = plans[#plans].next
        if #plans + 5 <= max_objects then
            local closing = tg_tco_try_close(state_now, home, plans, ctx, rules.close, 30, rules.close_straights)
            if closing and #plans + #closing <= max_objects then
                for _, p in ipairs(closing) do table.insert(plans, p) end
                return plans, "closed"
            end
        end
        -- step closer to the approach point and retry
        local best = nil
        for i = 1, ((ctx.scale or 1.0) > 3.0 and 36 or 12) do
            local e = rules.menu[math.random(#rules.menu)]
            if #e[1] == 1 then
                local cand = build_candidate(e)
                if cand and fits(cand, true) then
                    local d = tg_tp_dist(cand[1].next.P, approach)
                    if not best or d < best.d then best = { cand = cand, d = d } end
                end
            end
        end
        if not best then return nil, "cannot approach" end
        table.insert(plans, best.cand[1])
        if #plans >= max_objects - 5 then break end
    end
    return nil, "could not close"
end

-- ---------- animated spawn ----------
function tg_tco_spawn_animated(plan, label)
    if not TG_TUBECO_ANIMATE then return tg_tp_spawn(plan, label) end
    local lift = TG_TUBECO_ANIM_LIFT or 18.0
    local o = plan.origin
    local spins = { -270, -180, -135, -90, 90, 135, 180, 270 }
    local spin = spins[math.random(#spins)]
    local yaw0 = tg_normalize_heading(plan.yaw + spin)
    local obj = tg_try_create_stunt_tube_model(plan.model, o.x, o.y, o.z + lift, yaw0, label)
    if not obj then return nil end
    local frames = math.max(1, tonumber(TG_TETRIS_SPIN_FRAMES or 6) or 6)
    local step_ms = tonumber(TG_TETRIS_STEP_MS or 45) or 45
    local delta = (plan.yaw - yaw0 + 540.0) % 360.0 - 180.0
    if spin > 180 or spin < -180 then delta = delta + ((spin > 0) and -360 or 360) end
    for i = 1, frames do
        if TG_CANCEL_GENERATION then break end
        local t = i / frames
        local eased = 1.0 - (1.0 - t) * (1.0 - t)
        local yaw = tg_normalize_heading(yaw0 + delta * eased)
        local z = o.z + lift * (1.0 - eased)
        ENTITY.SET_ENTITY_COORDS_NO_OFFSET(obj, o.x, o.y, z + (tonumber(TG_TRACK_HEIGHT_OFFSET or 0.0) or 0.0), false, false, false)
        tg_tube3d_apply_rotation(obj, plan.pitch, plan.rollY, yaw, label)
        util.yield(step_ms)
    end
    ENTITY.SET_ENTITY_COORDS_NO_OFFSET(obj, o.x, o.y, o.z + (tonumber(TG_TRACK_HEIGHT_OFFSET or 0.0) or 0.0), false, false, false)
    tg_tube3d_apply_rotation(obj, plan.pitch, plan.rollY, plan.yaw, label)
    local meta = tg_get_meta(obj) or {}
    meta.tube3d = true
    meta.tube_piece = plan.key
    meta.x, meta.y, meta.z = o.x, o.y, o.z
    meta.pitch, meta.roll, meta.heading = plan.pitch, plan.rollY, plan.yaw
    tg_set_meta(obj, meta)
    if plan.tint and tg_pk_tint then tg_pk_tint(obj, plan.tint) end
    if tg_tn_harden then
        tg_tn_harden(obj, { x = o.x, y = o.y, z = o.z + (tonumber(TG_TRACK_HEIGHT_OFFSET or 0.0) or 0.0),
            pitch = plan.pitch, roll = plan.rollY, yaw = plan.yaw, model = plan.model })
    end
    return obj
end

-- ---------- entry point ----------
function tg_tube_course_build(rules_key)
    rules_key = rules_key or TG_TUBECO_RULES or "mixed"
    local rules = TG_TUBECO_RULESETS[rules_key] or TG_TUBECO_RULESETS.mixed
    tg_rs_build_start("Tube Course")
    clear_race_track("tube_course")
    TG_TUBEP_SEED_BUMP = (TG_TUBEP_SEED_BUMP or 0) + 7919
    if math.randomseed then math.randomseed(((os.time and os.time()) or 1) + TG_TUBEP_SEED_BUMP) end
    local lift = TG_TUBEP_START_LIFT
    TG_TUBEP_START_LIFT = TG_TUBECO_START_LIFT or 16.0
    local start = tg_tp_start_state("tube_course")
    TG_TUBEP_START_LIFT = lift
    TG_RS_NEAR = { P = { x = start.P.x, y = start.P.y }, r = 220.0 }
    local ctx = {
        floor_z = start.P.z - 1.0,
        ceil_z = start.P.z + (TG_TUBECO_MAX_RISE or 320.0),
        clearance = TG_TUBEP_CLEARANCE or 24.0,
        world = (TG_WORLD_OBSTACLE_AVOIDANCE ~= false), heightmap = true
    }
    tg_toast("Planning " .. rules.name .. " course...", 2500)
    local plans, why = nil, ""
    local attempts = (TG_TUBECO_ATTEMPTS or 10)
    for attempt = 1, attempts do
        if tg_rs_check_cancel() then return false end
        TG_WORLD_OBSTACLE_PROBE_CACHE = {}
        plans, why = tg_tco_plan_course(start, rules, ctx, { progress = function(n, t) tg_rs_plan_progress("Tube Course", attempt, attempts, n, t) end })
        tg_log("[TUBE_COURSE][ATTEMPT] " .. tostring(attempt) .. " result=" .. tostring(why) .. " pieces=" .. tostring(plans and #plans or 0))
        if plans then break end
        util.yield(0)
    end
    if tg_rs_check_cancel() then return false end
    if not plans then
        tg_toast("Couldn't close a course here (" .. tostring(why) .. "). Try again or move to open space.", 4500)
        tg_rs_progress_fail("Couldn't fit a course here - move to open space")
        return false
    end

    tg_rs_preload("Tube Course", plans)
    local token = tg_generation_start("tube_course") or nil
    local placed = 0
    local missed = {}
    for i, plan in ipairs(plans) do
        if tg_generation_should_stop(token, "tube_course") then break end
        if tg_rs_spawn_progress("Tube Course", i, #plans, "Spawning tube") then return false end
        util.yield(TG_TUBEP_DELAY_MS or 70)
        if tg_tco_spawn_animated(plan, "tube_course_" .. tostring(i)) then placed = placed + 1 else table.insert(missed, plan) end
    end
    placed = placed + tg_rs_repair("Tube Course", missed, function(plan, k) return tg_tp_spawn(plan, "tube_course_fix_" .. tostring(k)) end)
    if tg_rs_check_cancel() then return false end
    tg_log("[TUBE_COURSE][DONE] rules=" .. rules_key .. " placed=" .. tostring(placed) .. "/" .. tostring(#plans))
    tg_tn_settle_all("tube course")
    tg_report_state("tube_course_done")
    tg_tc_timer_arm(start, objects[#objects])
    tg_toast(rules.name .. ": " .. tostring(placed) .. " pieces, loops back to the start. 'Go To Start Line' to race.", 5000)
    tg_rs_progress_done(string.format("%d / %d pieces placed", placed, #plans))
    return placed > 0
end

function tg_tube_course_toggle_animation()
    TG_TUBECO_ANIMATE = not TG_TUBECO_ANIMATE
    tg_toast("Tube course build animation: " .. (TG_TUBECO_ANIMATE and "ON" or "OFF (instant)"), 2500)
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.1.8 tube races: course styles x tube sizes x piece sets, drive-in from the ground
-- ═══════════════════════════════════════════════════════════════════════════════════
-- * families (all measured from 129 official rockstar races, snapped joints, ~0.1-0.2 m fit):
--     std   = stt_prop_stunt_tube_*          (bend scale 1.0)
--     big   = ar_prop_ar_tube_*     (Arena)   (bends 2.7479x std, straights fitted)
--     giant = ar_prop_ar_tube_2x_*  (Arena 2x)(bends 5.5062x std, only the 90 deg corner exists)
-- * Race types copy the TUBE MIX of each official race category: which pieces Rockstar used
--   and how often their bends turn flat / vertical / diagonal.
-- * Drive-in: the first tube starts half-buried at ground level and climbs 8 degrees, so you
--   drive straight in off the ground. The course finishes at a second half-buried mouth beside
--   the entrance facing back toward you: drive out, turn around, go again. No end caps are ever used.

TG_TUBER_GROUND_ENTRY = (TG_TUBER_GROUND_ENTRY ~= false)
TG_TUBER_ENTRY_DIST = TG_TUBER_ENTRY_DIST or 40.0       -- mouth distance in front of you
TG_TUBER_ENTRY_PITCH = TG_TUBER_ENTRY_PITCH or 8.0      -- climb angle out of the ground
TG_TUBER_ENTRY_SINK = TG_TUBER_ENTRY_SINK or 0.5      -- tube FLOOR sits this far below ground (x tube size) so you drive straight in
