-- ---------- bigger families ----------
-- Bend scales and straight lengths were fitted from official joints. Bends marked (pred) exist in the game but
-- were not used in the races; they are predicted from the family's measured bend scale (all measured bends in
-- every family scale exactly with it).
TG_TUBER_FAMILIES = TG_TUBER_FAMILIES or {
    std = { name = "Standard", prefix = "", scale = 1.0 },
    big = {
        name = "Arena", prefix = "big_", scale = 2.7479, model = "ar_prop_ar_tube_",
        straights = { xxs = 46.82, xs = 134.31, s = 221.71, m = 440.77, l = 659.1, hg = 90.4 },
        bends = { crn = "crn", crn2 = "crn2", c30 = "crn_30d", c15 = "crn_15d", c5 = "crn_5d" }
    },
    giant = {
        name = "Arena 2x", prefix = "giant_", scale = 5.5062, model = "ar_prop_ar_tube_2x_",
        straights = { xxs = 93.53, xs = 134.18, s = 221.67, m = 440.49, l = 659.06 },
        -- v2.0.5: only the MEASURED 90-degree corner. The 45/30/15/5 degree 2x corners were predicted
        -- from the scale (never seen in an official race) and left visible gaps at their joints.
        bends = { crn = "crn" }
    },
    mega = {
        name = "Arena 4x", prefix = "mega_", scale = 11.0128, model = "ar_prop_ar_tube_4x_",
        straights = { xs = 134.2, s = 223.8, l = 659.04 },
        -- v2.0.5: measured pieces only (the predicted 4x m / 45 / 30 / 15 / 5 degree pieces left gaps)
        bends = { crn = "crn" }
    }
}

function tg_tr_register_families()
    for _, fam in pairs(TG_TUBER_FAMILIES) do
        if fam.model then
            for key, len in pairs(fam.straights or {}) do
                TG_TUBEP_PIECES[fam.prefix .. key] = { model = fam.model .. key, kind = "straight", len = len }
            end
            for key, suffix in pairs(fam.bends or {}) do
                local base = TG_TUBEP_PIECES[key]
                if base then
                    TG_TUBEP_PIECES[fam.prefix .. key] = {
                        model = fam.model .. suffix, kind = "bend", angle = base.angle,
                        r = base.r * fam.scale,
                        a = { base.a[1] * fam.scale, base.a[2] * fam.scale, 0.0 }
                    }
                end
            end
        end
    end
end
tg_tr_register_families()

