-- allowed = set of base piece keys this build may use (nil = all); loops = include loop-the-loops
function tg_tr_build_rules(rt, fam_key, allowed, loops, modset)
    local fam = TG_TUBER_FAMILIES[fam_key or rt.family] or TG_TUBER_FAMILIES.std
    local pre = fam.prefix or ""
    local menu, close, close_straights = {}, {}, {}
    local mix = rt.mix or { 60, 25, 15 }
    local counts = {}
    for key, count in pairs(rt.counts) do counts[key] = count end
    -- every default piece is always available (a little weight even if the style never used it)
    for key in pairs(TG_TUBER_DEFAULT_KEYS) do if not counts[key] then counts[key] = 3 end end
    if allowed then
        for key in pairs(allowed) do if not counts[key] then counts[key] = 6 end end
    end
    for key, count in pairs(counts) do
        local k = pre .. key
        local pc = TG_TUBEP_PIECES[k]
        if pc and (not allowed or allowed[key]) and not TG_TUBEP_BANNED[pc.model] then
            if pc.kind == "straight" then
                table.insert(menu, { { { k, 0 } }, count })
                if TG_TUBER_DEFAULT_KEYS[key] then table.insert(close_straights, k) end
            else
                if mix[1] > 0 then table.insert(menu, { { { k, "wside" } }, count * mix[1] / 100 }) end
                if mix[2] > 0 then table.insert(menu, { { { k, "wvert" } }, count * mix[2] / 100 }) end
                if mix[3] > 0 then table.insert(menu, { { { k, "wdiag" } }, count * mix[3] / 100 }) end
                if key == "crn" or key == "crn2" or key == "c30" then table.insert(close, k) end
            end
        end
    end
    if loops == nil then loops = (rt.loop or 0) > 0 end
    if loops and TG_TUBEP_PIECES[pre .. "crn2"] then
        table.insert(menu, { { { pre .. "s", 0 }, { pre .. "crn", 90 }, { pre .. "crn", 90 }, { pre .. "crn2", 0 }, { pre .. "crn2", 180 }, { pre .. "crn", 90 }, { pre .. "crn", 90 } }, math.max(rt.loop or 0, 12), "loop" })
    end
    -- v1.4.0: tube modules (style favourites + the piece types picked in the Tubes tab)
    local want = {}
    if rt.mods == "all" then for _, id in ipairs(TG_TUBE_PIECE_TYPES or {}) do want[id] = 5 end
    elseif type(rt.mods) == "table" then for id, w in pairs(rt.mods) do want[id] = w end end
    for id, w in pairs(modset or {}) do want[id] = math.max(want[id] or 0, (w == true) and 8 or w) end
    local allowed_flags = allowed and {} or nil
    if allowed then
        for k in pairs(allowed) do allowed_flags[k] = true end
        if allowed.gap or allowed.jmp then allowed_flags.__gapjump = true end
        if allowed.fn1 or allowed.fn2 then allowed_flags.__fn = true end
    end
    for id, w in pairs(want) do
        local mod = TG_TUBE_MODULE_BY_ID and TG_TUBE_MODULE_BY_ID[id]
        if mod and w > 0 then
            local a = tg_tm_template(mod, pre, allowed_flags, false)
            local b = tg_tm_template(mod, pre, allowed_flags, true)
            if a then table.insert(menu, { a, w * 0.5, id }) end
            if b then table.insert(menu, { b, w * 0.5, id .. "_m" }) end
        end
    end
    -- closing pieces only need to be bendy; keep a 45 deg corner available where the family has one
    if TG_TUBEP_PIECES[pre .. "crn2"] then table.insert(close, pre .. "crn2") end
    if TG_TUBEP_PIECES[pre .. "crn"] then table.insert(close, pre .. "crn") end
    if #close == 0 then close = { pre .. "crn" } end
    if #close_straights == 0 then close_straights = { pre .. "s" } end
    return { name = rt.name, menu = menu, close = close, close_straights = close_straights }
end

-- ---------- ground helpers ----------
function tg_tr_ground_z(x, y, zhint)
    return tg_ground_z(x, y) or zhint
end

-- ---------- timer: start gate + optional finish gate ----------
function tg_tc_timer_tick()
    local t = TG_TUBEC_TIMER
    if not t or not t.active then util.yield(400); return end
    local now = util.current_time_millis()
    if (now - (t.last_check or 0)) > 1000 then
        t.last_check = now
        local alive = false
        for _, o in ipairs(objects) do if o == t.obj then alive = true; break end end
        if not alive then t.active = false; tg_log("[TUBE_CIRCUIT][TIMER] stopped: course cleared"); return end
    end
    local p = tg_minigame_player_position() or nil
    if not p then util.yield(100); return end
    local pv = tg_tp_v(p.x, p.y, p.z)
    local function crossed(gate, key)
        local rel = tg_tp_sub(pv, gate.P)
        local s = tg_tp_dot(rel, gate.D)
        local lat = tg_tp_len(tg_tp_sub(rel, tg_tp_mul(gate.D, s)))
        local prev = t[key]
        t[key] = s
        return prev and prev < 0.0 and s >= 0.0 and lat < (gate.r or TG_TUBEC_GATE_RADIUS or 16.0) and (s - prev) < 60.0, tg_tp_len(rel)
    end
    local hit_start, d1 = crossed(t, "prev_s")
    local hit_finish, d2 = false, 1e9
    if t.finish then hit_finish, d2 = crossed(t.finish, "prev_f") end
    local function report(kind, secs)
        t.laps = (t.laps or 0) + 1
        local note
        if not t.best or secs < t.best then t.best = secs; note = "  NEW BEST!" else note = string.format("  (best %.2fs)", t.best) end
        tg_toast(string.format("%s %d: %.2fs%s", kind, t.laps, secs, note), 5000)
        tg_log(string.format("[TUBE_RACE][TIME] %s=%d time=%.2f best=%.2f", kind, t.laps, secs, t.best))
    end
    if t.finish then
        -- start-to-finish course: start mouth starts the clock, finish mouth stops it
        if hit_start then
            t.lap_start = now
            tg_toast("GO! Race timer started.", 2000)
        elseif hit_finish and t.lap_start then
            report("FINISH! Run", (now - t.lap_start) / 1000.0)
            t.lap_start = nil
        end
    elseif hit_start then
        -- closed loop: every pass of the start line is a lap
        if t.lap_start then report("Lap", (now - t.lap_start) / 1000.0) else tg_toast("GO! Lap timer started.", 2000) end
        t.lap_start = now
    end
    if math.min(d1, d2) > 600.0 then util.yield(200) else util.yield(0) end
end

function tg_tube_circuit_goto_start()
    local t = TG_TUBEC_TIMER
    if not t or not t.P then tg_toast("Build a tube course first.", 2500); return end
    local ped = players and players.user_ped and players.user_ped() or 0
    if not ped or ped == 0 then return end
    local target = ped
    if PED and PED.IS_PED_IN_ANY_VEHICLE and PED.GET_VEHICLE_PED_IS_IN and PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh and veh ~= 0 then target = veh end
    end
    local spot, dir
    if t.drive_spot then
        spot, dir = t.drive_spot, t.drive_dir
    else
        spot, dir = tg_tp_sub(t.P, tg_tp_mul(t.D, 25.0)), t.D
    end
    local heading = tg_normalize_heading(math.deg(tg_atan2_safe(dir.y, dir.x)) - 90.0)
    ENTITY.SET_ENTITY_COORDS_NO_OFFSET(target, spot.x, spot.y, spot.z, false, false, false)
    ENTITY.SET_ENTITY_HEADING(target, heading)
    t.prev_s, t.prev_f, t.lap_start = nil, nil, nil
    tg_toast(t.drive_spot and "In front of the entrance - drive straight in. Timer starts at the mouth." or "At the start line - drive forward.", 3500)
end

-- ---------- v2.0 object-limit helpers ----------
-- the bigger the tube the fewer pieces fit in the map before it hits the sea / mountains
TG_TUBER_FAMILY_CAP = {}          -- v2.0.3: no size caps, the object limit decides
function tg_tr_target_range(rt, fam_key, limit)
    -- v2.0.3: every size fills the object limit you pick: a random length between ~60% and the
    -- limit (minus room for the closing pieces). Standard tubes at the default 73 keep each
    -- style's own tuned length. Big sizes simply cover more of the map.
    local hi = math.max(12, limit - 9)
    if (fam_key == "std" or not fam_key) and limit <= 75 then
        local f = math.min(1.0, limit / 73.0)
        local lo2, hi2 = math.floor((rt.min or 52) * f + 0.5), math.floor((rt.max or 62) * f + 0.5)
        hi2 = math.max(12, math.min(hi2, hi))
        return math.max(10, math.min(lo2, hi2 - 2)), hi2
    end
    local lo = math.max(10, math.floor(hi * ((fam_key == "std" or not fam_key) and 0.75 or 0.6)))
    return lo, hi
end
-- load the collision of buildings around the course area so the building probe can see them
function tg_tr_request_collision(P, radius)
    if not tg_tn_void then return end
    tg_tn_void(0x07503F7948F491A7, P.x + 0.0, P.y + 0.0, P.z + 0.0)                    -- REQUEST_COLLISION_AT_COORD
    for _, f in ipairs({ 0.35, 0.7, 1.0 }) do
        for k = 0, 7 do
            local a = k * math.pi / 4
            tg_tn_void(0x07503F7948F491A7, P.x + math.cos(a) * radius * f, P.y + math.sin(a) * radius * f, P.z + 0.0)
        end
    end
    util.yield(250)
end

-- ---------- v2.0.6 One Way / Across The Map ----------
TG_TUBER_SEL.oneway = TG_TUBER_SEL.oneway or false
TG_TUBER_SEL.across = TG_TUBER_SEL.across or false
-- a random exit on dry ground, away from the start; nil if nothing usable
function tg_tr_pick_exit(sg, F, scale, ground_s, across)
    local fam = math.max(1.0, scale * (across and 0.3 or 0.45))
    local d0, d1 = math.min(300.0 * fam, 1200.0), math.min(750.0 * fam, 2500.0)
    if across then d0, d1 = math.min(1400.0 * fam, 2500.0), math.min(3200.0 * fam, 4500.0) end   -- the map is only ~5 x 8 km
    local base = math.atan(F.y, F.x)
    local best = nil
    for _ = 1, 20 do
        local a = base + math.rad(-150.0 + math.random() * 300.0)
        local d = d0 + math.random() * (d1 - d0)
        local x, y = sg.x + math.cos(a) * d, sg.y + math.sin(a) * d
        local g = tg_ground_z(x, y)
        local real = g ~= nil
        if not g and tg_rs_height then g = tg_rs_height(x, y) end
        if g and g > 1.0 then                               -- dry land (sea level is ~0)
            -- arrive from the side, not straight from the start: the free corridor behind the exit
            -- then never runs back over the entrance
            local turn = math.rad((math.random() < 0.5 and 1 or -1) * (55.0 + math.random() * 45.0))
            local ux, uy = (x - sg.x) / d, (y - sg.y) / d
            local u = tg_tp_norm(tg_tp_v(ux * math.cos(turn) - uy * math.sin(turn), ux * math.sin(turn) + uy * math.cos(turn), 0.0))
            local c = { P = tg_tp_v(x, y, g), ground = g, u = u, dist = d, real = real }
            if real then return c end
            best = best or c
        end
    end
    return best
end
-- Across The Map: long straights and gentle level sweeps, few tight / vertical pieces
function tg_tr_across_weights(rules)
    for _, e in ipairs(rules.menu or {}) do
        local steps = e[1]
        if e[3] then
            e[2] = e[2] * 0.35                              -- multi-piece modules (loops, knots...)
        elseif steps and #steps == 1 then
            local pc = TG_TUBEP_PIECES[steps[1][1]]
            if pc and pc.kind == "straight" then
                e[2] = e[2] * ((pc.len or 0) >= 150.0 and 6.0 or 2.0)
            elseif pc and pc.kind == "bend" then
                local w = ((pc.angle or 90) <= 30) and 2.5 or 0.5
                if steps[1][2] == "wvert" then w = w * 0.4 end
                e[2] = e[2] * w
            end
        end
    end
end
function tg_tube_race_toggle_oneway()
    TG_TUBER_SEL.oneway = not TG_TUBER_SEL.oneway
    tg_toast("One Way: " .. (TG_TUBER_SEL.oneway and "ON - the exit pops out somewhere random" or "OFF - the exit is beside the entrance"), 3000)
end
function tg_tube_race_toggle_across()
    TG_TUBER_SEL.across = not TG_TUBER_SEL.across
    tg_toast("Across The Map: " .. (TG_TUBER_SEL.across and "ON - long straights, travels a long way (best with Arena 2x / Mega)" or "OFF"), 3000)
end

-- ---------- builder ----------
-- build = { family = "std"|"big"|"giant"|"mega", allowed = {key=true}, loops = bool, label = text }
function tg_tube_race_build(type_key, build)
    type_key = type_key or TG_TUBER_LAST or "stunt"
    local rt = TG_TUBER_TYPES[type_key]
    if not rt then tg_toast("Unknown race type " .. tostring(type_key), 3000); return false end
    TG_TUBER_LAST = type_key
    build = build or {}
    tg_rs_build_start("Tube Race")
    local fam_key = build.family or rt.family
    local fam = TG_TUBER_FAMILIES[fam_key] or TG_TUBER_FAMILIES.std
    local scale = fam.scale or 1.0
    local rules = tg_tr_build_rules(rt, fam_key, build.allowed, build.loops, build.mods)
    clear_race_track("tube_race")
    TG_TUBEP_SEED_BUMP = (TG_TUBEP_SEED_BUMP or 0) + 7919
    if math.randomseed then math.randomseed(((os.time and os.time()) or 1) + TG_TUBEP_SEED_BUMP) end

    local pos, heading = tg_get_local_position_heading("tube_race")
    TG_RS_NEAR = { P = { x = pos.x, y = pos.y }, r = 220.0 }
    heading = tonumber(heading or 0.0) or 0.0
    local fx, fy = calculate_new_position({ x = 0.0, y = 0.0, z = 0.0 }, heading, 1.0, 0.0, 0.0)
    local F = tg_tp_norm(tg_tp_v(fx, fy, 0.0))
    local Zw = tg_tp_v(0.0, 0.0, 1.0)
    local L = tg_tp_norm(tg_tp_cross(Zw, F))
    local clearance = (TG_TUBEP_CLEARANCE or 24.0) * scale
    local ctx = {
        clearance = clearance, scale = scale,
        tube_radius = (TG_TUBECO_TUBE_RADIUS or 7.5) * scale,
        world = (TG_WORLD_OBSTACLE_AVOIDANCE ~= false),
        heightmap = (fam_key == "std")           -- v2.0.4: height-map building/terrain check for Standard tubes only
    }
    local start, home, gate_finish, drive_spot
    local oneway_dist = nil
    if TG_TUBER_GROUND_ENTRY then
        local th = math.rad(TG_TUBER_ENTRY_PITCH or 8.0)
        local dist = (TG_TUBER_ENTRY_DIST or 40.0) + (scale - 1.0) * 15.0
        -- mouths sit below ground level so the opening reaches the road surface: drive straight in
        -- v1.3.0: official track->tube joins put the tube centre 8.74 m above the road, so the floor is
        -- 8.74 m (x size) below the centre line. Put the floor just under the ground: drive straight in.
        local sink = ((TG_TUBER_ENTRY_SINK or 0.5) - (TG_TUBER_FLOOR_R or 8.74)) * scale
        local sg = tg_tp_add(tg_tp_v(pos.x, pos.y, pos.z), tg_tp_mul(F, dist))
        local ground_s = tg_tr_ground_z(sg.x, sg.y, pos.z - 1.0)
        sg.z = ground_s - sink
        local side = (math.random() < 0.5) and 1.0 or -1.0
        local lat = math.max(45.0, clearance * 1.7)
        local eg = tg_tp_add(sg, tg_tp_mul(L, side * lat))
        eg.z = tg_tr_ground_z(eg.x, eg.y, ground_s) - sink
        local Ds = tg_tp_norm(tg_tp_add(tg_tp_mul(F, math.cos(th)), tg_tp_mul(Zw, math.sin(th))))
        local De = tg_tp_norm(tg_tp_add(tg_tp_mul(F, -math.cos(th)), tg_tp_mul(Zw, -math.sin(th))))
        local ground_e = ground_s
        oneway_dist = nil
        if TG_TUBER_SEL.oneway then
            -- v2.0.6 One Way: exit somewhere random (far across the map with Across The Map on)
            local ex = tg_tr_pick_exit(sg, F, scale, ground_s, TG_TUBER_SEL.across)
            local rr = tg_rs_radius("tubes") or nil
            if ex and rr and ex.dist > rr * 0.85 then ex = nil end      -- v2.3.0: exit must be inside the radius
            if ex then
                ground_e = ex.ground
                eg = tg_tp_v(ex.P.x, ex.P.y, ex.ground - sink)
                De = tg_tp_norm(tg_tp_add(tg_tp_mul(ex.u, math.cos(th)), tg_tp_mul(Zw, -math.sin(th))))
                oneway_dist = ex.dist
            end
        end
        local Us = tg_tp_norm(tg_tp_sub(Zw, tg_tp_mul(Ds, tg_tp_dot(Zw, Ds))))
        local Ue = tg_tp_norm(tg_tp_sub(Zw, tg_tp_mul(De, tg_tp_dot(Zw, De))))
        start = { P = sg, D = Ds, U = Us }
        home = { P = eg, D = De, U = Ue }
        ctx.floor_z = math.min(sg.z, eg.z) - 1.5
        ctx.ceil_z = math.max(sg.z, eg.z) + 320.0 * math.max(1.0, math.min(scale * 0.6, 2.0))
        ctx.open = true
        -- only the buried mouths are exempt from the building probe
        ctx.noprobe = { { P = sg, r = 70.0 * scale, zmax = ground_s + 16.0 * scale }, { P = eg, r = 70.0 * scale, zmax = ground_e + 16.0 * scale } }
        gate_finish = { P = eg, D = De, r = 16.0 * scale }
        drive_spot = tg_tp_sub(sg, tg_tp_mul(F, dist * 0.8))
        drive_spot.z = ground_s + 1.0
    else
        local lift = TG_TUBEP_START_LIFT
        TG_TUBEP_START_LIFT = (TG_TUBECO_START_LIFT or 16.0) * scale
        start = tg_tp_start_state("tube_race")
        TG_TUBEP_START_LIFT = lift
        home = start
        ctx.floor_z = start.P.z - 1.0
        ctx.ceil_z = start.P.z + 320.0 * math.max(1.0, scale * 0.6)
    end

    local pre = fam.prefix or ""
    local lead = { { pre .. "xs", 0 } }
    -- v2.0 TrackMatic: the object limit slider decides the course length (every tube size)
    local limit = tg_rs_limit("tubes")
    local tmin, tmax = tg_tr_target_range(rt, fam_key, limit)
    -- roam further for longer courses (relative to the length this size was tuned for)
    local tuned = (TG_TUBER_SIZE_TARGETS[fam_key] or { 0, 56 })[2]
    local grow = math.max(1.0, math.sqrt(tmax / tuned))
    local opts = {
        lead = lead, home = home, approach = 200.0,
        min = tmin, max = tmax,
        max_objects = limit - 2,
        max_radius = (TG_TUBECO_MAX_RADIUS or 700.0) * math.min(scale, 3.7) * ((fam_key == "std") and (rt.radius or 1.0) or 1.0) * grow
    }
    ctx.ceil_z = ctx.ceil_z and (ctx.ceil_z + (grow - 1.0) * 160.0 * math.min(scale, 2.0))
    if TG_TUBER_SEL.across then
        opts.max_radius = opts.max_radius * 2.2
        tg_tr_across_weights(rules)
    end
    if oneway_dist then opts.max_radius = math.max(opts.max_radius, oneway_dist * 1.4) end
    -- v2.3.0 radius (Tubes tab): never roam further than this from the entrance
    local user_r = tg_rs_radius("tubes") or nil
    if user_r then ctx.user_r = user_r; ctx.rc = { x = pos.x, y = pos.y } end
    if user_r then opts.max_radius = math.min(opts.max_radius, math.max(80.0, user_r - 45.0 - 12.0 * scale)) end
    local fam_cap = TG_TUBER_FAMILY_CAP[fam_key]
    if fam_cap and limit > fam_cap + 9 then
        tg_toast(string.format("%s tubes are huge: capped at ~%d pieces (they would cover the whole map).", fam.name, fam_cap), 4000)
    end
    tg_toast("Planning " .. rt.name .. " - " .. fam.name .. " tubes" .. (build.label and (", " .. build.label) or "") .. string.format(" (%d-%d pieces)...", tmin, tmax), 2500)
    -- (v2.0.2: no REQUEST_COLLISION from the build job - streaming natives there can crash GTA)
    local plans, why = nil, ""
    tg_rs_stage("Planning tube course")
    local attempts = (rt.attempts or TG_TUBECO_ATTEMPTS or 10)
    if tmax > 120 then attempts = attempts + 4 end
    if fam_key == "mega" or fam_key == "giant" then attempts = attempts + 6 end
    for attempt = 1, attempts do
        TG_WORLD_OBSTACLE_PROBE_CACHE = {}
        if tg_rs_plan_progress("Tube Race", attempt, attempts, 0, tmax) then return false end
        opts.progress = function(n, t) tg_rs_plan_progress("Tube Race", attempt, attempts, n, t) end
        plans, why = tg_tco_plan_course(start, rules, ctx, opts)
        tg_log("[TUBE_RACE][ATTEMPT] " .. type_key .. " #" .. tostring(attempt) .. " result=" .. tostring(why) .. " pieces=" .. tostring(plans and #plans or 0))
        if plans then break end
        -- long courses that keep failing: shorten a little each retry
        if attempt % 3 == 0 and opts.max > 30 then
            opts.max = math.floor(opts.max * 0.9); opts.min = math.min(opts.min, opts.max - 4)
        end
        -- v2.0.5: "not enough space" -> loosen step by step so something always gets placed:
        -- half-way: drop the height-map check; last quarter: ignore buildings entirely
        if ctx.heightmap and attempt >= math.floor(attempts * 0.5) then
            ctx.heightmap = false
            tg_log("[TUBE_RACE][RELAX] height-map check off")
        end
        if ctx.world and attempt >= math.floor(attempts * 0.75) then
            ctx.world = false
            tg_toast("Tight spot - building the course without the building check.", 3500)
            tg_log("[TUBE_RACE][RELAX] building probe off")
        end
        util.yield(0)
    end
    if tg_rs_check_cancel() then return false end
    if not plans and tmax > (TG_TUBER_SIZE_TARGETS[fam_key] or { 0, rt.max or 62 })[2] then
        -- a long course wouldn't fit here: fall back to the normal length rather than nothing
        local base = TG_TUBER_SIZE_TARGETS[fam_key] or { rt.min or 52, rt.max or 62 }
        opts.min, opts.max = base[1], base[2]
        opts.max_radius = (TG_TUBECO_MAX_RADIUS or 700.0) * math.min(scale, 3.7) * ((fam_key == "std") and (rt.radius or 1.0) or 1.0)
        if user_r then opts.max_radius = math.min(opts.max_radius, math.max(80.0, user_r - 45.0 - 12.0 * scale)) end
        tg_toast("Long course didn't fit here - building a normal-length one instead.", 3500)
        for attempt = 1, 12 do
            if tg_rs_check_cancel() then return false end
            TG_WORLD_OBSTACLE_PROBE_CACHE = {}
            opts.progress = function(n, t) tg_rs_plan_progress("Tube Race", attempt, 12, n, t) end
            plans, why = tg_tco_plan_course(start, rules, ctx, opts)
            if plans then break end
            util.yield(0)
        end
    end
    if tg_rs_check_cancel() then return false end
    if not plans then
        tg_toast("Couldn't fit a " .. rt.name .. " course here (" .. tostring(why) .. "). Try again or face open space.", 4500)
        tg_rs_progress_fail("Couldn't fit a course here - face open space and try again")
        return false
    end
    if fam_key == "std" and tg_rs_apply_skin then tg_rs_apply_skin(plans) end   -- v2.0.7 Special Circuit skin
    tg_rs_preload("Tube Race", plans)

    local token = tg_generation_start("tube_race") or nil
    local placed = 0
    local missed = {}
    local saved_lift = TG_TUBECO_ANIM_LIFT
    TG_TUBECO_ANIM_LIFT = (saved_lift or 18.0) * math.min(scale, 3.0)
    for i, plan in ipairs(plans) do
        if tg_generation_should_stop(token, "tube_race") then break end
        if tg_rs_spawn_progress("Tube Race", i, #plans, "Spawning tube") then TG_TUBECO_ANIM_LIFT = saved_lift; return false end
        util.yield((#plans > 120) and 20 or (TG_TUBEP_DELAY_MS or 70))
        if tg_pk_colour_for then plan.tint = tg_pk_colour_for(TG_TUBER_SEL.colour, TG_TUBER_SEL.colour_index, i, nil) end
        if tg_tco_spawn_animated(plan, "tube_race_" .. tostring(i)) then placed = placed + 1 else table.insert(missed, plan) end
    end
    -- v2.0.3: repair passes for pieces that failed (big Arena / Mega models still streaming)
    local fixed = tg_rs_repair("Tube Race", missed, function(plan, k) return tg_tp_spawn(plan, "tube_race_fix_" .. tostring(k)) end)
    placed = placed + fixed
    TG_TUBECO_ANIM_LIFT = saved_lift
    if tg_rs_progress("Tube Race", 0.99, "Syncing tubes to the session...") then return false end
    local net_ok, net_total = 0, 0
    if tg_tn_settle_all then
        local a, b = tg_tn_settle_all("tube race")
        net_ok, net_total = a or 0, b or 0
    end
    if placed < #plans then tg_rs_progress_done(string.format("%d / %d pieces (some failed - lobby object budget full?)", placed, #plans))
    else tg_rs_progress_done(string.format("%d pieces placed", placed)) end
    tg_log("[TUBE_RACE][DONE] type=" .. type_key .. " family=" .. tostring(fam_key) .. " pieces=" .. tostring(build.label or "style default") .. " placed=" .. tostring(placed) .. "/" .. tostring(#plans))
    tg_report_state("tube_race_done")
    tg_tc_timer_arm(start, objects[#objects])
    TG_TUBEC_TIMER.r = 16.0 * scale
    TG_TUBEC_TIMER.finish = gate_finish
    TG_TUBEC_TIMER.drive_spot = drive_spot
    TG_TUBEC_TIMER.drive_dir = F
    if TG_TUBER_GROUND_ENTRY then
        tg_toast(rt.name .. ": " .. tostring(placed) .. " pieces. Drive into the mouth ahead - " ..
            (oneway_dist and string.format("ONE WAY: the exit is ~%.1f km away.", oneway_dist / 1000.0) or "finish pops out beside it.") ..
            ((tg_tn_in_session()) and string.format(" (%d/%d networked for everyone)", net_ok, net_total) or ""), 6000)
    else
        tg_toast(rt.name .. ": " .. tostring(placed) .. " pieces. Use 'Go To Start Line' to drop in.", 5000)
    end
    return placed > 0
end

function tg_tube_race_toggle_ground()
    TG_TUBER_GROUND_ENTRY = not TG_TUBER_GROUND_ENTRY
    tg_toast("Tube races: " .. (TG_TUBER_GROUND_ENTRY and "DRIVE-IN from the ground (start + finish mouths beside you)" or "FLOATING closed loop (teleport in)"), 3500)
end

-- The v1.1.5 Mixed / Flow / Stunt course buttons now build drive-in race types too.
TG_TUBER_LEGACY_COURSE_BUILD = TG_TUBER_LEGACY_COURSE_BUILD or tg_tube_course_build
function tg_tube_course_build(rules_key)
    local map = { mixed = "stunt", flow = "issi", stunt = "sky" }
    if TG_TUBER_GROUND_ENTRY and map[rules_key or "mixed"] then
        return tg_tube_race_build(map[rules_key or "mixed"])
    end
    return TG_TUBER_LEGACY_COURSE_BUILD(rules_key)
end

-- ---------- dropdown selection -> build ----------
function tg_tube_race_build_selected()
    local sel = TG_TUBER_SEL
    local style = sel.style
    if style == "random" then style = TG_TUBER_STYLE_ORDER[math.random(#TG_TUBER_STYLE_ORDER - 1)] end
    local size = sel.size
    if size == "random" then local o = { "std", "big", "giant" }; size = o[math.random(#o)] end
    local addons = {}
    if sel.pieces == "custom" then for k, v in pairs(sel.addons) do addons[k] = v end
    elseif sel.pieces == "everything" then addons = { gapjump = true, fn = true, loops = true }
    elseif sel.pieces == "random" then for _, k in ipairs(TG_TUBER_ADDON_ORDER) do addons[k] = math.random() < 0.5 end end
    local allowed, names = {}, {}
    for k in pairs(TG_TUBER_DEFAULT_KEYS) do allowed[k] = true end
    for _, a in ipairs(TG_TUBER_ADDON_ORDER) do
        if addons[a] then
            table.insert(names, TG_TUBER_ADDON_NAMES[a])
            for k in pairs(TG_TUBER_ADDON_KEYS[a] or {}) do allowed[k] = true end
        end
    end
    local label = (#names > 0) and ("default + " .. table.concat(names, ", ")) or "default tubes"
    -- tube piece types (modules)
    local mods, mm = {}, sel.modmode or "style"
    if mm == "mine" then for id, on in pairs(sel.mods or {}) do if on then mods[id] = 8 end end
    elseif mm == "all" then for _, id in ipairs(TG_TUBE_PIECE_TYPES) do mods[id] = 5 end
    elseif mm == "random" then
        for _ = 1, 6 do mods[TG_TUBE_PIECE_TYPES[math.random(#TG_TUBE_PIECE_TYPES)]] = 8 end
    end
    local nmods = 0
    for _ in pairs(mods) do nmods = nmods + 1 end
    if nmods > 0 then label = label .. ", " .. tostring(nmods) .. " piece types" end
    return tg_tube_race_build(style, { family = size, allowed = allowed, loops = addons.loops == true, label = label, mods = mods })
end

function tg_tr_cycle(order, current)
    for i, v in ipairs(order) do if v == current then return order[(i % #order) + 1] end end
    return order[1]
end
function tg_tube_race_cycle_style()
    TG_TUBER_SEL.style = tg_tr_cycle(TG_TUBER_STYLE_ORDER, TG_TUBER_SEL.style)
    local rt = TG_TUBER_TYPES[TG_TUBER_SEL.style]
    tg_toast("Course style: " .. (rt and rt.name or "Random style"), 2500)
end
function tg_tube_race_cycle_size()
    TG_TUBER_SEL.size = tg_tr_cycle(TG_TUBER_SIZE_ORDER, TG_TUBER_SEL.size)
    tg_toast("Tube size: " .. TG_TUBER_SIZE_NAMES[TG_TUBER_SEL.size], 2500)
end
function tg_tube_race_cycle_pieces()
    TG_TUBER_SEL.pieces = tg_tr_cycle(TG_TUBER_PIECES_ORDER, TG_TUBER_SEL.pieces)
    tg_toast("Tube pieces: " .. TG_TUBER_PIECES_NAMES[TG_TUBER_SEL.pieces], 2500)
end
function tg_tube_race_toggle_addon(key)
    TG_TUBER_SEL.addons[key] = not TG_TUBER_SEL.addons[key]
    if TG_TUBER_SEL.pieces == "default" and TG_TUBER_SEL.addons[key] then TG_TUBER_SEL.pieces = "custom" end
    tg_toast("Add-on " .. TG_TUBER_ADDON_NAMES[key] .. ": " .. (TG_TUBER_SEL.addons[key] and "ON" or "OFF"), 2500)
end

-- Prime-safe custom dropdowns: an open combo is always closed with EndCombo.
function tg_tube_ui_combo_items(options, on_pick)
    for _, opt in ipairs(options) do
        if ImGui.Selectable(opt[2], opt[3] == true) then on_pick(opt[1]) end
    end
end
function tg_tube_ui_combo(id, title, preview, options, on_pick)
    ImGui.Text(title)
    if ImGui.BeginCombo(id, preview) then tg_tube_ui_combo_items(options, on_pick); ImGui.EndCombo() end
end

-- Production UI sizing: text-first widths and automatic row wraps for DPI scaling.
-- v1.2.0 perf: text widths are remembered for a second (one CalcTextSize per label per second
-- instead of every frame); the cache resets each second so font / DPI changes still apply
TG_PM_TW = {}
TG_PM_TW_AT = 0
function tg_pm_text_width(label)
    local now = tg_now_ms()
    if now - TG_PM_TW_AT > 1000 or now < TG_PM_TW_AT then TG_PM_TW = {}; TG_PM_TW_AT = now end
    local key = label or ""
    local w = TG_PM_TW[key]
    if w then return w end
    local visible = tostring(key):match("^(.-)##") or tostring(key)
    local x = ImGui.CalcTextSize(visible)
    if type(x) == "table" or type(x) == "userdata" then x = x.x end      -- some builds return an ImVec2
    if not (x and x > 0) then x = #visible * 10 end                      -- conservative fallback for larger Cherax fonts
    TG_PM_TW[key] = x
    return x
end
function tg_pm_button_width(label, minimum)
    return math.max(tonumber(minimum or 70) or 70, math.ceil(tg_pm_text_width(label) + 28))
end
function tg_pm_room_for_next(label, minimum)
    local width = ImGui.GetContentRegionAvail()
    if type(width) == "number" and width > 0 then
        return width >= tg_pm_button_width(label, minimum) + 12
    end
    return true
end
function tg_pm_maybe_same(label, minimum, row_count, max_columns)
    if row_count < max_columns and tg_pm_room_for_next(label, minimum) then
        ImGui.SameLine()
        return row_count
    end
    return 0
end

-- v1.2.0: option buttons instead of ImGui combo popups. The popups could get stuck in ClickGUI
-- (a pick wouldn't change back until the script was reloaded). Plain buttons have no popup state:
-- a click sets the value right away, exactly like the tab buttons.
function tg_ui_choice_row(title, id, options, current, on_pick, per_row, width)
    if title then ImGui.Text(title) end
    per_row = per_row or 4
    local row_count = 0
    for i, opt in ipairs(options) do
        local active = (opt[1] == current) or (opt[3] == true)
        local n = tg_ui_push_button_colors(active) or 0
        local caption = tostring(opt[2])
        local w = tg_pm_button_width(caption, width or 150)
        local clicked = ImGui.Button(caption .. "##" .. id .. "_" .. tostring(opt[1]), w, 30)
        tg_ui_pop_colors(n)
        if clicked then on_pick(opt[1]) end
        tg_hp_from_button(id, opt[1], opt[2])
        row_count = row_count + 1
        if i < #options then
            local next_caption = tostring(options[i + 1][2])
            row_count = tg_pm_maybe_same(next_caption, width or 150, row_count, per_row)
        end
    end
end

TG_TUBER_STYLE_SHORT = { stunt = "Stunt", voltic = "Rocket Voltic", ruiner = "Ruiner 2000", issi = "Issi Classic", circuit = "Hotring", sky = "Sky High", random = "Random" }
TG_TUBER_SIZE_SHORT = { std = "Standard", big = "Arena 2.75x", giant = "Arena 2x", mega = "Mega 4x (add-on)", random = "Random size" }
TG_TUBER_PIECES_SHORT = { default = "Default tubes", custom = "Default + add-ons", everything = "Everything", random = "Random add-ons" }
TG_TUBER_SEL.colour = TG_TUBER_SEL.colour or "off"
TG_TUBER_SEL.colour_index = TG_TUBER_SEL.colour_index or 1
TG_TUBER_COLOUR_ORDER = { "off", "single", "rainbow", "random" }


function tg_tube_race_cycle_colour()
    TG_TUBER_SEL.colour = tg_tr_cycle(TG_TUBER_COLOUR_ORDER, TG_TUBER_SEL.colour)
    tg_toast("Tube colour: " .. ((TG_PK_COLOUR_NAMES and TG_PK_COLOUR_NAMES[TG_TUBER_SEL.colour]) or TG_TUBER_SEL.colour), 2500)
end
function tg_tube_race_next_colour()
    TG_TUBER_SEL.colour_index = (TG_TUBER_SEL.colour_index % 15) + 1
    TG_TUBER_SEL.colour = "single"
    tg_toast("Tube colour #" .. tostring(TG_TUBER_SEL.colour_index), 2000)
end

function tg_tube_race_entry_sink(delta)
    TG_TUBER_ENTRY_SINK = math.max(-2.0, math.min(10.0, (TG_TUBER_ENTRY_SINK or 0.5) + (delta or 0.0)))
    tg_toast(string.format("Tube floor at the entrance: %.1f m %s the ground (next build)", math.abs(TG_TUBER_ENTRY_SINK), TG_TUBER_ENTRY_SINK >= 0 and "below" or "above"), 2500)
end

function tg_tube_race_cycle_modmode()
    TG_TUBER_SEL.modmode = tg_tr_cycle({ "style", "mine", "all", "random" }, TG_TUBER_SEL.modmode or "style")
    tg_toast("Tube piece types: " .. ({ style = "style's picks", mine = "my picks", all = "all 30", random = "random 6" })[TG_TUBER_SEL.modmode], 2500)
end

-- v2.0 TrackMatic: RANDOM ALL = every style's pieces + every add-on + every tube module, random segments
function tg_tube_race_random_all()
    local sel = TG_TUBER_SEL
    local size = sel.size
    if size == "random" then local o = { "std", "big", "giant" }; size = o[math.random(#o)] end
    local allowed = {}
    for k in pairs(TG_TUBER_DEFAULT_KEYS) do allowed[k] = true end
    for _, a in ipairs(TG_TUBER_ADDON_ORDER) do for k in pairs(TG_TUBER_ADDON_KEYS[a] or {}) do allowed[k] = true end end
    local mods = {}
    for _, m in ipairs(TG_TUBE_MODULES or {}) do mods[m.id] = 3 + math.random(5) end
    -- borrow the bend mix of a random style each build so no two are alike
    local rt = TG_TUBER_TYPES.allmix
    local donor = TG_TUBER_TYPES[TG_TUBER_STYLE_ORDER[math.random(#TG_TUBER_STYLE_ORDER - 2)]]
    if donor and donor.mix then rt.mix = { donor.mix[1] * 0.5 + 17, donor.mix[2] * 0.5 + 16, donor.mix[3] * 0.5 + 17 } end
    return tg_tube_race_build("allmix", { family = size, allowed = allowed, loops = true, label = "Random All: every piece + module", mods = mods })
end
-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.1.9 tube networking + visibility
-- Why other players could not see the tubes (and saw "invisible walls"):
--  * GTA only registers script objects on the network properly when the calling script is a
--    network script. Our Lua job was not, so EXISTS_ON_ALL_MACHINES etc. never stuck and the
--    pieces only existed for players standing close by. Constructor (Stand) / BiggerScript
--    (Cherax) build inside the "freemode" script context - we now do the same.
--  * Remote copies of a piece arrive with low-precision rotation. On a 260 m tube a fraction
--    of a degree is a lip of a metre at the next joint = invisible wall on SOME connectors
--    (long / rolled / vertical pieces). High-precision rotation sync + a final re-sync fixes it.
--  * A remote copy only appears when you're in range, then its model still has to stream:
--    drive fast and you reach it before it draws. Scope distance + "exists on all machines"
--    create the copies up-front, and the Visibility Boost keeps tube models loaded and
--    stretches their draw distance on your own machine.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_TUBENET_ENABLED = (TG_TUBENET_ENABLED ~= false)
TG_TUBENET_FREEMODE = (TG_TUBENET_FREEMODE ~= false)        -- build inside the freemode script context (Constructor / BiggerScript style)
TG_TUBENET_HIGH_PRECISION = (TG_TUBENET_HIGH_PRECISION ~= false)
TG_TUBENET_SCOPE = TG_TUBENET_SCOPE or 5000.0                -- metres other players receive the pieces from
TG_TUBENET_LOD = TG_TUBENET_LOD or 0xFFFF                    -- max LOD distance (stored as uint16)
TG_TUBENET_REGISTER_MS = TG_TUBENET_REGISTER_MS or 300
TG_TUBENET_KEEPER_MS = TG_TUBENET_KEEPER_MS or 3000
TG_TUBENET_BOOST = (TG_TUBENET_BOOST ~= false)               -- local draw distance + model preload for every stunt tube nearby
TG_TUBENET_BOOST_MS = TG_TUBENET_BOOST_MS or 2000
TG_TUBENET_PIECES = TG_TUBENET_PIECES or {}                  -- handle -> { x,y,z, pitch,roll,yaw, model, net, players = {} }
TG_TUBENET_STATS = TG_TUBENET_STATS or { hardened = 0, networked = 0, failed = 0, last = "" }

TG_TN_H = {
    IS_NETWORKED = 0xC7827959479DCC78, REGISTER = 0x06FAACD625D80CAA, NETID_FROM_ENTITY = 0xA11700682F3AD45C,
    OBJ_TO_NET = 0x99BFDC94A603E541, EXISTS_ON_ALL = 0xE05E81A888FA63C8, ALWAYS_EXISTS_FOR = 0xA8A024587329F36A,
    CAN_MIGRATE = 0x299EEB23175895FC, CAN_BE_REASSIGNED = 0x9D724B400A7E8FFC,
    HP_ROTATION = 0x95BAF97C82464629, HP_BLENDING = 0x2B1813ABA29016C5, SCOPE = 0xBA7F0B77D80A4EB7,
    SET_LOD = 0x5927F96A78577363, GET_LOD = 0x4159C2762B5791D6,
    PLAYER_ACTIVE = 0xB8DFD30D6973E135, SESSION_STARTED = 0x9DE624D2FC4B603F, PLAYER_ID = 0x4F8644AF03D0E0D6,
    GET_ROT = 0xAFBD61CC738D9EB9, GET_COORDS = 0x3FEF770D40960D5A, SET_ROT = 0x8524A8B0171D5E07,
    FREEZE = 0x428CA6DBD1094446, SET_COORDS_NO_OFFSET = 0x239A3351AC1DA385, EXISTS = 0x7239B21A38F536BA,
    GET_MODEL = 0x9F47B058362C84B5, REQUEST_MODEL = 0x963D27A58DF860AC, HAS_MODEL_LOADED = 0x98A4EB5D89A0C952,
    MISSION = 0xAD738C3085FE7E11, FREEZE_WAIT_COLLISION = 0x3910051CCECDB00C, LOAD_COLLISION = 0x0DC7CABAB1E9B67E
}

function tg_tn_void(h, ...)
    return Natives.InvokeVoid(h, ...)
end
function tg_tn_bool(h, ...)
    return Natives.InvokeBool(h, ...) == true
end
function tg_tn_int(h, ...)
    return tonumber(Natives.InvokeInt(h, ...)) or 0
end
function tg_tn_v3(h, ...)
    local a, b, c = Natives.InvokeV3(h, ...)
    if type(a) == "table" or type(a) == "userdata" then
        if a.x == nil then return nil end
        return { x = a.x, y = a.y, z = a.z }
    end
    if a == nil then return nil end
    return { x = tonumber(a) or 0.0, y = tonumber(b) or 0.0, z = tonumber(c) or 0.0 }
end

function tg_tn_in_session() return tg_tn_bool(TG_TN_H.SESSION_STARTED) end
function tg_tn_exists(e) return e and e ~= 0 and tg_tn_bool(TG_TN_H.EXISTS, e) end
function tg_tn_sleep(ms) util.yield(ms or 0) end
function tg_tn_now() return Time.GetEpocheMs() end

-- Run fn inside the freemode script context (the same trick BiggerScript uses for networked maps).
-- Returns true when the job was queued there; false means "run it yourself".
-- TG_TN_IN_FREEMODE_JOB is the coroutine of the freemode job that is running (false when none).
TG_TN_IN_FREEMODE_JOB = false
function tg_tn_in_freemode_job() return TG_TN_IN_FREEMODE_JOB ~= false and TG_TN_IN_FREEMODE_JOB == coroutine.running() end
function tg_tn_freemode_job(tag, fn)
    if not (TG_TUBENET_ENABLED and TG_TUBENET_FREEMODE) or tg_tn_in_freemode_job() then return false end
    if not tg_tn_in_session() then return false end
    local queued = false
    local gen_at_queue = TG_RS_CANCEL_GEN
    Script.ExecuteAsScript("freemode", function()
        Script.QueueJob(function()
            if TG_RS_CANCEL_GEN ~= gen_at_queue then
                tg_log("[TUBE_NET][" .. tostring(tag) .. "] skipped: cleared before it started")
                return
            end
            tg_rs_job_begin(gen_at_queue)
            if TG_RS_PROG and TG_RS_PROG.queued then TG_RS_PROG.queued = nil; TG_RS_PROG.msg = "Starting..."; TG_RS_PROG.touched = util.current_time_millis() end
            TG_TN_IN_FREEMODE_JOB = coroutine.running()
            fn()
            TG_TN_IN_FREEMODE_JOB = false
            if tg_rs_cancelled() then tg_log("[TUBE_NET][" .. tostring(tag) .. "] cancelled by Clear Track") end
        end)
        queued = true
    end)
    if queued and TG_RS_PROG then
        TG_RS_PROG.active, TG_RS_PROG.queued, TG_RS_PROG.done_at = true, true, nil
        TG_RS_PROG.msg = "Queued in the session's network context - starting..."
        TG_RS_PROG.touched = util.current_time_millis()
    end
    return queued
end

-- Same idea for short non-yielding passes (keeper ticks).
function tg_tn_in_freemode(fn)
    if TG_TUBENET_FREEMODE and tg_tn_in_session() then
        Script.ExecuteAsScript("freemode", fn)
    else
        fn()
    end
    return true
end

function tg_tn_net_id(e)
    local id = tg_tn_int(TG_TN_H.NETID_FROM_ENTITY, e)
    if id == 0 then id = tg_tn_int(TG_TN_H.OBJ_TO_NET, e) end
    return id
end

function tg_tn_players()
    local list = {}
    local me = tg_tn_int(TG_TN_H.PLAYER_ID)
    for pid = 0, 31 do
        if pid == me or tg_tn_bool(TG_TN_H.PLAYER_ACTIVE, pid) then table.insert(list, pid) end
    end
    return list
end

-- Network flags only (no yields): safe inside ExecuteAsScript.
function tg_tn_apply_flags(e, rec)
    local net = tg_tn_net_id(e)
    if net == 0 then return false end
    rec.net = net
    tg_tn_void(TG_TN_H.EXISTS_ON_ALL, net, true)
    tg_tn_void(TG_TN_H.CAN_MIGRATE, net, false)
    tg_tn_void(TG_TN_H.CAN_BE_REASSIGNED, net, false)
    rec.players = rec.players or {}
    for _, pid in ipairs(tg_tn_players()) do
        if not rec.players[pid] then
            tg_tn_void(TG_TN_H.ALWAYS_EXISTS_FOR, net, pid, true)
            rec.players[pid] = true
        end
    end
    if TG_TUBENET_HIGH_PRECISION then
        tg_tn_void(TG_TN_H.HP_ROTATION, net, true)
        tg_tn_void(TG_TN_H.HP_BLENDING, net, true)
    end
    tg_tn_void(TG_TN_H.SCOPE, e, TG_TUBENET_SCOPE + 0.0)
    rec.flagged = true
    return true
end

-- Pose + draw distance (no yields).
function tg_tn_apply_pose(e, rec)
    tg_tn_void(TG_TN_H.SET_COORDS_NO_OFFSET, e, rec.x, rec.y, rec.z, false, false, false)
    tg_tn_void(TG_TN_H.SET_ROT, e, rec.pitch, rec.roll, rec.yaw, 2, true)
    tg_tn_void(TG_TN_H.FREEZE, e, true)
    tg_tn_void(TG_TN_H.SET_LOD, e, TG_TUBENET_LOD)
    tg_tn_void(TG_TN_H.LOAD_COLLISION, e, true, 0)
end

-- Constructor-style networking for one finished piece. May yield (call from a script job).
function tg_tn_harden(e, pose)
    if not TG_TUBENET_ENABLED or not tg_tn_exists(e) then return false end
    if not TG_TN_KEEPER_STARTED then tg_tn_start_keeper() end
    local rec = TG_TUBENET_PIECES[e] or {}
    TG_TUBENET_PIECES[e] = rec
    if pose then
        rec.x, rec.y, rec.z = pose.x, pose.y, pose.z
        rec.pitch, rec.roll, rec.yaw, rec.model = pose.pitch or 0.0, pose.roll or 0.0, pose.yaw or 0.0, pose.model
    end
    tg_tn_void(TG_TN_H.SET_LOD, e, TG_TUBENET_LOD)
    tg_tn_void(TG_TN_H.FREEZE_WAIT_COLLISION, e, false)
    if not tg_tn_in_session() then return true end
    local deadline = tg_tn_now() + TG_TUBENET_REGISTER_MS
    local tries = 0
    while not tg_tn_bool(TG_TN_H.IS_NETWORKED, e) and tg_tn_now() < deadline and tries < 40 do
        tg_tn_void(TG_TN_H.REGISTER, e)
        tries = tries + 1
        tg_tn_sleep(0)
    end
    rec.networked = tg_tn_bool(TG_TN_H.IS_NETWORKED, e)
    local flagged = tg_tn_apply_flags(e, rec)
    TG_TUBENET_STATS.hardened = TG_TUBENET_STATS.hardened + 1
    if rec.networked and flagged then TG_TUBENET_STATS.networked = TG_TUBENET_STATS.networked + 1
    else TG_TUBENET_STATS.failed = TG_TUBENET_STATS.failed + 1 end
    return rec.networked and flagged
end

-- After a build: push one exact final pose for every piece (now with high-precision rotation on),
-- so remote copies don't keep a pose from the middle of the spin-and-drop animation.
function tg_tn_settle_all(label)
    if not TG_TUBENET_ENABLED then return 0, 0 end
    local total, ok_count, i = 0, 0, 0
    for e, rec in pairs(TG_TUBENET_PIECES) do
        if tg_tn_exists(e) then
            total = total + 1
            if not rec.flagged or not tg_tn_bool(TG_TN_H.IS_NETWORKED, e) then tg_tn_harden(e) end
            if rec.x then tg_tn_apply_pose(e, rec) end
            if rec.flagged then ok_count = ok_count + 1 end
            i = i + 1
            if i % 8 == 0 then tg_tn_sleep(0) end
        else
            TG_TUBENET_PIECES[e] = nil
        end
    end
    TG_TUBENET_STATS.last = string.format("%s: %d/%d pieces networked for everyone", tostring(label or "course"), ok_count, total)
    tg_log("[TUBE_NET][SETTLE] " .. TG_TUBENET_STATS.last .. " session=" .. tostring(tg_tn_in_session()))
    return ok_count, total
end

-- Keeper: re-flags pieces for players who joined later, re-registers anything that dropped off,
-- and every few passes re-sends the exact pose.
TG_TN_KEEPER_STARTED = TG_TN_KEEPER_STARTED or false
TG_TN_KEEPER_PASS = 0
function tg_tn_keeper_pass()
    if not TG_TUBENET_ENABLED or not tg_tn_in_session() then return end
    TG_TN_KEEPER_PASS = TG_TN_KEEPER_PASS + 1
    local resend = (TG_TN_KEEPER_PASS % 5 == 0)
    tg_tn_in_freemode(function()
        for e, rec in pairs(TG_TUBENET_PIECES) do
            if tg_tn_exists(e) then
                if not tg_tn_bool(TG_TN_H.IS_NETWORKED, e) then tg_tn_void(TG_TN_H.REGISTER, e); rec.players = {} end
                tg_tn_apply_flags(e, rec)
                if resend and rec.x then tg_tn_apply_pose(e, rec) end
            else
                TG_TUBENET_PIECES[e] = nil
            end
        end
    end)
end

-- ---------- local visibility boost (works on anyone's tubes, including other players' courses) ----------
TG_TN_TUBE_HASHES = nil
function tg_tn_tube_hashes()
    if TG_TN_TUBE_HASHES then return TG_TN_TUBE_HASHES end
    local set, names = {}, {}
    for _, pc in pairs(TG_TUBEP_PIECES or {}) do if pc.model then names[pc.model] = true end end
    for _, m in ipairs(TG_STUNT_TUBE_MODELS or {}) do names[m] = true end
    for name in pairs(names) do
        local h = tonumber(util.joaat(name)) or 0
        set[h] = name
        if h < 0 then set[h + 4294967296] = name else set[h - 4294967296] = name end
    end
    TG_TN_TUBE_HASHES = set
    return set
end

TG_TN_BOOSTED = TG_TN_BOOSTED or {}
function tg_tn_boost_pass()
    if not TG_TUBENET_BOOST then return 0 end
    local hashes = tg_tn_tube_hashes()
    local count = PoolMgr.GetCurrentObjectCount()
    if not count then return 0 end
    local boosted, models = 0, {}
    local chunk = TG_TUBENET_BOOST_CHUNK or 400
    local first = TG_TN_BOOST_CURSOR or 0
    if first >= count then first = 0 end
    local last = math.min(count - 1, first + chunk - 1)
    TG_TN_BOOST_CURSOR = (last + 1 >= count) and 0 or (last + 1)
    for i = first, last do
        local e = PoolMgr.GetObject(i)
        if e and e ~= 0 and not TG_TN_BOOSTED[e] then
            local m = tg_tn_int(TG_TN_H.GET_MODEL, e)
            if hashes[m] then
                tg_tn_void(TG_TN_H.SET_LOD, e, TG_TUBENET_LOD)
                tg_tn_void(TG_TN_H.LOAD_COLLISION, e, true, 0)
                TG_TN_BOOSTED[e] = true
                models[m] = true
                boosted = boosted + 1
            end
        end
    end
    -- keep every tube model we've seen resident so fast approaches don't outrun streaming
    for m in pairs(models) do tg_tn_void(TG_TN_H.REQUEST_MODEL, m) end
    for e in pairs(TG_TN_BOOSTED) do if not tg_tn_exists(e) then TG_TN_BOOSTED[e] = nil end end
    return boosted
end

function tg_tn_preload_models()
    for h in pairs(tg_tn_tube_hashes()) do
        if h >= 0 and h < 4294967296 then tg_tn_void(TG_TN_H.REQUEST_MODEL, h) end
    end
end

function tg_tn_start_keeper()
    if TG_TN_KEEPER_STARTED then return end
    if TG_PRIME_REGISTER_TICKS == false then return end
    TG_TN_KEEPER_STARTED = true
    local next_keep, next_boost = 0, 0
    local function step(now)
        if now >= next_keep then
            next_keep = now + TG_TUBENET_KEEPER_MS
            tg_tn_keeper_pass()
        end
        if now >= next_boost then
            next_boost = now + TG_TUBENET_BOOST_MS
            tg_tn_boost_pass()
        end
    end
    util.create_tick_handler(function()
        step(tg_tn_now())
        util.yield(250)
    end)
end

-- ---------- joint check (diagnostic for "invisible walls") ----------
-- Reads every stunt tube near you back from the game (your own or someone else's), works out where
-- each piece's mouths really are, and reports the worst joint. A step of more than ~0.15 m is
-- enough to catch a wheel.
function tg_tn_rot_matrix(p, r, y)
    local cp, sp = math.cos(math.rad(p)), math.sin(math.rad(p))
    local cr, sr = math.cos(math.rad(r)), math.sin(math.rad(r))
    local cy, sy = math.cos(math.rad(y)), math.sin(math.rad(y))
    -- R = Rz(y) * Rx(p) * Ry(r); columns X, Y, Z
    local X = tg_tp_v(cy * cr - sy * sp * sr, sy * cr + cy * sp * sr, -cp * sr)
    local Y = tg_tp_v(-sy * cp, cy * cp, sp)
    local Z = tg_tp_v(cy * sr + sy * sp * cr, sy * sr - cy * sp * cr, cp * cr)
    return { X = X, Y = Y, Z = Z }
end

TG_TN_MODEL_PIECE = nil
function tg_tn_model_piece(m)
    if not TG_TN_MODEL_PIECE then
        TG_TN_MODEL_PIECE = {}
        for _, pc in pairs(TG_TUBEP_PIECES or {}) do
            if pc.model then
                local h = tonumber(util.joaat(pc.model)) or 0
                TG_TN_MODEL_PIECE[h] = pc
                if h < 0 then TG_TN_MODEL_PIECE[h + 4294967296] = pc else TG_TN_MODEL_PIECE[h - 4294967296] = pc end
            end
        end
    end
    return TG_TN_MODEL_PIECE[m]
end

function tg_tn_scale(pc)
    local m = tostring(pc and pc.model or "")
    if m:find("_4x_", 1, true) then return 11.0 end
    if m:find("_2x_", 1, true) then return 5.5 end
    if m:find("ar_prop_ar_tube", 1, true) then return 2.75 end
    return 1.0
end

-- ports of a placed piece in world space: { {P, D}, {P, D} } with D pointing out of the mouth
function tg_tn_world_ports(pc, pos, rot)
    local R = tg_tn_rot_matrix(rot.x, rot.y, rot.z)
    local a, b, exit_local = tg_tp_geo(pc)
    local o = tg_tp_v(pos.x, pos.y, pos.z)
    return {
        { P = tg_tp_add(o, tg_tp_apply(R, a)), D = tg_tp_mul(tg_tp_norm(tg_tp_apply(R, tg_tp_v(1, 0, 0))), -1.0) },
        { P = tg_tp_add(o, tg_tp_apply(R, b)), D = tg_tp_norm(tg_tp_apply(R, exit_local)) }
    }
end

function tg_tube_net_check_joints()
    local list = {}
    local function add(e)
        local pc = tg_tn_model_piece(tg_tn_int(TG_TN_H.GET_MODEL, e))
        if not pc then return end
        local pos = tg_tn_v3(TG_TN_H.GET_COORDS, e, false)
        local rot = tg_tn_v3(TG_TN_H.GET_ROT, e, 2)
        if pos and rot then table.insert(list, { e = e, pc = pc, ports = tg_tn_world_ports(pc, pos, rot) }) end
    end
    local seen = {}
    for i = 0, (PoolMgr.GetCurrentObjectCount() or 0) - 1 do
        local e = PoolMgr.GetObject(i)
        if e and e ~= 0 and not seen[e] then seen[e] = true; add(e) end
    end
    if #list < 2 then tg_toast("Joint check: no stunt tubes found near you.", 3500); return end
    local joints, worst_gap, worst_ang, bad = 0, 0.0, 0.0, 0
    for i, A in ipairs(list) do
        for pa = 1, 2 do
            local best, bestd, bestang = nil, 1e9, 0.0
            for j, B in ipairs(list) do
                if j ~= i then
                    for pb = 1, 2 do
                        local d = tg_tp_dist(A.ports[pa].P, B.ports[pb].P)
                        if d < bestd then
                            bestd = d
                            local c = -tg_tp_dot(A.ports[pa].D, B.ports[pb].D)
                            bestang = math.deg(math.acos(math.max(-1.0, math.min(1.0, c))))
                            best = j
                        end
                    end
                end
            end
            -- only count ports that are meant to be joined (a few metres apart at most)
            if best and bestd < 4.0 * tg_tn_scale(A.pc) then
                joints = joints + 1
                if bestd > worst_gap then worst_gap = bestd end
                if bestang > worst_ang then worst_ang = bestang end
                if bestd > 0.15 or bestang > 0.5 then bad = bad + 1 end
            end
        end
    end
    joints = math.floor(joints / 2)
    bad = math.floor((bad + 1) / 2)
    local msg = string.format("Joint check: %d tubes, %d joints. Worst step %.2f m, worst angle %.2f deg. %s",
        #list, joints, worst_gap, worst_ang, (bad > 0) and (tostring(bad) .. " joint(s) out of line - press Re-Sync Course (builder)") or "All joints line up.")
    tg_log("[TUBE_NET][JOINTS] " .. msg)
    tg_toast(msg, 7000)
end

-- ---------- buttons ----------
function tg_tube_net_resync()
    local function run()
        local okn, total = tg_tn_settle_all("re-sync")
        tg_toast(string.format("Re-synced %d tube pieces (%d networked for everyone%s).", total, okn,
            tg_tn_in_session() and "" or " - not in an online session"), 4500)
    end
    if not tg_tn_freemode_job("resync", run) then run() end
end

function tg_tube_net_status()
    local alive, flagged = 0, 0
    for e, rec in pairs(TG_TUBENET_PIECES) do
        if tg_tn_exists(e) then
            alive = alive + 1
            if rec.flagged and tg_tn_bool(TG_TN_H.IS_NETWORKED, e) then flagged = flagged + 1 end
        end
    end
    tg_toast(string.format("Tube network: %d/%d pieces networked for everyone. Session: %s. Freemode context: %s. Boost: %s.",
        flagged, alive, tg_tn_in_session() and "online" or "offline",
        TG_TUBENET_FREEMODE and "ON" or "OFF", TG_TUBENET_BOOST and "ON" or "OFF"), 6000)
end

function tg_tube_net_toggle_boost()
    TG_TUBENET_BOOST = not TG_TUBENET_BOOST
    TG_TN_BOOSTED = {}
    tg_toast("Tube Visibility Boost: " .. (TG_TUBENET_BOOST and "ON (long draw distance + models kept loaded for every stunt tube near you)" or "OFF"), 4000)
end

function tg_tube_net_toggle_freemode()
    TG_TUBENET_FREEMODE = not TG_TUBENET_FREEMODE
    tg_toast("Build in freemode context: " .. (TG_TUBENET_FREEMODE and "ON (others see the whole course)" or "OFF (old behaviour)"), 4000)
end

-- run builders inside the freemode context (they re-enter themselves as a freemode job)
TG_TN_WRAPPED = TG_TN_WRAPPED or {}
function tg_tn_wrap(name, f)
    if not f or TG_TN_WRAPPED[name] then return f end
    local wrapped = function(...)
        local n = select("#", ...)
        local args = { ... }
        if tg_tn_freemode_job(name, function() f(table.unpack(args, 1, n)) end) then return true end
        return f(...)
    end
    TG_TN_WRAPPED[name] = true
    return wrapped
end
tg_tube_race_build = tg_tn_wrap("tg_tube_race_build", tg_tube_race_build)
tg_tube_course_build = tg_tn_wrap("tg_tube_course_build", tg_tube_course_build)
tg_tube_circuit_build = tg_tn_wrap("tg_tube_circuit_build", tg_tube_circuit_build)
tg_tube_shape_random_course = tg_tn_wrap("tg_tube_shape_random_course", tg_tube_shape_random_course)
tg_tube_shape_knot = tg_tn_wrap("tg_tube_shape_knot", tg_tube_shape_knot)
tg_tube_shape_loop = tg_tn_wrap("tg_tube_shape_loop", tg_tube_shape_loop)
tg_tube_shape_corkscrew = tg_tn_wrap("tg_tube_shape_corkscrew", tg_tube_shape_corkscrew)
tg_tube_shape_spiral = tg_tn_wrap("tg_tube_shape_spiral", tg_tube_shape_spiral)
tg_tube_build_start = tg_tn_wrap("tg_tube_build_start", tg_tube_build_start)
tg_tube_build_add = tg_tn_wrap("tg_tube_build_add", tg_tube_build_add)
-- ═══════════════════════════════════════════════════════════════════════════════════
-- trackmatic core (v2.0): object limits, safe entity spawn, reliable spawning, build progress hud
-- ═══════════════════════════════════════════════════════════════════════════════════
RS_NAME = "TrackMatic"
TG_RS = TG_RS or { safe = true, limits = { tubes = 73, parkour = 73, hybrid = 73, tracks = 60 }, track_user = false }
for k, v in pairs(TG_RS.limits) do if v > 80 then TG_RS.limits[k] = 80 end end

-- v2.0.6: 80 objects is the absolute maximum for every builder (online, other players can't see
-- more than that anyway). There is no way to go past it.
TG_RS_ABSOLUTE_MAX = 80
function tg_rs_hardmax() return TG_RS_ABSOLUTE_MAX end
function tg_rs_limit(kind)
    local v = tonumber(TG_RS.limits[kind] or 73) or 73
    return math.max(10, math.min(v, tg_rs_hardmax()))
end
function tg_rs_set_limit(kind, v)
    TG_RS.limits[kind] = math.max(10, math.min(math.floor(tonumber(v) or 73), tg_rs_hardmax()))
    if kind == "tracks" then TG_RS.track_user = true; tg_rs_apply_track_limit() end
end
function tg_rs_toggle_safe()
    TG_RS.safe = true
    for k in pairs(TG_RS.limits) do TG_RS.limits[k] = math.min(TG_RS.limits[k], tg_rs_hardmax()) end
    tg_toast("TrackMatic: the object limit is fixed at 80 maximum.", 3000)
    do return end
    for k in pairs(TG_RS.limits) do TG_RS.limits[k] = math.min(TG_RS.limits[k], tg_rs_hardmax()) end
    tg_rs_apply_track_limit()
    local online = tg_tn_in_session()
    tg_toast("Safe Entity Spawn: " .. (TG_RS.safe and "ON (hard max 90 objects)" or
        (online and "OFF (hard max 500) - other players only see 90 objects: anything past 90 is visible to you only" or "OFF (hard max 500 objects)")), 6000)
end
-- road tracks (the original generator) follow the same cap
function tg_rs_apply_track_limit()
    local cap = tg_rs_hardmax()
    if TG_RS.track_user then
        total_max_fragement = tg_rs_limit("tracks")
        current_max_fragement = total_max_fragement
    else
        -- remember the generator's own online/offline defaults so turning Safe OFF gives them back
        if not TG_RS.track_orig or (total_max_fragement and total_max_fragement ~= TG_RS.track_applied) then
            TG_RS.track_orig = { total_max_fragement or 60, current_max_fragement or 60 }
        end
        total_max_fragement = math.min(TG_RS.track_orig[1], cap)
        current_max_fragement = math.min(TG_RS.track_orig[2], cap)
        TG_RS.track_applied = total_max_fragement
    end
end

-- ---------- cancel: Clear Track stops builds that are still planning / spawning / queued ----------
-- every build job remembers the clear generation it started in (TG_RS_JOB_GEN, keyed by the job's
-- coroutine). Clear Track bumps TG_RS_CANCEL_GEN, so tg_rs_cancelled() turns true for every job that
-- started before it. builders check it in their loops and return early: planners return nil,
-- spawn loops stop, and entities.create_object refuses to spawn for a cancelled job.
TG_RS_CANCEL_GEN = TG_RS_CANCEL_GEN or 0
TG_RS_RUN_GEN = TG_RS_RUN_GEN or nil
TG_RS_JOB_GEN = TG_RS_JOB_GEN or setmetatable({}, { __mode = "k" })
function tg_rs_job_begin(gen)
    TG_RS_JOB_GEN[coroutine.running()] = gen or TG_RS_CANCEL_GEN
end
function tg_rs_build_start(label)
    TG_RS_RUN_GEN = TG_RS_CANCEL_GEN
    TG_RS_JOB_GEN[coroutine.running()] = TG_RS_CANCEL_GEN
end
-- only jobs that registered (queued builds, freemode jobs, anything that called tg_rs_build_start)
function tg_rs_job_cancelled()
    local gen = TG_RS_JOB_GEN[coroutine.running()]
    return gen ~= nil and gen ~= TG_RS_CANCEL_GEN
end
function tg_rs_cancelled()
    local gen = TG_RS_JOB_GEN[coroutine.running()]
    if gen == nil then gen = TG_RS_RUN_GEN end
    return gen ~= nil and gen ~= TG_RS_CANCEL_GEN
end
-- call inside builder loops: true when this build was cancelled (the caller returns / breaks)
function tg_rs_check_cancel()
    return tg_rs_cancelled()
end
function tg_rs_cancel_all(reason)
    TG_RS_CANCEL_GEN = TG_RS_CANCEL_GEN + 1
    tg_log("[TRACKMATIC][CANCEL] all builds cancelled (" .. tostring(reason) .. ")")
end

-- ---------- v2.2.4 crash trace ----------
-- For a short window after a Creator / Lab plan ends, every game native TrackMatic calls is written
-- to the Cherax log (consecutive repeats collapsed), plus every HUD frame and Creator / Lab panel
-- render. If the game ever "fails fast" again, the last [TRACE] lines name the exact call.
TG_RS_TRACE_UNTIL = TG_RS_TRACE_UNTIL or 0
TG_PM_TRACE_ENABLED = false -- avoid wrapping every native during normal operation
TG_RS_TRACE_LAST, TG_RS_TRACE_REP = nil, 0
function tg_rs_tracing() return TG_PM_TRACE_ENABLED == true and util.current_time_millis() < (TG_RS_TRACE_UNTIL or 0) end
function tg_rs_trace(what)
    if not tg_rs_tracing() then return end
    if what == TG_RS_TRACE_LAST then TG_RS_TRACE_REP = TG_RS_TRACE_REP + 1; return end
    if TG_RS_TRACE_REP > 0 and tg_log then tg_log(string.format("[TRACE] (x%d more)", TG_RS_TRACE_REP)) end
    TG_RS_TRACE_LAST, TG_RS_TRACE_REP = what, 0
    tg_log("[TRACE] " .. tostring(what))
end
function tg_rs_trace_start(ms, why)
    if not TG_PM_TRACE_ENABLED then return end
    TG_RS_TRACE_UNTIL = util.current_time_millis() + (ms or 15000)
    TG_RS_TRACE_LAST = nil
    tg_log("[TRACE] window open " .. tostring(why))
end
-- ---------- build progress (HUD bar at the bottom of the screen) ----------
TG_RS_PROG = TG_RS_PROG or { active = false }
-- returns true when the build was cancelled, so loops can stop: if tg_rs_progress(...) then return end
function tg_rs_progress(label, frac, msg)
    if tg_rs_check_cancel() then return true end
    tg_rs_start_hud()
    local p = TG_RS_PROG
    if not p.active or p.label ~= label then
        p.t0 = util.current_time_millis()
        if not p.queued then p.tab = (TG_UI_ACTIVE_TAB == "Creator") and "Track" or TG_UI_ACTIVE_TAB end
    end
    p.active, p.label, p.frac, p.msg = true, label, math.max(0.0, math.min(1.0, frac or 0.0)), msg or ""
    p.touched = util.current_time_millis()
    p.queued, p.done_at, p.failed = nil, nil, nil
    p.stage = TG_RS_STAGE
    return false
end
function tg_rs_progress_done(msg)
    local p = TG_RS_PROG
    local B = TG_RS_BUILD
    if B and B.full then
        tg_rs_diag("BUILD END (budget full) " .. tostring(msg))
        p.active, p.failed, p.done_at = true, true, util.current_time_millis()
        p.msg = string.format("Lobby object budget full - stopped safely at %d objects (%s)", B.spawned or 0, tostring(msg or ""))
        return
    end
    if B and B.label then tg_rs_diag("BUILD END " .. tostring(msg)) end
    TG_RS_RUN_GEN = nil
    TG_RS_JOB_GEN[coroutine.running()] = nil
    if p.active then p.frac, p.msg, p.done_at = 1.0, msg or "Done", util.current_time_millis() end
end
function tg_rs_progress_fail(msg)
    local p = TG_RS_PROG
    p.active, p.frac, p.msg, p.failed, p.done_at = true, p.frac or 0, msg or "Failed", true, util.current_time_millis()
end
-- planning share of the bar is 0..0.35, spawning 0.35..1.0
function tg_rs_plan_progress(label, attempt, attempts, placed, target)
    local f = ((attempt - 1) + math.min(1.0, (placed or 0) / math.max(1, target or 1))) / math.max(1, attempts)
    return tg_rs_progress(label, 0.35 * f, string.format("Planning  %d/%d", placed or 0, target or 0))
end
function tg_rs_spawn_progress(label, i, n, what)
    return tg_rs_progress(label, 0.35 + 0.65 * (i / math.max(1, n)), string.format("%s  %d/%d", what or "Spawning", i, n))
end
-- count objects from ANY builder (original road tracks too) so something always shows
TG_RS_SPAWN_COUNT = TG_RS_SPAWN_COUNT or 0
if tg_stable_spawn_finalize and not TG_RS_FINALIZE_WRAPPED then
    TG_RS_FINALIZE_WRAPPED = true
    local orig = tg_stable_spawn_finalize
    tg_stable_spawn_finalize = function(entity, x, y, z, label)
        if label == "post_track_create" then
            tg_rs_start_hud()
            TG_RS_SPAWN_COUNT = TG_RS_SPAWN_COUNT + 1
            local p = TG_RS_PROG
            local starting = (p.frac == 0 and (p.msg == "Starting" or p.queued))
            if not p.active or starting or (p.label == "Building" and (util.current_time_millis() - (p.touched or 0)) < 4000) or (p.done_at and (util.current_time_millis() - p.done_at) > 3000) then
                p.queued = nil
                if not p.active or p.label ~= "Building" then p.base = TG_RS_SPAWN_COUNT - 1 end
                p.active, p.label, p.frac, p.done_at, p.failed = true, "Building", -1, nil, nil
                p.msg = string.format("%d objects placed", TG_RS_SPAWN_COUNT - (p.base or 0))
                p.touched = util.current_time_millis()
                p.t0 = p.t0 or p.touched
            end
        end
        return orig(entity, x, y, z, label)
    end
end
-- queued (waiting for a native job slot) - shown the moment you press a build button.
-- Never starts the HUD tick here (this can run inside a UI render callback); the job starts it.
function tg_rs_queued(label)
    local p = TG_RS_PROG
    local now = util.current_time_millis()
    p.active, p.label, p.frac, p.msg, p.t0, p.touched = true, label or "Build", 0.0, "Queued", now, now
    p.tab = TG_RS_NEXT_TAB or ((TG_UI_ACTIVE_TAB == "Creator") and "Track" or TG_UI_ACTIVE_TAB)
    p.done_at, p.failed, p.queued = nil, nil, true
end
TG_RS_QUEUE_WORDS = { "build", "random", "start", "generate", "spawn", "play", "course", "race", "again", "loop", "track", "load", "minigame", "arcade", "parkour", "hybrid", "tube", "eliminator", "climb", "drifter", "spiral", "switchback", "sprint" }
if tg_ui_queue_action and not TG_RS_QUEUE_WRAPPED then
    TG_RS_QUEUE_WRAPPED = true
    local orig = tg_ui_queue_action
    tg_ui_queue_action = function(label, callback)
        local l = string.lower(tostring(label or ""))
        local show = false
        if not string.find(l, "clear", 1, true) and not string.find(l, "stop", 1, true) then
            for _, w in ipairs(TG_RS_QUEUE_WORDS) do if string.find(l, w, 1, true) then show = true; break end end
        end
        if show and type(callback) == "function" then
            tg_rs_queued(tostring(label))
            local inner = callback
            local gen_at_press = TG_RS_CANCEL_GEN
            callback = function()
                if TG_RS_CANCEL_GEN ~= gen_at_press then
                    tg_log("[TRACKMATIC][CANCEL] skipped queued '" .. tostring(label) .. "' (cleared before it started)")
                    return
                end
                tg_rs_job_begin(gen_at_press)
                tg_rs_start_hud()
                local p = TG_RS_PROG
                if p.queued and p.label == tostring(label) then p.queued = nil; p.msg = "Starting"; p.touched = util.current_time_millis() end
                inner()
                if tg_rs_cancelled() then
                    tg_log("[TRACKMATIC][CANCEL] '" .. tostring(label) .. "' stopped by Clear Track")
                    return
                end
                if p.active and not p.done_at and not p.queued and p.label == tostring(label) then
                    -- the action never reported progress itself (quick toggles etc.)
                    tg_rs_progress_done("Done")
                end
            end
        end
        return orig(label, callback)
    end
end

function tg_rs_draw_text(text, x, y, scale, r, g, b, a, center)
    tg_tn_void(0x66E0276CC5F6B9DA, 4)                       -- SET_TEXT_FONT
    tg_tn_void(0x07C837F9A01C34C9, 0.0, scale + 0.0)        -- SET_TEXT_SCALE
    tg_tn_void(0xBE6B23FFA53FB442, r, g, b, a)              -- SET_TEXT_COLOUR
    tg_tn_void(0xC02F4DBFB51D988B, center and true or false) -- SET_TEXT_CENTRE
    tg_tn_void(0x2513DFB0FB8400FE)                          -- SET_TEXT_OUTLINE
    tg_tn_void(0x25FBB336DF1804CB, "STRING")                -- BEGIN_TEXT_COMMAND_DISPLAY_TEXT
    tg_tn_void(0x6C188BE134E074AA, text)                    -- ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME
    tg_tn_void(0xCD015E5BB0D96A57, x + 0.0, y + 0.0, 0)     -- END_TEXT_COMMAND_DISPLAY_TEXT
end
function tg_rs_draw_rect(x, y, w, h, r, g, b, a)
    tg_tn_void(0x3A618A217E5154F0, x + 0.0, y + 0.0, w + 0.0, h + 0.0, math.floor(r), math.floor(g), math.floor(b), math.floor(a), false)
end

TG_RS_HUD = (TG_RS_HUD ~= false)
function tg_rs_hud_frame()
    local p = TG_RS_PROG
    if not TG_RS_HUD or not p.active then return end
    tg_rs_trace("hud frame")
    local now = util.current_time_millis()
    if p.done_at and now - p.done_at > 3500 then p.active = false; return end
    if p.label == "Building" and not p.done_at and now - (p.touched or now) > 3000 then p.done_at = now; p.msg = (p.msg or "") .. " - done" end
    -- a builder that died without reporting: don't leave the bar up forever
    if not p.done_at and now - (p.touched or now) > (p.queued and 180000 or 45000) then p.done_at = now; p.msg = (p.msg or "") .. " (no update - stopped?)" end
    local secs = (now - (p.t0 or now)) / 1000.0
    -- v2.3.0: the corner HUD (ON_PRESENT, ImGui background layer) draws it - no natives per frame
    if tg_rs_card_live() then return end
    local x, y, w, h = 0.5, 0.925, 0.36, 0.022
    tg_rs_draw_rect(x, y, w + 0.006, h + 0.05, 10, 8, 18, 190)
    local f = p.frac or 0
    if f < 0 then f = (now % 1600) / 1600.0 end      -- unknown total: moving sweep
    local cr, cg, cb = 255, 196, 0                       -- Neo yellow
    if p.failed then cr, cg, cb = 255, 60, 60 elseif p.done_at then cr, cg, cb = 90, 230, 120 end
    tg_rs_draw_rect(x, y + 0.012, w, h * 0.55, 45, 40, 60, 230)
    if (p.frac or 0) < 0 then
        tg_rs_draw_rect(x - w / 2 + w * f, y + 0.012, w * 0.18, h * 0.55, cr, cg, cb, 255)
    else
        tg_rs_draw_rect(x - w / 2 + (w * f) / 2, y + 0.012, w * f, h * 0.55, cr, cg, cb, 255)
    end
    local pct = ((p.frac or 0) >= 0) and string.format("%d%%  ", math.floor(f * 100 + 0.5)) or ""
    tg_rs_draw_text(string.format("TrackMatic  |  %s  |  %s%s  (%.0fs)", tostring(p.label), pct, tostring(p.msg or ""), secs), x, y - 0.022, 0.32, 255, 255, 255, 255, true)
end
-- started on first use (never during script load: keeps Prime start-up exactly as before)
function tg_rs_start_hud()
    if TG_RS_HUD_STARTED or TG_PRIME_REGISTER_TICKS == false then return end
    if tg_tn_in_freemode_job() then return end      -- never register a tick from inside the freemode script context
    TG_RS_HUD_STARTED = true
    tg_rs_present_register()
    util.create_tick_handler(function()
        tg_rs_late_init()
        tg_rs_hud_frame()
        util.yield(0)
        return true
    end)
end

-- ---------- reliable spawning ----------
-- Arena / Arena 2x / Arena 4x models are huge: they must be streamed in BEFORE the object is created,
-- otherwise the create fails (piece skipped) or the object exists without a model (invisible).
TG_RS_MODEL_LOADED = TG_RS_MODEL_LOADED or {}
-- v2.0.2: NO manual model streaming. Calling REQUEST_MODEL / HAS_MODEL_LOADED from the build job
-- (it runs inside the freemode script context) made GTA "fail fast" (crash) - see the 16:19 / 16:30 /
-- 16:55 crash logs. GTA.CreateObject requests models itself, exactly like v1.4 did, so these are no-ops.
function tg_rs_model_loaded(h) return true end
function tg_rs_load_model(model, timeout_ms) return true end

-- ---------- build breadcrumbs (crash diagnostics) ----------
-- Rolling log of the last steps of every build, rewritten after each step, so if the game
-- hard-crashes the last line shows exactly what TrackMatic was doing:
--   <Cherax>\Lua\TrackMatic\trackmatic_build_diag.log
TG_RS_DIAG_LINES = TG_RS_DIAG_LINES or {}
TG_PM_DIAG_FILE_ENABLED = false -- no per-piece disk writes in production mode
function tg_rs_diag(msg)
    if not TG_PM_DIAG_FILE_ENABLED then return end
    local t = TG_RS_DIAG_LINES
    table.insert(t, string.format("[%s] %s", tostring(util.current_time_millis()), tostring(msg)))
    while #t > 120 do table.remove(t, 1) end
    if tg_prime_diag_file_path then
        local _, dir = tg_prime_diag_file_path()
        if dir then FileMgr.WriteFileContent(dir .. "\\trackmatic_build_diag.log", table.concat(t, "\n") .. "\n", false) end
    end
    tg_log("[TRACKMATIC][DIAG] " .. tostring(msg))
end

-- ---------- per-build spawn guard ----------
-- GTA Online only lets a session hold so many networked script objects (other players' props count
-- too). Going past it can crash the game instead of failing politely, so every build checks the
-- budget before each object and stops cleanly when it is full.
TG_RS_BUILD = TG_RS_BUILD or { spawned = 0, failed = 0, streak = 0, full = false, dynamic = 0 }
TG_RS_MAX_DYNAMIC_ONLINE = TG_RS_MAX_DYNAMIC_ONLINE or 10
function tg_rs_build_begin(label, planned)
    TG_RS_BUILD = { label = label, spawned = 0, failed = 0, streak = 0, full = false, dynamic = 0, planned = planned or 0,
                    online = tg_tn_in_session() or false, can_reg = nil }
    tg_rs_diag(string.format("BUILD BEGIN %s planned=%d online=%s safe=%s limit_tubes=%d limit_parkour=%d limit_hybrid=%d existing_objects=%d",
        tostring(label), planned or 0, tostring(TG_RS_BUILD.online), tostring(TG_RS.safe), tg_rs_limit("tubes"), tg_rs_limit("parkour"), tg_rs_limit("hybrid"), #objects))
end
-- true = the session can take one more networked object (or we can't tell)
function tg_rs_budget_ok()
    local b = TG_RS_BUILD
    if b.full then return false end
    if not b.online then return true end
    if b.can_reg == "ignore" then return true end
    local r = Natives.InvokeBool(0x800DD4721A8B008B, 1)            -- CAN_REGISTER_MISSION_OBJECTS
    if r == nil then b.can_reg = "ignore"; return true end
    local yes = (r == true) or (type(r) == "number" and r ~= 0)
    if not yes and b.spawned == 0 then b.can_reg = "ignore"; return true end -- says "no" before anything: not tracking us
    if not yes then
        b.full = true
        tg_rs_diag("BUDGET FULL (CAN_REGISTER_MISSION_OBJECTS=false) after " .. tostring(b.spawned) .. " objects")
    end
    return yes
end
function tg_rs_budget_stop_msg()
    local b = TG_RS_BUILD
    if b.full and not b.told then
        b.told = true
        tg_toast(string.format("TrackMatic: the lobby's object budget is full - stopped safely at %d objects. Lower the object limit (73 is safe).", b.spawned), 7000)
        tg_rs_progress_fail(string.format("Lobby object budget full - stopped safely at %d objects", b.spawned))
    end
end

-- preload every model a course needs, with progress
function tg_rs_preload(label, list)
    tg_rs_build_begin(label, #(list or {}))
    local seen, models = {}, {}
    for _, p in ipairs(list or {}) do if p.model and not seen[p.model] then seen[p.model] = true; table.insert(models, p.model) end end
    tg_rs_progress(label, 0.35, string.format("Starting spawn (%d models)", #models))
    tg_rs_diag("spawn start: " .. tostring(#models) .. " models")
end
if tg_try_create_stunt_tube_model and not TG_RS_CREATE_WRAPPED then
    TG_RS_CREATE_WRAPPED = true
    TG_RS_ORIG_CREATE = tg_try_create_stunt_tube_model
    tg_try_create_stunt_tube_model = function(model, x, y, z, heading, label)
        local b = TG_RS_BUILD
        if tg_rs_cancelled() then return nil end
        if not tg_rs_budget_ok() then tg_rs_budget_stop_msg(); return nil end
        tg_rs_diag(string.format("spawn #%d %s (%s)", b.spawned + 1, tostring(model), tostring(label)))
        for attempt = 1, 2 do
            local obj = TG_RS_ORIG_CREATE(model, x, y, z, heading, label)
            if obj and obj ~= 0 then
                b.spawned, b.streak = b.spawned + 1, 0
                return obj
            end
            if attempt == 2 then break end
            -- big Arena / Mega models can still be streaming on the first try: wait a moment, try once more
            tg_rs_diag("retry " .. tostring(model))
            util.yield(250)
        end
        b.failed, b.streak = b.failed + 1, b.streak + 1
        tg_rs_diag("spawn FAILED " .. tostring(model) .. " streak=" .. tostring(b.streak))
        -- (v2.0.3: a failure is NOT treated as "lobby full" any more - big Arena / Mega models often
        -- fail the first time while they stream in; the builders' repair passes fill those gaps)
        return nil
    end
end

-- ---------- clear everything ----------
function tg_rs_clear_all()
    tg_rs_cancel_all("Clear Track")
    do  -- v2.3.2: the progress card shows the clear too
        local p0 = TG_RS_PROG
        local now0 = util.current_time_millis()
        p0.active, p0.label, p0.frac, p0.msg, p0.done_at, p0.failed, p0.queued, p0.stage = true, "Clear Track", -1, "Clearing track", nil, nil, nil, "Clearing track"
        p0.t0, p0.touched = now0, now0
        p0.tab = p0.tab or "Home"
    end
    tg_rs_late_init()
    if TG_AR and TG_AR.active then TG_AR.active.active = false end
    if TG_PK_STATE then TG_PK_STATE.active = false end
    if TG_TUBEC_TIMER then TG_TUBEC_TIMER.active = false end
    if TG_TUBENET_PIECES then for k in pairs(TG_TUBENET_PIECES) do TG_TUBENET_PIECES[k] = nil end end
    clear_race_track("clear")
    local p = TG_RS_PROG
    p.active, p.label, p.frac, p.msg, p.done_at, p.failed, p.queued, p.stage = true, "Clear Track", 1.0, "Track cleared", util.current_time_millis(), nil, nil, nil
    p.t0 = p.t0 or util.current_time_millis()
    tg_toast("TrackMatic: track cleared (and any build in progress cancelled).", 2500)
    -- a piece that was mid-spawn when you pressed Clear: sweep again a moment later
    util.yield(1500)
    if #objects > 0 and not (TG_RS_RUN_GEN == TG_RS_CANCEL_GEN) then clear_race_track("clear_sweep") end
end
-- keep the road-track cap applied after every clear (clear_race_track is defined later in the
-- script than this module, so the wrap happens on first use)
function tg_rs_late_init()
    if TG_RS_CLEAR_WRAPPED or not clear_race_track then return end
    TG_RS_CLEAR_WRAPPED = true
    local orig = clear_race_track
    clear_race_track = function(action)
        -- the baseline's own Clear / End buttons cancel TrackMatic builds too
        if action == "clear" or action == "end" or action == "clear_track" then
            if tg_rs_cancelled and not tg_rs_cancelled() and TG_RS_RUN_GEN then tg_rs_cancel_all(action) end
        end
        local r = orig(action)
        tg_rs_apply_track_limit()
        return r
    end
    tg_rs_apply_track_limit()
end

-- ---------- fast overlap pre-check (500-object courses) ----------
function tg_rs_bounds(plan)
    if plan._br then return plan._bc, plan._br end
    local s = plan.samples
    if not s or #s == 0 then plan._bc, plan._br = tg_tp_v(0, 0, -1e9), 0.0; return plan._bc, plan._br end
    local cx, cy, cz = 0, 0, 0
    for _, q in ipairs(s) do cx, cy, cz = cx + q.x, cy + q.y, cz + q.z end
    local c = tg_tp_v(cx / #s, cy / #s, cz / #s)
    local r = 0.0
    for _, q in ipairs(s) do r = math.max(r, tg_tp_dist(q, c)) end
    plan._bc, plan._br = c, r
    return c, r
end
-- true when two pieces are certainly further apart than `clear`
function tg_rs_far(a, b, clear)
    local ca, ra = tg_rs_bounds(a)
    local cb, rb = tg_rs_bounds(b)
    local d = clear + ra + rb
    local dx, dy, dz = ca.x - cb.x, ca.y - cb.y, ca.z - cb.z
    return dx * dx + dy * dy + dz * dz > d * d
end

-- ---------- UI helpers ----------
function tg_rs_limit_step(kind, d) tg_rs_set_limit(kind, tg_rs_limit(kind) + d); tg_toast(string.format("%s object limit: %d (hard max %d)", kind, tg_rs_limit(kind), tg_rs_hardmax()), 2500) end

-- scale a {min,max} count range for a chosen object limit (73 = the tuned default)
function tg_rs_scale_range(r, limit, cap)
    local f = limit / 73.0
    local a = math.max(2, math.floor(r[1] * f + 0.5))
    local b = math.max(a, math.floor(r[2] * f + 0.5))
    if cap then a, b = math.min(a, cap), math.min(b, cap) end
    return a, b
end

-- 100-entry pickers: pages of buttons with < Prev / Next > (keeps the panel short)
TG_RS_PAGES = TG_RS_PAGES or {}
function tg_rs_paged_row(title, id, options, current, on_pick, per_row, width, page_size)
    page_size = page_size or 20
    local pages = math.max(1, math.ceil(#options / page_size))
    local pg = TG_RS_PAGES[id]
    if not pg then
        pg = 1
    end
    pg = math.max(1, math.min(pg, pages))
    TG_RS_PAGES[id] = pg
    local cur_name = nil
    for _, o in ipairs(options) do if o[1] == current then cur_name = o[2] end end
    if title then ImGui.Text(string.format("%s  -  selected: %s", title, tostring(cur_name or "-"))) end
    if pages > 1 then
        local c1 = ImGui.Button("< Prev##pg_" .. id, 90, 26)
        if c1 then TG_RS_PAGES[id] = (pg - 2) % pages + 1 end
        ImGui.SameLine()
        ImGui.Text(string.format(" Page %d / %d ", pg, pages))
        ImGui.SameLine()
        local c2 = ImGui.Button("Next >##pg_" .. id, 90, 26)
        if c2 then TG_RS_PAGES[id] = pg % pages + 1 end
    end
    local slice = {}
    for i = (pg - 1) * page_size + 1, math.min(#options, pg * page_size) do table.insert(slice, options[i]) end
    tg_ui_choice_row(nil, id, slice, current, on_pick, per_row, width)
end

-- ---------- world height map (buildings + terrain, everywhere) ----------
-- The building probe only "sees" collision that is streamed in near the player, so far parts of big
-- courses could still go through buildings or under hills. GTA's static height map
-- (GET_APPROX_HEIGHT_FOR_POINT - the one flying AI uses) covers the whole map with no streaming.
TG_RS_HEIGHTMAP = (TG_RS_HEIGHTMAP ~= false)
TG_RS_HEIGHTMAP_COURSES = (TG_RS_HEIGHTMAP_COURSES == true)   -- v2.0.4: parkour / hybrid don't use it (they were fine)
TG_RS_HCACHE = TG_RS_HCACHE or {}
function tg_rs_height(x, y)
    if not TG_RS_HEIGHTMAP then return nil end
    -- v2.2.4: only ever ask about points on the map
    if type(x) ~= "number" or type(y) ~= "number" or x ~= x or y ~= y or x < -4200 or x > 4600 or y < -4200 or y > 8600 then return nil end
    local k = math.floor(x / 16) .. ":" .. math.floor(y / 16)
    local c = TG_RS_HCACHE[k]
    if c ~= nil then return c or nil end
    local h = nil
    if TG_RS_HEIGHT_FN then
        h = TG_RS_HEIGHT_FN(x, y)
    else
        h = tonumber(Natives.InvokeFloat(0x29C24BFBED8AB8FB, x + 0.0, y + 0.0))      -- GET_APPROX_HEIGHT_FOR_POINT
    end
    if not h or h ~= h or h < -200.0 or h > 2500.0 then h = nil end
    TG_RS_HCACHE[k] = h or false
    return h
end
-- true when point p (with `below` metres of body under it) is inside the height map + margin
-- near the player the real collision is loaded and the building probe is exact; the coarse height map
-- is used further out (TG_RS_NEAR = { P = player position, r = radius } set by each planner)
function tg_rs_below_world(p, below, margin)
    local n = TG_RS_NEAR
    if n and n.P then
        local dx, dy = p.x - n.P.x, p.y - n.P.y
        if dx * dx + dy * dy < (n.r or 220.0) * (n.r or 220.0) then return false end
    end
    local h = tg_rs_height(p.x, p.y)
    return h ~= nil and (p.z - (below or 0.0)) < h + (margin or 0.0)
end

-- ---------- repair passes: fill pieces that failed to spawn (big tube models still streaming) ----------
-- missed = list of plans; spawn_fn(plan, k) -> handle or nil. Up to 5 passes, waiting longer each time.
function tg_rs_repair(label, missed, spawn_fn)
    local fixed = 0
    for pass = 1, 5 do
        if #missed == 0 or (TG_RS_BUILD and TG_RS_BUILD.full) then break end
        if tg_rs_progress(label, 0.97, string.format("Filling %d gap(s) - pass %d / 5", #missed, pass)) then return fixed, 0 end
        tg_rs_diag(string.format("repair pass %d: %d missing", pass, #missed))
        util.yield(700 * pass)
        if tg_rs_check_cancel() then return fixed, 0 end
        local still = {}
        for k, plan in ipairs(missed) do
            if tg_rs_check_cancel() then return fixed, 0 end
            if spawn_fn(plan, k) then fixed = fixed + 1 else table.insert(still, plan) end
            util.yield(60)
        end
        missed = still
    end
    if #missed > 0 then
        tg_rs_diag(string.format("repair gave up on %d piece(s)", #missed))
        tg_toast(string.format("TrackMatic: %d piece(s) wouldn't spawn - press 'Re-Sync Course' or rebuild.", #missed), 6000)
    end
    return fixed, #missed
end
-- highest height-map point along a line ahead of P (direction psi), between d0 and d1 metres
function tg_rs_height_ahead(P, psi, d0, d1)
    local best = nil
    for d = d0, d1, 40 do
        local h = tg_rs_height(P.x + math.cos(psi) * d, P.y + math.sin(psi) * d)
        if h and (not best or h > best) then best = h end
    end
    return best
end
-- a descent ramp tile must not end inside a building (height map well above the real ground)
function tg_rs_descent_blocked(P, ground)
    local n = TG_RS_NEAR
    if n and n.P then
        local dx, dy = P.x - n.P.x, P.y - n.P.y
        if dx * dx + dy * dy < (n.r or 220.0) * (n.r or 220.0) then return false end
    end
    local h = tg_rs_height(P.x, P.y)
    return h ~= nil and P.z < h - 2.0 and (not ground or h > ground + 4.0)
end
-- ═══════════════════════════════════════════════════════════════════════════════════
-- trackmatic v2.3.0 ui: radius, difficulty groups, style picker, corner progress hud
-- ═══════════════════════════════════════════════════════════════════════════════════

-- ---------- radius (Tubes, Track, Parkour, Hybrid, Lab) ----------
-- 0 = unlimited. Every builder keeps the whole course inside a circle of this radius round you.
TG_RS_RADIUS = TG_RS_RADIUS or { tubes = 0, creator = 0, parkour = 0, hybrid = 0, lab = 0 }
TG_RS_RADIUS_OPTS = { { 0, "Unlimited" }, { 300, "300 m" }, { 500, "500 m" }, { 1000, "1 km" }, { 2000, "2 km" } }
function tg_rs_radius(kind)
    kind = TG_RS_RADIUS_AS or kind
    local r = tonumber(TG_RS_RADIUS[kind] or 0) or 0
    if r <= 0 then return nil end
    return r
end

-- ---------- difficulty groups ----------
TG_RS_TIERS = { { "all", "All" }, { "easy", "Easy" }, { "medium", "Medium" }, { "hard", "Hard" } }
TG_RS_TIER_RGB = { easy = { 0.30, 0.85, 0.45 }, medium = { 1.0, 0.77, 0.0 }, hard = { 1.0, 0.30, 0.25 } }
TG_RS_TAG_NAMES = { tight = "Tight", flowing = "Flowing", twisty = "Twisty", hilly = "Hilly", jumps = "Jumps", fast = "Fast",
                    vertical = "Vertical", rolls = "Rolls", loops = "Loops", norail = "No rails", gaps = "Long gaps", climbs = "Climbs", drops = "Drops", short = "Short hops" }
TG_RS_TAG_ORDER = { "tight", "flowing", "twisty", "hilly", "vertical", "rolls", "loops", "jumps", "gaps", "climbs", "drops", "short", "norail", "fast" }

-- rank a list of { key, score, tags } into thirds (easy / medium / hard)
function tg_rs_rank(list)
    table.sort(list, function(a, b) return a.score < b.score end)
    local n = #list
    local out = {}
    for i, e in ipairs(list) do
        local t = (i <= math.ceil(n / 3)) and "easy" or ((i <= math.ceil(2 * n / 3)) and "medium" or "hard")
        out[e.key] = { tier = t, tags = e.tags, score = e.score }
    end
    return out
end

-- tube course styles: tight pieces, vertical / diagonal turns and loops make it harder
TG_RS_TUBE_TIGHT = { xxs = 1, crn = 1, crn2 = 1, hg = 1, qg = 1 }
TG_RS_TUBE_LONG = { l = 1, m = 1, c5 = 1, c15 = 1 }
function tg_rs_tube_ranks()
    if TG_RS_TUBE_RANKS then return TG_RS_TUBE_RANKS end
    local list = {}
    for _, k in ipairs(TG_TUBER_STYLE_ORDER or {}) do
        local rt = TG_TUBER_TYPES and TG_TUBER_TYPES[k]
        if rt and k ~= "random" and k ~= "allmix" then
            local tot, tight, long = 0, 0, 0
            for pk, n in pairs(rt.counts or {}) do
                tot = tot + n
                if TG_RS_TUBE_TIGHT[pk] then tight = tight + n end
                if TG_RS_TUBE_LONG[pk] then long = long + n end
            end
            tot = math.max(1, tot)
            local mix = rt.mix or { 60, 25, 15 }
            local vert, diag = (mix[2] or 0) / 100.0, (mix[3] or 0) / 100.0
            local loops = ((rt.loop or 0) > 0) or (rt.mods and (rt.mods.loop or rt.mods.cork or rt.mods.barrel)) and true or false
            local knot = rt.mods and (rt.mods.knot or rt.mods.pretzel or rt.mods.twist) and true or false
            local score = (tight / tot) * 2.2 - (long / tot) * 1.0 + vert * 1.2 + diag * 1.6 + (loops and 0.4 or 0) + (knot and 0.3 or 0)
            local tags = {}
            if tight / tot >= 0.45 then table.insert(tags, "tight") end
            if long / tot >= 0.40 then table.insert(tags, "flowing") end
            if diag >= 0.30 then table.insert(tags, "rolls") end
            if vert >= 0.40 then table.insert(tags, "vertical") end
            if loops then table.insert(tags, "loops") end
            if knot or (tight / tot >= 0.35 and diag + vert >= 0.4) then table.insert(tags, "twisty") end
            table.insert(list, { key = k, score = score, tags = tags })
        end
    end
    TG_RS_TUBE_RANKS = tg_rs_rank(list)
    return TG_RS_TUBE_RANKS
end
-- parkour course types: long gaps, big drops, no rails, turns and climbs make it harder
function tg_rs_pk_ranks()
    if TG_RS_PK_RANKS then return TG_RS_PK_RANKS end
    local list = {}
    for _, k in ipairs(TG_PK_STYLE_ORDER or {}) do
        local st = TG_PK_STYLES and TG_PK_STYLES[k]
        if st and k ~= "random" and k ~= "allmix" then
            local gap = (st.gap and st.gap[2]) or 14
            local drop = (st.drop and st.drop[2]) or 3
            local turn = st.turn or 0
            local score = gap / 9.0 + drop / 4.0 + ((st.rails == false) and 0.9 or 0) + turn * 0.8 + (st.up_p or 0) * 2.0 + (st.jitter and 0.2 or 0)
            local tags = {}
            if gap >= 16 then table.insert(tags, "gaps") end
            if gap <= 13 then table.insert(tags, "short") end
            if drop >= 5 then table.insert(tags, "drops") end
            if (st.up_p or 0) > 0 then table.insert(tags, "climbs") end
            if turn >= 0.5 then table.insert(tags, "twisty") end
            if st.rails == false then table.insert(tags, "norail") end
            if st.boost_p and st.boost_p > 0.3 then table.insert(tags, "fast") end
            table.insert(list, { key = k, score = score, tags = tags })
        end
    end
    TG_RS_PK_RANKS = tg_rs_rank(list)
    return TG_RS_PK_RANKS
end
TG_RS_HY_RANKS = { balanced = { tier = "medium", tags = {} }, tubes = { tier = "easy", tags = { "flowing" } }, props = { tier = "medium", tags = { "jumps" } },
                   parkour = { tier = "hard", tags = { "gaps", "jumps" } } }

-- ---------- style picker: difficulty + tag filters over a paged, colour-coded grid ----------
-- entries: { { key, name, tier, tags }, ... }; entries without a tier (Random ...) are always shown first
TG_RS_FILT = TG_RS_FILT or {}
TG_RS_PICK_CACHE = {}
function tg_rs_tier_push(tier, active)
    local c = TG_RS_TIER_RGB[tier]
    if not c then return tg_ui_push_button_colors(active) end
    local k = active and 0.95 or 0.38
    ImGui.PushStyleColor(ImGuiCol.Button, c[1] * k, c[2] * k, c[3] * k, 1.0)
    ImGui.PushStyleColor(ImGuiCol.ButtonHovered, math.min(1, c[1] * k + 0.15), math.min(1, c[2] * k + 0.15), math.min(1, c[3] * k + 0.15), 1.0)
    ImGui.PushStyleColor(ImGuiCol.ButtonActive, c[1], c[2], c[3], 1.0)
    local n = 3
    if active then ImGui.PushStyleColor(ImGuiCol.Text, 0.05, 0.05, 0.08, 1.0); n = 4 end
    return n
end
function tg_rs_style_picker(id, entries, current, on_pick, per_row, width)
    per_row, width = per_row or 4, width or 165
    local F = TG_RS_FILT[id] or { tier = "all", tag = "any" }
    TG_RS_FILT[id] = F
    -- v1.2.0 perf: tier counts, tag chips, button ids and the filtered list are worked out once per
    -- style list and filter, not every frame (the style lists themselves are now built once)
    local C = TG_RS_PICK_CACHE[id]
    if not C or C.entries ~= entries then
        local cnt, have = { all = 0 }, {}
        for _, e in ipairs(entries) do
            if e[3] then
                cnt.all = cnt.all + 1
                cnt[e[3]] = (cnt[e[3]] or 0) + 1
                for _, t in ipairs(e[4] or {}) do have[t] = true end
            end
        end
        local tiers = {}
        for i, t in ipairs(TG_RS_TIERS) do tiers[i] = string.format("%s %d##tier_%s_%s", t[2], cnt[t[1]] or 0, id, t[1]) end
        local tags = { { "any", "Any" } }
        for _, t in ipairs(TG_RS_TAG_ORDER) do if have[t] then table.insert(tags, { t, TG_RS_TAG_NAMES[t] }) end end
        for _, t in ipairs(tags) do t[3] = t[2] .. "##tag_" .. id .. "_" .. t[1] end
        local ids = {}
        for _, e in ipairs(entries) do ids[e] = tostring(e[2]) .. "##sp_" .. id .. "_" .. tostring(e[1]) end
        C = { entries = entries, tiers = tiers, tags = tags, ids = ids, lists = {} }
        TG_RS_PICK_CACHE[id] = C
    end
    for i, t in ipairs(TG_RS_TIERS) do
        local n = tg_rs_tier_push(t[1], F.tier == t[1])
        local c = ImGui.Button(C.tiers[i], 96, 26)
        tg_ui_pop_colors(n)
        if c then F.tier = t[1] end
        if i < #TG_RS_TIERS then ImGui.SameLine() end
    end
    local tags = C.tags
    if #tags > 1 then
        for i, t in ipairs(tags) do
            local n = tg_ui_push_button_colors(F.tag == t[1]) or 0
            local c = ImGui.Button(t[3], tg_pm_button_width(t[2], 82), 24)
            tg_ui_pop_colors(n)
            if c then F.tag = t[1] end
            if i < #tags then
                if i % 8 ~= 0 and tg_pm_room_for_next(tags[i+1][2], 82) then ImGui.SameLine() end
            end
        end
    end
    local fkey = F.tier .. "|" .. F.tag
    local list = C.lists[fkey]
    if not list then
        list = {}
        for _, e in ipairs(entries) do
            local show = (e[3] == nil)
            if not show then
                show = (F.tier == "all" or e[3] == F.tier)
                if show and F.tag ~= "any" then
                    show = false
                    for _, t in ipairs(e[4] or {}) do if t == F.tag then show = true end end
                end
            end
            if show then table.insert(list, e) end
        end
        C.lists[fkey] = list
        C.lists[fkey .. "#key"] = id .. "|" .. fkey
    end
    -- paging
    local key = C.lists[fkey .. "#key"]
    local page_size = per_row * 6
    local pages = math.max(1, math.ceil(#list / page_size))
    local pg = TG_RS_PAGES[key]
    if not pg then
        pg = 1
    end
    pg = math.max(1, math.min(pg, pages))
    TG_RS_PAGES[key] = pg
    if pages > 1 then
        local c1 = ImGui.Button("<##pp_" .. key, 34, 22)
        if c1 then TG_RS_PAGES[key] = (pg - 2) % pages + 1 end
        ImGui.SameLine()
        ImGui.Text(string.format("%d / %d", pg, pages))
        ImGui.SameLine()
        local c2 = ImGui.Button(">##pn_" .. key, 34, 22)
        if c2 then TG_RS_PAGES[key] = pg % pages + 1 end
    end
    local shown = 0
    for i = (pg - 1) * page_size + 1, math.min(#list, pg * page_size) do
        local e = list[i]
        local n = tg_rs_tier_push(e[3], e[1] == current)
        local c = ImGui.Button(C.ids[e] or (tostring(e[2]) .. "##sp_" .. id .. "_" .. tostring(e[1])), tg_pm_button_width(e[2], width), 28)
        tg_ui_pop_colors(n)
        if c then on_pick(e[1]) end
        tg_hp_from_button(id, e[1], e[2])
        shown = shown + 1
        if shown % per_row ~= 0 and i < math.min(#list, pg * page_size)
            and tg_pm_room_for_next(list[i + 1][2], width) then ImGui.SameLine() end
    end
    if #list == 0 then ImGui.Text("  none") end
end
-- one line under the picker: name, tier and tags of the selected style (+ a short description)
function tg_rs_style_line(name, tier, tags, desc)
    local c = TG_RS_TIER_RGB[tier or ""] or { 0.85, 0.85, 0.9 }
    local tt = {}
    for _, t in ipairs(tags or {}) do table.insert(tt, TG_RS_TAG_NAMES[t] or t) end
    local s = tostring(name or "") .. (tier and ("  |  " .. (tier:sub(1, 1):upper() .. tier:sub(2))) or "") .. ((#tt > 0) and ("  |  " .. table.concat(tt, ", ")) or "")
    ImGui.TextColored(c[1], c[2], c[3], 1.0, s)
    if desc and desc ~= "" then ImGui.TextDisabled("  " .. tostring(desc)) end
end
-- section header
function tg_rs_h(text, r, g, b)
    ImGui.TextColored(r or 1.0, g or 0.77, b or 0.0, 1.0, text)
end

-- ---------- compact top row: objects slider, radius, clear ----------
-- (replaces the v2.0 limit block: no step buttons, no progress text - the corner HUD shows progress)
function tg_rs_limit_ui(kind, title)
    local v = tg_rs_limit(kind)
    ImGui.Text("Objects")
    ImGui.SameLine()
    ImGui.PushItemWidth(200)
    local nv = ImGui.SliderInt("##rslimit_" .. kind, v, 10, tg_rs_hardmax())
    ImGui.PopItemWidth()
    if type(nv) == "number" and nv ~= v then tg_rs_set_limit(kind, nv) end
    ImGui.SameLine()
    local c2 = ImGui.Button("Clear##rsclear_" .. kind, 70, 24)
