-- ---------- corner progress HUD (DriftGod installer style) ----------
-- Small panel in the bottom-right corner drawn on the ImGui background layer from ON_PRESENT:
-- rounded track, eased fill, big percent, label and a short status line. Colour = the tab that
-- started the build. Falls back to the native-rect bar if ON_PRESENT / ImGui drawing is missing.
TG_RS_TAB_RGB = {
    Home = { 90, 170, 255 }, Games = { 255, 90, 200 }, Tubes = { 167, 94, 252 }, Track = { 255, 140, 20 },
    Parkour = { 255, 70, 70 }, Hybrid = { 255, 205, 0 }, Lab = { 0, 210, 190 }, Saved = { 120, 230, 120 }, Settings = { 200, 200, 210 },
}
function tg_rs_hud_rgb(p)
    if p.failed then return 255, 70, 70 end
    if p.done_at then return 90, 230, 120 end
    local c = TG_RS_TAB_RGB[p.tab or ""] or { 255, 196, 0 }
    return c[1], c[2], c[3]
end
function tg_rs_short_msg(m)
    m = tostring(m or "")
    if #m > 46 then m = m:sub(1, 44) .. ".." end
    return m
end
-- ---------- v2.3.2 progress card (Startup Browser notification style) ----------
-- A real ImGui window drawn every frame from ON_PRESENT (registered when the script loads, like
-- Startup's top-right Browser cards and DriftGod's loader): slides in from the right edge of the
-- screen when a build starts, stays up for the whole build, slides back out ~3 s after it ends.
--   TRACKMATIC  |  TRACK                                   62%
--   Stunt Race - Rocket Voltic
--   [=================                   ]
--   Spawning track  38/62                                 12s
TG_RS_CARD = TG_RS_CARD or { x = nil, shown = false, t_show = 0 }
TG_RS_CARD_W, TG_RS_CARD_H = 400, 132
TG_RS_STAGE_WORDS = {
    { "^Queued", "Waiting to start" }, { "^Starting", "Starting" },
    { "^Planning", "Planning track" }, { "^Snapping", "Spawning track" }, { "^Spawning gate", "Placing gates" },
    { "^Spawning", "Spawning objects" }, { "^Decorating", "Adding decorations" }, { "^Cleared", "Track cleared" },
}
function tg_rs_stage_text(p)
    local m = tostring(p.msg or "")
    local staged = false
    if p.stage and not p.done_at then m = tostring(p.stage) .. ((m:match("(%d+/%d+)")) and ("  " .. m:match("(%d+/%d+)")) or ""); staged = true end
    for _, w in ipairs(staged and {} or TG_RS_STAGE_WORDS) do
        local rest = m:match(w[1] .. "%s*(.*)$")
        if rest then m = w[2] .. ((rest ~= "") and ("  " .. rest) or ""); break end
    end
    if p.failed then m = "Stopped - " .. m elseif p.done_at and not m:find("cleared", 1, true) then m = "Done - " .. m end
    if #m > 52 then m = m:sub(1, 50) .. ".." end
    return m
end
function tg_rs_card_display()
    local sw, sh = 1920, 1080
    local rx, ry = ImGui.GetDisplaySize()
    if type(rx) == "number" and type(ry) == "number" and rx > 0 and ry > 0 then sw, sh = rx, ry end
    return sw, sh
end
function tg_rs_card_flags()
    local f = 0
    for _, k in ipairs({ "NoTitleBar", "NoResize", "NoMove", "NoCollapse", "NoScrollbar", "NoSavedSettings", "NoInputs", "NoFocusOnAppearing", "NoNav", "NoScrollWithMouse" }) do
        f = f + ImGuiWindowFlags[k]
    end
    return f
end
function tg_rs_present_draw()
    local p = TG_RS_PROG
    local now = util.current_time_millis()
    local C = TG_RS_CARD
    -- visible while a build runs and for 3 s after it ends
    local want = p and p.active and not (p.done_at and now - p.done_at > 3000)
    local sw, sh = tg_rs_card_display()
    local W, H = TG_RS_CARD_W, TG_RS_CARD_H
    local shownX, hiddenX = sw - W - 24, sw + 24
    C.x = C.x or hiddenX
    local target = want and shownX or hiddenX
    C.x = C.x + (target - C.x) * 0.18                          -- smooth slide (ease toward target every frame)
    if math.abs(C.x - target) < 0.5 then C.x = target end
    if not want and C.x >= hiddenX - 1 then TG_RS_HUD_EASE = nil; return end
    local r, g, b = tg_rs_hud_rgb(p)
    -- eased fill (never runs backwards)
    local raw = tonumber(p.frac or 0) or 0
    local sweep = raw < 0
    if not sweep then
        local e = TG_RS_HUD_EASE
        if e == nil or raw < e - 0.2 then e = raw
        elseif raw > e then e = math.min(raw, e + math.max(0.006, (raw - e) * 0.25)) end
        TG_RS_HUD_EASE = e
    end
    local pct = sweep and nil or math.floor((TG_RS_HUD_EASE or 0) * 100 + 0.5)
    ImGui.SetNextWindowPos(C.x, 22, ImGuiCond.Always)
    ImGui.SetNextWindowSize(W, H, ImGuiCond.Always)
    ImGui.SetNextWindowBgAlpha(0.96)
    local nc, nv = 0, 0
    ImGui.PushStyleColor(ImGuiCol.WindowBg, 0.055, 0.025, 0.090, 0.97); nc = nc + 1
    ImGui.PushStyleColor(ImGuiCol.Border, r / 255, g / 255, b / 255, 0.95); nc = nc + 1
    ImGui.PushStyleColor(ImGuiCol.PlotHistogram, r / 255, g / 255, b / 255, 1.0); nc = nc + 1
    ImGui.PushStyleColor(ImGuiCol.FrameBg, 0.16, 0.13, 0.22, 1.0); nc = nc + 1
    ImGui.PushStyleColor(ImGuiCol.Text, 0.95, 0.95, 1.0, 1.0); nc = nc + 1
    ImGui.PushStyleVar(ImGuiStyleVar.WindowRounding, 10.0); nv = nv + 1
    ImGui.PushStyleVar(ImGuiStyleVar.WindowPadding, 14.0, 10.0); nv = nv + 1
    ImGui.PushStyleVar(ImGuiStyleVar.WindowBorderSize, 1.5); nv = nv + 1
    ImGui.PushStyleVar(ImGuiStyleVar.FrameRounding, 5.0); nv = nv + 1
    if ImGui.Begin("##TrackMaticProgressCard", true, tg_rs_card_flags()) ~= false then tg_rs_present_card_body(p, r, g, b, W, pct, sweep, now) end
    ImGui.End()
    ImGui.PopStyleVar(nv)
    ImGui.PopStyleColor(nc)
end
function tg_rs_present_card_body(p, r, g, b, W, pct, sweep, now)
        local tab = string.upper(tostring(p.tab or "TrackMatic"))
        local col = { r / 255, g / 255, b / 255 }
        -- row 1: brand | tab ................ percent
        ImGui.TextColored(0.76, 0.43, 1.0, 1.0, "TRACKMATIC")
        ImGui.SameLine()
        ImGui.TextColored(col[1], col[2], col[3], 1.0, "|  " .. tab)
        local ptxt = pct and (tostring(pct) .. "%") or (p.done_at and "100%" or "...")
        ImGui.SameLine(W - 14 - 64)
        ImGui.SetWindowFontScale(1.35)
        ImGui.TextColored(col[1], col[2], col[3], 1.0, ptxt)
        ImGui.SetWindowFontScale(1.0)
        -- row 2: what's being built
        local label = tostring(p.label or ""):gsub("##.*$", "")
        if label == label:upper() and #label > 1 then label = label:sub(1, 1) .. label:sub(2):lower() .. " " .. tostring(p.tab or "") end
        if #label > 46 then label = label:sub(1, 44) .. ".." end
        ImGui.Text(label)
        -- row 3: the bar
        local frac = sweep and ((now % 1400) / 1400.0) or math.min(1.0, TG_RS_HUD_EASE or 0)
        if p.done_at then frac = 1.0 end
        ImGui.ProgressBar(frac, W - 28, 14, "")
        -- row 4: progress update ............ seconds
        local secs = math.floor((now - (p.t0 or now)) / 1000.0)
        ImGui.TextColored(1.0, 0.73, 0.32, 1.0, tg_rs_stage_text(p))
        ImGui.SameLine(W - 14 - 40)
        ImGui.TextColored(0.62, 0.64, 0.70, 1.0, tostring(secs) .. "s")
        TG_RS_CARD_DRAWN = now
end
function tg_rs_present_register()
    if TG_RS_PRESENT_REG then return true end
    TG_RS_PRESENT_REG = true
    TG_RS_PRESENT_GEN = (TG_RS_PRESENT_GEN or 0) + 1
    local gen = TG_RS_PRESENT_GEN
    local id = EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
        if TG_RS_PRESENT_GEN ~= gen then return end
        tg_rs_present_draw()
    end)
    tg_log("[TRACKMATIC][HUD] progress card on ON_PRESENT: " .. tostring(id))
    return true
end
-- registered at script load, exactly like Startup / DriftGod / Minigames do it
tg_rs_present_register()
-- the old native bar only draws when the card hasn't drawn in the last half second
function tg_rs_card_live()
    return TG_RS_CARD_DRAWN ~= nil and (util.current_time_millis() - TG_RS_CARD_DRAWN) < 500
end
-- stage words for the card ("Scanning area", "Planning tube course", "Weaving round buildings" ...)
function tg_rs_stage(text) TG_RS_STAGE = text; if TG_RS_PROG and TG_RS_PROG.active then TG_RS_PROG.stage = text end end
if tg_rs_spawn_progress and not TG_RS_SPAWN_STAGE_WRAPPED then
    TG_RS_SPAWN_STAGE_WRAPPED = true
    TG_RS_ORIG_SPAWN_PROGRESS = tg_rs_spawn_progress
    tg_rs_spawn_progress = function(label, i, n, what)
        TG_RS_STAGE = nil
        return TG_RS_ORIG_SPAWN_PROGRESS(label, i, n, what)
    end
end
if tg_rs_build_start and not TG_RS_BUILD_STAGE_WRAPPED then
    TG_RS_BUILD_STAGE_WRAPPED = true
    TG_RS_ORIG_BUILD_START = tg_rs_build_start
    tg_rs_build_start = function(label)
        TG_RS_STAGE = nil
        return TG_RS_ORIG_BUILD_START(label)
    end
end
