function tg_pk_lerp(a, b, t) return a + (b - a) * t end
function tg_pk_rand(a, b) return a + (b - a) * math.random() end

-- ---------- geometry ----------
function tg_pk_rot(dir)
    local X = tg_tp_norm(dir)
    local Y = tg_tp_cross(tg_tp_v(0, 0, 1), X)
    if tg_tp_len(Y) < 0.001 then Y = tg_tp_v(0, 1, 0) end
    Y = tg_tp_norm(Y)
    return { X = X, Y = Y, Z = tg_tp_cross(X, Y) }
end

function tg_pk_samples(a, b, step)
    local pts, n = {}, math.max(1, math.ceil(tg_tp_dist(a, b) / (step or 10.0)))
    for i = 0, n do table.insert(pts, tg_tp_add(a, tg_tp_mul(tg_tp_sub(b, a), i / n))) end
    return pts
end

-- straight from port P along heading psi (rad) with nose-up pitch (deg)
function tg_pk_straight(state, key, pitch)
    local pc = TG_PK_PIECES[key]
    local th = math.rad(pitch or 0.0)
    local d = tg_tp_v(math.cos(th) * math.cos(state.psi), math.cos(th) * math.sin(state.psi), math.sin(th))
    local R = tg_pk_rot(d)
    local origin = tg_tp_add(state.P, tg_tp_mul(d, pc.len * 0.5))
    local exitP = tg_tp_add(state.P, tg_tp_mul(d, pc.len))
    local p, r, y = tg_tp_euler(R)
    return { key = key, model = pc.model, origin = origin, pitch = p, rollY = r, yaw = y, R = R, arc = pc.len,
             samples = tg_pk_samples(state.P, exitP, 10.0), entry = state.P, next = { P = exitP, psi = state.psi } }
end

function tg_pk_rz(phi, v) return tg_tp_v(v[1] * math.cos(phi) - v[2] * math.sin(phi), v[1] * math.sin(phi) + v[2] * math.cos(phi), 0.0) end

-- flat corner, side = 1 left / -1 right
function tg_pk_bend(state, key, side)
    local pc = TG_PK_PIECES[key]
    local ang = math.rad(pc.angle)
    local phi, enter, exit, npsi
    if side >= 0 then
        phi = state.psi; enter, exit = pc.A, pc.B; npsi = state.psi + ang
    else
        -- drive the same piece backwards: enter at B travelling against B's outward direction
        phi = state.psi - ang + math.pi; enter, exit = pc.B, pc.A; npsi = state.psi - ang
    end
    local origin = tg_tp_sub(state.P, tg_pk_rz(phi, enter))
    local exitP = tg_tp_add(origin, tg_pk_rz(phi, exit))
    exitP.z = state.P.z
    local R = { X = tg_tp_v(math.cos(phi), math.sin(phi), 0), Y = tg_tp_v(-math.sin(phi), math.cos(phi), 0), Z = tg_tp_v(0, 0, 1) }
    local p, r, y = tg_tp_euler(R)
    -- samples along the arc (same arc both ways; a right turn just runs it backwards)
    local samples, rad = {}, tg_tp_dist(state.P, exitP) / (2.0 * math.sin(ang * 0.5))
    for i = 0, 6 do
        local t = ang * i / 6
        if side < 0 then t = ang - t end
        local w = tg_pk_rz(phi, { pc.A[1] + rad * math.sin(t), pc.A[2] + rad * (1 - math.cos(t)) })
        table.insert(samples, tg_tp_v(origin.x + w.x, origin.y + w.y, state.P.z))
    end
    return { key = key, model = pc.model, origin = tg_tp_v(origin.x, origin.y, state.P.z), pitch = p, rollY = r, yaw = y, R = R,
             arc = rad * ang, samples = samples, entry = state.P, next = { P = exitP, psi = npsi } }
end

-- ---------- checks ----------
TG_PK_GROUND_CACHE = {}
function tg_pk_ground(x, y, hint)
    -- only real ground readings are cached; when the probe fails we return nil (= no terrain limit)
    local k = math.floor(x / 8) .. ":" .. math.floor(y / 8)
    local g = TG_PK_GROUND_CACHE[k]
    if g ~= nil then return g end
    local gz = tg_ground_z(x, y)
    if gz then TG_PK_GROUND_CACHE[k] = gz end
    return gz
end

-- clear of earlier pieces (except the last `skip`), of the ground, and of buildings
function tg_pk_fits(plan, placed, ctx, opts)
    opts = opts or {}
    if ctx.radius and ctx.rc then
        for _, s in ipairs(plan.samples or {}) do
            local dx, dy = s.x - ctx.rc.x, s.y - ctx.rc.y
            if dx * dx + dy * dy > ctx.radius * ctx.radius then return false, "radius" end
        end
    end
    local skip = opts.skip or 2
    for i = 1, #placed - skip do
        local q = placed[i]
        if not (tg_rs_far(plan, q, 26.0)) then
        for _, s in ipairs(plan.samples) do
            for _, t in ipairs(q.samples) do
                local dx, dy, dz = s.x - t.x, s.y - t.y, s.z - t.z
                if dx * dx + dy * dy < 26.0 * 26.0 and math.abs(dz) < 12.0 then return false, "overlap" end
            end
        end
    end
        end
    if opts.near_ground and TG_RS_HEIGHTMAP_COURSES and tg_rs_below_world then
        -- ramps up from / down to the ground: just never deep inside a building or hill
        for _, s in ipairs(plan.samples) do if tg_rs_below_world(s, 0.0, -6.0) then return false, "heightmap" end end
    end
    if not opts.near_ground then
        for _, s in ipairs(plan.samples) do
            local g = tg_pk_ground(s.x, s.y, s.z - 50.0)
            if g and s.z < g + 6.0 then return false, "terrain" end
            if TG_RS_HEIGHTMAP_COURSES and tg_rs_below_world(s, 0.0, 6.0) then return false, "heightmap" end
        end
    end
    if ctx.world and tg_world_obstacle_line_probe and not opts.near_ground then
        local a, b = plan.samples[1], plan.samples[#plan.samples]
        if tg_world_obstacle_line_probe(a.x, a.y, a.z + 3.0, b.x, b.y, b.z + 3.0, 0, "parkour") then return false, "building" end
    end
    return true
end

-- ---------- planner ----------
-- v1.4.0 planner: every course type is data. Style fields (all optional except islands/gap/drop):
--  kick {tile,deg} | ramps {"a","b","c"} + ramp_p | boost_p | gate_p | balls_p | pins ("final"/"once")
--  land/run lists | turn prob + turns + turn_mode ("random","alternate","same","uturn") | rails | jitter | lateral
--  up_p + rise {a,b} (jump UP onto a higher island using a big stunt ramp) | start_h
function tg_pk_plan_course(style_key, diff_key)
    local st = TG_PK_STYLES[style_key]
    local df = TG_PK_DIFFS[diff_key] or TG_PK_DIFFS.normal
    local T = tg_tt_take("parkour") or nil
    if T and T.st then st = T.st end
    local pos, heading = tg_get_local_position_heading("parkour")
    TG_RS_NEAR = { P = { x = pos.x, y = pos.y }, r = 220.0 }
    heading = tonumber(heading or 0.0) or 0.0
    -- v2.0.3: after a few blocked attempts, try starting a little to the left / right
    heading = heading + (TG_RS_TRY_YAW or 0.0)
    local fx, fy = calculate_new_position({ x = 0.0, y = 0.0, z = 0.0 }, heading, 1.0, 0.0, 0.0)
    local psi0 = math.atan(fy, fx)
    if not psi0 or psi0 ~= psi0 then psi0 = tg_atan2_safe(fy, fx) end
    local F = tg_tp_v(math.cos(psi0), math.sin(psi0), 0)
    local ctx = { world = (TG_WORLD_OBSTACLE_AVOIDANCE ~= false) }
    -- v2.3.0 radius: the whole course stays inside this circle round you
    ctx.radius = tg_rs_radius("parkour") or nil
    ctx.rc = { x = pos.x, y = pos.y }
    if ctx.radius then ctx.leash = math.max(90.0, ctx.radius * 0.4) end
    TG_PK_GROUND_CACHE = {}
    local rails = (st.rails ~= false)
    local function K(key) if rails then return key end return "n" .. key end   -- railed / rail-less tile
    local function mk(key) if TG_PK_PIECES[K(key)] then return K(key) end return key end

    -- decide every jump first (up or down, ramp or tile kicker) so the start is exactly high enough
    local base_st = st
    local limit = TG_PK_MAX_OBJECTS or 73
    local ilo, ihi = tg_rs_scale_range(st.islands, limit)
    -- big limits: aim past the budget, the planner stops when the object limit is reached
    if limit > 90 then ilo, ihi = math.floor(ilo * 1.5), math.floor(ihi * 1.7) end
    local n_islands = math.random(ilo, ihi)
    -- v2.3.0 radius: fewer islands so the course fits the circle
    local rad0 = tg_rs_radius("parkour") or nil
    if rad0 then n_islands = math.min(n_islands, math.max(4, math.floor(rad0 / 70.0))) end
    local long_course = n_islands > st.islands[2]
    local jumps_plan, level, lowest = {}, 0.0, 0.0
    for i = 1, n_islands do
        local t = (n_islands > 1) and (i - 1) / (n_islands - 1) or 0
        -- long courses repeat the difficulty ramp every 10 islands instead of stretching it
        if long_course then t = ((i - 1) % 10) / 9 end
        if T and T.curve then t = t ^ T.curve end
        local j = { t = t, st = base_st }
        if base_st.mix_all then
            local pool = TG_PK_STYLE_ORDER
            local donor
            repeat donor = TG_PK_STYLES[pool[math.random(#pool)]] until donor and not donor.mix_all
            j.st = donor
        end
        local st = j.st
        local force_up = (level < -55.0)          -- long courses: climb back up instead of sinking forever
        if force_up or (st.up_p and math.random() < st.up_p) then
            j.ramp = (math.random() < 0.7) and "c" or "b"
            local r = st.rise or { 3, 6 }
            j.rise = math.min(tg_pk_lerp(r[1], r[2], t), (j.ramp == "c") and 8.0 or 4.0)
            j.delta = j.rise
        else
            if st.ramps and math.random() < (st.ramp_p or 1.0) then j.ramp = st.ramps[math.random(#st.ramps)] end
            j.delta = -tg_pk_lerp(st.drop[1], st.drop[2], t) * df.drop
        end
        jumps_plan[i] = j
        level = level + j.delta
        lowest = math.min(lowest, level)
    end

    local plans, props = {}, {}
    local function push(plan) table.insert(plans, plan); return plan end
    local function prop(model, pos3, psi, extra) return tg_hy_prop(props, model, pos3, psi, extra) end

    -- 1) buried ramp up from the ground
    local sg = tg_tp_add(tg_tp_v(pos.x, pos.y, pos.z), tg_tp_mul(F, 35.0))
    if ctx.radius and TG_RS_START_BACK then sg = tg_tp_add(tg_tp_v(pos.x, pos.y, pos.z), tg_tp_mul(F, -ctx.radius * 0.5)) end
    local ground_s = tg_tr_ground_z(sg.x, sg.y, pos.z - 1.0)
    local state = { P = tg_tp_v(sg.x, sg.y, ground_s - TG_PK_ENTRY_SINK), psi = psi0 }
    local start_gate = { P = state.P, D = F, U = tg_tp_v(0, 0, 1), r = 16.0 }
    local drive_spot = tg_tp_sub(sg, tg_tp_mul(F, 28.0)); drive_spot.z = ground_s + 1.0
    local target = ground_s + math.max(st.start_h or 26.0, -lowest + 16.0)
    -- v2.0.3: tall buildings / hills ahead (height map): start high enough to clear them
    local hahead = TG_RS_HEIGHTMAP_COURSES and tg_rs_height_ahead(state.P, psi0, 240, 760) or nil
    if hahead and hahead + 16.0 > target then target = math.min(ground_s + 120.0, hahead + 16.0) end
    local rpitch = ctx.radius and math.max((T and T.rpitch) or TG_PK_RAMP_PITCH, 13.0) or ((T and T.rpitch) or TG_PK_RAMP_PITCH)   -- v2.3.0: steeper, shorter ramp inside a radius
    if ctx.radius then target = math.min(target, ground_s + math.max(24.0, ctx.radius * 0.1)) end
    local rise = 53.0 * math.sin(math.rad(rpitch))
    local guard = 0
    while state.P.z + rise * 0.5 < target and guard < 26 do
        guard = guard + 1
        local pl = tg_pk_straight(state, K("m"), rpitch)
        local ok, why = tg_pk_fits(pl, plans, ctx, { near_ground = true })
        if not ok then return nil, "ramp " .. why end
        push(pl); state = pl.next
    end

    -- 2) start island
    local checkpoints = {}
    local first = tg_pk_straight(state, K(ctx.radius and "m" or "lm"), 0.0)
    local ok0, why0 = tg_pk_fits(first, plans, ctx, { near_ground = true })
    if not ok0 then return nil, "start " .. why0 end
    push(first).island = 0
    if st.gantry and tg_hy_on_tile then prop("stt_prop_race_gantry_01", tg_hy_on_tile(first, 18.0, 0, 0.05), first.next.psi) end
    table.insert(checkpoints, { P = tg_tp_add(first.entry, tg_tp_v(math.cos(state.psi) * 12.0, math.sin(state.psi) * 12.0, 2.5)), psi = state.psi, island = 0 })
    state = first.next

    local jumps = {}
    local last_side = (math.random() < 0.5) and 1 or -1
    local same_side = last_side
    local pins_done = false
    local function leash_side(sstate)
        -- far from the start and heading away: turn back toward it (keeps long courses on the map)
        local dx, dy = start_gate.P.x - sstate.P.x, start_gate.P.y - sstate.P.y
        local far = math.sqrt(dx * dx + dy * dy)
        if far < (ctx.leash or (T and T.leash) or TG_PK_LEASH or 1400.0) then return nil end
        local hx, hy = math.cos(sstate.psi), math.sin(sstate.psi)
        if (hx * dx + hy * dy) / far > 0.2 then return nil end
        return ((hx * dy - hy * dx) >= 0) and 1 or -1
    end
    for i = 1, n_islands do
        local jp = jumps_plan[i]
        local st = jp.st
        rails = (st.rails ~= false)
        local t = jp.t
        local placed_island = false
        for attempt = 1, 10 do
            local mark, pmark = #plans, #props
            local s = { P = state.P, psi = state.psi }
            local good = true
            local function add(pl, opts)
                if not good then return nil end
                local ok = tg_pk_fits(pl, plans, ctx, opts)
                if not ok then good = false; return nil end
                push(pl).island = i; s = pl.next
                return pl
            end
            local run = st.run[math.random(#st.run)]
            if run ~= "" then add(tg_pk_straight(s, mk(run), 0.0)) end
            local leash = good and leash_side(s) or nil
            -- long courses stuck at a dead end: later attempts try a corner to get out
            if good and not leash and long_course and attempt > 5 then leash = (math.random() < 0.5) and 1 or -1 end
            if good and ((st.turns and #st.turns > 0 and math.random() < (st.turn or 0)) or leash) then
                local mode = st.turn_mode or (st.alternate and "alternate") or "random"
                local side
                if mode == "alternate" then side = -last_side
                elseif mode == "same" then side = same_side
                else side = (math.random() < 0.5) and 1 or -1 end
                local bend = (st.turns and #st.turns > 0) and st.turns[math.random(#st.turns)] or "b90"
                if leash then side = leash; if mode == "uturn" then mode = "random" end end
                add(tg_pk_bend(s, bend, side))
                if mode == "uturn" and good then add(tg_pk_bend(s, bend, side)) end
                if good then last_side = side end
                if good then add(tg_pk_straight(s, K("m"), 0.0)) end
            end
            -- kicker: a real stunt ramp on a flat tile, or a pitched tile
            local ramp = jp.ramp and TG_HY_RAMPS and TG_HY_RAMPS[jp.ramp] or nil
            local kick_angle, lip_h = 0.0, 0.0
            if good then
                if ramp then
                    local tile = add(tg_pk_straight(s, K("m"), 0.0))
                    if tile then tile.kicker = true end
                    if tile then
                        if st.boost_p and math.random() < st.boost_p then prop("stt_prop_track_speedup_t1", tg_hy_on_tile(tile, 8.0, 0, -0.11), tile.next.psi) end
                        prop(ramp.model, tg_hy_on_tile(tile, 53.0 - ramp.back, 0, ramp.up), tile.next.psi)
                    end
                    kick_angle, lip_h = ramp.angle, ramp.lip
                else
                    local kick = st.kick or { "m", 6 }
                    local ang = kick[2] * ((T and T.kgrow) and (1.0 - T.kgrow * 0.5 + T.kgrow * t) or (0.9 + 0.2 * t))
                    local prev = plans[#plans]
                    local k = add(tg_pk_straight(s, mk(kick[1]), ang))
                    if k then k.kicker = true end
                    if k and st.boost_p and math.random() < st.boost_p and prev and prev.island == i and math.abs(prev.pitch) < 0.1 and math.abs(prev.rollY) < 0.1 and TG_PK_PIECES[prev.key] and TG_PK_PIECES[prev.key].kind == "straight" then
                        prop("stt_prop_track_speedup_t1", tg_hy_on_tile(prev, TG_PK_PIECES[prev.key].len * 0.6, 0, -0.11), prev.next.psi)
                    end
                    kick_angle, lip_h = ang, 0.0
                end
            end
            if good then
                local lip = s
                local g0, g1 = st.gap[1], st.gap[2]
                if jp.rise then g0, g1 = 8.0, 14.0 end
                local gr = (T and T.grand) or 1.0
                local gap = tg_pk_lerp(g0, g1, t) * df.gap * ((ramp and not jp.rise) and ((T and T.ramp_gap) or 1.25) or 1.0) + tg_pk_rand(-gr, gr)
                local lvl = state.P.z + jp.delta
                local jitter = math.rad(tg_pk_rand(-(st.jitter or 6), (st.jitter or 6)))
                local lat = st.lateral and tg_pk_rand(-st.lateral, st.lateral) or 0.0
                local land = { P = tg_tp_v(lip.P.x + math.cos(lip.psi) * gap - math.sin(lip.psi) * lat,
                                           lip.P.y + math.sin(lip.psi) * gap + math.cos(lip.psi) * lat, lvl), psi = lip.psi + jitter }
                if ctx.world and tg_world_obstacle_line_probe then
                    if tg_world_obstacle_line_probe(lip.P.x, lip.P.y, lip.P.z + lip_h + 2.0, land.P.x, land.P.y, land.P.z + 2.0, 0, "parkour_gap") then good = false end
                end
                if good then
                    local lkey = st.land[math.random(#st.land)]
                    if ramp and ramp.lip > 10 and not jp.rise then lkey = "l" end
                    if st.pins == "final" and i == n_islands and TG_PK_PIECES[lkey].len < 106 then lkey = "lm" end
                    local landing = tg_pk_straight(land, mk(lkey), 0.0)
                    landing.tt_gap = true
                    local okl = tg_pk_fits(landing, plans, ctx, { skip = #plans - mark + 1 })
                    if okl then
                        push(landing).island = i
                        local llen = TG_PK_PIECES[landing.key].len
                        table.insert(checkpoints, { P = tg_tp_add(land.P, tg_tp_v(math.cos(land.psi) * math.min(12.0, llen * 0.5), math.sin(land.psi) * math.min(12.0, llen * 0.5), 2.5)), psi = land.psi, island = i })
                        table.insert(jumps, { gap = math.sqrt(gap * gap + lat * lat), drop = (lip.P.z + lip_h) - lvl, kick = kick_angle, land_len = llen, up = jp.rise and true or false })
                        if st.gate_p and math.random() < st.gate_p and llen >= 53 then
                            prop("ar_prop_ar_neon_gate_04a", tg_hy_on_tile(landing, math.min(30.0, llen * 0.6), 0, 2.62), landing.next.psi + math.pi)
                        end
                        local want_pins = (st.pins == "once" and not pins_done and llen >= 106 and math.random() < 0.5) or (st.pins == "final" and i == n_islands and llen >= 106)
                        if want_pins then
                            pins_done = true
                            local rows = { { 0 }, { -1.45, 1.45 }, { -2.9, 0, 2.9 }, { -4.35, -1.45, 1.45, 4.35 } }
                            for r, ys in ipairs(rows) do
                                for _, y in ipairs(ys) do prop("stt_prop_stunt_bowling_pin", tg_hy_on_tile(landing, llen * 0.65 + (r - 1) * 2.5, y, 0.5), landing.next.psi, { dynamic = true }) end
                            end
                        elseif st.balls_p and llen >= 53 and math.random() < st.balls_p then
                            local models = { "stt_prop_stunt_soccer_sball", "stt_prop_stunt_soccer_ball", "stt_prop_stunt_soccer_lball" }
                            for _, y in ipairs({ -5.0, 5.0 }) do
                                prop(models[math.random(#models)], tg_hy_on_tile(landing, llen * 0.6 + math.random() * 8.0, y, 6.0), landing.next.psi, { dynamic = true })
                            end
                        end
                        if base_st.mix_all and tg_rs_stunt_plan and math.random() < 0.85 then tg_rs_stunt_plan(props, landing) end
                        state = landing.next
                        placed_island = true
                    end
                end
            end
            if placed_island then break end
            while #plans > mark do table.remove(plans) end
            while #props > pmark do table.remove(props) end
        end
        if not placed_island then
            -- a long course that runs out of room just finishes early
            if i > (ctx.radius and 2 or (base_st.islands[1] + 1)) then n_islands = i - 1; break end
            return nil, "island " .. tostring(i)
        end
        if TG_PK_PLAN_PROGRESS then TG_PK_PLAN_PROGRESS(i, n_islands) end
        if tg_rs_check_cancel() then return nil, "cancelled" end
        if i % 4 == 0 then util.yield(0) end
        if #plans + #props > TG_PK_MAX_OBJECTS - ((T and math.max(10, math.ceil((state.P.z - ground_s) / (53.0 * math.sin(math.rad((T and T.rpitch) or TG_PK_RAMP_PITCH)))) + 4)) or 10) then n_islands = i; break end
    end
    st = base_st
    rails = (st.rails ~= false)

    -- 3) ramp back down to the ground; finish at the bottom
    -- v2.3.0 radius: turn back toward the middle before the descent so it stays inside the circle
    if ctx.radius and ctx.rc then
        for _ = 1, 2 do
            local dx, dy = ctx.rc.x - state.P.x, ctx.rc.y - state.P.y
            local d = math.sqrt(dx * dx + dy * dy)
            local hx, hy = math.cos(state.psi), math.sin(state.psi)
            if d < 1.0 or (hx * dx + hy * dy) / d > 0.3 then break end
            local side = ((hx * dy - hy * dx) >= 0) and 1 or -1
            local b = tg_pk_bend(state, "b90", side)
            if not b or not tg_pk_fits(b, plans, ctx, {}) then break end
            push(b); state = b.next
        end
    end
    local guard2 = 0
    while guard2 < 26 do
        guard2 = guard2 + 1
        local pl = tg_pk_straight(state, K("m"), -((T and T.rpitch) or TG_PK_RAMP_PITCH))
        local g = tg_pk_ground(pl.next.P.x, pl.next.P.y, pl.next.P.z - 50.0) or (pl.next.P.z - 100.0)
        local ok = tg_pk_fits(pl, plans, ctx, { near_ground = true })
        if not ok then return nil, "descent" end
        if TG_RS_HEIGHTMAP_COURSES and tg_rs_descent_blocked(pl.next.P, tg_pk_ground(pl.next.P.x, pl.next.P.y, pl.next.P.z - 60.0)) then return nil, "descent building" end
        push(pl); state = pl.next
        if state.P.z <= g then break end
    end
    if st.gantry and tg_hy_prop then
        local fg = tg_tp_add(state.P, tg_tp_v(math.cos(state.psi) * 14.0, math.sin(state.psi) * 14.0, 0))
        fg.z = (tg_pk_ground(fg.x, fg.y, fg.z + 20.0) or fg.z) + 0.05
        prop("stt_prop_race_gantry_01", fg, state.psi)
    end
    while #plans + #props > TG_PK_MAX_OBJECTS and #props > 0 do table.remove(props) end
    if #plans > TG_PK_MAX_OBJECTS then return nil, "too many pieces" end
    local finish_gate = { P = state.P, D = tg_tp_v(math.cos(state.psi), math.sin(state.psi), 0), r = 16.0 }
    return plans, { props = props, start = start_gate, finish = finish_gate, drive_spot = drive_spot, checkpoints = checkpoints,
                    jumps = jumps, islands = n_islands, style = st.name, tune = T }
end

-- ---------- colours ----------
function tg_pk_tint(obj, idx)
    if not obj or obj == 0 or idx == nil or idx < 0 then return end
    Natives.InvokeVoid(0x971DA0055324D033, obj, math.floor(idx) % 16)
end

-- colour index for piece i of n on island k (nil = leave the model's own colour)
function tg_pk_colour_for(mode, fixed, i, island)
    if mode == "single" then return fixed or 1 end
    if mode == "island" then return ((island or 0) % 15) + 1 end
    if mode == "rainbow" then return (i % 15) + 1 end
    if mode == "random" then return math.random(1, 15) end
    return nil
end

-- ---------- respawn on fall ----------
TG_PK_STATE = TG_PK_STATE or { active = false }
function tg_pk_vehicle_or_ped()
    local ped = tg_tn_int(0xD80958FC74E988A6)
    if not ped or ped == 0 then return 0 end
    if tg_tn_bool(0x997ABD671D25CA0B, ped, false) then
        local veh = tg_tn_int(0x9A9112A0FE9A4713, ped, false)
        if veh and veh ~= 0 then return veh, true end
    end
    return ped, false
end

function tg_pk_put_at(cp, speed)
    local e, in_veh = tg_pk_vehicle_or_ped()
    if not e or e == 0 then return end
    tg_tn_void(0x1C99BB7B6E96D16F, e, 0.0, 0.0, 0.0)
    tg_tn_void(0x239A3351AC1DA385, e, cp.P.x, cp.P.y, cp.P.z, false, false, false)
    tg_tn_void(0x8E2530AA8ADA980E, e, tg_normalize_heading(math.deg(cp.psi) - 90.0))
    if in_veh and speed and speed > 0 then tg_tn_void(0xAB54A438726D25D5, e, speed + 0.0) end
end

function tg_pk_tick()
    local s = TG_PK_STATE
    if not s.active then util.yield(500); return end
    local alive = false
    for _, o in ipairs(objects) do if o == s.obj then alive = true; break end end
    if not alive then s.active = false; return end
    local p = tg_minigame_player_position() or nil
    if not p then util.yield(200); return end
    local cps = s.checkpoints
    -- progress: the furthest island whose landing you've been on
    for i = (s.reached or 0) + 1, math.min(#cps, (s.reached or 0) + 3) do
        local cp = cps[i]
        local dx, dy = p.x - cp.P.x, p.y - cp.P.y
        if dx * dx + dy * dy < 45.0 * 45.0 and math.abs(p.z - cp.P.z) < 8.0 then s.reached = i end
    end
    if TG_PK_RESPAWN and (s.reached or 0) >= 1 and not cps[s.reached].noresp then
        local cur = cps[s.reached]
        local nxt = cps[math.min(#cps, s.reached + 1)]
        local floor_z = math.min(cur.P.z, nxt.P.z) - 18.0
        local now = util.current_time_millis()
        if p.z < floor_z and (now - (s.last_respawn or 0)) > 2500 then
            s.last_respawn = now
            s.falls = (s.falls or 0) + 1
            tg_pk_put_at(cur, 14.0)
            tg_toast(string.format("Fell! Back to %s. Falls: %d", (cur.island == 0) and "the start island" or ("island " .. tostring(cur.island)), s.falls), 2500)
        end
    end
    -- v2.0.4: everyone else on the course too
    if TG_PK_RESPAWN and tg_rs_others_course_tick then
        tg_rs_others_course_tick(cps)          -- errors land in the parkour tick guard
    end
    util.yield(100)
end

function tg_pk_arm(meta, obj)
    TG_PK_STATE = { active = true, checkpoints = meta.checkpoints, obj = obj, reached = 0, falls = 0 }
    if not TG_PK_TICK_REGISTERED then
        TG_PK_TICK_REGISTERED = true
        util.create_tick_handler(function()
            tg_pk_tick()
            return true
        end)
    end
end

-- ---------- build ----------
function tg_parkour_build(style_key, diff_key)
    local sel = TG_PK_SEL
    style_key = style_key or sel.style
    if style_key == "random" or not TG_PK_STYLES[style_key] then
        style_key = TG_PK_STYLE_ORDER[math.random(#TG_PK_STYLE_ORDER - 1)]
    end
    diff_key = diff_key or sel.difficulty
    local st = TG_PK_STYLES[style_key]
    tg_rs_build_start("Parkour")
    clear_race_track("parkour")
    TG_TUBEP_SEED_BUMP = (TG_TUBEP_SEED_BUMP or 0) + 7919
    if math.randomseed then math.randomseed(((os.time and os.time()) or 1) + TG_TUBEP_SEED_BUMP) end
    TG_PK_MAX_OBJECTS = tg_rs_limit("parkour")
    tg_toast("Planning " .. st.name .. " (" .. TG_PK_DIFFS[diff_key].name .. string.format(", up to %d objects)...", TG_PK_MAX_OBJECTS), 2500)
    local plans, meta = nil, nil
    tg_rs_stage("Planning islands")
    for attempt = 1, 25 do
        TG_WORLD_OBSTACLE_PROBE_CACHE = {}
        if tg_rs_plan_progress("Parkour", attempt, 25, 0, 1) then return false end
        TG_PK_PLAN_PROGRESS = function(i, n) tg_rs_plan_progress("Parkour", attempt, 25, i, n) end
        TG_RS_TRY_YAW = ({ 0, 0, 0, 0, 0, 25, -25, 0, 45, -45, 0, 70, -70, 0, 90, -90 })[((attempt - 1) % 16) + 1]
        TG_RS_START_BACK = (attempt > 8) or nil      -- v2.3.0: small radius - start further back so the course crosses the whole circle
        plans, meta = tg_pk_plan_course(style_key, diff_key)
        TG_PK_PLAN_PROGRESS = nil
        TG_RS_TRY_YAW = nil
        TG_RS_START_BACK = nil
        tg_log("[PARKOUR][ATTEMPT] " .. style_key .. " #" .. tostring(attempt) .. " " .. (plans and ("pieces=" .. #plans) or tostring(meta)))
        if plans then break end
        if attempt % 3 == 0 then util.yield(0) end
    end
    if tg_rs_check_cancel() then return false end
    if not plans then
        tg_toast("Couldn't fit a " .. st.name .. " course here (" .. tostring(meta) .. "). Face open space and try again.", 4500)
        tg_rs_progress_fail("Couldn't fit a course here - face open space and try again")
        return false
    end
    local all = {}
    for _, p in ipairs(plans) do table.insert(all, p) end
    for _, p in ipairs(meta.props or {}) do table.insert(all, p) end
    tg_rs_preload("Parkour", all)
    local total = #plans + #(meta.props or {})
    local token = tg_generation_start("parkour") or nil
    local placed = 0
    local missed = {}
    for i, plan in ipairs(plans) do
        if tg_generation_should_stop(token, "parkour") then break end
        plan.tint = tg_pk_colour_for(sel.colour, sel.colour_index, i, plan.island)
        if tg_tt_tint then plan.tint = tg_tt_tint(meta.tune, plan, plan.tint) end
        if tg_rs_spawn_progress("Parkour", i, total, "Spawning track") then return false end
        util.yield((#plans > 120) and 20 or (TG_TUBEP_DELAY_MS or 70))
        if tg_tco_spawn_animated(plan, "parkour_" .. tostring(i)) then placed = placed + 1 else table.insert(missed, plan) end
    end
    placed = placed + tg_rs_repair("Parkour", missed, function(plan, k) return tg_tp_spawn(plan, "parkour_fix_" .. tostring(k)) end)
    local placed_props = 0
    for i, p in ipairs(meta.props or {}) do
        if tg_generation_should_stop(token, "parkour") then break end
        if tg_rs_spawn_progress("Parkour", #plans + i, total, "Spawning props") then return false end
        util.yield(40)
        if tg_hy_spawn_prop(p, "parkour_prop_" .. tostring(i)) then placed_props = placed_props + 1 end
    end
    if tg_rs_progress("Parkour", 0.99, "Syncing to the session...") then return false end
    tg_tn_settle_all("parkour")
    tg_tc_timer_arm(meta.start, objects[#objects])
    TG_TUBEC_TIMER.r = 16.0
    TG_TUBEC_TIMER.finish = meta.finish
    TG_TUBEC_TIMER.drive_spot = meta.drive_spot
    TG_TUBEC_TIMER.drive_dir = meta.start.D
    tg_pk_arm(meta, objects[#objects])
    TG_PK_LAST = meta
    tg_log("[PARKOUR][DONE] style=" .. style_key .. " diff=" .. diff_key .. " islands=" .. tostring(meta.islands) .. " placed=" .. tostring(placed) .. "/" .. tostring(#plans))
    tg_toast(string.format("%s: %d islands, %d pieces + %d props. Drive up the ramp ahead - fall off and you're put back on the last island.", st.name, meta.islands, placed, placed_props), 6000)
    tg_rs_progress_done(string.format("%d islands, %d pieces + %d props", meta.islands, placed, placed_props))
    return placed > 0
end

function tg_parkour_build_selected() return tg_parkour_build(TG_PK_SEL.style, TG_PK_SEL.difficulty) end
if tg_tn_wrap then tg_parkour_build = tg_tn_wrap("tg_parkour_build", tg_parkour_build) end

function tg_parkour_goto_start()
    if not TG_PK_LAST then tg_toast("Build a parkour course first.", 2500); return end
    tg_tube_circuit_goto_start()
end

function tg_parkour_cycle(field, order, names)
    TG_PK_SEL[field] = tg_tr_cycle(order, TG_PK_SEL[field])
    local v = TG_PK_SEL[field]
    local label = names and names[v] or (TG_PK_STYLES[v] and TG_PK_STYLES[v].name) or (TG_PK_DIFFS[v] and TG_PK_DIFFS[v].name) or v
    tg_toast("Parkour " .. field .. ": " .. tostring(label), 2500)
end
function tg_parkour_cycle_style() tg_parkour_cycle("style", TG_PK_STYLE_ORDER) end
function tg_parkour_cycle_difficulty() tg_parkour_cycle("difficulty", TG_PK_DIFF_ORDER) end
function tg_parkour_cycle_colour() tg_parkour_cycle("colour", TG_PK_COLOUR_ORDER, TG_PK_COLOUR_NAMES) end
function tg_parkour_next_colour()
    TG_PK_SEL.colour_index = (TG_PK_SEL.colour_index % 15) + 1
    if TG_PK_SEL.colour == "off" then TG_PK_SEL.colour = "single" end
    tg_toast("Parkour colour #" .. tostring(TG_PK_SEL.colour_index), 2000)
end
function tg_parkour_toggle_respawn()
    TG_PK_RESPAWN = not TG_PK_RESPAWN
    tg_toast("Parkour respawn on fall: " .. (TG_PK_RESPAWN and "ON" or "OFF"), 2500)
end

