for _, r in ipairs(TG_HY_SECTION_LIST) do if TG_HY_SEL.sections[r.id] == nil then TG_HY_SEL.sections[r.id] = true end end
for _, id in ipairs(TG_HY_TUBE_SHAPE_IDS) do if TG_HY_SEL.shapes[id] == nil then TG_HY_SEL.shapes[id] = true end end
for _, p in ipairs(TG_HY_PROP_LIST) do if TG_HY_SEL.props[p[1]] == nil then TG_HY_SEL.props[p[1]] = (p[1] ~= "ball_l" and p[1] ~= "tannoy") end end
TG_HY_SEL.panel = TG_HY_SEL.panel or "sections"

function tg_hy_prop_on(key)
    if TG_HY_SEL.mix == "allmix" then return true end
    if TG_HY_SEL.mix == "random" then
        TG_HYS.rand_props = TG_HYS.rand_props or {}
        if TG_HYS.rand_props[key] == nil then TG_HYS.rand_props[key] = math.random() < 0.6 end
        return TG_HYS.rand_props[key]
    end
    return TG_HY_SEL.props[key] == true
end
function tg_hy_shape_on(id) return TG_HY_SEL.mix == "random" or TG_HY_SEL.mix == "allmix" or TG_HY_SEL.shapes[id] == true end

-- ---------- overlap check that understands tubes ----------
function tg_hy_fits(plan, placed, ctx, opts)
    opts = opts or {}
    if ctx and ctx.radius and ctx.rc then
        for _, s in ipairs(plan.samples or {}) do
            local dx, dy = s.x - ctx.rc.x, s.y - ctx.rc.y
            if dx * dx + dy * dy > ctx.radius * ctx.radius then return false, "radius" end
        end
    end
    local skip = opts.skip or 2
    local is_tube = plan.is_tube
    for i = 1, #placed - skip do
        local q = placed[i]
        if q.samples and not (tg_rs_far(plan, q, 26.0)) then
            local tube_pair = is_tube or q.is_tube
            for _, s in ipairs(plan.samples) do
                for _, t in ipairs(q.samples) do
                    local dx, dy, dz = s.x - t.x, s.y - t.y, s.z - t.z
                    if tube_pair then
                        if dx * dx + dy * dy + dz * dz < 24.0 * 24.0 then return false, "overlap" end
                    elseif dx * dx + dy * dy < 26.0 * 26.0 and math.abs(dz) < 12.0 then return false, "overlap" end
                end
            end
        end
    end
    if opts.near_ground and TG_RS_HEIGHTMAP_COURSES and tg_rs_below_world then
        for _, s in ipairs(plan.samples) do if tg_rs_below_world(s, 0.0, -6.0) then return false, "heightmap" end end
    end
    if not opts.near_ground then
        for _, s in ipairs(plan.samples) do
            local g = tg_pk_ground(s.x, s.y, s.z - 60.0)
            if g and s.z < g + (is_tube and 13.0 or 6.0) then return false, "terrain" end
            if TG_RS_HEIGHTMAP_COURSES and tg_rs_below_world(s, 0.0, is_tube and 13.0 or 6.0) then return false, "heightmap" end
        end
        if ctx.world and tg_world_obstacle_line_probe then
            local a, b = plan.samples[1], plan.samples[#plan.samples]
            if tg_world_obstacle_line_probe(a.x, a.y, a.z + 3.0, b.x, b.y, b.z + 3.0, 0, "hybrid") then return false, "building" end
        end
    end
    return true
end

-- ---------- props ----------
function tg_hy_on_tile(tile, along, left, up)
    local d = tg_tp_v(math.cos(tile.next.psi), math.sin(tile.next.psi), 0)
    local l = tg_tp_v(-d.y, d.x, 0)
    return tg_tp_add(tg_tp_add(tg_tp_add(tile.entry, tg_tp_mul(d, along)), tg_tp_mul(l, left or 0.0)), tg_tp_v(0, 0, up or 0.0))
end

function tg_hy_prop(props, model, pos, psi_rad, extra)
    local p = { prop = true, model = model, origin = pos, pitch = 0.0, rollY = 0.0, yaw = tg_normalize_heading(math.deg(psi_rad)) }
    if extra then for k, v in pairs(extra) do p[k] = v end end
    table.insert(props, p)
    return p
end

function tg_hy_add_pins(props, tile, at)
    local rows = { { 0 }, { -1.45, 1.45 }, { -2.9, 0, 2.9 }, { -4.35, -1.45, 1.45, 4.35 } }
    for r, ys in ipairs(rows) do
        for _, y in ipairs(ys) do tg_hy_prop(props, "stt_prop_stunt_bowling_pin", tg_hy_on_tile(tile, at + (r - 1) * 2.5, y, 0.5), tile.next.psi, { dynamic = true }) end
    end
end

-- ---------- tube shape from the end of a flat track tile ----------
function tg_hy_tube_section(state, shape, ctx, plans)
    local up = TG_HY_TUBE_FLOOR
    local ts = { P = tg_tp_add(state.P, tg_tp_v(0, 0, up)), D = tg_tp_v(math.cos(state.psi), math.sin(state.psi), 0), U = tg_tp_v(0, 0, 1) }
    local out = {}
    for _, step in ipairs(shape) do
        local pl = tg_tp_plan(ts, step[1], step[2])
        if not pl then return nil end
        pl.is_tube = true
        -- inside the shape: the tube planner's own clearance rules (skips its neighbours along the tube)
        if not tg_tp_fits(pl, out, { clearance = 20.0 }) then return nil end
        -- against the rest of the course: only the run-up tile right behind the mouth is exempt
        if not tg_hy_fits(pl, plans, ctx, { skip = 1 }) then return nil end
        table.insert(out, pl)
        ts = pl.next
    end
    if math.abs(ts.D.z) > 0.02 or ts.U.z < 0.995 then return nil end
    return out, { P = tg_tp_sub(ts.P, tg_tp_v(0, 0, up)), psi = math.atan(ts.D.y, ts.D.x) }
end

-- ---------- one section ----------
-- returns true on success (plans/props/checkpoints/jumps appended), false to roll back
function tg_hy_run_section(sec, B)
    local df = B.df
    local T = B.tune or {}
    local s = B.state
    local last_flat = B.last_flat
    local island = B.island + 1
    local function flat_tile(key)
        local pl = tg_pk_straight(s, key, 0.0)
        if not tg_hy_fits(pl, B.plans, B.ctx) then return nil end
        pl.island = island; table.insert(B.plans, pl); s = pl.next; last_flat = pl
        return pl
    end
    local function deck_len(t) return t and TG_PK_PIECES[t.key] and TG_PK_PIECES[t.key].len or 0 end
    for _, st in ipairs(sec.steps) do
        local op = st[1]
        if op == "run" then
            if not flat_tile(st[2]) then return false end
        elseif op == "turn" then
            local side = (st[3] == "L" and 1) or (st[3] == "R" and -1) or ((math.random() < 0.5) and 1 or -1)
            local n = (st[3] == "U") and 2 or 1
            for _ = 1, n do
                local b = tg_pk_bend(s, st[2], side)
                if not tg_hy_fits(b, B.plans, B.ctx) then return false end
                b.island = island; table.insert(B.plans, b); s = b.next
            end
            if not flat_tile("m") then return false end
        elseif op == "tube" then
            local cands = {}
            for _, id in ipairs(st[2]) do if tg_hy_shape_on(id) then table.insert(cands, id) end end
            if #cands == 0 then for _, id in ipairs(TG_HY_TUBE_SHAPE_IDS) do if tg_hy_shape_on(id) then table.insert(cands, id) end end end
            if #cands == 0 then return false end
            local id = cands[math.random(#cands)]
            local mod = TG_TUBE_MODULE_BY_ID[id]
            local seq = tg_tm_template(mod, "", nil, false)
            if not seq then return false end
            -- a short flat run so the tube mouth isn't straight off a landing edge
            if not last_flat or last_flat ~= B.plans[#B.plans] then if not flat_tile("m") then return false end end
            local pre_boost = tg_hy_prop_on("boost") and math.random() < (T.preboost or 0.4)
            if pre_boost and last_flat then tg_hy_prop(B.props, "stt_prop_track_speedup_t1", tg_hy_on_tile(last_flat, deck_len(last_flat) * 0.5, 0, -0.11), last_flat.next.psi) end
            local tubes, exit = tg_hy_tube_section(s, seq, B.ctx, B.plans)
            if not tubes then return false end
            for _, tp in ipairs(tubes) do tp.island = island; table.insert(B.plans, tp) end
            s = exit
            local out = tg_pk_straight(s, T.tube_exit or "lm", 0.0)
            if not tg_hy_fits(out, B.plans, B.ctx, { skip = 1 }) then return false end
            out.island = island; table.insert(B.plans, out); s = out.next; last_flat = out
            table.insert(B.checkpoints, { P = tg_hy_on_tile(out, 15.0, 0, 2.5), psi = out.next.psi, island = island })
            B.counts.tubes = B.counts.tubes + 1
            B.shapes_used[id] = (B.shapes_used[id] or 0) + 1
        elseif op == "jump" then
            local kind = st[2]
            if kind == "?" then kind = ({ "tile", "a", "b", "c", "hop", "drop", "up" })[math.random(7)] end
            local forced_up = (kind == "upforce")
            if forced_up then kind = "up" end
            -- v2.0 jump kinds: hop (small kicker, short gap), drop (short gap, big drop), up (big ramp onto a HIGHER island)
            local rampkey = kind
            if kind == "up" then rampkey = "c" end
            if kind == "hop" or kind == "drop" then rampkey = "tile" end
            if rampkey ~= "tile" and not forced_up and not tg_hy_prop_on("ramp_" .. rampkey) then rampkey = "tile"; if kind == "up" then kind = "tile" end end
            local ramp = (rampkey ~= "tile") and TG_HY_RAMPS[rampkey] or nil
            local kick_angle, lip_h
            if ramp then
                local tile = flat_tile("m")
                if not tile then return false end
                tile.kicker = true
                table.insert(B.props, { prop = true, model = ramp.model, origin = tg_hy_on_tile(tile, 53.0 - ramp.back, 0, ramp.up), pitch = 0, rollY = 0, yaw = tg_normalize_heading(math.deg(tile.next.psi)) })
                kick_angle, lip_h = ramp.angle, ramp.lip
            else
                if not last_flat or last_flat ~= B.plans[#B.plans] then if not flat_tile("m") then return false end end
                local ang = ((kind == "hop") and 5.0 or ((kind == "drop") and 4.0 or 7.0)) * (T.kick_k or 1.0)
                local k = tg_pk_straight(s, (kind == "hop") and "s" or "m", ang)
                if not tg_hy_fits(k, B.plans, B.ctx) then return false end
                k.island = island; k.kicker = true; table.insert(B.plans, k); s = k.next
                kick_angle, lip_h = ang, 0.0
            end
            local mark = #B.plans
            local t = B.t
            if T.curve then t = t ^ T.curve end
            local gr = T.grand or 1.0
            local gap = tg_pk_lerp(T.g0 or 12.0, T.g1 or 20.0, t) * df.gap * (ramp and (T.ramp_gap or 1.25) or 1.0) + tg_pk_rand(-gr, gr)
            local drop = (T.jdrop or 5.0) * df.drop
            local kick_len = (kind == "hop") and 17.67 or 53.0
            if kind == "hop" then gap = tg_pk_lerp(8.0, 12.0, t) * (T.hop_k or 1.0) * df.gap + tg_pk_rand(-0.5, 0.5); drop = 2.5 * df.drop
            elseif kind == "drop" then gap = tg_pk_lerp(6.0, 10.0, t) * df.gap + tg_pk_rand(-0.5, 0.5); drop = tg_pk_rand((T.ddepth or 11.0) - 2.0, (T.ddepth or 11.0) + 2.0) * df.drop
            elseif kind == "up" then gap = tg_pk_lerp(8.0, 12.0, t) * df.gap; drop = -tg_pk_rand((T.uheight or 5.5) - 1.5, (T.uheight or 5.5) + 1.5) end
            local level = s.P.z - ((ramp or kick_angle == 0) and 0 or (kick_len * math.sin(math.rad(kick_angle)))) - drop
            local lip = s
            local wob = T.wobble or 6
            local land = { P = tg_tp_v(lip.P.x + math.cos(lip.psi) * gap, lip.P.y + math.sin(lip.psi) * gap, level), psi = lip.psi + math.rad(tg_pk_rand(-wob, wob)) }
            if B.ctx.world and tg_world_obstacle_line_probe then
                if tg_world_obstacle_line_probe(lip.P.x, lip.P.y, lip.P.z + lip_h + 2.0, land.P.x, land.P.y, land.P.z + 2.0, 0, "hybrid_gap") then return false end
            end
            local lkey = (ramp and ramp.lip > 10 and kind ~= "up") and "l" or ((kind == "hop") and "m" or (T.land or "lm"))
            local landing = tg_pk_straight(land, lkey, 0.0)
            if not tg_hy_fits(landing, B.plans, B.ctx, { skip = 3 }) then return false end
            landing.tt_gap = true
            landing.island = island; table.insert(B.plans, landing); s = landing.next; last_flat = landing
            table.insert(B.checkpoints, { P = tg_hy_on_tile(landing, 12.0, 0, 2.5), psi = landing.next.psi, island = island })
            table.insert(B.jumps, { gap = gap, drop = (lip.P.z + lip_h) - level, kick = kick_angle, land_len = TG_PK_PIECES[lkey].len, ramp = ramp and ramp.model or "", up = (kind == "up") })
            B.counts.jumps = B.counts.jumps + 1
        else
            -- props that sit on the last flat deck
            local deck = last_flat
            local len = deck_len(deck)
            if deck and len >= 53 then
                if op == "boost" and tg_hy_prop_on("boost") then
                    tg_hy_prop(B.props, "stt_prop_track_speedup_t1", tg_hy_on_tile(deck, len * 0.55, 0, -0.11), deck.next.psi)
                elseif op == "boost2" and tg_hy_prop_on("boost2") then
                    tg_hy_prop(B.props, "stt_prop_track_speedup_t2", tg_hy_on_tile(deck, len * 0.55, 0, 0.03), deck.next.psi)
                elseif op == "gate" and tg_hy_prop_on("gate") then
                    tg_hy_prop(B.props, "ar_prop_ar_neon_gate_04a", tg_hy_on_tile(deck, len * 0.5, 0, 2.62), deck.next.psi + math.pi)
                elseif op == "pins" and tg_hy_prop_on("pins") and len >= 106 and not TG_HYS.pins_used then
                    TG_HYS.pins_used = true
                    tg_hy_add_pins(B.props, deck, len * 0.62)
                elseif op == "balls" and len >= 53 then
                    local sizes = {}
                    if tg_hy_prop_on("ball_s") then table.insert(sizes, "stt_prop_stunt_soccer_sball") end
                    if tg_hy_prop_on("ball_m") then table.insert(sizes, "stt_prop_stunt_soccer_ball") end
                    if tg_hy_prop_on("ball_l") then table.insert(sizes, "stt_prop_stunt_soccer_lball") end
                    if #sizes > 0 then
                        for _, y in ipairs(T.ball_ys or { -6.0, 0.0, 6.0 }) do
                            tg_hy_prop(B.props, sizes[math.random(#sizes)], tg_hy_on_tile(deck, len * 0.6 + math.random() * 10.0, y, 6.0), deck.next.psi, { dynamic = true })
                        end
                    end
                elseif op == "bball" and tg_hy_prop_on("bball") then
                    tg_hy_prop(B.props, "stt_prop_stunt_bowling_ball", tg_hy_on_tile(deck, len * 0.75, (math.random() < 0.5) and -4.0 or 4.0, 4.0), deck.next.psi, { dynamic = true })
                elseif op == "tyres" and tg_hy_prop_on("tyres") and len >= 106 then
                    local nt = T.tyres or 4
                    for k = 1, nt do
                        tg_hy_prop(B.props, "stt_prop_tyre_wall_01", tg_hy_on_tile(deck, 20.0 + k * (T.tyres and ((len - 30.0) / nt) or 18.0), ((k % 2 == 0) and 1 or -1) * 5.0, 0.08), deck.next.psi + math.pi * 0.5)
                    end
                end
            end
        end
    end
    -- v2.0.5: a random stunt object (a different one every time) at the side of the last deck
    if last_flat and tg_rs_stunt_plan and tg_hy_prop_on("stunts") and math.random() < (TG_HY_STUNT_P or T.stunt_p or ((TG_HY_SEL.mix == "allmix") and 0.9 or 0.45)) then
        local sp = tg_rs_stunt_plan(B.props, last_flat)
        if sp then sp.island = island end
        if sp and TG_HY_STUNT_P then          -- v2.0.7 Arena Gauntlet: a second hazard further down the deck, other side
            local sp2 = tg_rs_stunt_plan(B.props, last_flat, 0.62 + math.random() * 0.1)
            if sp2 then sp2.island = island; sp2.side = -sp.side end
        end
    end
    B.state = s
    B.last_flat = last_flat
    B.island = island
    return true
end

-- weighted pick of an enabled section, flavoured by the mix
function tg_hy_pick_section(B)
    local sel = TG_HY_SEL
    local mix = TG_HY_MIXES[sel.mix] or TG_HY_MIXES.balanced
    local total, list = 0.0, {}
    for _, r in ipairs(TG_HY_SECTION_LIST) do
        local on = (sel.mix == "random") or (sel.mix == "allmix") or sel.sections[r.id]
        if on then
            local w = 1.0
            local TT = B.tune
            if mix.tube then
                local mt, mj, mp = mix.tube, mix.jump, mix.prop
                if TT and TT.mixw then mt, mj, mp = TT.mixw[1], TT.mixw[2], TT.mixw[3] end
                w = ((TT and TT.base_w) or 0.3) + r.tubes * mt + r.jumps * mj + r.props * mp * 0.7
            end
            if B.recent[r.id] then w = w * ((TT and TT.repeat_k) or 0.3) end
            total = total + w
            table.insert(list, { r, w })
        end
    end
    if #list == 0 then return TG_HY_SECTION_BY_ID.boostleap end
    local x = math.random() * total
    for _, e in ipairs(list) do x = x - e[2]; if x <= 0 then return e[1] end end
    return list[#list][1]
end

TG_HY_UP_SECTION = { id = "_climb", name = "Climb Back Up", steps = { { "boost" }, { "jump", "upforce" } } }
-- ---------- planner ----------
function tg_hy_plan_course()
    local sel = TG_HY_SEL
    local T = tg_tt_take("hybrid") or nil
    local df = TG_PK_DIFFS[sel.difficulty] or TG_PK_DIFFS.normal
    local lenp = TG_HY_LENGTHS[sel.length] or TG_HY_LENGTHS.medium
    local slo, shi = tg_rs_scale_range(lenp.segs, TG_HY_MAX_OBJECTS or 73)
    if (TG_HY_MAX_OBJECTS or 73) > 90 then slo, shi = math.floor(slo * 1.4), math.floor(shi * 1.6) end
    local n_segs = math.random(slo, shi)
    if T and T.segs then n_segs = math.random(math.max(2, T.segs - 1), T.segs + 1) end
    local rad0 = tg_rs_radius("hybrid") or nil       -- v2.3.0 radius: fewer sections
    if rad0 then n_segs = math.min(n_segs, math.max(3, math.floor(rad0 / 110.0))) end
    local long_course = n_segs > lenp.segs[2]
    local pos, heading = tg_get_local_position_heading("hybrid")
    TG_RS_NEAR = { P = { x = pos.x, y = pos.y }, r = 220.0 }
    heading = tonumber(heading or 0.0) or 0.0
    -- v2.0.3: after a few blocked attempts, try starting a little to the left / right
    heading = heading + (TG_RS_TRY_YAW or 0.0)
    local fx, fy = calculate_new_position({ x = 0.0, y = 0.0, z = 0.0 }, heading, 1.0, 0.0, 0.0)
    local psi0 = math.atan(fy, fx)
    local F = tg_tp_v(math.cos(psi0), math.sin(psi0), 0)
    local ctx = { world = (TG_WORLD_OBSTACLE_AVOIDANCE ~= false) }
    -- v2.3.0 radius: the whole course stays inside this circle round you
    ctx.radius = tg_rs_radius("hybrid") or nil
    ctx.rc = { x = pos.x, y = pos.y }
    if ctx.radius then ctx.leash = math.max(90.0, ctx.radius * 0.4) end
    TG_PK_GROUND_CACHE = {}

    local B = { plans = {}, props = {}, checkpoints = {}, jumps = {}, counts = { jumps = 0, tubes = 0, sections = 0 }, ctx = ctx, df = df,
                island = 0, recent = {}, shapes_used = {}, sections_used = {}, tune = T }
    local sg = tg_tp_add(tg_tp_v(pos.x, pos.y, pos.z), tg_tp_mul(F, 35.0))
    if ctx.radius and TG_RS_START_BACK then sg = tg_tp_add(tg_tp_v(pos.x, pos.y, pos.z), tg_tp_mul(F, -ctx.radius * 0.5)) end
    local ground_s = tg_tr_ground_z(sg.x, sg.y, pos.z - 1.0)
    local state = { P = tg_tp_v(sg.x, sg.y, ground_s - TG_PK_ENTRY_SINK), psi = psi0 }
    local start_gate = { P = state.P, D = F, U = tg_tp_v(0, 0, 1), r = 16.0 }
    local drive_spot = tg_tp_sub(sg, tg_tp_mul(F, 28.0)); drive_spot.z = ground_s + 1.0
    -- every jump drops ~5 m (plus kicker rise); start high enough for a jumpy course
    local target = ground_s + math.min(95.0, math.max(32.0, n_segs * 0.8 * (((T and T.jdrop) or 5.0) * df.drop + 6.0) + 18.0))
    if T and T.start_bonus then target = target + T.start_bonus end
    if ctx.radius then target = math.min(target, ground_s + math.max(24.0, ctx.radius * 0.09)) end   -- v2.3.0: lower = shorter ramps
    -- v2.0.3: tall buildings / hills ahead (height map): start high enough to clear them
    local hahead = TG_RS_HEIGHTMAP_COURSES and tg_rs_height_ahead(state.P, psi0, 240, 760) or nil
    if hahead and hahead + 16.0 > target then target = math.min(ground_s + 120.0, hahead + 16.0) end
    local rpitch = ctx.radius and math.max((T and T.rpitch) or TG_PK_RAMP_PITCH, 13.0) or ((T and T.rpitch) or TG_PK_RAMP_PITCH)   -- v2.3.0: steeper, shorter ramp inside a radius
    local rise = 53.0 * math.sin(math.rad(rpitch))
    local guard = 0
    while state.P.z + rise * 0.5 < target and guard < 26 do
        guard = guard + 1
        local pl = tg_pk_straight(state, "m", rpitch)
        if not tg_hy_fits(pl, B.plans, ctx, { near_ground = true }) then return nil, "ramp" end
        table.insert(B.plans, pl); state = pl.next
    end
    local first = tg_pk_straight(state, ctx.radius and "m" or "lm", 0.0)
    if not tg_hy_fits(first, B.plans, ctx, { near_ground = true }) then return nil, "start" end
    first.island = 0; table.insert(B.plans, first)
    if tg_hy_prop_on("gantry") then tg_hy_prop(B.props, "stt_prop_race_gantry_01", tg_hy_on_tile(first, 18.0, 0, 0.05), first.next.psi) end
    -- decor beside the drive-up spot (on the ground, off the course)
    local Lv = tg_tp_v(-F.y, F.x, 0)
    for _, side in ipairs({ -1, 1 }) do
        local spot = tg_tp_add(sg, tg_tp_mul(Lv, side * 22.0))
        spot.z = (tg_pk_ground(spot.x, spot.y, ground_s + 5.0) or ground_s)
        if tg_hy_prop_on("speakers") then tg_hy_prop(B.props, "stt_prop_speakerstack_01a", spot, psi0 + (side > 0 and -math.pi / 2 or math.pi / 2)) end
        if tg_hy_prop_on("tannoy") then
            local t2 = tg_tp_add(spot, tg_tp_mul(F, -10.0)); t2.z = (tg_pk_ground(t2.x, t2.y, ground_s + 5.0) or ground_s)
            tg_hy_prop(B.props, "stt_prop_race_tannoy", t2, psi0)
        end
    end
    table.insert(B.checkpoints, { P = tg_hy_on_tile(first, 12.0, 0, 2.5), psi = first.next.psi, island = 0 })
    B.state = first.next
    B.last_flat = first

    local made = 0
    for i = 1, n_segs do
        B.t = (n_segs > 1) and (i - 1) / (n_segs - 1) or 0
        if long_course then B.t = ((i - 1) % 8) / 7 end
        -- long courses: climb back up when low, and turn back toward the start when far away
        local cur = B.state
        local g = tg_pk_ground(cur.P.x, cur.P.y, cur.P.z - 60.0)
        local low = g and (cur.P.z - g) < ((T and T.climb_back) or 34.0)
        local dx, dy = start_gate.P.x - cur.P.x, start_gate.P.y - cur.P.y
        local far = math.sqrt(dx * dx + dy * dy)
        local leash = nil
        if far > (ctx.leash or (T and T.leash) or TG_HY_LEASH or 1400.0) then
            local hx, hy = math.cos(cur.psi), math.sin(cur.psi)
            if (hx * dx + hy * dy) / far < 0.2 then leash = ((hx * dy - hy * dx) >= 0) and "L" or "R" end
        end
        local done = false
        for attempt = 1, 10 do
            local sec = (attempt <= 8) and tg_hy_pick_section(B) or TG_HY_SECTION_BY_ID.boostleap
            if low and attempt <= 6 then sec = TG_HY_UP_SECTION
            elseif leash and attempt <= 6 then sec = { id = "_leash", name = "Turn Back", steps = { { "turn", "b90", leash }, { "jump", "tile" } } } end
            local snap = { #B.plans, #B.props, #B.checkpoints, #B.jumps, B.state, B.last_flat, B.island, B.counts.jumps, B.counts.tubes, TG_HYS.pins_used }
            if tg_hy_run_section(sec, B) then
                done = true
                B.counts.sections = B.counts.sections + 1
                B.recent = { [sec.id] = true }
                table.insert(B.sections_used, sec.name)
                break
            end
            while #B.plans > snap[1] do table.remove(B.plans) end
            while #B.props > snap[2] do table.remove(B.props) end
            while #B.checkpoints > snap[3] do table.remove(B.checkpoints) end
            while #B.jumps > snap[4] do table.remove(B.jumps) end
            B.state, B.last_flat, B.island, B.counts.jumps, B.counts.tubes, TG_HYS.pins_used = snap[5], snap[6], snap[7], snap[8], snap[9], snap[10]
        end
        if not done then
            if made >= (ctx.radius and 1 or (lenp.segs[1] + 1)) then break end      -- ran out of room: finish here
            return nil, "section " .. tostring(i)
        end
        made = made + 1
        if TG_HY_PLAN_PROGRESS then TG_HY_PLAN_PROGRESS(i, n_segs) end
        if tg_rs_check_cancel() then return nil, "cancelled" end
        if i % 3 == 0 then util.yield(0) end
        if #B.plans + #B.props > TG_HY_MAX_OBJECTS - ((T and math.max(12, math.ceil((B.state.P.z - ground_s) / (53.0 * math.sin(math.rad((T and T.rpitch) or TG_PK_RAMP_PITCH)))) + 6)) or 12) then break end
    end
    n_segs = made

    -- ramp down to the ground + finish gantry
    state = B.state

    -- v2.3.0 radius: turn back toward the middle before the descent so it stays inside the circle
    if ctx.radius and ctx.rc then
        for _ = 1, 2 do
            local dx, dy = ctx.rc.x - state.P.x, ctx.rc.y - state.P.y
            local d = math.sqrt(dx * dx + dy * dy)
            local hx, hy = math.cos(state.psi), math.sin(state.psi)
            if d < 1.0 or (hx * dx + hy * dy) / d > 0.3 then break end
            local side = ((hx * dy - hy * dx) >= 0) and 1 or -1
            local b = tg_pk_bend(state, "b90", side)
            if not b or not tg_hy_fits(b, B.plans, ctx) then break end
            table.insert(B.plans, b); state = b.next
        end
    end
    local guard2 = 0
    while guard2 < 26 do
        guard2 = guard2 + 1
        local pl = tg_pk_straight(state, "m", -((T and T.rpitch) or TG_PK_RAMP_PITCH))
        local g = tg_pk_ground(pl.next.P.x, pl.next.P.y, pl.next.P.z - 60.0) or (pl.next.P.z - 100.0)
        if not tg_hy_fits(pl, B.plans, ctx, { near_ground = true }) then return nil, "descent" end
        if TG_RS_HEIGHTMAP_COURSES and tg_rs_descent_blocked(pl.next.P, tg_pk_ground(pl.next.P.x, pl.next.P.y, pl.next.P.z - 60.0)) then return nil, "descent building" end
        table.insert(B.plans, pl); state = pl.next
        if state.P.z <= g then break end
    end
    if tg_hy_prop_on("gantry") then
        local fg = tg_tp_add(state.P, tg_tp_v(math.cos(state.psi) * 14.0, math.sin(state.psi) * 14.0, 0))
        fg.z = (tg_pk_ground(fg.x, fg.y, fg.z + 20.0) or fg.z) + 0.05
        tg_hy_prop(B.props, "stt_prop_race_gantry_01", fg, state.psi)
    end
    while #B.plans + #B.props > TG_HY_MAX_OBJECTS and #B.props > 0 do table.remove(B.props) end
    if #B.plans > TG_HY_MAX_OBJECTS then return nil, "too many pieces" end
    local finish_gate = { P = state.P, D = tg_tp_v(math.cos(state.psi), math.sin(state.psi), 0), r = 16.0 }
    return B.plans, { props = B.props, start = start_gate, finish = finish_gate, drive_spot = drive_spot, checkpoints = B.checkpoints,
                      jumps = B.jumps, counts = B.counts, segments = n_segs, sections_used = B.sections_used, shapes_used = B.shapes_used, tune = T }
end

-- ---------- spawning ----------
function tg_hy_spawn_prop(p, label)
    if p.stunt then return tg_rs_spawn_stunt(p, label) or nil end
    local o = p.origin
    -- v2.0.1: online, physics props are the heaviest thing to sync. Courses keep at most a handful
    -- (minigames that need them are exempt) and the giant soccer ball becomes the normal one.
    local B = TG_RS_BUILD
    if p.dynamic and B and B.online and B.label ~= "Minigame" then
        if p.model == "stt_prop_stunt_soccer_lball" then p.model = "stt_prop_stunt_soccer_ball" end
        if (B.dynamic or 0) >= (TG_RS_MAX_DYNAMIC_ONLINE or 10) then return nil end
        B.dynamic = (B.dynamic or 0) + 1
    end
    local obj = tg_try_create_stunt_tube_model(p.model, o.x, o.y, o.z, p.yaw, label)
    if not obj then return nil end
    if p.dynamic then
        tg_tn_void(0x428CA6DBD1094446, obj, false)          -- FREEZE_ENTITY_POSITION
        tg_tn_void(0x1718DE8E3F2823CA, obj, true)           -- SET_ENTITY_DYNAMIC
        tg_tn_void(0x4A4722448F18EEF5, obj, true)           -- SET_ENTITY_HAS_GRAVITY
        tg_tn_void(0x710311ADF0E20730, obj)                 -- ACTIVATE_PHYSICS
        tg_tn_harden(obj, nil)
    else
        tg_tube3d_apply_rotation(obj, 0.0, 0.0, p.yaw, label)
        tg_tn_harden(obj, { x = o.x, y = o.y, z = o.z, pitch = 0.0, roll = 0.0, yaw = p.yaw, model = p.model })
    end
    if p.tint and tg_pk_tint then tg_pk_tint(obj, p.tint) end
    p.handle = obj
    return obj
end

function tg_hybrid_build(mix_override)
    local sel = TG_HY_SEL
    if mix_override then
        local keep = sel.mix
        sel.mix = mix_override
        local r = tg_hybrid_build_inner()
        sel.mix = keep
        return r
    end
    return tg_hybrid_build_inner()
end
function tg_hybrid_build_inner()
    local sel = TG_HY_SEL
    tg_rs_build_start("Hybrid")
    clear_race_track("hybrid")
    TG_TUBEP_SEED_BUMP = (TG_TUBEP_SEED_BUMP or 0) + 7919
    if math.randomseed then math.randomseed(((os.time and os.time()) or 1) + TG_TUBEP_SEED_BUMP) end
    local mixname = (TG_HY_MIXES[sel.mix] or TG_HY_MIXES.balanced).name
    TG_HY_MAX_OBJECTS = tg_rs_limit("hybrid")
    tg_toast("Planning Hybrid course (" .. mixname .. ", " .. TG_HY_LENGTHS[sel.length].name .. string.format(", up to %d objects)...", TG_HY_MAX_OBJECTS), 2500)
    local plans, meta = nil, nil
    tg_rs_stage("Planning sections")
    for attempt = 1, 30 do
        TG_HYS.rand_props, TG_HYS.pins_used = nil, nil
        TG_WORLD_OBSTACLE_PROBE_CACHE = {}
        if tg_rs_plan_progress("Hybrid", attempt, 30, 0, 1) then return false end
        TG_HY_PLAN_PROGRESS = function(i, n) tg_rs_plan_progress("Hybrid", attempt, 30, i, n) end
        TG_RS_TRY_YAW = ({ 0, 0, 0, 0, 0, 25, -25, 0, 45, -45, 0, 70, -70, 0, 90, -90 })[((attempt - 1) % 16) + 1]
        TG_RS_START_BACK = (attempt > 8) or nil      -- v2.3.0: small radius - start further back so the course crosses the whole circle
        plans, meta = tg_hy_plan_course()
        TG_HY_PLAN_PROGRESS = nil
        TG_RS_TRY_YAW = nil
        TG_RS_START_BACK = nil
        tg_log("[HYBRID][ATTEMPT] #" .. tostring(attempt) .. " " .. (plans and ("pieces=" .. #plans .. " props=" .. #meta.props) or tostring(meta)))
        if plans then break end
        if attempt % 3 == 0 then util.yield(0) end
    end
    if tg_rs_check_cancel() then return false end
    if not plans then
        tg_toast("Couldn't fit a Hybrid course here (" .. tostring(meta) .. "). Face open space and try again.", 4500)
        tg_rs_progress_fail("Couldn't fit a course here - face open space and try again")
        return false
    end
    local all = {}
    for _, p in ipairs(plans) do table.insert(all, p) end
    for _, p in ipairs(meta.props) do table.insert(all, p) end
    tg_rs_preload("Hybrid", all)
    local total = #all
    local token = tg_generation_start("hybrid") or nil
    local placed, placed_props = 0, 0
    local missed = {}
    for i, plan in ipairs(plans) do
        if tg_generation_should_stop(token, "hybrid") then break end
        plan.tint = tg_pk_colour_for(sel.colour, sel.colour_index, i, plan.island)
        if tg_tt_tint then plan.tint = tg_tt_tint(meta.tune, plan, plan.tint) end
        if tg_rs_spawn_progress("Hybrid", i, total, plan.is_tube and "Spawning tube" or "Spawning track") then return false end
        util.yield((#plans > 120) and 20 or (TG_TUBEP_DELAY_MS or 70))
        if tg_tco_spawn_animated(plan, "hybrid_" .. tostring(i)) then placed = placed + 1 else table.insert(missed, plan) end
    end
    placed = placed + tg_rs_repair("Hybrid", missed, function(plan, k) return tg_tp_spawn(plan, "hybrid_fix_" .. tostring(k)) end)
    for i, p in ipairs(meta.props) do
        if tg_generation_should_stop(token, "hybrid") then break end
        if tg_rs_spawn_progress("Hybrid", #plans + i, total, "Spawning props") then return false end
        util.yield(40)
        if tg_hy_spawn_prop(p, "hybrid_prop_" .. tostring(i)) then placed_props = placed_props + 1 end
    end
    if tg_rs_progress("Hybrid", 0.99, "Syncing to the session...") then return false end
    tg_tn_settle_all("hybrid")
    tg_tc_timer_arm(meta.start, objects[#objects])
    TG_TUBEC_TIMER.r = 16.0
    TG_TUBEC_TIMER.finish = meta.finish
    TG_TUBEC_TIMER.drive_spot = meta.drive_spot
    TG_TUBEC_TIMER.drive_dir = meta.start.D
    tg_pk_arm(meta, objects[1])
    TG_PK_LAST = meta
    TG_HY_LAST = meta
    tg_log(string.format("[HYBRID][DONE] mix=%s sections=%d jumps=%d tubes=%d pieces=%d props=%d (%s)", sel.mix, meta.counts.sections, meta.counts.jumps, meta.counts.tubes, placed, placed_props, table.concat(meta.sections_used, ", ")))
    tg_toast(string.format("Hybrid: %d sections, %d jumps, %d tube shapes, %d props (%d objects). Drive up the ramp ahead!",
        meta.counts.sections, meta.counts.jumps, meta.counts.tubes, placed_props, placed + placed_props), 6000)
    tg_rs_progress_done(string.format("%d sections, %d objects", meta.counts.sections, placed + placed_props))
    return placed > 0
end
if tg_tn_wrap then tg_hybrid_build = tg_tn_wrap("tg_hybrid_build", tg_hybrid_build) end

function tg_hybrid_goto_start()
    if not TG_HY_LAST then tg_toast("Build a Hybrid course first.", 2500); return end
    tg_tube_circuit_goto_start()
end

-- ---------- buttons / panel ----------
function tg_hybrid_cycle_mix()
    TG_HY_SEL.mix = tg_tr_cycle(TG_HY_MIX_ORDER, TG_HY_SEL.mix)
    tg_toast("Hybrid mix: " .. TG_HY_MIXES[TG_HY_SEL.mix].name, 2500)
end
function tg_hybrid_cycle_length()
    TG_HY_SEL.length = tg_tr_cycle(TG_HY_LENGTH_ORDER, TG_HY_SEL.length)
    tg_toast("Hybrid length: " .. TG_HY_LENGTHS[TG_HY_SEL.length].name, 2500)
end
function tg_hybrid_cycle_difficulty()
    TG_HY_SEL.difficulty = tg_tr_cycle(TG_PK_DIFF_ORDER, TG_HY_SEL.difficulty)
    tg_toast("Hybrid difficulty: " .. TG_PK_DIFFS[TG_HY_SEL.difficulty].name, 2500)
end
function tg_hybrid_cycle_colour()
    TG_HY_SEL.colour = tg_tr_cycle(TG_PK_COLOUR_ORDER, TG_HY_SEL.colour)
    tg_toast("Hybrid colours: " .. TG_PK_COLOUR_NAMES[TG_HY_SEL.colour], 2500)
end
function tg_hybrid_set_all(group, value)
    local t = TG_HY_SEL[group]
    for k in pairs(t) do t[k] = value end
    TG_HY_SEL.mix = "custom"
    tg_toast("Hybrid " .. group .. ": all " .. (value and "ON" or "OFF") .. " (mix set to Custom)", 2500)
end
function tg_hybrid_toggle_prop(key)
    TG_HY_SEL.props[key] = not TG_HY_SEL.props[key]
    if TG_HY_SEL.mix == "random" then TG_HY_SEL.mix = "custom" end
    tg_toast("Hybrid prop " .. key .. ": " .. (TG_HY_SEL.props[key] and "ON" or "OFF"), 2500)
end


-- toggle anything by key (FeatureMgr fallback buttons)
function tg_hybrid_toggle(key)
    local sel = TG_HY_SEL
    for _, group in ipairs({ "props", "sections", "shapes" }) do
        if sel[group][key] ~= nil then
            sel[group][key] = not sel[group][key]
            if sel.mix == "random" then sel.mix = "custom" end
            tg_toast("Hybrid " .. key .. ": " .. (sel[group][key] and "ON" or "OFF"), 2500)
            return
        end
    end
end

-- v2.0 TrackMatic: build once with every section / shape / prop on, without touching your Custom picks
function tg_hybrid_random_all() return tg_hybrid_build("allmix") end
-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.4.0 arcade: 30 creative minigames built from the tube / parkour / hybrid generators,
-- floating arenas, runways and stunt props. Every layout stays under the 75-object limit.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_AR = TG_AR or { sel = "gaterush", best = {}, active = nil }
TG_AR_MAX = 73

-- ---------- small helpers ----------
function tg_tn_float(h, ...)
    return tonumber(Natives.InvokeFloat(h, ...)) or 0.0
end
function tg_ar_now() return util.current_time_millis() end
function tg_ar_player()
    local p = tg_minigame_player_position() or nil
    local ent, in_veh = 0, false
    if tg_pk_vehicle_or_ped then ent, in_veh = tg_pk_vehicle_or_ped() end
    local P = { pos = p and tg_tp_v(p.x, p.y, p.z) or nil, ent = ent, in_veh = in_veh }
    P.speed = (ent and ent ~= 0) and tg_tn_float(0xD5037BA82E12416F, ent) or 0.0          -- GET_ENTITY_SPEED
    P.air = (ent and ent ~= 0) and tg_tn_bool(0x886E37EC497200B6, ent) or false           -- IS_ENTITY_IN_AIR
    return P
end
function tg_ar_epos(h) return h and h ~= 0 and tg_tn_v3(0x3FEF770D40960D5A, h, false) or nil end
function tg_ar_erot(h) return h and h ~= 0 and tg_tn_v3(0xAFBD61CC738D9EB9, h, 2) or nil end
function tg_ar_delete(h)
    if not h or h == 0 then return end
    tg_delete(h)
    for i = #objects, 1, -1 do if objects[i] == h then table.remove(objects, i) end end
    if TG_TUBENET_PIECES then TG_TUBENET_PIECES[h] = nil end
end
function tg_ar_put(P, psi, speed)
    tg_pk_put_at({ P = P, psi = psi }, speed or 0.0)
end
function tg_ar_fmt_time(ms) return string.format("%.2fs", (ms or 0) / 1000.0) end
function tg_ar_toast(msg, ms) tg_toast(msg, ms or 3000); if TG_AR.active then TG_AR.active.status = msg end end

-- signed-distance gate crossing (like the race timer); key keeps the previous side per gate
function tg_ar_cross(G, key, gate, pos)
    local rel = tg_tp_sub(pos, gate.P)
    local s = tg_tp_dot(rel, gate.D)
    local lat = tg_tp_len(tg_tp_sub(rel, tg_tp_mul(gate.D, s)))
    local prev = G.cross[key]
    G.cross[key] = s
    return prev and prev < 0.0 and s >= 0.0 and lat < (gate.r or 16.0) and (s - prev) < 60.0
end
function tg_ar_near(a, b, r, dz) return a and b and ((a.x - b.x) ^ 2 + (a.y - b.y) ^ 2) < r * r and math.abs(a.z - b.z) < (dz or 10.0) end

-- ---------- layout builder ----------
function tg_ar_frame()
    local pos, heading = tg_get_local_position_heading("arcade")
    heading = tonumber(heading or 0.0) or 0.0
    local fx, fy = calculate_new_position({ x = 0.0, y = 0.0, z = 0.0 }, heading, 1.0, 0.0, 0.0)
    local psi = math.atan(fy, fx)
    local F = tg_tp_v(math.cos(psi), math.sin(psi), 0)
    local sg = tg_tp_add(tg_tp_v(pos.x, pos.y, pos.z), tg_tp_mul(F, 35.0))
    local ground = tg_tr_ground_z(sg.x, sg.y, pos.z - 1.0)
    TG_PK_GROUND_CACHE = {}
    return { pos = pos, psi = psi, F = F, L = tg_tp_v(-F.y, F.x, 0), sg = sg, ground = ground,
             plans = {}, props = {}, ctx = { world = (TG_WORLD_OBSTACLE_AVOIDANCE ~= false) },
             state = { P = tg_tp_v(sg.x, sg.y, ground - TG_PK_ENTRY_SINK), psi = psi } }
end
function tg_ar_add(B, key, pitch, opts)
    local pl = tg_pk_straight(B.state, key, pitch or 0.0)
    if opts and opts.check and not tg_hy_fits(pl, B.plans, B.ctx, opts) then return nil end
    table.insert(B.plans, pl); B.state = pl.next
    return pl
end
-- drive-up ramp from the ground to `height` above it
function tg_ar_climb(B, height)
    local rise = 53.0 * math.sin(math.rad(TG_PK_RAMP_PITCH))
    local guard = 0
    while B.state.P.z + rise * 0.5 < B.ground + height and guard < 12 do
        guard = guard + 1
        tg_ar_add(B, "m", TG_PK_RAMP_PITCH)
    end
    B.start_gate = { P = B.plans[1].entry, D = B.F, r = 16.0 }
    B.drive_spot = tg_tp_sub(B.sg, tg_tp_mul(B.F, 28.0)); B.drive_spot.z = B.ground + 1.0
end
function tg_ar_descend(B)
    local guard = 0
    while guard < 14 do
        guard = guard + 1
        local pl = tg_ar_add(B, "m", -TG_PK_RAMP_PITCH)
        local g = tg_pk_ground(pl.next.P.x, pl.next.P.y, pl.next.P.z - 60.0) or B.ground
        if B.state.P.z <= g then break end
    end
end
-- floating arena of rail-less tiles (106 x 23.4 each): cols across, rows along
function tg_ar_arena(B, cols, rows)
    local P0, psi = B.state.P, B.state.psi
    local F = tg_tp_v(math.cos(psi), math.sin(psi), 0)
    local L = tg_tp_v(-F.y, F.x, 0)
    local tiles = {}
    for r = 0, rows - 1 do
        for c = 1, cols do
            local off = (c - (cols + 1) / 2) * 23.4
            local st = { P = tg_tp_add(tg_tp_add(P0, tg_tp_mul(F, r * 106.0)), tg_tp_mul(L, off)), psi = psi }
            local pl = tg_pk_straight(st, "nlm", 0.0)
            pl.arena = true
            table.insert(B.plans, pl); table.insert(tiles, pl)
        end
    end
    local A = { tiles = tiles, F = F, L = L, psi = psi, level = P0.z, half_len = rows * 53.0, half_wid = cols * 11.7,
                center = tg_tp_add(P0, tg_tp_mul(F, rows * 53.0)) }
    function A.at(along, lat, up) return tg_tp_add(tg_tp_add(tg_tp_add(A.center, tg_tp_mul(A.F, along)), tg_tp_mul(A.L, lat)), tg_tp_v(0, 0, up or 0)) end
    function A.local_of(p)
        local d = tg_tp_sub(p, A.center)
        return tg_tp_dot(d, A.F), tg_tp_dot(d, A.L), p.z - A.level
    end
    function A.inside(p, margin)
        local a, l, z = A.local_of(p)
        return math.abs(a) <= A.half_len + (margin or 0) and math.abs(l) <= A.half_wid + (margin or 0) and z > -4
    end
    B.arena = A
    return A
end
function tg_ar_prop(B, model, pos, psi, extra) return tg_hy_prop(B.props, model, pos, psi, extra) end

-- spawn everything; records plan.handle / prop.handle
function tg_ar_spawn(B, label, colour)
    clear_race_track("arcade")
    -- TrackMatic: never exceed the Safe Entity Spawn hard max (props go first)
    local cap = tg_rs_hardmax()
    while #B.plans + #B.props > cap and #B.props > 0 do table.remove(B.props) end
    while #B.plans > cap do table.remove(B.plans) end
    local all = {}
    for _, p in ipairs(B.plans) do table.insert(all, p) end
    for _, p in ipairs(B.props) do table.insert(all, p) end
    local plabel = "Minigame"
    tg_rs_preload(plabel, all)
    local token = tg_generation_start("arcade") or nil
    local n = 0
    for i, plan in ipairs(B.plans) do
        if tg_generation_should_stop(token, "arcade") then tg_rs_progress_fail("Stopped"); return false end
        if colour then plan.tint = tg_pk_colour_for(colour, 1, i, plan.island or (plan.arena and 3) or 0) end
        if tg_rs_spawn_progress(plabel, i, #all, "Spawning arena") then return false end
        util.yield(TG_TUBEP_DELAY_MS or 60)
        local obj = tg_tco_spawn_animated(plan, label .. "_" .. tostring(i))
        if obj then plan.handle = obj; n = n + 1 end
    end
    for i, p in ipairs(B.props) do
        if tg_rs_spawn_progress(plabel, #B.plans + i, #all, "Spawning props") then return false end
        util.yield(30)
        tg_hy_spawn_prop(p, label .. "_prop_" .. tostring(i))
        if p.handle then n = n + 1 end
    end
    tg_tn_settle_all(label)
    if n > 0 then tg_rs_progress_done(string.format("%d / %d objects - GO!", n, #all)) else tg_rs_progress_fail("Nothing spawned") end
    return n > 0
end
-- spawn one physics prop mid-game
function tg_ar_spawn_dynamic(model, pos, psi)
    local p = { prop = true, model = model, origin = pos, pitch = 0, rollY = 0, yaw = tg_normalize_heading(math.deg(psi or 0)), dynamic = true }
    tg_hy_spawn_prop(p, "arcade_dyn")
    return p.handle
end

-- course from one of the existing planners (parkour style / hybrid mix / tube race)
function tg_ar_course(kind, arg)
    local plans, meta
    for attempt = 1, 25 do
        if tg_rs_check_cancel() then return nil end
        TG_WORLD_OBSTACLE_PROBE_CACHE = {}
        TG_HYS.rand_props, TG_HYS.pins_used = nil, nil
        if kind == "parkour" then plans, meta = tg_pk_plan_course(arg.style, arg.diff or "normal")
        else
            local saved = { mix = TG_HY_SEL.mix, length = TG_HY_SEL.length, difficulty = TG_HY_SEL.difficulty }
            TG_HY_SEL.mix, TG_HY_SEL.length, TG_HY_SEL.difficulty = arg.mix or "balanced", arg.length or "short", arg.diff or "normal"
            plans, meta = tg_hy_plan_course()
            TG_HY_SEL.mix, TG_HY_SEL.length, TG_HY_SEL.difficulty = saved.mix, saved.length, saved.difficulty
        end
        if plans then break end
        if attempt % 3 == 0 then util.yield(0) end
    end
    if not plans then return nil end
    local B = { plans = plans, props = meta.props or {}, meta = meta, start_gate = meta.start, finish_gate = meta.finish,
                drive_spot = meta.drive_spot, checkpoints = meta.checkpoints }
    return B
end

-- ---------- game engine ----------
TG_AR_GAMES = {}
TG_AR_ORDER = {}
function tg_ar_def(def) TG_AR_GAMES[def.id] = def; table.insert(TG_AR_ORDER, def.id) end

function tg_ar_finish(G, value, text)
    if G.done then return end
    G.done = true
    local def = G.def
    local best = TG_AR.best[def.id]
    local better = (best == nil) or (def.lower_better and value < best) or (not def.lower_better and value > best)
    if value ~= nil and better then TG_AR.best[def.id] = value end
    local bs = TG_AR.best[def.id]
    local fmt = def.fmt or function(v) return tostring(v) end
    local msg = string.format("%s - %s  %s", def.name, text or fmt(value), better and value ~= nil and "NEW BEST!" or ("(best " .. (bs and fmt(bs) or "-") .. ")"))
    tg_ar_toast(msg, 8000)
    tg_log("[ARCADE][RESULT] " .. msg)
    G.active = false
    TG_PK_RESPAWN = G.saved_respawn
end

function tg_ar_tick()
    local G = TG_AR.active
    if not G or not G.active then util.yield(400); return end
    local now = tg_ar_now()
    local P = tg_ar_player()
    if not P.pos then util.yield(150); return end
    -- game cleared from under us?
    if G.anchor then
        local alive = false
        for _, o in ipairs(objects) do if o == G.anchor then alive = true; break end end
        if not alive and not G.allow_no_anchor then G.active = false; tg_log("[ARCADE] stopped: course cleared"); return end
    end
    if G.limit and G.t0 and (now - G.t0) > G.limit * 1000 then
        if G.def.timeout then G.def.timeout(G, P, now) else tg_ar_finish(G, G.score or 0) end
        return
    end
    G.def.tick(G, P, now)
    -- v2.0.4: other players who fall off an arena platform go back onto it
    if G.A and G.A.level and G.spot and tg_rs_others_arena_tick then tg_rs_others_arena_tick(G.A.level, G.spot) end
    util.yield(0)
end

function tg_arcade_start(id)
    id = id or TG_AR.sel
    local def = TG_AR_GAMES[id]
    if not def then return end
    if TG_AR.active then TG_AR.active.active = false end
    tg_rs_build_start("Minigame")
    tg_toast("Arcade: building " .. def.name .. "...", 2500)
    local G = { def = def, cross = {}, score = 0, active = false, saved_respawn = TG_PK_RESPAWN }
    def.build(G)
    if tg_rs_check_cancel() then TG_PK_RESPAWN = G.saved_respawn; return false end
    if not G.built then
        tg_toast("Arcade: couldn't build " .. def.name .. " here. Face open space and try again.", 5000)
        tg_log("[ARCADE] build failed")
        TG_PK_RESPAWN = G.saved_respawn
        return false
    end
    if TG_TUBEC_TIMER then TG_TUBEC_TIMER.active = false end     -- the game keeps its own clock
    G.anchor = G.anchor or objects[1]
    G.active = true
    TG_AR.active = G
    if not TG_AR_TICK_REGISTERED then
        TG_AR_TICK_REGISTERED = true
        util.create_tick_handler(function() tg_ar_tick(); return true end)
    end
    tg_ar_toast(def.name .. ": " .. def.how, 7000)
    return true
end
if tg_tn_wrap then tg_arcade_start = tg_tn_wrap("tg_arcade_start", tg_arcade_start) end

function tg_arcade_stop()
    local G = TG_AR.active
    if G and G.active then G.active = false; TG_PK_RESPAWN = G.saved_respawn; tg_toast("Arcade: " .. G.def.name .. " stopped.", 2500) end
end
function tg_arcade_goto_start()
    local G = TG_AR.active
    if not G or not G.spot then tg_toast("Start an arcade game first.", 2500); return end
    tg_ar_put(G.spot.P, G.spot.psi, 0.0)
    G.cross = {}
end

-- ---------- reusable game patterns ----------
-- RACE: start gate -> finish gate. opts: hardcore (no respawn, fall = out), gates (must pass), bonus(G) -> seconds off
function tg_ar_race_setup(G, B, opts)
    G.built = tg_ar_spawn(B, "arcade", opts.colour or "island")
    if not G.built then return end
    G.start, G.finish, G.cps = B.start_gate, B.finish_gate, B.checkpoints or {}
    G.spot = { P = B.drive_spot or B.start_gate.P, psi = math.atan(B.start_gate.D.y, B.start_gate.D.x) }
    G.opts = opts
    G.gates = {}
    for _, p in ipairs(B.props or {}) do
        if p.model == "ar_prop_ar_neon_gate_04a" then table.insert(G.gates, { P = p.origin, hit = false }) end
        if p.model == "stt_prop_stunt_bowling_pin" and p.handle then G.pins = G.pins or {}; table.insert(G.pins, { h = p.handle, o = p.origin }) end
    end
    if opts.hardcore then TG_PK_RESPAWN = false else TG_PK_RESPAWN = true end
    tg_pk_arm({ checkpoints = G.cps }, objects[1])
    G.limit = opts.limit or 600
    G.t0 = tg_ar_now()
end
function tg_ar_pins_down(G)
    local n = 0
    for _, pin in ipairs(G.pins or {}) do
        local p = tg_ar_epos(pin.h)
        local r = tg_ar_erot(pin.h)
        if not p then n = n + 1
        elseif tg_tp_dist(p, pin.o) > 1.6 or (r and (math.abs(r.x) > 35 or math.abs(r.y) > 35)) then n = n + 1 end
    end
    return n
end
function tg_ar_race_tick(G, P, now)
    local o = G.opts
    if not G.t_start then
        if tg_ar_cross(G, "start", G.start, P.pos) then G.t_start = now; tg_ar_toast("GO!", 1500) end
        return
    end
    for _, g in ipairs(G.gates) do
        if not g.hit and tg_ar_near(P.pos, g.P, 14.0, 10.0) then g.hit = true; G.gates_hit = (G.gates_hit or 0) + 1; tg_ar_toast(string.format("Gate %d/%d", G.gates_hit, #G.gates), 1200) end
    end
    if o.airtime then
        if P.air then G.air_ms = (G.air_ms or 0) + (now - (G.last_t or now)) end
        G.last_t = now
    end
    local st = TG_PK_STATE
    if o.hardcore and st and (st.reached or 0) >= 1 then
        local cur = st.checkpoints[st.reached]
        if P.pos.z < cur.P.z - 18.0 then
            local islands = math.max(0, (st.reached or 1) - 1)
            G.score = islands
            tg_ar_finish(G, islands, string.format("You fell after %d island(s)", islands))
            return
        end
    end
    if G.finish and tg_ar_cross(G, "finish", G.finish, P.pos) then
        local t = now - G.t_start
        if o.airtime then
            local s = (G.air_ms or 0) / 1000.0
            tg_ar_finish(G, s, string.format("%.1f s of air time (run %s)", s, tg_ar_fmt_time(t)))
        elseif o.hardcore then
            local islands = #G.cps - 1
            tg_ar_finish(G, islands + 100, string.format("Made it! All %d islands in %s", islands, tg_ar_fmt_time(t)))
        else
            local missed = #G.gates - (G.gates_hit or 0)
            local pen = (o.gates and missed or 0) * 10000
            local bonus = o.pins and (tg_ar_pins_down(G) * 1000) or 0
            local falls = (TG_PK_STATE and TG_PK_STATE.falls) or 0
            local total = math.max(0, t + pen - bonus)
            local extra = (o.gates and missed > 0) and string.format(" (+%ds missed gates)", missed * 10) or ""
            if o.pins then extra = extra .. string.format(" (-%ds for %d pins)", bonus / 1000, bonus / 1000) end
            tg_ar_finish(G, total, string.format("Time %s%s, %d fall(s)", tg_ar_fmt_time(total), extra, falls))
        end
    end
end
function tg_ar_race_game(id, name, how, layout, opts)
    tg_ar_def({ id = id, name = name, how = how, lower_better = not (opts.airtime or opts.hardcore),
        fmt = (opts.airtime and function(v) return string.format("%.1fs air", v) end)
           or (opts.hardcore and function(v) return (v >= 100) and ("finished (" .. tostring(v - 100) .. " islands)") or (tostring(v) .. " islands") end)
           or function(v) return tg_ar_fmt_time(v) end,
        build = function(G)
            local B = layout(G)
            if not B then return end
            tg_ar_race_setup(G, B, opts)
        end,
        tick = tg_ar_race_tick })
end

-- JUMP: runway -> stunt ramp -> landing field; measure each attempt
function tg_ar_jump_layout(G, ramp_key, land_keys, gap, drop, runway)
    local B = tg_ar_frame()
    tg_ar_climb(B, 34.0)
    for _, k in ipairs(runway or { "lm" }) do tg_ar_add(B, k, 0.0) end
    local boost_tile = B.plans[#B.plans]
    tg_ar_prop(B, "stt_prop_track_speedup_t1", tg_hy_on_tile(boost_tile, 30.0, 0, -0.11), boost_tile.next.psi)
    local ramp_tile = tg_ar_add(B, "m", 0.0)
    local R = TG_HY_RAMPS[ramp_key]
    tg_ar_prop(B, R.model, tg_hy_on_tile(ramp_tile, 53.0 - R.back, 0, R.up), ramp_tile.next.psi)
    local lip = B.state
    G.lip = { P = tg_tp_v(lip.P.x, lip.P.y, lip.P.z + R.lip), psi = lip.psi }
    G.lip_ground = lip.P
    local s = { P = tg_tp_v(lip.P.x + math.cos(lip.psi) * gap, lip.P.y + math.sin(lip.psi) * gap, lip.P.z - drop), psi = lip.psi }
    G.land_tiles = {}
    for _, k in ipairs(land_keys) do
        local pl = tg_pk_straight(s, k, 0.0)
        table.insert(B.plans, pl); table.insert(G.land_tiles, pl); s = pl.next
    end
    G.land_level = lip.P.z - drop
    G.runway_start = { P = tg_tp_add(lip.P, tg_tp_v(0, 0, 2.5)), psi = lip.psi }
    -- the runway start = first flat tile after the climb
    for _, pl in ipairs(B.plans) do
        if math.abs(pl.pitch or 0) < 0.1 and math.abs(pl.rollY or 0) < 0.1 then G.runway_start = { P = tg_hy_on_tile(pl, 6.0, 0, 2.5), psi = pl.next.psi }; break end
    end
    B.start_gate = B.start_gate
    return B
end
function tg_ar_jump_game(id, name, how, ramp_key, land_keys, gap, drop, measure, runway)
    tg_ar_def({ id = id, name = name, how = how, lower_better = (measure == "precision"),
        fmt = (measure == "height" and function(v) return string.format("%.1f m high", v) end)
           or (measure == "precision" and function(v) return string.format("%.1f m from the bullseye", v) end)
           or function(v) return string.format("%.1f m", v) end,
        build = function(G)
            local B = tg_ar_jump_layout(G, ramp_key, land_keys, gap, drop, runway)
            G.built = tg_ar_spawn(B, "arcade", "rainbow")
            if not G.built then return end
            G.spot = G.runway_start
            G.limit, G.t0, G.attempts, G.best_run = 120, tg_ar_now(), 0, nil
            G.target = (measure == "precision") and G.land_tiles[1] or nil
            tg_ar_put(G.spot.P, G.spot.psi, 0.0)
        end,
        timeout = function(G) tg_ar_finish(G, G.best_run, G.best_run and nil or "no valid jump") end,
        tick = function(G, P, now)
            local lip = G.lip
            local d_lip = tg_tp_dist(tg_tp_v(P.pos.x, P.pos.y, 0), tg_tp_v(G.lip_ground.x, G.lip_ground.y, 0))
            if not G.flying then
                -- launched: in the air within 25 m of the lip, moving forward
                if P.air and d_lip < 25.0 then G.flying = { t = now, maxz = P.pos.z } end
                return
            end
            G.flying.maxz = math.max(G.flying.maxz, P.pos.z)
            local fell = P.pos.z < G.land_level - 15.0
            if (not P.air and (now - G.flying.t) > 400) or fell then
                local f = G.flying
                G.flying = nil
                G.attempts = G.attempts + 1
                local value
                if fell then value = nil
                elseif measure == "height" then value = f.maxz - G.lip.P.z
                elseif measure == "precision" then
                    local c = tg_hy_on_tile(G.target, TG_PK_PIECES[G.target.key].len * 0.5, 0, 0)
                    value = tg_tp_dist(tg_tp_v(P.pos.x, P.pos.y, 0), tg_tp_v(c.x, c.y, 0))
                    if math.abs(P.pos.z - G.land_level) > 6 then value = nil end
                else value = d_lip end
                if value then
                    local better = (G.best_run == nil) or (measure == "precision" and value < G.best_run) or (measure ~= "precision" and value > G.best_run)
                    if better then G.best_run = value end
                    tg_ar_toast(string.format("Attempt %d: %s%s", G.attempts, G.def.fmt(value), better and "  (best this round)" or ""), 3000)
                else
                    tg_ar_toast(string.format("Attempt %d: no good - missed the landing", G.attempts), 2500)
                end
                G.reset_at = now + 2500
            end
            if G.reset_at and now > G.reset_at then end
        end })
    -- reset to the runway after each attempt (separate tiny wrapper so the tick above stays simple)
    local def = TG_AR_GAMES[id]
    local inner = def.tick
    def.tick = function(G, P, now)
        if G.reset_at and now > G.reset_at then G.reset_at = nil; G.flying = nil; tg_ar_put(G.spot.P, G.spot.psi, 0.0); return end
        inner(G, P, now)
    end
end

-- ARENA games share a floating platform
function tg_ar_arena_layout(cols, rows, height)
    local B = tg_ar_frame()
    tg_ar_climb(B, height or 30.0)
    tg_ar_add(B, "m", 0.0)
    local A = tg_ar_arena(B, cols, rows)
    return B, A
end
function tg_ar_arena_common(G, B, A, limit)
    G.built = tg_ar_spawn(B, "arcade", "single")
    if not G.built then return end
    G.A = A
    G.spot = { P = A.at(-A.half_len + 15.0, 0, 2.5), psi = A.psi }
    G.limit, G.t0 = limit, tg_ar_now()
    for _, pl in ipairs(B.plans) do if pl.arena then G.anchor = pl.handle; break end end
    tg_ar_put(G.spot.P, G.spot.psi, 0.0)
end
function tg_ar_arena_fall(G, P)
    if P.pos.z < G.A.level - 12.0 then
        G.falls = (G.falls or 0) + 1
        tg_ar_put(G.spot.P, G.spot.psi, 0.0)
        tg_ar_toast("Fell off! Back on the platform. Falls: " .. tostring(G.falls), 1800)
        return true
    end
end
function tg_ar_balls(G, list, model, count, spread)
    for i = 1, count do
        local h = tg_ar_spawn_dynamic(model, G.A.at(tg_pk_rand(-spread, spread), tg_pk_rand(-G.A.half_wid + 8, G.A.half_wid - 8), 8.0), G.A.psi)
        if h then table.insert(list, h) end
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- the 30 games
-- ═══════════════════════════════════════════════════════════════════════════════════
-- 1-4, 21, 25-28: courses
tg_ar_race_game("gaterush", "Gate Rush", "Drive up the ramp and pass every neon gate. +10s for each one you miss.",
    function() return tg_ar_course("parkour", { style = "gaterush" }) end, { gates = true })
tg_ar_race_game("hybriddash", "Hybrid Dash", "A short tube + island + prop course. Fastest time wins.",
    function() return tg_ar_course("hybrid", { mix = "balanced", length = "short" }) end, {})
tg_ar_race_game("hardcore", "Hardcore Hopper", "No respawns: fall once and it's over. How many islands can you clear?",
    function() return tg_ar_course("parkour", { style = "islands" }) end, { hardcore = true })
tg_ar_race_game("staircase", "Sky Staircase", "Jump UP every island with the big stunt ramps. Race to the top.",
    function() return tg_ar_course("parkour", { style = "staircase" }) end, {})
tg_ar_race_game("switchrace", "Switchback Descent", "Zig-zag down the sky against the clock.",
    function() return tg_ar_course("parkour", { style = "switch" }) end, {})
tg_ar_race_game("bowlrun", "Bowling Run", "Race the course and smash the pin rack at the end: every pin knocked takes 1s off.",
    function() return tg_ar_course("parkour", { style = "bowling" }) end, { pins = true })
tg_ar_race_game("endurance", "Island Endurance", "Sixteen islands, no respawns. Count how far you get.",
    function() return tg_ar_course("parkour", { style = "endurance" }) end, { hardcore = true })
tg_ar_race_game("airtime", "Air Time", "A ramp-packed course: rack up as many seconds in the air as you can before the finish.",
    function() return tg_ar_course("parkour", { style = "rampage" }) end, { airtime = true })
tg_ar_race_game("leapoffaith", "Leap of Faith", "Three or four of the biggest jumps in the game. Just finish.",
    function() return tg_ar_course("parkour", { style = "leap" }) end, {})
tg_ar_race_game("tubeheavy", "Tube Gauntlet", "A tube-heavy hybrid: loops, S-bends and humps between jumps.",
    function() return tg_ar_course("hybrid", { mix = "tubes", length = "short" }) end, {})

-- 11: drag race / 12: speed trap / 13: tyre slalom (straight runways)
tg_ar_def({ id = "dragrace", name = "Drag Race", how = "Floor it down the 640 m strip. Clock starts at the first boost pad.", lower_better = true,
    fmt = function(v) return tg_ar_fmt_time(v) end,
    build = function(G)
        local B = tg_ar_frame()
        tg_ar_climb(B, 24.0)
        local first = tg_ar_add(B, "lm", 0.0)
        tg_ar_prop(B, "stt_prop_race_gantry_01", tg_hy_on_tile(first, 10.0, 0, 0.05), first.next.psi)
        for _ = 1, 3 do tg_ar_add(B, "l", 0.0) end
        local last = tg_ar_add(B, "l", 0.0)
        tg_ar_prop(B, "stt_prop_race_gantry_01", tg_hy_on_tile(last, 140.0, 0, 0.05), last.next.psi)
        local finish = tg_hy_on_tile(last, 140.0, 0, 0)
        tg_ar_descend(B)
        G.built = tg_ar_spawn(B, "arcade", "rainbow")
        if not G.built then return end
        G.start = { P = tg_hy_on_tile(first, 10.0, 0, 0), D = tg_tp_v(math.cos(first.next.psi), math.sin(first.next.psi), 0), r = 14 }
        G.finish = { P = finish, D = G.start.D, r = 14 }
        G.spot = { P = tg_hy_on_tile(first, 2.0, 0, 2.5), psi = first.next.psi }
        G.limit, G.t0 = 300, tg_ar_now()
        tg_ar_put(G.spot.P, G.spot.psi, 0.0)
    end,
    tick = function(G, P, now)
        if not G.t_start then
            if tg_ar_cross(G, "s", G.start, P.pos) then G.t_start = now; tg_ar_toast("GO!", 1000) end
        elseif tg_ar_cross(G, "f", G.finish, P.pos) then
            tg_ar_finish(G, now - G.t_start, "Drag time " .. tg_ar_fmt_time(now - G.t_start) .. string.format(" (top %.0f km/h)", (G.top or 0) * 3.6))
        end
        G.top = math.max(G.top or 0, P.speed or 0)
    end })

tg_ar_def({ id = "speedtrap", name = "Speed Trap", how = "Boost pads all the way down the strip. Hit the neon gate as fast as you can - best of as many runs as you like in 90s.", lower_better = false,
    fmt = function(v) return string.format("%.0f km/h", v * 3.6) end,
    build = function(G)
        local B = tg_ar_frame()
        tg_ar_climb(B, 24.0)
        local tiles = {}
        for i = 1, 4 do
            local t = tg_ar_add(B, "lm", 0.0); table.insert(tiles, t)
            tg_ar_prop(B, "stt_prop_track_speedup_t1", tg_hy_on_tile(t, 30.0, 0, -0.11), t.next.psi)
            tg_ar_prop(B, "stt_prop_track_speedup_t1", tg_hy_on_tile(t, 75.0, 0, -0.11), t.next.psi)
        end
        tg_ar_prop(B, "ar_prop_ar_neon_gate_04a", tg_hy_on_tile(tiles[4], 95.0, 0, 2.62), tiles[4].next.psi + math.pi)
        tg_ar_add(B, "lm", 0.0)
        tg_ar_descend(B)
        G.built = tg_ar_spawn(B, "arcade", "rainbow")
        if not G.built then return end
        G.trap = { P = tg_hy_on_tile(tiles[4], 95.0, 0, 0), D = tg_tp_v(math.cos(tiles[4].next.psi), math.sin(tiles[4].next.psi), 0), r = 14 }
        G.spot = { P = tg_hy_on_tile(tiles[1], 3.0, 0, 2.5), psi = tiles[1].next.psi }
        G.limit, G.t0, G.best_run = 90, tg_ar_now(), nil
        tg_ar_put(G.spot.P, G.spot.psi, 0.0)
    end,
    timeout = function(G) tg_ar_finish(G, G.best_run or 0) end,
    tick = function(G, P, now)
        if tg_ar_cross(G, "trap", G.trap, P.pos) then
            local v = P.speed or 0
            if not G.best_run or v > G.best_run then G.best_run = v end
            tg_ar_toast(string.format("Trap: %.0f km/h (best %.0f). Back to the start...", v * 3.6, G.best_run * 3.6), 2500)
            G.reset_at = now + 2500
        end
        if G.reset_at and now > G.reset_at then G.reset_at = nil; G.cross = {}; tg_ar_put(G.spot.P, G.spot.psi, 0.0) end
    end })

tg_ar_def({ id = "slalom", name = "Tyre Slalom", how = "Weave through the tyre-wall slalom on three long decks. Fastest time.", lower_better = true,
    fmt = function(v) return tg_ar_fmt_time(v) end,
    build = function(G)
        local B = tg_ar_frame()
        tg_ar_climb(B, 22.0)
        local tiles = {}
        for i = 1, 3 do
            local t = tg_ar_add(B, "lm", 0.0); table.insert(tiles, t)
            for k = 1, 4 do tg_ar_prop(B, "stt_prop_tyre_wall_01", tg_hy_on_tile(t, 12.0 + k * 20.0, ((k + i) % 2 == 0 and 1 or -1) * 5.0, 0.08), t.next.psi + math.pi * 0.5) end
        end
        tg_ar_descend(B)
        G.built = tg_ar_spawn(B, "arcade", "island")
        if not G.built then return end
        local d = tg_tp_v(math.cos(tiles[1].next.psi), math.sin(tiles[1].next.psi), 0)
        G.start = { P = tiles[1].entry, D = d, r = 14 }
        G.finish = { P = tiles[3].next.P, D = tg_tp_v(math.cos(tiles[3].next.psi), math.sin(tiles[3].next.psi), 0), r = 14 }
        G.spot = { P = tg_tp_add(tg_tp_sub(tiles[1].entry, tg_tp_mul(d, 30.0)), tg_tp_v(0, 0, 2.5)), psi = tiles[1].next.psi }
        G.limit, G.t0 = 240, tg_ar_now()
        G.spot = { P = B.drive_spot, psi = B.psi }
    end,
    tick = function(G, P, now)
        if not G.t_start then
            if tg_ar_cross(G, "s", G.start, P.pos) then G.t_start = now; tg_ar_toast("GO!", 1000) end
        elseif tg_ar_cross(G, "f", G.finish, P.pos) then tg_ar_finish(G, now - G.t_start) end
        if G.t_start and P.pos.z < G.start.P.z - 15 then tg_ar_toast("Fell off - back to the start!", 2000); G.t_start = nil; G.cross = {}; tg_ar_put(G.spot.P, G.spot.psi, 0.0) end
    end })

-- 14-17: jumps
tg_ar_jump_game("longjump", "Long Jump", "Boost, big ramp, fly! Longest jump in 2 minutes wins. You're reset after every attempt.", "c", { "nl", "nl" }, 14.0, 10.0, "distance", { "lm", "lm" })
tg_ar_jump_game("highjump", "High Jump", "Launch off the biggest ramp: highest point above the lip wins.", "c", { "nl" }, 16.0, 8.0, "height", { "lm", "lm" })
tg_ar_jump_game("precision", "Precision Landing", "Land as close as you can to the middle of the small pad. Too fast and you overshoot.", "b", { "ns" }, 28.0, 8.0, "precision", { "lm" })
tg_ar_jump_game("smalljump", "Ramp Hop Distance", "Medium ramp, short runway: control is everything. Longest jump wins.", "a", { "nl" }, 10.0, 6.0, "distance", { "m" })

-- 18: triple jump
tg_ar_def({ id = "triplejump", name = "Triple Jump", how = "Three ramps in a row: small, medium, big. Total distance of all three jumps.", lower_better = false,
    fmt = function(v) return string.format("%.1f m total", v) end,
    build = function(G)
        local B = tg_ar_frame()
        tg_ar_climb(B, 40.0)
        tg_ar_add(B, "lm", 0.0)
        G.lips = {}
        local level_drop = 0
        for _, rk in ipairs({ "a", "b", "c" }) do
            local tile = tg_ar_add(B, "m", 0.0)
            tg_ar_prop(B, "stt_prop_track_speedup_t1", tg_hy_on_tile(tile, 8.0, 0, -0.11), tile.next.psi)
            local R = TG_HY_RAMPS[rk]
            tg_ar_prop(B, R.model, tg_hy_on_tile(tile, 53.0 - R.back, 0, R.up), tile.next.psi)
            table.insert(G.lips, B.state.P)
            local lip = B.state
            B.state = { P = tg_tp_v(lip.P.x + math.cos(lip.psi) * 16.0, lip.P.y + math.sin(lip.psi) * 16.0, lip.P.z - 6.0), psi = lip.psi }
            tg_ar_add(B, (rk == "c") and "l" or "lm", 0.0)
        end
        G.finish_P = B.state.P
        tg_ar_descend(B)
        G.built = tg_ar_spawn(B, "arcade", "rainbow")
        if not G.built then return end
        G.spot = { P = B.drive_spot, psi = B.psi }
        G.start = B.start_gate
        G.limit, G.t0, G.total, G.n = 300, tg_ar_now(), 0, 0
    end,
    tick = function(G, P, now)
        if not G.flying then
            for i, lp in ipairs(G.lips) do
                if not (G.used and G.used[i]) and P.air and tg_ar_near(P.pos, lp, 25.0, 25.0) then G.flying = { i = i, from = lp, t = now } end
            end
            if tg_ar_near(P.pos, G.finish_P, 30.0, 10.0) and G.n > 0 then tg_ar_finish(G, G.total) end
            return
        end
        if not P.air and (now - G.flying.t) > 400 then
            local d = tg_tp_dist(tg_tp_v(P.pos.x, P.pos.y, 0), tg_tp_v(G.flying.from.x, G.flying.from.y, 0))
            G.used = G.used or {}; G.used[G.flying.i] = true
            G.total, G.n = G.total + d, G.n + 1
            tg_ar_toast(string.format("Jump %d: %.1f m (total %.1f m)", G.n, d, G.total), 2500)
            G.flying = nil
            if G.n >= 3 then tg_ar_finish(G, G.total) end
        end
        if P.pos.z < G.lips[1].z - 60 then tg_ar_finish(G, G.total, string.format("Fell! %.1f m from %d jump(s)", G.total, G.n)) end
    end })

-- 19-25: arena games
tg_ar_def({ id = "soccer", name = "Sky Soccer", how = "Push the giant ball through the neon goal at the far end. Most goals in 2 minutes.", lower_better = false,
    fmt = function(v) return tostring(v) .. " goals" end,
    build = function(G)
        local B, A = tg_ar_arena_layout(3, 2)
        tg_ar_prop(B, "ar_prop_ar_neon_gate_04a", A.at(A.half_len - 3.0, 0, 2.62), A.psi + math.pi)
        tg_ar_arena_common(G, B, A, 120)
        if not G.built then return end
        G.balls = {}
        tg_ar_balls(G, G.balls, "stt_prop_stunt_soccer_lball", 1, 5)
    end,
    timeout = function(G) tg_ar_finish(G, G.score) end,
    tick = function(G, P, now)
        tg_ar_arena_fall(G, P)
        local h = G.balls[1]
        local bp = tg_ar_epos(h)
        if not bp then return end
        local a, l, z = G.A.local_of(bp)
        if a > G.A.half_len and math.abs(l) < 10.0 then
            G.score = G.score + 1
            tg_ar_toast("GOOOAL! " .. tostring(G.score), 2500)
            tg_ar_delete(h); G.balls = {}; tg_ar_balls(G, G.balls, "stt_prop_stunt_soccer_lball", 1, 3)
        elseif z < -10.0 then
            tg_ar_toast("Ball's gone over the side - new ball!", 1800)
            tg_ar_delete(h); G.balls = {}; tg_ar_balls(G, G.balls, "stt_prop_stunt_soccer_lball", 1, 3)
        end
    end })

tg_ar_def({ id = "ballblitz", name = "Ball Blitz", how = "Knock all six giant balls off the platform in 90 seconds.", lower_better = true,
    fmt = function(v) return tg_ar_fmt_time(v) end,
    build = function(G)
        local B, A = tg_ar_arena_layout(3, 2)
        tg_ar_arena_common(G, B, A, 90)
        if not G.built then return end
        G.balls = {}
        tg_ar_balls(G, G.balls, "stt_prop_stunt_soccer_ball", 3, 60)
        tg_ar_balls(G, G.balls, "stt_prop_stunt_soccer_lball", 3, 60)
    end,
    timeout = function(G)
        local off = 0
        for _, h in ipairs(G.balls) do local p = tg_ar_epos(h); if not p or p.z < G.A.level - 10 then off = off + 1 end end
        tg_ar_finish(G, 999999, string.format("Time's up: %d of %d balls knocked off", off, #G.balls))
    end,
    tick = function(G, P, now)
        tg_ar_arena_fall(G, P)
        local off = 0
        for _, h in ipairs(G.balls) do local p = tg_ar_epos(h); if not p or p.z < G.A.level - 10 then off = off + 1 end end
        if off ~= G.off then G.off = off; if off > 0 then tg_ar_toast(string.format("%d / %d off!", off, #G.balls), 1200) end end
        if off >= #G.balls and #G.balls > 0 then tg_ar_finish(G, now - G.t0, "All balls off in " .. tg_ar_fmt_time(now - G.t0)) end
    end })

tg_ar_def({ id = "herder", name = "Ball Herder", how = "Push all three balls into the tyre pen at the far end and keep them there.", lower_better = true,
    fmt = function(v) return tg_ar_fmt_time(v) end,
    build = function(G)
        local B, A = tg_ar_arena_layout(3, 2)
        -- pen: tyre walls around the last 30 m of the middle lane
        for _, a in ipairs({ A.half_len - 30, A.half_len - 15 }) do
            tg_ar_prop(B, "stt_prop_tyre_wall_01", A.at(a, 16.0, 0.08), A.psi)
            tg_ar_prop(B, "stt_prop_tyre_wall_01", A.at(a, -16.0, 0.08), A.psi)
        end
        tg_ar_prop(B, "ar_prop_ar_neon_gate_04a", A.at(A.half_len - 32.0, 0, 2.62), A.psi + math.pi)
        tg_ar_arena_common(G, B, A, 150)
        if not G.built then return end
        G.balls = {}
        tg_ar_balls(G, G.balls, "stt_prop_stunt_soccer_ball", 3, 40)
    end,
    timeout = function(G) tg_ar_finish(G, 999999, string.format("Time's up: %d of 3 in the pen", G.inpen or 0)) end,
    tick = function(G, P, now)
        tg_ar_arena_fall(G, P)
        local n = 0
        for i, h in ipairs(G.balls) do
            local p = tg_ar_epos(h)
            if p then
                local a, l, z = G.A.local_of(p)
                if a > G.A.half_len - 32 and math.abs(l) < 16 and z > -5 then n = n + 1 end
                if z < -12 then tg_ar_delete(h); G.balls[i] = tg_ar_spawn_dynamic("stt_prop_stunt_soccer_ball", G.A.at(0, 0, 8), G.A.psi) or h end
            end
        end
        if n ~= G.inpen then G.inpen = n; tg_ar_toast(string.format("%d / 3 in the pen", n), 1200) end
        if n >= 3 then tg_ar_finish(G, now - G.t0) end
    end })

tg_ar_def({ id = "pinhunter", name = "Pin Hunter", how = "Three pin racks on a floating platform. Knock down all 30 pins in 90 seconds.", lower_better = false,
    fmt = function(v) return tostring(v) .. " pins" end,
    build = function(G)
        local B, A = tg_ar_arena_layout(3, 2)
        local spots = { { 20, 0 }, { 75, -18 }, { 75, 18 } }
        local fake = {}
        for _, sp in ipairs(spots) do
            local tile = { entry = A.at(sp[1] - 50.0, sp[2], 0), next = { psi = A.psi } }
            tg_hy_add_pins(B.props, tile, 50.0)
        end
        tg_ar_arena_common(G, B, A, 90)
        if not G.built then return end
        G.pins = {}
        for _, p in ipairs(B.props) do if p.model == "stt_prop_stunt_bowling_pin" and p.handle then table.insert(G.pins, { h = p.handle, o = p.origin }) end end
    end,
    timeout = function(G) tg_ar_finish(G, tg_ar_pins_down(G)) end,
    tick = function(G, P, now)
        tg_ar_arena_fall(G, P)
        if (now - (G.last_count or 0)) > 500 then
            G.last_count = now
            local n = tg_ar_pins_down(G)
            if n ~= G.down then G.down = n; tg_ar_toast(string.format("%d / %d pins down", n, #G.pins), 1000) end
            if n >= #G.pins and #G.pins > 0 then tg_ar_finish(G, n, string.format("All %d pins in %s!", n, tg_ar_fmt_time(now - G.t0))) end
        end
    end })

tg_ar_def({ id = "checkpoints", name = "Checkpoint Hunt", how = "Five neon gates are scattered over a big floating platform. Drive through all of them, any order.", lower_better = true,
    fmt = function(v) return tg_ar_fmt_time(v) end,
    build = function(G)
        local B, A = tg_ar_arena_layout(3, 3)
        G.cps = {}
        for i = 1, 5 do
            local a, l = tg_pk_rand(-A.half_len + 25, A.half_len - 15), tg_pk_rand(-A.half_wid + 10, A.half_wid - 10)
            local yaw = A.psi + math.rad(math.random(0, 3) * 45)
            tg_ar_prop(B, "ar_prop_ar_neon_gate_04a", A.at(a, l, 2.62), yaw)
            table.insert(G.cps, { P = A.at(a, l, 0), hit = false })
        end
        tg_ar_arena_common(G, B, A, 120)
    end,
    timeout = function(G) local n = 0; for _, c in ipairs(G.cps) do if c.hit then n = n + 1 end end; tg_ar_finish(G, 999999, string.format("Time's up: %d of 5 gates", n)) end,
    tick = function(G, P, now)
        tg_ar_arena_fall(G, P)
        local n = 0
        for _, c in ipairs(G.cps) do
            if not c.hit and tg_ar_near(P.pos, c.P, 10.0, 8.0) then c.hit = true; tg_ar_toast("Gate!", 800) end
            if c.hit then n = n + 1 end
        end
        if n >= #G.cps then tg_ar_finish(G, now - G.t0) end
    end })

tg_ar_def({ id = "shrinking", name = "Shrinking Arena", how = "A 3x3 floating floor loses a tile every 5 seconds. Stay on as long as you can.", lower_better = false,
    fmt = function(v) return tg_ar_fmt_time(v) end,
    build = function(G)
        local B, A = tg_ar_arena_layout(3, 3)
        tg_ar_arena_common(G, B, A, 600)
        if not G.built then return end
        G.left = {}
        for _, t in ipairs(A.tiles) do if t.handle then table.insert(G.left, t.handle) end end
        G.allow_no_anchor = true
        G.next_drop = tg_ar_now() + 8000
        G.balls = {}
        tg_ar_balls(G, G.balls, "stt_prop_stunt_soccer_ball", 2, 60)
    end,
    tick = function(G, P, now)
        if P.pos.z < G.A.level - 12.0 then tg_ar_finish(G, now - G.t0, "Survived " .. tg_ar_fmt_time(now - G.t0)); return end
        if now > G.next_drop and #G.left > 0 then
            local i = math.random(#G.left)
            tg_ar_delete(G.left[i]); table.remove(G.left, i)
            G.next_drop = now + math.max(2500, 5000 - (9 - #G.left) * 300)
            tg_ar_toast(string.format("Tile gone! %d left", #G.left), 1000)
        end
    end })

tg_ar_def({ id = "kingofhill", name = "King of the Hill", how = "Stay on the small platform while giant balls rain down. Score = seconds on the platform in 90s.", lower_better = false,
    fmt = function(v) return string.format("%.1fs on top", v) end,
    build = function(G)
        local B, A = tg_ar_arena_layout(2, 1)
        tg_ar_arena_common(G, B, A, 90)
        if not G.built then return end
        G.balls, G.on_ms, G.next_ball = {}, 0, tg_ar_now() + 4000
    end,
    timeout = function(G) tg_ar_finish(G, G.on_ms / 1000.0) end,
    tick = function(G, P, now)
        if G.A.inside(P.pos, 1.0) then G.on_ms = G.on_ms + (now - (G.last_t or now)) end
        G.last_t = now
        tg_ar_arena_fall(G, P)
        if now > G.next_ball then
            G.next_ball = now + 3500
            local h = tg_ar_spawn_dynamic((math.random() < 0.5) and "stt_prop_stunt_soccer_ball" or "stt_prop_stunt_soccer_lball", G.A.at(tg_pk_rand(-40, 40), tg_pk_rand(-15, 15), 25.0), G.A.psi)
            if h then table.insert(G.balls, h) end
            while #G.balls > 5 do tg_ar_delete(table.remove(G.balls, 1)) end
        end
    end })

-- 26: crumbling bridge
tg_ar_def({ id = "crumble", name = "Crumbling Bridge", how = "Every bridge tile crumbles a second after you touch it. Don't stop, don't fall.", lower_better = true,
    fmt = function(v) return tg_ar_fmt_time(v) end,
    build = function(G)
        local B = tg_ar_frame()
        tg_ar_climb(B, 30.0)
        local entry = tg_ar_add(B, "m", 0.0)
        G.tiles = {}
        for i = 1, 26 do
            local pl
            if i % 7 == 0 then pl = tg_pk_bend(B.state, "b45", (math.random() < 0.5) and 1 or -1)
                if not tg_hy_fits(pl, B.plans, B.ctx) then pl = tg_pk_straight(B.state, "ns", 0.0) end
                table.insert(B.plans, pl); B.state = pl.next
            else pl = tg_ar_add(B, "ns", 0.0) end
            table.insert(G.tiles, pl)
        end
        local goal = tg_ar_add(B, "lm", 0.0)
        tg_ar_prop(B, "stt_prop_race_gantry_01", tg_hy_on_tile(goal, 30.0, 0, 0.05), goal.next.psi)
        G.built = tg_ar_spawn(B, "arcade", "rainbow")
        if not G.built then return end
        G.goal = { P = tg_hy_on_tile(goal, 30.0, 0, 0), D = tg_tp_v(math.cos(goal.next.psi), math.sin(goal.next.psi), 0), r = 14 }
        G.start = { P = entry.next.P, D = tg_tp_v(math.cos(entry.next.psi), math.sin(entry.next.psi), 0), r = 14 }
        G.level = entry.next.P.z
        G.spot = { P = B.drive_spot, psi = B.psi }
        G.limit, G.t0 = 300, tg_ar_now()
        G.anchor = goal.handle
    end,
    tick = function(G, P, now)
        if not G.t_start then
            if tg_ar_cross(G, "s", G.start, P.pos) then G.t_start = now; tg_ar_toast("GO! Keep moving!", 1500) end
            return
        end
        for _, t in ipairs(G.tiles) do
            if t.handle and not t.gone then
                local c = t.samples[math.floor(#t.samples / 2) + 1]
                if not t.touch and tg_ar_near(P.pos, c, 13.0, 6.0) then t.touch = now end
                if t.touch and now - t.touch > 1100 then tg_ar_delete(t.handle); t.gone = true end
            end
        end
        if P.pos.z < G.level - 15.0 then tg_ar_finish(G, 9999999, "The bridge got you!"); return end
        if tg_ar_cross(G, "g", G.goal, P.pos) then tg_ar_finish(G, now - G.t_start) end
    end })

-- 27: boulder dash
tg_ar_def({ id = "boulders", name = "Boulder Dash", how = "Drive up the long ramp while giant bowling balls roll down at you. Reach the top!", lower_better = true,
    fmt = function(v) return tg_ar_fmt_time(v) end,
    build = function(G)
        local B = tg_ar_frame()
        tg_ar_climb(B, 6.0)
        local first = tg_ar_add(B, "lm", 0.0)
        for _ = 1, 7 do tg_ar_add(B, "m", 7.0) end
        local top = tg_ar_add(B, "lm", 0.0)
        tg_ar_prop(B, "stt_prop_race_gantry_01", tg_hy_on_tile(top, 25.0, 0, 0.05), top.next.psi)
        G.built = tg_ar_spawn(B, "arcade", "single")
        if not G.built then return end
        G.top = top
        G.goal = { P = tg_hy_on_tile(top, 25.0, 0, 0), D = tg_tp_v(math.cos(top.next.psi), math.sin(top.next.psi), 0), r = 14 }
        G.start = { P = first.entry, D = tg_tp_v(math.cos(first.next.psi), math.sin(first.next.psi), 0), r = 14 }
        G.spot = { P = tg_hy_on_tile(first, 5.0, 0, 2.5), psi = first.next.psi }
        G.limit, G.t0, G.balls, G.next_ball = 240, tg_ar_now(), {}, tg_ar_now() + 3000
        tg_ar_put(G.spot.P, G.spot.psi, 0.0)
    end,
    tick = function(G, P, now)
        if not G.t_start and tg_ar_cross(G, "s", G.start, P.pos) then G.t_start = now; tg_ar_toast("GO!", 1000) end
        if now > G.next_ball then
            G.next_ball = now + 3200
            local h = tg_ar_spawn_dynamic("stt_prop_stunt_bowling_ball", tg_hy_on_tile(G.top, 70.0, tg_pk_rand(-6, 6), 5.0), G.top.next.psi)
            if h then table.insert(G.balls, h) end
            while #G.balls > 4 do tg_ar_delete(table.remove(G.balls, 1)) end
        end
        if P.pos.z < G.start.P.z - 25 then tg_ar_toast("Knocked off - back to the bottom!", 2000); G.cross = {}; G.t_start = nil; tg_ar_put(G.spot.P, G.spot.psi, 0.0) end
        if G.t_start and tg_ar_cross(G, "g", G.goal, P.pos) then tg_ar_finish(G, now - G.t_start) end
    end })

-- 28: endless runner
tg_ar_def({ id = "endless", name = "Endless Runner", how = "Islands keep appearing ahead and vanishing behind. How far can you go? One fall ends it.", lower_better = false,
    fmt = function(v) return tostring(v) .. " islands" end,
    build = function(G)
        local B = tg_ar_frame()
        tg_ar_climb(B, 40.0)
        local first = tg_ar_add(B, "lm", 0.0)
        G.built = tg_ar_spawn(B, "arcade", "island")
        if not G.built then return end
        G.live = {}
        for _, pl in ipairs(B.plans) do table.insert(G.live, pl) end
        G.state, G.level, G.islands, G.ctx = first.next, first.next.P.z, 0, B.ctx
        G.ground0 = B.ground
        G.spot = { P = B.drive_spot, psi = B.psi }
        G.limit, G.t0 = 1800, tg_ar_now()
        G.allow_no_anchor = true
        G.queue = 0
        for _ = 1, 3 do tg_ar_endless_next(G) end
    end,
    tick = function(G, P, now)
        -- which island are we on?
        for i = #G.live, 1, -1 do
            local pl = G.live[i]
            if pl.island and pl.island > G.islands and tg_ar_near(P.pos, pl.entry, 40.0, 8.0) then
                G.islands = pl.island
                tg_ar_toast("Island " .. tostring(G.islands), 800)
                tg_ar_endless_next(G)
                -- drop pieces far behind
                while #G.live > 22 do local old = table.remove(G.live, 1); if old.handle then tg_ar_delete(old.handle) end end
                break
            end
        end
        local lowest = G.level
        for _, pl in ipairs(G.live) do lowest = math.min(lowest, pl.entry.z) end
        if P.pos.z < lowest - 20.0 and G.islands > 0 then tg_ar_finish(G, G.islands) end
    end })
function tg_ar_endless_next(G)
    for attempt = 1, 8 do
        local s = G.state
        local tmp = {}
        local good = true
        local function add(pl) if not good then return end if not tg_hy_fits(pl, G.live, G.ctx, { skip = 2 }) then good = false return end table.insert(tmp, pl); s = pl.next end
        if math.random() < 0.3 then add(tg_pk_bend(s, "b45", (math.random() < 0.5) and 1 or -1)) end
        add(tg_pk_straight(s, "m", 0.0))
        local up = (G.level < (G.ground0 or G.level) + 22) and true or (math.random() < 0.15)
        local ramp = nil
        local lip_z
        if up or math.random() < 0.3 then
            ramp = TG_HY_RAMPS[up and "c" or "a"]
            add(tg_pk_straight(s, "m", 0.0))
            lip_z = s.P.z
        else
            add(tg_pk_straight(s, "m", 7.0))
            lip_z = s.P.z
        end
        if good then
            local gap = up and 11.0 or tg_pk_rand(12.0, 20.0)
            local lvl = up and (G.level + 6.0) or (G.level - tg_pk_rand(3.0, 6.0))
            local land = { P = tg_tp_v(s.P.x + math.cos(s.psi) * gap, s.P.y + math.sin(s.psi) * gap, lvl), psi = s.psi + math.rad(tg_pk_rand(-8, 8)) }
            local landing = tg_pk_straight(land, "lm", 0.0)
            if tg_hy_fits(landing, G.live, G.ctx, { skip = 0 }) then
                G.queue = G.queue + 1
                for _, pl in ipairs(tmp) do pl.island = G.queue - 1; local obj = tg_tco_spawn_animated(pl, "endless"); pl.handle = obj; table.insert(G.live, pl) end
                if ramp then
                    local tile = tmp[#tmp]
                    local p = { prop = true, model = ramp.model, origin = tg_hy_on_tile(tile, 53.0 - ramp.back, 0, ramp.up), pitch = 0, rollY = 0, yaw = tg_normalize_heading(math.deg(tile.next.psi)) }
                    tg_hy_spawn_prop(p, "endless_ramp")
                    table.insert(G.live, { handle = p.handle, entry = tile.entry, samples = {} })
                end
                landing.island = G.queue
                landing.tint = (G.queue % 15) + 1
                local obj = tg_tco_spawn_animated(landing, "endless")
                landing.handle = obj
                table.insert(G.live, landing)
                G.state, G.level = landing.next, lvl
                return true
            end
        end
    end
    return false
end

-- 29: mega strike / 30: stunt score attack
tg_ar_def({ id = "megastrike", name = "Mega Strike", how = "Boost off the biggest ramp and land in a ten-pin rack. Three throws: total pins.", lower_better = false,
    fmt = function(v) return tostring(v) .. " pins" end,
    build = function(G)
        local B = tg_ar_jump_layout(G, "b", { "nl" }, 12.0, 6.0, { "lm" })
        local land = G.land_tiles[1]
        G.rack_tile = land
        G.built = tg_ar_spawn(B, "arcade", "rainbow")
        if not G.built then return end
        G.spot = G.runway_start
        G.limit, G.t0, G.throw, G.total = 300, tg_ar_now(), 0, 0
        tg_ar_megastrike_rack(G)
        tg_ar_put(G.spot.P, G.spot.psi, 0.0)
    end,
    tick = function(G, P, now)
        if not G.rolling then
            if P.air and tg_ar_near(P.pos, G.lip_ground, 25.0, 25.0) then G.rolling = now end
            return
        end
        if now - G.rolling > 7000 then
            local n = tg_ar_pins_down(G)
            G.throw, G.total, G.rolling = G.throw + 1, G.total + n, nil
            tg_ar_toast(string.format("Throw %d: %d pins%s (total %d)", G.throw, n, n == 10 and " - STRIKE!" or "", G.total), 3000)
            if G.throw >= 3 then tg_ar_finish(G, G.total); return end
            for _, pin in ipairs(G.pins) do tg_ar_delete(pin.h) end
            tg_ar_megastrike_rack(G)
            tg_ar_put(G.spot.P, G.spot.psi, 0.0)
        end
    end })
function tg_ar_megastrike_rack(G)
    G.pins = {}
    local props = {}
    tg_hy_add_pins(props, G.rack_tile, 70.0)
    for _, p in ipairs(props) do tg_hy_spawn_prop(p, "strike_pin"); if p.handle then table.insert(G.pins, { h = p.handle, o = p.origin }) end end
end

tg_ar_def({ id = "scoreattack", name = "Stunt Score Attack", how = "Points for air time (10/s), neon gates (50), pins (20) and finishing (500). Falls cost 100. 5 minutes.", lower_better = false,
    fmt = function(v) return tostring(math.floor(v)) .. " pts" end,
    build = function(G)
        local saved = TG_HY_SEL.props.gate
        TG_HY_SEL.props.gate, TG_HY_SEL.props.pins = true, true
        local B = tg_ar_course("hybrid", { mix = "props", length = "medium" })
        TG_HY_SEL.props.gate = saved
        if not B then return end
        tg_ar_race_setup(G, B, { limit = 300 })
        G.pts = 0
    end,
    timeout = function(G) tg_ar_finish(G, tg_ar_score_points(G)) end,
    tick = function(G, P, now)
        if P.air and G.t_start then G.air_ms = (G.air_ms or 0) + (now - (G.last_t or now)) end
        G.last_t = now
        if not G.t_start then
            if tg_ar_cross(G, "start", G.start, P.pos) then G.t_start = now; tg_ar_toast("GO! Score as much as you can!", 1500) end
            return
        end
        for _, g in ipairs(G.gates) do
            if not g.hit and tg_ar_near(P.pos, g.P, 14.0, 10.0) then g.hit = true; tg_ar_toast("+50 gate", 900) end
        end
        if G.finish and tg_ar_cross(G, "finish", G.finish, P.pos) then G.finished = true; tg_ar_finish(G, tg_ar_score_points(G)) end
    end })
function tg_ar_score_points(G)
    local gates = 0
    for _, g in ipairs(G.gates or {}) do if g.hit then gates = gates + 1 end end
    local pins = tg_ar_pins_down(G)
    local falls = (TG_PK_STATE and TG_PK_STATE.falls) or 0
    return math.max(0, math.floor((G.air_ms or 0) / 100) + gates * 50 + pins * 20 + (G.finished and 500 or 0) - falls * 100)
end

-- ---------- UI ----------
function tg_arcade_select(delta)
    local idx = 1
    for i, id in ipairs(TG_AR_ORDER) do if id == TG_AR.sel then idx = i end end
    idx = ((idx - 1 + delta) % #TG_AR_ORDER) + 1
    TG_AR.sel = TG_AR_ORDER[idx]
    local d = TG_AR_GAMES[TG_AR.sel]
    tg_toast(string.format("Arcade %d/%d: %s - %s", idx, #TG_AR_ORDER, d.name, d.how), 4000)
end
function tg_arcade_ui_render_panel()
    ImGui.Separator()
    ImGui.TextColored(1.0, 0.85, 0.1, 1.0, "ARCADE - 30 CREATIVE MINIGAMES")
    local list = {}
    for i, id in ipairs(TG_AR_ORDER) do table.insert(list, { id, string.format("%d. %s", i, TG_AR_GAMES[id].name) }) end
    tg_ui_choice_row(nil, "argame", list, TG_AR.sel, function(v) TG_AR.sel = v end, 3, 200)
    local d = TG_AR_GAMES[TG_AR.sel]
    if d then
        ImGui.Text(d.name .. ": " .. d.how)
        local b = TG_AR.best[d.id]
        ImGui.Text("Your best this session: " .. (b and d.fmt(b) or "-"))
    end
    if tg_ui_button then
        tg_ui_button("START GAME", 200, true, function() tg_arcade_start(TG_AR.sel) end)
        tg_ui_same_line()
        tg_ui_button("Back To Start", 160, false, function() tg_arcade_goto_start() end)
        tg_ui_same_line()
        tg_ui_button("Stop Game", 140, false, function() tg_arcade_stop() end)
    end
    tg_rs_tp_ui()
    local G = TG_AR.active
    if G then
        local secs = G.t0 and ((tg_ar_now() - G.t0) / 1000.0) or 0
        ImGui.Text(string.format("%s %s  |  %.0fs%s  |  %s", G.def.name, G.active and "LIVE" or "finished", secs, G.limit and ("/" .. tostring(G.limit) .. "s") or "", tostring(G.status or "")))
    end
end
-- ═══════════════════════════════════════════════════════════════════════════════════
-- trackmatic v2.0.4: bring everyone to the course + respawn everyone who falls off
-- Uses Cherax's own per-player "Teleport To Me" / "Send To My Waypoint" features
-- (the method proven in the Minigames / WarGames script), one player at a time.
-- ═══════════════════════════════════════════════════════════════════════════════════
-- v2.2.0: off by default on every tab (turn it on in any tab's bring players row)
TG_RS_RESPAWN_OTHERS = false -- default OFF; opt in explicitly using the UI
TG_RS_TP_ABOVE = TG_RS_TP_ABOVE or 18.0                    -- "above me" height
TG_RS_TP_FEATURES = {
    to_me = { "Teleport To Me", "Teleport to Me" },
    waypoint = { "Send To My Waypoint", "Send to My Waypoint" },
    all_to_me = { "Teleport All To Me", "Teleport All to Me", "Remote Teleport: Teleport All To Me" },
    all_waypoint = { "Send All To My Waypoint", "Send All to My Waypoint", "Teleport All To My Waypoint", "Remote Teleport: Send All To My Waypoint" },
}

function tg_rs_me() return tg_tn_int(TG_TN_H.PLAYER_ID) end
function tg_rs_other_players()
    local me, list = tg_rs_me(), {}
    for pid = 0, 31 do
        if pid ~= me and tg_tn_bool(TG_TN_H.PLAYER_ACTIVE, pid) then table.insert(list, pid) end
    end
    return list
end
function tg_rs_player_ped(pid) return tg_tn_int(0x50FAC3A3E030A6E1, pid) end            -- GET_PLAYER_PED_SCRIPT_INDEX
function tg_rs_player_pos(pid)
    local ped = tg_rs_player_ped(pid)
    if not ped or ped == 0 then return nil, 0 end
    local v = tg_tn_v3(0x3FEF770D40960D5A, ped, false)                                     -- GET_ENTITY_COORDS
    if not v then return nil, ped end
    return tg_tp_v(v.x, v.y, v.z), ped
end
function tg_rs_player_name(pid)
    return Players.GetName(pid) or ("player " .. tostring(pid))
end

-- trigger a Cherax player feature (pid) or a session-wide one (pid = nil)
function tg_rs_trigger_feature(names, pid)
    for _, name in ipairs(names) do
        local f
        if pid ~= nil then f = FeatureMgr.GetFeatureByName(name, pid) else f = FeatureMgr.GetFeatureByName(name) end
        if f then
            f:TriggerCallback()
            return true, name
        end
    end
    return false, "not found"
end

-- my entity (vehicle if I'm in one) + where it is
function tg_rs_my_anchor()
    local e = tg_pk_vehicle_or_ped() or 0
    if not e or e == 0 then return nil end
    local v = tg_tn_v3(0x3FEF770D40960D5A, e, false)
    if not v then return nil end
    return { e = e, x = v.x, y = v.y, z = v.z, h = tg_tn_float(0xE83D4F9BA2A38914, e) or 0.0 }   -- GET_ENTITY_HEADING
end
function tg_rs_move_anchor(a, x, y, z)
    tg_tn_void(0x428CA6DBD1094446, a.e, true)                                              -- FREEZE_ENTITY_POSITION
    tg_tn_void(0x239A3351AC1DA385, a.e, x + 0.0, y + 0.0, z + 0.0, false, false, false)     -- SET_ENTITY_COORDS_NO_OFFSET
end
function tg_rs_restore_anchor(a)
    tg_tn_void(0x239A3351AC1DA385, a.e, a.x + 0.0, a.y + 0.0, a.z + 0.0, false, false, false)
    tg_tn_void(0x8E2530AA8ADA980E, a.e, (a.h or 0.0) + 0.0)                                 -- SET_ENTITY_HEADING
    tg_tn_void(0x1C99BB7B6E96D16F, a.e, 0.0, 0.0, 0.0)                                     -- SET_ENTITY_VELOCITY
    tg_tn_void(0x428CA6DBD1094446, a.e, false)
end

-- bring every other player to points around `centre` (ring so nobody stacks), then put me back
function tg_rs_tp_all_to(centre, label)
    local players = tg_rs_other_players()
    if #players == 0 then tg_toast("TrackMatic: nobody else in the session.", 3000); return end
    local a = tg_rs_my_anchor()
    if not a then tg_toast("TrackMatic: couldn't read your position.", 3000); return end
    local ok_n, fail_n = 0, 0
    for i, pid in ipairs(players) do
        local ang = (i - 1) * (2.0 * math.pi / math.max(6, #players))
        local r = (#players > 1) and 9.0 or 0.0
        tg_rs_move_anchor(a, centre.x + math.cos(ang) * r, centre.y + math.sin(ang) * r, centre.z)
        util.yield(250)
        local ok = tg_rs_trigger_feature(TG_RS_TP_FEATURES.to_me, pid)
        if ok then ok_n = ok_n + 1 else fail_n = fail_n + 1 end
        util.yield(300)
    end
    util.yield(650)
    tg_rs_restore_anchor(a)
    if ok_n == 0 and fail_n > 0 then
        -- per-player feature missing: try Cherax's session-wide one
        if tg_rs_trigger_feature(TG_RS_TP_FEATURES.all_to_me, nil) then ok_n = #players end
    end
    tg_toast(string.format("TrackMatic: sent %d player(s) %s%s", ok_n, label or "", fail_n > 0 and string.format(" (%d failed)", fail_n) or ""), 5000)
end

function tg_rs_tp_all_above_me()
    local a = tg_rs_my_anchor()
    if not a then tg_toast("TrackMatic: couldn't read your position.", 3000); return end
    tg_rs_tp_all_to({ x = a.x, y = a.y, z = a.z + (TG_RS_TP_ABOVE or 18.0) }, "above you")
end
function tg_rs_tp_all_waypoint()
    local players = tg_rs_other_players()
    if #players == 0 then tg_toast("TrackMatic: nobody else in the session.", 3000); return end
    local ok_n = 0
    for _, pid in ipairs(players) do
        if tg_rs_trigger_feature(TG_RS_TP_FEATURES.waypoint, pid) then ok_n = ok_n + 1 end
        util.yield(225)
    end
    if ok_n == 0 and tg_rs_trigger_feature(TG_RS_TP_FEATURES.all_waypoint, nil) then ok_n = #players end
    tg_toast(string.format("TrackMatic: sent %d player(s) to your waypoint (set one on the map first).", ok_n), 5000)
end
function tg_rs_tp_all_start()
    local t = TG_TUBEC_TIMER
    if not t or not (t.drive_spot or t.P) then tg_toast("Build a course first.", 2500); return end
    local s = t.drive_spot or t.P
    tg_rs_tp_all_to({ x = s.x, y = s.y, z = s.z + 2.0 }, "to the course start")
end

-- ---------- respawn other players who fall off ----------
-- One player at a time: try to take control of their car and move it (no effect on you);
-- if the game won't give control, use the proven per-player "Teleport To Me" with you as the anchor
-- for about a second.
TG_RS_OTHERS = TG_RS_OTHERS or { list = {}, last_scan = 0 }
function tg_rs_respawn_player(pid, P, psi)
    local ped = tg_rs_player_ped(pid)
    if not ped or ped == 0 then return false end
    local heading = tg_normalize_heading(math.deg(psi or 0.0) - 90.0)
    -- 1) direct: their vehicle
    if tg_tn_bool(0x997ABD671D25CA0B, ped, false) then                                      -- IS_PED_IN_ANY_VEHICLE
        local veh = tg_tn_int(0x9A9112A0FE9A4713, ped, false)                                -- GET_VEHICLE_PED_IS_IN
        if veh and veh ~= 0 then
            for _ = 1, 12 do
                if tg_tn_bool(0x01BF60A500E28887, veh) then break end                       -- NETWORK_HAS_CONTROL_OF_ENTITY
                tg_tn_void(0xB69317BF5E782347, veh)                                          -- NETWORK_REQUEST_CONTROL_OF_ENTITY
                util.yield(25)
            end
            if tg_tn_bool(0x01BF60A500E28887, veh) then
                tg_tn_void(0x1C99BB7B6E96D16F, veh, 0.0, 0.0, 0.0)
                tg_tn_void(0x239A3351AC1DA385, veh, P.x + 0.0, P.y + 0.0, P.z + 0.0, false, false, false)
                tg_tn_void(0x8E2530AA8ADA980E, veh, heading + 0.0)
                tg_tn_void(0xAB54A438726D25D5, veh, 14.0)                                    -- SET_VEHICLE_FORWARD_SPEED
                return true, "direct"
            end
        end
    end
    -- 2) proven fallback: per-player Teleport To Me, with me briefly at the checkpoint
    if TG_RS_RESPAWN_ANCHOR == false then return false end
    local a = tg_rs_my_anchor()
    if not a then return false end
    tg_rs_move_anchor(a, P.x, P.y, P.z + 1.5)
    util.yield(250)
    local ok = tg_rs_trigger_feature(TG_RS_TP_FEATURES.to_me, pid)
    util.yield(700)
    tg_rs_restore_anchor(a)
    return ok, "remote"
end

-- course with checkpoints (parkour / hybrid / arcade courses)
function tg_rs_others_course_tick(cps)
    if not TG_RS_RESPAWN_OTHERS or not cps or #cps < 2 then return end
    local O = TG_RS_OTHERS
    local now = util.current_time_millis()
    if now - (O.last_scan or 0) < 400 then return end
    O.last_scan = now
    if O.cps ~= cps then O.cps, O.list = cps, {} end
    for _, pid in ipairs(tg_rs_other_players()) do
        local p = tg_rs_player_pos(pid)
        if p then
            local s = O.list[pid] or { reached = 0, last = 0, name = tg_rs_player_name(pid) }
            O.list[pid] = s
            for i = (s.reached or 0) + 1, math.min(#cps, (s.reached or 0) + 3) do
                local cp = cps[i]
                local dx, dy = p.x - cp.P.x, p.y - cp.P.y
                if dx * dx + dy * dy < 45.0 * 45.0 and math.abs(p.z - cp.P.z) < 8.0 then s.reached = i end
            end
            -- v2.2.0: never in the last stretch of a course (marked noresp) or once they've finished
            if (s.reached or 0) >= 1 and not cps[s.reached].noresp and s.reached < #cps then
                local cur = cps[s.reached]
                local nxt = cps[math.min(#cps, s.reached + 1)]
                local floor_z = math.min(cur.P.z, nxt.P.z) - 18.0
                if p.z < floor_z and (now - (s.last or 0)) > 4000 then
                    s.last = now
                    s.falls = (s.falls or 0) + 1
                    local ok, how = tg_rs_respawn_player(pid, cur.P, cur.psi)
                    tg_log(string.format("[TRACKMATIC][RESPAWN] %s fell -> checkpoint %d ok=%s via %s", tostring(s.name), s.reached, tostring(ok), tostring(how)))
                end
            end
        end
    end
end

-- flat arena (minigames): anyone below the platform goes back onto it
function tg_rs_others_arena_tick(level_z, spot)
    if not TG_RS_RESPAWN_OTHERS or not spot then return end
    local O = TG_RS_OTHERS
    local now = util.current_time_millis()
    if now - (O.last_arena or 0) < 400 then return end
    O.last_arena = now
    O.arena = O.arena or {}
    for _, pid in ipairs(tg_rs_other_players()) do
        local p = tg_rs_player_pos(pid)
        if p then
            local s = O.arena[pid] or { seen = false, last = 0 }
            O.arena[pid] = s
            local dx, dy = p.x - spot.P.x, p.y - spot.P.y
            -- only players who have actually been up on the platform
            if dx * dx + dy * dy < 250.0 * 250.0 and p.z > level_z - 3.0 then s.seen = true end
            if s.seen and p.z < level_z - 12.0 and dx * dx + dy * dy < 400.0 * 400.0 and (now - s.last) > 4000 then
                s.last = now
                tg_rs_respawn_player(pid, spot.P, spot.psi)
            end
        end
    end
end

function tg_rs_toggle_respawn_others()
    TG_RS_RESPAWN_OTHERS = not TG_RS_RESPAWN_OTHERS
    tg_toast("Respawn everyone who falls: " .. (TG_RS_RESPAWN_OTHERS and "ON" or "OFF (only you)"), 3000)
end

-- buttons shared by the Tubes / Parkour / Hybrid / Games panels
function tg_rs_tp_ui()
    if not tg_ui_button then return end
    ImGui.TextColored(1.0, 0.77, 0.0, 1.0, "BRING PLAYERS")
    tg_ui_button("TP All Above Me", 170, false, function() tg_rs_tp_all_above_me() end)
    tg_ui_same_line()
    tg_ui_button("TP All To Waypoint", 170, false, function() tg_rs_tp_all_waypoint() end)
    tg_ui_same_line()
    tg_ui_button("TP All To Course Start", 190, false, function() tg_rs_tp_all_start() end)
    tg_ui_button(TG_RS_RESPAWN_OTHERS and "Respawn Everyone On Fall: ON" or "Respawn Everyone On Fall: OFF", 270, TG_RS_RESPAWN_OTHERS == true,
        function() tg_rs_toggle_respawn_others() end)
end
-- 2026-10: stunt objects from "Stunt props for Map Editor v2" (stunt props.txt), minus track/tube pieces
-- (those are course pieces with measured joints) and physics balls/pins (already their own props).
TG_RS_STUNT_MODELS = {
    "stt_prop_corner_sign_01", "stt_prop_corner_sign_02", "stt_prop_corner_sign_03", "stt_prop_corner_sign_04",
    "stt_prop_corner_sign_05", "stt_prop_corner_sign_06", "stt_prop_corner_sign_07", "stt_prop_corner_sign_08",
    "stt_prop_corner_sign_09", "stt_prop_corner_sign_10", "stt_prop_corner_sign_11", "stt_prop_corner_sign_12",
