-- ═══════════════════════════════════════════════════════════════════════════════════
-- trackmatic v2.0.5: stunt objects on the track decks (hybrid + random all)
-- Every object's real size is read from the game (GET_MODEL_DIMENSIONS), so it is sat exactly on
-- the deck, turned so its long side runs along the track, and only used if it FITS:
--   narrow things (signs, flags, tyre walls, blocks...) go at the side so the lane stays open,
--   wide flat things (bumps, pads) go in the middle, anything else is skipped for another one.
-- Each build walks through a shuffled bag, so every object is a different one until all are used.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_RS_STUNTS_ON = (TG_RS_STUNTS_ON ~= false)
TG_RS_STUNT_DIMS = TG_RS_STUNT_DIMS or {}       -- model -> {min, max} | false
TG_RS_STUNT_NOFIT = TG_RS_STUNT_NOFIT or {}     -- model -> true (never fits on a deck)
TG_RS_STUNT_BAG = TG_RS_STUNT_BAG or {}
TG_RS_ARENA_NOFIT = TG_RS_ARENA_NOFIT or {}   -- v2.0.7: Arena Gauntlet pool (centre lane allowed)
TG_RS_DECK_HALF = 11.4                           -- track deck half width (23.4 m wide)

function tg_rs_model_dims_read(model, st)
    local h = util.joaat(model)
    st.pmin, st.pmax = Memory.Alloc(24), Memory.Alloc(24)
    if not st.pmin or st.pmin == 0 or not st.pmax or st.pmax == 0 then return nil end
    Natives.InvokeVoid(0x03E8D3D5F549087A, h, st.pmin, st.pmax)              -- GET_MODEL_DIMENSIONS
    local a, b = tg_world_obstacle_read_v3(st.pmin), tg_world_obstacle_read_v3(st.pmax)
    if not a or not b then return nil end
    if (b.x - a.x) <= 0.01 and (b.y - a.y) <= 0.01 then return nil end      -- unknown model
    return { min = a, max = b }
end
function tg_rs_model_dims(model)
    local c = TG_RS_STUNT_DIMS[model]
    if c ~= nil then return c or nil end
    -- TG_RS_DIMS_FN: test hook (offline planner tests), nil in the game
    if TG_RS_DIMS_FN then local d = TG_RS_DIMS_FN(model); TG_RS_STUNT_DIMS[model] = d or false; return d end
    local st = {}
    local res = tg_rs_model_dims_read(model, st)
    tg_world_obstacle_free_ptr(st.pmin)
    tg_world_obstacle_free_ptr(st.pmax)
    TG_RS_STUNT_DIMS[model] = res or false
    return res
end

function tg_rs_next_stunt()
    local bag = TG_RS_STUNT_BAG
    if #bag == 0 then
        local nofit = TG_RS_STUNT_POOL and TG_RS_ARENA_NOFIT or TG_RS_STUNT_NOFIT
        for _, m in ipairs(TG_RS_STUNT_POOL or TG_RS_STUNT_MODELS) do if not nofit[m] then table.insert(bag, m) end end
        for i = #bag, 2, -1 do local j = math.random(i); bag[i], bag[j] = bag[j], bag[i] end
        if #bag == 0 then return nil end
    end
    return table.remove(bag)
end

-- where/how a model sits on a deck tile; nil when it doesn't fit
function tg_rs_stunt_fit(model, deck_len, allow_centre)
    local d = tg_rs_model_dims(model)
    if not d then return nil end
    local w, l, h = d.max.x - d.min.x, d.max.y - d.min.y, d.max.z - d.min.z
    local rot = 0.0
    local across, along = l, w                 -- default: model X along the track
    if l > w then rot, across, along = 90.0, w, l end
    if along > deck_len * 0.8 or h > 30.0 then return nil end
    local lane
    if across <= 7.0 then lane = "side"
    elseif allow_centre and h <= 2.5 and across <= TG_RS_DECK_HALF * 2.0 - 1.0 then lane = "centre"
    else return nil end
    return { d = d, rot = rot, across = across, along = along, h = h, lane = lane }
end

-- plan entry (used by the Hybrid / Parkour planners): one stunt object on `tile`
function tg_rs_stunt_plan(props, tile, at_frac)
    if not TG_RS_STUNTS_ON or not tile or not tile.next then return nil end
    local len = (TG_PK_PIECES[tile.key] and TG_PK_PIECES[tile.key].len) or 0
    if len < 53 then return nil end
    local p = { prop = true, stunt = true, tile = tile, deck_len = len, at = len * (at_frac or (0.18 + math.random() * 0.12)),
                side = (math.random() < 0.5) and 1 or -1, model = "stt_prop_tyre_wall_01", origin = tile.entry, pitch = 0, rollY = 0, yaw = 0 }
    table.insert(props, p)
    return p
end

-- spawn: pick the next unique object that fits, sit it on the deck
function tg_rs_spawn_stunt(p, label)
    for try = 1, 6 do
        local model = tg_rs_next_stunt()
        if not model then return nil end
        local fit = tg_rs_stunt_fit(model, p.deck_len, p.allow_centre or TG_RS_STUNT_CENTRE)
        if fit then
            local psi = p.tile.next.psi
            local yaw = tg_normalize_heading(math.deg(psi) + fit.rot)
            local lat = 0.0
            if fit.lane == "side" then lat = p.side * (TG_RS_DECK_HALF - fit.across * 0.5 - 0.4) end
            local target = tg_hy_on_tile(p.tile, p.at, lat, 0.0)
            -- put the bounding-box centre on the target point and its bottom on the deck
            local cx, cy = (fit.d.min.x + fit.d.max.x) * 0.5, (fit.d.min.y + fit.d.max.y) * 0.5
            local yr = math.rad(yaw)
            local ox = target.x - (cx * math.cos(yr) - cy * math.sin(yr))
            local oy = target.y - (cx * math.sin(yr) + cy * math.cos(yr))
            local oz = target.z - fit.d.min.z + 0.02
            local obj = tg_try_create_stunt_tube_model(model, ox, oy, oz, yaw, label)
            if obj then
                tg_tube3d_apply_rotation(obj, 0.0, 0.0, yaw, label)
                tg_tn_void(0x239A3351AC1DA385, obj, ox + 0.0, oy + 0.0, oz + 0.0, false, false, false)
                tg_tn_void(0x428CA6DBD1094446, obj, true)                               -- FREEZE
                tg_tn_harden(obj, { x = ox, y = oy, z = oz, pitch = 0.0, roll = 0.0, yaw = yaw, model = model })
                if p.tint and tg_pk_tint then tg_pk_tint(obj, p.tint) end
                p.model, p.handle = model, obj
                tg_rs_diag(string.format("stunt object %s (%s, %.1fx%.1fx%.1f m)", model, fit.lane, fit.along, fit.across, fit.h))
                return obj
            end
        else
            -- dims known and it doesn't fit: never try it again this session
            if TG_RS_STUNT_DIMS[model] ~= nil then (TG_RS_STUNT_POOL and TG_RS_ARENA_NOFIT or TG_RS_STUNT_NOFIT)[model] = true end
        end
    end
    return nil
end
-- ═══════════════════════════════════════════════════════════════════════════════════
-- trackmatic creator (v2.2.0)
-- Rockstar-style snapping for road tracks, sky tracks, circuits, drift loops, downhills, wipeouts
-- and Hybrid courses - 8 categories x 18 course styles (144), plus Random and Hybrid.
--
-- Where the data comes from:
--   * Every piece's Start/End snap point is read from the model itself (the Start/End bones the
--     official creator snaps with), taken from the Forge 3D models - 86 pieces.
--   * 216 community + official stunt maps (38,971 objects) were parsed to learn how pieces are
--     joined: 10,643 joints, median gap 1.4 cm. Learned rules used here:
--       - pieces always join End -> Start; right turns are left-turn pieces driven backwards
--       - joints may hinge: road pitch up to 15 deg (most 1-5), yaw only a few degrees, never roll
--       - road / Stunt Track / wide Stunt Track pieces join directly (the official family switches)
--       - speed pads sit in the middle of the deck, lined up; tyre walls on the road edge;
--         jump ramps sit on the deck with their lip pointing at the gap; gantries span the road
-- The planner "thinks before placing" like the tube races: several full plans are made, every
-- piece is checked against the course itself, the ground and buildings, and the best plan wins.
-- v2.2.0: planning runs in the normal script job with cached, rate-limited ground readings and
-- collision probes (the v2.1.0 Stunt Race / Downhill crash); only spawning uses the freemode context.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_CR_P = {
