  ["stt_prop_track_straight_lm"] = { f = "road", k = "straight", w = 11.71, dep = 1.5, s = { -53.010,0.000,0.050, 0.000000,0.000000,0.000000,1.000000 }, e = { 53.010,0.000,0.050, 0.000000,0.000000,0.000000,1.000000 }, len = 106.02, turn = 0.0, rturn = 0.0, dz = 0.00, bb = { -53.01,-11.71,-0.15,53.01,11.71,0.15 } },
