-- ---------- matrices (columns X/Y/Z, same layout as tg_tp_apply / tg_tp_euler) ----------
function tg_cr_q2m(qx, qy, qz, qw)
    local n = math.sqrt(qx * qx + qy * qy + qz * qz + qw * qw)
    if n < 1e-9 then n = 1.0 end
    qx, qy, qz, qw = qx / n, qy / n, qz / n, qw / n
    return {
        X = tg_tp_v(1 - 2 * (qy * qy + qz * qz), 2 * (qx * qy + qz * qw), 2 * (qx * qz - qy * qw)),
        Y = tg_tp_v(2 * (qx * qy - qz * qw), 1 - 2 * (qx * qx + qz * qz), 2 * (qy * qz + qx * qw)),
        Z = tg_tp_v(2 * (qx * qz + qy * qw), 2 * (qy * qz - qx * qw), 1 - 2 * (qx * qx + qy * qy)) }
end
function tg_cr_mul(A, B) return { X = tg_tp_apply(A, B.X), Y = tg_tp_apply(A, B.Y), Z = tg_tp_apply(A, B.Z) } end
function tg_cr_T(A) return { X = tg_tp_v(A.X.x, A.Y.x, A.Z.x), Y = tg_tp_v(A.X.y, A.Y.y, A.Z.y), Z = tg_tp_v(A.X.z, A.Y.z, A.Z.z) } end
function tg_cr_rz(deg)
    local a = math.rad(deg or 0.0)
    return { X = tg_tp_v(math.cos(a), math.sin(a), 0.0), Y = tg_tp_v(-math.sin(a), math.cos(a), 0.0), Z = tg_tp_v(0.0, 0.0, 1.0) }
end
-- nose-up pitch about the local Y axis
function tg_cr_pitch(deg)
    local a = -math.rad(deg or 0.0)
    return { X = tg_tp_v(math.cos(a), 0.0, -math.sin(a)), Y = tg_tp_v(0.0, 1.0, 0.0), Z = tg_tp_v(math.sin(a), 0.0, math.cos(a)) }
end
TG_CR_RZ180 = { X = { x = -1.0, y = 0.0, z = 0.0 }, Y = { x = 0.0, y = -1.0, z = 0.0 }, Z = { x = 0.0, y = 0.0, z = 1.0 } }
function tg_cr_port(p, is_start)
    local M = tg_cr_q2m(p[4], p[5], p[6], p[7])
    if is_start then M = tg_cr_mul(M, TG_CR_RZ180) end
    return tg_tp_v(p[1], p[2], p[3]), M
end
function tg_cr_flat(v) return tg_tp_v(v.x, v.y, 0.0) end
function tg_cr_pitch_of(R) return math.deg(math.asin(math.max(-1.0, math.min(1.0, R.X.z)))) end
function tg_cr_heading_of(R) return math.deg(tg_atan2_safe(R.X.y, R.X.x)) end
-- level frame looking along heading h (deg)
function tg_cr_frame(h)
    local D = tg_tp_v(math.cos(math.rad(h)), math.sin(math.rad(h)), 0.0)
    return { X = D, Y = tg_tp_v(-D.y, D.x, 0.0), Z = tg_tp_v(0.0, 0.0, 1.0) }
end

-- ---------- one piece snapped onto a socket ----------
-- sock = { P = point, R = frame (X along travel, Z up) }; rev = drive the piece backwards (mirror turn);
-- hy/hp = learned hinge at the joint (yaw / nose-up pitch, degrees)
function tg_cr_place(sock, model, rev, hy, hp, light)
    local pc = TG_CR_P[model]
    if not pc then return nil end
    local inP, inM = tg_cr_port(rev and pc.e or pc.s, not rev)
    local outP, outM = tg_cr_port(rev and pc.s or pc.e, rev)
    local H = sock.R
    if (hy and hy ~= 0) then H = tg_cr_mul(H, tg_cr_rz(hy)) end
    if (hp and hp ~= 0) then H = tg_cr_mul(H, tg_cr_pitch(hp)) end
    local Rp = tg_cr_mul(tg_cr_mul(H, TG_CR_RZ180), tg_cr_T(inM))
    local origin = tg_tp_sub(sock.P, tg_tp_apply(Rp, inP))
    local nP = tg_tp_add(origin, tg_tp_apply(Rp, outP))
    local nR = tg_cr_mul(Rp, outM)
    local plan = { model = model, rev = rev, hy = hy or 0, hp = hp or 0, origin = origin, R = Rp, inP = sock.P, inD = H.X,
        next = { P = nP, R = nR }, w = pc.w, dep = pc.dep, f = pc.f, k = pc.k, len = pc.len }
    if light then return plan end
    -- spine samples for overlap / world checks: bends follow a circular arc through both snap points
    -- (the turning pieces are circular), everything else a Hermite curve
    local c = tg_tp_dist(sock.P, nP)
    local arc = math.max(c, pc.len or c, 1.0)
    local tsc = arc
    local n = math.max(2, math.ceil(arc / 12.0))
    local s = {}
    local a0 = tg_atan2_safe(H.X.y, H.X.x)
    local a1 = tg_atan2_safe(nR.X.y, nR.X.x)
    local th = (a1 - a0 + math.pi) % (2 * math.pi) - math.pi
    if math.abs(math.abs(th) - math.pi) < 0.02 then th = (math.abs(pc.turn) > 0 and (tg_tp_dot(tg_tp_sub(nP, sock.P), tg_tp_v(-H.X.y, H.X.x, 0)) >= 0) and math.pi or -math.pi) end
    local hc = math.sqrt((nP.x - sock.P.x) ^ 2 + (nP.y - sock.P.y) ^ 2)
    if math.abs(th) > math.rad(8.0) and hc > 1.0 then
        local Rr = hc / (2.0 * math.sin(math.abs(th) * 0.5))
        local mx, my = (sock.P.x + nP.x) * 0.5, (sock.P.y + nP.y) * 0.5
        local ux, uy = (nP.x - sock.P.x) / hc, (nP.y - sock.P.y) / hc
        local sgn = (th > 0) and 1 or -1
        local nx, ny = -uy * sgn, ux * sgn
        local d = math.sqrt(math.max(0.0, Rr * Rr - (hc * 0.5) ^ 2))
        local cx0, cy0 = mx + nx * d, my + ny * d
        local vx, vy = sock.P.x - cx0, sock.P.y - cy0
        arc = Rr * math.abs(th)
        n = math.max(3, math.ceil(arc / 10.0))
        for i = 0, n do
            local t = i / n
            local ph = th * t
            local cs, sn = math.cos(ph), math.sin(ph)
            table.insert(s, tg_tp_v(cx0 + vx * cs - vy * sn, cy0 + vx * sn + vy * cs, sock.P.z + (nP.z - sock.P.z) * t))
        end
    else
        for i = 0, n do
            local t = i / n
            local t2, t3 = t * t, t * t * t
            local h00, h10, h01, h11 = 2 * t3 - 3 * t2 + 1, t3 - 2 * t2 + t, -2 * t3 + 3 * t2, t3 - t2
            table.insert(s, tg_tp_add(tg_tp_add(tg_tp_mul(sock.P, h00), tg_tp_mul(H.X, h10 * tsc)),
                                      tg_tp_add(tg_tp_mul(nP, h01), tg_tp_mul(nR.X, h11 * tsc))))
        end
    end
    plan.samples, plan.arc = s, arc
    local cx, cy, cz, r = 0, 0, 0, 0
    for _, q in ipairs(s) do cx, cy, cz = cx + q.x, cy + q.y, cz + q.z end
    cx, cy, cz = cx / #s, cy / #s, cz / #s
    for _, q in ipairs(s) do r = math.max(r, math.sqrt((q.x - cx) ^ 2 + (q.y - cy) ^ 2)) end
    plan.cx, plan.cy, plan.cz, plan.rad = cx, cy, cz, r + pc.w
    plan.pitch, plan.rollY, plan.yaw = tg_tp_euler(Rp)
    return plan
end

-- a flat "pseudo piece" (a wipeout platform in the middle of a course) so the overlap check sees it
function tg_cr_pseudo(C, D, len, wid)
    local s = {}
    for i = 0, 4 do table.insert(s, tg_tp_add(C, tg_tp_mul(D, -len * 0.5 + len * i / 4))) end
    return { model = "_pseudo", samples = s, arc = len, w = wid * 0.5, dep = 2.0, cx = C.x, cy = C.y, cz = C.z,
             rad = len * 0.5 + wid * 0.5, pseudo = true, next = { P = tg_tp_add(C, tg_tp_mul(D, len * 0.5)), R = { X = D, Y = tg_tp_v(-D.y, D.x, 0), Z = tg_tp_v(0, 0, 1) } } }
end

-- overlap with the course itself: decks closer than their widths at overlapping heights (the sky
-- track's 100 m pillar counts as solid below its deck)
function tg_cr_clear(plan, placed, skip_arc)
    local along, upto = 0.0, #placed
    skip_arc = skip_arc or (plan.w * 2.2)
    while upto >= 1 and along < skip_arc do along = along + (placed[upto].arc or 0.0); upto = upto - 1 end
    for i = 1, upto do
        local q = placed[i]
        local dx, dy = q.cx - plan.cx, q.cy - plan.cy
        local lim = q.rad + plan.rad
        if dx * dx + dy * dy < lim * lim then
            local mw = (q.w + plan.w) * 0.92 + 1.0
            for _, a in ipairs(plan.samples) do
                for _, b in ipairs(q.samples) do
                    local hx, hy = a.x - b.x, a.y - b.y
                    if hx * hx + hy * hy < mw * mw then
                        if (a.z - plan.dep) < (b.z + 7.0) and (b.z - q.dep) < (a.z + 7.0) then return false, "overlap" end
                    end
                end
            end
        end
    end
    return true
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v2.2.0 world sampling: no cherax ground helper, cached, rate limited
-- ═══════════════════════════════════════════════════════════════════════════════════
-- v2.1.0 crashed ("gtav wants to fail fast") a few ms into stunt race / downhill: the sprint planner
-- asked GTA.GetGroundZ for several hundred points in a single frame from inside the freemode job.
-- Now: planning runs in the normal script job (only spawning goes to the freemode context), ground
-- readings come straight from GET_GROUND_Z_EXCLUDING_OBJECTS_FOR_3D_COORD with one reused pointer,
-- every reading is cached on a 4 m grid, and the planner yields a frame after every few readings /
-- collision probes.
TG_CR_FRAME_BUDGET = TG_CR_FRAME_BUDGET or 40      -- work units per frame (ground = 1, probe = 3)
TG_CR_NEAR_R = TG_CR_NEAR_R or 220.0              -- real collision is only streamed near you
TG_CR_GC = TG_CR_GC or {}
TG_CR_BUD = TG_CR_BUD or { n = 0, ground = 0, probes = 0, frames = 0 }
function tg_cr_reset_world()
    TG_CR_GC = {}
    TG_CR_BUD = { n = 0, ground = 0, probes = 0, frames = 0 }
    TG_CR_PROBES_OFF = false
    TG_CR_PROBE_FLAGS_CUR = TG_CR_PROBE_FLAGS
end
function tg_cr_budget(cost)
    local B = TG_CR_BUD
    B.n = B.n + (cost or 1)
    if B.n >= TG_CR_FRAME_BUDGET then
        B.n = 0
        B.frames = B.frames + 1
        util.yield(0)
    end
end
function tg_cr_native_ground(x, y, z0)
    if TG_CR_GROUND_FN then return TG_CR_GROUND_FN(x, y, z0) end      -- test hook (offline planner tests)
    if not TG_CR_ZPTR or TG_CR_ZPTR == 0 then TG_CR_ZPTR = Memory.Alloc(16) end
    -- GET_GROUND_Z_EXCLUDING_OBJECTS_FOR_3D_COORD (our own pieces from the last build don't count)
    if Natives.InvokeBool(0x9E82F0F362881B29, x + 0.0, y + 0.0, z0 + 0.0, TG_CR_ZPTR, false, false) then
        local z = tonumber(Memory.ReadFloat(TG_CR_ZPTR))
        if z and z == z and z > -200.0 and z < 2600.0 then return z end
    end
    -- GET_GROUND_Z_FOR_3D_COORD as a second opinion
    if Natives.InvokeBool(0xC906A7DAB05C8D2B, x + 0.0, y + 0.0, z0 + 0.0, TG_CR_ZPTR, false, false) then
        local z = tonumber(Memory.ReadFloat(TG_CR_ZPTR))
        if z and z == z and z > -200.0 and z < 2600.0 then return z end
    end
    return nil
end
-- ground under a point: real collision near you (roofs count), the map's height map further out
function tg_cr_ground(x, y)
    local k = math.floor(x * 0.25) * 100000 + math.floor(y * 0.25)
    local c = TG_CR_GC[k]
    if c ~= nil then return c or nil end
    local g = nil
    local ctx = TG_CR_CTX
    if ctx and ctx.home and ((x - ctx.home.x) ^ 2 + (y - ctx.home.y) ^ 2) < TG_CR_NEAR_R * TG_CR_NEAR_R then
        tg_cr_budget(1)
        TG_CR_BUD.ground = TG_CR_BUD.ground + 1
        local top = tg_rs_height(x, y) or nil
        g = tg_cr_native_ground(x, y, (top and (top + 6.0)) or 1500.0)
    end
    if not g and tg_rs_height then g = tg_rs_height(x, y) end
    TG_CR_GC[k] = g or false
    return g
end
-- uncached reading at the exact point (object footprints) - still rate limited
function tg_cr_ground_exact(x, y)
    if tg_cr_near({ x = x, y = y }) then
        tg_cr_budget(1)
        TG_CR_BUD.ground = TG_CR_BUD.ground + 1
        local top = tg_rs_height(x, y) or nil
        local g = tg_cr_native_ground(x, y, (top and (top + 6.0)) or 1500.0)
        if g then return g end
    end
    return tg_cr_ground(x, y)
end
-- ---------- collision probes (v2.2.1) ----------
-- The shared helper used START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE with fresh 4-byte buffers
-- for every ray. Bursts of those crashed the game ("Wants To Fail Fast") in v2.1.0 sprint planning
-- and in v2.2.0 Wipeout in a built-up area. The Creator and Lab now use the asynchronous probe the
-- game's own scripts use (START_SHAPE_TEST_LOS_PROBE, polled with GET_SHAPE_TEST_RESULT until it
-- returns 0 or 2), at most 8 rays in flight, polled across frames, with persistent 64-byte buffers.
TG_CR_PROBE_FLAGS = 321                              -- world (buildings, terrain) + glass + foliage (trees)
TG_CR_PROBE_FLAGS_RELAXED = 1                        -- buildings + terrain only (never relaxed further)
TG_CR_PROBE_BATCH = TG_CR_PROBE_BATCH or 12
function tg_cr_alloc_probe_bufs()
    local t = { hit = Memory.Alloc(64), endc = Memory.Alloc(64), nrm = Memory.Alloc(64), ent = Memory.Alloc(64) }
    for _, v in pairs(t) do if not v or v == 0 then return nil end end
    return t
end
function tg_cr_probe_bufs()
    if TG_CR_PBUF then return TG_CR_PBUF end
    TG_CR_PBUF = tg_cr_alloc_probe_bufs()
    return TG_CR_PBUF
end
-- rays = { { ax, ay, az, bx, by, bz }, ... }; true when any ray hits something that isn't ours
function tg_cr_probe_any(rays)
    if #rays == 0 or TG_CR_PROBES_OFF or TG_WORLD_OBSTACLE_AVOIDANCE == false then return false end
    TG_CR_BUD.probes = TG_CR_BUD.probes + #rays
    if TG_CR_PROBE_FN then
        -- test hook (offline planner tests): one ray at a time, rate limited
        local fn = TG_CR_PROBE_FN
        local any = false
        for _, r in ipairs(rays) do
            tg_cr_budget(3)
            local hit, _, ent = fn(r[1], r[2], r[3], r[4], r[5], r[6], 0, "creator")
            if hit and not (tg_world_obstacle_is_own_entity(ent)) then any = true end
        end
        return any
    end
    local B = tg_cr_probe_bufs()
    if not B then TG_CR_PROBES_OFF = true; return false end
    local any = false
    local i = 1
    while i <= #rays do
        local live = {}
        for k = i, math.min(#rays, i + TG_CR_PROBE_BATCH - 1) do
            local r = rays[k]
            local h = Natives.InvokeInt(0x7EE9F5D83DD4F90E, r[1] + 0.0, r[2] + 0.0, r[3] + 0.0, r[4] + 0.0, r[5] + 0.0, r[6] + 0.0, TG_CR_PROBE_FLAGS_CUR or TG_CR_PROBE_FLAGS, 0, 7)
            if h and h ~= 0 then table.insert(live, h) end
        end
        i = i + TG_CR_PROBE_BATCH
        -- results arrive on a later frame; keep polling until every handle is finished (0 or 2)
        local tries = 0
        while #live > 0 and tries < 30 do
            util.yield(0)
            TG_CR_BUD.frames = TG_CR_BUD.frames + 1
            tries = tries + 1
            local still = {}
            for _, h in ipairs(live) do
                local res = Natives.InvokeInt(0x3D87450E15D98694, h, B.hit, B.endc, B.nrm, B.ent)
                if res == 1 then
                    table.insert(still, h)
                elseif res == 2 then
                    local hit = (tonumber(Memory.ReadInt(B.hit)) or 0) ~= 0
                    local ent = tonumber(Memory.ReadInt(B.ent)) or 0
                    if hit and not (tg_world_obstacle_is_own_entity(ent)) then any = true end
                end
            end
            live = still
        end
        TG_CR_BUD.n = 0
    end
    return any
end
function tg_cr_probe(ax, ay, az, bx, by, bz)
    return tg_cr_probe_any({ { ax, ay, az, bx, by, bz } })
end
function tg_cr_near(p)
    local ctx = TG_CR_CTX
    if not (ctx and ctx.home) then return false end
    return ((p.x - ctx.home.x) ^ 2 + (p.y - ctx.home.y) ^ 2) < TG_CR_NEAR_R * TG_CR_NEAR_R
end

-- world check for one piece; returns ok, reason, lowest / highest height above ground
-- ctx.probes = false: ground only (cheap pass while searching)
function tg_cr_world(plan, ctx)
    local s = plan.samples
    -- v2.3.0 radius (Track tab): every piece stays inside the circle round you
    local RC = TG_CR_RADIUS
    if RC and s then
        local w2 = (plan.w or 8.0)
        local lim = (RC.r - w2) * (RC.r - w2)
        for _, q in ipairs(s) do
            local dx, dy = q.x - RC.x, q.y - RC.y
            if dx * dx + dy * dy > lim then return false, "radius" end
        end
    end
    local bury = ctx.bury or 0.6
    local hmin, hmax = 99999.0, -99999.0
    local Lw = plan.R and tg_tp_norm(tg_cr_flat(plan.R.Y)) or tg_tp_v(0, 1, 0)
    if tg_tp_len(Lw) < 0.1 then Lw = tg_tp_v(0, 1, 0) end
    local w = plan.w or 8.0
    local we = w * (ctx.edge or 1.0)
    for _, q in ipairs(s) do
        local g = tg_cr_ground(q.x, q.y)
        for _, e in ipairs({ we, -we }) do
            local ge = tg_cr_ground(q.x + Lw.x * e, q.y + Lw.y * e)
            if ge and (not g or ge > g) then g = ge end
        end
        if g then
            local h = q.z - g
            local allow = bury
            if ctx.near_start and ctx.start_P and tg_tp_dist(q, ctx.start_P) < 40.0 then allow = math.max(allow, 2.5) end
            if h < -allow then return false, "terrain", h end
            hmin, hmax = math.min(hmin, h), math.max(hmax, h)
        end
    end
    if ctx.probes ~= false and not TG_CR_PROBES_OFF then
        local L = tg_tp_norm(tg_cr_flat(plan.R and plan.R.Y or tg_tp_v(0, 1, 0)))
        local wl = math.max(1.0, w - 1.5)
        local offs = { { 0.0, 1.0 }, { wl, 1.5 }, { -wl, 1.5 }, { 0.0, 5.0 } }
        -- segments of ~24 m (every other spine sample) - the probe is a line, it doesn't need more
        local step = (#s > 4) and 2 or 1
        local i = 1
        local rays = {}
        while i < #s do
            local j = math.min(#s, i + step)
            local a, b = s[i], s[j]
            if tg_cr_near(a) or tg_cr_near(b) then
                for _, o in ipairs(offs) do
                    table.insert(rays, { a.x + L.x * o[1], a.y + L.y * o[1], a.z + o[2], b.x + L.x * o[1], b.y + L.y * o[1], b.z + o[2] })
                end
            end
            i = j
        end
        if tg_cr_probe_any(rays) then return false, "building", hmin end
    end
    return true, "ok", (hmin < 99999.0) and hmin or nil, (hmax > -99999.0) and hmax or nil
end

