-- learned family switches (Hybrid): the joints official maps use between road, Stunt Track and dw pieces
TG_CR_SWITCH = {
    road = { stunt = "stt_prop_stunt_track_short", dw = "stt_prop_stunt_track_dwshort" },
    stunt = { road = "stt_prop_track_link", dw = "stt_prop_stunt_track_dwlink" },
    dw = { road = "stt_prop_track_straight_s", stunt = "stt_prop_stunt_track_straight" },
}
function tg_cr_learned_w(learned, m)
    local L = TG_CR_LEARNED[learned or "stunt"] or {}
    local n = L[m] or L[TG_CR_BAR[m] or ""] or L[TG_CR_UNBAR[m] or ""] or 0
    return 1.0 + math.sqrt(n)
end

-- ---------- course styles (144 + Random + Hybrid) ----------
function tg_cr_variant(cat, id)
    local list = TG_CR_VARIANTS[cat] or {}
    if #list == 0 then return {} end
    if id == nil or id == "random" then return list[math.random(#list)] end
    for _, v in ipairs(list) do if v.id == id then return v end end
    return list[1]
end
function tg_cr_variant_name(cat, id)
    if id == nil or id == "random" then return "Random style" end
    local v = tg_cr_variant(cat, id)
    return v and v.name or tostring(id)
end
-- tint for piece i: -1 model colour, 0..15 creator colour, "rainbow", "random"
function tg_cr_tint_for(tint, i)
    if tint == nil or tint == -1 then return nil end
    if tint == "rainbow" then return (i % 15) + 1 end
    if tint == "random" then return math.random(0, 15) end
    return tonumber(tint)
end

-- ---------- decor (learned placement rules) ----------
function tg_cr_deck_point(plan, t)
    local s = plan.samples
    local f = t * (#s - 1)
    local i = math.min(#s - 1, math.floor(f) + 1)
    local a, b = s[i], s[i + 1]
    local u = f - (i - 1)
    local P = tg_tp_add(a, tg_tp_mul(tg_tp_sub(b, a), u))
    local D = tg_tp_norm(tg_tp_sub(b, a))
    return P, D
end
function tg_cr_decor(list, model, plan, t, lat, yaw_off, lift)
    local P, D = tg_cr_deck_point(plan, t)
    local L = tg_tp_norm(tg_tp_cross(tg_tp_v(0, 0, 1), D))
    P = tg_tp_add(P, tg_tp_mul(L, lat or 0.0))
    local yaw = math.deg(tg_atan2_safe(D.y, D.x)) + (yaw_off or 0.0)
    table.insert(list, { decor = true, model = model, P = P, yaw = tg_normalize_heading(yaw), lift = lift or 0.0,
        pitch = math.deg(math.asin(math.max(-1, math.min(1, D.z)))) })
end
function tg_cr_decor_plan(d)
    local bb = TG_CR_BB[d.model]
    local R = tg_cr_mul(tg_cr_rz(d.yaw), tg_cr_pitch(d.pitch or 0.0))
    local cx, cy, zb = 0.0, 0.0, 0.0
    if bb then cx, cy, zb = (bb[1] + bb[4]) * 0.5, (bb[2] + bb[5]) * 0.5, bb[3] end
    local off = tg_tp_apply(R, tg_tp_v(cx, cy, zb))
    local up = tg_tp_mul(R.Z, 0.03 + (d.lift or 0.0))
    d.origin = tg_tp_add(tg_tp_sub(d.P, off), up)
    d.R = R
    d.pitch_e, d.roll_e, d.yaw_e = tg_tp_euler(R)
    return d
end

-- ---------- closed loops ----------
-- A loop is a polygon of n equal turns. Corners alternate between two corner sets (A,B,A,B...),
-- opposite edges hold the same pieces (any order) and every edge feature has zero net heading and
-- zero net height, so the loop closes exactly - the same trick creators use by copying corners.
TG_CR_CORNERS = {
    road = {
        [180] = { { "stt_prop_track_bend_180d" }, { "stt_prop_track_bend2_l_b", "stt_prop_track_bend2_l_b" }, { "stt_prop_track_bend_l", "stt_prop_track_bend_l" } },
        [90] = { { "stt_prop_track_bend_l" }, { "stt_prop_track_bend_l_b" }, { "stt_prop_track_bend2_l" }, { "stt_prop_track_bend2_l_b" },
                 { "stt_prop_track_bend_m", "stt_prop_track_bend_m" }, { "stt_prop_track_bend_30d", "stt_prop_track_bend_30d", "stt_prop_track_bend_30d" } },
        [60] = { { "stt_prop_track_bend_30d", "stt_prop_track_bend_30d" } },
        [45] = { { "stt_prop_track_bend_m" } },
    },
    drift = {
        [180] = { { "stt_prop_track_bend_180d" }, { "stt_prop_track_bend_l_b", "stt_prop_track_bend_l_b" },
                  { "sum_prop_track_ac_bend_135", "stt_prop_track_bend_m" } },
        [90] = { { "stt_prop_track_bend_l_b" }, { "stt_prop_track_bend_l" }, { "stt_prop_track_bend_m", "stt_prop_track_bend_m" },
                 { "sum_prop_track_ac_bend_135", { "stt_prop_track_bend_m", true } } },
        [45] = { { "stt_prop_track_bend_m" } },
    },
    stunt = {
        [180] = { { "stt_prop_stunt_track_uturn" }, { "stt_prop_stunt_track_turn", "stt_prop_stunt_track_turn" } },
        [90] = { { "stt_prop_stunt_track_turn" }, { "stt_prop_stunt_track_sh45", "stt_prop_stunt_track_sh45" }, { "stt_prop_stunt_track_sh45_a", "stt_prop_stunt_track_sh45_a" },
                 { "stt_prop_stunt_track_sh30", "stt_prop_stunt_track_sh30", "stt_prop_stunt_track_sh30" } },
        [60] = { { "stt_prop_stunt_track_sh30", "stt_prop_stunt_track_sh30" } },
        [45] = { { "stt_prop_stunt_track_sh45" }, { "stt_prop_stunt_track_sh45_a" } },
    },
    dw = {
        [180] = { { "stt_prop_stunt_track_dwuturn" }, { "stt_prop_stunt_track_dwturn", "stt_prop_stunt_track_dwturn" } },
        [90] = { { "stt_prop_stunt_track_dwturn" } },
    },
}
-- drift corner preferences (first model of the set decides)
TG_CR_DRIFT_PREF = {
    tight = { stt_prop_track_bend_l_b = 4, stt_prop_track_bend_l = 3, stt_prop_track_bend_m = 1 },
    hair = { stt_prop_track_bend_180d = 4, stt_prop_track_bend_l_b = 2 },
    wide = { stt_prop_track_bend_l = 3, stt_prop_track_bend_m = 3 },
    sharp = { sum_prop_track_ac_bend_135 = 5, stt_prop_track_bend_l_b = 1 },
}
function tg_cr_item(it) if type(it) == "table" then return it[1], it[2] == true end return it, false end
function tg_cr_item_turn(it)
    local m, r = tg_cr_item(it)
    local pc = TG_CR_P[m]
    if not pc then return 999 end
    local t = r and pc.rturn or pc.turn
    if math.abs(math.abs(t) - 180) < 0.5 then return 180 end
    return t
end
do
    for _, byturn in pairs(TG_CR_CORNERS) do
        for turn, sets in pairs(byturn) do
            for i = #sets, 1, -1 do
                local t = 0.0
                for _, it in ipairs(sets[i]) do t = t + tg_cr_item_turn(it) end
                if math.abs(t - turn) > 0.6 then table.remove(sets, i) end
            end
        end
    end
end
TG_CR_STRAIGHTS = {
    road = { "stt_prop_track_straight_s", "stt_prop_track_link", "stt_prop_track_straight_m", "stt_prop_track_straight_lm", "stt_prop_track_straight_l" },
    stunt = { "stt_prop_stunt_track_short", "stt_prop_stunt_track_straight", "stt_prop_stunt_track_st_02", "stt_prop_stunt_track_funlng",
              "stt_prop_stunt_track_cutout", "stt_prop_stunt_track_otake", "stt_prop_stunt_track_bumps", "stt_prop_stunt_track_hill" },
    dw = { "stt_prop_stunt_track_dwshort", "stt_prop_stunt_track_dwlink", "stt_prop_stunt_track_dwlink_02" },
}
TG_CR_START = { road = "stt_prop_track_start", stunt = "stt_prop_stunt_track_start", dw = "stt_prop_stunt_track_dwlink" }
TG_CR_START_TWIN = { road = "stt_prop_track_straight_lm", stunt = "stt_prop_stunt_track_funlng", dw = "stt_prop_stunt_track_dwlink_02" }
function tg_cr_straight_pick(fam, pref)
    local list = TG_CR_STRAIGHTS[fam]
    if pref == "short" then return list[math.random(1, math.min(3, #list))] end
    if pref == "long" then return list[math.random(math.max(1, #list - 1), #list)] end
    return list[math.random(#list)]
end

-- edge features with zero net heading and zero net height: items { model, reversed, hinge pitch }
-- (gap items = a jump: { gap = metres, ramp = model })
function tg_cr_features(fam, V, flavour)
    local F = {}
    local fw = (V and V.feats) or {}
    local function W(key, base) local m = fw[key]; if m == nil then return base end; return m end
    flavour = flavour or {}
    if fam == "road" then
        if not flavour.drift then
            local c = W("chic", 3)
            if c > 0 then
                table.insert(F, { w = c, items = { { "stt_prop_track_chicane_l" } } })
                table.insert(F, { w = c, items = { { "stt_prop_track_chicane_r" } } })
                table.insert(F, { w = c, items = { { "stt_prop_track_chicane_l_02" } } })
                table.insert(F, { w = c, items = { { "stt_prop_track_chicane_r_02" } } })
            end
        end
        local s15 = W("s15", 3)
        if s15 > 0 then
            table.insert(F, { w = s15, items = { { "stt_prop_track_bend_15d" }, { "stt_prop_track_bend_15d", true } } })
            table.insert(F, { w = s15, items = { { "stt_prop_track_bend_15d", true }, { "stt_prop_track_bend_15d" } } })
        end
        local s5 = W("s5", 2)
        if s5 > 0 then table.insert(F, { w = s5, items = { { "stt_prop_track_bend_5d" }, { "stt_prop_track_bend_5d", true } } }) end
        local s30 = W("s30", 2)
        if s30 > 0 then table.insert(F, { w = s30, items = { { "stt_prop_track_bend_30d" }, { "stt_prop_track_bend_30d", true }, { "stt_prop_track_bend_30d", true }, { "stt_prop_track_bend_30d" } } }) end
        if flavour.drift then
            local e = W("esses", 3)
            if e > 0 then table.insert(F, { w = e, items = { { "stt_prop_track_bend_m" }, { "stt_prop_track_bend_m", true }, { "stt_prop_track_bend_m", true }, { "stt_prop_track_bend_m" } } }) end
            local kk = W("kick", 2)
            if kk > 0 then
                table.insert(F, { w = kk, items = { { "stt_prop_track_bend_l_b" }, { "stt_prop_track_bend_l_b", true } } })
                table.insert(F, { w = kk, items = { { "stt_prop_track_chicane_l_02" } } })
                table.insert(F, { w = kk, items = { { "stt_prop_track_chicane_r_02" } } })
            end
        end
        if TG_CR.hills and not flavour.drift then
            local hw = W("hill", 3)
            local lo, hi = 4, 8
            if V and V.hills then lo, hi = V.hills[1] or 4, V.hills[2] or 8 end
            if hw > 0 and hi > 0 then
                local a = lo + math.random() * math.max(0.0, hi - lo)
                if a >= 1.0 then
                    -- a hinge hill (tilted joints, like the official maps): climb, flat top, drop, level out
                    table.insert(F, { w = hw, hill = true, items = { { "stt_prop_track_straight_m", false, a }, { "stt_prop_track_straight_m", false, -a },
                        { "stt_prop_track_straight_m", false, -a }, { "stt_prop_track_straight_m", false, a } } })
                    table.insert(F, { w = hw * 0.35, hill = true, items = { { "sr_prop_track_straight_l_u5" }, { "sr_prop_track_straight_l_d5" }, { "sr_prop_track_straight_l_d5" }, { "sr_prop_track_straight_l_u5" } } })
                end
            end
        end
        local jw = W("jump", 0)
        if TG_CR.jumps and jw > 0 then
            -- learned jump: take-off deck with the ramp on its end, a 35-50 m gap, a long landing deck (level for loops)
            local ramp = ({ "stt_prop_track_jump_01a", "stt_prop_track_jump_01a", "stt_prop_track_jump_02a" })[math.random(3)]
            local gap = 34 + math.random() * 14
            table.insert(F, { w = jw, cost = 2, items = { { "stt_prop_track_straight_l" }, { gap = gap, ramp = ramp }, { "stt_prop_track_straight_lm", landing = true } } })
        end
    elseif fam == "stunt" then
        local hw = (V and V.hillw) or 1.0
        table.insert(F, { w = 3, items = { { "stt_prop_stunt_track_sh15" }, { "stt_prop_stunt_track_sh15", true } } })
        table.insert(F, { w = 3, items = { { "stt_prop_stunt_track_sh15", true }, { "stt_prop_stunt_track_sh15" } } })
        table.insert(F, { w = 2, items = { { "stt_prop_stunt_track_sh30" }, { "stt_prop_stunt_track_sh30", true }, { "stt_prop_stunt_track_sh30", true }, { "stt_prop_stunt_track_sh30" } } })
        if TG_CR.hills and hw > 0 then
            table.insert(F, { w = 3 * hw, hill = true, items = { { "stt_prop_stunt_track_slope15" }, { "stt_prop_stunt_track_short" }, { "stt_prop_stunt_track_slope15", true } } })
            table.insert(F, { w = 1 * hw, hill = true, items = { { "stt_prop_stunt_track_slope30" }, { "stt_prop_stunt_track_straight" }, { "stt_prop_stunt_track_slope30", true } } })
            table.insert(F, { w = 1 * hw, items = { { "stt_prop_stunt_track_bumps" } } })
        end
    elseif fam == "dw" then
        local hw = (V and V.hillw) or 1.0
        table.insert(F, { w = 3, items = { { "stt_prop_stunt_track_dwsh15" }, { "stt_prop_stunt_track_dwsh15", true } } })
        table.insert(F, { w = 3, items = { { "stt_prop_stunt_track_dwsh15", true }, { "stt_prop_stunt_track_dwsh15" } } })
        if TG_CR.hills and hw > 0 then
            table.insert(F, { w = 3 * hw, hill = true, items = { { "stt_prop_stunt_track_dwslope15" }, { "stt_prop_stunt_track_dwshort" }, { "stt_prop_stunt_track_dwslope15", true } } })
        end
    end
    return F
end
-- v2.2.1 elevation pair: one edge climbs on hinged joints and levels out high, its mirror edge
-- (the copy on the opposite side of the polygon) drops back down. Horizontal lengths are identical
-- and the heights cancel, so the loop still closes exactly - everything in between runs raised.
function tg_cr_elev_feature(fam, L)
    local m, a, kmax
    if fam == "road" then m, a, kmax = "stt_prop_track_straight_m", L.elev_a or (6.0 + math.random() * 3.5), L.elev_k or 3
    elseif fam == "dw" then m, a, kmax = "stt_prop_stunt_track_dwlink", 4.5, 2
    else m, a, kmax = "stt_prop_stunt_track_straight", 4.5, 2 end
    if L.V and L.V.tt and L.V.tt.incline then a = math.min(a, L.V.tt.incline) end
    local k = math.random(1, kmax)
    local up, down = { { m, false, a } }, { { m, false, -a } }
    for _ = 2, k do table.insert(up, { m, false, 0 }); table.insert(down, { m, false, 0 }) end
    table.insert(up, { m, false, -a }); table.insert(down, { m, false, a })
    return { up = up, down = down, cost = k + 1 }
end
function tg_cr_pick_w(list)
    local tot = 0.0
    for _, it in ipairs(list) do tot = tot + (it.w or 1.0) end
    local r = math.random() * tot
    for _, it in ipairs(list) do r = r - (it.w or 1.0); if r <= 0 then return it end end
    return list[#list]
end
function tg_cr_shuffle(t)
    for i = #t, 2, -1 do local j = math.random(i); t[i], t[j] = t[j], t[i] end
    return t
end
function tg_cr_item_cost(items)
    local n = 0
    for _, g in ipairs(items) do if not g.gap then n = n + 1 end end
    return n
end

-- loop recipe: list of steps { model, reversed, hinge pitch, start = bool } and gap steps { gap = m }
-- L = loop description { fam, drift, shape, feat_p, straight, corners, start_model }
function tg_cr_loop_recipe(L, budget, mirror)
    local fam = L.fam
    local cfam = (L.drift and "drift") or fam
    local shape = L.shape or "auto"
    local n
    if shape == "oval" then n = 2 elseif shape == "rect" then n = 4 elseif shape == "hex" then n = 6 elseif shape == "oct" then n = 8
    else
        local r = math.random()
        local p2 = (budget < 36) and 0.3 or 0.0
        n = (r < p2) and 2 or (r < 0.72) and 4 or (r < 0.88) and 6 or 8
    end
    -- v2.2.5 compact loop (cramped spot): a hairpin oval or a tight square, the tightest corners
    if L.compact then n = (math.random() < 0.7) and 2 or 4 end
    local turn = math.floor(360 / n + 0.5)
    local sets = TG_CR_CORNERS[cfam][turn] or TG_CR_CORNERS[fam][turn]
    if not sets or #sets == 0 then n, turn = 4, 90; sets = TG_CR_CORNERS[cfam][90] or TG_CR_CORNERS[fam][90] end
    local function pick_set()
        if L.compact then
            local best, bl = nil, nil
            for _, st in ipairs(sets) do
                local l = 0.0
                for _, it in ipairs(st) do local m = tg_cr_item(it); l = l + ((TG_CR_P[m] and TG_CR_P[m].len) or 50.0) end
                if not bl or l < bl then best, bl = st, l end
            end
            return best
        end
        local pref = L.corners and TG_CR_DRIFT_PREF[L.corners]
        local ttw = L.V and L.V.tt and L.V.tt.setw_on and tg_tt_cr_setw
        if not pref and not ttw then return sets[math.random(#sets)] end
        local w = {}
        for _, st in ipairs(sets) do
            local ww = pref and (pref[tg_cr_item(st[1])] or 0.4) or 1.0
            if ttw then ww = ww * ttw(L.V.tt, st) end
            table.insert(w, { set = st, w = ww })
        end
        return tg_cr_pick_w(w).set
    end
    local A = pick_set()
    local B = (n == 2) and A or pick_set()
    local half = n / 2
    local corner_n = (#A + #B) * half
    if n == 2 then corner_n = #A * 2 end
    local edges = {}
    for k = 1, half do edges[k] = {} end
    local start_model = L.start_model or TG_CR_START[fam]
    table.insert(edges[1], { start_model, false, 0, start = true })
    local left = budget - corner_n - 2
    if left < 0 then return nil end
    -- climbs first (they're what makes the loop go up and down)
    if TG_CR.hills then
        for _ = 1, (L.compact and 0 or (L.elev or 0)) do
            local f = tg_cr_elev_feature(fam, L)
            if f.cost * 2 <= left - 4 then
                table.insert(edges[math.random(half)], { group = f.up, group_copy = f.down })
                left = left - f.cost * 2
            end
        end
    end
    local feats = tg_cr_features(fam, L.V, { drift = L.drift })
    local feat_p = L.feat_p or ((L.drift and 0.5) or 0.3)
    if L.compact then feat_p = math.min(feat_p, 0.12) end
    if TG_CR.across then feat_p = feat_p * 0.4 end
    local guard = 0
    while left >= 2 and guard < 300 do
        guard = guard + 1
        local k = math.random(half)
        if math.random() < feat_p and #feats > 0 then
            local f = tg_cr_pick_w(feats)
            local cost = f.cost or tg_cr_item_cost(f.items)
            if cost * 2 <= left then
                table.insert(edges[k], { group = f.items }); left = left - cost * 2
            end
        else
            local m = TG_CR.across and tg_cr_straight_pick(fam, "long") or tg_cr_straight_pick(fam, L.compact and "short" or L.straight)
            table.insert(edges[k], { m, false, 0 }); left = left - 2
        end
    end
    local steps = {}
    local function corner(set)
        for _, it in ipairs(set) do
            local m, r = tg_cr_item(it)
            table.insert(steps, { m, (r ~= mirror), 0 })
        end
    end
    local function edge(items, copy)
        local list = {}
        for _, it in ipairs(items) do
            if copy and it.start then table.insert(list, { L.start_twin or TG_CR_START_TWIN[fam], false, 0 })
            else table.insert(list, it) end
        end
        local keep = false
        local ttl = L.V and L.V.tt
        if ttl and (ttl.sym or 0) > 0 then
            if items.tt_keep == nil then items.tt_keep = (math.random() * 100.0 < ttl.sym) end
            keep = items.tt_keep
        end
        if copy then
            if not keep then tg_cr_shuffle(list) end
        else
            local first = table.remove(list, 1)
            if not keep then tg_cr_shuffle(list) end
            table.insert(list, 1, first)
        end
        for _, it in ipairs(list) do
            if it.group then
                for _, g in ipairs((copy and it.group_copy) or it.group) do
                    if g.gap then
                        table.insert(steps, { gap = g.gap, ramp = g.ramp })
                    else
                        local rev = (g[2] == true)
                        if mirror and TG_CR_P[g[1]] and math.abs(TG_CR_P[g[1]].turn) > 0.5 then rev = not rev end
                        local m = g[1]
                        if mirror and m:find("chicane_l", 1, true) then m = m:gsub("chicane_l", "chicane_r")
                        elseif mirror and m:find("chicane_r", 1, true) then m = m:gsub("chicane_r", "chicane_l") end
                        table.insert(steps, { m, rev, g[3] or 0, landing = g.landing })
                    end
                end
            else table.insert(steps, { it[1], it[2], it[3], start = it.start }) end
        end
    end
    for rep = 1, 2 do
        for k = 1, half do
            edge(edges[k], rep == 2)
            corner(((k % 2) == 1) and A or B)
        end
    end
    if fam == "road" then
        for _, s in ipairs(steps) do if s[1] and not s.start and s[1] ~= "stt_prop_track_cross" then s[1] = tg_cr_bar(s[1]) end end
    end
    return steps, n
end

-- overlap check that lets the loop close onto its first pieces
function tg_cr_clear_loop(p, plans, sock0)
    local near_start = tg_tp_dist(p.next.P, sock0.P) < (p.arc + p.w * 3.0)
    if not near_start then return tg_cr_clear(p, plans) end
    local skip_head, a = 0, 0.0
    while skip_head < #plans and a < p.w * 2.5 do skip_head = skip_head + 1; a = a + (plans[skip_head].arc or 0.0) end
    local sub = {}
    for j = skip_head + 1, #plans do table.insert(sub, plans[j]) end
    return tg_cr_clear(p, sub)
end

-- run a loop recipe from a socket; returns plans, closure gap (m), heading error (deg)
function tg_cr_run_steps(sock, steps, loop)
    local plans = {}
    local s = sock
    local pending_jump = nil
    for i, st in ipairs(steps) do
        if st.gap then
            local last = plans[#plans]
            if not last then return nil, 1e9, 180, "gap first" end
            last.jump = { ramp = st.ramp, gap = st.gap, drop = 0.0 }
            s = { P = tg_tp_add(s.P, tg_tp_mul(tg_tp_norm(tg_cr_flat(s.R.X)), st.gap)), R = s.R }
            pending_jump = true
        else
            local p = tg_cr_place(s, st[1], st[2], 0, st[3] or 0)
            if not p then return nil, 1e9, 180, "missing " .. tostring(st[1]) end
            p.step = st
            if pending_jump then p.landing = true; pending_jump = nil end
            local ok = loop and tg_cr_clear_loop(p, plans, sock) or tg_cr_clear(p, plans)
            if not ok then return nil, 1e9, 180, "overlap" end
            table.insert(plans, p)
            s = p.next
        end
        if i % 8 == 0 then util.yield(0) end
    end
    local gap = tg_tp_dist(s.P, sock.P)
    local hd = math.abs(((tg_cr_heading_of(s.R) - tg_cr_heading_of(sock.R)) + 540) % 360 - 180)
    return plans, gap, hd
end

-- ---------- start frame: always on the surface below you ----------
-- v2.2.0: building while flying / in no-clip used to leave the course floating in the air
function tg_cr_start_socket(ahead)
    local pos, heading = tg_get_local_position_heading("creator")
    heading = tonumber(heading or 0.0) or 0.0
    local fx, fy = calculate_new_position({ x = 0.0, y = 0.0, z = 0.0 }, heading, 1.0, 0.0, 0.0)
    local D = tg_tp_norm(tg_tp_v(fx, fy, 0.0))
    if TG_RS_TRY_YAW and TG_RS_TRY_YAW ~= 0 then
        local a = math.atan(D.y, D.x) + math.rad(TG_RS_TRY_YAW)
        D = tg_tp_v(math.cos(a), math.sin(a), 0.0)
    end
    local P = tg_tp_add(tg_tp_v(pos.x, pos.y, pos.z), tg_tp_mul(D, ahead or 14.0))
    TG_CR_CTX = { home = { x = pos.x, y = pos.y, z = pos.z } }
    -- first surface below you (or the ground if you're up in the air)
    local g = tg_cr_native_ground(P.x, P.y, pos.z + 3.0)
    if not g then g = tg_cr_ground(P.x, P.y) end
    P.z = g or (pos.z - 0.9)
    local R = { X = D, Y = tg_tp_norm(tg_tp_cross(tg_tp_v(0, 0, 1), D)), Z = tg_tp_v(0, 0, 1) }
    return { P = P, R = R }, pos
end

-- world score of a whole plan list (0 = clean)
function tg_cr_world_score(plans, ctx)
    local bad, worst = 0, nil
    for i, p in ipairs(plans) do
        local ok, why = tg_cr_world(p, ctx)
        if not ok then bad = bad + 1; worst = worst or why end
        if i % 4 == 0 and tg_rs_check_cancel() then return bad + 1, "cancelled" end
    end
    return bad, worst
end

-- ---------- approach ramp (v2.2.0 "Add ramp") ----------
-- From an open socket (pointing away from the course), lay straight pieces that tilt down on their
-- joints (the learned hinge: road up to ~10 deg, Stunt Track up to 5) until the deck reaches the
-- ground. Driving it the other way, you climb from the ground onto the raised course.
function tg_cr_plan_approach(sock, fam, avoid, ctx, parent)
    local straight = (fam == "road") and "stt_prop_track_straight_m" or ((fam == "dw") and "stt_prop_stunt_track_dwlink" or "stt_prop_stunt_track_straight")
    local first = (fam == "road") and "stt_prop_track_straight_s" or ((fam == "dw") and "stt_prop_stunt_track_dwshort" or "stt_prop_stunt_track_short")
    local maxp = (fam == "road") and 10.0 or 5.0
    local L = TG_CR_P[straight].len
    local seq = {}
    local all = {}
    for _, q in ipairs(avoid) do if q ~= parent then table.insert(all, q) end end
    local function push(p, bury)
        if not p then return false end
        if not tg_cr_clear(p, all, (#seq == 0) and 0.0 or nil) then return false end
        local ok = tg_cr_world(p, { bury = bury or 0.8, probes = ctx and ctx.probes })
        if not ok then return false end
        table.insert(seq, p); table.insert(all, p)
        return true
    end
    -- a flat piece first so the slope starts clear of the course's own deck
    if not push(tg_cr_place(sock, first, false, 0, 0), 0.8) then return nil end
    local s = seq[#seq].next
    for _ = 1, 4 do
        local ahead = tg_tp_add(s.P, tg_tp_mul(tg_tp_norm(tg_cr_flat(s.R.X)), L * 1.5))
        local g = tg_cr_ground(ahead.x, ahead.y) or tg_cr_ground(s.P.x, s.P.y)
        if not g then return nil end
        local h = s.P.z - g
        if h <= 0.6 then break end
        local k = math.max(1, math.ceil(h / (L * math.sin(math.rad(maxp)))))
        if #seq + k + 1 > 9 then return nil end
        local a = math.deg(math.asin(math.min(1.0, h / (k * L))))
        for i = 1, k do
            if not push(tg_cr_place(s, straight, false, 0, (i == 1) and -a or 0), (i == k) and 1.6 or 0.8) then return nil end
            s = seq[#seq].next
        end
        -- level out on the ground
        if not push(tg_cr_place(s, straight, false, 0, a), 1.6) then return nil end
        s = seq[#seq].next
    end
    -- the last deck must be at (or just above) the ground to drive onto
    local e = seq[#seq].next.P
    local ge = tg_cr_ground(e.x, e.y)
    if ge and (e.z - ge) > 1.2 then return nil end
    for _, p in ipairs(seq) do p.approach = true end
    return seq
end
-- v2.2.3 on-ramp: a flat piece on the ground, then straights tilted up on their joints, then a level
-- piece H metres up - the course starts at the top. Returns the pieces + the socket at the top.
function tg_cr_onramp(sock, fam, H, avoid, short)
    local flat = (fam == "road") and "stt_prop_track_straight_s" or ((fam == "dw") and "stt_prop_stunt_track_dwshort" or "stt_prop_stunt_track_short")
    local tilt = (fam == "road") and "stt_prop_track_straight_m" or ((fam == "dw") and "stt_prop_stunt_track_dwlink" or "stt_prop_stunt_track_straight")
    if short then tilt = flat end      -- v2.2.5 tight spot: short pieces, a shorter ramp
    local maxa = (fam == "road") and 8.0 or 5.0
    local L = TG_CR_P[tilt].len
    local k = math.max(1, math.ceil(H / (L * math.sin(math.rad(maxa)))))
    local a = math.deg(math.asin(math.min(1.0, H / (k * L))))
    local seq, all = {}, {}
    for _, q in ipairs(avoid or {}) do table.insert(all, q) end
    local s = sock
    local function push(m, hp, bury)
        local p = tg_cr_place(s, (fam == "road") and tg_cr_bar(m) or m, false, 0, hp)
        if not p then return false end
        if not tg_cr_clear(p, all) then return false end
        if not tg_cr_world(p, { bury = bury }) then return false end
        p.approach, p.onramp = true, true
        table.insert(seq, p); table.insert(all, p)
        s = p.next
        return true
    end
    -- the bottom sits a little into the ground so you drive straight on
    if not push(flat, 0, 1.2) then return nil end
    for i = 1, k do
        if not push(tilt, (i == 1) and a or 0, 1.2) then return nil end
    end
    if not push(tilt, -a, 0.8) then return nil end
    return seq, s
end
-- socket on one side port of a cross piece plan (side = +1 left, -1 right), pointing away
function tg_cr_cross_side(p, side)
    local pc = TG_CR_P[p.model]
    if not pc or not pc.side then return nil end
    local port = pc.side[(side > 0) and 1 or 2]
    local P = tg_tp_add(p.origin, tg_tp_apply(p.R, tg_tp_v(port[1], port[2], port[3])))
    local M = tg_cr_q2m(port[4], port[5], port[6], port[7])
    local R = tg_cr_mul(p.R, M)
    return { P = P, R = R }
end

-- ---------- loop builder (circuit, drift, sky loop, wide sky loop, Complete Loop) ----------
-- like the tube planner: many candidate loops, cheap ground pass first, the best few get the full
-- building probes, the best one wins
function tg_cr_plan_loop(L, budget, sock0, label)
    local best = nil
    local tries = 0
    local fam = L.fam
    local ramp = TG_CR.ramp
    local base_lifts
    if ramp then base_lifts = { 5.0, 6.5, 8.0, 10.0 }
    elseif fam == "road" then base_lifts = { 0.12, 3.0, 8.0, 15.0 }
    else base_lifts = { 0.12, 6.0 } end
    local scales = L.scales or { 1.0, 0.78, 0.58 }
    local per = L.per or 10
    local total = #scales * per
    for si, sc in ipairs(scales) do
        local b = math.max(12, math.floor(budget * sc))
        local cands = {}
        for attempt = 1, per do
            if tg_cr_time_up() then break end
            tg_rs_plan_progress(label, (L.try or 0) * total + (si - 1) * per + attempt, total * (L.tries or 1), 0, 1)
            local mirror = (math.random() < 0.5)
            local lift = base_lifts[1 + (attempt - 1) % #base_lifts]
            local LL = L
            -- the cross piece (a road junction) starts every raised loop - Stunt Track loops too, the
            -- official maps join road and Stunt Track pieces directly
            if ramp and lift > 1.2 then
                LL = {}
                for k, v in pairs(L) do LL[k] = v end
                LL.start_model, LL.start_twin = "stt_prop_track_cross", "stt_prop_track_cross"
            end
            local steps = tg_cr_loop_recipe(LL, b - ((ramp and lift > 1.2) and 6 or 0), mirror)
            if steps then
                local sock = { P = tg_tp_add(sock0.P, tg_tp_v(0, 0, lift)), R = sock0.R }
                local plans, gap, hd = tg_cr_run_steps(sock, steps, true)
                tries = tries + 1
                if plans and gap < 0.6 and hd < 1.0 then
                    local bad = tg_cr_world_score(plans, { bury = 0.8, near_start = true, start_P = sock.P, probes = false })
                    table.insert(cands, { plans = plans, cheap = bad, lift = lift, sock = sock, gap = gap, mirror = mirror })
                end
            end
            util.yield(0)
        end
        table.sort(cands, function(x, y) return (x.cheap * 100 + x.lift - #x.plans * 0.05) < (y.cheap * 100 + y.lift - #y.plans * 0.05) end)
        for i = 1, math.min(3, #cands) do
            local c = cands[i]
            local bad, why = tg_cr_world_score(c.plans, { bury = 0.8, near_start = true, start_P = c.sock.P })
            local approach = nil
            if c.lift > 1.2 and c.plans[1].model == "stt_prop_track_cross" then
                -- the approach comes in from the outside of the loop
                local side = c.mirror and 1 or -1
                for _, sd in ipairs({ side, -side }) do
                    local ss = tg_cr_cross_side(c.plans[1], sd)
                    if ss then approach = tg_cr_plan_approach(ss, "road", c.plans, {}, c.plans[1]) end
                    if approach then break end
                end
                if not approach then bad = bad + 1000 end
            end
            local score = bad * 100 + c.lift - #c.plans * 0.05
            if not best or score < best.score then
                best = { plans = c.plans, score = score, bad = bad, why = why, lift = c.lift, sock = c.sock, gap = c.gap, approach = approach, mirror = c.mirror }
            end
            if bad == 0 then return best, tries end
        end
    end
    return best, tries
end

-- ---------- point-to-point builder (stunt race, sky track, downhill, hybrid) ----------
function tg_cr_sprint_candidates(state, s)
    local fam = state.fam
    local V = state.V or {}
    local out = {}
    local pitch = tg_cr_pitch_of(s.R)
    local flat = math.abs(pitch) < 0.6
    for _, m in ipairs(TG_CR_SPRINT_MENU[fam] or {}) do
        local pc = TG_CR_P[m]
        if pc then
            local w = tg_cr_learned_w(state.learned, m)
            local k = pc.k
            local ok = true
            if fam == "road" then
                if (k == "bend" or k == "chicane") and not flat then ok = false end
                if k == "bendup" or k == "benddown" then ok = flat end
                if k == "up" and pitch > 25.0 then ok = false end
                local maxdown = state.downhill and (((V.steep or 1.0) >= 1.2) and 44.0 or ((V.steep or 1.0) >= 0.8) and 31.0 or 16.0) or 30.0
                if k == "down" and pitch < -maxdown then ok = false end
                if k == "down" and m:find("_d45", 1, true) and state.downhill and (V.steep or 1.0) < 1.2 then ok = false end
            end
            -- style knobs
            if k == "bend" or k == "chicane" then w = w * (V.twist or 1.0) end
            if k == "up" or k == "down" or k == "slope" or k == "drop" or k == "bendup" or k == "benddown" then w = w * (V.updown or 1.0) end
            if k == "feature" then w = w * (V.fx or 1.0) end
            if k == "straight" then
                local L = pc.len or 50
                if V.straight == "long" and L >= 80 then w = w * 1.8 elseif V.straight == "short" and L <= 55 then w = w * 1.6 end
            end
            -- learned hinge: a straight may tilt back to level on its joint (road up to 15 deg, Stunt Track 5)
            local hmax_h = (fam == "road") and 15.0 or 5.5
            if (k == "straight") and not flat and math.abs(pitch) <= hmax_h and w > 0 then
                table.insert(out, { m = (fam == "road") and tg_cr_bar(m) or m, rev = false, w = w * 1.5, k = k, hp = -pitch })
            end
            -- ... or tilt up / down from level to climb or drop (v2.2.1: real up and down)
            if k == "straight" and flat and w > 0 and (fam == "road" or fam == "stunt" or fam == "dw") then
                local a = (fam == "road") and (state.hinge or 7.0) or 4.5
                local wu = w * 1.6 * (V.updown or 1.0)
                table.insert(out, { m = (fam == "road") and tg_cr_bar(m) or m, rev = false, w = wu, k = "up", hp = a })
                table.insert(out, { m = (fam == "road") and tg_cr_bar(m) or m, rev = false, w = wu, k = "down", hp = -a })
            end
            if ok and w > 0 then
                local revs = { false }
                if math.abs(pc.turn) > 0.5 or k == "slope" or k == "drop" then revs = { false, true } end
                for _, r in ipairs(revs) do table.insert(out, { m = (fam == "road") and tg_cr_bar(m) or m, rev = r, w = w, k = k }) end
            end
        end
    end
    return out
end

function tg_cr_score_candidate(state, p, s)
    local V = state.V or {}
    local tt_placed = TG_TT_CR_LASTPLACED
    local score = math.log(1.0 + (state.cw or 1.0)) * 0.6 + math.random() * 1.2 * ((V.tt and V.tt.rk) or 1.0)
    local nP, nR = p.next.P, p.next.R
    local pitch = tg_cr_pitch_of(nR)
    local g = tg_cr_ground(nP.x, nP.y) or state.ref_ground
    -- height band; v2.2.0: the floor rises gradually from the ground (start on the ground, then climb)
    local hmin, hmax = state.hmin or 0.0, state.hmax or 120.0
    if state.rise and state.rise > 0 then hmin = math.min(hmin, state.rise * math.max(0, (state.n or 0) - (state.n0 or 0) - 2)) end
    if state.climb_to and (nP.z - (g or nP.z)) < state.climb_to then
        local cl = state.climb_to
        if state.rise and state.rise > 0 then cl = math.min(cl, state.rise * 1.6 * math.max(0, (state.n or 0) - (state.n0 or 0) - 1)) end
        hmin = math.max(hmin, cl)
    end
    if g then
        local h = nP.z - g
        if h < hmin then score = score - (hmin - h) * 0.05 - ((p.k == "up" or (p.k == "slope" and not p.rev)) and -1.5 or 0) end
        if h > hmax then score = score - (h - hmax) * 0.04 + ((p.k == "down" or (p.k == "slope" and p.rev)) and 1.2 or 0) end
    end
    -- v2.2.1: follow the course's height profile (0 at the start, waves up and down, back to the ground)
    if state.profile and g and not state.downhill then
        local tgt = state.profile((state.n or 0) + 1, state.left)
        local h = nP.z - g
        -- v2.2.6 weave mode (like the tubes): rise over the buildings ahead instead of stopping
        if state.weave then
            local fx2 = tg_cr_flat(nR.X)
            if tg_tp_len(fx2) > 0.1 then
                fx2 = tg_tp_norm(fx2)
                local top = g
                for _, ahead in ipairs({ 40.0, 80.0, 120.0 }) do
                    local q = tg_tp_add(nP, tg_tp_mul(fx2, ahead))
                    local ga = tg_cr_ground(q.x, q.y)
                    if ga and ga > top then top = ga end
                end
                if top - g > 3.0 then tgt = math.max(tgt, top - g + 8.0) end
            end
        end
        score = score - math.min(5.0, math.abs(h - tgt) * 0.07)
        local climb = nR.X.z
        if h < tgt - 3.0 and climb > 0.03 then score = score + 1.2 end
        if h > tgt + 4.0 and climb < -0.03 then score = score + 1.2 end
    end
    if state.downhill and not state.climb_to then
        if p.k == "down" or (p.k == "slope" and p.rev) then score = score + 1.0 * (V.steep or 1.0) end
        if p.k == "up" then score = score - 1.5 end
    end
    -- look ahead: ground rising in front of the deck -> climb or turn now, not when it's too late
    local fx = tg_cr_flat(nR.X)
    if tg_tp_len(fx) > 0.1 then
        fx = tg_tp_norm(fx)
        for _, ahead in ipairs({ 70.0, 150.0 }) do
            local q = tg_tp_add(nP, tg_tp_mul(fx, ahead))
            local ga = tg_cr_ground(q.x, q.y)
            if ga then
                local clear = nP.z + nR.X.z * ahead - ga
                if clear < 4.0 then score = score - math.min(6.0, (4.0 - clear) * 0.06) * ((ahead < 100) and 1.0 or 0.6) end
            end
        end
    end
    -- level out after climbs/drops, firmly near the end or after a few tilted pieces in a row
    if math.abs(pitch) > 1.0 then
        local firm = ((state.left or 99) < 6) or ((state.tilted or 0) >= 3) or state.want_flat
        score = score - math.abs(pitch) * (firm and 0.25 or 0.03)
    end
    -- goal steering
    if state.goal then
        local to = tg_cr_flat(tg_tp_sub(state.goal, nP))
        local d = tg_tp_len(to)
        local f = tg_cr_flat(nR.X)
        if d > 1 and tg_tp_len(f) > 0.1 then
            local c = tg_tp_dot(tg_tp_norm(to), tg_tp_norm(f))
            score = score + c * ((state.returning and 2.2) or (TG_CR.across and 1.8) or 0.8)
        end
    else
        local away = tg_tp_len(tg_cr_flat(tg_tp_sub(nP, state.home)))
        if away > (state.radius or 700.0) then
            local to = tg_tp_norm(tg_cr_flat(tg_tp_sub(state.home, nP)))
            score = score + tg_tp_dot(to, tg_tp_norm(tg_cr_flat(nR.X))) * 1.5
        end
    end
    local turn = (p.rev and -1 or 1) * ((TG_CR_P[p.model] and TG_CR_P[p.model].turn) or 0)
    if math.abs(turn) > 1 then
        local sgn = (turn > 0) and 1 or -1
        if state.last_turn_sign == sgn then score = score - 0.6 * (state.same_turns or 1) end
    end
    if p.model == state.last_model then score = score - 0.5 end
    if math.abs(turn) > 170 then
        score = score - 1.0 / math.max(0.3, V.hair or 1.0)
        if (state.since_hairpin or 99) < 6 then score = score - 3.0 end
    end
    if V.drift_style and tg_cr_drift_score then score = tg_cr_drift_score(V, state, p, score) end
    if V.tt and tg_tt_cr_score then score = tg_tt_cr_score(V.tt, state, p, s, score, tt_placed) end
    return score
end

-- Hybrid flavours: each section of a hybrid course borrows one category's character
TG_CR_HY_FLAVOURS = {
    { cat = "stunt", fam = "road", learned = "stunt", hmin = 0, hmax = 90, V = { twist = 1.0, updown = 1.2, jumps = 1.4, pads = 1.0 } },
    { cat = "circuit", fam = "road", learned = "circuit", hmin = 0, hmax = 30, V = { twist = 1.2, updown = 0.4, jumps = 0.6, pads = 0.6 } },
    { cat = "drift", fam = "road", learned = "drift", hmin = 0, hmax = 25, V = { twist = 2.2, updown = 0.2, jumps = 0.0, pads = 0.0, hair = 1.4 } },
    { cat = "downhill", fam = "road", learned = "downhill", hmin = 0, hmax = 200, downhill = true, V = { twist = 0.8, updown = 1.6, steep = 1.2, jumps = 1.2, pads = 1.6 } },
    { cat = "sky", fam = "stunt", learned = "sky", hmin = 10, hmax = 110, V = { twist = 1.1, updown = 1.0, fx = 1.4 } },
    { cat = "widesky", fam = "dw", learned = "sky", hmin = 10, hmax = 90, V = { twist = 0.9, updown = 1.0 } },
    { cat = "wipeout", fam = "road", learned = "stunt", hmin = 0, hmax = 60, hop = true, V = { twist = 0.6, updown = 0.6, jumps = 3.0 } },
}

-- v2.2.6 weave mode: start sockets in front of you where a first piece actually fits - straight
-- ahead first, then a little further / to either side of the road, then turned headings
function tg_cr_weave_starts(sock0, fam, turns)
    local probe = (fam == "road") and "stt_prop_track_straight_bar_s" or ((fam == "dw") and "stt_prop_stunt_track_dwshort" or "stt_prop_stunt_track_short")
    local D0 = tg_tp_norm(tg_cr_flat(sock0.R.X))
    local L0 = tg_tp_v(-D0.y, D0.x, 0)
    local zref = (TG_CR_CTX and TG_CR_CTX.home and TG_CR_CTX.home.z) or sock0.P.z
    local out = {}
    for _, t in ipairs(turns) do
        for _, ahead in ipairs({ 0.0, 10.0, 22.0 }) do
            for _, lat in ipairs({ 0.0, -7.0, 7.0, -14.0, 14.0 }) do
                local P = tg_tp_add(sock0.P, tg_tp_add(tg_tp_mul(D0, ahead), tg_tp_mul(L0, lat)))
                local g = tg_cr_native_ground(P.x, P.y, zref + 3.0) or tg_cr_ground(P.x, P.y)
                if g then
                    P.z = g
                    local sk = { P = P, R = tg_cr_frame(tg_cr_heading_of(sock0.R) + t) }
                    local p = tg_cr_place(sk, probe, false, 0, 0)
                    if p and tg_cr_world(p, { bury = 1.2, probes = false, edge = 0.85 }) then
                        table.insert(out, { sk = sk, cost = math.abs(t) * 0.4 + ahead + math.abs(lat) * 1.5 })
                    end
                end
            end
        end
    end
    table.sort(out, function(a, b) return a.cost < b.cost end)
    local socks = {}
    for i = 1, math.min(24, #out) do socks[i] = out[i].sk end
    tg_cr_diag(string.format("weave starts: %d spots in front of you fit a first piece", #out))
    return socks
end
function tg_cr_plan_sprint(S, budget, sock0, home, label)
    local best, best_score = nil, nil
    local fam = S.fam
    local starts = (fam == "road") and { "stt_prop_track_start", "stt_prop_track_start", "stt_prop_track_straight_m", "stt_prop_track_straight_s" }
                   or (fam == "dw") and { "stt_prop_stunt_track_dwlink", "stt_prop_stunt_track_dwlink_02", "stt_prop_stunt_track_dwshort", "stt_prop_stunt_track_dwshort" }
                   or { "stt_prop_stunt_track_start_02", "stt_prop_stunt_track_start_02", "stt_prop_stunt_track_short", "stt_prop_stunt_track_exshort" }
    local attempts = S.attempts or 3
    local turns = { 0, 35, -35, 70, -70, 110, -110, 180 }
    -- v2.2.6 weave mode: the course always starts in front of you - only headings that point ahead/sideways
    local wsocks = nil
    if S.weave then
        turns = { 0 }
        for a = 10, 100, 10 do table.insert(turns, a); table.insert(turns, -a) end
        wsocks = tg_cr_weave_starts(sock0, fam, turns)
        if #wsocks == 0 then return nil end
        turns = {}
        for i = 1, #wsocks do turns[i] = 0 end
    end
    local fails = 0
    local attempt = 0
    while attempt < attempts and fails < #turns and not tg_cr_time_up() do
        attempt = attempt + 1
        local sk = sock0
        if wsocks then sk = wsocks[fails + 1]
        elseif fails > 0 then sk = { P = sock0.P, R = tg_cr_frame(tg_cr_heading_of(sock0.R) + turns[fails + 1]) } end
        -- a blocked start also tries the shorter start pieces (v2.2.5: adapts to tight spots)
        local plans, extra = tg_cr_plan_sprint_once(S, budget, sk, home, starts[((attempt + fails - 1 + (S.short_start and 2 or 0)) % #starts) + 1], label, attempt, attempts)
        local need = 3
        if S.weave then
            -- weave mode: a stub that got stuck right away doesn't count - try the next start spot
            need = 3
            local n = 0
            for _, p in ipairs(plans or {}) do if not p.approach and not p.pseudo then n = n + 1 end end
            if n < 6 then plans = nil end
        end
        if not plans or #plans < need then fails = fails + 1; attempt = attempt - 1 end
        if plans and #plans >= need then
            -- tube-style pick: longest, most varied, cleanest
            local models = {}
            local nm = 0
            for _, p in ipairs(plans) do if not models[p.model] then models[p.model] = true; nm = nm + 1 end end
            local sc = (#plans / math.max(1, budget)) * 100 + nm * 0.8 + ((extra and extra.jumps) or 0) * 1.5
                       + ((extra and extra.closed) and 60 or 0) - ((extra and extra.no_onramp) and 30 or 0)
            if not best or sc > best_score then best, best_score = { plans = plans, extra = extra }, sc end
            if #plans >= budget * 0.92 and attempt >= 2 then break end
        end
    end
    if not best then return nil end
    return best.plans, best.extra
end

function tg_cr_plan_sprint_once(S, budget, sock0, home, start_model, label, attempt, attempts)
    local V = S.V or {}
    local state = { weave = S.weave, home = home, radius = TG_CR.across and 2600.0 or 650.0, same_turns = 0, V = V, fam = S.fam,
                    learned = S.learned, hmin = S.hmin or 0.0, hmax = V.hmax or S.hmax or 120.0, rise = S.rise, downhill = S.downhill, n = 0 }
    if S.return_home then state.radius = 320.0 end
    if TG_CR_RADIUS then state.radius = math.min(state.radius, TG_CR_RADIUS.r * 0.55) end
    if TG_CR.across or TG_CR.oneway then
        local h = tg_cr_heading_of(sock0.R) + (-60 + math.random() * 120)
        local d = TG_CR.across and (1800 + math.random() * 1700) or math.min(1100.0, 250.0 + budget * 9.0 * (0.7 + math.random() * 0.6))
        if TG_CR_RADIUS then d = math.min(d, TG_CR_RADIUS.r * 0.8) end
        state.goal = tg_tp_add(sock0.P, tg_tp_v(math.cos(math.rad(h)) * d, math.sin(math.rad(h)) * d, 0))
    end
    if S.downhill then
        local cl = V.climb or { 70, 160 }
        state.climb_to = cl[1] + math.random() * math.max(0, (cl[2] or cl[1]) - cl[1])
        state.rise = state.rise or 6.0
    end
    -- v2.2.1 height profile: starts on the ground like the tube races, rises and falls in waves, and
    -- comes back down to the ground for the finish
    if not S.downhill then
        local amp = S.prof_amp or math.max(20.0, math.min(80.0, (state.hmax or 120.0) * 0.5)) * math.max(0.7, math.min(1.8, (V.updown or 1.0) * 1.3))
        local per = 7 + math.random(0, 6)
        local base = state.hmin or 0.0
        state.prof_amp = amp
        state.profile = function(n, left)
            local n0 = state.prefix or 0
            if n < n0 + 2 then return state.start_h or 0.0 end
            local t = math.max(state.start_h or 0.0, (state.prof_base or base)) + state.prof_amp * (0.5 - 0.5 * math.cos(2.0 * math.pi * (n - n0 - 2) / per))
            if state.rise and state.rise > 0 then t = math.min(t, state.rise * (n - (state.n0 or 0) - 1)) end
            if left and left < 8 then t = t * math.max(0.0, (left - 2) / 6.0) end
            return t
        end
        state.hinge = 6.0 + math.random() * 4.0
    end
    -- hybrid: sections that switch flavour (and piece family) as the course goes
    local sections = S.hybrid and true or false
    local section_end = sections and (6 + math.random(0, 4)) or 1e9
    local flav = nil
    local function set_flavour(F)
        flav = F
        state.V, state.learned, state.hmin, state.hmax, state.downhill = F.V, F.learned, F.hmin, F.hmax, F.downhill
        state.hop = F.hop
        if F.downhill then state.climb_to = state.climb_to or (40 + math.random() * 40) else state.climb_to = nil end
        state.rise = (F.fam ~= "road") and 4.0 or nil
        state.prof_amp = math.max(14.0, math.min(60.0, (F.hmax or 60) * 0.4))
        state.prof_base = F.hmin or 0.0
    end
    local plans = {}
    local s = sock0
    state.ref_ground = tg_cr_ground(sock0.P.x, sock0.P.y) or sock0.P.z
    -- v2.2.3: every course starts with an on-ramp off the ground (Add Ramp)
    state.prefix = 0
    if TG_CR.ramp then
        local H = (state.fam == "road") and (4.5 + math.random() * 2.0) or (5.5 + math.random() * 2.0)
        if S.short_start then H = (state.fam == "road") and 3.0 or 3.2 end     -- v2.2.5: tight spot - a shorter ramp
        local seq, top = tg_cr_onramp(sock0, state.fam, H, {}, S.short_start)
        if not seq and S.weave then
            -- no straight run for a ramp in front of you: the course starts flat on the ground and
            -- climbs gradually on its own pieces, turning wherever it has to (like the tubes)
            seq, top = {}, sock0
            state.no_onramp = true
        end
        if not seq then return nil end
        for _, q in ipairs(seq) do table.insert(plans, q) end
        s = top
        state.prefix = #seq
        state.n0 = #seq
        state.start_h = H
    end
    -- on a slope the start deck follows the ground (learned hinge, up to 10 deg)
    local sm = start_model or TG_CR_START[state.fam]
    local spitch = 0.0
    if state.fam == "road" and TG_CR_P[sm] then
        local Ls = TG_CR_P[sm].len or 50
        local D0 = tg_tp_norm(tg_cr_flat(sock0.R.X))
        local ge = tg_cr_ground(sock0.P.x + D0.x * Ls, sock0.P.y + D0.y * Ls)
        if ge then
            spitch = math.deg(math.atan((ge - sock0.P.z) / Ls))
            if math.abs(spitch) < 1.5 then spitch = 0.0 end
            spitch = math.max(-10.0, math.min(10.0, spitch))
        end
    end
    if state.prefix > 0 then spitch = 0.0 end
    local first = tg_cr_place(s, sm, false, 0, spitch)
    if not first then return nil end
    if state.prefix > 0 and (not tg_cr_clear(first, plans) or not tg_cr_world(first, { bury = 0.8 })) then return nil end
    -- v2.2.6: a start on the ground is checked too (buildings, walls) - never through a building
    if state.prefix == 0 and not tg_cr_world(first, { bury = 1.2, near_start = true, start_P = sock0.P, edge = S.weave and 0.85 or nil }) then return nil end
    table.insert(plans, first); s = first.next
    local ctx = { bury = 0.8, near_start = true, start_P = sock0.P, edge = S.weave and 0.85 or nil }
    local cheap = { bury = 0.8, near_start = true, start_P = sock0.P, probes = false, edge = S.weave and 0.85 or nil }
    local backtracks = 0
    local relax = 0
    local tried = {}
    local jumps_left = (TG_CR.jumps and (state.fam == "road" or sections)) and math.max(0, math.floor((budget / 18) * (V.jumps or 1.0) + 0.5)) or 0
    if sections then jumps_left = math.max(2, jumps_left) end
    local njumps, nhops = 0, 0
    local decor_extra = {}
    while #plans < budget do
        if tg_cr_time_up() then break end
        tg_rs_plan_progress(label, math.max(1, attempt or 1), attempts or 1, #plans, budget)
        state.n = #plans
        -- v2.2.6 return course (Smart Random Loop style): explore, then steer back and finish near the start
        if S.return_home then
            local np = #plans - (state.prefix or 0)
            if not state.returning and np >= math.max(8, math.floor(budget * 0.45)) then
                state.returning = true
                state.goal = sock0.P
            end
            if state.returning then
                local dh = tg_tp_len(tg_cr_flat(tg_tp_sub(sock0.P, s.P)))
                state.home_left = math.ceil(dh / 40.0) + 2
                if dh < 80.0 and np >= 10 then state.closed = true; break end
            end
        end
        if state.goal and not state.returning and tg_tp_len(tg_cr_flat(tg_tp_sub(state.goal, s.P))) < 150.0 then
            if #plans >= budget * 0.85 then break end
            local f = tg_tp_norm(tg_cr_flat(s.R.X))
            local h = math.deg(tg_atan2_safe(f.y, f.x)) + (-50 + math.random() * 100)
            local d = TG_CR.across and 1500.0 or 600.0
            if TG_CR_RADIUS then
                d = TG_CR_RADIUS.r * 0.6
                h = math.deg(tg_atan2_safe(TG_CR_RADIUS.y - s.P.y, TG_CR_RADIUS.x - s.P.x)) + (-60 + math.random() * 120)
            end
            state.goal = tg_tp_add(s.P, tg_tp_v(math.cos(math.rad(h)) * d, math.sin(math.rad(h)) * d, 0))
        end
        if state.climb_to then
            local g = tg_cr_ground(s.P.x, s.P.y)
            if g and (s.P.z - g) >= state.climb_to and math.abs(tg_cr_pitch_of(s.R)) < 0.6 then state.climb_to = nil end
        end
        -- hybrid section switch (only on a level deck)
        if sections then
            state.want_flat = (#plans >= section_end - 1)
            if #plans >= section_end and math.abs(tg_cr_pitch_of(s.R)) < 0.6 then
                local opts = {}
                for _, F in ipairs(TG_CR_HY_FLAVOURS) do if F ~= flav then table.insert(opts, F) end end
                local F = opts[math.random(#opts)]
                local sw_ok = true
                if F.fam ~= state.fam then
                    local m = TG_CR_SWITCH[state.fam][F.fam]
                    local p = m and tg_cr_place(s, m, false, 0, 0)
                    if p and tg_cr_clear(p, plans) and tg_cr_world(p, ctx) then
                        p.k = TG_CR_P[m].k
                        table.insert(plans, p); s = p.next
                        state.fam = F.fam
                    else sw_ok = false end
                end
                if sw_ok then
                    set_flavour(F)
                    state.n0 = #plans
                    if F.hop then jumps_left = jumps_left + 2 end
                end
                section_end = #plans + 6 + math.random(0, 5)
                state.want_flat = false
            end
        end
        local key = #plans
        state.left = budget - #plans
        if state.home_left then state.left = math.min(state.left, state.home_left) end
        tried[key] = tried[key] or {}
        local cands = tg_cr_sprint_candidates(state, s)
        local scored = {}
        for _, c in ipairs(cands) do
            local id = c.m .. (c.rev and "r" or "f") .. (c.hp and string.format("h%.1f", c.hp) or "")
            if not tried[key][id] then
                local p = tg_cr_place(s, c.m, c.rev, 0, c.hp or 0)
                if p and tg_cr_clear(p, plans) then
                    state.cw = c.w
                    p.k = c.k
                    table.insert(scored, { p = p, sc = tg_cr_score_candidate(state, p, s), id = id })
                end
            end
        end
        table.sort(scored, function(a, b) return a.sc > b.sc end)
        local chosen = nil
        for i = 1, math.min(5, #scored) do
            local c = scored[i]
            tried[key][c.id] = true
            -- cheap ground check first; the collision probes only for the one we'd take
            if tg_cr_world(c.p, cheap) then
                local look = tg_cr_place(c.p.next, TG_CR_STRAIGHTS[state.fam][2], false, 0, 0)
                local tmp = {}
                for j = 1, #plans do tmp[j] = plans[j] end
                tmp[#tmp + 1] = c.p
                if look and tg_cr_clear(look, tmp) and tg_cr_world(c.p, ctx) then chosen = c.p; break end
            end
        end
        if chosen then
            local pc = TG_CR_P[chosen.model]
            -- jump: a ramp on a flat straight with its lip at the end, a gap, and a long landing deck
            -- (Wipeout flavour: land on a floating platform with obstacles, ramp off its far edge)
            if jumps_left > 0 and state.fam == "road" and pc.k == "straight" and (pc.len or 0) >= 50 and math.abs(tg_cr_pitch_of(chosen.next.R)) < 0.6
               and #plans > 3 and #plans < budget - 6 and math.random() < (state.hop and 0.8 or 0.35) then
                local ramp = ({ "stt_prop_track_jump_01a", "stt_prop_track_jump_01a", "stt_prop_track_jump_02a", "stt_prop_track_jump_01b" })[math.random(4)]
                local gap = (ramp == "stt_prop_track_jump_01b") and (55 + math.random() * 20) or (34 + math.random() * 16)
                local drop = 2.0 + math.random() * 6.0
                local F = chosen.next.R.X
                local Fh = tg_tp_norm(tg_cr_flat(F))
                local tmp = {}
                for j = 1, #plans do tmp[j] = plans[j] end
                tmp[#tmp + 1] = chosen
                local done = false
                if state.hop and #plans < budget - 10 then
                    -- platform hop: ramp -> platform -> ramp -> landing deck
                    local pm = "stt_prop_stunt_bblock_huge_02"
                    local bx, by = tg_cr_bbdims(pm)
                    local plen, pwid = by, bx
                    local g1 = 22 + math.random() * 10
                    local C = tg_tp_add(chosen.next.P, tg_tp_add(tg_tp_mul(Fh, g1 + plen * 0.5), tg_tp_v(0, 0, -drop)))
                    local pseudo = tg_cr_pseudo(C, Fh, plen, pwid)
                    local g2 = 26 + math.random() * 10
                    local land = { P = tg_tp_add(C, tg_tp_add(tg_tp_mul(Fh, plen * 0.5 + g2), tg_tp_v(0, 0, -(1.0 + math.random() * 3.0)))), R = { X = Fh, Y = tg_tp_v(-Fh.y, Fh.x, 0), Z = tg_tp_v(0, 0, 1) } }
                    local lp = tg_cr_place(land, tg_cr_bar("stt_prop_track_straight_lm"), false, 0, 0)
                    local okp = tg_cr_clear(pseudo, tmp, 0.0) and tg_cr_world(pseudo, cheap)
                    if okp then
                        local tmp2 = {}
                        for j = 1, #tmp do tmp2[j] = tmp[j] end
                        tmp2[#tmp2 + 1] = pseudo
                        okp = lp and tg_cr_clear(lp, tmp2, 0.0) and tg_cr_world(lp, ctx)
                    end
                    if okp then
                        chosen.jump = { ramp = ramp, gap = g1, drop = drop }
                        table.insert(plans, chosen)
                        pseudo.hop = { model = pm, C = C, D = Fh, len = plen, wid = pwid, ramp = "stt_prop_ramp_jump_l" }
                        table.insert(plans, pseudo)
                        lp.landing = true
                        table.insert(plans, lp)
                        s = lp.next
                        jumps_left = jumps_left - 1
                        nhops = nhops + 1
                        chosen = nil
                        done = true
                    end
                end
                if not done then
                    local land = { P = tg_tp_add(chosen.next.P, tg_tp_add(tg_tp_mul(F, gap), tg_tp_v(0, 0, -drop))), R = chosen.next.R }
                    local lp = tg_cr_place(land, tg_cr_bar("stt_prop_track_straight_lm"), false, 0, 0)
                    if lp and tg_cr_clear(lp, tmp, 0.0) and tg_cr_world(lp, ctx) then
                        chosen.jump = { ramp = ramp, gap = gap, drop = drop }
                        table.insert(plans, chosen)
                        lp.landing = true
                        table.insert(plans, lp)
                        s = lp.next
                        jumps_left = jumps_left - 1
                        njumps = njumps + 1
                        chosen = nil
                    end
                end
            end
            if chosen then
                table.insert(plans, chosen)
                s = chosen.next
            end
            tried[#plans] = nil
            local last = plans[#plans]
            local turn = (last.rev and -1 or 1) * ((TG_CR_P[last.model] and TG_CR_P[last.model].turn) or 0)
            if math.abs(turn) > 1 then
                local sgn = (turn > 0) and 1 or -1
                if state.last_turn_sign == sgn then state.same_turns = state.same_turns + 1 else state.same_turns = 1 end
                state.last_turn_sign = sgn
            end
            state.last_model = last.model
            if math.abs(tg_cr_pitch_of(last.next.R)) > 1.0 then state.tilted = (state.tilted or 0) + 1 else state.tilted = 0 end
            if math.abs(turn) > 170 then state.since_hairpin = 0 else state.since_hairpin = (state.since_hairpin or 99) + 1 end
        else
            backtracks = backtracks + 1
            if backtracks == 30 then TG_CR_PROBE_FLAGS_CUR = TG_CR_PROBE_FLAGS_RELAXED end
            local stuck = (backtracks > 70) or (#plans <= (state.prefix or 0) + 1)
            if stuck and relax < 2 then
                -- v2.2.2: don't give up in a built-up spot - first ignore lamp posts / trees / walls
                -- (the collision probes), then allow more ground contact, and carry on from here
                relax = relax + 1
                if relax == 1 then TG_CR_PROBE_FLAGS_CUR = TG_CR_PROBE_FLAGS_RELAXED     -- ignore lamp posts / trees, never buildings
                else ctx.bury, cheap.bury = 1.5, 1.5 end
                tried, backtracks = {}, 0
                state.relaxed = relax
            elseif stuck then
                break
            else
            local back = math.min(#plans - 1 - (state.prefix or 0), (backtracks % 5 == 0) and 3 or 1)
            for _ = 1, back do
                tried[#plans] = nil
                local rem = table.remove(plans)
                if rem and rem.landing then
                    local r2 = table.remove(plans)
                    if r2 and r2.pseudo then table.remove(plans) end
                end
            end
            if #plans == 0 then break end
            s = plans[#plans].next
            -- family follows the deck we're back on
            local lf = plans[#plans].f
            if lf == "road" or lf == "stunt" or lf == "dw" then state.fam = lf end
            end
        end
    end
    -- level out at the end if we're still tilted (a road can't end mid-slope)
    local function level_out(base)
        local seq, ss = {}, base.next
        for _ = 1, 4 do
            local pitch = tg_cr_pitch_of(ss.R)
            if math.abs(pitch) <= 0.6 then return seq end
            local want = (pitch > 0) and "sr_prop_track_straight_l_d" or "sr_prop_track_straight_l_u"
            local m = nil
            for _, a in ipairs({ 45, 30, 15, 5 }) do
                if not m and a <= math.abs(pitch) + 0.8 then m = want .. a end
            end
            if not m then return nil end
            local p = tg_cr_place(ss, m, false, 0, 0)
            local tmp = {}
            for j = 1, #plans do tmp[j] = plans[j] end
            for _, q in ipairs(seq) do tmp[#tmp + 1] = q end
            if not p or not tg_cr_clear(p, tmp) or not tg_cr_world(p, ctx) then return nil end
            table.insert(seq, p); ss = p.next
        end
        return (math.abs(tg_cr_pitch_of(ss.R)) <= 0.6) and seq or nil
    end
    while #plans > 2 and plans[#plans].f == "road" do
        if math.abs(tg_cr_pitch_of(plans[#plans].next.R)) <= 0.6 then break end
        local seq = level_out(plans[#plans])
        if seq then for _, q in ipairs(seq) do table.insert(plans, q) end; break end
        local rem = table.remove(plans)
        if rem and rem.landing then
            local r2 = table.remove(plans)
            if r2 and r2.pseudo then table.remove(plans) end
        end
    end
    -- a course must never end on a take-off ramp or a platform
    while #plans > 2 and (plans[#plans].jump or plans[#plans].pseudo) do table.remove(plans) end
    return plans, { jumps = njumps, hops = nhops, relaxed = relax, closed = state.closed, no_onramp = state.no_onramp }
end

-- ---------- wipeout (learned from Wipeout Course, Deadline Duet I-III, BSR-Jump, GTAMaps mk9) ----------
TG_CR_WO_SETS = {
    huge = { "stt_prop_stunt_bblock_huge_01", "stt_prop_stunt_bblock_huge_02", "stt_prop_stunt_bblock_huge_01", "stt_prop_stunt_bblock_huge_03" },
    small = { "stt_prop_stunt_bblock_xl3", "stt_prop_stunt_bblock_lrg3", "stt_prop_stunt_bblock_xl3", "stt_prop_stunt_bblock_huge_01" },
    mixed = { "stt_prop_stunt_bblock_huge_01", "stt_prop_stunt_bblock_huge_02", "stt_prop_stunt_bblock_xl3", "stt_prop_stunt_bblock_huge_03" },
}
TG_CR_WO_OBST = {
    ball = { m = "stt_prop_stunt_soccer_lball", dyn = true, lift = 0.0 },
    tyre = { m = "xs_prop_arrow_tyre_01a", slalom = true },
    flip = { m = "xs_prop_arena_flipper_large_01a_sf" },
    turn = { m = "xs_prop_arena_turntable_02a" },
    wall = { m = "xs_prop_arena_wall_rising_01a_sf" },
    fire = { m = "xs_prop_arena_pit_fire_01a_sf" },
    spike = { m = "xs_prop_arena_spikes_02a" },
    pin = { m = "stt_prop_stunt_bowling_pin", dyn = true },
    hump = { m = "stt_prop_stunt_bblock_hump_01", big = true },
    wride = { m = "stt_prop_wallride_45l", big = true },
}
function tg_cr_bbdims(m)
    local bb = TG_CR_BB[m]
    if not bb then return 10, 10, 1 end
    return bb[4] - bb[1], bb[5] - bb[2], bb[6] - bb[3]
end
function tg_cr_rect_overlap(a, b)
    local function axes(r) return { r.D, tg_tp_v(-r.D.y, r.D.x, 0) } end
    local function proj(r, ax)
        local c = r.C.x * ax.x + r.C.y * ax.y
        local e = math.abs(r.D.x * ax.x + r.D.y * ax.y) * r.len * 0.5 + math.abs(-r.D.y * ax.x + r.D.x * ax.y) * r.wid * 0.5
        return c - e, c + e
    end
    for _, r in ipairs({ a, b }) do
        for _, ax in ipairs(axes(r)) do
            local a1, a2 = proj(a, ax)
            local b1, b2 = proj(b, ax)
            if a2 < b1 or b2 < a1 then return false end
        end
    end
    return true
end
-- obstacles on one platform q (centre C, direction D, len, wid)
function tg_cr_wo_obstacles(items, q, V, room, dynref)
    local wts = {}
    for k, w in pairs((V and V.obst) or { ball = 3, tyre = 3, flip = 2, turn = 2, wall = 2, fire = 2, spike = 1, pin = 2, hump = 1, wride = 1 }) do
        if TG_CR_WO_OBST[k] then table.insert(wts, { k = k, w = w }) end
    end
    table.sort(wts, function(a, b) return a.k < b.k end)
    local count = 0
    local n_obs = (q.len > 60) and 3 or (q.len > 40) and 2 or 1
    local L = tg_tp_v(-q.D.y, q.D.x, 0)
    for k = 1, n_obs do
        if count >= room or #wts == 0 then break end
        local o = TG_CR_WO_OBST[tg_cr_pick_w(wts).k]
        if o.dyn and dynref.n >= 6 then o = TG_CR_WO_OBST.tyre end
        if o.big and q.wid < 30 then o = TG_CR_WO_OBST.flip end
        local along = -q.len * 0.25 + (k - 0.5) * (q.len * 0.5 / n_obs)
        local lat = (math.random() - 0.5) * (q.wid * 0.5)
        local at = tg_tp_add(tg_tp_add(q.C, tg_tp_mul(q.D, along)), tg_tp_mul(L, lat))
        if o.slalom then
            for j = -1, 1 do
                if count < room then
                    table.insert(items, { decor = true, model = o.m, P = tg_tp_add(tg_tp_add(q.C, tg_tp_mul(q.D, along)), tg_tp_mul(L, j * (q.wid * 0.28))), yaw = tg_normalize_heading(q.h + 90 * ((j % 2 == 0) and 1 or -1)), lift = 0.0, pitch = 0, tint = q.tint })
                    count = count + 1
                end
            end
        else
            table.insert(items, { decor = true, model = o.m, P = at, yaw = tg_normalize_heading(q.h + math.random(0, 3) * 90), lift = o.lift or 0.0, pitch = 0, dynamic = o.dyn })
            count = count + 1
            if o.dyn then dynref.n = dynref.n + 1 end
        end
    end
    return count
end
-- loop = true: the platforms circle round and finish beside the start (Complete Loop)
function tg_cr_plan_wipeout(budget, sock0, home, V, loop, label)
    V = V or {}
    local items, cps = {}, {}
    local heading = tg_cr_heading_of(sock0.R)
    local h0 = heading
    local P = tg_tp_v(sock0.P.x, sock0.P.y, sock0.P.z + 0.25)
    local set = TG_CR_WO_SETS[V.plats or "huge"] or TG_CR_WO_SETS.huge
    local gap_lo, gap_hi = (V.gap and V.gap[1]) or 7, (V.gap and V.gap[2]) or 15
    local rise, hmax = V.rise or 3.0, V.hmax or 25
    local ramp_kind = V.ramp or "mix"
    local placed_rects = {}
    local dynref = { n = 0 }
    local count = 0
    local plat_i = 0
    local turned = 0.0
    -- v2.2.3 "Add ramp": a road on-ramp climbs off the ground and runs straight onto the first platform
    local entry, ramp_seq = nil, nil
    if TG_CR.ramp and budget >= 12 then
        local seq, top = tg_cr_onramp(sock0, "road", 3.5 + math.random() * 1.5, {})
        if not seq then return {}, {}, nil, nil end
        ramp_seq = seq
        entry = seq[#seq]
        count = count + #seq
        P = tg_tp_v(top.P.x, top.P.y, top.P.z + 0.17)
        heading = tg_cr_heading_of(top.R)
        table.insert(cps, { P = tg_tp_add(seq[1].inP, tg_tp_v(0, 0, 1.5)), psi = math.rad(heading), island = 0 })
    end
    while count < budget - 3 do
        if tg_rs_check_cancel() then return nil, "cancelled" end
        tg_rs_plan_progress(label or "Wipeout", 1, 1, count, budget)
        plat_i = plat_i + 1
        local m = (plat_i == 1) and "stt_prop_stunt_bblock_huge_02" or set[math.random(#set)]
        local wx, wy = tg_cr_bbdims(m)
        local len, wid = wy, wx
        local ok_plat = nil
        -- Complete Loop: steer round in a circle (about 300 deg over the course) and back home
        local bias = 0
        if loop then
            local frac = count / math.max(1, budget)
            bias = (frac > 0.15) and 32 or 0
            if frac > 0.55 then
                local to = tg_cr_flat(tg_tp_sub(sock0.P, P))
                local want = math.deg(tg_atan2_safe(to.y, to.x))
                bias = ((want - heading + 540) % 360) - 180
                bias = math.max(-45, math.min(45, bias))
            end
        end
        -- v2.3.0 radius: steer back toward the middle before reaching the edge
        if TG_CR_RADIUS then
            local tc = tg_tp_v(TG_CR_RADIUS.x - P.x, TG_CR_RADIUS.y - P.y, 0)
            local dc = tg_tp_len(tc)
            if dc > TG_CR_RADIUS.r * 0.5 then
                local want = math.deg(tg_atan2_safe(tc.y, tc.x))
                bias = math.max(-60, math.min(60, ((want - heading + 540) % 360) - 180))
            end
        end
        for pass = 1, 2 do
        if ok_plat then break end
        for _, dh in ipairs({ bias, bias - 20 + math.random() * 40, bias - 35, bias + 35, bias - 55, bias + 55 }) do
            local first = (plat_i == 1 and not entry)
            local hh = heading + dh
            local D = tg_tp_v(math.cos(math.rad(hh)), math.sin(math.rad(hh)), 0)
            local gap = first and 0 or (gap_lo + math.random() * math.max(0, gap_hi - gap_lo))
            if plat_i == 1 and entry then gap = 0 end
            local C = tg_tp_add(P, tg_tp_mul(D, gap + len * 0.5))
            local gC = tg_cr_ground(C.x, C.y) or P.z
            local h = P.z - gC
            -- start on the ground, then step up gradually (learned: steps of 1-8 m) to the style's height
            local dz
            if first then dz = 0
            elseif loop and count > budget * 0.7 then dz = -rise * (0.6 + math.random() * 0.6)
            elseif h < hmax * 0.6 then dz = rise * (0.6 + math.random() * 0.6)
            else dz = -rise * 0.6 + math.random() * rise * 1.2 end
            if plat_i == 1 and entry then dz = 0 end
            C.z = P.z + dz
            if first then
                local top = gC
                for _, o in ipairs({ { len * 0.5, wid * 0.5 }, { len * 0.5, -wid * 0.5 }, { -len * 0.5, wid * 0.5 }, { -len * 0.5, -wid * 0.5 }, { 0, 0 } }) do
                    local q = tg_tp_add(tg_tp_add(C, tg_tp_mul(D, o[1])), tg_tp_mul(tg_tp_v(-D.y, D.x, 0), o[2]))
                    local gq = tg_cr_ground(q.x, q.y)
                    if gq and gq > top then top = gq end
                end
                C.z = top + 0.25
            end
            if not first and (C.z - gC) < 2.0 then C.z = gC + 2.0 + math.random() * 2.0 end
            if pass == 2 and not first then
                -- relaxed pass: float the platform clear of whatever is under it
                local top = gC
                for _, o in ipairs({ { len * 0.5, wid * 0.5 }, { len * 0.5, -wid * 0.5 }, { -len * 0.5, wid * 0.5 }, { -len * 0.5, -wid * 0.5 } }) do
                    local q = tg_tp_add(tg_tp_add(C, tg_tp_mul(D, o[1])), tg_tp_mul(tg_tp_v(-D.y, D.x, 0), o[2]))
                    local gq = tg_cr_ground(q.x, q.y)
                    if gq and gq > top then top = gq end
                end
                if C.z < top + 1.0 then C.z = top + 1.0 end
            end
            if (C.z - P.z) > 4.5 then C.z = P.z + 4.5 end
            if (C.z - gC) > hmax + 8 then C.z = gC + hmax + 8 end
            local r = 0.5 * math.sqrt(len * len + wid * wid)
            local clash = false
            if TG_CR_RADIUS then
                local dx, dy = C.x - TG_CR_RADIUS.x, C.y - TG_CR_RADIUS.y
                local rr = TG_CR_RADIUS.r - r
                if dx * dx + dy * dy > rr * rr then clash = true end
            end
            local me = { C = C, D = D, len = len + 4.0, wid = wid + 4.0 }
            for qi, q in ipairs(placed_rects) do
                if qi < #placed_rects and tg_cr_rect_overlap(me, q) then clash = true; break end
            end
            if not clash and entry then
                local er = { C = tg_tp_v(entry.cx, entry.cy, entry.cz), D = tg_tp_norm(tg_cr_flat(entry.next.R.X)), len = entry.arc + 6.0, wid = 30.0 }
                if plat_i > 2 and tg_cr_rect_overlap(me, er) then clash = true end
            end
            if not clash then
                local g = tg_cr_ground(C.x, C.y)
                local corners_ok = true
                for _, o in ipairs({ { len * 0.5, wid * 0.5 }, { len * 0.5, -wid * 0.5 }, { -len * 0.5, wid * 0.5 }, { -len * 0.5, -wid * 0.5 } }) do
                    local q = tg_tp_add(tg_tp_add(C, tg_tp_mul(D, o[1])), tg_tp_mul(tg_tp_v(-D.y, D.x, 0), o[2]))
                    local gq = tg_cr_ground(q.x, q.y)
                    if gq and (C.z - gq) < -0.5 then corners_ok = false; break end
                end
                if corners_ok and (not g or (C.z - g) > -0.5) then
                    -- a probe along the platform at deck height (walls / trees)
                    local a = tg_tp_add(C, tg_tp_mul(D, -len * 0.5))
                    local b = tg_tp_add(C, tg_tp_mul(D, len * 0.5))
                    if pass == 2 or not (tg_cr_near(C) and tg_cr_probe(a.x, a.y, a.z + 2.0, b.x, b.y, b.z + 2.0)) then
                        ok_plat = { m = m, C = C, D = D, h = hh, len = len, wid = wid, r = r, gap = gap }
                        break
                    end
                end
            end
        end
        end
        if not ok_plat then break end
        if count + 1 > budget then break end
        local q = ok_plat
        q.tint = tg_cr_tint_for(V.tint, plat_i)
        table.insert(placed_rects, q)
        table.insert(items, { decor = true, model = q.m, P = tg_tp_v(q.C.x, q.C.y, q.C.z), yaw = tg_normalize_heading(q.h - 90.0), lift = -0.4, pitch = 0, centre = true, tint = q.tint, platform = true })
        count = count + 1
        table.insert(cps, { P = tg_tp_v(q.C.x - q.D.x * q.len * 0.3, q.C.y - q.D.y * q.len * 0.3, q.C.z + 1.5), psi = math.rad(q.h), island = #cps })
        if count < budget - 2 then
            local ramp
            if ramp_kind == "l" then ramp = "stt_prop_ramp_jump_l" elseif ramp_kind == "m" then ramp = "stt_prop_ramp_jump_m"
            else ramp = (math.random() < 0.6) and "stt_prop_ramp_jump_m" or "stt_prop_ramp_jump_l" end
            local edge = tg_tp_add(q.C, tg_tp_mul(q.D, q.len * 0.5 - 2.0))
            local bb = TG_CR_BB[ramp]
            local back = bb and (bb[4] - bb[1]) * 0.5 or 10
            table.insert(items, { decor = true, model = ramp, P = tg_tp_sub(edge, tg_tp_mul(q.D, back)), yaw = tg_normalize_heading(q.h), lift = 0.0, pitch = 0 })
            count = count + 1
        end
        count = count + tg_cr_wo_obstacles(items, q, V, budget - 1 - count, dynref)
        P = tg_tp_add(q.C, tg_tp_mul(q.D, q.len * 0.5))
        turned = turned + ((q.h - heading + 540) % 360 - 180)
        heading = q.h
        if not loop and tg_tp_len(tg_cr_flat(tg_tp_sub(P, home))) > 700 then
            local to = tg_cr_flat(tg_tp_sub(home, P))
            heading = math.deg(tg_atan2_safe(to.y, to.x))
        end
        if loop and plat_i > 4 and tg_tp_len(tg_cr_flat(tg_tp_sub(P, sock0.P))) < 70 then break end
        util.yield(0)
    end
    return items, cps, entry, ramp_seq
end

-- ---------- decorations from the learned rules ----------
function tg_cr_add_decor(B, plans, budget)
    local V = B.V or {}
    local d = {}
    local npieces, last = 0, nil
    for _, p in ipairs(plans) do
        if not p.pseudo then npieces = npieces + 1 end
        if not p.pseudo and not p.approach then last = p end
    end
    local room = budget - npieces
    if room <= 0 then return d end
    local function add(...) if #d < room then tg_cr_decor(d, ...) end end
    -- jump ramps + platform hops first (they are part of the course)
    for _, p in ipairs(plans) do
        if p.jump and #d < room and p.samples then
            local bb = TG_CR_BB[p.jump.ramp]
            local half = bb and (bb[4] - bb[1]) * 0.5 or 18.0
            local t = math.max(0.0, 1.0 - (half + 1.0) / math.max(1.0, p.arc))
            add(p.jump.ramp, p, t, 0.0, 0.0, 0.0)
        end
        if p.hop and #d < room then
            local h = p.hop
            local hh = math.deg(tg_atan2_safe(h.D.y, h.D.x))
            table.insert(d, { decor = true, model = h.model, P = h.C, yaw = tg_normalize_heading(hh - 90.0), lift = -0.4, pitch = 0, centre = true, platform = true, tint = tg_cr_tint_for(V.tint, 3) })
            if #d < room then
                local bb = TG_CR_BB[h.ramp]
                local back = bb and (bb[4] - bb[1]) * 0.5 or 10
                local edge = tg_tp_add(h.C, tg_tp_mul(h.D, h.len * 0.5 - 2.0))
                table.insert(d, { decor = true, model = h.ramp, P = tg_tp_sub(edge, tg_tp_mul(h.D, back)), yaw = tg_normalize_heading(hh), lift = 0.0, pitch = 0 })
            end
            if #d < room - 1 then
                tg_cr_wo_obstacles(d, { C = h.C, D = h.D, len = h.len * 0.6, wid = h.wid, h = hh }, { obst = { ball = 2, tyre = 2, flip = 1, turn = 1 } }, math.min(2, room - #d), { n = 0 })
            end
        end
    end
    if not TG_CR.decor then return d end
    local first = nil
    for _, p in ipairs(plans) do if not p.approach and not p.pseudo then first = p; break end end
    if first and first.f == "road" and first.samples then add("stt_prop_race_gantry_01", first, 0.92, 0.0, 0.0, 0.0) end
    local pads = 0
    local padf = V.pads or 1.0
    local want_pads = B.loop and math.floor(padf * 2 + 0.5) or math.floor((#plans / 9) * padf + 0.5)
    if B.downhill then want_pads = math.floor((#plans / 6) * padf + 0.5) end
    for i, p in ipairs(plans) do
        if pads >= want_pads then break end
        local pc = TG_CR_P[p.model]
        if pc and p.samples and pc.k == "straight" and pc.f == "road" and (pc.len or 0) >= 50 and not p.jump and not p.landing and not p.approach and i > 2 and (i % 3 == 0) then
            add("stt_prop_track_speedup_t1", p, 0.45, 0.0, 0.0, 0.0); pads = pads + 1
        end
    end
    local df = V.decor or 1.0
    for i, p in ipairs(plans) do
        local pc = TG_CR_P[p.model]
        if pc and p.samples and math.abs(pc.turn) >= 44 and p.f == "road" and (df >= 1.0 or math.random() < df) then
            local turn = (p.rev and -1 or 1) * pc.turn
            local outside = (turn > 0) and -1 or 1
            if B.drift then
                local ts = (df >= 1.4) and { 0.15, 0.38, 0.62, 0.85 } or { 0.25, 0.5, 0.75 }
                for _, t in ipairs(ts) do add("xs_prop_arrow_tyre_01a", p, t, outside * (pc.w + 1.6), (turn > 0) and 90 or -90, 0.0) end
            elseif not TG_CR.barriers then
                add("stt_prop_tyre_wall_0r010", p, 0.5, outside * (pc.w + 0.8), 0.0, 0.0)
            end
        end
    end
    if last and not B.loop and last.f == "road" and last.samples then add("stt_prop_race_gantry_01", last, 0.85, 0.0, 0.0, 0.0) end
    return d
end

-- ---------- spawning (tube-style drop-in animation) ----------
TG_CR_ANIM_LIFT = TG_CR_ANIM_LIFT or 16.0
function tg_cr_spawn_obj(model, o, pitch, roll, yaw, label, dynamic, tint)
    local anim = TG_CR.animate and not dynamic
    local lift = anim and TG_CR_ANIM_LIFT or 0.0
    local spins = { -180, -135, -90, 90, 135, 180 }
    local spin = anim and spins[math.random(#spins)] or 0
    local yaw0 = tg_normalize_heading(yaw + spin)
    local obj = tg_try_create_stunt_tube_model(model, o.x, o.y, o.z + lift, anim and yaw0 or yaw, label)
    if not obj then return nil end
    if tint and tg_pk_tint then tg_pk_tint(obj, tint) end
    if anim then
        local frames = math.max(1, tonumber(TG_TETRIS_SPIN_FRAMES or 6) or 6)
        local step_ms = tonumber(TG_TETRIS_STEP_MS or 45) or 45
        local delta = spin == 0 and 0 or -spin
        for i = 1, frames do
            if TG_CANCEL_GENERATION then break end
            local t = i / frames
            local eased = 1.0 - (1.0 - t) * (1.0 - t)
            local yw = tg_normalize_heading(yaw0 + delta * eased)
            local z = o.z + lift * (1.0 - eased)
            tg_tn_void(0x239A3351AC1DA385, obj, o.x + 0.0, o.y + 0.0, z + 0.0, false, false, false)
            tg_tube3d_apply_rotation(obj, pitch, roll, yw, label)
            util.yield(step_ms)
        end
    end
    tg_tube3d_apply_rotation(obj, pitch, roll, yaw, label)
    tg_tn_void(0x239A3351AC1DA385, obj, o.x + 0.0, o.y + 0.0, o.z + 0.0, false, false, false)
    -- v2.3.0: the saved file gets the final spot, not the drop-in animation's start
    local meta = tg_get_meta(obj)
    if meta then meta.x, meta.y, meta.z = o.x, o.y, o.z end
    if dynamic then
        tg_tn_void(0x428CA6DBD1094446, obj, false)
    else
        tg_tn_void(0x428CA6DBD1094446, obj, true)
        tg_tn_harden(obj, { x = o.x, y = o.y, z = o.z, pitch = pitch, roll = roll, yaw = yaw, model = model })
    end
    return obj
end
function tg_cr_spawn_piece(p, label)
    local obj = tg_cr_spawn_obj(p.model, p.origin, p.pitch, p.rollY, p.yaw, label, false, p.tint)
    p.handle = obj
    return obj
end
function tg_cr_spawn_decor(d, label)
    if not d.origin then tg_cr_decor_plan(d) end
    local obj = tg_cr_spawn_obj(d.model, d.origin, d.pitch_e, d.roll_e, d.yaw_e, label, d.dynamic, d.tint)
    d.handle = obj
    return obj
end

-- ---------- course runtime: start / finish / lap timer ----------
TG_CR_RUN = TG_CR_RUN or { active = false }
function tg_cr_run_tick()
    local t = TG_CR_RUN
    if not t.active then util.yield(400); return end
    local now = util.current_time_millis()
    if (now - (t.last_check or 0)) > 1200 then
        t.last_check = now
        local alive = false
        for _, o in ipairs(objects) do if o == t.obj then alive = true; break end end
        if not alive then t.active = false; return end
    end
    local p = tg_minigame_player_position() or nil
    if not p then util.yield(150); return end
    local function crossed(G, key)
        local rel = tg_tp_sub(tg_tp_v(p.x, p.y, p.z), G.P)
        local s = tg_tp_dot(rel, G.D)
        local lat = tg_tp_len(tg_tp_sub(rel, tg_tp_mul(G.D, s)))
        local prev = t[key]
        t[key] = s
        return prev and prev < 0.0 and s >= 0.0 and lat < (G.r or 16.0) and (s - prev) < 60.0
    end
    if crossed(t.start, "ps") then
        if t.loop and t.t0 then
            local lap = (now - t.t0) / 1000.0
            t.laps = (t.laps or 0) + 1
            local note = (not t.best or lap < t.best) and "  NEW BEST!" or string.format("  (best %.2fs)", t.best)
            if not t.best or lap < t.best then t.best = lap end
            tg_toast(string.format("Lap %d: %.2fs%s", t.laps, lap, note), 4000)
        else
            tg_toast("GO!", 1500)
        end
        t.t0 = now
    end
    if not t.loop and t.finish and t.t0 and crossed(t.finish, "pf") then
        local secs = (now - t.t0) / 1000.0
        local note = (not t.best or secs < t.best) and "  NEW BEST!" or string.format("  (best %.2fs)", t.best)
        if not t.best or secs < t.best then t.best = secs end
        tg_toast(string.format("FINISH! %.2fs%s", secs, note), 6000)
        t.t0 = nil
    end
    util.yield(0)
end
function tg_cr_start_tick()
    if TG_CR_TICK or TG_PRIME_REGISTER_TICKS == false or tg_tn_in_freemode_job() then return end
    TG_CR_TICK = true
    util.create_tick_handler(function()
        tg_cr_run_tick()
        return true
    end)
end

-- ---------- a plan that can't fit (v2.2.2) ----------
-- All five crash logs end right after a quick planning failure - the only path that toasted twice
-- within milliseconds and switched the progress bar into its red "failed" state. Now a failed plan
-- finishes through the same path as a successful one and the reason shows in the panel.
TG_CR_NOTICE = TG_CR_NOTICE or nil
function tg_cr_notice(msg)
    tg_cr_diag("notice: " .. tostring(msg))
    TG_CR_NOTICE = { msg = tostring(msg), t = util.current_time_millis() }
    -- v2.2.4: nothing visible changes - the progress bar simply goes away
    if TG_RS_PROG then TG_RS_PROG.active = false; TG_RS_PROG.done_at = util.current_time_millis() end
    TG_RS_RUN_GEN = nil
    tg_cr_diag("notice: progress hidden")
end
-- ---------- toasts: never two within 2 s (v2.2.2) ----------
-- Every crash log shows the game failing right after a quick planning failure, i.e. a second
-- toast a few ms after the "Planning..." toast. Builders space their toasts out.
function tg_cr_toast(msg, ms)
    local now = util.current_time_millis()
    local wait = 2000 - (now - (TG_CR_LAST_TOAST or -100000))
    if wait > 0 then util.yield(wait) end          -- no wait when called outside a job
    TG_CR_LAST_TOAST = util.current_time_millis()
    tg_toast(msg, ms)
end
-- ---------- build: plan (normal script job) -> spawn (freemode context) ----------
function tg_cr_diag(msg)
    tg_rs_diag("[CREATOR] " .. tostring(msg))
end
-- resolve category + style: "random" = any category, "hybrid" = every style mixed
function tg_cr_resolve(cat)
    cat = cat or TG_CR.style or "circuit"
    if cat == "random" then cat = TG_CR_CAT_ORDER[math.random(#TG_CR_CAT_ORDER)]; return cat, tg_cr_variant(cat, "random") end
    if cat == "hybrid" then return "hybrid", { id = "hybrid", name = "Hybrid", tint = ({ -1, "rainbow", "random", 2, 9 })[math.random(5)] } end
    if not TG_CR_STYLES[cat] then cat = "circuit" end
    return cat, tg_cr_variant(cat, (TG_CR.var or {})[cat] or "random")
end

-- ---------- v2.2.5/v2.2.6 adaptive planning (like the tubes / the Home tab's Smart Random Loop) ----------
-- The course always starts in front of you. If the designed shape doesn't fit, the planner adapts
-- (smaller loop, then weaving piece by piece round buildings) and only builds a completely clear plan.
-- Each step gets its own time budget.
TG_CR_TOTAL_MS = TG_CR_TOTAL_MS or 75000
function tg_cr_stage(ms)
    TG_CR_DL = util.current_time_millis() + (ms or 10000)
end
-- planning time is up (or Clear Track cancelled this build): planners stop and return what they have
function tg_cr_time_up()
    if tg_rs_check_cancel() then return true end
    local now = util.current_time_millis()
    if TG_CR_DL and now > TG_CR_DL then return true end
    return (now - (TG_CR_T0 or now)) > TG_CR_TOTAL_MS
end
function tg_cr_plan_build(cat_in)
    local cat, V = tg_cr_resolve(cat_in)
    local st = TG_CR_STYLES[cat]
    local label = st.name .. " - " .. tostring(V.name or "")
    tg_rs_build_start(st.name)
    TG_TUBEP_SEED_BUMP = (TG_TUBEP_SEED_BUMP or 0) + 7919
    if math.randomseed then math.randomseed(((os.time and os.time()) or 1) + TG_TUBEP_SEED_BUMP) end
    tg_cr_reset_world()
    TG_CR_T0 = util.current_time_millis()
    TG_CR_DL = nil
    util.yield(0)
    local limit = tg_rs_limit("creator")
    local sock0, home = tg_cr_start_socket(14.0)
    local user_r = tg_rs_radius("creator") or nil
    TG_CR_RADIUS = user_r and { x = home.x, y = home.y, r = user_r } or nil
    tg_cr_diag(string.format("plan start %s / %s limit=%d at %.0f,%.0f,%.0f loop=%s ramp=%s", cat, tostring(V.id), limit, sock0.P.x, sock0.P.y, sock0.P.z, tostring(TG_CR.loop), tostring(TG_CR.ramp)))
    local B = { cat = cat, V = V, st = st, label = label, limit = limit, sock0 = sock0, plans = {}, decor = {}, cps = nil }
    local track_budget = TG_CR.decor and math.max(8, math.floor(limit * 0.86)) or limit
    tg_rs_stage(cat == "wipeout" and "Planning platforms" or "Planning track")
    local loop = st.loop or (TG_CR.loop and cat ~= "hybrid")
    B.loop = loop
    B.drift = st.drift
    B.downhill = st.downhill
    B.adapt = {}
    -- v2.2.6: the course always starts in front of you. When the planned shape doesn't fit, the
    -- planner weaves piece by piece around buildings and objects (like the tubes and the Home tab's
    -- Smart Random Loop): every piece is checked against the ground, buildings and the course itself
    -- before it's placed, a blocked piece is swapped for a turn / climb, dead ends back-track.
    local function sprint_S(fam, attempts)
        return { fam = fam, V = V, learned = st.learned, hmin = V.hmin or st.hmin, hmax = V.hmax or st.hmax,
                 rise = (fam ~= "road") and (V.rise or 4.0) or nil, downhill = st.downhill or V.downhill, hybrid = st.hybrid, attempts = attempts,
                 prof_amp = V.prof_amp }
    end
    local function course_n(plans)
        local n = 0
        for _, p in ipairs(plans or {}) do if not p.approach and not p.pseudo then n = n + 1 end end
        return n
    end
    local function sprint_at(S, budget, ms, lab, min_n)
        tg_cr_stage(ms)
        local plans, extra = tg_cr_plan_sprint(S, budget, sock0, home, lab)
        if plans and course_n(plans) >= (min_n or 3) then return plans, extra end
        return nil
    end
    local function weave(S, budget, ms, lab, min_n)
        tg_rs_stage("Weaving round buildings")
        S.weave, S.short_start, S.attempts = true, true, 3
        local plans, extra = sprint_at(S, budget, ms, lab, min_n or 6)
        if plans and extra and extra.no_onramp then table.insert(B.adapt, "no straight run for a ramp in front of you - starts on the ground and climbs as it weaves") end
        return plans, extra
    end
    if cat == "wipeout" then
        tg_cr_toast(string.format("Planning Wipeout - %s (up to %d objects)...", tostring(V.name), limit), 2500)
        local items, cps, entry, rseq = nil, nil, nil, nil
        local sk = nil
        for _, t in ipairs({ 0, 20, -20, 40, -40, 60, -60, 80, -80, 100, -100 }) do
            local s2 = (t == 0) and sock0 or { P = sock0.P, R = tg_cr_frame(tg_cr_heading_of(sock0.R) + t) }
            items, cps, entry, rseq = tg_cr_plan_wipeout(limit, s2, home, V, TG_CR.loop, label)
            if tg_rs_check_cancel() then return nil, "cancelled" end
            if #items >= 6 then sk = s2; break end
        end
        B.sock0 = sk or sock0
        B.plans = rseq or {}
        B.decor = items or {}
        B.cps = cps
        B.loop = false
        loop = false
        if not sk or #B.decor == 0 then return nil, "No room for platforms in front of you - face open space and try again" end
    elseif loop then
        local fam = st.fam
        local L = { fam = fam, drift = st.drift, V = V, shape = (TG_CR.shape ~= "auto" and TG_CR.shape) or V.shape or "auto",
                    feat_p = V.feat_p, straight = V.straight, corners = V.corners }
        -- v2.2.1: every loop goes up and down (elevation pairs), starting from the ground
        local hi = (V.hills and V.hills[2]) or 6
        if cat == "circuit" then L.elev = 3; L.elev_k = 2; L.elev_a = math.max(6.0, math.min(9.0, hi + 3))
        elseif cat == "drift" then L.elev = 2; L.elev_a = 5.0; L.elev_k = 2
        elseif cat == "skyloop" or cat == "widesky" then L.elev = ((V.hillw or 1) >= 1.5) and 2 or 1
        elseif cat == "stunt" then L.elev = 3; L.elev_a = 8.0
        elseif cat == "downhill" then L.elev = 3; L.elev_a = 10.0
        elseif cat == "sky" then L.elev = 2 end
        -- rolling hinge hills on every road loop edge (v2.2.3: hillier)
        if L.fam == "road" and not st.drift then
            local f = {}
            for k2, v2 in pairs((L.V and L.V.feats) or {}) do f[k2] = v2 end
            f.hill = math.max(f.hill or 0, 4) * 1.5 * ((V.tt and V.tt.hill_k) or 1.0)
            local vv = {}
            for k2, v2 in pairs(L.V or {}) do vv[k2] = v2 end
            vv.feats = f
            local lo2, hi2 = 4, 8
            if vv.hills then lo2, hi2 = math.max(4, vv.hills[1] or 4), math.max(8, vv.hills[2] or 8) end
            if V.tt and V.tt.incline then lo2, hi2 = math.min(lo2, V.tt.incline), math.min(hi2, V.tt.incline) end
            vv.hills = { lo2, hi2 }
            L.V = vv
            L.feat_p = math.max(L.feat_p or 0.3, (V.tt and V.tt.featp_floor) or 0.45)
        end
        if not st.loop then
            -- Complete Loop for a point-to-point category: the loop keeps the category's character
            if cat == "sky" then L.fam = "stunt"; L.V = { hillw = 1.5 * (V.fx or 1.0) }
            elseif cat == "stunt" then L.V = { feats = { chic = 2, s15 = 2, hill = 4 * (V.updown or 1.0), jump = 3 * (V.jumps or 1.0) }, hills = { 4, 9 } }; L.feat_p = 0.45
            elseif cat == "downhill" then L.V = { feats = { hill = 6, s15 = 1, jump = 2 * (V.jumps or 1.0) }, hills = { 7, 12 * math.min(1.2, V.steep or 1.0) } }; L.feat_p = 0.55
            end
        end
        tg_cr_toast(string.format("Planning %s - %s (up to %d objects) - checking ground and buildings first...", st.name, tostring(V.name), limit), 3000)
        -- a plan that touches a building / the ground, or has no ramp, is never used
        local function loop_at(heads, scales, per, ms, lab)
            tg_cr_stage(ms)
            L.scales, L.per, L.tries = scales, per, #heads
            for ti, t in ipairs(heads) do
                L.try = ti - 1
                local sk = (t == 0) and sock0 or { P = sock0.P, R = tg_cr_frame(tg_cr_heading_of(sock0.R) + t) }
                local b2 = tg_cr_plan_loop(L, track_budget, sk, lab)
                if b2 and b2.bad == 0 and (b2.approach or not TG_CR.ramp) then return b2 end
                tg_cr_diag(string.format("%s heading %+d: %s", lab, t, b2 and ("bad=" .. tostring(b2.bad)) or "no loop"))
                if tg_cr_time_up() then break end
            end
            return nil
        end
        local all8 = { 0, 45, -45, 90, -90, 135, -135, 180 }
        -- 1) the full loop, starting in front of you
        local best = loop_at(all8, nil, 10, 14000, label)
        -- 2) a compact loop (hairpin oval / tight square, short straights)
        if not best then
            L.compact = true
            tg_rs_stage("Fitting a smaller loop")
            best = loop_at(all8, { 0.32, 0.22 }, 6, 9000, label .. " - smaller loop")
            if best then table.insert(B.adapt, "compact loop to fit the space") end
            L.compact = nil
        end
        if best then
            B.plans = best.plans
            B.loopinfo = best
            if best.approach then
                for _, p in ipairs(best.approach) do table.insert(B.plans, p) end
            end
            B.tight = best.bad
        else
            -- 3) a fixed loop shape doesn't fit here: weave piece by piece around the buildings,
            --    then steer back and finish near the start (Smart Random Loop style)
            local S = sprint_S((fam == "dw" or fam == "stunt") and fam or "road", 3)
            S.return_home = true
            local plans, extra = weave(S, track_budget, 16000, label .. " - weaving round the buildings", 8)
            if not plans and S.fam == "road" then
                -- road pieces are too wide for these streets: the narrower Stunt Track (the official
                -- maps join the two families) weaves where the road can't
                local S2 = sprint_S("stunt", 3)
                S2.return_home = true
                plans, extra = weave(S2, track_budget, 14000, label .. " - narrower pieces", 8)
                if plans then table.insert(B.adapt, "narrower Stunt Track pieces to fit between the buildings") end
            end
            if plans and not (extra and extra.closed) then
                -- 4) couldn't make it back: keep the weaving course (open finish)
                table.insert(B.adapt, "weaves round the buildings (couldn't get back to the start - open finish)")
            elseif plans then
                table.insert(B.adapt, 1, "weaves round the buildings and finishes back near the start")
            end
            if not plans then return nil, "Boxed in - no way out in front of you for this course (buildings / slopes). Face a road or open space and try again" end
            B.plans = plans
            B.extra = extra
            B.loop = false
            loop = false
        end
    else
        local S = sprint_S(st.fam, (limit >= 50) and 3 or 4)
        if cat == "hybrid" then S.attempts = 3 end
        tg_cr_toast(string.format("Planning %s - %s (up to %d objects)...", st.name, tostring(V.name), limit), 2500)
        -- 1) as designed, 2) weave in front of you (short start pieces, ramp only if there's room)
        local plans, extra = sprint_at(S, track_budget, 16000, label)
        if not plans then
            plans, extra = weave(S, track_budget, 16000, label .. " - weaving round the buildings", 5)
            if plans then table.insert(B.adapt, 1, "weaves round the buildings") end
        end
        if not plans and st.fam == "road" then
            local S2 = sprint_S("stunt", 3)
            S2.hybrid, S2.downhill = nil, st.downhill
            plans, extra = weave(S2, track_budget, 14000, label .. " - narrower pieces", 5)
            if plans then table.insert(B.adapt, 1, "weaves round the buildings on narrower Stunt Track pieces (road pieces are too wide here)") end
        end
        if not plans then return nil, "Boxed in - no way out in front of you for this course (buildings / slopes). Face a road or open space and try again" end
        B.plans = plans
        B.extra = extra
        if extra and (extra.relaxed or 0) > 0 then B.tight = math.max(B.tight or 0, 1) end
    end
    B.loop = loop
    if not loop and cat ~= "wipeout" then
        local n = 0
        for _, p in ipairs(B.plans) do if not p.approach and not p.pseudo then n = n + 1 end end
        if n < track_budget * 0.45 and #B.adapt > 0 then table.insert(B.adapt, string.format("short course (%d pieces - all the open ground there was)", n)) end
    end
    -- colours
    for i, p in ipairs(B.plans) do if not p.pseudo then p.tint = tg_cr_tint_for(V.tint, i) end end
    if cat ~= "wipeout" then
        local decor = tg_cr_add_decor(B, B.plans, limit)
        B.decor = decor
    end
    for _, d in ipairs(B.decor) do tg_cr_decor_plan(d) end
    -- v2.2.6: tyres / walls / gantries beside a deck squeezed between buildings: drop any that would
    -- end up inside a wall (the course itself is already checked)
    if cat ~= "wipeout" then
        for i = #B.decor, 1, -1 do
            local d = B.decor[i]
            local o = d.origin or d.P
            if o and not d.platform and not d.jumpramp then
                local g = tg_cr_ground(o.x, o.y)
                if g and g > o.z + 1.0 then table.remove(B.decor, i) end
            end
        end
    end
    -- real pieces only (platform hops are spawned as decor)
    local pieces = {}
    for _, p in ipairs(B.plans) do if not p.pseudo then table.insert(pieces, p) end end
    B.pieces = pieces
    while #pieces + #B.decor > limit and #B.decor > 0 do table.remove(B.decor) end
    while #pieces + #B.decor > limit and #pieces > 3 do table.remove(pieces) end
    -- checkpoints: one per course piece (approach pieces excluded); the last 3 never respawn anyone
    if not B.cps then
        local cps = {}
        for _, p in ipairs(B.plans) do
            if p.pseudo then
                table.insert(cps, { P = tg_tp_add(tg_tp_v(p.cx, p.cy, p.cz), tg_tp_v(0, 0, 1.5)), psi = math.rad(tg_cr_heading_of(p.next.R)), island = #cps })
            elseif not p.approach then
                table.insert(cps, { P = tg_tp_add(p.next.P, tg_tp_v(0, 0, 1.5)), psi = math.rad(tg_cr_heading_of(p.next.R)), island = #cps })
            end
        end
        B.cps = cps
    end
    for i, c in ipairs(B.cps) do c.noresp = (i > #B.cps - 3) end
    tg_cr_diag(string.format("plan done %s: %d pieces, %d decor, %d checkpoints, ground reads %d, probes %d, frames %d",
        cat, #pieces, #B.decor, #B.cps, TG_CR_BUD.ground, TG_CR_BUD.probes, TG_CR_BUD.frames))
    return B
end

-- spawn a planned course (runs in the freemode context so everyone sees it)
function tg_cr_spawn_build(B)
    local st = B.st
    clear_race_track("creator")
    local all = {}
    for _, p in ipairs(B.pieces) do table.insert(all, { model = p.model }) end
    for _, d in ipairs(B.decor) do table.insert(all, { model = d.model }) end
    tg_rs_preload(st.name, all)
    local missed, placed, first_obj = {}, 0, nil
    local total = #B.pieces + #B.decor
    -- course order: pieces, with each platform hop's objects right after its take-off piece
    for i, p in ipairs(B.pieces) do
        if tg_rs_spawn_progress(st.name, i, total, "Snapping") then return false end
        util.yield(TG_CR.animate and 20 or 55)
        local obj = tg_cr_spawn_piece(p, "creator_" .. i)
        if obj then placed = placed + 1; first_obj = first_obj or obj else table.insert(missed, p) end
    end
    for j, d in ipairs(B.decor) do
        if tg_rs_spawn_progress(st.name, #B.pieces + j, total, "Decorating") then return false end
        util.yield(TG_CR.animate and 20 or 45)
        local obj = tg_cr_spawn_decor(d, "creator_d" .. j)
        if obj then placed = placed + 1; first_obj = first_obj or obj else table.insert(missed, d) end
    end
    if #missed > 0 and tg_rs_repair then
        local keep = TG_CR.animate
        TG_CR.animate = false
        placed = placed + tg_rs_repair(st.name, missed, function(x, k)
            if x.decor then return tg_cr_spawn_decor(x, "creator_fix_d" .. k) end
            return tg_cr_spawn_piece(x, "creator_fix_" .. k)
        end)
        TG_CR.animate = keep
    end
    if tg_rs_check_cancel() then return false end
    tg_tn_settle_all("creator")
    local course = {}
    for _, p in ipairs(B.plans) do if not p.approach and not p.pseudo then table.insert(course, p) end end
    if #course > 0 and B.cat ~= "wipeout" then
        local p1 = course[1]
        local S = { P = p1.inP, D = tg_tp_norm(tg_cr_flat(p1.inD)), r = (p1.w or 12) + 4 }
        S.P = tg_tp_add(S.P, tg_tp_mul(S.D, math.min(40.0, (p1.arc or 40) * 0.5)))
        local last = course[#course]
        local F = { P = last.next.P, D = tg_tp_norm(tg_cr_flat(last.next.R.X)), r = (last.w or 12) + 4 }
        TG_CR_RUN = { active = true, loop = B.loop, start = S, finish = (not B.loop) and F or nil, obj = first_obj,
                      best = (TG_CR_RUN and TG_CR_RUN.style == B.cat) and TG_CR_RUN.best or nil, style = B.cat,
                      tp = { P = tg_tp_add(p1.inP, tg_tp_add(tg_tp_mul(S.D, 8.0), tg_tp_v(0, 0, 1.2))), psi = math.atan(S.D.y, S.D.x) } }
        -- with an approach ramp, "Go To Start" puts you at the bottom of the ramp
        TG_CR_RUN.tp_ramp, TG_CR_RUN.tp_onramp = nil, nil
        for _, p in ipairs(B.plans) do
            if p.onramp then TG_CR_RUN.tp_onramp = TG_CR_RUN.tp_onramp or p
            elseif p.approach then TG_CR_RUN.tp_ramp = p end
        end
    elseif B.cps and B.cps[1] then
        TG_CR_RUN = { active = false, tp = { P = B.cps[1].P, psi = B.cps[1].psi } }
        for _, p in ipairs(B.plans) do if p.onramp then TG_CR_RUN.tp_onramp = TG_CR_RUN.tp_onramp or p end end
    end
    if B.cps and #B.cps >= 2 and first_obj and tg_pk_arm then tg_pk_arm({ checkpoints = B.cps }, first_obj) end
    TG_CR.last = { style = B.cat, variant = B.V and B.V.id, plans = B.plans, decor = B.decor, loop = B.loopinfo }
    local vname = tostring(B.V and B.V.name or "")
    local msg
    if B.cat == "wipeout" then msg = string.format("Wipeout - %s: %d objects. Jump platform to platform - fall off and you're put back.", vname, placed)
    elseif B.loop then msg = string.format("%s - %s: %d pieces + %d decorations. Lap timer starts at the gantry.", st.name, vname, #B.pieces, #B.decor)
    else msg = string.format("%s - %s: %d pieces + %d decorations. Timer starts on the start deck, finish at the end.", st.name, vname, #B.pieces, #B.decor) end
    if (B.tight or 0) > 0 then msg = msg .. string.format(" (tight spot: %d piece(s) touch the ground or a building)", B.tight) end
    TG_CR_NOTICE = nil
    if B.adapt and #B.adapt > 0 then
        msg = msg .. " Adapted to fit: " .. table.concat(B.adapt, "; ") .. "."
        TG_CR_NOTICE = { msg = "built - adapted to fit: " .. table.concat(B.adapt, "; "), t = util.current_time_millis() }
    end
    tg_rs_progress_done(string.format("%d objects placed", placed))
    tg_cr_toast(msg, 6000)
    tg_cr_diag("spawn done " .. tostring(placed) .. " objects")
    return placed > 0
end
if tg_tn_wrap then tg_cr_spawn_build = tg_tn_wrap("tg_cr_spawn_build", tg_cr_spawn_build) end

-- plan here (normal script job: yields are safe, no freemode-context natives), then hand the finished
-- plan to the spawner
function tg_cr_build(style)
    local B, why = tg_cr_plan_build(style)
    if tg_rs_check_cancel() then tg_cr_diag("planning cancelled by Clear Track"); return false end
    if not B then
        tg_cr_diag("plan gave up: " .. tostring(why))
        tg_cr_notice(tostring(why or "No room here"))
        return false
    end
    tg_cr_diag("spawn queued")
    return tg_cr_spawn_build(B)
end

function tg_cr_goto_start()
    local t = TG_CR_RUN
    if not t or not t.tp then tg_toast("Build a Creator course first.", 2500); return end
    if t.tp_onramp and t.tp_onramp.inP then
        local D = tg_tp_norm(tg_cr_flat(t.tp_onramp.inD))
        tg_pk_put_at({ P = tg_tp_add(t.tp_onramp.inP, tg_tp_add(tg_tp_mul(D, -12.0), tg_tp_v(0, 0, 1.5))), psi = math.atan(D.y, D.x) }, 0)
    elseif t.tp_ramp and t.tp_ramp.next then
        local e = t.tp_ramp.next
        local D = tg_tp_norm(tg_cr_flat(e.R.X))
        -- bottom of the approach ramp, facing up it
        tg_pk_put_at({ P = tg_tp_add(e.P, tg_tp_add(tg_tp_mul(D, 10.0), tg_tp_v(0, 0, 1.5))), psi = math.atan(-D.y, -D.x) }, 0)
    elseif tg_pk_put_at then tg_pk_put_at({ P = t.tp.P, psi = t.tp.psi }, 0) end
    t.ps, t.pf, t.t0 = nil, nil, nil
end

function tg_creator_build(style)
    tg_cr_start_tick()
    style = style or TG_CR.style
    -- planning yields: always run it as its own script job (safe from any menu callback)
    if tg_ui_queue_action and not TG_CR_IN_JOB then
        return tg_ui_queue_action("Creator plan", function()
            TG_CR_IN_JOB = true
            tg_cr_build(style)
            TG_CR_IN_JOB = false
            tg_cr_diag("plan job finished")
            tg_rs_trace_start(15000, "after Creator plan")
        end)
    end
    return tg_cr_build(style)
end
function tg_creator_random()
    local cat = TG_CR_CAT_MENU[math.random(#TG_CR_CAT_MENU)]
    if cat == "random" then cat = "hybrid" end
    return tg_creator_build(cat)
end
function tg_creator_cycle_style()
    TG_CR.style = tg_tr_cycle(TG_CR_CAT_MENU, TG_CR.style)
    tg_toast("Creator: " .. ((TG_CR_STYLES[TG_CR.style] or {}).name or ((TG_CR.style == "random") and "Random" or TG_CR.style)), 2500)
end
function tg_creator_cycle_variant()
    local cat = TG_CR.style
    local list = TG_CR_VARIANTS[cat]
    if not list then return end
    local ids = { "random" }
    for _, v in ipairs(list) do table.insert(ids, v.id) end
    TG_CR.var[cat] = tg_tr_cycle(ids, TG_CR.var[cat] or "random")
    tg_toast("Course style: " .. tg_cr_variant_name(cat, TG_CR.var[cat]), 2500)
end
function tg_creator_toggle(key, label)
    TG_CR[key] = not TG_CR[key]
    tg_toast(label .. ": " .. (TG_CR[key] and "ON" or "OFF"), 2000)
end

