-- ═══════════════════════════════════════════════════════════════════════════════════
-- trackmatic lab: prototype generators built from the catalog
--   1) Special Circuit tube skin (Tubes tab)   2) Air Race   3) Stunt Park   4) Arena Gauntlet
-- Every object's real size comes from the game (GET_MODEL_DIMENSIONS) so it sits on the ground,
-- faces the right way and never overlaps another one.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_RS.limits.lab = TG_RS.limits.lab or 60
TG_LAB = TG_LAB or { park = "mixed", air_alt = "mid", last = nil }

-- ---------- 1) Special Vehicle Circuit tube skin ----------
-- 217 of 219 joints in the official Special Vehicle Circuit races line up exactly with the standard
-- tube geometry, so these animated colour variants are drop-in replacements.
TG_RS_SKIN_MAP = { xxs = "sr_prop_spec_tube_xxs_0%da", xs = "sr_prop_stunt_tube_xs_0%da", s = "sr_prop_spec_tube_s_0%da",
    m = "sr_prop_spec_tube_m_0%da", l = "sr_prop_spec_tube_l_0%da", crn = "sr_prop_spec_tube_crn_0%da",
    crn2 = "sr_prop_stunt_tube_crn2_0%da", c30 = "sr_prop_spec_tube_crn_30d_0%da", c15 = "sr_prop_stunt_tube_crn_15d_0%da",
    c5 = "sr_prop_stunt_tube_crn_5d_0%da" }
TG_TUBER_SEL.skin = TG_TUBER_SEL.skin or "classic"
TG_TUBER_SKIN_ORDER = { "classic", "special", "special_mix" }
TG_TUBER_SKIN_NAMES = { classic = "Classic", special = "Special Circuit", special_mix = "Special (mixed colours)" }
function tg_rs_apply_skin(plans)
    local sk = TG_TUBER_SEL.skin
    if sk ~= "special" and sk ~= "special_mix" then return end
    local v = math.random(5)
    for _, p in ipairs(plans) do
        local f = TG_RS_SKIN_MAP[p.key or ""]
        if f then
            if sk == "special_mix" then v = math.random(5) end
            p.model = string.format(f, v)
        end
    end
end
function tg_tube_race_cycle_skin()
    TG_TUBER_SEL.skin = tg_tr_cycle(TG_TUBER_SKIN_ORDER, TG_TUBER_SEL.skin)
    tg_toast("Tube skin: " .. TG_TUBER_SKIN_NAMES[TG_TUBER_SEL.skin] .. " (Standard tubes)", 2500)
end

-- ---------- shared placement ----------
function tg_lab_extents(model)
    local d = tg_rs_model_dims(model)
    if not d then return nil end
    return { d = d, w = d.max.x - d.min.x, l = d.max.y - d.min.y, h = d.max.z - d.min.z,
             cx = (d.min.x + d.max.x) * 0.5, cy = (d.min.y + d.max.y) * 0.5, cz = (d.min.z + d.max.z) * 0.5 }
end
-- spawn `model` so its bounding box sits at P (mode "ground": bottom on P.z, "centre": box centre at P)
function tg_lab_place(model, P, yaw, mode, label)
    local e = tg_lab_extents(model)
    local yr = math.rad(yaw)
    local cx, cy, z = 0.0, 0.0, P.z
    if e then
        cx, cy = e.cx, e.cy
        z = (mode == "centre") and (P.z - e.cz) or (P.z - e.d.min.z + 0.03)
    end
    local ox = P.x - (cx * math.cos(yr) - cy * math.sin(yr))
    local oy = P.y - (cx * math.sin(yr) + cy * math.cos(yr))
    local obj = tg_try_create_stunt_tube_model(model, ox, oy, z, yaw, label)
    if not obj then return nil end
    tg_tube3d_apply_rotation(obj, 0.0, 0.0, yaw, label)
    tg_tn_void(0x239A3351AC1DA385, obj, ox + 0.0, oy + 0.0, z + 0.0, false, false, false)
    tg_tn_void(0x428CA6DBD1094446, obj, true)
    tg_tn_harden(obj, { x = ox, y = oy, z = z, pitch = 0.0, roll = 0.0, yaw = yaw, model = model })
    return obj
end
function tg_lab_shuffled(list)
    local t = {}
    for _, m in ipairs(list) do if not m:find("landmine", 1, true) then table.insert(t, m) end end   -- mines explode: never
    for i = #t, 2, -1 do local j = math.random(i); t[i], t[j] = t[j], t[i] end
    return t
end
-- v2.2.0: straight from the game's ground probe (no Cherax GetGroundZ helper, see the Creator crash fix)
function tg_lab_ground(x, y)
    local top = tg_rs_height(x, y) or nil
    return tg_cr_native_ground(x, y, (top and (top + 6.0)) or 1500.0) or nil
end
function tg_lab_frame()
    local pos, heading = tg_get_local_position_heading("lab")
    heading = tonumber(heading or 0.0) or 0.0
    local fx, fy = calculate_new_position({ x = 0.0, y = 0.0, z = 0.0 }, heading, 1.0, 0.0, 0.0)
    return pos, math.atan(fy, fx)
end

-- ---------- 2) Air Race: fly through gates in the sky ----------
TG_LAB_AIR = TG_LAB_AIR or { active = false }
function tg_lab_gate_pool()
    local pool = {}
    for _, m in ipairs(TG_RS_CATALOG.airgates.models) do
        local e = tg_lab_extents(m)
        if e then
            local thin, wide = math.min(e.w, e.l), math.max(e.w, e.l)
            -- a gate is wide, tall enough and thin; huge checkpoint tubes / towers are skipped
            if wide >= 8.0 and wide <= 120.0 and e.h >= 6.0 and e.h <= 120.0 and thin <= 0.45 * wide then
                table.insert(pool, { m = m, e = e, pass_x = (e.w < e.l), open = math.min(wide, e.h) })
            end
        elseif m:find("neon_gate", 1, true) or m:find("inflategates", 1, true) then
            table.insert(pool, { m = m, pass_x = true, open = 14.0 })    -- size unknown: assume it faces like the measured neon gate
        end
    end
    return pool
end
function tg_lab_air_build()
    tg_rs_build_start("Air Race")
    clear_race_track("lab_air")
    TG_TUBEP_SEED_BUMP = (TG_TUBEP_SEED_BUMP or 0) + 7919
    if math.randomseed then math.randomseed(((os.time and os.time()) or 1) + TG_TUBEP_SEED_BUMP) end
    local pool = tg_lab_gate_pool()
    if #pool == 0 then tg_toast("Air Race: no gate models available.", 4000); tg_rs_progress_fail("No gate models"); return false end
    local limit = tg_rs_limit("lab")
    local n = math.max(8, math.min(limit, 40))
    local pos, psi = tg_lab_frame()
    local g0 = tg_lab_ground(pos.x, pos.y) or pos.z
    local alt = ({ low = 45.0, mid = 90.0, high = 160.0 })[TG_LAB.air_alt or "mid"] or 90.0
    local P = { x = pos.x + math.cos(psi) * 80.0, y = pos.y + math.sin(psi) * 80.0, z = g0 + alt }
    local heading, gates = psi, {}
    for i = 1, n do
        tg_rs_plan_progress("Air Race", 1, 1, i, n)
        if i % 5 == 0 then util.yield(0) end
        if i > 1 then
            heading = heading + math.rad(-32.0 + math.random() * 64.0)
            local step = 150.0 + math.random() * 90.0
            -- v2.3.0 radius: turn back toward the middle before reaching the edge
            local lr = tg_rs_radius("lab") or nil
            if lr then
                step = math.min(step, math.max(60.0, lr * 0.35))
                local dx, dy = pos.x - P.x, pos.y - P.y
                if dx * dx + dy * dy > (lr * 0.5) ^ 2 then heading = math.atan(dy, dx) + math.rad(-35.0 + math.random() * 70.0) end
            end
            P = { x = P.x + math.cos(heading) * step, y = P.y + math.sin(heading) * step, z = P.z + (-25.0 + math.random() * 50.0) }
        end
        -- stay well above the ground / buildings (height map covers the whole map)
        local floor = (tg_rs_height(P.x, P.y)) or tg_lab_ground(P.x, P.y) or g0
        P.z = math.max(P.z, floor + 35.0)
        P.z = math.min(P.z, floor + 320.0)
        local pick = pool[math.random(#pool)]
        table.insert(gates, { P = { x = P.x, y = P.y, z = P.z }, psi = heading, g = pick })
    end
    local all = {}
    for _, gt in ipairs(gates) do table.insert(all, { model = gt.g.m }) end
    tg_rs_preload("Air Race", all)
    local placed = 0
    for i, gt in ipairs(gates) do
        if tg_rs_spawn_progress("Air Race", i, #gates, "Spawning gate") then return false end
        util.yield(60)
        local yaw = math.deg(gt.psi)
        if not gt.g.pass_x then yaw = yaw - 90.0 end
        gt.handle = tg_lab_place(gt.g.m, gt.P, tg_normalize_heading(yaw), "centre", "lab_air_" .. i)
        if gt.handle then placed = placed + 1 end
    end
    tg_tn_settle_all("air race")
    TG_LAB_AIR = { active = true, gates = gates, next = 1, t0 = nil, best = TG_LAB_AIR.best }
    tg_lab_start_tick()
    tg_rs_progress_done(string.format("%d gates - fly through them in order", placed))
    tg_toast(string.format("Air Race: %d gates in the sky ahead. Grab a plane or a heli and fly through them in order - the clock starts at gate 1.", placed), 7000)
    return placed > 0
end
function tg_lab_air_tick()
    local A = TG_LAB_AIR
    if not A.active or not A.gates then return end
    local p = tg_minigame_player_position() or nil
    if not p then return end
    local gt = A.gates[A.next]
    if not gt then return end
    local dx, dy, dz = p.x - gt.P.x, p.y - gt.P.y, p.z - gt.P.z
    local r = math.max(10.0, (gt.g.open or 14.0) * 0.6) + 4.0
    if dx * dx + dy * dy + dz * dz < r * r then
        local now = util.current_time_millis()
        if A.next == 1 then A.t0 = now; tg_toast("GO! Gate 1 / " .. #A.gates, 2000)
        elseif A.next == #A.gates then
            local secs = (now - (A.t0 or now)) / 1000.0
            local note = (not A.best or secs < A.best) and "  NEW BEST!" or string.format("  (best %.2fs)", A.best)
            if not A.best or secs < A.best then A.best = secs end
            tg_toast(string.format("FINISH! %d gates in %.2fs%s", #A.gates, secs, note), 6000)
            A.next = 1; A.t0 = nil
            return
        else
            tg_toast(string.format("Gate %d / %d", A.next, #A.gates), 1200)
        end
        A.next = A.next + 1
    end
end
function tg_lab_start_tick()
    if TG_LAB_TICK or TG_PRIME_REGISTER_TICKS == false or tg_tn_in_freemode_job() then return end
    TG_LAB_TICK = true
    util.create_tick_handler(function()
        local alive = false
        local A = TG_LAB_AIR
        if A.active and A.gates and A.gates[1] and A.gates[1].handle then
            for _, o in ipairs(objects) do if o == A.gates[1].handle then alive = true; break end end
            if not alive then A.active = false end
        end
        tg_lab_air_tick()
        util.yield(100)
        return true
    end)
end

