-- ---------- 3) Stunt Park (v2.2.0): think-ahead freestyle park ----------
-- Learned from the park / stunt maps (216 maps, 1,000+ ramp placements):
--   * ramps launch along their local +X (the run-up track always sits on their -X side)
--   * kicker -> lander: the same ramp turned round, lip to lip, so you land on its slope
--   * small kickers are set 2-3 side by side to make one wide ramp
--   * speed pad ~11 m before a ramp, hoop ~26 m past the lip, target ~52 m past it
--   * raised slab decks with a second ramp on top ("ramps on ramps"), loops, spirals, wall-rides
-- Planner (same thinking as the tubes / Creator):
--   1) scan the ground ahead on a 10 m grid: real ground, buildings / trees from the height map,
--      water, slopes
--   2) lay combos along flowing lines - each combo's landing runs into the next one's run-up, so
--      stunts aim at stunts; every combo reserves a clear corridor (run-up + flight + run-out) that
--      nothing else may touch, plus collision probes along it
--   3) every object sits exactly on the ground (lowest point under its footprint, never floating)
--   4) plan in the normal script job, spawn in the freemode context (drop-in animation)
TG_LAB.animate = (TG_LAB.animate ~= false)
-- v2.2.5: combos too long / too big for the compact (between-the-buildings) pass
TG_LAB_BIG_COMBOS = { wide = true, awide = true, mega = true, spiral = true, loop = true, deck = true, wall = true, target = true, flipper = true, turn = true }
TG_LAB_PARKS = {
    mixed = { name = "Mixed Park", desc = "Every combo: kicker/lander, wide ramps, hoops, targets, boost jumps, loops, spirals, wall-rides, raised decks with ramps on top, mega jumps, flips.",
              combos = { kick = 4, wide = 3, hoop = 2, target = 2, boost = 3, chain = 2, loop = 2, spiral = 1, wall = 2, deck = 2, mega = 1, flip = 2 } },
    ramps = { name = "Ramp Park", desc = "Pure jumps: kicker/lander lines, chains, wide ramps, boost jumps, mega jumps, flips, decks with ramps on top.",
              combos = { kick = 5, wide = 4, boost = 3, chain = 3, mega = 2, flip = 3, deck = 2, loop = 1 } },
    arena = { name = "Arena Park", desc = "Arena War jumps and hazards: arena kickers, flipper runs, turntable crossings, fire pits beside the lines.",
              combos = { akick = 5, awide = 3, flipper = 2, turn = 2, boost = 2, deck = 1, target = 1 } },
}
TG_LAB_PARK_ORDER = { "mixed", "ramps", "arena" }
if TG_LAB.park == "blocks" or not TG_LAB_PARKS[TG_LAB.park or ""] then TG_LAB.park = "mixed" end

TG_LAB_RAMPS = {
    stt = { xs = "stt_prop_ramp_jump_xs", s = "stt_prop_ramp_jump_s", m = "stt_prop_ramp_jump_m", l = "stt_prop_ramp_jump_l", xl = "stt_prop_ramp_jump_xl", xxl = "stt_prop_ramp_jump_xxl" },
    arena = { s = "xs_prop_arena_jump_s_01a", m = "xs_prop_arena_jump_m_01a", l = "xs_prop_arena_jump_l_01a", xl = "xs_prop_arena_jump_xl_01a", xxl = "xs_prop_arena_jump_xxl_01a" },
}
function tg_lab_bb(m)
    local b = TG_LAB_BB[m]
    if b then return b end
    local e = tg_lab_extents(m)
    if e and e.d then return { e.d.min.x, e.d.min.y, e.d.min.z, e.d.max.x, e.d.max.y, e.d.max.z } end
    return { -5, -5, 0, 5, 5, 3 }
end

-- combo in its own frame: x along the flow (entry at x = 0), y to the left.
-- part = { m, x, y, yaw (deg, relative), air = height of the model's bottom above the ground (nil = on the ground) }
function tg_lab_add_ramp(C, m, x_back, y, reverse, air)
    -- x_back = where the low (back) end of the ramp goes; returns the lip x
    local b = tg_lab_bb(m)
    if not reverse then
        table.insert(C.parts, { m = m, x = x_back - b[1], y = y or 0, yaw = 0, air = air, kind = "ramp" })
        return x_back - b[1] + b[4]
    end
    -- turned round (a lander): x_back is now where its lip goes, the low end is further on
    table.insert(C.parts, { m = m, x = x_back + b[4], y = y or 0, yaw = 180, air = air, kind = "ramp" })
    return x_back + b[4] - b[1]
end
function tg_lab_gap(h) return 1.6 * h + 8.0 end
function tg_lab_combo(kind, arena, chained)
    local C = { kind = kind, parts = {}, hw = TG_LAB_COMPACT and 7.0 or 9.0, turn = 0 }
    local R = arena and TG_LAB_RAMPS.arena or TG_LAB_RAMPS.stt
    local function pick(list) return list[math.random(#list)] end
    local run = chained and 16.0 or (TG_LAB_COMPACT and 20.0 or 30.0)
    if kind == "kick" or kind == "akick" or kind == "boost" or kind == "flip" then
        local sz = pick(TG_LAB_COMPACT and { "s", "s", "m", "m" } or { "s", "m", "m", "l", "l", "xl" })
        local m = R[sz] or R.m
        if kind == "flip" then m = pick({ "stt_prop_ramp_adj_flip_m", "stt_prop_ramp_adj_flip_s" }) end
        if kind == "boost" then table.insert(C.parts, { m = "stt_prop_track_speedup_t1", x = run - 11.0, y = 0, yaw = 0, kind = "pad" }) end
        local b = tg_lab_bb(m)
        local lip = tg_lab_add_ramp(C, m, run, 0)
        local gap = tg_lab_gap(b[6]) * ((kind == "boost") and 1.3 or 1.0)
        local back = tg_lab_add_ramp(C, m, lip + gap, 0, true)
        C.len = back + 24.0
        C.name = (kind == "boost") and "Boost jump" or ((kind == "flip") and "Flip ramp" or "Kicker -> lander")
    elseif kind == "wide" or kind == "awide" then
        local m = R[pick({ "s", "m", "l" })] or R.m
        local b = tg_lab_bb(m)
        local w = (b[5] - b[2]) + 0.05
        local n = pick({ 2, 3, 3 })
        local lip, back = 0, 0
        for i = 1, n do
            local y = (i - (n + 1) / 2) * w
            lip = tg_lab_add_ramp(C, m, run, y)
        end
        for i = 1, n do
            local y = (i - (n + 1) / 2) * w
            back = tg_lab_add_ramp(C, m, lip + tg_lab_gap(b[6]), y, true)
        end
        C.hw = n * w * 0.5 + 6.0
        C.len = back + 24.0
        C.name = "Wide kicker"
    elseif kind == "hoop" then
        local m = R[pick({ "m", "l" })]
        local b = tg_lab_bb(m)
        local lip = tg_lab_add_ramp(C, m, run, 0)
        if math.random() < 0.5 then
            -- the giant tyre hoop stands on the ground, ~26 m past the lip (pass through along its Y)
            table.insert(C.parts, { m = "stt_prop_hoop_tyre_01a", x = lip + 26.0, y = 0, yaw = 90, kind = "hoop" })
            C.hw = 27.0
        else
            table.insert(C.parts, { m = "stt_prop_hoop_small_01", x = lip + 14.0, y = 0, yaw = 90, air = b[6] + 2.5, kind = "hoop" })
        end
        local back = tg_lab_add_ramp(C, m, lip + tg_lab_gap(b[6]) + 10.0, 0, true)
        C.len = back + 24.0
        C.name = "Hoop jump"
    elseif kind == "target" then
        local m = R[pick({ "m", "l", "xl" })] or R.l
        local lip = tg_lab_add_ramp(C, m, run, 0)
        table.insert(C.parts, { m = "stt_prop_stunt_target_small", x = lip + 52.0, y = 0, yaw = 0, kind = "target" })
        C.hw = 21.0
        C.len = lip + 52.0 + 19.5 + 25.0
        C.name = "Target jump"
    elseif kind == "chain" then
        local m = R[pick({ "s", "m" })]
        local b = tg_lab_bb(m)
        local x = run
        for k = 1, 2 do
            local lip = tg_lab_add_ramp(C, m, x, 0)
            local back = tg_lab_add_ramp(C, m, lip + tg_lab_gap(b[6]), 0, true)
            x = back + 14.0
        end
        C.len = x + 22.0
        C.name = "Jump chain"
    elseif kind == "loop" then
        table.insert(C.parts, { m = "stt_prop_track_speedup_t1", x = run - 14.0, y = 0, yaw = 0, kind = "pad" })
        local b = tg_lab_bb("stt_prop_ramp_adj_loop")
        table.insert(C.parts, { m = "stt_prop_ramp_adj_loop", x = run - b[1], y = 0, yaw = 0, kind = "loop" })
        C.hw = 22.0
        C.len = run - b[1] + b[4] + 34.0
        C.name = "360 loop"
    elseif kind == "spiral" then
        local m = pick({ "stt_prop_ramp_spiral_xxl", "stt_prop_ramp_spiral_l" })
        local b = tg_lab_bb(m)
        table.insert(C.parts, { m = m, x = run - b[1], y = 0, yaw = 0, kind = "spiral" })
        C.hw = 26.0
        C.len = run - b[1] + b[4] + 40.0
        C.name = "Spiral ramp"
    elseif kind == "wall" then
        local right = math.random() < 0.5
        local m = right and pick({ "stt_prop_wallride_45ra", "stt_prop_wallride_90rb" }) or pick({ "stt_prop_wallride_45la", "stt_prop_wallride_90lb" })
        local b = tg_lab_bb(m)
        table.insert(C.parts, { m = m, x = run - b[1], y = 0, yaw = 0, kind = "wall" })
        C.hw = math.max(math.abs(b[2]), math.abs(b[5])) + 5.0
        C.len = run - b[1] + b[4] + 30.0
        C.turn = (m:find("90", 1, true) and 90 or 45) * (right and -1 or 1)
        C.name = "Wall ride"
    elseif kind == "deck" then
        -- ramps on ramps: kicker up onto a raised slab, a second kicker on top, a big lander below
        local up = R.l or "stt_prop_ramp_jump_l"
        local bu = tg_lab_bb(up)
        local lip = tg_lab_add_ramp(C, up, run, 0)
        local slab = "stt_prop_stunt_bblock_huge_01"
        local bs = tg_lab_bb(slab)
        local slen, top = bs[5] - bs[2], bu[6] - 3.0
        local s0 = lip + 16.0
        table.insert(C.parts, { m = slab, x = s0 + slen * 0.5, y = 0, yaw = 90, air = top - (bs[6] - bs[3]), kind = "deck" })
        local m2 = R.m or "stt_prop_ramp_jump_m"
        local b2 = tg_lab_bb(m2)
        local lip2 = tg_lab_add_ramp(C, m2, s0 + slen - 2.0 - (b2[4] - b2[1]), 0, false, top)
        local land = R.xl or R.l
        local back = tg_lab_add_ramp(C, land, lip2 + tg_lab_gap(top + b2[6]) * 0.8, 0, true)
        C.hw = (bs[4] - bs[1]) * 0.5 + 5.0
        C.len = back + 34.0
        C.name = "Raised deck (ramp on ramp)"
    elseif kind == "mega" then
        local m = R.xxl or R.xl
        local b = tg_lab_bb(m)
        run = math.max(run, 34.0)
        table.insert(C.parts, { m = "stt_prop_track_speedup_t1", x = run - 11.0, y = 0, yaw = 0, kind = "pad" })
        table.insert(C.parts, { m = "stt_prop_track_speedup_t1", x = run - 30.0, y = 0, yaw = 0, kind = "pad" })
        local lip = tg_lab_add_ramp(C, m, run + 10.0, 0)
        local back = tg_lab_add_ramp(C, m, lip + tg_lab_gap(b[6]) * 1.2, 0, true)
        C.len = back + 40.0
        C.name = "Mega jump"
    elseif kind == "flipper" then
        for k = 1, 2 do table.insert(C.parts, { m = "xs_prop_arena_flipper_large_01a_sf", x = run + (k - 1) * 30.0, y = 0, yaw = 0, kind = "hazard" }) end
        C.len = run + 30.0 + 40.0
        C.side = { "xs_prop_arena_pit_fire_01a_sf" }
        C.name = "Flipper run"
    elseif kind == "turn" then
        for k = 1, 3 do table.insert(C.parts, { m = "xs_prop_arena_turntable_02a", x = run + (k - 1) * 22.0, y = 0, yaw = 0, kind = "hazard" }) end
        C.len = run + 44.0 + 34.0
        C.side = { "xs_prop_arena_pit_fire_01a_sf", "xs_prop_arena_wall_rising_01a_sf" }
        C.name = "Turntable crossing"
    end
    -- arena parks: fire pits / rising walls BESIDE the line (never in it)
    if arena and C.side == nil and math.random() < 0.4 then C.side = { "xs_prop_arena_pit_fire_01a_sf" } end
    return C
end

-- ---------- area scan ----------
function tg_lab_scan(pos, F, label)
    local S = { cells = {}, cs = 10.0, pos = pos }
    local R = 205.0
    local lr = tg_rs_radius("lab") or nil      -- v2.3.0 radius
    if lr then R = math.min(R, lr) end
    local n, nok = 0, 0
    local L = tg_tp_v(-F.y, F.x, 0)
    local g_here = tg_cr_ground(pos.x, pos.y) or pos.z
    for i = -20, 20 do
        for j = -20, 20 do
            local x, y = pos.x + i * S.cs, pos.y + j * S.cs
            local dx, dy = x - pos.x, y - pos.y
            if dx * dx + dy * dy < R * R then
                n = n + 1
                if n % 60 == 0 and tg_rs_plan_progress then tg_rs_plan_progress(label, 1, 2, n, 1300) end
                local g = tg_cr_ground(x, y)
                local top = tg_rs_height(x, y) or nil
                local ok = g ~= nil and g > 0.8
                if ok and top and (top - g) > 6.0 then
                    -- v2.2.5 compact pass: the height map is coarse next to buildings - a street cell at
                    -- your level stays usable (the corridor probes and footprint readings still check it)
                    ok = TG_LAB_COMPACT and math.abs(g - g_here) < 8.0 or false
                end
                -- compact pass: only ground at your level (no roofs)
                if ok and TG_LAB_COMPACT and math.abs(g - g_here) >= 8.0 then ok = false end
                S.cells[i * 1000 + j] = { g = g, ok = ok }
                if ok then nok = nok + 1 end
            end
        end
    end
    -- slopes: a cell is bad when its ground differs from a neighbour by more than 2 m
    for k, c in pairs(S.cells) do
        if c.ok then
            local i, j = math.floor((k + 500) / 1000), 0
            j = k - i * 1000
            for _, d in ipairs({ { 1, 0 }, { 0, 1 }, { -1, 0 }, { 0, -1 } }) do
                local o = S.cells[(i + d[1]) * 1000 + (j + d[2])]
                -- (compact pass: a jump of more than 6 m is a building wall, not a slope - the corridor
                -- probes and footprint readings keep everything off it)
                if o and o.g and math.abs(o.g - c.g) > 2.0 and not (TG_LAB_COMPACT and (not o.ok) and math.abs(o.g - c.g) > 6.0) then c.steep = true end
            end
        end
    end
    S.n, S.nok, S.g_here = n, nok, g_here
    return S
end
function tg_lab_cell(S, x, y)
    local i = math.floor((x - S.pos.x) / S.cs + 0.5)
    local j = math.floor((y - S.pos.y) / S.cs + 0.5)
    return S.cells[i * 1000 + j]
end

-- oriented rectangle overlap (2D): r = { C, D (unit), len, wid }
function tg_lab_rect(P, D, x0, x1, hw)
    local c = (x0 + x1) * 0.5
    return { C = tg_tp_add(P, tg_tp_mul(D, c)), D = D, len = (x1 - x0), wid = hw * 2.0 }
end

-- place one combo at P heading h (deg); returns the world parts or nil, why
function tg_lab_fit(C, S, P, h, reserved, prev)
    local D = tg_tp_v(math.cos(math.rad(h)), math.sin(math.rad(h)), 0)
    local Lv = tg_tp_v(-D.y, D.x, 0)
    -- 1) the corridor: every scan cell along it usable, flat enough, not steep
    local corr = tg_lab_rect(P, D, 6.0, C.len, C.hw)
    for _, r in ipairs(reserved) do if r ~= prev and tg_cr_rect_overlap(corr, r) then return nil, "crowded" end end
    local gmin, gmax = 1e9, -1e9
    local x = 0.0
    while x <= C.len do
        for _, y in ipairs({ -C.hw * 0.7, 0.0, C.hw * 0.7 }) do
            local q = tg_tp_add(tg_tp_add(P, tg_tp_mul(D, x)), tg_tp_mul(Lv, y))
            local c = tg_lab_cell(S, q.x, q.y)
            if not c or not c.ok or c.steep then return nil, "ground" end
            gmin, gmax = math.min(gmin, c.g), math.max(gmax, c.g)
        end
        x = x + 10.0
    end
    if gmax - gmin > 6.0 then return nil, "uneven" end
    -- 2) every object: flat footprint, bottom on the lowest ground under it
    local out = {}
    local deck_ref = nil
    for _, p in ipairs(C.parts) do
        local b = tg_lab_bb(p.m)
        local yaw = h + (p.yaw or 0)
        local Dm = tg_tp_v(math.cos(math.rad(yaw)), math.sin(math.rad(yaw)), 0)
        local Lm = tg_tp_v(-Dm.y, Dm.x, 0)
        local O = tg_tp_add(tg_tp_add(P, tg_tp_mul(D, p.x)), tg_tp_mul(Lv, p.y or 0))
        local lo, hi = 1e9, -1e9
        local mx, my = (b[1] + b[4]) * 0.5, (b[2] + b[5]) * 0.5
        for _, o in ipairs({ { b[1], b[2] }, { b[1], b[5] }, { b[4], b[2] }, { b[4], b[5] }, { mx, my },
                             { mx, b[2] }, { mx, b[5] }, { b[1], my }, { b[4], my } }) do
            local q = tg_tp_add(tg_tp_add(O, tg_tp_mul(Dm, o[1])), tg_tp_mul(Lm, o[2]))
            local g = tg_cr_ground_exact(q.x, q.y)
            if not g then return nil, "no ground" end
            -- inside a building (the height map stands well above the ground here)
            local top = tg_rs_height(q.x, q.y) or nil
            if top and (top - g) > 6.0 and not (TG_LAB_COMPACT and math.abs(g - (S.g_here or g)) < 8.0) then return nil, "building" end
            lo, hi = math.min(lo, g), math.max(hi, g)
        end
        if not p.air and (hi - lo) > 1.2 then return nil, "footprint slope" end
        if p.kind == "deck" then deck_ref = lo end
        if p.air and C.kind == "deck" and deck_ref then lo = deck_ref end
        -- bottom of the box on the lowest ground (a hair under it - never floating)
        local z = lo - b[3] - 0.30 + (p.air or 0.0)
        table.insert(out, { m = p.m, x = O.x, y = O.y, z = z, yaw = tg_normalize_heading(yaw), kind = p.kind, ground = lo })
    end
    -- 3) collision probes along the corridor (walls, poles, trees, fences)
    if not TG_CR_PROBES_OFF then
        local x0 = 6.0
        local rays = {}
        while x0 < C.len do
            local x1 = math.min(C.len, x0 + 24.0)
            for _, y in ipairs({ -C.hw * 0.8, 0.0, C.hw * 0.8 }) do
                local a = tg_tp_add(tg_tp_add(P, tg_tp_mul(D, x0)), tg_tp_mul(Lv, y))
                local bq = tg_tp_add(tg_tp_add(P, tg_tp_mul(D, x1)), tg_tp_mul(Lv, y))
                local ga, gb = tg_cr_ground(a.x, a.y) or P.z, tg_cr_ground(bq.x, bq.y) or P.z
                table.insert(rays, { a.x, a.y, ga + 1.6, bq.x, bq.y, gb + 1.6 })
            end
            x0 = x1
        end
        if tg_cr_probe_any(rays) then return nil, "obstacle" end
    end
    -- side hazards (arena): just outside the corridor, only where there's room
    if C.side then
        for k, xs in ipairs({ C.len * 0.35, C.len * 0.65 }) do
            local side = (k % 2 == 0) and 1 or -1
            local q = tg_tp_add(tg_tp_add(P, tg_tp_mul(D, xs)), tg_tp_mul(Lv, side * (C.hw + 9.0)))
            local c = tg_lab_cell(S, q.x, q.y)
            if c and c.ok and not c.steep then
                local m = C.side[math.random(#C.side)]
                local b = tg_lab_bb(m)
                local yaw = tg_normalize_heading(h + 90)
                local Dm = tg_tp_v(math.cos(math.rad(yaw)), math.sin(math.rad(yaw)), 0)
                local r = { C = q, D = Dm, len = (b[4] - b[1]) + 2.0, wid = (b[5] - b[2]) + 2.0 }
                local free = not tg_cr_rect_overlap(r, corr)
                for _, rr in ipairs(reserved) do if free and tg_cr_rect_overlap(r, rr) then free = false end end
                local lo, hi = 1e9, -1e9
                for _, o in ipairs({ { b[1], b[2] }, { b[1], b[5] }, { b[4], b[2] }, { b[4], b[5] } }) do
                    local qx, qy = q.x + Dm.x * o[1] - Dm.y * o[2], q.y + Dm.y * o[1] + Dm.x * o[2]
                    local g = tg_cr_ground_exact(qx, qy)
                    if not g then free = false; break end
                    local tq = tg_rs_height(qx, qy) or nil
                    if tq and (tq - g) > 6.0 then free = false; break end
                    lo, hi = math.min(lo, g), math.max(hi, g)
                end
                local top = tg_rs_height(q.x, q.y) or nil
                if top and lo < 1e8 and (top - lo) > 6.0 then free = false end
                if free and (hi - lo) <= 0.8 then
                    table.insert(out, { m = m, x = q.x, y = q.y, z = lo - b[3] - 0.30, yaw = yaw, kind = "side", side = true, rect = r })
                end
            end
        end
    end
    local exitP = tg_tp_add(P, tg_tp_mul(D, C.len))
    exitP.z = tg_cr_ground(exitP.x, exitP.y) or P.z
    return { parts = out, rect = corr, exitP = exitP, exit_h = h + (C.turn or 0), C = C }
end

function tg_lab_park_plan(kind)
    local def = TG_LAB_PARKS[kind] or TG_LAB_PARKS.mixed
    local arena = (kind == "arena")
    local label = "Stunt Park"
    local limit = tg_rs_limit("lab")
    local pos, psi = tg_lab_frame()
    if not TG_LAB_COMPACT then tg_cr_reset_world() end     -- the compact pass reuses the ground readings
    TG_CR_CTX = { home = { x = pos.x, y = pos.y, z = pos.z } }
    TG_CR_PROBE_FLAGS_CUR = 337     -- parks also keep clear of lamp posts, signs and fences
    util.yield(0)
    local F = tg_tp_v(math.cos(psi), math.sin(psi), 0)
    tg_rs_stage("Scanning area")
    local S = tg_lab_scan(pos, F, label)
    tg_rs_stage("Planning stunt park")
    tg_lab_diag(string.format("park scan: %d cells, %d usable", S.n, S.nok))
    if S.nok < (TG_LAB_COMPACT and 12 or 30) then return nil, "No open flat ground here - try a parking lot, airfield, beach or desert" end
    local wts = {}
    for k, w in pairs(def.combos) do
        -- compact pass: only the combos that fit between buildings
        if not TG_LAB_COMPACT or not TG_LAB_BIG_COMBOS[k] then table.insert(wts, { k = k, w = w }) end
    end
    table.sort(wts, function(a, b) return a.k < b.k end)
    local reserved, combos, objs = {}, {}, 0
    local lines, fails = 0, 0
    local P, h = nil, math.deg(psi)
    local last_kind = nil
    local prev_rect = nil
    -- line starts: in front of you first, then the open cell furthest from everything placed
    local function new_line()
        lines = lines + 1
        if lines == 1 then
            local p = tg_tp_add(tg_tp_v(pos.x, pos.y, pos.z), tg_tp_mul(F, 30.0))
            return p, math.deg(psi)
        end
        -- try open cells (furthest from everything first) with 8 headings each: the first one whose
        -- opening stretch is free starts the line
        local cand = {}
        for k, c in pairs(S.cells) do
            if c.ok and not c.steep then
                local i = math.floor((k + 500) / 1000)
                local j = k - i * 1000
                local q = tg_tp_v(pos.x + i * S.cs, pos.y + j * S.cs, c.g)
                local d = 1e9
                for _, r in ipairs(reserved) do d = math.min(d, tg_tp_len(tg_cr_flat(tg_tp_sub(q, r.C))) - r.len * 0.5 - r.wid * 0.5) end
                if d > 12.0 then table.insert(cand, { q = q, d = d + math.random() * 30.0 }) end
            end
        end
        table.sort(cand, function(x, y) return x.d > y.d end)
        for n = 1, math.min(40, #cand) do
            local q = cand[n].q
            local h0 = math.random() * 360.0
            for k = 0, 7 do
                local hh = h0 + k * 45.0
                local D = tg_tp_v(math.cos(math.rad(hh)), math.sin(math.rad(hh)), 0)
                local r = tg_lab_rect(q, D, 0.0, 70.0, 10.0)
                local free = true
                for _, rr in ipairs(reserved) do if tg_cr_rect_overlap(r, rr) then free = false; break end end
                if free then
                    for x = 0, 70, 10 do
                        local c = tg_lab_cell(S, q.x + D.x * x, q.y + D.y * x)
                        if not c or not c.ok or c.steep then free = false; break end
                    end
                end
                if free then return q, hh end
            end
        end
        return nil
    end
    P, h = new_line()
    while P and objs < limit and fails < 60 and lines <= 16 do
        if tg_rs_plan_progress(label, 2, 2, objs, limit) then return nil, "cancelled" end
        local placed = nil
        for t = 1, 6 do
            local k = tg_cr_pick_w(wts).k
            if k == last_kind and #wts > 1 then k = tg_cr_pick_w(wts).k end
            local C = tg_lab_combo(k, arena, prev_rect ~= nil)
            if objs + #C.parts <= limit then
                for _, dh in ipairs({ 0, (math.random() < 0.5) and 20 or -20, -25, 25, -45, 45, -70, 70, -90, 90 }) do
                    local fit = tg_lab_fit(C, S, P, h + dh, reserved, prev_rect)
                    if fit then placed = fit; break end
                end
            end
            if placed then break end
        end
        if placed then
            -- hard cap: side hazards are the first to go
            while objs + #placed.parts > limit and #placed.parts > 0 and placed.parts[#placed.parts].side do table.remove(placed.parts) end
            if objs + #placed.parts > limit then placed = nil end
        end
        if placed then
            table.insert(reserved, placed.rect)
            prev_rect = placed.rect
            for _, q in ipairs(placed.parts) do if q.rect then table.insert(reserved, q.rect) end end
            table.insert(combos, placed)
            objs = objs + #placed.parts
            last_kind = placed.C.kind
            -- the landing runs straight into the next combo's run-up (stunts aimed at stunts)
            P, h = placed.exitP, placed.exit_h + (-15 + math.random() * 30)
        else
            fails = fails + 1
            prev_rect = nil
            P, h = new_line()
        end
    end
    if #combos == 0 then return nil, "No open flat ground here - try a parking lot, airfield, beach or desert" end
    return { def = def, combos = combos, objs = objs, lines = lines }
end

function tg_lab_park_spawn(B)
    clear_race_track("lab_park")
    local list = {}
    for _, c in ipairs(B.combos) do for _, p in ipairs(c.parts) do table.insert(list, p) end end
    local all = {}
    for _, p in ipairs(list) do table.insert(all, { model = p.m }) end
    tg_rs_preload("Stunt Park", all)
    local keep = TG_CR.animate
    TG_CR.animate = TG_LAB.animate
    local placed, missed = 0, {}
    for i, p in ipairs(list) do
        if tg_rs_spawn_progress("Stunt Park", i, #list, "Spawning") then TG_CR.animate = keep; return false end
        util.yield(TG_LAB.animate and 20 or 60)
        local obj = tg_cr_spawn_obj(p.m, { x = p.x, y = p.y, z = p.z }, 0.0, 0.0, p.yaw, "lab_park_" .. i, false, nil)
        if obj then placed = placed + 1 else table.insert(missed, p) end
    end
    TG_CR.animate = false
    if #missed > 0 and tg_rs_repair then
        placed = placed + tg_rs_repair("Stunt Park", missed, function(p, k)
            return tg_cr_spawn_obj(p.m, { x = p.x, y = p.y, z = p.z }, 0.0, 0.0, p.yaw, "lab_park_fix_" .. k, false, nil)
        end)
    end
    TG_CR.animate = keep
    if tg_rs_check_cancel() then return false end
    tg_tn_settle_all("stunt park")
    local names = {}
    for _, c in ipairs(B.combos) do names[c.C.name] = (names[c.C.name] or 0) + 1 end
    local parts = {}
    for n, k in pairs(names) do table.insert(parts, k .. "x " .. n) end
    table.sort(parts)
    TG_LAB.last = { park = B.def.name, combos = B.combos }
    TG_LAB_NOTICE = nil
    if B.adapt then TG_LAB_NOTICE = { msg = "built - adapted to fit: " .. B.adapt, t = util.current_time_millis() } end
    tg_rs_progress_done(string.format("%s: %d objects", B.def.name, placed))
    tg_cr_toast(string.format("%s: %d objects in %d combos on %d line(s) - %s. Every landing runs into the next jump.%s", B.def.name, placed, #B.combos, B.lines, table.concat(parts, ", "), B.adapt and (" Adapted: " .. B.adapt .. ".") or ""), 8000)
    return placed > 0
end
if tg_tn_wrap then tg_lab_park_spawn = tg_tn_wrap("tg_lab_park_spawn", tg_lab_park_spawn) end
function tg_lab_diag(m) tg_rs_diag("[LAB] " .. tostring(m)) end

function tg_lab_park_build(kind)
    kind = kind or TG_LAB.park or "mixed"
    if not TG_LAB_PARKS[kind] then kind = "mixed" end
    local def = TG_LAB_PARKS[kind]
    tg_rs_build_start("Stunt Park")
    TG_TUBEP_SEED_BUMP = (TG_TUBEP_SEED_BUMP or 0) + 7919
    if math.randomseed then math.randomseed(((os.time and os.time()) or 1) + TG_TUBEP_SEED_BUMP) end
    tg_cr_toast("Scanning the ground ahead for " .. def.name .. "...", 2500)
    -- v2.2.5 adapt like the Home tab's Smart Random loop: a cramped spot doesn't fail - a compact
    -- pass (smaller ramps, shorter run-ups, the street between the buildings) fills what's there
    TG_LAB_COMPACT = false
    local B, why = tg_lab_park_plan(kind)
    if tg_rs_check_cancel() then return false end
    if not B or #B.combos < 3 then
        tg_lab_diag("park: " .. (B and (#B.combos .. " combo(s)") or tostring(why)) .. " - trying the compact pass")
        TG_LAB_COMPACT = true
        local B2, why2 = tg_lab_park_plan(kind)
        TG_LAB_COMPACT = false
        if tg_rs_check_cancel() then return false end
        if B2 and (not B or B2.objs > B.objs) then B = B2; B.adapt = "compact park (small ramps) to fit between the buildings"
        elseif not B then why = why2 end
    end
    TG_LAB_COMPACT = false
    if not B then
        tg_lab_diag("park gave up: " .. tostring(why))
        TG_LAB_NOTICE = { msg = tostring(why), t = util.current_time_millis() }
        if TG_RS_PROG then TG_RS_PROG.active = false end
        TG_RS_RUN_GEN = nil
        return false
    end
    tg_lab_diag(string.format("park planned: %d combos, %d objects, %d lines, probes %d", #B.combos, B.objs, B.lines, TG_CR_BUD.probes))
    return tg_lab_park_spawn(B)
end
-- ---------- 4) Arena Gauntlet: a Hybrid course lined with Arena War hazards ----------
TG_RS_ARENA_POOL = {}
do
    for _, k in ipairs({ "hazards", "barriers", "pads", "targets" }) do
        for _, m in ipairs(TG_RS_CATALOG[k].models) do
            if not m:find("tube", 1, true) and not m:find("landmine", 1, true) then table.insert(TG_RS_ARENA_POOL, m) end
        end
    end
end
function tg_lab_arena_build()
    TG_RS_STUNT_POOL, TG_RS_STUNT_CENTRE, TG_HY_STUNT_P = TG_RS_ARENA_POOL, true, 1.0
    local keep_bag, keep_on = TG_RS_STUNT_BAG, TG_RS_STUNTS_ON
    TG_RS_STUNT_BAG, TG_RS_STUNTS_ON = {}, true
    TG_RS_RADIUS_AS = "lab"         -- v2.3.0: the Lab radius applies to the gauntlet
    local r = tg_hybrid_build("allmix")
    TG_RS_RADIUS_AS = nil
    TG_RS_STUNT_POOL, TG_RS_STUNT_CENTRE, TG_HY_STUNT_P = nil, nil, nil
    TG_RS_STUNT_BAG, TG_RS_STUNTS_ON = keep_bag, keep_on
    return r
end

-- the deck stunt-object bag also gets every catalog barrier / target / small block that isn't in it yet
do
    local have = {}
    for _, m in ipairs(TG_RS_STUNT_MODELS or {}) do have[m] = true end
    for _, k in ipairs({ "barriers", "targets", "blocks", "hazards" }) do
        for _, m in ipairs(TG_RS_CATALOG[k].models) do
            if not have[m] and not m:find("landmine", 1, true) then have[m] = true; table.insert(TG_RS_STUNT_MODELS, m) end
        end
    end
end

