-- builders run in the session's network (freemode) context like every other builder; the ring tick is
-- registered first, from the normal context
if tg_tn_wrap then
    tg_lab_air_build = tg_tn_wrap("tg_lab_air_build", tg_lab_air_build)
    tg_lab_arena_build = tg_tn_wrap("tg_lab_arena_build", tg_lab_arena_build)
end
function tg_lab_air_race() tg_lab_start_tick(); return tg_lab_air_build() end
-- the park plans in its own script job (yields), then spawns in the freemode context
function tg_lab_stunt_park()
    local kind = TG_LAB.park
    if tg_ui_queue_action and not TG_LAB_IN_JOB then
        return tg_ui_queue_action("Stunt Park plan", function()
            TG_LAB_IN_JOB = true
            tg_lab_park_build(kind)
            TG_LAB_IN_JOB = false
            tg_rs_trace_start(15000, "after Lab plan")
        end)
    end
    return tg_lab_park_build(kind)
end
function tg_lab_arena_gauntlet() return tg_lab_arena_build() end
function tg_lab_cycle_park()
    TG_LAB.park = tg_tr_cycle(TG_LAB_PARK_ORDER, TG_LAB.park)
    tg_toast("Stunt Park: " .. TG_LAB_PARKS[TG_LAB.park].name, 2500)
end
function tg_lab_cycle_alt()
    TG_LAB.air_alt = tg_tr_cycle({ "low", "mid", "high" }, TG_LAB.air_alt)
    tg_toast("Air Race height: " .. TG_LAB.air_alt, 2500)
end
