TG_RS_COL = { tubes = { 0.78, 0.45, 1.0 }, track = { 1.0, 0.55, 0.10 }, parkour = { 1.0, 0.30, 0.25 }, hybrid = { 1.0, 0.85, 0.10 }, lab = { 0.0, 0.85, 0.78 } }
