-- ---------- TUBES ----------
function tg_tube_ui_render_panel()
    local sel = TG_TUBER_SEL
    tg_rs_header("tubes", "TUBES")
    tg_rs_limit_ui("tubes")
    tg_rs_sep()
    local R = tg_rs_tube_ranks()
    local entries = TG_UI_TUBE_ENTRIES                       -- v1.2.0 perf: the style list is built once
    if not entries then
        entries = {}
        for _, k in ipairs(TG_TUBER_STYLE_ORDER) do
            local rt = TG_TUBER_TYPES[k]
            local name = (TG_TUBER_STYLE_SHORT and TG_TUBER_STYLE_SHORT[k]) or (rt and rt.name) or k
            if k == "random" then name = "Random" end
            local r = R[k]
            table.insert(entries, { k, name, r and r.tier or nil, r and r.tags or nil })
        end
