-- ---------- TRACK (was Creator) ----------
-- "Random style" honours the difficulty / tag filter that's showing
if tg_cr_variant and not TG_CR_VARIANT_WRAPPED then
    TG_CR_VARIANT_WRAPPED = true
    local orig = tg_cr_variant
    tg_cr_variant = function(cat, id)
        if id == nil or id == "random" then
            local F = TG_RS_FILT and TG_RS_FILT["crvar_" .. tostring(cat)]
            if F and (F.tier ~= "all" or F.tag ~= "any") then
                local pool = {}
                for _, v in ipairs(TG_CR_VARIANTS[cat] or {}) do
                    local ok = (F.tier == "all" or v.tier == F.tier)
                    if ok and F.tag ~= "any" then
                        ok = false
                        for _, t in ipairs(v.tags or {}) do if t == F.tag then ok = true end end
                    end
                    if ok then table.insert(pool, v) end
                end
                if #pool > 0 then return pool[math.random(#pool)] end
            end
        end
        return orig(cat, id)
    end
end
