    end
    if not is_loop_cat and cat ~= "hybrid" then table.insert(chips, { "loop", "Loop" }) end
    for _, c in ipairs({ { "ramp", "Ramp" }, { "animate", "Animation" }, { "barriers", "Barriers" }, { "hills", "Hills" }, { "jumps", "Jumps" }, { "decor", "Decor" } }) do table.insert(chips, c) end
    for i, c in ipairs(chips) do
        tg_rs_toggle_chip("cr_" .. c[1], c[2], TG_CR[c[1]] == true, function() TG_CR[c[1]] = not TG_CR[c[1]] end, 100)
        if i % 6 ~= 0 and i < #chips then tg_rs_same() end
    end
    tg_cc_colour_row("crcolour", TG_CR)
