-- ---------- Saved: category-based file names + a category filter ----------
-- Files are named  <Category>_<Style>_<pieces>p[_Loop]_<yymmdd_HHMM>.tgtrack
--   e.g. Tubes_SkyHigh_62p_261021_2145, Track_StuntRace-RocketVoltic_74p_..., Parkour_Frogger_40p_...
-- Older files (no category) show under "Other".
TG_RS_SAVE_CATS = { "Road", "Tubes", "Track", "Parkour", "Hybrid", "Lab" }
function tg_rs_clean_name(s)
    s = tostring(s or "")
    s = s:gsub("[^%w%- ]", ""):gsub("(%w)(%w*)", function(a, b) return a:upper() .. b end):gsub(" ", "")
    if #s > 28 then s = s:sub(1, 28) end
    return s
end
function tg_rs_save_name(n, is_loop, stamp)
    local last = TG_RS_LAST_BUILD or {}
    local tab = last.tab
    local cat, style = "Road", nil
    if tab == "Tubes" then
        cat = "Tubes"
        local rt = TG_TUBER_TYPES and TG_TUBER_SEL and TG_TUBER_TYPES[TG_TUBER_SEL.style]
        style = rt and rt.name or "Random"
    elseif tab == "Track" then
        cat = "Track"
        local L = TG_CR and TG_CR.last
        if L and L.style then
            local st = TG_CR_STYLES and TG_CR_STYLES[L.style]
            local v = L.variant and tg_cr_variant(L.style, L.variant)
            style = tg_rs_clean_name(st and st.name or L.style) .. ((v and v.name) and ("-" .. tg_rs_clean_name(v.name)) or "")
        end
    elseif tab == "Parkour" then
        cat = "Parkour"
        local st = TG_PK_STYLES and TG_PK_SEL and TG_PK_STYLES[TG_PK_SEL.style]
        style = st and st.name or "Random"
    elseif tab == "Hybrid" then
        cat = "Hybrid"
        style = TG_HY_MIXES and TG_HY_SEL and TG_HY_MIXES[TG_HY_SEL.mix] and TG_HY_MIXES[TG_HY_SEL.mix].name or "Mix"
    elseif tab == "Lab" then
        cat, style = "Lab", last.label
    else
        style = is_loop and "Loop" or "Sprint"
    end
    style = (style and style:find("-", 1, true)) and style or tg_rs_clean_name(style)
    if style == "" then style = "Course" end
    return string.format("%s_%s_%dp%s_%s", cat, style, n, is_loop and "_Loop" or "", tostring(stamp))
end
function tg_rs_save_cat_of(name)
    local c = tostring(name or ""):match("^(%a+)_")
    for _, k in ipairs(TG_RS_SAVE_CATS) do if c == k then return k end end
    return "Other"
end
-- remember which tab the last finished build came from (for the file name)
if tg_rs_progress_done and not TG_RS_DONE_WRAPPED then
    TG_RS_DONE_WRAPPED = true
    local orig = tg_rs_progress_done
    tg_rs_progress_done = function(msg)
        local p = TG_RS_PROG
        if p and p.active and not p.failed then TG_RS_LAST_BUILD = { tab = p.tab, label = p.label, msg = msg } end
        return orig(msg)
    end
end
function tg_render_track_save_dropdown()
    TG_TRACK_SAVE_FILES = TG_TRACK_SAVE_FILES or {}
    TG_TRACK_SAVE_NAMES = TG_TRACK_SAVE_NAMES or {}
    TG_RS_SAVE_FILTER = TG_RS_SAVE_FILTER or "All"
    local count = #TG_TRACK_SAVE_FILES
    -- category chips with counts
    local cnt = { All = count }
    for i = 1, count do local c = tg_rs_save_cat_of(TG_TRACK_SAVE_NAMES[i]); cnt[c] = (cnt[c] or 0) + 1 end
    local chips = { "All" }
    for _, k in ipairs(TG_RS_SAVE_CATS) do table.insert(chips, k) end
    table.insert(chips, "Other")
    local shown = 0
    for _, k in ipairs(chips) do
        if k == "All" or (cnt[k] or 0) > 0 then
            if shown > 0 then tg_rs_same() end
            shown = shown + 1
            local n = tg_ui_push_button_colors(TG_RS_SAVE_FILTER == k) or 0
            local c = ImGui.Button(string.format("%s %d##savecat_%s", k, cnt[k] or 0, k), 96, 24)
            tg_ui_pop_colors(n)
            if c then TG_RS_SAVE_FILTER = k end
        end
    end
    local idx = tonumber(TG_TRACK_SAVE_SELECTED_INDEX or 1) or 1
    if count > 0 then idx = math.max(1, math.min(idx, count)) end
    TG_TRACK_SAVE_SELECTED_INDEX = idx
    local label = (count > 0) and tostring(TG_TRACK_SAVE_NAMES[idx] or "-") or "No saved files - press Refresh"
    if ImGui.BeginCombo("##TrackMaticSavedFile", label) then
            for i = 1, count do
                local name = TG_TRACK_SAVE_NAMES[i]
                if TG_RS_SAVE_FILTER == "All" or tg_rs_save_cat_of(name) == TG_RS_SAVE_FILTER then
                    if ImGui.Selectable(tostring(name), i == idx) then TG_TRACK_SAVE_SELECTED_INDEX = i end
                end
            end
        ImGui.EndCombo()
    end
end

-- ---------- HOME: DriftGod-style dashboard (two columns of cards) ----------
--   left : Last Build | Quick Actions        right: Session | Saved | Minigames
TG_RS_TXT = { header = { 0.74, 0.45, 1.0 }, white = { 0.92, 0.92, 0.96 }, gold = { 1.0, 0.72, 0.25 }, cyan = { 0.35, 0.85, 1.0 },
              green = { 0.40, 0.95, 0.55 }, red = { 1.0, 0.35, 0.30 }, purple = { 0.78, 0.50, 1.0 }, dim = { 0.62, 0.60, 0.70 } }
function tg_rs_ctext(msg, col)
    local c = TG_RS_TXT[col or "white"] or TG_RS_TXT.white
    ImGui.TextColored(c[1], c[2], c[3], 1.0, tostring(msg or ""))
end
-- a ClickGUI card. EndCustomChildWindow is due after every Begin (tg_rs_card_end)
function tg_rs_card(name)
    return ClickGUI.BeginCustomChildWindow(name) == true, true
end
function tg_rs_card_end(real)
    if real then ClickGUI.EndCustomChildWindow() end
end
function tg_rs_rows_body(rows)
    for _, r in ipairs(rows) do
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0); tg_rs_ctext(r[1], "white")
        ImGui.TableSetColumnIndex(1); tg_rs_ctext(r[2], r[3] or "white")
    end
end
function tg_rs_rows(id, rows)
    local ok = false
    local flags = ImGuiTableFlags.SizingStretchSame
    if ImGui.BeginTable(id, 2, flags) then
        tg_rs_rows_body(rows); ImGui.EndTable()
        ok = true
    end
    if not ok then for _, r in ipairs(rows) do tg_rs_ctext(tostring(r[1]) .. ":  " .. tostring(r[2]), r[3] or "white") end end
end
-- a quick action: queue the build and colour the corner HUD by the tab it belongs to
function tg_rs_quick(label, tab, fn, w)
    local n = tg_ui_push_button_colors(true,tab=="Saved" and nil or "Start Game") or 0
    local c = ImGui.Button(label .. "##qa", w or 170, 30)
    tg_ui_pop_colors(n)
    if c then
        TG_RS_NEXT_TAB = tab
        tg_ui_queue_action(label, fn)
        TG_RS_NEXT_TAB = nil
    end
end
function tg_rs_toggle_row(label, on, fn)
    local n = tg_ui_push_button_colors(on == true) or 0
    local c = ImGui.Button((on and "  ON  " or "  OFF ") .. "##tg_" .. label, 56, 24)
    tg_ui_pop_colors(n)
    if c then fn() end
    tg_rs_same()
    tg_rs_ctext(label, "white")
end
function tg_rs_home_status()
    local p = TG_RS_PROG
    if p and p.active and not p.done_at then
        local f = p.frac or 0
        return (f >= 0) and string.format("Building %d%%", math.floor(f * 100 + 0.5)) or "Building", "gold"
    end
    if p and p.failed then return "Last build failed", "red" end
    return "Ready", "green"
end
function tg_rs_count_objects()
    local n = 0
    for _ in pairs(objects or {}) do n = n + 1 end
    return n
end
function tg_ui_render_home()
    local cols = false
    local flags = ImGuiTableFlags.SizingStretchSame
    if ImGui.BeginTable("RS_HomeColumns", 2, flags) then cols = true end
    if cols then tg_ui_render_home_body(true); ImGui.EndTable() else tg_ui_render_home_body(false) end
end
function tg_ui_render_home_body(cols)
    if cols then ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0) end
    -- LEFT: last build
    local open, real = tg_rs_card("Last Build")
    if open then
        tg_rs_ctext("Last Build", "header")
        local L = TG_RS_LAST_BUILD or {}
        local st, sc = tg_rs_home_status()
        local best = (TG_CR_RUN and TG_CR_RUN.best) and string.format("%.2fs", TG_CR_RUN.best) or "-"
        tg_rs_rows("RS_LastBuild", {
            { "Course", tostring(L.label or "None yet"), "gold" },
            { "Tab", tostring(L.tab or "-"), "purple" },
            { "Result", tostring(L.msg or "-"), "cyan" },
            { "Best Time", best, "white" },
            { "Status", st, sc },
        })
    end
    if open or real then tg_rs_card_end(real) end
    -- LEFT: quick actions
    open, real = tg_rs_card("Quick Actions")
    if open then
        tg_rs_ctext("Quick Actions", "header")
