        tg_rs_quick("Track Circuit", "Track", function() TG_CR.style = "circuit"; tg_creator_build("circuit") end)
        tg_rs_quick("Parkour", "Parkour", function() tg_parkour_build_selected() end); tg_rs_same()
        tg_rs_quick("Hybrid", "Hybrid", function() tg_hybrid_build() end)
        tg_rs_quick("Road Loop", "Home", function()
            connector_build_natural_curvy_road({ delay_ms = 90, no_180 = true, top_n = 5, tetris_preview = true, preview_rejects = 0, preview_delay_ms = 90, reject_delay_ms = 30, preview_spin_frames = TG_TETRIS_SPIN_FRAMES, anim_step_ms = TG_TETRIS_STEP_MS })
        end); tg_rs_same()
        tg_rs_quick("Load Latest Save", "Saved", function()
            tg_track_save_refresh_list(true)
