        tg_rs_toggle_row("Build Animation", TG_CR and TG_CR.animate, function() TG_CR.animate = not TG_CR.animate; if TG_LAB then TG_LAB.animate = TG_CR.animate end end)
        tg_rs_toggle_row("Respawn Everyone On Fall", TG_RS_RESPAWN_OTHERS, function() tg_rs_toggle_respawn_others() end)
        tg_rs_toggle_row("Tube Visibility Boost", TG_TUBENET_BOOST, function() tg_tube_net_toggle_boost() end)
        tg_rs_toggle_row("Track Ramp", TG_CR and TG_CR.ramp, function() TG_CR.ramp = not TG_CR.ramp end)
        tg_sm_home_row()
    end
    if open or real then tg_rs_card_end(real) end
    if cols then ImGui.TableSetColumnIndex(1) end
    -- RIGHT: session
    open, real = tg_rs_card("Session")
    if open then
        tg_rs_ctext("Session", "header")
        local rr = {}
        for _, k in ipairs({ "tubes", "creator", "parkour", "hybrid" }) do
            local r = tg_rs_radius(k)
            table.insert(rr, r and (r >= 1000 and string.format("%dk", r / 1000) or tostring(r)) or "-")
        end
        tg_rs_rows("RS_Session", {
            { "Objects Out", tostring(tg_rs_count_objects()), "cyan" },
            { "Object Limit", tostring(tg_rs_hardmax() or 80), "white" },
            { "Radius T/Tr/P/H", table.concat(rr, " / "), "purple" },
            { "Saved Files", tostring(#(TG_TRACK_SAVE_FILES or {})), "gold" },
        })
        tg_ui_button("Clear Track", 130, false, function() tg_rs_clear_all() end); tg_rs_same()
        tg_ui_button("Save Current", 130, false, function() tg_track_save_current() end)
    end
    if open or real then tg_rs_card_end(real) end
    -- RIGHT: saved
    open, real = tg_rs_card("Saved")
    if open then
        tg_rs_ctext("Saved", "header")
        local names = TG_TRACK_SAVE_NAMES or {}
        local shown = 0
        for i = 1, math.min(4, #(TG_TRACK_SAVE_FILES or {})) do
            local nm = tostring(names[i] or "")
