        end
    end
    if open or real then tg_rs_card_end(real) end
end

local function attach_object(parent_obj, child_model, x, y, z, rotX, rotY, rotZ)
    tg_debug("ATTACH", "parent=" .. tg_handle(parent_obj) .. " child=" .. tostring(child_model) .. " offset=" .. string.format("%.3f, %.3f, %.3f", x or 0, y or 0, z or 0) .. " rot=" .. string.format("%.2f, %.2f, %.2f", rotX or 0, rotY or 0, rotZ or 0))
    if not parent_obj then
        return nil
    end

    if TG_MANUAL_ATTACH_MODE then
        local wm = tg_world_from_parent(parent_obj, x, y, z, rotZ)
        tg_debug("ATTACH", "manual_world child=" .. tostring(child_model) .. " world=" .. string.format("%.3f, %.3f, %.3f", wm.x, wm.y, wm.z) .. " heading=" .. string.format("%.2f", wm.heading))
        wm.model = child_model
        connector_apply_track_size_meta(wm, child_model)
        local blocked, block_reason = tg_world_obstacle_probe_meta(wm, parent_obj, "attach_final")
        if blocked then
            tg_warn("OBSTACLE", "final attach veto child=" .. tostring(child_model) .. " reason=" .. tostring(block_reason))
            return nil
        end
        tg_log("[CONNECTOR][ORIENT] parent=" .. tg_handle(parent_obj) .. " childModel=" .. tostring(child_model) .. " parentHeading=" .. string.format("%.2f", (tg_get_meta(parent_obj) and tg_get_meta(parent_obj).heading) or 0.0) .. " relRotZ=" .. tostring(rotZ or 0.0) .. " childHeading=" .. string.format("%.2f", wm.heading))
        local child_obj = create_track_object(child_model, wm.x, wm.y, wm.z, wm.heading)
        if child_obj then
            local cm = tg_get_meta(child_obj) or {}
            cm.parent = parent_obj
            cm.offset = { x = x or 0.0, y = y or 0.0, z = z or 0.0 }
            cm.rot = { x = rotX or 0.0, y = rotY or 0.0, z = rotZ or 0.0 }
            tg_set_meta(child_obj, cm)
            if TG_ENABLE_EXPERIMENTAL_NATIVE_ATTACH then
                ENTITY.ATTACH_ENTITY_TO_ENTITY(child_obj, parent_obj, 0, x, y, z, rotX, rotY, rotZ, false, false, true, false, 2, true, 0)
                tg_debug("ATTACH", "experimental_native_attach child=" .. tg_handle(child_obj))
            else
                tg_warn("ATTACH", "native attach skipped; manual world placement used")
            end
            ENTITY.FREEZE_ENTITY_POSITION(child_obj, true)
        end
        return child_obj
    end

    local child_obj = create_track_object(child_model, 0.0, 0.0, 0.0)
    if child_obj then
        ENTITY.ATTACH_ENTITY_TO_ENTITY(child_obj, parent_obj, 0, x, y, z, rotX, rotY, rotZ, false, false, true, false, 2, true, 0)
        tg_debug("ATTACH", "success child=" .. tg_handle(child_obj) .. " parent=" .. tg_handle(parent_obj))
        ENTITY.FREEZE_ENTITY_POSITION(child_obj, true)
    end
    return child_obj
end


-- Forward declarations used by scoped connector callbacks.
-- These are assigned later by the original function bodies.

