-- v0.2.9 connector fit lab
-- ═══════════════════════════════════════════════════════════════════════════════════
local connector_builder_state = {
    active = false,
    start_obj = nil,
    current_obj = nil,
    current_model = nil,
    current_direction = "left",
    current_heading = 0.0,
    pieces = 0,
    accepted = 0,
    rejected = 0,
    history = {},
}

local function tg_distance2d(a, b)
    if not a or not b then return 999999.0 end
    local dx = (a.x or 0.0) - (b.x or 0.0)
    local dy = (a.y or 0.0) - (b.y or 0.0)
    return math.sqrt(dx * dx + dy * dy)
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.6.7 object size memory / rotated bounds
-- ═══════════════════════════════════════════════════════════════════════════════════
-- memorizes actual/fallback dimensions per track model and uses them for
-- candidate overlap checks instead of treating pieces like simple center points.

function connector_fallback_track_size(model)
    model = tostring(model or "")
    if model == "stt_prop_track_straight_bar_m" then return 53.0, 18.0, 4.0, "fallback_straight" end
    if model == "sum_prop_track_ac_bend_bar_45" then return 42.0, 28.0, 4.0, "fallback_bend45" end
    if model == "sum_prop_track_ac_bend_bar_135" then return 64.0, 54.0, 4.0, "fallback_bend135" end
    if model == "ch_prop_track_bend_bar_lc" then return 55.0, 42.0, 4.0, "fallback_bend90" end
    if model == "sum_prop_track_ac_bend_bar_180d" then return 62.0, 50.0, 4.0, "fallback_bend180" end

    if list_track_fragment then
        for _, frag in ipairs(list_track_fragment) do
            if frag and frag.model == model then
                return tonumber(frag.length or 50.0) or 50.0,
                    tonumber(frag.width or 24.0) or 24.0,
                    4.0,
                    "fallback_fragment_list"
            end
        end
    end

    return 50.0, 24.0, 4.0, "fallback_default"
end

-- length, width, height of a model from the game (MISC shim + v3 buffers)
function connector_native_model_size(model)
    local minv, maxv = v3.new(), v3.new()
    local hash = util.joaat(model)
    MISC.GET_MODEL_DIMENSIONS(hash, minv, maxv)
    local dx = math.abs((maxv.x or 0.0) - (minv.x or 0.0))
    local dy = math.abs((maxv.y or 0.0) - (minv.y or 0.0))
    local dz = math.abs((maxv.z or 0.0) - (minv.z or 0.0))
    return math.max(dx, dy), math.min(dx, dy), dz
end
function connector_track_size(model)
    model = tostring(model or "")
    TG_TRACK_SIZE_CACHE = TG_TRACK_SIZE_CACHE or {}
    if TG_TRACK_SIZE_CACHE[model] then return TG_TRACK_SIZE_CACHE[model] end

    local fl, fw, fh, source = connector_fallback_track_size(model)
    local length, width, height = fl, fw, fh

    if TG_TRACK_SIZE_USE_NATIVE then
        local native_len, native_wid, native_h = connector_native_model_size(model)
        if native_len and native_wid and native_len >= (TG_TRACK_SIZE_SANITY_MIN or 8.0) and native_len <= (TG_TRACK_SIZE_SANITY_MAX or 140.0) and native_wid >= 3.0 then
            -- v0.7.0: Cherax/native dimensions returned 50x50 for every track object in testing,
            -- which is too generic. Use native only when it is meaningfully different from the fallback.
            local generic_square = math.abs((native_len or 0) - 50.0) < 0.25 and math.abs((native_wid or 0) - 50.0) < 0.25
            if not TG_MANUAL_SIZE_OVERRIDE and not generic_square then
                length, width, height = native_len, native_wid, native_h or fh
                source = "native_model_dimensions"
            else
                length, width, height = fl, fw, fh
                source = "fallback_manual_sizefix"
            end
        end
    end

    local info = {
        model = model,
        length = tonumber(length or fl) or fl,
        width = tonumber(width or fw) or fw,
        height = tonumber(height or fh) or fh,
        source = tostring(source or "fallback"),
    }
    info.radius = math.sqrt((info.length * 0.5) * (info.length * 0.5) + (info.width * 0.5) * (info.width * 0.5))
    TG_TRACK_SIZE_CACHE[model] = info

    if TG_SIZE_LOGGING then
        tg_log("[SIZE][MEMO] model=" .. tostring(model) ..
            " length=" .. string.format("%.2f", info.length) ..
            " width=" .. string.format("%.2f", info.width) ..
            " height=" .. string.format("%.2f", info.height) ..
            " radius=" .. string.format("%.2f", info.radius) ..
            " source=" .. tostring(info.source))
    end

    return info
end


function connector_print_track_size_memory(reason)
    reason = reason or "manual"
    TG_TRACK_SIZE_CACHE = TG_TRACK_SIZE_CACHE or {}
    connector_track_size("stt_prop_track_straight_bar_m")
    connector_track_size("sum_prop_track_ac_bend_bar_45")
    connector_track_size("sum_prop_track_ac_bend_bar_135")
    connector_track_size("ch_prop_track_bend_bar_lc")
    connector_track_size("sum_prop_track_ac_bend_bar_180d")
    tg_log("[SIZE][CACHE_BEGIN] reason=" .. tostring(reason))
    for model, info in pairs(TG_TRACK_SIZE_CACHE) do
        tg_log("[SIZE][CACHE] model=" .. tostring(model) ..
            " length=" .. string.format("%.2f", tonumber(info.length or 0) or 0) ..
            " width=" .. string.format("%.2f", tonumber(info.width or 0) or 0) ..
            " height=" .. string.format("%.2f", tonumber(info.height or 0) or 0) ..
            " radius=" .. string.format("%.2f", tonumber(info.radius or 0) or 0) ..
            " source=" .. tostring(info.source or "unknown"))
    end
    tg_log("[SIZE][CACHE_END] reason=" .. tostring(reason))
end

function connector_apply_track_size_meta(meta, model)
    if not meta then return meta end
    local info = connector_track_size(model or meta.model)
    meta.size_length = info.length
    meta.size_width = info.width
    meta.size_height = info.height
    meta.size_radius = info.radius
    meta.size_source = info.source
    return meta
end

function connector_meta_size(meta)
    if not meta then return connector_track_size(nil) end
    if not meta.size_length or not meta.size_width then
        connector_apply_track_size_meta(meta, meta.model)
    end
    return {
        length = tonumber(meta.size_length or 50.0) or 50.0,
        width = tonumber(meta.size_width or 24.0) or 24.0,
        height = tonumber(meta.size_height or 4.0) or 4.0,
        radius = tonumber(meta.size_radius or 28.0) or 28.0,
    }
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.0.1 world / building / prop obstacle avoidance
-- ═══════════════════════════════════════════════════════════════════════════════════
-- this intentionally uses shape-test line probes instead of entity query natives.
-- TrackMatic's Prime-safe branch keeps risky ENTITY query natives disabled,
-- (Natives + Memory shape-test path).

function tg_world_obstacle_is_own_entity(entity)
    if not entity or entity == 0 then return false end
    return tg_get_meta(entity) ~= nil
end

function tg_world_obstacle_free_ptr(ptr)
    if ptr and ptr ~= 0 then
        Memory.Free(ptr)
    end
end

function tg_world_obstacle_read_v3(ptr)
    if not ptr or ptr == 0 then return nil end
    return tg_v3_from_any(Memory.ReadV3(ptr))
end

function tg_world_obstacle_line_probe(x1, y1, z1, x2, y2, z2, ignore_entity, label)
    local handle = invoke_int(
        N.START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE,
        tonumber(x1) or 0.0, tonumber(y1) or 0.0, tonumber(z1) or 0.0,
        tonumber(x2) or 0.0, tonumber(y2) or 0.0, tonumber(z2) or 0.0,
        TG_WORLD_OBSTACLE_FLAGS or 337,
        (type(ignore_entity) == "number" and ignore_entity) or 0,
        7
    )
    if not handle or handle == 0 then return false, nil, 0, "no_handle" end

    local hit_ptr = Memory.AllocInt()
    local end_ptr = Memory.Alloc(24)
    local normal_ptr = Memory.Alloc(24)
    local entity_ptr = Memory.AllocInt()
    local result = invoke_int(N.GET_SHAPE_TEST_RESULT, handle, hit_ptr, end_ptr, normal_ptr, entity_ptr)
    local hit, hit_pos, ent, status = false, nil, 0, "result_" .. tostring(result)
    if result == 2 then
        hit = (tonumber(Memory.ReadInt(hit_ptr) or 0) or 0) ~= 0
        hit_pos = tg_world_obstacle_read_v3(end_ptr)
        ent = tonumber(Memory.ReadInt(entity_ptr) or 0) or 0
        status = "ok"
    end

    tg_world_obstacle_free_ptr(hit_ptr)
    tg_world_obstacle_free_ptr(end_ptr)
    tg_world_obstacle_free_ptr(normal_ptr)
    tg_world_obstacle_free_ptr(entity_ptr)

    return hit, hit_pos, ent, status
end

function tg_world_obstacle_cache_key(meta)
    if not meta then return "nil" end
    return tostring(meta.model or "?") .. "|" ..
        string.format("%.1f|%.1f|%.1f|%.0f|%.1f",
            tonumber(meta.x or 0.0) or 0.0,
            tonumber(meta.y or 0.0) or 0.0,
            tonumber(meta.z or 0.0) or 0.0,
            tonumber(meta.heading or 0.0) or 0.0,
            tonumber(TG_WORLD_OBSTACLE_MARGIN or 2.5) or 2.5)
end

function tg_world_obstacle_probe_meta(meta, ignore_entity, label)
    if TG_WORLD_OBSTACLE_AVOIDANCE == false then return false, "disabled" end
    if not meta or meta.x == nil or meta.y == nil or meta.z == nil then return false, "no_meta" end

    connector_apply_track_size_meta(meta, meta.model)
    local key = tg_world_obstacle_cache_key(meta)
    TG_WORLD_OBSTACLE_PROBE_CACHE = TG_WORLD_OBSTACLE_PROBE_CACHE or {}
    local cached = TG_WORLD_OBSTACLE_PROBE_CACHE[key]
    if cached ~= nil then
        TG_WORLD_OBSTACLE_STATS.cache_hits = (tonumber(TG_WORLD_OBSTACLE_STATS.cache_hits or 0) or 0) + 1
        return cached.blocked == true, tostring(cached.reason or "cached")
    end

    TG_WORLD_OBSTACLE_STATS.checked = (tonumber(TG_WORLD_OBSTACLE_STATS.checked or 0) or 0) + 1

    local size = connector_meta_size(meta)
    local length = math.max(12.0, tonumber(size.length or 50.0) or 50.0)
    local width = math.max(8.0, tonumber(size.width or 24.0) or 24.0)
    local height = math.max(2.0, tonumber(size.height or 4.0) or 4.0)
    local margin = math.max(0.0, tonumber(TG_WORLD_OBSTACLE_MARGIN or 2.5) or 2.5)
    local heading = math.rad(tg_normalize_heading(meta.heading or 0.0))
    local fx, fy = math.cos(heading), math.sin(heading)
    local rx, ry = -fy, fx
    local cx, cy, cz = tonumber(meta.x) or 0.0, tonumber(meta.y) or 0.0, tonumber(meta.z) or 0.0
    local probe_z = cz + math.max(1.8, height * 0.5 + 0.8)
    local half_l = math.max(5.0, length * 0.42)
    local half_w = math.max(4.0, width * 0.48 + margin)
    local long_w = math.max(2.0, margin * 0.5)

    local probes = {
        { "centerline", cx - fx * (half_l + long_w), cy - fy * (half_l + long_w), probe_z, cx + fx * (half_l + long_w), cy + fy * (half_l + long_w), probe_z },
        { "cross_mid", cx - rx * half_w, cy - ry * half_w, probe_z, cx + rx * half_w, cy + ry * half_w, probe_z },
        { "cross_front", cx + fx * (length * 0.28) - rx * half_w, cy + fy * (length * 0.28) - ry * half_w, probe_z, cx + fx * (length * 0.28) + rx * half_w, cy + fy * (length * 0.28) + ry * half_w, probe_z },
        { "cross_rear", cx - fx * (length * 0.28) - rx * half_w, cy - fy * (length * 0.28) - ry * half_w, probe_z, cx - fx * (length * 0.28) + rx * half_w, cy - fy * (length * 0.28) + ry * half_w, probe_z },
        { "vertical_clearance", cx, cy, cz + math.max(12.0, height + 8.0), cx, cy, cz + math.max(1.25, height * 0.35) },
    }

    for _, p in ipairs(probes) do
        local hit, hit_pos, entity_hit, status = tg_world_obstacle_line_probe(p[2], p[3], p[4], p[5], p[6], p[7], ignore_entity, p[1])
        if hit then
            local own = tg_world_obstacle_is_own_entity(entity_hit)
            local ignored = type(ignore_entity) == "number" and ignore_entity ~= 0 and entity_hit == ignore_entity
            if not own and not ignored then
                local reason = tostring(p[1]) .. " entity=" .. tostring(entity_hit or 0)
                if hit_pos then reason = reason .. " hit=" .. tg_vec_str(hit_pos) end
                TG_WORLD_OBSTACLE_PROBE_CACHE[key] = { blocked = true, reason = reason }
                TG_WORLD_OBSTACLE_STATS.blocked = (tonumber(TG_WORLD_OBSTACLE_STATS.blocked or 0) or 0) + 1
                tg_log("[OBSTACLE][BLOCK] label=" .. tostring(label or "candidate") ..
                    " model=" .. tostring(meta.model or "?") ..
                    " reason=" .. reason ..
                    " candidate=" .. tg_vec_str(meta))
                return true, reason
            end
        elseif status == "probe_error" or status == "unavailable" then
            -- Fail open instead of killing generation if the native layer is unavailable.
            TG_WORLD_OBSTACLE_PROBE_CACHE[key] = { blocked = false, reason = status }
            return false, status
        end
    end

    TG_WORLD_OBSTACLE_PROBE_CACHE[key] = { blocked = false, reason = "clear" }
    return false, "clear"
end

function tg_world_obstacle_filter_scored(scored, parent_obj, opts, label)
    opts = opts or {}
    if TG_WORLD_OBSTACLE_AVOIDANCE == false or opts.skip_world_obstacles then return scored end
    if not scored or #scored == 0 then return scored end

    local desired = tonumber(opts.world_obstacle_clear_candidates or opts.top_n or 3) or 3
    desired = math.max(1, math.min(desired, TG_WORLD_OBSTACLE_MAX_CLEAR_CANDIDATES or 5))
    local clear_count = 0
    local ignore_entity = (type(parent_obj) == "number" and parent_obj) or 0

    for _, item in ipairs(scored) do
        if (tonumber(item.score or -99999) or -99999) > -500 then
            local meta = item.meta
            if not meta and parent_obj and item.row then
                meta = tg_world_from_parent(parent_obj, item.row.x, item.row.y, item.row.z, item.row.rotZ)
                meta.model = item.row.child
                meta.direction = item.row.direction
                meta.angle = item.row.angle
                connector_apply_track_size_meta(meta, meta.model)
                item.meta = meta
            end

            if meta then
                local blocked, why = tg_world_obstacle_probe_meta(meta, ignore_entity, tostring(label or "candidate") .. ":" .. tostring(item.row and item.row.child or meta.model))
                item.world_obstacle_checked = true
                item.world_obstacle_blocked = blocked == true
                if blocked then
                    item.score = -12000
                    item.reasons = tostring(item.reasons or "") .. ",worldObstacle=" .. tostring(why)
                else
                    clear_count = clear_count + 1
                    if clear_count >= desired then break end
                end
            else
                item.world_obstacle_checked = true
            end
        end
    end

    table.sort(scored, function(a, b) return (a.score or 0) > (b.score or 0) end)
    return scored
end

function tg_world_obstacle_candidate_is_usable(item, opts)
    opts = opts or {}
    if not item or (tonumber(item.score or -99999) or -99999) <= -500 then return false end
    if TG_WORLD_OBSTACLE_AVOIDANCE == false or opts.skip_world_obstacles then return true end
    return item.world_obstacle_checked == true and item.world_obstacle_blocked ~= true
end

function tg_world_obstacle_status_to_log(reason)
    local st = TG_WORLD_OBSTACLE_STATS or {}
    tg_log("[OBSTACLE][STATUS] reason=" .. tostring(reason or "manual") ..
        " enabled=" .. tostring(TG_WORLD_OBSTACLE_AVOIDANCE ~= false) ..
        " margin=" .. string.format("%.2f", tonumber(TG_WORLD_OBSTACLE_MARGIN or 0.0) or 0.0) ..
        " checked=" .. tostring(st.checked or 0) ..
        " blocked=" .. tostring(st.blocked or 0) ..
        " cacheHits=" .. tostring(st.cache_hits or 0) ..
        " nativeFail=" .. tostring(st.native_fail or 0))
end

function connector_axis_dot(ax, ay, bx, by)
    return (ax or 0.0) * (bx or 0.0) + (ay or 0.0) * (by or 0.0)
end

function connector_obb_axis_gap(a, b, ax, ay, pad)
    local asz = connector_meta_size(a)
    local bsz = connector_meta_size(b)
    local ah = tg_normalize_heading(a.heading or 0.0)
    local bh = tg_normalize_heading(b.heading or 0.0)

    local afx, afy = math.cos(math.rad(ah)), math.sin(math.rad(ah))
    local arx, ary = -afy, afx
    local bfx, bfy = math.cos(math.rad(bh)), math.sin(math.rad(bh))
    local brx, bry = -bfy, bfx

    local ahl = (asz.length * 0.5) + (pad or 0.0)
    local ahw = (asz.width * 0.5) + (pad or 0.0)
    local bhl = (bsz.length * 0.5) + (pad or 0.0)
    local bhw = (bsz.width * 0.5) + (pad or 0.0)

    local cx = (b.x or 0.0) - (a.x or 0.0)
    local cy = (b.y or 0.0) - (a.y or 0.0)

    local dist = math.abs(connector_axis_dot(cx, cy, ax, ay))
    local ra = ahl * math.abs(connector_axis_dot(afx, afy, ax, ay)) + ahw * math.abs(connector_axis_dot(arx, ary, ax, ay))
    local rb = bhl * math.abs(connector_axis_dot(bfx, bfy, ax, ay)) + bhw * math.abs(connector_axis_dot(brx, bry, ax, ay))
    return dist - (ra + rb)
end

function connector_obb_clearance(a, b, pad)
    if not a or not b then return 999999.0, false end
    connector_apply_track_size_meta(a, a.model)
    connector_apply_track_size_meta(b, b.model)

    local ah = tg_normalize_heading(a.heading or 0.0)
    local bh = tg_normalize_heading(b.heading or 0.0)

    local axes = {
        {x=math.cos(math.rad(ah)), y=math.sin(math.rad(ah))},
        {x=-math.sin(math.rad(ah)), y=math.cos(math.rad(ah))},
        {x=math.cos(math.rad(bh)), y=math.sin(math.rad(bh))},
        {x=-math.sin(math.rad(bh)), y=math.cos(math.rad(bh))},
    }

    local best_gap = 999999.0
    local worst_pen = 999999.0
    local separated = false

    for _, axis in ipairs(axes) do
        local gap = connector_obb_axis_gap(a, b, axis.x, axis.y, pad or 0.0)
        if gap > 0.0 then
            separated = true
            if gap < best_gap then best_gap = gap end
        else
            if -gap < worst_pen then worst_pen = -gap end
        end
    end

    if separated then return best_gap, false end
    return -worst_pen, true
end

function connector_size_bounds_penalty(candidate_meta, old_meta, opts, index, is_start)
    opts = opts or {}
    if not candidate_meta or not old_meta then return 0, "", false end

    if is_start and opts.loopback_final then
        -- Final loopback is allowed to touch the first real start piece.
        return 0, "", false
    end

    local hard_pad = tonumber(opts.size_clearance_padding or TG_SIZE_CLEARANCE_PADDING or 5.5) or 5.5
    local soft_pad = tonumber(opts.size_clearance_soft_padding or TG_SIZE_CLEARANCE_SOFT_PADDING or 10.0) or 10.0

    local hard_gap, hard_hit = connector_obb_clearance(candidate_meta, old_meta, hard_pad)
    if hard_hit then
        return TG_SIZE_OVERLAP_PENALTY or -6200,
            "sizeOverlap#" .. tostring(index or "?") .. " gap=" .. string.format("%.1f", hard_gap),
            true
    end

    local soft_gap, soft_hit = connector_obb_clearance(candidate_meta, old_meta, soft_pad)
    if soft_hit then
        local penalty = -math.floor(math.abs(soft_gap) * (TG_SIZE_SOFT_PENALTY_MULT or 38))
        return penalty,
            "sizeNear#" .. tostring(index or "?") .. " gap=" .. string.format("%.1f", soft_gap),
            false
    end

    return 0, "", false
end

local function connector_fragment_dims(model)
    local info = connector_track_size and connector_track_size(model)
    if info then return tonumber(info.length or 50.0) or 50.0, tonumber(info.width or 24.0) or 24.0 end
    return connector_fallback_track_size(model)
end

local function connector_sample_points(meta)
    if not meta then return {} end
    local x, y = tonumber(meta.x or 0.0) or 0.0, tonumber(meta.y or 0.0) or 0.0
    local heading = tg_normalize_heading(meta.heading or 0.0)
    local length, width = connector_fragment_dims(meta.model)
    local fx, fy = math.cos(math.rad(heading)), math.sin(math.rad(heading))
    local rx, ry = -fy, fx
    local l = (tonumber(length) or 50.0) * 0.50
    local w = (tonumber(width) or 24.0) * 0.50
    return {
        {x=x, y=y},
        {x=x + fx*l, y=y + fy*l},
        {x=x - fx*l, y=y - fy*l},
        {x=x + rx*w, y=y + ry*w},
        {x=x - rx*w, y=y - ry*w},
        {x=x + fx*l + rx*w, y=y + fy*l + ry*w},
        {x=x + fx*l - rx*w, y=y + fy*l - ry*w},
        {x=x - fx*l + rx*w, y=y - fy*l + ry*w},
        {x=x - fx*l - rx*w, y=y - fy*l - ry*w},
    }
end

local function connector_min_sample_distance(a, b)
    local pa, pb = connector_sample_points(a), connector_sample_points(b)
    local best = 999999.0
    for _, aa in ipairs(pa) do
        for _, bb in ipairs(pb) do
            local dx = (aa.x or 0.0) - (bb.x or 0.0)
            local dy = (aa.y or 0.0) - (bb.y or 0.0)
            local d = math.sqrt(dx * dx + dy * dy)
            if d < best then best = d end
        end
    end
    return best
end

local function connector_overlap_penalty(candidate_meta, opts)
    opts = opts or {}
    if not candidate_meta then return 0, "", false end
    local h = connector_builder_state.history or {}
    local skip_recent = tonumber(opts.overlap_skip_recent or TG_OVERLAP_SKIP_RECENT or 3) or 3
    local hard_center = tonumber(opts.overlap_center_hard_dist or TG_OVERLAP_CENTER_HARD_DIST or 34.0) or 34.0
    local soft_center = tonumber(opts.overlap_center_soft_dist or TG_OVERLAP_CENTER_SOFT_DIST or 58.0) or 58.0
    local hard_sample = tonumber(opts.overlap_sample_hard_dist or TG_OVERLAP_SAMPLE_HARD_DIST or 18.0) or 18.0
    local soft_sample = tonumber(opts.overlap_sample_soft_dist or TG_OVERLAP_SAMPLE_SOFT_DIST or 31.0) or 31.0
    local pieces = tonumber(connector_builder_state.pieces or #h) or #h

    local worst_penalty = 0
    local reasons = {}
    local hard_reject = false

    for i, hist in ipairs(h) do
        local recent_cutoff = #h - skip_recent + 1
        local is_recent = (i >= recent_cutoff)
        local is_start = (i == 1)
        if hist and hist.obj and not is_recent then
            local old = tg_get_meta(hist.obj) or hist
            if old then
                connector_apply_track_size_meta(candidate_meta, candidate_meta.model)
                connector_apply_track_size_meta(old, old.model)
                local center_d = tg_distance2d(candidate_meta, old)
                local sample_d = connector_min_sample_distance(candidate_meta, old)
                local size_penalty, size_reason, size_hard = connector_size_bounds_penalty(candidate_meta, old, opts, i, is_start)
                if size_penalty ~= 0 then
                    if size_penalty < worst_penalty then worst_penalty = size_penalty end
                    table.insert(reasons, size_reason)
                    if size_hard then hard_reject = true end
                end
                local can_touch_start = is_start and opts.allow_start_close and (pieces >= (opts.loopback_min_pieces or TG_LOOPBACK_MIN_PIECES or 18))
                    and center_d < (opts.loopback_close_dist or TG_LOOPBACK_CLOSE_DIST or 62.0)
                if (center_d < hard_center or sample_d < hard_sample) and not can_touch_start then
                    hard_reject = true
                    worst_penalty = worst_penalty - 1800
                    table.insert(reasons, "hardOverlap#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d) .. " s=" .. string.format("%.1f", sample_d))
                    break
                elseif can_touch_start then
                    worst_penalty = worst_penalty + 650
                    table.insert(reasons, "loopbackStartTouch#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d) .. " s=" .. string.format("%.1f", sample_d))
                elseif center_d < soft_center or sample_d < soft_sample then
                    local p = -220
                    if sample_d < soft_sample then p = p - math.floor((soft_sample - sample_d) * 8) end
                    if center_d < soft_center then p = p - math.floor((soft_center - center_d) * 3) end
                    worst_penalty = worst_penalty + p
                    table.insert(reasons, "softNear#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d) .. " s=" .. string.format("%.1f", sample_d))
                end

                if is_start and not opts.allow_start_close and pieces > 5 then
                    local avoid = tonumber(opts.start_avoid_dist or TG_LOOP_START_AVOID_DIST or 74.0) or 74.0
                    if center_d < avoid then
                        worst_penalty = worst_penalty - 650
                        table.insert(reasons, "avoidEarlyStart=" .. string.format("%.1f", center_d))
                    end
                end
            end
        end
    end

    return worst_penalty, table.concat(reasons, ","), hard_reject
end

local function connector_heading_to(from_meta, to_meta)
    if not from_meta or not to_meta then return 0.0 end
    return tg_normalize_heading(math.deg(math.atan((to_meta.y or 0.0) - (from_meta.y or 0.0), (to_meta.x or 0.0) - (from_meta.x or 0.0))))
end

local function connector_angle_diff(a, b)
    a, b = tg_normalize_heading(a), tg_normalize_heading(b)
    local d = math.abs(a - b) % 360.0
    if d > 180.0 then d = 360.0 - d end
    return d
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.6.4 port / side tracking
-- ═══════════════════════════════════════════════════════════════════════════════════
-- keeps a single live open connector per chain. this prevents choosing the side of a
-- straight/curve that was already used by the previous attached piece.

function connector_port_opposite(side)
    side = tostring(side or "")
    if side == "left" then return "right" end
    if side == "right" then return "left" end
    return "left"
end

function connector_port_is_side(side)
    side = tostring(side or "")
    return side == "left" or side == "right"
end

function connector_port_meta(obj)
    local m = tg_get_meta(obj)
    if not m then return nil end
    m.used_ports = m.used_ports or {}
    return m
end

function connector_port_init(obj, open_side, reason)
    local m = connector_port_meta(obj)
    if not m then return end
    open_side = connector_port_is_side(open_side) and open_side or "left"
    m.used_ports = m.used_ports or {}
    m.open_port = open_side
    tg_set_meta(obj, m)
    if TG_PORT_LOGGING then
        tg_log("[PORT][INIT] reason=" .. tostring(reason or "") .. " obj=" .. tg_handle(obj) .. " open=" .. tostring(open_side))
    end
end

function connector_port_current_open()
    local m = connector_port_meta(connector_builder_state.current_obj)
    local side = m and m.open_port or connector_builder_state.current_direction or "left"
    if not connector_port_is_side(side) then side = "left" end
    return side
end

function connector_port_penalty(row, opts)
    opts = opts or {}
    if not TG_STRICT_CHAIN_PORTS then return 0, "" end
    local parent_obj = connector_builder_state.current_obj
    local parent_m = connector_port_meta(parent_obj)
    if not parent_m then return 0, "" end

    local desired = tostring(row and row.parentDirection or connector_builder_state.current_direction or "left")
    if not connector_port_is_side(desired) then desired = connector_port_current_open() end
    local open_side = connector_port_current_open()

    if parent_m.used_ports and parent_m.used_ports[desired] then
        return -9000, "portUsed=" .. tostring(desired)
    end

    -- The current piece should only be extended from its live open side.
    -- The old code let parentDirection='front' or duplicate straight rows reuse the wrong side.
    if desired ~= open_side then
        return -5000, "wrongOpenPort want=" .. tostring(open_side) .. " row=" .. tostring(desired)
    end

    return 0, ""
end

function connector_resolve_next_open_side(parent_side, row)
    parent_side = connector_port_is_side(parent_side) and parent_side or connector_port_current_open()
    local d = tostring(row and row.direction or "")
    if d == "left" or d == "right" then return d end
    -- Straight/front rows keep the live lane going forward.
    return parent_side
end

function connector_port_mark_attach(parent_obj, child_obj, row, next_side)
    local parent_m = connector_port_meta(parent_obj)
    local child_m = connector_port_meta(child_obj)
    if not parent_m or not child_m then return end

    local parent_side = tostring(row and row.parentDirection or connector_port_current_open())
    if not connector_port_is_side(parent_side) then parent_side = connector_port_current_open() end
    next_side = connector_port_is_side(next_side) and next_side or connector_resolve_next_open_side(parent_side, row)

    parent_m.used_ports = parent_m.used_ports or {}
    parent_m.used_ports[parent_side] = true
    parent_m.closed_port = parent_side
    parent_m.open_port = nil
    tg_set_meta(parent_obj, parent_m)

    child_m.used_ports = child_m.used_ports or {}
    child_m.incoming_port = connector_port_opposite(next_side)
    child_m.used_ports[child_m.incoming_port] = true
    child_m.open_port = next_side
    tg_set_meta(child_obj, child_m)

    if TG_PORT_LOGGING then
        tg_log("[PORT][ATTACH] parent=" .. tg_handle(parent_obj) ..
            " parentUsed=" .. tostring(parent_side) ..
            " child=" .. tg_handle(child_obj) ..
            " childIncoming=" .. tostring(child_m.incoming_port) ..
            " childOpen=" .. tostring(next_side))
    end
end

function connector_port_reopen_current_after_backtrack(entry)
    if not entry or not entry.obj then return end
    local m = connector_port_meta(entry.obj)
    if not m then return end
    local open_side = tostring(entry.open_side or m.open_port or connector_builder_state.current_direction or "left")
    if not connector_port_is_side(open_side) then open_side = "left" end
    m.used_ports = m.used_ports or {}
    m.used_ports[open_side] = nil
    m.open_port = open_side
    tg_set_meta(entry.obj, m)
    if TG_PORT_LOGGING then
        tg_log("[PORT][REOPEN] obj=" .. tg_handle(entry.obj) .. " open=" .. tostring(open_side))
    end
end

local function connector_reset_state()
    connector_builder_state.active = false
    connector_builder_state.start_obj = nil
    connector_builder_state.current_obj = nil
    connector_builder_state.current_model = nil
    connector_builder_state.current_direction = "left"
    connector_builder_state.current_heading = 0.0
    connector_builder_state.pieces = 0
    connector_builder_state.accepted = 0
    connector_builder_state.rejected = 0
    connector_builder_state.history = {}
    connector_builder_state.first_real_obj = nil
    connector_builder_state.no_starter_seed_obj = nil
end

local function connector_candidate_list(parent_model, parent_direction, opts)
    opts = opts or {}
    local list = {}
    parent_direction = parent_direction or "left"
    for _, f in ipairs(attached_formation or {}) do
        if f.parent == parent_model then
            local direction_ok = (f.parentDirection == parent_direction) or (parent_direction == "front") or (f.parentDirection == "front")
            if direction_ok then
                local include = true
                local angle_abs = math.abs(tonumber(f.angle or 0) or 0)
                if opts.no_180 and angle_abs == 180 then include = false end
                if opts.no_front and f.direction == "front" then include = false end
                if opts.only_front and f.direction ~= "front" then include = false end
                if opts.min_turn_angle and f.direction ~= "front" and angle_abs < tonumber(opts.min_turn_angle) then include = false end
                if opts.max_turn_angle and f.direction ~= "front" and angle_abs > tonumber(opts.max_turn_angle) then include = false end
                if opts.only_turn_direction and tostring(f.direction or "") ~= tostring(opts.only_turn_direction) then include = false end
                if include then table.insert(list, f) end
            end
        end
    end
    return list
end


function connector_deadend_round(v)
    v = tonumber(v or 0.0) or 0.0
    return tostring(math.floor((v * 10.0) + 0.5) / 10.0)
end

function connector_deadend_key(parent_obj, parent_direction, f)
    if not f then return "nil" end
    return tg_handle(parent_obj) ..
        "|dir=" .. tostring(parent_direction or "") ..
        "|child=" .. tostring(f.child or "") ..
        "|row=" .. tostring(f.direction or "") ..
        "|x=" .. connector_deadend_round(f.x) ..
        "|y=" .. connector_deadend_round(f.y) ..
        "|rz=" .. connector_deadend_round(f.rotZ)
end

function connector_deadend_is_blocked(parent_obj, parent_direction, f)
    local key = connector_deadend_key(parent_obj, parent_direction, f)
    return TG_DEADEND_CANDIDATES and TG_DEADEND_CANDIDATES[key] == true, key
end

function connector_deadend_mark(entry, reason)
    if not entry then return false end
    local key = entry.dead_key
    if not key and entry.parent_obj and entry.attach then
        key = connector_deadend_key(entry.parent_obj, entry.parent_direction, entry.attach)
    end
    if not key then return false end
    TG_DEADEND_CANDIDATES = TG_DEADEND_CANDIDATES or {}
    TG_DEADEND_CANDIDATES[key] = true
    tg_log("[DEADEND][MARK] reason=" .. tostring(reason or "blocked") ..
        " key=" .. tostring(key) ..
        " child=" .. tostring(entry.model or (entry.attach and entry.attach.child)))
    return true
end

function connector_start_guard_meta()
    if connector_builder_state then
        -- v0.6.9 snake mode: the "start touch" target is the rear goal piece,
        -- while generation starts from the front launch piece.
        if connector_builder_state.loop_target_obj then
            local m = tg_get_meta(connector_builder_state.loop_target_obj)
            if m and m.x and m.y then return m end
        end
        if connector_builder_state.first_real_obj then
            local m = tg_get_meta(connector_builder_state.first_real_obj)
            if m and m.x and m.y then return m end
        end
        if connector_builder_state.start_obj then
            local m = tg_get_meta(connector_builder_state.start_obj)
            if m and m.x and m.y then return m end
        end
        local h = connector_builder_state.history or {}
        if h[1] and h[1].obj then
            local m = tg_get_meta(h[1].obj)
            if m and m.x and m.y then return m end
        end
    end
    return nil
end


function connector_turn_sign_from_entry(entry)
    if not entry then return 0 end
    local attach = entry.attach
    local rz = attach and tonumber(attach.rotZ or 0.0) or 0.0
    if rz > 10.0 and rz < 180.0 then return 1 end
    if rz < -10.0 or rz > 180.0 then return -1 end
    return 0
end

function connector_recent_turn_signs()
    local h = connector_builder_state and connector_builder_state.history or {}
    local a = connector_turn_sign_from_entry(h[#h])
    local b = connector_turn_sign_from_entry(h[#h - 1])
    local c = connector_turn_sign_from_entry(h[#h - 2])
    return a, b, c
end

function connector_candidate_turn_sign(f)
    if not f then return 0 end
    local rz = tonumber(f.rotZ or 0.0) or 0.0
    if math.abs(rz) < 10.0 or tostring(f.direction or "") == "front" then return 0 end
    if rz > 0.0 and rz < 180.0 then return 1 end
    return -1
end

function connector_score_candidate(f, opts)
    opts = opts or {}
    local score = 100
    local reasons = {}
    local angle = math.abs(tonumber(f.angle or 0) or 0)
    local dir = tostring(f.direction or "")
    local child = tostring(f.child or "")

    local function add(delta, why)
        score = score + delta
        if why then table.insert(reasons, why .. (delta >= 0 and "+" or "") .. tostring(delta)) end
    end

    if angle == 0 or dir == "front" then add(24, "straight") end
    if angle == 45 then add(18, "gentle45") end
    if angle == 90 then add(8, "turn90") end
    if angle == 135 then add(-18, "sharp135") end
    if angle >= 180 then add(-80, "avoid180") end

    if opts.prefer_turns and dir ~= "front" then add(20, "prefer_turn") end
    if opts.prefer_gentle_turns and dir ~= "front" then
        if angle == 45 then add(125, "minigameGentle45")
        elseif angle == 90 then add(70, "minigameGentle90")
        elseif angle >= 135 then add(-260, "minigameAvoidSharp") end
    end
    if opts.prefer_sharp_turns and dir ~= "front" then
        if angle == 90 then add(85, "minigameSharp90")
        elseif angle == 135 then add(125, "minigameSharp135")
        elseif angle == 45 then add(-20, "minigameLess45") end
    end
    if opts.prefer_straight then
        if dir == "front" then add(55, "prefer_straight") else add(-25, "not_straight") end
    end
    if opts.snake_force_straight then
        if dir == "front" then add(260, "forceStraightRun") else add(-340, "forceStraightNoCurve") end
    end

    if opts.natural_road then
        if dir == "front" then
            add(TG_ROAD_STRAIGHT_SCORE or -20, "roadStraightBias")
        else
            add(TG_ROAD_CURVE_SCORE or 135, "roadCurveBias")
        end
        if opts.road_force_curve and dir == "front" then add(TG_ROAD_FORCE_CURVE_PENALTY or -1200, "roadForceCurve") end
        if opts.road_force_straight and dir ~= "front" then add(TG_ROAD_FORCE_STRAIGHT_PENALTY or -420, "roadNeedStraight") end
        if angle == 45 then add(60, "roadGentle45") end
        if angle == 90 then add(45, "roadCorner90") end
        if angle == 135 then add(TG_ROAD_SHARP_TURN_PENALTY or -210, "roadAvoidSharpStar") end
        if angle >= 180 then add(-650, "roadNoHairpin") end
    end

    -- v0.6.9 snake rhythm: give the route actual straightaways instead of endless curves.
    -- Only applies during the outbound/random section; loopback_final still prioritizes returning.
    if opts.snake_straight_rhythm and not opts.loopback_final and not opts.prefer_towards_target then
        local hist_count = #(connector_builder_state.history or {})
        local every = tonumber(TG_SNAKE_STRAIGHT_EVERY or 4) or 4
        local window = tonumber(TG_SNAKE_STRAIGHT_WINDOW or 2) or 2
        local opening = tonumber(TG_SNAKE_OPENING_STRAIGHT_BIAS_PIECES or 8) or 8
        local want_straight = (hist_count <= opening) or ((hist_count % every) < window)
        if want_straight then
            if dir == "front" then
                add(TG_SNAKE_STRAIGHT_BONUS or 78, "snakeStraight")
            else
                add(TG_SNAKE_CURVE_HOLD_PENALTY or -34, "snakeHoldCurve")
            end
        end
    end

    if TG_ANTI_WIGGLE_ENABLED and opts.snake_straight_rhythm and not opts.loopback_final and not opts.prefer_towards_target then
        local cand_sign = connector_candidate_turn_sign(f)
        local last1, last2, last3 = connector_recent_turn_signs()
        local hist_count = #(connector_builder_state.history or {})
        if dir == "front" and (last1 ~= 0 or last2 ~= 0) then
            add(TG_ANTI_WIGGLE_STRAIGHT_AFTER_TURN_BONUS or 165, "antiWiggleStraight")
        elseif cand_sign ~= 0 then
            if last1 ~= 0 and cand_sign ~= last1 then
                add(TG_ANTI_WIGGLE_ALT_TURN_PENALTY or -260, "antiWiggleAltTurn")
            end
            if last1 ~= 0 and last2 ~= 0 and cand_sign ~= last1 and last1 ~= last2 then
                add(-420, "antiWiggleZigZag3")
            end
            if last1 ~= 0 and cand_sign == last1 then
                add(TG_ANTI_WIGGLE_SAME_TURN_PENALTY or -95, "antiWiggleSameTurn")
            end
            if hist_count < 10 then
                add(-120, "antiEarlyCurveSpam")
            end
        end
    end

    local h = connector_builder_state.history or {}
    local last = h[#h]
    local prev = h[#h - 1]
    if last and last.model == child then add(-22, "same_model") end
    if last and prev and last.model == child and prev.model == child then add(-55, "same_model_x3") end
    if dir ~= "front" and last and prev and last.direction == dir and prev.direction == dir then add(-45, "turn_spiral") end
    if dir ~= "front" and last and last.direction == dir and angle >= 90 then add(-18, "repeat_side") end

    local parent_obj = connector_builder_state.current_obj
    if parent_obj then
        local wm = tg_world_from_parent(parent_obj, f.x, f.y, f.z, f.rotZ)
        wm.model = f.child
        wm.direction = f.direction
        wm.angle = f.angle

        local blocked, dead_key = connector_deadend_is_blocked(parent_obj, connector_builder_state.current_direction, f)
        if blocked then
            add(TG_DEADEND_PENALTY or -9000, "deadEndBlocked")
        end

        local start_guard_meta = connector_start_guard_meta()
        if start_guard_meta and not opts.loopback_final then
            local hist_count = #(connector_builder_state.history or {})
            local guard_dist = tonumber(opts.start_guard_dist or TG_START_GUARD_RANDOM_DIST or 150.0) or 150.0
            if opts.legacy_smart_clearance then
                guard_dist = tonumber(opts.start_guard_dist or TG_START_GUARD_SMART_DIST or 135.0) or 135.0
            end
            local cur_start_d = tg_distance2d(tg_get_meta(parent_obj), start_guard_meta)
            local cand_start_d = tg_distance2d(wm, start_guard_meta)

            if hist_count > 3 and cand_start_d < guard_dist then
                add(-4200, "startGuard=" .. string.format("%.1f", cand_start_d))
            end

            local no_return_until = tonumber(opts.no_return_until_pieces or TG_SMART_NO_RETURN_UNTIL_PIECES or 24) or 24
            if hist_count < no_return_until and cand_start_d < (cur_start_d - 35.0) then
                add(-1800, "earlyReturnToStart=" .. string.format("%.1f", cand_start_d))
            end
        end

        if opts.legacy_smart_clearance then
            local pm = tg_get_meta(parent_obj)
            local parent_model = tostring(pm and pm.model or connector_builder_state.current_model or "")
            local parent_child_dist = tg_distance2d(wm, pm)
            if parent_model == "stt_prop_track_straight_bar_m" and angle > 0 and parent_child_dist < (opts.parent_turn_min_dist or TG_LEGACY_SMART_PARENT_TURN_MIN_DIST or 46.0) then
                add(-650, "parentTurnTooClose=" .. string.format("%.1f", parent_child_dist))
            end
            if parent_model == "stt_prop_track_straight_bar_m" and child == "sum_prop_track_ac_bend_bar_45" then
                add(-450, "discourageHalfBack45FromStraight")
            end
        end

        local port_penalty, port_reason = connector_port_penalty(f, opts)
        if port_penalty ~= 0 then add(port_penalty, port_reason) end

        if opts.loop_bounds then
            local origin = opts.loop_origin_meta or connector_start_guard_meta() or connector_loop_target_meta()
            if origin and origin.x and origin.y and wm and wm.x and wm.y then
                local dx = math.abs((wm.x or 0.0) - (origin.x or 0.0))
                local dy = math.abs((wm.y or 0.0) - (origin.y or 0.0))
                local max_x = tonumber(opts.loop_bound_max_x or 160.0) or 160.0
                local max_y = tonumber(opts.loop_bound_max_y or 180.0) or 180.0
                if dx > max_x or dy > max_y then
                    add(opts.loop_bound_penalty or TG_LOOP15_BOUND_PENALTY or -6500, "loopBounds=" .. string.format("%.0f", dx) .. "x" .. string.format("%.0f", dy))
                elseif dir ~= "front" and (dx > max_x * 0.72 or dy > max_y * 0.72) then
                    add(TG_LOOP15_NEAR_BOUND_TURN_BONUS or 360, "nearBoundTurn")
                end
            end
        end

        connector_apply_track_size_meta(wm, wm.model)
        local overlap_penalty, overlap_reason, hard_overlap = connector_overlap_penalty(wm, opts)
        if overlap_penalty ~= 0 then add(overlap_penalty, overlap_reason or "overlap_guard") end
        if hard_overlap then add(-900, "strictHardReject") end

        if opts.target_meta then
            local before = tg_distance2d(tg_get_meta(parent_obj), opts.target_meta)
            local after = tg_distance2d(wm, opts.target_meta)
            local gain = before - after
            if opts.prefer_towards_target then
                local mult = opts.loopback_final and (TG_LOOPBACK_SCORE_MULT or 8.0) or 4
                add(math.floor(gain * mult), "towardTarget=" .. string.format("%.1f", gain))
                if opts.loopback_final then
                    if after < (opts.loopback_close_dist or TG_LOOPBACK_CLOSE_DIST or 62.0) then add(1400, "loopbackNearStart=" .. string.format("%.1f", after)) end
                    if gain < -4.0 then add(-420, "loopbackAway") end
                elseif gain < -8.0 then add(-180, "awayFromTarget") end
            else
                add(math.floor(gain * 1.2), "mildTarget=" .. string.format("%.1f", gain))
            end
            if opts.allow_start_close and after < (opts.close_dist or TG_LOOP_CLOSE_DIST or 28.0) then
                add(900, "closeStart=" .. string.format("%.1f", after))
            end
        end
    end

    return score, table.concat(reasons, ",")
end

local function connector_pick_candidate(parent_model, parent_direction, opts)
    opts = opts or {}
    local candidates = connector_candidate_list(parent_model, parent_direction, opts)
    if #candidates == 0 and opts.prefer_turns then
        opts.prefer_turns = false
        candidates = connector_candidate_list(parent_model, parent_direction, opts)
    end
    if #candidates == 0 then return nil, 0 end

    local scored = {}
    for _, f in ipairs(candidates) do
        local score, reasons = connector_score_candidate(f, opts)
        table.insert(scored, { row = f, score = score, reasons = reasons })
    end
    table.sort(scored, function(a, b) return (a.score or 0) > (b.score or 0) end)
    tg_world_obstacle_filter_scored(scored, connector_builder_state and connector_builder_state.current_obj or nil, opts, "live_pick")

    local usable = {}
    for _, item in ipairs(scored) do
        if tg_world_obstacle_candidate_is_usable(item, opts) then table.insert(usable, item) end
    end
    if #usable == 0 then
        local top = scored[1]
        if TG_WORLD_OBSTACLE_AVOIDANCE ~= false and not opts.skip_world_obstacles then
            if top then tg_warn("OBSTACLE", "all candidate routes blocked or rejected; refusing to build through world geometry top=" .. tostring(top.row and top.row.child) .. " reasons=" .. tostring(top.reasons)) end
            return nil, #candidates, scored, nil
        elseif opts.legacy_smart_clearance and TG_LEGACY_SMART_ALLOW_SAFE_FALLBACK ~= false then
            -- v0.6.0: Smart Random should not choke after a few pieces.
            -- If strict clearance rejects everything, use the least-bad candidate unless it is a true hard overlap.
            local reasons = tostring(top and top.reasons or "")
            local unsafe = reasons:find("hardOverlap", 1, true) or reasons:find("centerHard", 1, true)
                or reasons:find("strictHardReject", 1, true) or reasons:find("portUsed", 1, true)
                or reasons:find("wrongOpenPort", 1, true)
            if top and not unsafe then
                tg_warn("CONNECTOR", "legacy-smart fallback using least-bad candidate child=" .. tostring(top.row.child) .. " score=" .. tostring(top.score) .. " reasons=" .. tostring(top.reasons))
                usable = { top }
            else
                if top then tg_warn("CONNECTOR", "legacy-smart all candidates blocked; not forcing unsafe overlap child=" .. tostring(top.row.child) .. " score=" .. tostring(top.score) .. " reasons=" .. tostring(top.reasons)) end
                return nil, #candidates, scored, nil
            end
        elseif opts.strict_overlap then
            if top then tg_warn("CONNECTOR", "all candidates rejected by strict guard; stopping instead of forcing overlap child=" .. tostring(top.row.child) .. " score=" .. tostring(top.score) .. " reasons=" .. tostring(top.reasons)) end
            return nil, #candidates, scored, nil
        else
            if top then tg_warn("CONNECTOR", "all candidates rejected; using best bad candidate child=" .. tostring(top.row.child) .. " score=" .. tostring(top.score) .. " reasons=" .. tostring(top.reasons)) end
            usable = scored
        end
    end

    local top_n = math.min(#usable, opts.top_n or 3)
    local pick_index = 1
    if top_n > 1 then pick_index = math.random(top_n) end
    local chosen = usable[pick_index]
    local best = usable[1]
    if chosen then
        tg_log("[CONNECTOR][PICK] parent=" .. tostring(parent_model) ..
            " dir=" .. tostring(parent_direction) ..
            " candidates=" .. tostring(#candidates) ..
            " usable=" .. tostring(#usable) ..
            " chosen=" .. tostring(chosen.row.child) ..
            " score=" .. tostring(chosen.score) ..
            " reasons=" .. tostring(chosen.reasons) ..
            " best=" .. tostring(best and best.row and best.row.child) ..
            " bestScore=" .. tostring(best and best.score))
        return chosen.row, #candidates, scored, chosen
    end
    local fallback = candidates[math.random(#candidates)]
    return fallback, #candidates, scored, nil
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.3.8 animated tetris preview + loop builder helpers
-- ═══════════════════════════════════════════════════════════════════════════════════
function connector_create_preview_object(model, x, y, z, heading, label)
    label = label or "preview"
    x, y, z = tonumber(x) or 0.0, tonumber(y) or 0.0, tonumber(z) or 0.0
    z = z + (tonumber(TG_TRACK_HEIGHT_OFFSET or 0.0) or 0.0)
    heading = tg_normalize_heading(heading)
    tg_debug("TETRIS", "preview_create label=" .. tostring(label) .. " model=" .. tostring(model) .. " pos=" .. string.format("%.3f,%.3f,%.3f", x, y, z) .. " heading=" .. string.format("%.2f", heading))
    util.request_model(util.joaat(model))
    local obj = entities.create_object(util.joaat(model), v3(x, y, z))
    if not obj or obj == 0 then
        tg_warn("TETRIS", "preview create failed model=" .. tostring(model))
        return nil
    end
    tg_set_meta(obj, { model = model, x = x, y = y, z = z, heading = heading, preview = true })
    ENTITY.SET_ENTITY_HEADING(obj, heading)
    return obj
end

function connector_delete_preview_object(obj, label)
    label = label or "preview_delete"
    if not obj or obj == 0 then return end
    entities.delete_by_handle(obj)
    tg_debug("TETRIS", "preview_deleted label=" .. tostring(label) .. " obj=" .. tg_handle(obj))
end

function connector_short_heading_delta(from_h, to_h)
    from_h = tg_normalize_heading(from_h)
    to_h = tg_normalize_heading(to_h)
    local delta = (to_h - from_h + 540.0) % 360.0 - 180.0
    return delta
end

function connector_random_preview_start_heading(target_heading, opts, accepted)
    opts = opts or {}
    target_heading = tg_normalize_heading(target_heading)
    if opts.random_animation == false or TG_TETRIS_RANDOM_ANIM == false then
        return tg_normalize_heading(target_heading + (accepted and -90.0 or 90.0))
    end
    local spins = { -270.0, -225.0, -180.0, -135.0, -90.0, 90.0, 135.0, 180.0, 225.0, 270.0 }
    local spin = spins[math.random(#spins)]
    -- Rejected pieces wiggle harder; accepted pieces usually take a cleaner path into place.
    if not accepted and math.random(100) <= 45 then spin = spin * 1.25 end
    return tg_normalize_heading(target_heading + spin)
end

function connector_animate_preview_heading(obj, start_heading, target_heading, opts, label, accepted)
    opts = opts or {}
    if not obj or obj == 0 then return end
    local frames = tonumber(opts.preview_spin_frames or TG_TETRIS_SPIN_FRAMES or 6) or 6
    if frames < 1 then frames = 1 end
    local step_ms = tonumber(opts.anim_step_ms or TG_TETRIS_STEP_MS or 45) or 45
    start_heading = tg_normalize_heading(start_heading)
    target_heading = tg_normalize_heading(target_heading)
    local delta = connector_short_heading_delta(start_heading, target_heading)
    tg_log("[TETRIS][ANIM] label=" .. tostring(label) .. " obj=" .. tg_handle(obj) .. " startHeading=" .. string.format("%.2f", start_heading) .. " targetHeading=" .. string.format("%.2f", target_heading) .. " frames=" .. tostring(frames) .. " random=" .. tostring(TG_TETRIS_RANDOM_ANIM) .. " accepted=" .. tostring(accepted == true))
    for i = 1, frames do
        if TG_CANCEL_GENERATION then break end
        local t = i / frames
        -- Ease-out: big movement at first, smaller snap near the lock point.
        local eased = 1.0 - ((1.0 - t) * (1.0 - t))
        local h = tg_normalize_heading(start_heading + delta * eased)
        ENTITY.SET_ENTITY_HEADING(obj, h)
        util.yield(step_ms)
    end
    ENTITY.SET_ENTITY_HEADING(obj, target_heading)
end

function connector_heading_to(from_meta, to_meta)
    if not from_meta or not to_meta then return 0.0 end
    local dx = (to_meta.x or 0.0) - (from_meta.x or 0.0)
    local dy = (to_meta.y or 0.0) - (from_meta.y or 0.0)
    local atan2 = math.atan2 or math.atan
    return tg_normalize_heading(math.deg(atan2(dy, dx)))
end

function connector_preview_one_candidate(parent_obj, item, chosen_row, opts, label, ordinal)
    if not item or not item.row then return false end
    opts = opts or {}
    local row = item.row
    local wm = tg_world_from_parent(parent_obj, row.x, row.y, row.z, row.rotZ)
    local lift = tonumber(opts.preview_lift or 1.45) or 1.45
    local accepted = (row == chosen_row)
    local outcome = accepted and "LOCK_NEXT" or "REJECT_VISUAL"
    local target_heading = tg_normalize_heading(wm.heading)
    local start_heading = connector_random_preview_start_heading(target_heading, opts, accepted)
    local obj = connector_create_preview_object(row.child, wm.x, wm.y, wm.z + lift, start_heading, label)
    tg_log("[TETRIS][TRY] label=" .. tostring(label) ..
        " #" .. tostring(ordinal or 1) ..
        " outcome=" .. outcome ..
        " child=" .. tostring(row.child) ..
        " rowDir=" .. tostring(row.direction) ..
        " angle=" .. tostring(row.angle) ..
        " score=" .. tostring(item.score) ..
        " startHeading=" .. string.format("%.2f", start_heading) ..
        " lockHeading=" .. string.format("%.2f", target_heading) ..
        " reasons=" .. tostring(item.reasons))
    connector_animate_preview_heading(obj, start_heading, target_heading, opts, label .. "_" .. outcome, accepted)
    util.yield(opts.preview_delay_ms or 220)
    connector_delete_preview_object(obj, label .. "_" .. outcome)
    if not accepted then util.yield(opts.reject_delay_ms or 90) end
    return accepted
end

function connector_preview_candidate_sequence(parent_obj, scored, chosen_row, opts, label)
    opts = opts or {}
    if not opts.tetris_preview then return end
    scored = scored or {}
    local reject_limit = tonumber(opts.preview_rejects or 2) or 2
    local shown_rejects = 0
    local shown_chosen = false
    local ordinal = 1
    tg_log("[TETRIS][BEGIN] label=" .. tostring(label) .. " scored=" .. tostring(#scored) .. " rejectPreviews=" .. tostring(reject_limit) .. " delayMs=" .. tostring(opts.preview_delay_ms or 320))
    for _, item in ipairs(scored) do
        if item and item.row then
            if item.row == chosen_row then
                connector_preview_one_candidate(parent_obj, item, chosen_row, opts, label, ordinal)
                shown_chosen = true
                ordinal = ordinal + 1
                break
            elseif shown_rejects < reject_limit then
                connector_preview_one_candidate(parent_obj, item, chosen_row, opts, label, ordinal)
                shown_rejects = shown_rejects + 1
                ordinal = ordinal + 1
            end
        end
    end
    if not shown_chosen and chosen_row then
        connector_preview_one_candidate(parent_obj, { row = chosen_row, score = "chosen", reasons = "chosen_not_in_preview_window" }, chosen_row, opts, label, ordinal)
    end
    tg_log("[TETRIS][END] label=" .. tostring(label) .. " shownRejects=" .. tostring(shown_rejects) .. " shownLock=" .. tostring(shown_chosen or chosen_row ~= nil))
end

function tg_apply_track_rotation(obj, pitch, roll, yaw, label)
    if not obj or obj == 0 then return false end
    pitch = tonumber(pitch or 0.0) or 0.0
    roll = tonumber(roll or 0.0) or 0.0
    yaw = tg_normalize_heading(yaw or 0.0)
    Natives.InvokeVoid(N.SET_ENTITY_ROTATION, obj, pitch, roll, yaw, 2, true)
    local meta = tg_get_meta(obj) or {}
    meta.pitch = pitch
    meta.roll = roll
    meta.heading = yaw
    meta.aoa = tonumber(meta.aoa or 0.0) or 0.0
    tg_set_meta(obj, meta)
    return true
end

-- Apply a true local Angle of Attack while keeping the track perfectly level side-to-side.
-- Track straight pieces travel along their local X axis. A local-Y rotation raises/lowers
-- that X axis without banking the road. We compose local-Y AoA with world-Z yaw explicitly
-- as a quaternion so camera heading cannot turn the climb into a sideways tilt.
function tg_apply_track_aoa(obj, aoa_deg, yaw, label)
    if not obj or obj == 0 then return false end
    aoa_deg = math.abs(tonumber(aoa_deg or 0.0) or 0.0)
    yaw = tg_normalize_heading(yaw or 0.0)

    local yaw_half = math.rad(yaw) * 0.5
    -- Standard right-handed local-Y positive rotation points +X downward, so use -AoA for nose-up.
    local aoa_half = math.rad(-aoa_deg) * 0.5

    local ax, ay, az, aw = 0.0, 0.0, math.sin(yaw_half), math.cos(yaw_half) -- world Z yaw
    local bx, by, bz, bw = 0.0, math.sin(aoa_half), 0.0, math.cos(aoa_half) -- local Y AoA

    -- q = qYaw * qAoA. This keeps local Y horizontal, which guarantees zero side bank.
    local qx = aw * bx + ax * bw + ay * bz - az * by
    local qy = aw * by - ax * bz + ay * bw + az * bx
    local qz = aw * bz + ax * by - ay * bx + az * bw
    local qw = aw * bw - ax * bx - ay * by - az * bz

    Natives.InvokeVoid(N.SET_ENTITY_QUATERNION, obj, qx, qy, qz, qw)

    local meta = tg_get_meta(obj) or {}
    meta.heading = yaw
    meta.pitch = 0.0
    meta.roll = 0.0
    meta.aoa = aoa_deg
    tg_set_meta(obj, meta)
    tg_log("[START_AOA][APPLY] label=" .. tostring(label or "") ..
        " heading=" .. string.format("%.1f", yaw) ..
        " aoa=" .. string.format("%.1f", aoa_deg) ..
        " bank=0.0")
    return true
end

function tg_compute_start_ramp_layout(pos, heading)
    pos = pos or { x = 0.0, y = 0.0, z = 72.0 }
    heading = tg_normalize_heading(heading or 0.0)

    local length = math.max(20.0, tonumber(TG_START_RAMP_SEGMENT_LENGTH or 53.0) or 53.0)
    local half = length * 0.5
    local aoa = math.abs(tonumber(TG_START_RAMP_AOA_DEG or 10.0) or 10.0)
    local up_count = math.max(1, math.floor(tonumber(TG_START_RAMP_UP_PIECES or 3) or 3))
    local angle = math.rad(aoa)
    local horiz_len = length * math.cos(angle)
    local rise_len = length * math.sin(angle)

    local entries = {}
    local x, y = calculate_new_position(pos, heading, TG_START_RAMP_FORWARD_OFFSET or 18.0, 0.0, 0.0)
    local z = (tonumber(pos.z) or 0.0) + (TG_START_RAMP_BASE_HEIGHT or 1.2) + half * math.sin(angle)

    for i = 1, up_count do
        if i > 1 then
            x, y = calculate_new_position({ x = x, y = y, z = z }, heading, horiz_len, 0.0, 0.0)
            z = z + rise_len
        end
        entries[#entries + 1] = {
            model = "stt_prop_track_straight_bar_m",
            x = x, y = y, z = z,
            heading = heading,
            pitch = 0.0, roll = 0.0, aoa = aoa,
            direction = "left",
            start_ramp = true,
            ramp_index = i,
            ramp_up = true
        }
    end

    -- Flat exit: connect its start edge to the end edge of the third climbing piece.
    local last = entries[#entries]
    local flat_dist = half * math.cos(angle) + half
    local flat_x, flat_y = calculate_new_position(last, heading, flat_dist, 0.0, 0.0)
    local flat_z = last.z + half * math.sin(angle)
    local flat = {
        model = "stt_prop_track_straight_bar_m",
        x = flat_x, y = flat_y, z = flat_z,
        heading = heading,
        pitch = 0.0, roll = 0.0, aoa = 0.0,
        direction = "left",
        start_ramp = true,
        ramp_index = up_count + 1,
        ramp_flat = true
    }
    entries[#entries + 1] = flat

    return {
        entries = entries,
        first = entries[1],
        second = entries[2],
        third = entries[3],
        flat = flat,
        up_count = up_count,
        aoa = aoa
    }
end

function tg_spawn_start_launch_ramp(pos, heading, label, seed_mode)
    local layout = tg_compute_start_ramp_layout(pos, heading)
    local entries = layout and layout.entries or nil
    if not entries or #entries < 2 then
        tg_warn("START_RAMP", "invalid AoA launch layout")
        return nil
    end

    for i, meta in ipairs(entries) do
        connector_apply_track_size_meta(meta, meta.model)
        local blocked, why = tg_world_obstacle_probe_meta(meta, 0, tostring(label or "start_ramp") .. "_piece_" .. tostring(i))
        if blocked then
            tg_warn("START_RAMP", "launch blocked piece=" .. tostring(i) .. " reason=" .. tostring(why))
            tg_toast("Launch ramp is blocked by a building/object. Look toward a clearer direction and try again.", 4500)
            return nil
        end
    end

    local spawned = {}
    local flat_index = #entries
    for i, meta in ipairs(entries) do
        local obj = create_track_object(meta.model, meta.x, meta.y, meta.z, meta.heading)
        if not obj or obj == 0 then
            tg_warn("START_RAMP", "spawn failed piece=" .. tostring(i))
            for _, old_obj in ipairs(spawned) do tg_delete(old_obj) end
            return nil
        end

        if (tonumber(meta.aoa or 0.0) or 0.0) > 0.0 then
            tg_apply_track_aoa(obj, meta.aoa, meta.heading, tostring(label or "start_ramp") .. "_" .. tostring(i))
        else
            tg_apply_track_rotation(obj, 0.0, 0.0, meta.heading, tostring(label or "start_ramp") .. "_flat")
        end

        local om = tg_get_meta(obj) or {}
        om.start_ramp = true
        om.ramp_index = i
        om.ramp_up = i < flat_index
        om.ramp_flat = i == flat_index
        om.aoa = tonumber(meta.aoa or 0.0) or 0.0
        om.pitch = 0.0
        om.roll = 0.0
        if seed_mode and i == flat_index then om.keep_visible_seed = true end
        tg_set_meta(obj, om)
        table.insert(spawned, obj)
    end

    local first_obj = spawned[1]
    local flat_obj = spawned[#spawned]
    connector_builder_state.active = true
    connector_builder_state.start_obj = seed_mode and flat_obj or first_obj
    connector_builder_state.current_obj = flat_obj
    connector_builder_state.current_model = "stt_prop_track_straight_bar_m"
    connector_builder_state.current_direction = "left"
    connector_builder_state.current_heading = heading or 0.0
    connector_port_init(flat_obj, "left", seed_mode and "ramp_seed_flat_exit" or "ramp_flat_exit")

    if seed_mode then
        connector_builder_state.first_real_obj = nil
        connector_builder_state.no_starter_seed_obj = flat_obj
        connector_builder_state.seed_start_meta = tg_get_meta(flat_obj)
        connector_builder_state.history = {
            { obj = flat_obj, model = "stt_prop_track_straight_bar_m", direction = "left", open_side = "left", heading = heading or 0.0, ramp_seed = true }
        }
        connector_builder_state.pieces = 1
        connector_builder_state.accepted = 1
    else
        connector_builder_state.first_real_obj = first_obj
        connector_builder_state.history = {}
        for i, obj in ipairs(spawned) do
            connector_builder_state.history[#connector_builder_state.history + 1] = {
                obj = obj,
                model = "stt_prop_track_straight_bar_m",
                direction = "left",
                open_side = (i == #spawned) and "left" or nil,
                heading = heading or 0.0,
                start_ramp = true,
                ramp_index = i,
                ramp_up = i < #spawned,
                ramp_flat = i == #spawned,
                aoa = (i < #spawned) and (layout.aoa or 0.0) or 0.0
            }
        end
        connector_builder_state.pieces = #spawned
        connector_builder_state.accepted = #spawned
    end

    tg_log("[START_RAMP][READY] label=" .. tostring(label or "start") ..
        " heading=" .. string.format("%.1f", heading or 0.0) ..
        " aoa=" .. string.format("%.1f", layout.aoa or 0.0) ..
        " upPieces=" .. tostring(layout.up_count or 3) ..
        " flatPiece=" .. tostring(#spawned) ..
        " flatZ=" .. string.format("%.2f", (tg_get_meta(flat_obj) and tg_get_meta(flat_obj).z) or 0.0) ..
        " entryBase=" .. string.format("%.2f", tonumber(TG_START_RAMP_BASE_HEIGHT or -1.60) or -1.60) ..
        " belowPlayer=" .. string.format("%.2f", math.abs(tonumber(TG_START_RAMP_BASE_HEIGHT or -1.60) or -1.60)) ..
        " bank=0.0" ..
        " seedMode=" .. tostring(seed_mode == true))
    return flat_obj
end

local function connector_spawn_start(label, start_opts)
    label = label or "connector_start"
    start_opts = start_opts or {}
    connector_reset_state()
    local pos, heading = tg_get_local_position_heading(label)
    heading = heading or 0.0

    if TG_START_LAUNCH_RAMP ~= false and start_opts.ramp ~= false then
        return tg_spawn_start_launch_ramp(pos, heading, label, start_opts.seed_mode == true)
    end

    local base_x, base_y, base_z = calculate_new_position(pos, heading, 18.0, 0.0, 1.2)

    if TG_SNAKE_STARTER_ENABLED ~= false then
        local spacing = tonumber(TG_SNAKE_STARTER_SPACING or 53.0) or 53.0
        local front_gap = tonumber(TG_SNAKE_STARTER_FRONT_GAP or spacing) or spacing
        local back_gap = tonumber(TG_SNAKE_STARTER_BACK_GAP or spacing) or spacing

        local middle_pos = { x = base_x, y = base_y, z = base_z }
        local fx, fy, fz = calculate_new_position(middle_pos, heading, front_gap, 0.0, 0.0)
        local bx, by, bz = calculate_new_position(middle_pos, heading, -back_gap, 0.0, 0.0)

        local back_obj = create_track_object("stt_prop_track_straight_bar_m", bx, by, bz, heading)
        local mid_obj = create_track_object("stt_prop_track_straight_bar_m", base_x, base_y, base_z, heading)
        local front_obj = create_track_object("stt_prop_track_straight_bar_m", fx, fy, fz, heading)

        if not front_obj or front_obj == 0 then
            tg_error("[CONNECTOR] failed to spawn snake front launch straight")
            return nil
        end

        connector_builder_state.active = true
        connector_builder_state.snake_starter_mode = true
        connector_builder_state.loop_target_obj = back_obj
        connector_builder_state.snake_middle_obj = mid_obj
        connector_builder_state.front_launch_obj = front_obj
        connector_builder_state.start_obj = front_obj
        connector_builder_state.first_real_obj = front_obj
        connector_builder_state.current_obj = front_obj
        connector_builder_state.current_model = "stt_prop_track_straight_bar_m"
        connector_builder_state.current_direction = "left"
        connector_builder_state.current_heading = heading or 0.0
        connector_builder_state.pieces = 1
        connector_builder_state.accepted = 1

        if back_obj and back_obj ~= 0 then connector_port_init(back_obj, "right", "snake_goal_rear") end
        if mid_obj and mid_obj ~= 0 then connector_port_init(mid_obj, "left", "snake_middle") end
        connector_port_init(front_obj, "left", "snake_front_launch")

        table.insert(connector_builder_state.history, {
            obj=front_obj,
            model="stt_prop_track_straight_bar_m",
            direction="left",
            open_side="left",
            heading=heading or 0.0,
            snake_front_launch=true
        })

        tg_log("[SNAKE][STARTER] rearGoal=" .. tg_handle(back_obj) ..
            " middle=" .. tg_handle(mid_obj) ..
            " frontLaunch=" .. tg_handle(front_obj) ..
            " spacing=" .. string.format("%.1f", spacing) ..
            " heading=" .. string.format("%.1f", heading or 0.0))
        tg_log("[CONNECTOR][START] obj=" .. tg_handle(front_obj) ..
            " pos=" .. tg_vec_str(tg_get_meta(front_obj)) ..
            " heading=" .. tostring(heading) ..
            " nextDir=left loopTarget=" .. tg_handle(back_obj))
        return front_obj
    end

    local x, y, z = base_x, base_y, base_z
    local start_meta = { model = "stt_prop_track_straight_bar_m", x = x, y = y, z = z, heading = heading }
    local start_blocked, start_reason = tg_world_obstacle_probe_meta(start_meta, 0, label .. "_start")
    if start_blocked then
        tg_warn("OBSTACLE", "starting track position blocked reason=" .. tostring(start_reason))
        tg_toast("Starting area is blocked by a building/object. Move to a more open area and try again.", 4500)
        return nil
    end
    local obj = create_track_object("stt_prop_track_straight_bar_m", x, y, z, heading)
    if not obj or obj == 0 then
        tg_error("[CONNECTOR] failed to spawn starting straight")
        return nil
    end
    connector_builder_state.active = true
    connector_builder_state.start_obj = obj
    connector_builder_state.current_obj = obj
    connector_builder_state.current_model = "stt_prop_track_straight_bar_m"
    connector_builder_state.current_direction = "left"
    connector_builder_state.current_heading = heading or 0.0
    connector_builder_state.pieces = 1
    connector_builder_state.accepted = 1
    connector_port_init(obj, "left", "start")
    table.insert(connector_builder_state.history, {obj=obj, model="stt_prop_track_straight_bar_m", direction="left", open_side="left", heading=heading or 0.0})
    tg_log("[CONNECTOR][START] obj=" .. tg_handle(obj) .. " pos=" .. tg_vec_str(tg_get_meta(obj)) .. " heading=" .. tostring(heading) .. " nextDir=left")
    return obj
end

local function connector_try_next(label, opts)
    label = label or "connector_next"
    opts = opts or {}
    if not connector_builder_state.active or not connector_builder_state.current_obj then
        local ok_start = connector_spawn_start(label .. "_auto_start")
        if not ok_start then return nil end
        util.yield(opts.delay_ms or 250)
    end

    local parent_obj = connector_builder_state.current_obj
    local parent_model = connector_builder_state.current_model
    local parent_direction = connector_builder_state.current_direction
    local candidate, count, scored = connector_pick_candidate(parent_model, parent_direction, opts)
    if not candidate then
        connector_builder_state.rejected = connector_builder_state.rejected + 1
        tg_warn("CONNECTOR", label .. " no candidate for parent=" .. tostring(parent_model) .. " dir=" .. tostring(parent_direction))
        return nil
    end

    if tg_generation_should_stop(opts.generation_token, label .. "_before_preview") then return nil end
    tg_debug("CONNECTOR", label .. " testing candidates=" .. tostring(count) .. " parent=" .. tostring(parent_model) .. " dir=" .. tostring(parent_direction) .. " -> child=" .. tostring(candidate.child) .. " child_dir=" .. tostring(candidate.direction) .. " offset=" .. string.format("%.2f,%.2f,%.2f", candidate.x or 0, candidate.y or 0, candidate.z or 0) .. " rotZ=" .. tostring(candidate.rotZ))
    connector_preview_candidate_sequence(parent_obj, scored, candidate, opts, label)
    if tg_generation_should_stop(opts.generation_token, label .. "_before_attach") then return nil end
    local child_obj = attach_object(parent_obj, candidate.child, candidate.x, candidate.y, candidate.z, candidate.rotX, candidate.rotY, candidate.rotZ)
    if not child_obj or child_obj == 0 then
        connector_builder_state.rejected = connector_builder_state.rejected + 1
        tg_warn("CONNECTOR", label .. " rejected: spawn/attach returned nil")
        return nil
    end

    local child_meta = tg_get_meta(child_obj) or {}
    local child_heading = tonumber(child_meta.heading) or ((tonumber(tg_get_meta(parent_obj) and tg_get_meta(parent_obj).heading) or 0.0) + (tonumber(candidate.rotZ) or 0.0))

    -- Important: original formation rows use parentDirection only as left/right.
    -- A straight child often reports direction="front"; keeping that as the next parentDirection
    -- causes the builder to stop because no parentDirection="front" rows exist.
    local next_direction = connector_resolve_next_open_side(parent_direction, candidate)

    connector_port_mark_attach(parent_obj, child_obj, candidate, next_direction)

    connector_builder_state.current_obj = child_obj
    connector_builder_state.current_model = candidate.child
    connector_builder_state.current_direction = next_direction
    connector_builder_state.current_heading = child_heading
    connector_builder_state.pieces = connector_builder_state.pieces + 1
    connector_builder_state.accepted = connector_builder_state.accepted + 1
    table.insert(connector_builder_state.history, {
        obj=child_obj,
        model=candidate.child,
        direction=next_direction,
        open_side=next_direction,
        parent_side=candidate.parentDirection,
        heading=child_heading,
        attach=candidate,
        parent_obj=parent_obj,
        parent_model=parent_model,
        parent_direction=parent_direction,
        dead_key=connector_deadend_key(parent_obj, parent_direction, candidate)
    })

    local cm = tg_get_meta(child_obj)
    local sm = tg_get_meta(connector_builder_state.start_obj)
    tg_log("[CONNECTOR][ACCEPT] #" .. tostring(connector_builder_state.pieces) ..
        " obj=" .. tg_handle(child_obj) ..
        " model=" .. tostring(candidate.child) ..
        " rowDir=" .. tostring(candidate.direction) ..
        " nextDir=" .. tostring(next_direction) ..
        " heading=" .. string.format("%.2f", child_heading) ..
        " relRotZ=" .. tostring(candidate.rotZ) ..
        " dist_to_start=" .. string.format("%.1f", tg_distance2d(cm, sm)) ..
        " pos=" .. tg_vec_str(cm))
    if TG_LOG_MODE == "compact" and ((connector_builder_state.accepted or 0) % (TG_LOG_PROGRESS_EVERY or 5) == 0) then
        local cm = tg_get_meta(connector_builder_state.current_obj)
        local tm = connector_start_guard_meta and connector_start_guard_meta() or nil
        local d = (cm and tm) and tg_distance2d(cm, tm) or -1
        tg_log("[TRACKMATIC][PROGRESS] pieces=" .. tostring(connector_builder_state.accepted or 0) ..
            " current=" .. tostring(connector_builder_state.current_model or "?") ..
            " dir=" .. tostring(connector_builder_state.current_direction or "?") ..
            " distToLoopTarget=" .. string.format("%.1f", d))
    end

    return child_obj, candidate
end

local function connector_build_chain(count, opts)
    opts = opts or {}
    opts.generation_token = opts.generation_token or tg_generation_start("connector_chain")
    local gen_token = opts.generation_token
    count = tonumber(count) or 5
    if count < 1 then count = 1 end
    clear_race_track("connector_chain")
    connector_spawn_start("connector_chain_start")
    for i = 2, count do
        util.yield(opts.delay_ms or 350)
        if tg_generation_should_stop(gen_token, "chain_step_" .. tostring(i)) then return false end
        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        if i % 4 == 0 then step_opts.prefer_straight = true end
        local obj = connector_try_next("chain_step_" .. tostring(i), step_opts)
        if not obj then
            tg_warn("CONNECTOR", "chain stopped at step=" .. tostring(i))
            break
        end
    end
    tg_log("[CONNECTOR][CHAIN_DONE] requested=" .. tostring(count) .. " placed=" .. tostring(connector_builder_state.pieces) .. " accepted=" .. tostring(connector_builder_state.accepted) .. " rejected=" .. tostring(connector_builder_state.rejected))
    tg_report_state("connector_chain_done")
end

local function connector_build_loop_prototype()
    clear_race_track("connector_loop")
    connector_spawn_start("connector_loop_start")
    local total = 14
    for i = 2, total do
        util.yield(350)
        local opts = { delay_ms = 350, no_180 = true }
        if i < 9 then
            opts.prefer_turns = (i % 3 == 0)
        else
            -- prototype loop bias: keep using turns late in the chain so the course starts curling back.
            opts.prefer_turns = true
            opts.no_front = (i % 2 == 0)
        end
        local obj = connector_try_next("loop_step_" .. tostring(i), opts)
        if not obj then break end
    end
    local end_meta = tg_get_meta(connector_builder_state.current_obj)
    local start_meta = tg_get_meta(connector_builder_state.start_obj)
    local dist = tg_distance2d(end_meta, start_meta)
    tg_log("[CONNECTOR][LOOP_PROTO_DONE] pieces=" .. tostring(connector_builder_state.pieces) .. " end_dist_to_start=" .. string.format("%.1f", dist) .. " note=prototype only; true closure solver comes after connector visuals are confirmed")
    tg_report_state("connector_loop_proto_done")
end



-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.5.0 strict loop-to-start closure helpers
-- ═══════════════════════════════════════════════════════════════════════════════════
function connector_meta_copy(meta)
    if not meta then return nil end
    return {
        x = tonumber(meta.x or 0.0) or 0.0,
        y = tonumber(meta.y or 0.0) or 0.0,
        z = tonumber(meta.z or 0.0) or 0.0,
        heading = tonumber(meta.heading or 0.0) or 0.0,
        model = meta.model,
        handle = meta.handle
    }
end

function connector_loop_target_meta()
    local target_obj = connector_builder_state.loop_target_obj or connector_builder_state.start_obj
    local start = connector_meta_copy(tg_get_meta(target_obj))
    if not start then return nil end
    -- v0.6.9: in snake-starter mode this is the rear goal straight, not the front launch piece.
    start.model = "LOOP_START_TARGET"
    return start
end

function connector_force_snap_bridge_to_start(label, opts)
    opts = opts or {}
    label = label or "short_snap_bridge_to_start"
    local cur = connector_meta_copy(tg_get_meta(connector_builder_state.current_obj))
    local start = connector_loop_target_meta()
    if not cur or not start then
        tg_warn("LOOP", "[SHORT_SNAP] missing current/start meta")
        return false
    end

    local dx = (start.x or 0.0) - (cur.x or 0.0)
    local dy = (start.y or 0.0) - (cur.y or 0.0)
    local dz = (start.z or 0.0) - (cur.z or 0.0)
    local dist = math.sqrt(dx * dx + dy * dy)
    local max_dist = tonumber(opts.max_final_snap_dist or TG_LOOP_MAX_FINAL_SNAP_DIST or 86.0) or 86.0
    if dist > max_dist then
        tg_warn("LOOP", "[SHORT_SNAP_ESCALATE_TO_FORCE_TOUCH] dist=" .. string.format("%.1f", dist) ..
            " max=" .. string.format("%.1f", max_dist) ..
            " reason=needs_multi_segment_touch")
        return connector_force_touch_start_bridge(label .. "_force_touch", opts)
    end

    local segment_len = tonumber(opts.snap_segment_len or TG_LOOP_SNAP_SEGMENT_LEN or 53.0) or 53.0
    local intervals = math.max(1, math.floor((dist / segment_len) + 0.5))
    local pieces_to_add = math.max(1, intervals - 1)
    if pieces_to_add > 2 then pieces_to_add = 2 end

    local atan2 = math.atan2 or math.atan
    local heading = tg_normalize_heading(math.deg(atan2(dy, dx)))
    tg_log("[LOOP][SHORT_SNAP_BEGIN] label=" .. tostring(label) ..
        " dist=" .. string.format("%.1f", dist) ..
        " heading=" .. string.format("%.1f", heading) ..
        " addPieces=" .. tostring(pieces_to_add))

    for i = 1, pieces_to_add do
        local t = i / (pieces_to_add + 1)
        local x = (cur.x or 0.0) + dx * t
        local y = (cur.y or 0.0) + dy * t
        local z = (cur.z or 0.0) + dz * t

        local temp_meta = { x = x, y = y, z = z, heading = heading, model = "stt_prop_track_straight_bar_m" }
        local penalty, reason, hard = connector_overlap_penalty(temp_meta, { strict_overlap = false, overlap_skip_recent = 1, allow_start_close = true })
        if hard then
            tg_warn("LOOP", "[SHORT_SNAP_REFUSED] overlap at snap segment i=" .. tostring(i) .. " reason=" .. tostring(reason))
            return false
        end
        local world_blocked, world_reason = tg_world_obstacle_probe_meta(temp_meta, connector_builder_state.current_obj, label .. "_snap_" .. tostring(i))
        if world_blocked then
            tg_warn("OBSTACLE", "short snap refused i=" .. tostring(i) .. " reason=" .. tostring(world_reason))
            return false
        end

        if opts.tetris_preview then
            local preview_start = connector_random_preview_start_heading(heading, opts, true)
            local preview = connector_create_preview_object("stt_prop_track_straight_bar_m", x, y, z + (opts.preview_lift or 1.25), preview_start, label .. "_preview_" .. tostring(i))
            connector_animate_preview_heading(preview, preview_start, heading, opts, label .. "_snap_" .. tostring(i), true)
            util.yield(opts.preview_delay_ms or 90)
            connector_delete_preview_object(preview, label .. "_preview_delete_" .. tostring(i))
        end

        local obj = create_track_object("stt_prop_track_straight_bar_m", x, y, z, heading)
        if not obj or obj == 0 then
            tg_warn("LOOP", "[SHORT_SNAP] failed to create snap segment i=" .. tostring(i))
            return false
        end

        connector_builder_state.current_obj = obj
        connector_builder_state.current_model = "stt_prop_track_straight_bar_m"
        connector_builder_state.current_direction = "left"
        connector_builder_state.current_heading = heading
        connector_builder_state.pieces = connector_builder_state.pieces + 1
        connector_builder_state.accepted = connector_builder_state.accepted + 1
        table.insert(connector_builder_state.history, {obj=obj, model="stt_prop_track_straight_bar_m", direction="left", heading=heading, short_snap_bridge=true})

        local seg_meta = tg_get_meta(obj)
        tg_log("[LOOP][SHORT_SNAP_SEGMENT] i=" .. tostring(i) ..
            "/" .. tostring(pieces_to_add) ..
            " obj=" .. tg_handle(obj) ..
            " distToStart=" .. string.format("%.1f", tg_distance2d(seg_meta, start)))
        util.yield(opts.delay_ms or 80)
    end

    local final_meta = tg_get_meta(connector_builder_state.current_obj)
    local final_dist = tg_distance2d(final_meta, start)
    tg_log("[LOOP][SHORT_SNAP_DONE] label=" .. tostring(label) ..
        " finalCenterDistToStart=" .. string.format("%.1f", final_dist) ..
        " status=SHORT_BRIDGE_BACK_TO_START")
    return true
end



function connector_loop15_curved_touch_start(label, opts)
    opts = opts or {}
    label = label or "loop15_curved_touch"

    local start = connector_builder_state.first_real_obj and tg_get_meta(connector_builder_state.first_real_obj) or connector_start_guard_meta() or connector_loop_target_meta()
    local cur = tg_get_meta(connector_builder_state.current_obj)
    if not cur or not start then
        tg_warn("LOOP15", "[CURVED_TOUCH_REFUSED] missing current/start meta")
        return false
    end

    local close_dist = tonumber(opts.force_touch_close_dist or opts.close_dist or TG_LOOP15_CLOSE_DIST or 82.0) or 82.0
    local pieces_now = tonumber(connector_builder_state.pieces or 0) or 0
    local max_total = tonumber(opts.max_total_pieces or 0) or 0
    local remaining = tonumber(opts.force_touch_max_segments or 0) or 0
    if max_total > 0 then
        local budget_remaining = math.max(0, max_total - pieces_now)
        if remaining <= 0 or remaining > budget_remaining then remaining = budget_remaining end
    end
    remaining = math.floor(remaining)

    local dist = tg_distance2d(cur, start)
    tg_log("[LOOP15][CURVED_TOUCH_BEGIN] label=" .. tostring(label) ..
        " dist=" .. string.format("%.1f", dist) ..
        " remaining=" .. tostring(remaining) ..
        " closeDist=" .. string.format("%.1f", close_dist))

    if dist <= close_dist then
        tg_log("[LOOP15][CURVED_TOUCH_ALREADY] dist=" .. string.format("%.1f", dist))
        return true
    end
    if remaining <= 0 then
        tg_warn("LOOP15", "[CURVED_TOUCH_NO_BUDGET] dist=" .. string.format("%.1f", dist))
        return false
    end

    local last_dist = dist
    for i = 1, remaining do
        if opts.max_total_pieces and (connector_builder_state.pieces or 0) >= opts.max_total_pieces then
            tg_log("[LOOP15][CURVED_TOUCH_BUDGET_STOP] pieces=" .. tostring(connector_builder_state.pieces) .. "/" .. tostring(opts.max_total_pieces))
            break
        end

        cur = tg_get_meta(connector_builder_state.current_obj)
        dist = tg_distance2d(cur, start)
        if dist <= close_dist then
            tg_log("[LOOP15][CURVED_TOUCH_DONE] finalDistToStart=" .. string.format("%.1f", dist) .. " status=TOUCHED_START")
            return true
        end

        util.yield(opts.delay_ms or 90)
        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        step_opts.target_meta = start
        step_opts.loop_origin_meta = start
        step_opts.prefer_towards_target = true
        step_opts.loopback_final = true
        step_opts.loopback_close_dist = close_dist
        step_opts.prefer_turns = true
        step_opts.no_front = false
        step_opts.no_180 = (i <= remaining - 2)
        step_opts.top_n = tonumber(TG_LOOP15_RETURN_TOP_N or 2) or 2
        step_opts.allow_start_close = true
        step_opts.start_avoid_dist = 0
        step_opts.no_return_until_pieces = 0
        connector_apply_legacy_smart_clearance_opts(step_opts)
        if TG_LOOP15_RETURN_STRICT_OVERLAP then step_opts.strict_overlap = true end

        local obj = connector_try_next_legacy_smart(label .. "_curved_" .. tostring(i), step_opts)
        if not obj then
            tg_warn("LOOP15", "[CURVED_TOUCH_BLOCKED] i=" .. tostring(i) .. " dist=" .. string.format("%.1f", dist))
            return false
        end

        local after = tg_get_meta(connector_builder_state.current_obj)
        local after_dist = tg_distance2d(after, start)
        tg_log("[LOOP15][CURVED_TOUCH_SEGMENT] i=" .. tostring(i) .. "/" .. tostring(remaining) ..
            " obj=" .. tg_handle(obj) ..
            " distBefore=" .. string.format("%.1f", dist) ..
            " distAfter=" .. string.format("%.1f", after_dist) ..
            " gained=" .. string.format("%.1f", dist - after_dist))
        last_dist = after_dist
    end

    local final_meta = tg_get_meta(connector_builder_state.current_obj)
    local final_dist = tg_distance2d(final_meta, start)
    local ok = final_dist <= close_dist
    tg_log("[LOOP15][CURVED_TOUCH_DONE] finalDistToStart=" .. string.format("%.1f", final_dist) ..
        " status=" .. (ok and "TOUCHED_START" or "CURVED_STILL_OPEN"))
    return ok
end

function connector_force_touch_start_bridge(label, opts)
    opts = opts or {}
    label = label or "force_touch_start_bridge"

    local cur = connector_meta_copy(tg_get_meta(connector_builder_state.current_obj))
    local start = connector_start_guard_meta() or connector_loop_target_meta()
    if not cur or not start then
        tg_warn("LOOPBACK", "[FORCE_TOUCH_REFUSED] missing current/start meta")
        return false
    end

    local dx = (start.x or 0.0) - (cur.x or 0.0)
    local dy = (start.y or 0.0) - (cur.y or 0.0)
    local dz = (start.z or 0.0) - (cur.z or 0.0)
    local dist = math.sqrt(dx * dx + dy * dy)
    local max_dist = tonumber(opts.force_touch_max_dist or TG_LOOP_FORCE_TOUCH_MAX_DIST or 320.0) or 320.0
    local close_dist = tonumber(opts.force_touch_close_dist or TG_LOOP_FORCE_TOUCH_CLOSE_DIST or 72.0) or 72.0
    local seg_len = tonumber(opts.snap_segment_len or TG_LOOP_SNAP_SEGMENT_LEN or 53.0) or 53.0

    if dist <= close_dist then
        tg_log("[LOOPBACK][TOUCH_ALREADY] label=" .. tostring(label) .. " dist=" .. string.format("%.1f", dist))
        return true
    end

    if dist > max_dist then
        tg_warn("LOOPBACK", "[FORCE_TOUCH_REFUSED] dist=" .. string.format("%.1f", dist) ..
            " max=" .. string.format("%.1f", max_dist) ..
            " reason=too_far_for_clean_touch")
        return false
    end

    local max_segments = tonumber(opts.force_touch_max_segments or TG_LOOP_FORCE_TOUCH_MAX_SEGMENTS or 6) or 6
    local segments = math.max(1, math.floor((dist / seg_len) + 0.5))
    if segments > max_segments then segments = max_segments end

    local atan2 = math.atan2 or math.atan
    local heading = tg_normalize_heading(math.deg(atan2(dy, dx)))

    tg_log("[LOOPBACK][FORCE_TOUCH_BEGIN] label=" .. tostring(label) ..
        " dist=" .. string.format("%.1f", dist) ..
        " heading=" .. string.format("%.1f", heading) ..
        " segments=" .. tostring(segments) ..
        " closeDist=" .. string.format("%.1f", close_dist))

    for i = 1, segments do
        local t = i / (segments + 1)
        local x = (cur.x or 0.0) + dx * t
        local y = (cur.y or 0.0) + dy * t
        local z = (cur.z or 0.0) + dz * t

        local touch_meta = { model = "stt_prop_track_straight_bar_m", x = x, y = y, z = z, heading = heading }
        local world_blocked, world_reason = tg_world_obstacle_probe_meta(touch_meta, connector_builder_state.current_obj, label .. "_touch_" .. tostring(i))
        if world_blocked then
            tg_warn("OBSTACLE", "force-touch bridge refused i=" .. tostring(i) .. " reason=" .. tostring(world_reason))
            return false
        end

        if opts.tetris_preview then
            local preview_start = connector_random_preview_start_heading(heading, opts, true)
            local preview = connector_create_preview_object("stt_prop_track_straight_bar_m", x, y, z + (opts.preview_lift or 1.25), preview_start, label .. "_preview_" .. tostring(i))
            connector_animate_preview_heading(preview, preview_start, heading, opts, label .. "_touch_" .. tostring(i), true)
            util.yield(opts.preview_delay_ms or 60)
            connector_delete_preview_object(preview, label .. "_preview_delete_" .. tostring(i))
        end

        local obj = create_track_object("stt_prop_track_straight_bar_m", x, y, z, heading)
        if not obj or obj == 0 then
            tg_warn("LOOPBACK", "[FORCE_TOUCH_FAILED] create failed segment=" .. tostring(i))
            return false
        end

        connector_builder_state.current_obj = obj
        connector_builder_state.current_model = "stt_prop_track_straight_bar_m"
        connector_builder_state.current_direction = "front"
        connector_builder_state.current_heading = heading
        connector_builder_state.pieces = (connector_builder_state.pieces or 0) + 1
        connector_builder_state.accepted = (connector_builder_state.accepted or 0) + 1
        table.insert(connector_builder_state.history, {obj=obj, model="stt_prop_track_straight_bar_m", direction="front", heading=heading, force_touch_bridge=true})

        local seg_meta = tg_get_meta(obj)
        tg_log("[LOOPBACK][FORCE_TOUCH_SEGMENT] i=" .. tostring(i) ..
            "/" .. tostring(segments) ..
            " obj=" .. tg_handle(obj) ..
            " distToStart=" .. string.format("%.1f", tg_distance2d(seg_meta, start)))
        util.yield(opts.delay_ms or 60)
    end

    local final_meta = tg_get_meta(connector_builder_state.current_obj)
    local final_dist = tg_distance2d(final_meta, start)
    local ok = final_dist <= close_dist
    tg_log("[LOOPBACK][FORCE_TOUCH_DONE] label=" .. tostring(label) ..
        " finalDistToStart=" .. string.format("%.1f", final_dist) ..
        " status=" .. (ok and "TOUCHED_START" or "TOUCH_STILL_OPEN"))
    return ok
end


function connector_bridge_until_snap_range(total_pieces, opts)
    opts = opts or {}
    local start = connector_loop_target_meta()
    if not start then return false end
    local snap_range = tonumber(opts.snap_bridge_range or TG_LOOP_SNAP_BRIDGE_RANGE or 185.0) or 185.0
    local max_extra = tonumber(opts.max_extra_bridge or TG_LOOP_MAX_EXTRA_BRIDGE or 80) or 80
    local attempts = 0

    while attempts < max_extra do
        local cur = tg_get_meta(connector_builder_state.current_obj)
        local dist = tg_distance2d(cur, start)
        local remaining_to_target = math.max(0, (tonumber(total_pieces or 0) or 0) - connector_builder_state.pieces)
        if dist <= snap_range then
            tg_log("[LOOP][SNAP_RANGE] dist=" .. string.format("%.1f", dist) .. " snapRange=" .. string.format("%.1f", snap_range) .. " attempts=" .. tostring(attempts))
            return true
        end

        attempts = attempts + 1
        util.yield(opts.delay_ms or 100)
        local bridge_opts = {}
        for k, v in pairs(opts) do bridge_opts[k] = v end
        bridge_opts.target_meta = start
        bridge_opts.prefer_towards_target = true
        bridge_opts.strict_overlap = true
        bridge_opts.allow_start_close = true
        bridge_opts.no_180 = (attempts < max_extra - 3)
        bridge_opts.top_n = 1
        bridge_opts.prefer_turns = true
        bridge_opts.overlap_skip_recent = TG_OVERLAP_SKIP_RECENT

        tg_log("[LOOP][RETURN_ROUTE] attempt=" .. tostring(attempts) ..
            " dist=" .. string.format("%.1f", dist) ..
            " snapRange=" .. string.format("%.1f", snap_range) ..
            " remainingToTarget=" .. tostring(remaining_to_target))

        local obj = connector_try_next("loop_return_route_" .. tostring(attempts), bridge_opts)
        if not obj then
            tg_warn("LOOP", "return route connector failed before snap range; forcing snap bridge from current position")
            return false
        end
    end
    tg_warn("LOOP", "return route max extra reached; forcing snap bridge from current position")
    return false
end

function connector_place_loop_bridge_piece(label, remaining_slots, opts)
    opts = opts or {}
    label = label or "loop_bridge"
    local cur = tg_get_meta(connector_builder_state.current_obj)
    local start = tg_get_meta(connector_builder_state.start_obj)
    if not cur or not start then return nil end
    local dist_before = tg_distance2d(cur, start)
    local slots = tonumber(remaining_slots or 1) or 1
    if slots < 1 then slots = 1 end
    local close_dist = tonumber(opts.close_dist or TG_LOOP_CLOSE_DIST or 28.0) or 28.0
    if dist_before < close_dist then
        tg_log("[LOOP][CLOSED] label=" .. tostring(label) .. " dist=" .. string.format("%.1f", dist_before) .. " remainingSlots=" .. tostring(remaining_slots))
        return connector_builder_state.current_obj
    end

    local step_opts = {}
    for k, v in pairs(opts) do step_opts[k] = v end
    step_opts.target_meta = start
    step_opts.prefer_towards_target = true
    step_opts.strict_overlap = true
    step_opts.allow_start_close = (slots <= 4 or dist_before < (close_dist + 55.0))
    step_opts.start_avoid_dist = TG_LOOP_START_AVOID_DIST
    step_opts.no_180 = (slots > 3)
    step_opts.top_n = 1 -- closure phase should choose the best scored connector, not random.
    if slots <= 6 then step_opts.prefer_turns = true end

    tg_log("[LOOP][SENSE] label=" .. tostring(label) ..
        " remaining=" .. tostring(slots) ..
        " distBefore=" .. string.format("%.1f", dist_before) ..
        " closeDist=" .. string.format("%.1f", close_dist) ..
        " allowStartClose=" .. tostring(step_opts.allow_start_close))

    local obj = connector_try_next(label, step_opts)
    if not obj then
        tg_warn("LOOP", "connector bridge failed/stopped label=" .. tostring(label) .. " distBefore=" .. string.format("%.1f", dist_before))
        return nil
    end

    local after_meta = tg_get_meta(connector_builder_state.current_obj)
    local dist_after = tg_distance2d(after_meta, start)
    tg_log("[LOOP][BRIDGE_ACCEPT] #" .. tostring(connector_builder_state.pieces) ..
        " obj=" .. tg_handle(obj) ..
        " distBefore=" .. string.format("%.1f", dist_before) ..
        " distAfter=" .. string.format("%.1f", dist_after) ..
        " gained=" .. string.format("%.1f", dist_before - dist_after) ..
        " pos=" .. tg_vec_str(after_meta))
    return obj
end


function connector_loop_route_quality(opts)
    opts = opts or {}
    local start = connector_loop_target_meta()
    local cur = tg_get_meta(connector_builder_state.current_obj)
    local dist = tg_distance2d(cur, start)
    local min_x, max_x, min_y, max_y = 999999.0, -999999.0, 999999.0, -999999.0
    for _, entry in ipairs(connector_builder_state.history or {}) do
        local m = entry and tg_get_meta(entry.obj)
        if m then
            if m.x < min_x then min_x = m.x end
            if m.x > max_x then max_x = m.x end
            if m.y < min_y then min_y = m.y end
            if m.y > max_y then max_y = m.y end
        end
    end
    local spread = math.max(max_x - min_x, max_y - min_y)
    local ok = true
    local reason = "ok"
    if dist > (opts.reject_if_open_dist or TG_LOOP_REJECT_IF_OPEN_DIST or 115.0) then
        ok = false
        reason = "too_open_dist=" .. string.format("%.1f", dist)
    elseif spread < (opts.min_route_spread or TG_LOOP_MIN_ROUTE_SPREAD or 115.0) then
        ok = false
        reason = "too_small_spread=" .. string.format("%.1f", spread)
    end
    tg_log("[LOOP][QUALITY] ok=" .. tostring(ok) ..
        " reason=" .. tostring(reason) ..
        " dist=" .. string.format("%.1f", dist) ..
        " spread=" .. string.format("%.1f", spread) ..
        " pieces=" .. tostring(connector_builder_state.pieces))
    return ok, reason, dist, spread
end

function connector_build_looping_track(total_pieces, opts)
    opts = opts or {}
    opts.generation_token = opts.generation_token or tg_generation_start("looping_track")
    local gen_token = opts.generation_token
    total_pieces = tonumber(total_pieces or 50) or 50
    if total_pieces < 8 then total_pieces = 8 end
    clear_race_track("looping_track")
    connector_spawn_start("looping_track_start")

    -- v0.6.6: random loop also reserves a real return/touch phase.
    local reserve = tonumber(opts.bridge_reserve or math.floor(total_pieces * (TG_RANDOM_RETURN_RESERVE_RATIO or 0.28))) or 10
    if reserve < (TG_RANDOM_RETURN_RESERVE_MIN or 10) then reserve = (TG_RANDOM_RETURN_RESERVE_MIN or 10) end
    if reserve > (TG_RANDOM_RETURN_RESERVE_MAX or 20) then reserve = (TG_RANDOM_RETURN_RESERVE_MAX or 20) end
    if reserve >= total_pieces then reserve = math.max(3, total_pieces - 8) end

    local random_target = total_pieces - reserve
    local start_meta = connector_loop_target_meta()
    tg_log("[LOOP][BEGIN_RETRYABLE] target=" .. tostring(total_pieces) ..
        " randomTarget=" .. tostring(random_target) ..
        " bridgeReserve=" .. tostring(reserve) ..
        " maxFinalSnapDist=" .. string.format("%.1f", tonumber(opts.max_final_snap_dist or TG_LOOP_MAX_FINAL_SNAP_DIST or 86.0) or 86.0) ..
        " noLongSnap=true" ..
        " tetris=" .. tostring(opts.tetris_preview == true))

    for i = 2, random_target do
        util.yield(opts.delay_ms or 120)
        if tg_generation_should_stop(gen_token, "loop_random_step_" .. tostring(i)) then return false, "CANCELLED" end
        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        step_opts.no_180 = true
        step_opts.snake_straight_rhythm = TG_SNAKE_STRAIGHT_RHYTHM
        step_opts = connector_apply_straight_run_opts(step_opts)
        step_opts.top_n = step_opts.top_n or 4
        step_opts.strict_overlap = true
        step_opts.overlap_skip_recent = math.max(TG_OVERLAP_SKIP_RECENT or 3, 5)
        step_opts.allow_start_close = false
        step_opts.start_avoid_dist = TG_START_GUARD_RANDOM_DIST
        step_opts.start_guard_dist = TG_START_GUARD_RANDOM_DIST
        step_opts.no_return_until_pieces = math.floor(total_pieces * (TG_RANDOM_RETURN_RATIO or 0.64))

        if i > math.floor(random_target * (TG_RANDOM_RETURN_RATIO or 0.64)) then
            step_opts.target_meta = start_meta
            step_opts.prefer_towards_target = true
            step_opts.prefer_turns = true
            step_opts.no_front = (i % 3 == 0)
            step_opts.top_n = 2
        elseif i <= (TG_SNAKE_OPENING_STRAIGHT_BIAS_PIECES or 8) or (i % 4 == 0) or (i % 4 == 1) then
            step_opts.prefer_straight = true
        end

        local obj = connector_try_next("loop_random_step_" .. tostring(i), step_opts)
        if not obj then
            tg_warn("LOOP", "random section stopped at step=" .. tostring(i) .. "; moving to return route")
            break
        end
    end

    local max_return = tonumber(opts.max_extra_bridge or TG_LOOP_MAX_EXTRA_BRIDGE or 80) or 80
    local close_enough = tonumber(opts.max_final_snap_dist or TG_LOOP_MAX_FINAL_SNAP_DIST or 86.0) or 86.0
    local attempts = 0
    while attempts < max_return do
        if tg_generation_should_stop(gen_token, "loop_return_attempt_" .. tostring(attempts)) then return false, "CANCELLED" end
        local cur = tg_get_meta(connector_builder_state.current_obj)
        local dist = tg_distance2d(cur, start_meta)
        if dist <= close_enough then
            tg_log("[LOOP][SHORT_CLOSE_RANGE] dist=" .. string.format("%.1f", dist) .. " closeEnough=" .. string.format("%.1f", close_enough) .. " attempts=" .. tostring(attempts))
            break
        end

        attempts = attempts + 1
        util.yield(opts.delay_ms or 100)
        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        step_opts.target_meta = start_meta
        step_opts.prefer_towards_target = true
        step_opts.loopback_final = true
        step_opts.loopback_close_dist = TG_LOOPBACK_CLOSE_DIST
        step_opts.strict_overlap = true
        step_opts.allow_start_close = true
        step_opts.no_180 = (attempts < max_return - 4)
        step_opts.top_n = 1
        step_opts.prefer_turns = true
        step_opts.overlap_skip_recent = math.max(TG_OVERLAP_SKIP_RECENT or 3, 5)

        tg_log("[LOOP][RETURN_NO_SNAP] attempt=" .. tostring(attempts) .. " dist=" .. string.format("%.1f", dist) .. " targetShortClose=" .. string.format("%.1f", close_enough))
        local obj = connector_try_next("loop_return_step_" .. tostring(attempts), step_opts)
        if not obj then
            tg_warn("LOOP", "return route failed; will evaluate route quality/retry")
            break
        end
    end

    local snap_ok = connector_force_snap_bridge_to_start("loop_short_final_bridge", opts)
    local ok_quality, q_reason, dist, spread = connector_loop_route_quality(opts)
    local status = snap_ok and "LOOPED_BACK_TO_START_TOUCH" or "BAD_LOOP_RETRY_NEEDED"
    tg_log("[LOOP][DONE_RETRYABLE] status=" .. status ..
        " target=" .. tostring(total_pieces) ..
        " placed=" .. tostring(connector_builder_state.pieces) ..
        " end_dist_to_start=" .. string.format("%.1f", dist or 9999.0) ..
        " spread=" .. string.format("%.1f", spread or 0.0) ..
        " reason=" .. tostring(q_reason) ..
        " note=no long straight snap allowed")
    tg_report_state("looping_track_done_retryable")
    return snap_ok, status
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.5.2 plan-first loop builder
-- ═══════════════════════════════════════════════════════════════════════════════════
-- dry-runs the whole track as metadata before creating any gta objects.
-- This avoids the visible "spawn, fail, clear, retry" loop and lets us reject
-- starter-piece overlaps before they ever appear in-world.

function connector_plan_world_from_meta(parent, row)
    local base_heading = tonumber(parent and parent.heading or 0.0) or 0.0
    local ox = tonumber(row and row.x or 0.0) or 0.0
    local oy = tonumber(row and row.y or 0.0) or 0.0
    local oz = tonumber(row and row.z or 0.0) or 0.0
    local rx, ry, rz = tg_rotated_offset(base_heading, ox, oy, oz)
    local heading = tg_normalize_heading(base_heading + (tonumber(row and row.rotZ or 0.0) or 0.0))
    return {
        x = (parent.x or 0.0) + rx,
        y = (parent.y or 0.0) + ry,
        z = (parent.z or 0.0) + rz,
        heading = heading,
        model = row and row.child or "stt_prop_track_straight_bar_m",
        direction = row and row.direction or "front",
        angle = row and row.angle or 0,
        row = row
    }
end

function connector_plan_sample_points(meta)
    local points = {}
    if not meta then return points end
    local len, width = connector_fragment_dims(meta.model)
    len = tonumber(len or 53.0) or 53.0
    width = tonumber(width or 23.5) or 23.5
    local h = tonumber(meta.heading or 0.0) or 0.0

    local function add_local(ox, oy)
        local rx, ry = tg_rotated_offset(h, ox, oy, 0.0)
        table.insert(points, { x = (meta.x or 0.0) + rx, y = (meta.y or 0.0) + ry })
    end

    -- Centerline + edge samples. This is deliberately conservative for the planner.
    add_local(0.0, 0.0)
    add_local(len * 0.34, 0.0)
    add_local(-len * 0.34, 0.0)
    add_local(len * 0.18, width * 0.42)
    add_local(len * 0.18, -width * 0.42)
    add_local(-len * 0.18, width * 0.42)
    add_local(-len * 0.18, -width * 0.42)

    -- Curves/bends cover more space than their centerline suggests.
    local angle = math.abs(tonumber(meta.angle or 0) or 0)
    local model = tostring(meta.model or "")
    if angle >= 45 or model:find("bend", 1, true) then
        add_local(width * 0.55, width * 0.55)
        add_local(-width * 0.55, width * 0.55)
        add_local(width * 0.55, -width * 0.55)
        add_local(-width * 0.55, -width * 0.55)
    end

    return points
end

function connector_plan_points_too_close(a, b, limit)
    limit = tonumber(limit or TG_PLAN_HARD_SAMPLE_DIST or 30.0) or 30.0
    local aa = connector_plan_sample_points(a)
    local bb = connector_plan_sample_points(b)
    for _, p in ipairs(aa) do
        for _, q in ipairs(bb) do
            local dx = (p.x or 0.0) - (q.x or 0.0)
            local dy = (p.y or 0.0) - (q.y or 0.0)
            local d = math.sqrt(dx * dx + dy * dy)
            if d < limit then
                return true, d
            end
        end
    end
    return false, 999999.0
end

function connector_plan_overlap_penalty(meta, plan, opts)
    opts = opts or {}
    plan = plan or {}
    if not meta then return -9999, "nilMeta", true end
    local hard_limit = tonumber(opts.plan_hard_sample_dist or TG_PLAN_HARD_SAMPLE_DIST or 30.0) or 30.0
    local start_guard = tonumber(opts.plan_start_guard_dist or TG_PLAN_START_GUARD_DIST or 105.0) or 105.0

    for i, old in ipairs(plan) do
        -- Skip the last two pieces. Adjacent and grandparent pieces can be naturally close on bends.
        -- Do NOT skip the starting piece once the route is established.
        local is_recent = i >= (#plan - 1)
        local should_check = (not is_recent)
        if i == 1 and #plan > 3 then should_check = true end

        if should_check then
            local hard, sample_d = connector_plan_points_too_close(meta, old, hard_limit)
            local center_d = tg_distance2d(meta, old)
            if i == 1 and #plan > 3 then
                -- Extra guard around the starter piece. Prevent turn pieces from sitting on the start.
                if center_d < start_guard or sample_d < (hard_limit + 10.0) then
                    return -5000, "startGuard#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d) .. " s=" .. string.format("%.1f", sample_d), true
                end
            end
            if hard then
                return -4200, "sampleOverlap#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d) .. " s=" .. string.format("%.1f", sample_d), true
            end
            if center_d < 40.0 then
                return -1500, "centerNear#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d), true
            end
        end
    end

    return 0, "clear", false
end

function connector_plan_score_candidate(parent, plan, row, opts)
    opts = opts or {}
    local score = 100
    local reasons = {}

    local function add(delta, why)
        score = score + delta
        if why then table.insert(reasons, why .. (delta >= 0 and "+" or "") .. tostring(delta)) end
    end

    local meta = connector_plan_world_from_meta(parent, row)
    local angle = math.abs(tonumber(row.angle or 0) or 0)
    local dir = tostring(row.direction or "")
    local child = tostring(row.child or "")

    if angle == 0 or dir == "front" then add(28, "straight") end
    if angle == 45 then add(22, "gentle45") end
    if angle == 90 then add(8, "turn90") end
    if angle == 135 then add(-34, "sharp135") end
    if angle >= 180 then add(-220, "avoid180") end

    if opts.prefer_turns and dir ~= "front" then add(20, "prefer_turn") end
    if opts.prefer_gentle_turns and dir ~= "front" then
        if angle == 45 then add(125, "minigameGentle45")
        elseif angle == 90 then add(70, "minigameGentle90")
        elseif angle >= 135 then add(-260, "minigameAvoidSharp") end
    end
    if opts.prefer_sharp_turns and dir ~= "front" then
        if angle == 90 then add(85, "minigameSharp90")
        elseif angle == 135 then add(125, "minigameSharp135")
        elseif angle == 45 then add(-20, "minigameLess45") end
    end
    if opts.prefer_straight then
        if dir == "front" then add(55, "prefer_straight") else add(-30, "not_straight") end
    end

    local last = plan[#plan]
    local prev = plan[#plan - 1]
    if last and last.model == child then add(-28, "same_model") end
    if last and prev and last.model == child and prev.model == child then add(-70, "same_model_x3") end
    if dir ~= "front" and last and prev and last.direction == dir and prev.direction == dir then add(-65, "turn_spiral") end
    if dir ~= "front" and last and last.direction == dir and angle >= 90 then add(-26, "repeat_side") end

    local op, oreason, hard = connector_plan_overlap_penalty(meta, plan, opts)
    if op ~= 0 then add(op, oreason) end
    if hard then add(-1000, "hardReject") end

    if opts.target_meta then
        local before = tg_distance2d(parent, opts.target_meta)
        local after = tg_distance2d(meta, opts.target_meta)
        local gain = before - after
        if opts.prefer_towards_target then
            add(math.floor(gain * 4.0), "towardTarget=" .. string.format("%.1f", gain))
            if gain < -7.0 then add(-220, "awayFromTarget") end
        else
            add(math.floor(gain * 1.2), "mildTarget=" .. string.format("%.1f", gain))
        end
    end

    return score, table.concat(reasons, ","), meta
end

function connector_plan_pick_candidate(parent, plan, opts)
    opts = opts or {}
    local candidates = connector_candidate_list(parent.model, parent.direction, opts)
    if #candidates == 0 then return nil, nil, "noCandidates" end

    local scored = {}
    for _, row in ipairs(candidates) do
        local score, reasons, meta = connector_plan_score_candidate(parent, plan, row, opts)
        table.insert(scored, { row = row, score = score, reasons = reasons, meta = meta })
    end
    table.sort(scored, function(a, b) return (a.score or 0) > (b.score or 0) end)
    tg_world_obstacle_filter_scored(scored, nil, opts, "plan_pick")

    local usable = {}
    for _, item in ipairs(scored) do
        if tg_world_obstacle_candidate_is_usable(item, opts) then table.insert(usable, item) end
    end

    if #usable == 0 then
        local top = scored[1]
        return nil, scored, "allRejected:" .. tostring(top and top.reasons)
    end

    local top_n = math.min(#usable, tonumber(opts.top_n or 2) or 2)
    local pick_index = 1
    if top_n > 1 then pick_index = math.random(top_n) end
    return usable[pick_index], scored, "ok"
end

function connector_plan_next_direction(parent_direction, row)
    local next_direction = tostring(row and row.direction or "")
    if next_direction ~= "left" and next_direction ~= "right" then
        next_direction = tostring(parent_direction or "left")
    end
    return next_direction
end

function connector_plan_build_once(total_pieces, opts)
    opts = opts or {}
    total_pieces = tonumber(total_pieces or 40) or 40
    local pos, heading = tg_get_local_position_heading("plan_first_start")
    heading = heading or 0.0
    local sx, sy, sz = calculate_new_position(pos, heading, 18.0, 0.0, 1.2)
    local start = {
        model = "stt_prop_track_straight_bar_m",
        x = sx,
        y = sy,
        z = sz,
        heading = heading,
        direction = "left",
        angle = 0,
        start = true
    }

    local plan = { start }
    local target = start
    local random_until = math.max(6, math.floor(total_pieces * 0.56))

    for i = 2, total_pieces do
        local parent = plan[#plan]
        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        step_opts.no_180 = true
        step_opts.strict_overlap = true
        step_opts.top_n = 2
        step_opts.plan_hard_sample_dist = opts.plan_hard_sample_dist or TG_PLAN_HARD_SAMPLE_DIST
        step_opts.plan_start_guard_dist = opts.plan_start_guard_dist or TG_PLAN_START_GUARD_DIST

        if i > random_until then
            step_opts.target_meta = target
            step_opts.prefer_towards_target = true
            step_opts.prefer_turns = true
            step_opts.no_front = (i % 3 == 0)
            step_opts.top_n = 1
        elseif i % 5 == 0 then
            step_opts.prefer_straight = true
        elseif i % 4 == 0 then
            step_opts.prefer_turns = true
        end

        local chosen, scored, why = connector_plan_pick_candidate(parent, plan, step_opts)
        if not chosen then
            return nil, "step" .. tostring(i) .. "_" .. tostring(why), plan
        end

        local meta = chosen.meta
        meta.model = chosen.row.child
        meta.direction = connector_plan_next_direction(parent.direction, chosen.row)
        meta.row = chosen.row
        meta.index = i
        table.insert(plan, meta)
    end

    local end_meta = plan[#plan]
    local close_dist = tg_distance2d(end_meta, target)
    local max_close = tonumber(opts.plan_close_dist or TG_PLAN_CLOSE_DIST or 82.0) or 82.0

    if close_dist > max_close then
        return nil, "openDist=" .. string.format("%.1f", close_dist), plan
    end

    -- Optional short closing straight only. This is planned and overlap-checked first.
    local bridge_limit = tonumber(opts.plan_max_final_bridge_pieces or TG_PLAN_MAX_FINAL_BRIDGE_PIECES or 2) or 2
    if close_dist > 38.0 and bridge_limit > 0 then
        local dx = target.x - end_meta.x
        local dy = target.y - end_meta.y
        local dz = target.z - end_meta.z
        local atan2 = math.atan2 or math.atan
        local bridge_heading = tg_normalize_heading(math.deg(atan2(dy, dx)))
        local bridge_count = math.min(bridge_limit, math.max(1, math.floor(close_dist / 53.0)))
        for b = 1, bridge_count do
            local t = b / (bridge_count + 1)
            local bm = {
                model = "stt_prop_track_straight_bar_m",
                x = end_meta.x + dx * t,
                y = end_meta.y + dy * t,
                z = end_meta.z + dz * t,
                heading = bridge_heading,
                direction = "left",
                angle = 0,
                planned_bridge = true
            }
            local op, oreason, hard = connector_plan_overlap_penalty(bm, plan, opts)
            if hard then return nil, "bridgeOverlap:" .. tostring(oreason), plan end
            local world_blocked, world_reason = tg_world_obstacle_probe_meta(bm, 0, "plan_bridge")
            if world_blocked then return nil, "bridgeObstacle:" .. tostring(world_reason), plan end
            table.insert(plan, bm)
        end
    end

    return plan, "ok", plan
end

function connector_plan_route_quality(plan, opts)
    opts = opts or {}
    if not plan or #plan < 8 then return false, "tooFewPieces" end
    local start = plan[1]
    local finish = plan[#plan]
    local dist = tg_distance2d(start, finish)
    local min_x, max_x, min_y, max_y = 999999.0, -999999.0, 999999.0, -999999.0
    for _, m in ipairs(plan) do
        if m.x < min_x then min_x = m.x end
        if m.x > max_x then max_x = m.x end
        if m.y < min_y then min_y = m.y end
        if m.y > max_y then max_y = m.y end
    end
    local spread = math.max(max_x - min_x, max_y - min_y)
    if dist > (opts.plan_close_dist or TG_PLAN_CLOSE_DIST or 82.0) then
        return false, "openDist=" .. string.format("%.1f", dist)
    end
    if spread < (opts.min_route_spread or TG_LOOP_MIN_ROUTE_SPREAD or 115.0) then
        return false, "smallSpread=" .. string.format("%.1f", spread)
    end
    return true, "dist=" .. string.format("%.1f", dist) .. " spread=" .. string.format("%.1f", spread)
end

function connector_materialize_plan(plan, opts)
    opts = opts or {}
    opts.generation_token = opts.generation_token or tg_generation_start("materialize_plan")
    local gen_token = opts.generation_token
    if not plan or #plan == 0 then return false end
    clear_race_track("planned_materialize")
    connector_reset_state()

    tg_log("[PLAN][MATERIALIZE_BEGIN] pieces=" .. tostring(#plan) .. " tetris=" .. tostring(opts.tetris_preview == true))
    for i, meta in ipairs(plan) do
        if tg_generation_should_stop(gen_token, "materialize_plan_" .. tostring(i)) then return false end
        if opts.tetris_preview and i > 1 then
            local preview_start = connector_random_preview_start_heading(meta.heading, opts, true)
            local preview = connector_create_preview_object(meta.model, meta.x, meta.y, meta.z + (opts.preview_lift or 1.25), preview_start, "planned_piece_" .. tostring(i))
            connector_animate_preview_heading(preview, preview_start, meta.heading, opts, "planned_piece_" .. tostring(i), true)
            util.yield(opts.preview_delay_ms or 80)
            connector_delete_preview_object(preview, "planned_piece_" .. tostring(i) .. "_delete")
        end

        if i > 1 then
            local ignore_parent = (connector_builder_state and type(connector_builder_state.current_obj) == "number") and connector_builder_state.current_obj or 0
            local blocked, reason = tg_world_obstacle_probe_meta(meta, ignore_parent, "materialize_" .. tostring(i))
            if blocked then
                tg_warn("OBSTACLE", "planned materialize refused i=" .. tostring(i) .. " reason=" .. tostring(reason))
                return false
            end
        end

        local obj = create_track_object(meta.model, meta.x, meta.y, meta.z, meta.heading)
        if not obj or obj == 0 then
            tg_warn("PLAN", "materialize failed at i=" .. tostring(i) .. " model=" .. tostring(meta.model))
            return false
        end

        if i == 1 then
            connector_builder_state.active = true
            connector_builder_state.start_obj = obj
            connector_builder_state.current_direction = "left"
        end

        connector_builder_state.current_obj = obj
        connector_builder_state.current_model = meta.model
        connector_builder_state.current_direction = meta.direction or connector_builder_state.current_direction or "left"
        connector_builder_state.current_heading = meta.heading
        connector_builder_state.pieces = i
        connector_builder_state.accepted = i
        table.insert(connector_builder_state.history, { obj = obj, model = meta.model, direction = connector_builder_state.current_direction, heading = meta.heading, planned = true })

        tg_log("[PLAN][SPAWN] #" .. tostring(i) ..
            " obj=" .. tg_handle(obj) ..
            " model=" .. tostring(meta.model) ..
            " pos=" .. tg_vec_str(meta) ..
            " heading=" .. string.format("%.1f", tonumber(meta.heading or 0.0) or 0.0))
        util.yield(opts.delay_ms or 70)
    end

    local dist = tg_distance2d(plan[1], plan[#plan])
    tg_log("[PLAN][MATERIALIZE_DONE] pieces=" .. tostring(#plan) .. " finalDistToStart=" .. string.format("%.1f", dist))
    tg_report_state("planned_loop_done")
    return true
end

function connector_build_planned_random_loop(opts)
    opts = opts or {}
    local minv = tonumber(TG_LOOP_RANDOM_MIN or 18) or 18
    local maxv = tonumber(TG_LOOP_RANDOM_MAX or 60) or 60
    if maxv < minv then maxv = minv end
    local attempts = tonumber(opts.plan_attempts or TG_PLAN_ATTEMPTS or 28) or 28
    if attempts < 1 then attempts = 1 end

    local best_plan = nil
    local best_reason = "none"
    local best_len = 0

    for attempt = 1, attempts do
        if tg_generation_should_stop(gen_token, "random_loop_attempt_" .. tostring(attempt)) then return false end
        local total = math.random(minv, maxv)
        tg_log("[PLAN][TRY] attempt=" .. tostring(attempt) .. "/" .. tostring(attempts) .. " targetPieces=" .. tostring(total))
        local plan, reason, partial = connector_plan_build_once(total, opts)
        if plan then
            local ok, q = connector_plan_route_quality(plan, opts)
            tg_log("[PLAN][QUALITY] ok=" .. tostring(ok) .. " reason=" .. tostring(q) .. " pieces=" .. tostring(#plan))
            if ok then
                tg_log("[PLAN][ACCEPT] attempt=" .. tostring(attempt) .. " pieces=" .. tostring(#plan) .. " reason=" .. tostring(q))
                return connector_materialize_plan(plan, opts)
            end
            reason = q
        end
        if partial and #partial > best_len then
            best_plan = partial
            best_len = #partial
            best_reason = reason
        end
        tg_log("[PLAN][REJECT] attempt=" .. tostring(attempt) .. " reason=" .. tostring(reason) .. " partialPieces=" .. tostring(partial and #partial or 0))
        util.yield(15)
    end

    tg_warn("PLAN", "no valid preplanned loop found; not spawning bad layout. bestPartialPieces=" .. tostring(best_len) .. " bestReason=" .. tostring(best_reason))
    return false
end


function connector_build_planned_random_loop_until_success(opts)
    opts = opts or {}
    opts.generation_token = opts.generation_token or tg_generation_start("auto_plan_until_success")
    local gen_token = opts.generation_token
    local max_attempts = tonumber(opts.auto_max_attempts or TG_PLAN_AUTO_MAX_ATTEMPTS or 500) or 500
    if max_attempts < 1 then max_attempts = 1 end
    local relax_after = tonumber(opts.relax_after or TG_PLAN_RELAX_AFTER or 80) or 80
    local progress_every = tonumber(opts.progress_log_every or TG_PLAN_PROGRESS_LOG_EVERY or 25) or 25

    local minv = tonumber(TG_LOOP_RANDOM_MIN or 18) or 18
    local maxv = tonumber(TG_LOOP_RANDOM_MAX or 60) or 60
    if maxv < minv then maxv = minv end

    local best_plan = nil
    local best_len = 0
    local best_reason = "none"

    tg_print_version_banner("AUTO_PLAN_BEGIN")
    tg_log("[AUTO_PLAN][BEGIN] maxAttempts=" .. tostring(max_attempts) ..
        " min=" .. tostring(minv) ..
        " max=" .. tostring(maxv) ..
        " relaxAfter=" .. tostring(relax_after))

    for attempt = 1, max_attempts do
        if tg_generation_should_stop(gen_token, "auto_plan_attempt_" .. tostring(attempt)) then return false end
        local trial_opts = {}
        for k, v in pairs(opts) do trial_opts[k] = v end

        if attempt > relax_after then
            -- After enough safe rejections, slightly relax false-positive sample checks.
            trial_opts.plan_hard_sample_dist = tonumber(opts.relaxed_plan_hard_sample_dist or TG_PLAN_RELAX_HARD_SAMPLE_DIST or 24.0) or 24.0
            trial_opts.plan_start_guard_dist = tonumber(opts.relaxed_plan_start_guard_dist or TG_PLAN_RELAX_START_GUARD_DIST or 92.0) or 92.0
            trial_opts.plan_close_dist = math.max(tonumber(opts.plan_close_dist or TG_PLAN_CLOSE_DIST or 82.0) or 82.0, 96.0)
        end

        local total = math.random(minv, maxv)
        local plan, reason, partial = connector_plan_build_once(total, trial_opts)

        if plan then
            local ok, q = connector_plan_route_quality(plan, trial_opts)
            if ok then
                tg_log("[AUTO_PLAN][SUCCESS] attempt=" .. tostring(attempt) ..
                    " targetPieces=" .. tostring(total) ..
                    " finalPieces=" .. tostring(#plan) ..
                    " relaxed=" .. tostring(attempt > relax_after) ..
                    " quality=" .. tostring(q))
                return connector_materialize_plan(plan, trial_opts)
            end
            reason = q
        end

        if partial and #partial > best_len then
            best_plan = partial
            best_len = #partial
            best_reason = reason
        end

        if attempt == 1 or attempt % progress_every == 0 then
            tg_log("[AUTO_PLAN][PROGRESS] attempt=" .. tostring(attempt) ..
                "/" .. tostring(max_attempts) ..
                " lastReason=" .. tostring(reason) ..
                " bestPartialPieces=" .. tostring(best_len) ..
                " relaxed=" .. tostring(attempt > relax_after))
        end

        -- Yield every attempt so Cherax/GTA does not hard-freeze while planning.
        util.yield(0)
    end

    tg_warn("AUTO_PLAN", "no valid plan after max attempts; not spawning bad layout. bestPartialPieces=" .. tostring(best_len) .. " bestReason=" .. tostring(best_reason))
    return false
end

function connector_build_random_looping_track(opts)
    opts = opts or {}
    opts.generation_token = opts.generation_token or tg_generation_start("preview_random_loop")
    local gen_token = opts.generation_token
    local minv = tonumber(TG_LOOP_RANDOM_MIN or 18) or 18
    local maxv = tonumber(TG_LOOP_RANDOM_MAX or 60) or 60
    if maxv < minv then maxv = minv end
    local attempts = tonumber(opts.retry_attempts or TG_LOOP_RANDOM_RETRY_ATTEMPTS or 5) or 5
    if attempts < 1 then attempts = 1 end

    for attempt = 1, attempts do
        local total = math.random(minv, maxv)
        tg_log("[LOOP][RANDOM_RETRY] attempt=" .. tostring(attempt) ..
            "/" .. tostring(attempts) ..
            " min=" .. tostring(minv) ..
            " max=" .. tostring(maxv) ..
            " chosen=" .. tostring(total) ..
            " mode=no_long_snap_retry")
        local ok, status = connector_build_looping_track(total, opts)
        if tg_generation_should_stop(gen_token, "random_loop_after_attempt_" .. tostring(attempt)) then return false end
        if ok then
            tg_log("[LOOP][RANDOM_SUCCESS] attempt=" .. tostring(attempt) .. " status=" .. tostring(status))
            return true
        end
        tg_warn("LOOP", "random loop attempt failed quality/closure; retrying with fresh layout attempt=" .. tostring(attempt) .. " status=" .. tostring(status))
        if attempt < attempts then
            util.yield(500)
        end
    end

    tg_warn("LOOP", "all random loop retry attempts failed; last failed layout left visible for inspection")
    return false
end



-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.5.7 legacy-smart no-starter loop
-- ═══════════════════════════════════════════════════════════════════════════════════
-- this keeps the natural "legacy random loop" behavior, but avoids the visible starter
-- piece becoming a collision/overlap target. It spawns a short-lived seed only to get
-- the first real piece positioned, then deletes the seed and continues normally.
-- No retry loop: if the route fails, it stops and leaves the result for inspection.


function connector_apply_legacy_smart_clearance_opts(step_opts)
    step_opts = step_opts or {}
    step_opts.legacy_smart_clearance = true
    -- v0.6.0: use clearance as strong scoring, not as an immediate dead-end.
    step_opts.strict_overlap = false
    step_opts.overlap_skip_recent = tonumber(TG_LEGACY_SMART_SKIP_RECENT or 1) or 1
    step_opts.overlap_center_hard_dist = tonumber(TG_LEGACY_SMART_CLEARANCE_RADIUS or 54.0) or 54.0
    step_opts.overlap_center_soft_dist = tonumber(TG_LEGACY_SMART_SOFT_RADIUS or 76.0) or 76.0
    step_opts.overlap_sample_hard_dist = tonumber(TG_LEGACY_SMART_SAMPLE_HARD or 28.0) or 28.0
    step_opts.overlap_sample_soft_dist = tonumber(TG_LEGACY_SMART_SAMPLE_SOFT or 42.0) or 42.0
    step_opts.parent_turn_min_dist = tonumber(TG_LEGACY_SMART_PARENT_TURN_MIN_DIST or 40.0) or 40.0
    return step_opts
end

function connector_delete_seed_start_if_needed(reason)
    reason = reason or "delete_seed"
    if connector_builder_state and connector_builder_state.no_starter_seed_obj then
        local seed = connector_builder_state.no_starter_seed_obj
        local seed_meta = tg_get_meta(seed)
        local keep_visible = seed_meta and seed_meta.keep_visible_seed == true
        tg_log("[NO_STARTER][DELETE_SEED] reason=" .. tostring(reason) .. " seed=" .. tg_handle(seed) .. " keepVisible=" .. tostring(keep_visible))
        if not keep_visible then
            tg_delete(seed)
        else
            tg_log("[START_RAMP][KEEP_FLAT_EXIT] logical seed removed from planner history; visible flat ramp exit remains")
        end
        connector_builder_state.no_starter_seed_obj = nil
        -- v0.6.1: remove the temporary seed from history. It is no longer visible, so overlap logic must not reject against it.
        local new_history = {}
        for _, entry in ipairs(connector_builder_state.history or {}) do
            if entry and entry.obj ~= seed then
                table.insert(new_history, entry)
            end
        end
        connector_builder_state.history = new_history
        connector_builder_state.pieces = #new_history
        connector_builder_state.accepted = #new_history
        connector_builder_state.start_obj = connector_builder_state.first_real_obj or connector_builder_state.current_obj
        tg_log("[NO_STARTER][HISTORY_CLEAN] removedSeed=" .. tg_handle(seed) .. " pieces=" .. tostring(connector_builder_state.pieces))
    end
end

function connector_spawn_seed_start_no_starter(label)
    label = label or "legacy_smart_seed"
    local seed = connector_spawn_start(label, { seed_mode = true })
    if not seed or seed == 0 then return nil end

    if connector_builder_state.snake_starter_mode then
        -- v0.6.9: in snake mode the returned object is the real front launch piece,
        -- not a temporary seed, so do not delete/promote it away.
        connector_builder_state.seed_start_meta = tg_get_meta(connector_builder_state.loop_target_obj or seed)
        tg_log("[SNAKE][SEED_MODE] front launch is real; rear goal is loop target=" .. tg_handle(connector_builder_state.loop_target_obj))
        return seed
    end

    connector_builder_state.no_starter_seed_obj = seed
    connector_builder_state.seed_start_meta = tg_get_meta(seed)
    tg_log("[NO_STARTER][SEED] spawned temporary seed=" .. tg_handle(seed) .. " pos=" .. tg_vec_str(connector_builder_state.seed_start_meta))
    return seed
end

function connector_promote_first_real_piece(obj, label)
    if not obj or obj == 0 then return end
    if connector_builder_state.no_starter_seed_obj and not connector_builder_state.first_real_obj then
        connector_builder_state.first_real_obj = obj
        connector_builder_state.start_obj = obj
        -- Remove seed from visible world after first real track piece exists.
        connector_delete_seed_start_if_needed(label or "first_real_piece")
        connector_builder_state.current_obj = obj
        connector_builder_state.current_model = (tg_get_meta(obj) and tg_get_meta(obj).model) or connector_builder_state.current_model
        connector_builder_state.active = true
        tg_log("[NO_STARTER][PROMOTE] firstReal=" .. tg_handle(obj) .. " meta=" .. tg_vec_str(tg_get_meta(obj)))
    end
end

function connector_try_next_legacy_smart(label, opts)
    opts = opts or {}
    local obj, candidate = connector_try_next(label, opts)
    if obj then connector_promote_first_real_piece(obj, label) end
    return obj, candidate
end


function connector_legacy_smart_backtrack(count, reason)
    count = tonumber(count or TG_LEGACY_SMART_BACKTRACK_DELETE_COUNT or 1) or 1
    reason = tostring(reason or "blocked")
    local removed = 0
    for _ = 1, count do
        local h = connector_builder_state.history or {}
        if #h <= 1 then break end -- keep first real piece as baseline
        local entry = h[#h]
        local obj = entry and entry.obj
        connector_deadend_mark(entry, reason)
        if obj and obj ~= 0 then
            tg_log("[BACKTRACK][DELETE] reason=" .. reason .. " obj=" .. tg_handle(obj) .. " model=" .. tostring(entry.model))
            tg_delete(obj)
            for i = #objects, 1, -1 do
                if objects[i] == obj then table.remove(objects, i); break end
            end
            for i = #entity_can_tint, 1, -1 do
                if entity_can_tint[i] == obj then table.remove(entity_can_tint, i); break end
            end
            removed = removed + 1
        end
        table.remove(h, #h)
        connector_builder_state.history = h
    end
    local h = connector_builder_state.history or {}
    local last = h[#h]
    if last and last.obj then
        connector_builder_state.current_obj = last.obj
        connector_builder_state.current_model = last.model or (tg_get_meta(last.obj) and tg_get_meta(last.obj).model) or connector_builder_state.current_model
        connector_builder_state.current_direction = last.direction or connector_builder_state.current_direction or "left"
        connector_builder_state.current_heading = last.heading or connector_builder_state.current_heading or 0.0
        connector_builder_state.pieces = #h
        connector_builder_state.accepted = #h
        connector_port_reopen_current_after_backtrack(last)
        tg_log("[BACKTRACK][DONE] removed=" .. tostring(removed) .. " nowPieces=" .. tostring(#h) .. " current=" .. tg_handle(last.obj))
        return removed > 0
    end
    tg_log("[BACKTRACK][FAILED] reason=" .. reason .. " removed=" .. tostring(removed) .. " history=" .. tostring(#h))
    return false
end


function connector_apply_straight_run_opts(step_opts)
    step_opts = step_opts or {}
    if TG_SNAKE_STRAIGHT_RHYTHM == false then return step_opts end

    local h = connector_builder_state and connector_builder_state.history or {}
    local last = h[#h]
    local last_turn = connector_turn_sign_from_entry(last)

    if last_turn ~= 0 and (TG_STRAIGHT_RUN_ACTIVE or 0) <= 0 then
        TG_STRAIGHT_RUN_TARGET = math.random(TG_STRAIGHT_RUN_MIN or 3, TG_STRAIGHT_RUN_MAX or 7)
        TG_STRAIGHT_RUN_ACTIVE = TG_STRAIGHT_RUN_TARGET
        tg_log("[TRACKMATIC][PROGRESS] straight-run armed after curve target=" .. tostring(TG_STRAIGHT_RUN_TARGET))
    end

    if (TG_STRAIGHT_RUN_ACTIVE or 0) > 0 then
        step_opts.prefer_straight = true
        step_opts.snake_force_straight = true
        step_opts.top_n = 1
        TG_STRAIGHT_RUN_ACTIVE = TG_STRAIGHT_RUN_ACTIVE - 1
    end

    return step_opts
end



-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.7.3 dynamic loop budget helpers
-- ═══════════════════════════════════════════════════════════════════════════════════

function tg_loop_profile(max_pieces)
    max_pieces = tonumber(max_pieces or TG_LOOP15_MAX_PIECES or 15) or 15
    if max_pieces < 8 then max_pieces = 8 end

    local seg = tonumber(TG_LOOP_SNAP_SEGMENT_LEN or 53.0) or 53.0
    local reserve = math.floor(max_pieces * (TG_LOOP15_RESERVE_RATIO or 0.46) + 0.5)
    if reserve < (TG_LOOP15_MIN_RESERVE or 6) then reserve = (TG_LOOP15_MIN_RESERVE or 6) end
    if reserve > (TG_LOOP15_MAX_RESERVE or 8) then reserve = (TG_LOOP15_MAX_RESERVE or 8) end
    if reserve >= max_pieces then reserve = math.max(3, max_pieces - 5) end

    local explore = max_pieces - reserve
    if explore < 4 then explore = 4 end
    if explore > max_pieces - 3 then explore = max_pieces - 3 end
    reserve = max_pieces - explore

    local max_x = math.max(TG_LOOP15_MIN_BOUND_X or 135.0, seg * max_pieces * (TG_LOOP15_BOUND_SCALE_X or 0.24))
    local max_y = math.max(TG_LOOP15_MIN_BOUND_Y or 155.0, seg * max_pieces * (TG_LOOP15_BOUND_SCALE_Y or 0.28))
    local return_start = math.max(4, math.floor(explore * (TG_LOOP15_RETURN_RATIO or 0.48) + 0.5))
    local force_budget = math.max(0, math.min(3, max_pieces - explore - 3))

    return {
        max_pieces = max_pieces,
        target = max_pieces,
        explore = explore,
        reserve = reserve,
        return_start = return_start,
        max_x = max_x,
        max_y = max_y,
        force_budget = force_budget,
        close_dist = TG_LOOP15_CLOSE_DIST or 82.0,
        force_touch_max_dist = TG_LOOP15_FORCE_TOUCH_MAX_DIST or 185.0, -- seed only; v0.7.4 expands dynamically from remaining budget
        start_guard = 92.0,
        no_return_until = return_start
    }
end

function tg_loop_profile_log(prefix, profile)
    profile = profile or tg_loop_profile(TG_LOOP15_MAX_PIECES or 15)
    tg_log(tostring(prefix or "[LOOP][PROFILE]") ..
        " maxPieces=" .. tostring(profile.max_pieces) ..
        " explore=" .. tostring(profile.explore) ..
        " returnReserve=" .. tostring(profile.reserve) ..
        " returnStart=" .. tostring(profile.return_start) ..
        " maxX=" .. string.format("%.1f", profile.max_x or 0.0) ..
        " maxY=" .. string.format("%.1f", profile.max_y or 0.0) ..
        " forceBudget=" .. tostring(profile.force_budget) ..
        " closeDist=" .. string.format("%.1f", profile.close_dist or 0.0))
end

function connector_apply_loop15_shape_opts(step_opts, step_i, target, profile)
    step_opts = step_opts or {}
    profile = profile or tg_loop_profile(target or TG_LOOP15_MAX_PIECES or 15)

    step_opts.small_loop_15 = true
    step_opts.natural_road = true
    step_opts.loop_bounds = true
    step_opts.loop_bound_max_x = profile.max_x
    step_opts.loop_bound_max_y = profile.max_y
    step_opts.no_180 = true
    step_opts.snake_straight_rhythm = false
    step_opts.start_guard_dist = profile.start_guard or 92.0
    step_opts.no_return_until_pieces = profile.no_return_until or 6
    step_opts.top_n = step_opts.top_n or 3

    local total, straight, curve, straight_run, curve_run, straight_pct, curve_pct = tg_road_stats()
    local minp = TG_LOOP15_STRAIGHT_MIN_PERCENT or 20
    local maxp = TG_LOOP15_STRAIGHT_MAX_PERCENT or 40

    if straight_run >= (TG_LOOP15_MAX_STRAIGHT_RUN or 2) or (total >= 3 and straight_pct >= maxp) then
        step_opts.no_front = true
        step_opts.prefer_turns = true
        step_opts.road_force_curve = true
    elseif curve_run >= (TG_LOOP15_MAX_CURVE_RUN or 5) or (total >= 5 and straight_pct <= minp) then
        step_opts.prefer_straight = true
        step_opts.road_force_straight = true
    elseif math.random(100) <= 68 then
        step_opts.prefer_turns = true
    else
        step_opts.prefer_straight = true
    end

    return step_opts
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.7.1 natural curvy road builder
-- ═══════════════════════════════════════════════════════════════════════════════════
-- purpose:
--   Build an open road instead of a loop/star.
--   Target ratio: 20-40% straightaways, 60-80% curves.
--   No forced loopback bridge, no rear snake goal, no star closure.

function tg_road_piece_is_straight(entry)
    if not entry then return false end
    return tostring(entry.model or "") == "stt_prop_track_straight_bar_m"
end

function tg_road_stats()
    local h = connector_builder_state and connector_builder_state.history or {}
    local total, straight, curve = 0, 0, 0
    local straight_run, curve_run = 0, 0
    for _, entry in ipairs(h) do
        if entry and entry.obj then
            total = total + 1
            if tg_road_piece_is_straight(entry) then
                straight = straight + 1
                straight_run = straight_run + 1
                curve_run = 0
            else
                curve = curve + 1
                curve_run = curve_run + 1
                straight_run = 0
            end
        end
    end
    local straight_pct = (total > 0) and ((straight * 100.0) / total) or 0.0
    local curve_pct = (total > 0) and ((curve * 100.0) / total) or 0.0
    return total, straight, curve, straight_run, curve_run, straight_pct, curve_pct
end

function connector_apply_natural_road_opts(step_opts, step_i, target)
    step_opts = step_opts or {}
    step_i = tonumber(step_i or 1) or 1
    target = tonumber(target or 40) or 40

    step_opts.natural_road = true
    step_opts.no_180 = true
    step_opts.snake_straight_rhythm = false
    step_opts.snake_force_straight = false
    step_opts.loopback_final = false
    step_opts.prefer_towards_target = false
    step_opts.target_meta = nil
    step_opts.allow_start_close = false
    step_opts.start_avoid_dist = 0
    step_opts.start_guard_dist = TG_ROAD_START_GUARD_DIST or 185.0
    step_opts.no_return_until_pieces = TG_ROAD_NO_RETURN_UNTIL or 999
    step_opts.top_n = step_opts.top_n or 5

    local total, straight, curve, straight_run, curve_run, straight_pct, curve_pct = tg_road_stats()
    local minp = tonumber(TG_ROAD_STRAIGHT_MIN_PERCENT or 20) or 20
    local maxp = tonumber(TG_ROAD_STRAIGHT_MAX_PERCENT or 40) or 40
    local roll = math.random(100)

    -- Hard guards for the requested visual ratio.
    if total >= 3 and straight_pct >= maxp then
        step_opts.no_front = true
        step_opts.prefer_turns = true
        step_opts.road_force_curve = true
    elseif total >= 5 and straight_pct <= minp then
        step_opts.only_front = true
        step_opts.prefer_straight = true
        step_opts.road_force_straight = true
    elseif straight_run >= (TG_ROAD_MAX_STRAIGHT_RUN or 2) then
        step_opts.no_front = true
        step_opts.prefer_turns = true
        step_opts.road_force_curve = true
    elseif curve_run >= (TG_ROAD_MAX_CURVE_RUN or 5) then
        step_opts.prefer_straight = true
        step_opts.road_force_straight = true
    else
        if roll <= (TG_ROAD_CURVE_BIAS_PERCENT or 70) then
            step_opts.prefer_turns = true
            if roll <= 38 then step_opts.no_front = true end
        else
            step_opts.prefer_straight = true
        end
    end

    return step_opts
end

function connector_build_natural_curvy_road(opts)
    opts = opts or {}
    opts.generation_token = opts.generation_token or tg_generation_start("natural_curvy_road")
    local gen_token = opts.generation_token

    clear_race_track("natural_curvy_road")
    TG_STRAIGHT_RUN_ACTIVE = 0
    TG_STRAIGHT_RUN_TARGET = 0

    local old_snake = TG_SNAKE_STARTER_ENABLED
    TG_SNAKE_STARTER_ENABLED = false
    local start = connector_spawn_start("natural_curvy_road_start")
    TG_SNAKE_STARTER_ENABLED = old_snake

    if not start then
        tg_error("[ROAD] failed to spawn natural road start")
        return false
    end

    local minv = tonumber(TG_LOOP_RANDOM_MIN or 18) or 18
    local maxv = tonumber(TG_LOOP_RANDOM_MAX or 60) or 60
    if maxv < minv then maxv = minv end
    if maxv < 30 then maxv = 30 end
    local target = math.random(math.max(minv, 28), maxv)

    tg_log("[ROAD][BEGIN] target=" .. tostring(target) ..
        " desiredStraight=" .. tostring(TG_ROAD_STRAIGHT_MIN_PERCENT) .. "-" .. tostring(TG_ROAD_STRAIGHT_MAX_PERCENT) .. "%" ..
        " desiredCurves=60-80%" ..
        " mode=open-road-no-loopback")

    local i = math.max(2, (tonumber(connector_builder_state.pieces or 1) or 1) + 1)
    local backtracks = 0
    while i <= target do
        util.yield(opts.delay_ms or 90)
        if tg_generation_should_stop(gen_token, "natural_road_step_" .. tostring(i)) then return false end

        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        connector_apply_legacy_smart_clearance_opts(step_opts)
        connector_apply_natural_road_opts(step_opts, i, target)

        local obj = connector_try_next_legacy_smart("natural_road_step_" .. tostring(i), step_opts)
        if obj then
            i = i + 1
            local total, straight, curve, straight_run, curve_run, straight_pct, curve_pct = tg_road_stats()
            if total % (TG_LOG_PROGRESS_EVERY or 5) == 0 then
                tg_log("[ROAD][PROGRESS] pieces=" .. tostring(total) ..
                    " straight=" .. tostring(straight) .. "(" .. string.format("%.0f", straight_pct) .. "%)" ..
                    " curves=" .. tostring(curve) .. "(" .. string.format("%.0f", curve_pct) .. "%)" ..
                    " straightRun=" .. tostring(straight_run) ..
                    " curveRun=" .. tostring(curve_run))
            end
        else
            backtracks = backtracks + 1
            if backtracks > (TG_ROAD_BACKTRACK_LIMIT or 18) or not connector_legacy_smart_backtrack(TG_ROAD_BACKTRACK_DELETE_COUNT or 2, "natural_road_blocked_step_" .. tostring(i)) then
                tg_warn("ROAD", "stopped early at step=" .. tostring(i) .. " backtracks=" .. tostring(backtracks))
                break
            end
            i = math.max(2, i - 1)
        end
    end

    local total, straight, curve, straight_run, curve_run, straight_pct, curve_pct = tg_road_stats()
    tg_log("[ROAD][DONE] status=NATURAL_ROAD_DONE placed=" .. tostring(total) ..
        " straight=" .. tostring(straight) .. "(" .. string.format("%.0f", straight_pct) .. "%)" ..
        " curves=" .. tostring(curve) .. "(" .. string.format("%.0f", curve_pct) .. "%)" ..
        " note=open road; no forced loop/star closure")
    tg_report_state("natural_curvy_road_done")
    return true
end

function connector_build_legacy_smart_no_starter_loop(opts)
    opts = opts or {}
    opts.generation_token = opts.generation_token or tg_generation_start("smart_random_loop")
    local gen_token = opts.generation_token
    clear_race_track("legacy_smart_no_starter")
    local old_snake_starter_enabled = TG_SNAKE_STARTER_ENABLED
    if opts.no_snake_starter then TG_SNAKE_STARTER_ENABLED = false end
    connector_spawn_seed_start_no_starter("legacy_smart_no_starter_seed")
    TG_SNAKE_STARTER_ENABLED = old_snake_starter_enabled

    local loop_profile = opts.loop_profile or nil
    if opts.small_loop_15 then
        loop_profile = tg_loop_profile(tonumber(opts.max_target or opts.fixed_target or TG_LOOP15_MAX_PIECES or 15) or 15)
        opts.loop_profile = loop_profile
        opts.max_total_pieces = loop_profile.max_pieces
        opts.close_dist = loop_profile.close_dist
        opts.force_touch_max_dist = loop_profile.force_touch_max_dist
        tg_loop_profile_log("[LOOP15][PROFILE]", loop_profile)
    end

    local minv = tonumber(TG_LOOP_RANDOM_MIN or 18) or 18
    local maxv = tonumber(TG_LOOP_RANDOM_MAX or 60) or 60
    local target = nil
    if opts.fixed_target or opts.max_target or opts.loop_max_pieces then
        target = tonumber(opts.fixed_target or opts.max_target or opts.loop_max_pieces) or 15
        target = math.floor(target)
    else
        if maxv < minv then maxv = minv end
        if maxv < (TG_SMART_MIN_TARGET_PIECES or 32) then maxv = (TG_SMART_MIN_TARGET_PIECES or 32) end
        target = math.random(math.max(minv, TG_SMART_MIN_TARGET_PIECES or 32), maxv)
    end
    if target < 8 then target = 8 end

    -- v0.7.3: loopback is budget-aware. For 15 Max, reserve enough pieces
    -- to start coming back early instead of waiting until the route is too far away.
    local reserve = tonumber(opts.bridge_reserve or (loop_profile and loop_profile.reserve) or math.floor(target * (TG_SMART_RETURN_RESERVE_RATIO or 0.34))) or 12
    if opts.small_loop_15 then
        if reserve < (TG_LOOP15_MIN_RESERVE or 6) then reserve = (TG_LOOP15_MIN_RESERVE or 6) end
        if reserve > (TG_LOOP15_MAX_RESERVE or 8) then reserve = (TG_LOOP15_MAX_RESERVE or 8) end
    else
        if reserve < (TG_SMART_RETURN_RESERVE_MIN or 12) then reserve = (TG_SMART_RETURN_RESERVE_MIN or 12) end
        if reserve > (TG_SMART_RETURN_RESERVE_MAX or 22) then reserve = (TG_SMART_RETURN_RESERVE_MAX or 22) end
    end
    if reserve >= target then reserve = math.max(3, target - 5) end
    local random_target = tonumber(opts.random_target or (loop_profile and loop_profile.explore) or (target - reserve)) or (target - reserve)
    random_target = math.floor(random_target)
    if random_target < 4 then random_target = 4 end
    if random_target > target - 3 then random_target = target - 3 end
    reserve = target - random_target

    tg_log("[LEGACY_SMART][BEGIN] target=" .. tostring(target) ..
        " randomTarget=" .. tostring(random_target) ..
        " bridgeReserve=" .. tostring(reserve) ..
        " noStarter=true retry=false" ..
        " clearance=" .. tostring(TG_LEGACY_SMART_CLEARANCE_RADIUS) ..
        " sampleHard=" .. tostring(TG_LEGACY_SMART_SAMPLE_HARD) ..
        " skipRecent=" .. tostring(TG_LEGACY_SMART_SKIP_RECENT) ..
        " loopbackClose=" .. tostring(TG_LOOPBACK_CLOSE_DIST) ..
        " mode=" .. tostring(opts.small_loop_15 and "loop15_max" or "legacy_smart") ..
        " maxTotal=" .. tostring(opts.max_total_pieces or "none"))

    -- Natural legacy-style random section with small backtracking.
    local i = 2
    local backtracks = 0
    while i <= random_target do
        util.yield(opts.delay_ms or 90)
        if tg_generation_should_stop(gen_token, "legacy_smart_random_" .. tostring(i)) then return false end
        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        step_opts.no_180 = true
        step_opts.snake_straight_rhythm = TG_SNAKE_STRAIGHT_RHYTHM
        step_opts = connector_apply_straight_run_opts(step_opts)
        step_opts.top_n = step_opts.top_n or 1
        connector_apply_legacy_smart_clearance_opts(step_opts)
        step_opts.allow_start_close = true
        step_opts.start_avoid_dist = 0
        step_opts.start_guard_dist = TG_START_GUARD_SMART_DIST
        step_opts.no_return_until_pieces = TG_SMART_NO_RETURN_UNTIL_PIECES

        if opts.small_loop_15 then
            connector_apply_loop15_shape_opts(step_opts, i, target, loop_profile)
        end

        local return_cutoff = math.floor(random_target * (opts.return_ratio or TG_SMART_RETURN_RATIO or 0.62))
        if opts.small_loop_15 and loop_profile then return_cutoff = loop_profile.return_start end

        if i > return_cutoff and connector_builder_state.first_real_obj then
            step_opts.target_meta = tg_get_meta(connector_builder_state.first_real_obj)
            step_opts.loop_origin_meta = step_opts.target_meta
            step_opts.prefer_towards_target = true
            step_opts.prefer_turns = true
            step_opts.no_front = opts.small_loop_15 and false or (i % 4 == 0)
            step_opts.top_n = opts.small_loop_15 and 3 or 1
        elseif not opts.small_loop_15 and (i <= (TG_SNAKE_OPENING_STRAIGHT_BIAS_PIECES or 8) or (i % 4 == 0) or (i % 4 == 1)) then
            step_opts.prefer_straight = true
        end

        local obj = connector_try_next_legacy_smart("legacy_smart_random_" .. tostring(i), step_opts)
        if obj then
            i = i + 1
        else
            backtracks = backtracks + 1
            tg_warn("LEGACY_SMART", "blocked at step=" .. tostring(i) .. " backtrack=" .. tostring(backtracks) .. "/" .. tostring(TG_LEGACY_SMART_BACKTRACK_LIMIT) .. " retry=false")
            if backtracks > (TG_LEGACY_SMART_BACKTRACK_LIMIT or 12) or not connector_legacy_smart_backtrack(TG_DEADEND_BACKTRACK_DELETE_COUNT or TG_LEGACY_SMART_BACKTRACK_DELETE_COUNT or 2, "random_blocked_step_" .. tostring(i)) then
                connector_delete_seed_start_if_needed("random_failed")
                break
            end
            i = math.max(2, i - 1)
        end
    end

    -- Gentle bridge toward the first real piece, not the deleted seed starter.
    local close_target = connector_builder_state.first_real_obj and tg_get_meta(connector_builder_state.first_real_obj) or tg_get_meta(connector_builder_state.start_obj)
    local bridge_limit = math.max(reserve, opts.small_loop_15 and reserve or (TG_SMART_RETURN_RESERVE_MIN or 12))
    if opts.small_loop_15 and TG_LOOP15_DIRECT_TOUCH_ALWAYS then
        -- Disabled in v0.7.5: direct straight return looked ugly and cut across the track.
        bridge_limit = 0
        tg_log("[LOOP15][DIRECT_TOUCH_MODE_DISABLED] this should not run in v0.7.5")
    end
    for extra = 1, bridge_limit do
        if opts.max_total_pieces and (connector_builder_state.pieces or 0) >= opts.max_total_pieces then
            tg_log("[LOOP15][BUDGET_STOP] phase=bridge pieces=" .. tostring(connector_builder_state.pieces) .. "/" .. tostring(opts.max_total_pieces))
            break
        end
        if tg_generation_should_stop(gen_token, "legacy_smart_bridge_" .. tostring(extra)) then return false end
        if not close_target then break end
        local cur = tg_get_meta(connector_builder_state.current_obj)
        local dist = tg_distance2d(cur, close_target)
        if dist < (opts.close_dist or TG_LOOP_CLOSE_DIST or 28.0) then
            tg_log("[LEGACY_SMART][CLOSE] extra=" .. tostring(extra - 1) .. " dist=" .. string.format("%.1f", dist))
            break
        end

        util.yield(opts.delay_ms or 90)
        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        step_opts.target_meta = close_target
        step_opts.prefer_towards_target = true
        step_opts.loopback_final = true
        step_opts.loopback_close_dist = TG_LOOPBACK_CLOSE_DIST
        step_opts.prefer_turns = true
        step_opts.no_180 = (extra <= reserve - 3)
        step_opts.top_n = 1
        connector_apply_legacy_smart_clearance_opts(step_opts)
        if opts.small_loop_15 then
            connector_apply_loop15_shape_opts(step_opts, random_target + extra, target, loop_profile)
            step_opts.target_meta = close_target
            step_opts.loop_origin_meta = close_target
            step_opts.prefer_towards_target = true
            step_opts.loopback_final = true
            step_opts.prefer_turns = true
            step_opts.no_front = false
            step_opts.top_n = tonumber(TG_LOOP15_RETURN_TOP_N or 2) or 2
            if TG_LOOP15_RETURN_STRICT_OVERLAP then step_opts.strict_overlap = true end
        end
        step_opts.allow_start_close = true
        step_opts.start_avoid_dist = 0

        local obj = connector_try_next_legacy_smart("legacy_smart_bridge_" .. tostring(extra), step_opts)
        if not obj then
            tg_warn("LEGACY_SMART", "bridge blocked extra=" .. tostring(extra) .. " attempting one backtrack")
            if not connector_legacy_smart_backtrack(1, "bridge_blocked_" .. tostring(extra)) then break end
        end
    end

    connector_delete_seed_start_if_needed("done")
    if opts.max_total_pieces then
        local remaining_touch_budget = math.max(0, (opts.max_total_pieces or 0) - (connector_builder_state.pieces or 0))
        opts.force_touch_max_segments = math.min(tonumber(opts.force_touch_max_segments or remaining_touch_budget) or remaining_touch_budget, remaining_touch_budget)
        opts.force_touch_close_dist = opts.force_touch_close_dist or TG_LOOP15_CLOSE_DIST or 82.0

        tg_log("[LOOP15][TOUCH_BUDGET] remaining=" .. tostring(remaining_touch_budget) ..
            " maxSegments=" .. tostring(opts.force_touch_max_segments) ..
            " mode=" .. tostring((opts.small_loop_15 and TG_LOOP15_CURVED_RETURN_MODE) and "curved_connector_return" or "straight_force_touch"))
    end
    local force_touch_ok = false
    if opts.small_loop_15 and TG_LOOP15_CURVED_RETURN_MODE then
        force_touch_ok = connector_loop15_curved_touch_start("legacy_smart_curved_final_touch", opts)
    else
        force_touch_ok = connector_force_touch_start_bridge("legacy_smart_final_touch", opts)
    end
    local final_meta = tg_get_meta(connector_builder_state.current_obj)
    local target_meta = connector_builder_state.first_real_obj and tg_get_meta(connector_builder_state.first_real_obj) or tg_get_meta(connector_builder_state.start_obj)
    local final_dist = tg_distance2d(final_meta, target_meta)
    local final_close_dist = tonumber(opts.force_touch_close_dist or opts.close_dist or TG_LOOP_FORCE_TOUCH_CLOSE_DIST or 72.0) or 72.0
    local status = (force_touch_ok or final_dist < final_close_dist) and "LEGACY_SMART_TOUCHED_START" or "LEGACY_SMART_OPEN"
    tg_log("[LEGACY_SMART][DONE] status=" .. status ..
        " placed=" .. tostring(connector_builder_state.pieces) ..
        " finalDistToFirstReal=" .. string.format("%.1f", final_dist) ..
        " note=no retry; no visible starter seed")
    tg_report_state("legacy_smart_no_starter_done")
    return status == "LEGACY_SMART_TOUCHED_START" or status == "LEGACY_SMART_CLOSED"
end



-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.7.6 plan-first smart loop 15
-- ═══════════════════════════════════════════════════════════════════════════════════
-- builds the route invisibly in memory first. only after a full closed-loop
-- plan is accepted does it spawn the real objects with the Tetris preview
-- animation. This keeps the fun visual build, but removes panic bridges.

function connector_plan15_fake_handle(label, n)
    return "__plan15_" .. tostring(label or "plan") .. "_" .. tostring(n or 0) .. "_" .. tostring(math.random(100000, 999999))
end

function connector_plan15_restore_state(snapshot)
    if not snapshot then return end
    connector_builder_state.active = snapshot.active
    connector_builder_state.start_obj = snapshot.start_obj
    connector_builder_state.current_obj = snapshot.current_obj
    connector_builder_state.current_model = snapshot.current_model
    connector_builder_state.current_direction = snapshot.current_direction
    connector_builder_state.current_heading = snapshot.current_heading
    connector_builder_state.pieces = snapshot.pieces
    connector_builder_state.accepted = snapshot.accepted
    connector_builder_state.rejected = snapshot.rejected
    connector_builder_state.history = snapshot.history or {}
    connector_builder_state.first_real_obj = snapshot.first_real_obj
    connector_builder_state.no_starter_seed_obj = snapshot.no_starter_seed_obj
    connector_builder_state.seed_start_meta = snapshot.seed_start_meta
    connector_builder_state.snake_starter_mode = snapshot.snake_starter_mode
    connector_builder_state.loop_target_obj = snapshot.loop_target_obj
    connector_builder_state.snake_middle_obj = snapshot.snake_middle_obj
    connector_builder_state.front_launch_obj = snapshot.front_launch_obj
end

function connector_plan15_snapshot_state()
    return {
        active = connector_builder_state.active,
        start_obj = connector_builder_state.start_obj,
        current_obj = connector_builder_state.current_obj,
        current_model = connector_builder_state.current_model,
        current_direction = connector_builder_state.current_direction,
        current_heading = connector_builder_state.current_heading,
        pieces = connector_builder_state.pieces,
        accepted = connector_builder_state.accepted,
        rejected = connector_builder_state.rejected,
        history = connector_builder_state.history,
        first_real_obj = connector_builder_state.first_real_obj,
        no_starter_seed_obj = connector_builder_state.no_starter_seed_obj,
        seed_start_meta = connector_builder_state.seed_start_meta,
        snake_starter_mode = connector_builder_state.snake_starter_mode,
        loop_target_obj = connector_builder_state.loop_target_obj,
        snake_middle_obj = connector_builder_state.snake_middle_obj,
        front_launch_obj = connector_builder_state.front_launch_obj
    }
end

function connector_plan15_virtual_start(label)
    label = label or "plan15"
    connector_reset_state()

    local pos, heading = tg_get_local_position_heading(label .. "_virtual_start")
    heading = heading or 0.0
    local layout = tg_compute_start_ramp_layout(pos, heading)
    local flat = layout and layout.flat or nil
    local base_x, base_y, base_z
    if TG_START_LAUNCH_RAMP ~= false and flat then
        base_x, base_y, base_z = flat.x, flat.y, flat.z
    else
        base_x, base_y, base_z = calculate_new_position(pos, heading, 18.0, 0.0, 1.2)
    end
    local seed = connector_plan15_fake_handle(label, "seed")

    tg_set_meta(seed, {
        model = "stt_prop_track_straight_bar_m",
        x = base_x,
        y = base_y,
        z = base_z,
        heading = heading,
        plan_virtual = true,
        ramp_flat_exit = TG_START_LAUNCH_RAMP ~= false
    })
    connector_apply_track_size_meta(tg_get_meta(seed), "stt_prop_track_straight_bar_m")

    connector_builder_state.active = true
    connector_builder_state.start_obj = seed
    connector_builder_state.current_obj = seed
    connector_builder_state.current_model = "stt_prop_track_straight_bar_m"
    connector_builder_state.current_direction = "left"
    connector_builder_state.current_heading = heading or 0.0
    connector_builder_state.pieces = 1
    connector_builder_state.accepted = 1
    connector_builder_state.no_starter_seed_obj = seed
    connector_builder_state.seed_start_meta = tg_get_meta(seed)
    connector_builder_state.history = {
        {
            obj = seed,
            model = "stt_prop_track_straight_bar_m",
            direction = "left",
            open_side = "left",
            heading = heading or 0.0,
            plan_seed = true
        }
    }
    connector_port_init(seed, "left", "plan15_virtual_seed")
    return seed
end

function connector_plan15_promote_virtual_first_real(obj)
    if not obj then return end
    local seed = connector_builder_state.no_starter_seed_obj
    if seed and not connector_builder_state.first_real_obj then
        connector_builder_state.first_real_obj = obj
        connector_builder_state.start_obj = obj
        connector_builder_state.no_starter_seed_obj = nil
        local clean = {}
        for _, entry in ipairs(connector_builder_state.history or {}) do
            if entry and entry.obj ~= seed then table.insert(clean, entry) end
        end
        connector_builder_state.history = clean
        connector_builder_state.pieces = #clean
        connector_builder_state.accepted = #clean
    end
end

function connector_plan15_apply_virtual(row, step_index, plan)
    if not row then return nil end
    plan = plan or {}
    local parent_obj = connector_builder_state.current_obj
    local parent_model = connector_builder_state.current_model
    local parent_direction = connector_builder_state.current_direction
    if not parent_obj then return nil end

    local wm = tg_world_from_parent(parent_obj, row.x, row.y, row.z, row.rotZ)
    wm.model = row.child
    wm.direction = row.direction
    wm.angle = row.angle
    wm.plan_virtual = true
    connector_apply_track_size_meta(wm, wm.model)

    local fake = connector_plan15_fake_handle("step", step_index or #plan.steps + 1)
    tg_set_meta(fake, wm)
    local next_direction = connector_resolve_next_open_side(parent_direction, row)
    connector_port_mark_attach(parent_obj, fake, row, next_direction)

    connector_builder_state.current_obj = fake
    connector_builder_state.current_model = row.child
    connector_builder_state.current_direction = next_direction
    connector_builder_state.current_heading = wm.heading or 0.0
    connector_builder_state.pieces = (connector_builder_state.pieces or 0) + 1
    connector_builder_state.accepted = (connector_builder_state.accepted or 0) + 1

    local entry = {
        obj = fake,
        model = row.child,
        direction = next_direction,
        open_side = next_direction,
        parent_side = row.parentDirection,
        heading = wm.heading or 0.0,
        attach = row,
        parent_obj = parent_obj,
        parent_model = parent_model,
        parent_direction = parent_direction,
        dead_key = connector_deadend_key(parent_obj, parent_direction, row),
        meta = wm,
        plan_virtual = true
    }
    table.insert(connector_builder_state.history, entry)
    table.insert(plan.steps, {
        row = row,
        model = row.child,
        direction = next_direction,
        parent_direction = parent_direction,
        parent_model = parent_model,
        heading = wm.heading or 0.0,
        meta = wm
    })
    connector_plan15_promote_virtual_first_real(fake)
    return fake
end

function connector_plan15_count_mix(steps)
    local straight = 0
    local curves = 0
    for _, step in ipairs(steps or {}) do
        local row = step and step.row
        if row and tostring(row.direction or "") == "front" then straight = straight + 1 else curves = curves + 1 end
    end
    return straight, curves
end

function connector_plan15_mix_ok(steps, allow_soft)
    local straight, curves = connector_plan15_count_mix(steps)
    local total = straight + curves
    if total <= 0 then return false, straight, curves, 0 end
    local pct = (straight / total) * 100.0
    local minp = tonumber(TG_LOOP15_STRAIGHT_MIN_PERCENT or 20) or 20
    local maxp = tonumber(TG_LOOP15_STRAIGHT_MAX_PERCENT or 40) or 40
    if allow_soft then
        minp = math.max(0, minp - 7)
        maxp = math.min(100, maxp + 8)
    end
    return pct >= minp and pct <= maxp, straight, curves, pct
end

function connector_plan15_step_opts(step_index, target, profile, attempt)
    local step_opts = {
        small_loop_15 = true,
        planned_loop15 = true,
        no_180 = true,
        no_starter = true,
        tetris_preview = false,
        strict_overlap = true,
        top_n = TG_PLAN15_TOP_N or 4,
        world_obstacle_clear_candidates = 1, -- keep invisible planner fast; it still skips blocked routes
        snake_straight_rhythm = TG_SNAKE_STRAIGHT_RHYTHM,
        allow_start_close = true,
        start_avoid_dist = 0,
        start_guard_dist = TG_START_GUARD_SMART_DIST,
        no_return_until_pieces = math.max(3, (profile and profile.return_start or 5) - 1),
        loopback_min_pieces = TG_PLAN15_LOOPBACK_MIN_PIECES or 8,
        loopback_close_dist = TG_PLAN15_ACCEPT_CLOSE_DIST or 82.0,
        close_dist = TG_PLAN15_ACCEPT_CLOSE_DIST or 82.0,
        loop_bounds = true,
        loop_origin_meta = connector_builder_state.first_real_obj and tg_get_meta(connector_builder_state.first_real_obj) or nil,
        loop_bound_max_x = profile and profile.max_x or TG_LOOP15_MIN_BOUND_X or 135.0,
        loop_bound_max_y = profile and profile.max_y or TG_LOOP15_MIN_BOUND_Y or 155.0,
        overlap_skip_recent = TG_LEGACY_SMART_SKIP_RECENT or 1,
        overlap_center_hard_dist = TG_LEGACY_SMART_CLEARANCE_RADIUS or 48.0,
        overlap_center_soft_dist = TG_LEGACY_SMART_SOFT_RADIUS or 76.0,
        overlap_sample_hard_dist = TG_LEGACY_SMART_SAMPLE_HARD or 22.0,
        overlap_sample_soft_dist = TG_LEGACY_SMART_SAMPLE_SOFT or 42.0,
        parent_turn_min_dist = TG_LEGACY_SMART_PARENT_TURN_MIN_DIST or 40.0
    }

    connector_apply_legacy_smart_clearance_opts(step_opts)
    connector_apply_straight_run_opts(step_opts)
    connector_apply_loop15_shape_opts(step_opts, step_index, target, profile)

    local return_start = profile and profile.return_start or math.floor(target * 0.52)
    local remaining = target - step_index
    if step_index >= return_start or remaining <= 6 then
        local tm = connector_builder_state.first_real_obj and tg_get_meta(connector_builder_state.first_real_obj) or nil
        if tm then
            step_opts.target_meta = tm
            step_opts.loop_origin_meta = tm
            step_opts.prefer_towards_target = true
            step_opts.loopback_final = remaining <= 5
            step_opts.prefer_turns = true
            step_opts.no_front = false
            step_opts.top_n = TG_PLAN15_RETURN_TOP_N or 5
        end
    end

    -- Add controlled variety by attempt so every rejected plan is not identical.
    if attempt and (attempt % 3 == 0) then step_opts.prefer_turns = true end
    if attempt and (attempt % 5 == 0) then step_opts.prefer_straight = true end
    return step_opts
end

function connector_plan15_try_once(attempt, target)
    local profile = tg_loop_profile(target or (TG_PLAN15_MAX_PIECES or 15))
    connector_plan15_virtual_start("plan15_attempt_" .. tostring(attempt or 1))

    local plan = { steps = {}, target = target, profile = profile, attempt = attempt }
    local fail_reason = nil

    for i = 1, target do
        local opts = connector_plan15_step_opts(i, target, profile, attempt)
        local row = nil
        local count = 0
        local scored = nil
        row, count, scored = connector_pick_candidate(connector_builder_state.current_model, connector_builder_state.current_direction, opts)
        if not row then
            fail_reason = "no_candidate_at_" .. tostring(i)
            break
        end
        connector_plan15_apply_virtual(row, i, plan)

        local min_done = TG_PLAN15_MIN_PIECES or 10
        local first_meta = connector_builder_state.first_real_obj and tg_get_meta(connector_builder_state.first_real_obj) or nil
        local cur_meta = connector_builder_state.current_obj and tg_get_meta(connector_builder_state.current_obj) or nil
        local dist = (first_meta and cur_meta) and tg_distance2d(cur_meta, first_meta) or 999999.0
        local mix_ok = false
        mix_ok = connector_plan15_mix_ok(plan.steps, i < target)
        if i >= min_done and dist <= (TG_PLAN15_ACCEPT_CLOSE_DIST or 82.0) and mix_ok then
            plan.final_dist = dist
            plan.target = i
            return plan, "accepted_early"
        end
    end

    local first_meta = connector_builder_state.first_real_obj and tg_get_meta(connector_builder_state.first_real_obj) or nil
    local cur_meta = connector_builder_state.current_obj and tg_get_meta(connector_builder_state.current_obj) or nil
    local final_dist = (first_meta and cur_meta) and tg_distance2d(cur_meta, first_meta) or 999999.0
    local mix_ok, straight, curves, pct = connector_plan15_mix_ok(plan.steps, false)
    plan.final_dist = final_dist
    plan.straights = straight
    plan.curves = curves
    plan.straight_pct = pct

    if not fail_reason and #plan.steps >= (TG_PLAN15_MIN_PIECES or 10) and final_dist <= (TG_PLAN15_ACCEPT_CLOSE_DIST or 82.0) and mix_ok then
        return plan, "accepted_full"
    end

    if not fail_reason then
        if final_dist > (TG_PLAN15_ACCEPT_CLOSE_DIST or 82.0) then
            fail_reason = "open_dist_" .. string.format("%.1f", final_dist)
        elseif not mix_ok then
            fail_reason = "mix_bad_s" .. tostring(straight) .. "_c" .. tostring(curves)
        else
            fail_reason = "unknown_reject"
        end
    end
    return nil, fail_reason, plan
end

function connector_plan15_find_plan(opts)
    opts = opts or {}
    local snapshot = connector_plan15_snapshot_state()
    local best_reject = nil
    local best_dist = 999999.0
    local attempts = tonumber(opts.attempts or TG_PLAN15_MAX_ATTEMPTS or 180) or 180
    local min_p = tonumber(opts.min_pieces or TG_PLAN15_MIN_PIECES or 10) or 10
    local max_p = tonumber(opts.max_pieces or TG_PLAN15_MAX_PIECES or 15) or 15
    local reject_logged = 0

    tg_log("[PLAN15][BEGIN] attempts=" .. tostring(attempts) .. " pieces=" .. tostring(min_p) .. "-" .. tostring(max_p) .. " mode=invisible_first")
    for attempt = 1, attempts do
        local target = math.random(min_p, max_p)
        connector_plan15_restore_state(snapshot)
        local plan, status, reject_plan = connector_plan15_try_once(attempt, target)
        if plan then
            local mix_ok, straight, curves, pct = connector_plan15_mix_ok(plan.steps, true)
            tg_log("[PLAN15][ACCEPT] attempt=" .. tostring(attempt) ..
                " pieces=" .. tostring(#plan.steps) ..
                " straights=" .. tostring(straight) ..
                " curves=" .. tostring(curves) ..
                " straightPct=" .. string.format("%.1f", pct or 0.0) ..
                " closeDist=" .. string.format("%.1f", plan.final_dist or 0.0) ..
                " status=" .. tostring(status))
            connector_plan15_restore_state(snapshot)
            return plan
        else
            local fd = reject_plan and reject_plan.final_dist or 999999.0
            if fd < best_dist then best_dist = fd; best_reject = status end
            if reject_logged < (TG_PLAN15_MAX_REJECT_SUMMARY or 8) or (attempt % 25 == 0) then
                tg_log("[PLAN15][REJECT] attempt=" .. tostring(attempt) ..
                    " reason=" .. tostring(status) ..
                    " bestDist=" .. string.format("%.1f", best_dist))
                reject_logged = reject_logged + 1
            end
        end
        if attempt % 15 == 0 then util.yield(0) end
    end

    connector_plan15_restore_state(snapshot)
    tg_warn("PLAN15", "no accepted invisible plan attempts=" .. tostring(attempts) .. " bestReason=" .. tostring(best_reject) .. " bestDist=" .. string.format("%.1f", best_dist))
    return nil
end

function connector_spawn_planned_step(label, step, opts)
    opts = opts or {}
    if not step or not step.row then return nil end
    local parent_obj = connector_builder_state.current_obj
    local parent_model = connector_builder_state.current_model
    local parent_direction = connector_builder_state.current_direction
    local row = step.row
    if not parent_obj then return nil end

    local scored = {}
    local cands = connector_candidate_list(parent_model, parent_direction, opts)
    for _, f in ipairs(cands or {}) do
        local sc, rs = connector_score_candidate(f, opts)
        table.insert(scored, { row = f, score = sc, reasons = rs })
    end
    table.sort(scored, function(a, b) return (a.score or 0) > (b.score or 0) end)

    local planned_meta = tg_world_from_parent(parent_obj, row.x, row.y, row.z, row.rotZ)
    planned_meta.model = row.child
    connector_apply_track_size_meta(planned_meta, planned_meta.model)
    local world_blocked, world_reason = tg_world_obstacle_probe_meta(planned_meta, parent_obj, tostring(label) .. "_final")
    if world_blocked then
        tg_warn("OBSTACLE", "planned step veto label=" .. tostring(label) .. " reason=" .. tostring(world_reason))
        return nil
    end

    connector_preview_candidate_sequence(parent_obj, scored, row, opts, label)
    if tg_generation_should_stop(opts.generation_token, label .. "_before_attach") then return nil end

    local child_obj = attach_object(parent_obj, row.child, row.x, row.y, row.z, row.rotX, row.rotY, row.rotZ)
    if not child_obj or child_obj == 0 then
        tg_warn("PLAN15", "spawn failed label=" .. tostring(label) .. " child=" .. tostring(row.child))
        return nil
    end

    local child_meta = tg_get_meta(child_obj) or {}
    local child_heading = tonumber(child_meta.heading) or ((tonumber(tg_get_meta(parent_obj) and tg_get_meta(parent_obj).heading) or 0.0) + (tonumber(row.rotZ) or 0.0))
    local next_direction = connector_resolve_next_open_side(parent_direction, row)
    connector_port_mark_attach(parent_obj, child_obj, row, next_direction)

    connector_builder_state.current_obj = child_obj
    connector_builder_state.current_model = row.child
    connector_builder_state.current_direction = next_direction
    connector_builder_state.current_heading = child_heading
    connector_builder_state.pieces = connector_builder_state.pieces + 1
    connector_builder_state.accepted = connector_builder_state.accepted + 1
    table.insert(connector_builder_state.history, {
        obj = child_obj,
        model = row.child,
        direction = next_direction,
        open_side = next_direction,
        parent_side = row.parentDirection,
        heading = child_heading,
        attach = row,
        parent_obj = parent_obj,
        parent_model = parent_model,
        parent_direction = parent_direction,
        dead_key = connector_deadend_key(parent_obj, parent_direction, row)
    })

    connector_promote_first_real_piece(child_obj, label)
    return child_obj
end

function connector_build_planned_smart_loop15(opts)
    opts = opts or {}
    local gen_token = tg_generation_start("planned_smart_loop15")
    opts.generation_token = gen_token
    clear_race_track("planned_smart_loop15")

    local plan = connector_plan15_find_plan(opts)
    if not plan then
        tg_warn("PLAN15", "build aborted: no valid invisible plan found")
        return false
    end

    if tg_generation_should_stop(gen_token, "planned15_before_spawn") then return false end
    connector_spawn_seed_start_no_starter("planned15_seed")

    local build_opts = {}
    for k, v in pairs(opts) do build_opts[k] = v end
    build_opts.generation_token = gen_token
    build_opts.tetris_preview = true
    build_opts.preview_rejects = TG_PLAN15_PREVIEW_REJECTS or 2
    build_opts.preview_lift = 1.45
    build_opts.delay_ms = opts.delay_ms or 110
    build_opts.anim_step_ms = opts.anim_step_ms or TG_TETRIS_STEP_MS or 45
    build_opts.preview_spin_frames = opts.preview_spin_frames or TG_TETRIS_SPIN_FRAMES or 6
    build_opts.allow_start_close = true
    build_opts.loopback_min_pieces = TG_PLAN15_LOOPBACK_MIN_PIECES or 8

    tg_log("[BUILD15][ANIMATE] pieces=" .. tostring(#plan.steps) .. " source=accepted_invisible_plan")
    for i, step in ipairs(plan.steps or {}) do
        if tg_generation_should_stop(gen_token, "planned15_step_" .. tostring(i)) then return false end
        util.yield(build_opts.delay_ms or 110)
        local obj = connector_spawn_planned_step("planned15_step_" .. tostring(i), step, build_opts)
        if not obj then
            tg_warn("BUILD15", "planned step failed i=" .. tostring(i) .. " aborting")
            return false
        end
        if TG_LOG_MODE == "compact" and (i == 1 or i == #plan.steps or (i % 5 == 0)) then
            tg_log("[BUILD15][PROGRESS] i=" .. tostring(i) .. "/" .. tostring(#plan.steps) ..
                " model=" .. tostring(step.model) ..
                " dir=" .. tostring(step.direction))
        end
    end

    connector_delete_seed_start_if_needed("planned15_done")
    local final_meta = tg_get_meta(connector_builder_state.current_obj)
    local start_meta = connector_builder_state.first_real_obj and tg_get_meta(connector_builder_state.first_real_obj) or tg_get_meta(connector_builder_state.start_obj)
    local final_dist = tg_distance2d(final_meta, start_meta)
    local ok = final_dist <= (TG_PLAN15_ACCEPT_CLOSE_DIST or 82.0)
    tg_log("[BUILD15][DONE] status=" .. tostring(ok and "CLOSED_LOOP" or "OPEN") ..
        " pieces=" .. tostring(connector_builder_state.pieces) ..
        " closeDist=" .. string.format("%.1f", final_dist) ..
        " note=plan-first no straight force bridge")
    tg_report_state("planned_smart_loop15_done")
    return ok
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v0.5.6 smart random loop
-- ═══════════════════════════════════════════════════════════════════════════════════
-- live tetris builder: think before each real placement, reject bad pieces,
-- then animate/spawn only the selected candidate for that single step.

function connector_smart_start_meta()
    local sm = tg_get_meta(connector_builder_state.start_obj)
    if sm and sm.x and sm.y then return sm end
    local h = connector_builder_state.history or {}
    if h[1] and h[1].obj then
        sm = tg_get_meta(h[1].obj)
        if sm and sm.x and sm.y then return sm end
    end
    return nil
end

function connector_smart_phase(piece_index, total, dist_to_start)
    piece_index = tonumber(piece_index or 1) or 1
    total = tonumber(total or 30) or 30
    dist_to_start = tonumber(dist_to_start or 999999.0) or 999999.0
    if dist_to_start <= (TG_SMART_CLOSE_RANGE or 95.0) and piece_index > 8 then return "close" end
    if piece_index >= math.floor(total * 0.58) then return "return" end
    return "explore"
end

function connector_smart_overlap_score(meta, opts)
    opts = opts or {}
    local score = 0
    local reasons = {}
    local hard = false
    local sample_limit = tonumber(opts.smart_sample_dist or TG_SMART_OVERLAP_SAMPLE_DIST or 30.0) or 30.0
    local center_hard = tonumber(opts.smart_center_hard or TG_SMART_OVERLAP_CENTER_HARD or 42.0) or 42.0
    local center_soft = tonumber(opts.smart_center_soft or TG_SMART_OVERLAP_CENTER_SOFT or 72.0) or 72.0
    local start_guard = tonumber(opts.smart_start_guard or TG_SMART_START_GUARD_DIST or 115.0) or 115.0
    local skip_recent = tonumber(opts.smart_skip_recent or TG_SMART_SKIP_RECENT or 2) or 2
    local phase = tostring(opts.smart_phase or "explore")

    local function add(delta, why)
        score = score + delta
        if why then table.insert(reasons, why .. (delta >= 0 and "+" or "") .. tostring(delta)) end
    end

    local history = connector_builder_state.history or {}
    for i, entry in ipairs(history) do
        local old = entry and tg_get_meta(entry.obj)
        if old then
            local is_recent = i > (#history - skip_recent)
            local is_start = (i == 1)
            local should_check = (not is_recent) or is_start

            if should_check then
                local center_d = tg_distance2d(meta, old)
                local sample_bad, sample_d = false, 999999.0
                if connector_plan_points_too_close then
                    sample_bad, sample_d = connector_plan_points_too_close(meta, old, sample_limit)
                end

                if is_start and #history > 2 and phase ~= "close" then
                    if center_d < start_guard or sample_d < (sample_limit + 12.0) then
                        add(-5000, "startGuard#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d) .. " s=" .. string.format("%.1f", sample_d))
                        hard = true
                    end
                elseif is_start and phase == "close" then
                    -- Near the end we can approach the start, but still do not sit on top of it.
                    if center_d < 38.0 or sample_d < (sample_limit - 4.0) then
                        add(-4500, "badCloseStartOverlap c=" .. string.format("%.1f", center_d) .. " s=" .. string.format("%.1f", sample_d))
                        hard = true
                    end
                elseif sample_bad then
                    add(-4200, "sampleOverlap#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d) .. " s=" .. string.format("%.1f", sample_d))
                    hard = true
                elseif center_d < center_hard then
                    add(-3000, "centerHard#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d))
                    hard = true
                elseif center_d < center_soft then
                    local penalty = -math.floor((center_soft - center_d) * 8)
                    add(penalty, "centerSoft#" .. tostring(i) .. " c=" .. string.format("%.1f", center_d))
                end
            end
        end
    end

    return score, table.concat(reasons, ","), hard
end

function connector_smart_score_candidate(row, opts)
    opts = opts or {}
    local parent_obj = connector_builder_state.current_obj
    local parent_meta = tg_get_meta(parent_obj)
    if not parent_obj or not parent_meta or not row then
        return -9999, "missingParentOrRow", nil, true
    end

    local wm = tg_world_from_parent(parent_obj, row.x, row.y, row.z, row.rotZ)
    wm.model = row.child
    wm.direction = row.direction
    wm.angle = row.angle

    local score = 100
    local reasons = {}
    local function add(delta, why)
        score = score + delta
        if why then table.insert(reasons, why .. (delta >= 0 and "+" or "") .. tostring(delta)) end
    end

    local angle = math.abs(tonumber(row.angle or 0) or 0)
    local dir = tostring(row.direction or "")
    local child = tostring(row.child or "")
    local phase = tostring(opts.smart_phase or "explore")
    local start = connector_smart_start_meta()

    if angle == 0 or dir == "front" then add(28, "straight") end
    if angle == 45 then add(24, "gentle45") end
    if angle == 90 then add(8, "turn90") end
    if angle == 135 then add(-38, "sharp135") end
    if angle >= 180 then add(-250, "avoid180") end

    local h = connector_builder_state.history or {}
    local last = h[#h]
    local prev = h[#h - 1]
    if last and last.model == child then add(-25, "sameModel") end
    if last and prev and last.model == child and prev.model == child then add(-75, "sameModel3") end
    if dir ~= "front" and last and prev and last.direction == dir and prev.direction == dir then add(-65, "spiralTurn") end
    if dir ~= "front" and last and last.direction == dir and angle >= 90 then add(-30, "repeatHardTurn") end

    if phase == "explore" then
        if dir == "front" then add(35, "exploreStraight") end
        if angle == 45 then add(15, "exploreGentle") end
        if angle >= 90 then add(-16, "exploreAvoidHardTurn") end
    elseif phase == "return" or phase == "close" then
        if start then
            local before = tg_distance2d(parent_meta, start)
            local after = tg_distance2d(wm, start)
            local gain = before - after
            add(math.floor(gain * (phase == "close" and 7.0 or 4.5)), "towardStart=" .. string.format("%.1f", gain))
            if gain < -7.0 then add(-240, "awayFromStart") end
            if phase == "close" and after < (TG_SMART_CLOSE_RANGE or 95.0) then add(180, "closeRange=" .. string.format("%.1f", after)) end
        end
        if angle >= 135 then add(-70, "returnAvoidSharp") end
    end

    local op, oreason, hard = connector_smart_overlap_score(wm, opts)
    if op ~= 0 then add(op, oreason) end
    if hard then add(-1000, "hardReject") end

    return score, table.concat(reasons, ","), wm, hard
end

function connector_smart_pick_candidate(opts)
    opts = opts or {}
    local parent_model = connector_builder_state.current_model
    local parent_direction = connector_builder_state.current_direction
    local candidates = connector_candidate_list(parent_model, parent_direction, opts)
    if #candidates == 0 then return nil, {}, "noCandidates" end

    local scored = {}
    for _, row in ipairs(candidates) do
        local score, reasons, wm, hard = connector_smart_score_candidate(row, opts)
        table.insert(scored, { row = row, score = score, reasons = reasons, meta = wm, hard = hard })
    end
    table.sort(scored, function(a, b) return (a.score or 0) > (b.score or 0) end)

    local usable = {}
    for _, item in ipairs(scored) do
        if (item.score or 0) > -500 and not item.hard then table.insert(usable, item) end
    end

    local best = scored[1]
    local parent_meta = tg_get_meta(connector_builder_state.current_obj)
    local start_meta = connector_smart_start_meta()
    local dist = tg_distance2d(parent_meta, start_meta)
    tg_log("[SMART][THINK] phase=" .. tostring(opts.smart_phase) ..
        " parent=" .. tostring(parent_model) ..
        " dir=" .. tostring(parent_direction) ..
        " distToStart=" .. string.format("%.1f", dist) ..
        " candidates=" .. tostring(#candidates) ..
        " usable=" .. tostring(#usable) ..
        " best=" .. tostring(best and best.row and best.row.child) ..
        " bestScore=" .. tostring(best and best.score) ..
        " bestReasons=" .. tostring(best and best.reasons))

    if #usable == 0 then
        tg_warn("SMART", "all candidates rejected; best=" .. tostring(best and best.row and best.row.child) .. " score=" .. tostring(best and best.score) .. " reasons=" .. tostring(best and best.reasons))
        return nil, scored, "allRejected"
    end

    local top_n = math.min(#usable, tonumber(opts.smart_top_n or opts.top_n or 2) or 2)
    local chosen = usable[1]
    if top_n > 1 and opts.smart_deterministic ~= true then
        chosen = usable[math.random(top_n)]
    end

    tg_log("[SMART][PICK] chosen=" .. tostring(chosen.row.child) ..
        " score=" .. tostring(chosen.score) ..
        " reasons=" .. tostring(chosen.reasons))
    return chosen.row, scored, "ok"
end

function connector_try_next_smart(label, opts)
    label = label or "smart_next"
    opts = opts or {}
    if not connector_builder_state.active or not connector_builder_state.current_obj then
        local ok_start = connector_spawn_start(label .. "_auto_start")
        if not ok_start then return nil end
        util.yield(opts.delay_ms or 250)
    end

    local candidate, scored, status = connector_smart_pick_candidate(opts)
    if not candidate then
        connector_builder_state.rejected = connector_builder_state.rejected + 1
        tg_warn("SMART", label .. " no smart candidate status=" .. tostring(status))
        return nil
    end

    connector_preview_candidate_sequence(connector_builder_state.current_obj, scored, candidate, opts, label)
    local child_obj = attach_object(connector_builder_state.current_obj, candidate.child, candidate.x, candidate.y, candidate.z, candidate.rotX, candidate.rotY, candidate.rotZ)
    if not child_obj or child_obj == 0 then
        connector_builder_state.rejected = connector_builder_state.rejected + 1
        tg_warn("SMART", label .. " rejected: attach/spawn failed")
        return nil
    end

    local parent_direction = connector_builder_state.current_direction
    local child_meta = tg_get_meta(child_obj) or {}
    local child_heading = tonumber(child_meta.heading) or 0.0

    local next_direction = tostring(candidate.direction or "")
    if next_direction ~= "left" and next_direction ~= "right" then
        next_direction = tostring(parent_direction or "left")
    end

    connector_builder_state.current_obj = child_obj
    connector_builder_state.current_model = candidate.child
    connector_builder_state.current_direction = next_direction
    connector_builder_state.current_heading = child_heading
    connector_builder_state.pieces = connector_builder_state.pieces + 1
    connector_builder_state.accepted = connector_builder_state.accepted + 1
    table.insert(connector_builder_state.history, {obj=child_obj, model=candidate.child, direction=next_direction, heading=child_heading, attach=candidate, smart=true})

    local cm = tg_get_meta(child_obj)
    local sm = connector_smart_start_meta()
    tg_log("[SMART][ACCEPT] #" .. tostring(connector_builder_state.pieces) ..
        " obj=" .. tg_handle(child_obj) ..
        " model=" .. tostring(candidate.child) ..
        " rowDir=" .. tostring(candidate.direction) ..
        " nextDir=" .. tostring(next_direction) ..
        " heading=" .. string.format("%.2f", child_heading) ..
        " distToStart=" .. string.format("%.1f", tg_distance2d(cm, sm)) ..
        " pos=" .. tg_vec_str(cm))
    return child_obj, candidate
end

function connector_build_smart_random_loop(opts)
    opts = opts or {}
    opts.generation_token = opts.generation_token or tg_generation_start("strict_smart_random_loop")
    local gen_token = opts.generation_token
    clear_race_track("smart_random_loop")
    connector_spawn_start("smart_random_loop_start")

    local minv = tonumber(TG_LOOP_RANDOM_MIN or 18) or 18
    local maxv = tonumber(TG_LOOP_RANDOM_MAX or 60) or 60
    if maxv < minv then maxv = minv end
    local target = math.random(minv, maxv)
    local start_meta = connector_smart_start_meta()
    tg_log("[SMART][BEGIN] target=" .. tostring(target) ..
        " start=" .. tg_vec_str(start_meta) ..
        " overlapSample=" .. tostring(TG_SMART_OVERLAP_SAMPLE_DIST) ..
        " startGuard=" .. tostring(TG_SMART_START_GUARD_DIST))

    -- Live smart route. It thinks before every placement, but does not full pre-plan or infinite loop.
    for i = 2, target do
        util.yield(opts.delay_ms or 100)
        if tg_generation_should_stop(gen_token, "smart_loop_step_" .. tostring(i)) then return false end
        local cur = tg_get_meta(connector_builder_state.current_obj)
        local dist = tg_distance2d(cur, start_meta)
        local phase = connector_smart_phase(i, target, dist)

        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        step_opts.smart_phase = phase
        step_opts.no_180 = true
        step_opts.strict_overlap = true
        step_opts.tetris_preview = true
        step_opts.preview_rejects = opts.preview_rejects or 1
        step_opts.smart_top_n = phase == "explore" and 2 or 1
        step_opts.smart_deterministic = (phase ~= "explore")
        if phase == "return" or phase == "close" then
            step_opts.prefer_turns = true
            step_opts.no_front = (i % 3 == 0 and phase ~= "close")
        elseif i % 5 == 0 then
            step_opts.prefer_straight = true
        end

        local obj = connector_try_next_smart("smart_loop_step_" .. tostring(i), step_opts)
        if not obj then
            tg_warn("SMART", "smart loop stopped at step=" .. tostring(i) .. " phase=" .. tostring(phase))
            break
        end

        cur = tg_get_meta(connector_builder_state.current_obj)
        dist = tg_distance2d(cur, start_meta)
        if i > 10 and dist <= (TG_SMART_CLOSE_RANGE or 95.0) and phase == "close" then
            tg_log("[SMART][CLOSE_RANGE] step=" .. tostring(i) .. " dist=" .. string.format("%.1f", dist) .. " stopping near start")
            break
        end
    end

    -- Extra close phase if target length ended too open.
    for extra = 1, tonumber(TG_SMART_EXTRA_RETURN_STEPS or 45) or 45 do
        if tg_generation_should_stop(gen_token, "smart_close_step_" .. tostring(extra)) then return false end
        local cur = tg_get_meta(connector_builder_state.current_obj)
        local dist = tg_distance2d(cur, start_meta)
        if dist <= (TG_SMART_CLOSE_RANGE or 95.0) then
            tg_log("[SMART][CLOSE_DONE] extra=" .. tostring(extra - 1) .. " dist=" .. string.format("%.1f", dist))
            break
        end
        util.yield(opts.delay_ms or 100)
        local step_opts = {}
        for k, v in pairs(opts) do step_opts[k] = v end
        step_opts.smart_phase = "close"
        step_opts.no_180 = true
        step_opts.strict_overlap = true
        step_opts.tetris_preview = true
        step_opts.preview_rejects = opts.preview_rejects or 1
        step_opts.smart_top_n = 1
        step_opts.smart_deterministic = true
        step_opts.prefer_turns = true
        local obj = connector_try_next_smart("smart_close_step_" .. tostring(extra), step_opts)
        if not obj then
            tg_warn("SMART", "smart close phase failed extra=" .. tostring(extra))
            break
        end
    end

    local end_meta = tg_get_meta(connector_builder_state.current_obj)
    local final_dist = tg_distance2d(end_meta, start_meta)
    local status = final_dist <= (TG_SMART_CLOSE_RANGE or 95.0) and "SMART_LOOP_NEAR_START" or "SMART_LOOP_OPEN"
    tg_log("[SMART][DONE] status=" .. status ..
        " placed=" .. tostring(connector_builder_state.pieces) ..
        " accepted=" .. tostring(connector_builder_state.accepted) ..
        " rejected=" .. tostring(connector_builder_state.rejected) ..
        " finalDistToStart=" .. string.format("%.1f", final_dist))
    tg_report_state("smart_random_loop_done")
    return status == "SMART_LOOP_NEAR_START"
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- v1.1.0 minigame suite
-- ═══════════════════════════════════════════════════════════════════════════════════
-- modes:
--   Eliminator  - endless rising conveyor course; midpoint grows front + deletes rear.
--   Drifter     - gentle 45/90 degree bends with occasional small elevation stages.
--   Spiral      - repeated same-direction turns with regular climbs toward the sky.
--   Switchback  - alternating sharp turns with mountain-road style elevation changes.
--   Sky Sprint  - fast straight-biased elevated race with occasional gentle corners.
--   Sky Climb   - one continuous camera-facing 10-degree-style AoA incline to the sky.
--
-- All regular pieces are created through connector_try_next_legacy_smart(), the same
-- edge-connected Smart Random path. The only special geometry is an AoA transition ramp,
-- whose center points are calculated from the current track's outgoing edge so there is
-- no floating gap and no side bank.

function tg_minigame_is_run_current(run_id, generation_token)
    if not TG_MINIGAME_ACTIVE then return false end
    if tonumber(run_id or -1) ~= tonumber(TG_MINIGAME_RUN_ID or 0) then return false end
    if tg_generation_should_stop(generation_token, "minigame_run_check") then return false end
    return true
end

function tg_minigame_begin(mode)
    TG_MINIGAME_RUN_ID = (tonumber(TG_MINIGAME_RUN_ID or 0) or 0) + 1
    TG_MINIGAME_ACTIVE = true
    TG_MINIGAME_MODE = tostring(mode or "unknown")
    TG_MINIGAME_STATE = "building"
    TG_MINIGAME_LEVELS = {}
    TG_MINIGAME_CURRENT_LEVEL = 1
    local token = tg_generation_start("minigame_" .. TG_MINIGAME_MODE)
    tg_log("[MINIGAME][BEGIN] mode=" .. TG_MINIGAME_MODE .. " run=" .. tostring(TG_MINIGAME_RUN_ID) .. " token=" .. tostring(token))
    return TG_MINIGAME_RUN_ID, token
end

function tg_minigame_stop(reason, leave_track)
    reason = tostring(reason or "manual_stop")
    TG_MINIGAME_ACTIVE = false
    TG_MINIGAME_STATE = "stopped"
    TG_MINIGAME_RUN_ID = (tonumber(TG_MINIGAME_RUN_ID or 0) or 0) + 1
    tg_generation_cancel("minigame_" .. reason)
    tg_log("[MINIGAME][STOP] mode=" .. tostring(TG_MINIGAME_MODE) .. " reason=" .. reason .. " leaveTrack=" .. tostring(leave_track ~= false))
    if leave_track == false and clear_race_track then clear_race_track("minigame_stop_clear") end
    TG_MINIGAME_MODE = "none"
end

function tg_minigame_player_position()
    -- GetLocalVehicle / GetLocalPed are nil when not in a vehicle / during loading
    return tg_try_obj_position(GTA.GetLocalVehicle(), "minigame_vehicle") or tg_try_obj_position(GTA.GetLocalPed(), "minigame_ped")
end

function tg_minigame_distance3d(a, b)
    if not a or not b then return 999999.0 end
    local dx = (tonumber(a.x) or 0.0) - (tonumber(b.x) or 0.0)
    local dy = (tonumber(a.y) or 0.0) - (tonumber(b.y) or 0.0)
    local dz = (tonumber(a.z) or 0.0) - (tonumber(b.z) or 0.0)
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end

function tg_minigame_level_table(level)
    level = math.max(1, math.floor(tonumber(level or 1) or 1))
    TG_MINIGAME_LEVELS = TG_MINIGAME_LEVELS or {}
    TG_MINIGAME_LEVELS[level] = TG_MINIGAME_LEVELS[level] or {}
    return TG_MINIGAME_LEVELS[level]
end

function tg_minigame_tag_history_entry(level, kind)
    local history = connector_builder_state and connector_builder_state.history or {}
    local entry = history[#history]
    if not entry or not entry.obj then return nil end
    level = math.max(1, math.floor(tonumber(level or 1) or 1))
    local list = tg_minigame_level_table(level)
    entry.minigame_level = level
    entry.minigame_kind = tostring(kind or "road")
    entry.minigame_index = #list + 1
    table.insert(list, entry)
    local meta = tg_get_meta(entry.obj) or {}
    meta.minigame_level = level
    meta.minigame_kind = entry.minigame_kind
    meta.minigame_index = entry.minigame_index
    tg_set_meta(entry.obj, meta)
    return entry
end

function tg_minigame_tag_existing_history(level, kind)
    local list = tg_minigame_level_table(level)
    for _, entry in ipairs(connector_builder_state and connector_builder_state.history or {}) do
        if entry and entry.obj and not entry.minigame_level then
            entry.minigame_level = level
            entry.minigame_kind = tostring(kind or "launch")
            entry.minigame_index = #list + 1
            table.insert(list, entry)
            local meta = tg_get_meta(entry.obj) or {}
            meta.minigame_level = level
            meta.minigame_kind = entry.minigame_kind
            meta.minigame_index = entry.minigame_index
            tg_set_meta(entry.obj, meta)
        end
    end
end

function tg_minigame_remove_handle_from_array(array, obj)
    if not array or not obj then return end
    for i = #array, 1, -1 do
        if array[i] == obj then table.remove(array, i) end
    end
end

function tg_minigame_delete_oldest_piece(reason)
    local history = connector_builder_state and connector_builder_state.history or {}
    if #history <= (TG_ELIMINATOR_MIN_REAR_BUFFER or 4) then return false end

    for i = 1, #history do
        local entry = history[i]
        local obj = entry and entry.obj or nil
        if obj and obj ~= 0 and obj ~= connector_builder_state.current_obj then
            entry.minigame_deleted = true
            tg_delete(obj)
            tg_minigame_remove_handle_from_array(objects, obj)
            tg_minigame_remove_handle_from_array(entity_can_tint, obj)
            table.remove(history, i)
            connector_builder_state.history = history
            connector_builder_state.pieces = #history
            connector_builder_state.accepted = #history
            local first = history[1]
            if first and first.obj then
                connector_builder_state.start_obj = first.obj
                connector_builder_state.first_real_obj = first.obj
            end
            tg_log("[MINIGAME][ELIMINATOR][DESPAWN] reason=" .. tostring(reason or "advance") ..
                " obj=" .. tg_handle(obj) .. " remaining=" .. tostring(#history))
            return true
        end
    end
    return false
end

function tg_minigame_nearest_level_progress(level)
    local pos = tg_minigame_player_position()
    if not pos then return 0, 999999.0, 0 end
    local list = tg_minigame_level_table(level)
    local best_index, best_dist, alive = 0, 999999.0, 0
    for i, entry in ipairs(list) do
        if entry and entry.obj and not entry.minigame_deleted then
            local meta = tg_get_meta(entry.obj)
            if meta then
                alive = alive + 1
                local dist = tg_minigame_distance3d(pos, meta)
                if dist < best_dist then best_dist, best_index = dist, i end
            end
        end
    end
    return best_index, best_dist, #list
end

function tg_minigame_build_step_options(profile, step_index)
    local opts = {
        delay_ms = TG_ELIMINATOR_BUILD_DELAY_MS or 95,
        no_180 = true,
        top_n = 4,
        tetris_preview = false,
        preview_rejects = 0,
        allow_start_close = true,
        start_avoid_dist = 0,
        start_guard_dist = 0,
        no_return_until_pieces = 9999,
        world_obstacle_clear_candidates = 5,
    }
    connector_apply_legacy_smart_clearance_opts(opts)

    profile = tostring(profile or "eliminator")
    step_index = tonumber(step_index or 1) or 1

    if profile == "drifter" then
        opts.prefer_turns = true
        opts.prefer_gentle_turns = true
        opts.max_turn_angle = 90
        if step_index % 5 == 0 then opts.prefer_straight = true; opts.no_front = false
        else opts.no_front = (step_index % 3 ~= 0) end
    elseif profile == "spiral" then
        opts.prefer_turns = true
        opts.prefer_sharp_turns = true
        opts.no_front = true
        opts.min_turn_angle = 45
        opts.max_turn_angle = 90
        opts.only_turn_direction = TG_MINIGAME_SPIRAL_DIRECTION or "left"
    elseif profile == "switchback" then
        opts.prefer_turns = true
        opts.prefer_sharp_turns = true
        opts.no_front = true
        opts.min_turn_angle = 90
        opts.max_turn_angle = 135
        local block = math.floor((step_index - 1) / 2)
        opts.only_turn_direction = (block % 2 == 0) and "left" or "right"
    elseif profile == "skysprint" then
        if step_index % 5 == 0 then
            opts.prefer_turns = true
            opts.prefer_gentle_turns = true
            opts.max_turn_angle = 90
        else
            opts.only_front = true
            opts.prefer_straight = true
        end
    else -- eliminator
        if step_index % 4 == 0 then
            opts.prefer_straight = true
        else
            opts.prefer_turns = true
            opts.prefer_gentle_turns = true
            opts.max_turn_angle = 135
        end
    end
    return opts
end

function tg_minigame_add_connected_piece(level, profile, step_index, run_id, generation_token)
    if not tg_minigame_is_run_current(run_id, generation_token) then return nil end
    local opts = tg_minigame_build_step_options(profile, step_index)
    opts.generation_token = generation_token
    local obj = connector_try_next_legacy_smart("minigame_" .. tostring(profile) .. "_" .. tostring(step_index), opts)

    -- If a highly stylized filter dead-ends, relax only the style constraint, not overlap/world safety.
    if not obj and (profile == "spiral" or profile == "switchback" or profile == "skysprint") then
        local fallback = tg_minigame_build_step_options("eliminator", step_index)
        fallback.generation_token = generation_token
        fallback.prefer_turns = profile ~= "skysprint"
        fallback.prefer_gentle_turns = profile == "spiral"
        fallback.prefer_straight = profile == "skysprint"
        fallback.max_turn_angle = profile == "spiral" and 135 or nil
        obj = connector_try_next_legacy_smart("minigame_" .. tostring(profile) .. "_relaxed_" .. tostring(step_index), fallback)
    end

    if obj then
        tg_minigame_tag_history_entry(level, "road")
        return obj
    end
    return nil
end

function tg_minigame_force_flat_anchor(level, run_id, generation_token, label)
    if not tg_minigame_is_run_current(run_id, generation_token) then return nil end
    local opts = {
        generation_token = generation_token,
        only_front = true,
        prefer_straight = true,
        no_180 = true,
        top_n = 1,
        tetris_preview = false,
        allow_start_close = true,
        start_avoid_dist = 0,
        start_guard_dist = 0,
        no_return_until_pieces = 9999,
        world_obstacle_clear_candidates = 3,
    }
    connector_apply_legacy_smart_clearance_opts(opts)
    local obj = connector_try_next_legacy_smart(tostring(label or "minigame_flat_anchor"), opts)
    if obj then tg_minigame_tag_history_entry(level, "ramp_anchor") end
    return obj
end

function tg_minigame_outgoing_heading(anchor_obj)
    if not anchor_obj or anchor_obj == 0 then return connector_builder_state.current_heading or 0.0 end
    local pm = tg_get_meta(anchor_obj) or {}
    local candidates = connector_candidate_list(
        connector_builder_state.current_model or pm.model or "stt_prop_track_straight_bar_m",
        connector_builder_state.current_direction or "left",
        { only_front = true, no_180 = true }
    )
    local row = candidates and candidates[1] or nil
    if row then
        local wm = tg_world_from_parent(anchor_obj, row.x, row.y, row.z, row.rotZ)
        local dx = (tonumber(wm.x) or 0.0) - (tonumber(pm.x) or 0.0)
        local dy = (tonumber(wm.y) or 0.0) - (tonumber(pm.y) or 0.0)
        if math.abs(dx) + math.abs(dy) > 0.01 then
            local atan2 = math.atan2 or math.atan
            return tg_normalize_heading(math.deg(atan2(dy, dx)))
        end
    end
    return tg_normalize_heading(connector_builder_state.current_heading or pm.heading or 0.0)
end

function tg_minigame_compute_transition_layout(anchor_obj, aoa_deg, up_count)
    local pm = tg_get_meta(anchor_obj)
    if not pm then return nil end
    local heading = tg_minigame_outgoing_heading(anchor_obj)
    local length = math.max(20.0, tonumber(TG_START_RAMP_SEGMENT_LENGTH or 53.0) or 53.0)
    local half = length * 0.5
    local aoa = math.abs(tonumber(aoa_deg or TG_ELIMINATOR_LEVEL_AOA or 10.0) or 10.0)
    local count = math.max(1, math.floor(tonumber(up_count or TG_ELIMINATOR_LEVEL_RAMP_PIECES or 3) or 3))
    local rad = math.rad(aoa)
    local horiz = length * math.cos(rad)
    local rise = length * math.sin(rad)
    local entries = {}

    -- Existing flat parent contributes half its length; the ramp contributes half its projected length.
    local first_dist = half + half * math.cos(rad)
    local x, y = calculate_new_position(pm, heading, first_dist, 0.0, 0.0)
    local z = (tonumber(pm.z) or 0.0) + half * math.sin(rad)

    for i = 1, count do
        if i > 1 then
            x, y = calculate_new_position({x=x,y=y,z=z}, heading, horiz, 0.0, 0.0)
            z = z + rise
        end
        entries[#entries + 1] = {
            model = "stt_prop_track_straight_bar_m", x=x, y=y, z=z,
            heading=heading, pitch=0.0, roll=0.0, aoa=aoa,
            minigame_transition=true, transition_up=true, transition_index=i
        }
    end

    local last = entries[#entries]
    local flat_dist = half * math.cos(rad) + half
    local fx, fy = calculate_new_position(last, heading, flat_dist, 0.0, 0.0)
    local fz = (tonumber(last.z) or 0.0) + half * math.sin(rad)
    entries[#entries + 1] = {
        model = "stt_prop_track_straight_bar_m", x=fx, y=fy, z=fz,
        heading=heading, pitch=0.0, roll=0.0, aoa=0.0,
        minigame_transition=true, transition_flat=true, transition_index=count+1
    }
    return entries, heading, aoa
end

function tg_minigame_append_transition_ramp(level, run_id, generation_token, opts)
    opts = opts or {}
    if not tg_minigame_is_run_current(run_id, generation_token) then return false end

    -- End the random route on a real flat straight so the transition is edge-aligned to a known floor.
    local anchor = tg_minigame_force_flat_anchor(level, run_id, generation_token, "minigame_level_" .. tostring(level) .. "_anchor")
    if not anchor then
        tg_warn("MINIGAME", "could not create flat anchor for level transition " .. tostring(level))
        return false
    end
    if opts.cull then tg_minigame_delete_oldest_piece("anchor_level_" .. tostring(level)) end
    util.yield(opts.delay_ms or TG_ELIMINATOR_CULL_DELAY_MS or 105)

    local entries, heading, aoa = tg_minigame_compute_transition_layout(anchor, opts.aoa or TG_ELIMINATOR_LEVEL_AOA, opts.up_count or TG_ELIMINATOR_LEVEL_RAMP_PIECES)
    if not entries then return false end

    -- Preflight the entire transition before spawning any of it. TrackMatic-owned pieces are ignored
    -- by obstacle avoidance, while buildings/map props still veto the transition.
    for i, meta in ipairs(entries) do
        connector_apply_track_size_meta(meta, meta.model)
        local blocked, why = tg_world_obstacle_probe_meta(meta, anchor, "minigame_transition_" .. tostring(level) .. "_" .. tostring(i))
        if blocked then
            tg_warn("MINIGAME", "level ramp blocked level=" .. tostring(level) .. " piece=" .. tostring(i) .. " reason=" .. tostring(why))
            tg_toast("Minigame climb is blocked by a building/object. The course stopped before clipping through it.", 4500)
            return false
        end
    end

    for i, meta in ipairs(entries) do
        if not tg_minigame_is_run_current(run_id, generation_token) then return false end
        local obj = create_track_object(meta.model, meta.x, meta.y, meta.z, meta.heading)
        if not obj then return false end
        if (tonumber(meta.aoa or 0.0) or 0.0) > 0.0 then
            tg_apply_track_aoa(obj, meta.aoa, meta.heading, "minigame_level_" .. tostring(level) .. "_ramp_" .. tostring(i))
        else
            tg_apply_track_rotation(obj, 0.0, 0.0, meta.heading, "minigame_level_" .. tostring(level) .. "_flat")
        end
        local om = tg_get_meta(obj) or {}
        om.minigame_level = level
        om.minigame_kind = meta.transition_flat and "level_flat" or "level_ramp"
        om.minigame_transition = true
        om.aoa = tonumber(meta.aoa or 0.0) or 0.0
        om.pitch = 0.0
        om.roll = 0.0
        tg_set_meta(obj, om)

        connector_builder_state.history[#connector_builder_state.history + 1] = {
            obj=obj, model=meta.model, direction="left", open_side=meta.transition_flat and "left" or nil,
            heading=meta.heading, minigame_level=level, minigame_kind=om.minigame_kind,
            minigame_transition=true, aoa=om.aoa
        }
        local entry = connector_builder_state.history[#connector_builder_state.history]
        local list = tg_minigame_level_table(level)
        entry.minigame_index = #list + 1
        table.insert(list, entry)
        connector_builder_state.pieces = #connector_builder_state.history
        connector_builder_state.accepted = #connector_builder_state.history

        connector_builder_state.current_obj = obj
        connector_builder_state.current_model = meta.model
        connector_builder_state.current_heading = meta.heading
        connector_builder_state.current_direction = "left"
        if meta.transition_flat then connector_port_init(obj, "left", "minigame_level_flat_exit") end

        tg_log("[MINIGAME][RAMP] level=" .. tostring(level) .. " piece=" .. tostring(i) .. "/" .. tostring(#entries) ..
            " aoa=" .. string.format("%.1f", tonumber(meta.aoa or 0.0) or 0.0) .. " bank=0.0 z=" .. string.format("%.1f", tonumber(meta.z or 0.0) or 0.0))
        if opts.cull then tg_minigame_delete_oldest_piece("ramp_level_" .. tostring(level) .. "_piece_" .. tostring(i)) end
        util.yield(opts.delay_ms or TG_ELIMINATOR_CULL_DELAY_MS or 105)
    end

    tg_log("[MINIGAME][RAMP_DONE] level=" .. tostring(level) .. " aoa=" .. string.format("%.1f", aoa or 0.0) ..
        " upPieces=" .. tostring(#entries - 1) .. " heading=" .. string.format("%.1f", heading or 0.0) .. " floorConnected=true")
    return true
end

function tg_minigame_build_initial_level(run_id, generation_token, profile, target)
    if not tg_minigame_is_run_current(run_id, generation_token) then return false end
    clear_race_track("minigame_" .. tostring(profile) .. "_reset")
    TG_MINIGAME_LEVELS = {}
    TG_MINIGAME_CURRENT_LEVEL = 1
    local start = connector_spawn_start("minigame_" .. tostring(profile) .. "_start")
    if not start then return false end
    tg_minigame_tag_existing_history(1, "launch")

    target = math.max(#(connector_builder_state.history or {}), math.floor(tonumber(target or 20) or 20))
    local failures = 0
    while #(tg_minigame_level_table(1)) < target do
        if not tg_minigame_is_run_current(run_id, generation_token) then return false end
        local step = #(tg_minigame_level_table(1)) + 1
        local obj = tg_minigame_add_connected_piece(1, profile, step, run_id, generation_token)
        if obj then
            failures = 0
        else
            failures = failures + 1
            if failures >= 4 then
                tg_warn("MINIGAME", "initial level stopped early profile=" .. tostring(profile) .. " failures=" .. tostring(failures))
                break
            end
        end
        util.yield(TG_ELIMINATOR_BUILD_DELAY_MS or 95)
    end
    tg_log("[MINIGAME][LEVEL_READY] mode=" .. tostring(profile) .. " level=1 pieces=" .. tostring(#tg_minigame_level_table(1)))
    return #tg_minigame_level_table(1) >= 8
end

function tg_minigame_eliminator_extend_level(next_level, run_id, generation_token)
    if not tg_minigame_is_run_current(run_id, generation_token) then return false end
    TG_MINIGAME_STATE = "ascending_to_level_" .. tostring(next_level)
    tg_minigame_level_table(next_level)

    local ramp_ok = tg_minigame_append_transition_ramp(next_level, run_id, generation_token, {
        aoa = TG_ELIMINATOR_LEVEL_AOA,
        up_count = TG_ELIMINATOR_LEVEL_RAMP_PIECES,
        delay_ms = TG_ELIMINATOR_CULL_DELAY_MS,
        cull = true,
    })
    if not ramp_ok then return false end

    local failures = 0
    while #tg_minigame_level_table(next_level) < (TG_ELIMINATOR_LEVEL_PIECES or 20) do
        if not tg_minigame_is_run_current(run_id, generation_token) then return false end
        local step = #tg_minigame_level_table(next_level) + 1
        local obj = tg_minigame_add_connected_piece(next_level, "eliminator", step, run_id, generation_token)
        if obj then
            failures = 0
            tg_minigame_delete_oldest_piece("grow_level_" .. tostring(next_level) .. "_piece_" .. tostring(step))
        else
            failures = failures + 1
            if failures >= 5 then
                tg_warn("MINIGAME", "Eliminator front could not extend after retries at level=" .. tostring(next_level))
                return false
            end
        end
        util.yield(TG_ELIMINATOR_CULL_DELAY_MS or 105)
    end

    TG_MINIGAME_CURRENT_LEVEL = next_level
    TG_MINIGAME_STATE = "level_" .. tostring(next_level) .. "_ready"
    local front_meta = tg_get_meta(connector_builder_state.current_obj) or {}
    tg_log("[MINIGAME][ELIMINATOR][LEVEL_READY] level=" .. tostring(next_level) ..
        " pieces=" .. tostring(#tg_minigame_level_table(next_level)) ..
        " altitude=" .. string.format("%.1f", tonumber(front_meta.z or 0.0) or 0.0))
    tg_toast("Eliminator Level " .. tostring(next_level) .. " ready! Rear track is disappearing.", 2600)
    return true
end

function tg_minigame_eliminator()
    local run_id, generation_token = tg_minigame_begin("Eliminator")
    if not tg_minigame_build_initial_level(run_id, generation_token, "eliminator", TG_ELIMINATOR_LEVEL_PIECES) then
        TG_MINIGAME_ACTIVE = false
        TG_MINIGAME_STATE = "build_failed"
        tg_toast("Eliminator could not build the first level here. Try a more open starting direction.", 4500)
        return false
    end

    TG_MINIGAME_STATE = "level_1_ready"
    tg_toast("Eliminator ready. Reach the halfway point to build Level 2 and erase the track behind you!", 5000)

    local level = 1
    local last_log_index = -1
    while tg_minigame_is_run_current(run_id, generation_token) do
        local index, dist, total = tg_minigame_nearest_level_progress(level)
        local trigger = math.max(2, math.ceil((tonumber(total) or 0) * (TG_ELIMINATOR_HALF_RATIO or 0.50)))
        if index ~= last_log_index and index > 0 and dist <= (TG_ELIMINATOR_PROGRESS_RADIUS or 42.0) then
            last_log_index = index
            tg_log("[MINIGAME][ELIMINATOR][PROGRESS] level=" .. tostring(level) .. " nearest=" .. tostring(index) .. "/" .. tostring(total) ..
                " trigger=" .. tostring(trigger) .. " dist=" .. string.format("%.1f", dist))
        end

        if total > 0 and index >= trigger and dist <= (TG_ELIMINATOR_PROGRESS_RADIUS or 42.0) then
            local front = tg_get_meta(connector_builder_state.current_obj) or {}
            if (tonumber(front.z or 0.0) or 0.0) >= (TG_ELIMINATOR_MAX_ALTITUDE or 1200.0) then
                TG_MINIGAME_STATE = "summit"
                tg_log("[MINIGAME][ELIMINATOR][SUMMIT] altitude=" .. tostring(front.z))
                tg_toast("ELIMINATOR SUMMIT! You reached the top of the generated tower.", 6000)
                break
            end
            local next_level = level + 1
            tg_log("[MINIGAME][ELIMINATOR][HALFWAY] level=" .. tostring(level) .. " index=" .. tostring(index) ..
                " startingLevel=" .. tostring(next_level))
            tg_toast("HALFWAY! Level " .. tostring(next_level) .. " is building. Keep moving, the rear is disappearing!", 3200)
            if not tg_minigame_eliminator_extend_level(next_level, run_id, generation_token) then
                TG_MINIGAME_STATE = "extension_stopped"
                break
            end
            level = next_level
            last_log_index = -1
        end
        util.yield(TG_ELIMINATOR_MONITOR_MS or 180)
    end

    if tonumber(run_id) == tonumber(TG_MINIGAME_RUN_ID) then
        TG_MINIGAME_ACTIVE = false
        if TG_MINIGAME_STATE ~= "summit" then TG_MINIGAME_STATE = "finished" end
    end
    tg_log("[MINIGAME][END] mode=Eliminator state=" .. tostring(TG_MINIGAME_STATE) .. " level=" .. tostring(level))
    return true
end

function tg_minigame_build_static(mode, profile, target, ramp_every, ramp_aoa, ramp_up_count)
    local run_id, generation_token = tg_minigame_begin(mode)
    clear_race_track("minigame_" .. tostring(profile) .. "_reset")
    TG_MINIGAME_LEVELS = {}
    TG_MINIGAME_CURRENT_LEVEL = 1
    local start = connector_spawn_start("minigame_" .. tostring(profile) .. "_start")
    if not start then
        TG_MINIGAME_ACTIVE = false
        TG_MINIGAME_STATE = "build_failed"
        return false
    end
    tg_minigame_tag_existing_history(1, "launch")

    local level = 1
    local total_added = #(connector_builder_state.history or {})
    local since_ramp = 0
    local failures = 0
    target = math.max(total_added + 8, math.floor(tonumber(target or 36) or 36))

    while total_added < target and tg_minigame_is_run_current(run_id, generation_token) do
        if ramp_every and ramp_every > 0 and since_ramp >= ramp_every and total_added < target - 6 then
            level = level + 1
            if not tg_minigame_append_transition_ramp(level, run_id, generation_token, {
                aoa = ramp_aoa or 7.0, up_count = ramp_up_count or 2, delay_ms = 85, cull = false
            }) then break end
            total_added = #(connector_builder_state.history or {})
            since_ramp = 0
        else
            local obj = tg_minigame_add_connected_piece(level, profile, total_added + 1, run_id, generation_token)
            if obj then
                total_added = total_added + 1
                since_ramp = since_ramp + 1
                failures = 0
            else
                failures = failures + 1
                if failures >= 5 then break end
            end
            util.yield(85)
        end
    end

    TG_MINIGAME_CURRENT_LEVEL = level
    TG_MINIGAME_STATE = "ready"
    TG_MINIGAME_ACTIVE = false -- static course is complete; track remains until cleared.
    tg_log("[MINIGAME][STATIC_READY] mode=" .. tostring(mode) .. " pieces=" .. tostring(#(connector_builder_state.history or {})) ..
        " levels=" .. tostring(level) .. " floorConnected=true")
    tg_toast(tostring(mode) .. " ready! " .. tostring(#(connector_builder_state.history or {})) .. " connected pieces.", 4000)
    return true
end

function tg_minigame_drifter()
    return tg_minigame_build_static("Drifter", "drifter", TG_MINIGAME_DRIFTER_PIECES, 13, 6.0, 2)
end

function tg_minigame_spiral()
    TG_MINIGAME_SPIRAL_DIRECTION = (math.random(2) == 1) and "left" or "right"
    tg_log("[MINIGAME][SPIRAL] direction=" .. tostring(TG_MINIGAME_SPIRAL_DIRECTION))
    return tg_minigame_build_static("Spiral", "spiral", TG_MINIGAME_SPIRAL_PIECES, 7, 8.0, 2)
end

function tg_minigame_switchback()
    return tg_minigame_build_static("Switchback", "switchback", TG_MINIGAME_SWITCHBACK_PIECES, 9, 8.0, 2)
end

function tg_minigame_skysprint()
    return tg_minigame_build_static("Sky Sprint", "skysprint", TG_MINIGAME_SKYSPRINT_PIECES, 11, 7.0, 2)
end

-- Continuous zero-bank incline. This intentionally does NOT use connector_spawn_start(),
-- because the normal Smart Random launch becomes flat after three climbing pieces.
-- Sky Climb repeats that same AoA forever, placing every segment edge-to-edge.
function tg_minigame_skyclimb()
    local run_id, generation_token = tg_minigame_begin("Sky Climb")
    clear_race_track("minigame_skyclimb_reset")
    connector_reset_state()
    TG_MINIGAME_LEVELS = {}
    TG_MINIGAME_CURRENT_LEVEL = 1

    local pos, heading = tg_get_local_position_heading("minigame_skyclimb_start")
    if not pos then
        TG_MINIGAME_ACTIVE = false
        TG_MINIGAME_STATE = "build_failed"
        tg_toast("Sky Climb could not read your start position.", 4000)
        return false
    end

    heading = tg_normalize_heading(heading or 0.0)
    local model = "stt_prop_track_straight_bar_m"
    local length = math.max(20.0, tonumber(TG_START_RAMP_SEGMENT_LENGTH or 53.0) or 53.0)
    local half = length * 0.5
    local aoa = math.abs(tonumber(TG_START_RAMP_AOA_DEG or 10.0) or 10.0)
    local rad = math.rad(aoa)
    local horiz = length * math.cos(rad)
    local rise = length * math.sin(rad)
    local max_altitude = tonumber(TG_MINIGAME_SKYCLIMB_MAX_ALTITUDE or 1200.0) or 1200.0
    local max_pieces = math.max(24, math.floor(tonumber(TG_MINIGAME_SKYCLIMB_MAX_PIECES or 140) or 140))
    local delay_ms = math.max(35, math.floor(tonumber(TG_MINIGAME_SKYCLIMB_BUILD_DELAY_MS or 70) or 70))

    local x, y = calculate_new_position(pos, heading, TG_START_RAMP_FORWARD_OFFSET or 18.0, 0.0, 0.0)
    -- Same below-player entry geometry as the confirmed-good Smart Random launch ramp.
    local z = (tonumber(pos.z) or 0.0) + (TG_START_RAMP_BASE_HEIGHT or -1.60) + half * math.sin(rad)

    connector_builder_state.active = true
    connector_builder_state.history = {}
    connector_builder_state.pieces = 0
    connector_builder_state.accepted = 0
    connector_builder_state.rejected = 0

    local previous_obj = 0
    local built = 0
    TG_MINIGAME_STATE = "climbing"

    while built < max_pieces and z <= max_altitude and tg_minigame_is_run_current(run_id, generation_token) do
        local meta = {
            model=model, x=x, y=y, z=z, heading=heading,
            pitch=0.0, roll=0.0, aoa=aoa,
            minigame_level=1, minigame_kind="sky_climb",
            sky_climb=true, sky_climb_index=built + 1
        }
        connector_apply_track_size_meta(meta, model)
        local blocked, why = tg_world_obstacle_probe_meta(meta, previous_obj, "minigame_skyclimb_" .. tostring(built + 1))
        if blocked then
            TG_MINIGAME_STATE = "blocked"
            tg_warn("MINIGAME", "Sky Climb blocked at piece=" .. tostring(built + 1) .. " reason=" .. tostring(why))
            tg_toast("Sky Climb stopped before clipping through a building/object.", 4500)
            break
        end

        local obj = create_track_object(model, x, y, z, heading)
        if not obj or obj == 0 then
            TG_MINIGAME_STATE = "spawn_failed"
            tg_warn("MINIGAME", "Sky Climb spawn failed at piece=" .. tostring(built + 1))
            break
        end

        tg_apply_track_aoa(obj, aoa, heading, "minigame_skyclimb_" .. tostring(built + 1))
        local om = tg_get_meta(obj) or {}
        om.minigame_level = 1
        om.minigame_kind = "sky_climb"
        om.sky_climb = true
        om.sky_climb_index = built + 1
        om.aoa = aoa
        om.pitch = 0.0
        om.roll = 0.0
        tg_set_meta(obj, om)

        local entry = {
            obj=obj, model=model, direction="left", heading=heading,
            minigame_level=1, minigame_kind="sky_climb",
            sky_climb=true, sky_climb_index=built + 1, aoa=aoa
        }
        connector_builder_state.history[#connector_builder_state.history + 1] = entry
        local level_list = tg_minigame_level_table(1)
        entry.minigame_index = #level_list + 1
        table.insert(level_list, entry)

        built = built + 1
        connector_builder_state.pieces = built
        connector_builder_state.accepted = built
        if built == 1 then
            connector_builder_state.start_obj = obj
            connector_builder_state.first_real_obj = obj
        end
        connector_builder_state.current_obj = obj
        connector_builder_state.current_model = model
        connector_builder_state.current_direction = "left"
        connector_builder_state.current_heading = heading
        previous_obj = obj

        tg_log("[MINIGAME][SKY_CLIMB][PIECE] index=" .. tostring(built) ..
            " aoa=" .. string.format("%.1f", aoa) ..
            " bank=0.0 z=" .. string.format("%.1f", z) ..
            " floorConnected=true")

        x, y = calculate_new_position({x=x,y=y,z=z}, heading, horiz, 0.0, 0.0)
        z = z + rise
        util.yield(delay_ms)
    end

    if tonumber(run_id) == tonumber(TG_MINIGAME_RUN_ID) then
        TG_MINIGAME_ACTIVE = false
        if TG_MINIGAME_STATE == "climbing" then TG_MINIGAME_STATE = "summit" end
    end

    tg_log("[MINIGAME][SKY_CLIMB][READY] pieces=" .. tostring(built) ..
        " aoa=" .. string.format("%.1f", aoa) ..
        " heading=" .. string.format("%.1f", heading) ..
        " state=" .. tostring(TG_MINIGAME_STATE) ..
        " floorConnected=true belowPlayer=" .. string.format("%.2f", math.abs(tonumber(TG_START_RAMP_BASE_HEIGHT or -1.60) or -1.60)))
    tg_toast("Sky Climb ready: " .. tostring(built) .. " attached incline pieces.", 4500)
    return built > 0
end

function tg_minigame_status_to_log()
    tg_log("[MINIGAME][STATUS] mode=" .. tostring(TG_MINIGAME_MODE) ..
        " active=" .. tostring(TG_MINIGAME_ACTIVE) ..
        " state=" .. tostring(TG_MINIGAME_STATE) ..
        " level=" .. tostring(TG_MINIGAME_CURRENT_LEVEL) ..
        " visibleHistory=" .. tostring(#(connector_builder_state and connector_builder_state.history or {})))
end


