    if #objects < 16 then
        return
    end
   
    local end_model = "stt_prop_track_straight_bar_m"
    local end_attachment = nil
   
     for _, attachment in ipairs(attached_formation) do
        if Last_direction == "front" then
            end_attachment = {"stt_prop_track_straight_bar_m", parentDirection="left", child = "stt_prop_track_straight_bar_m", x = 53.00, y = 0.0, z = 0.0, rotX = 0.0, rotY = 0.0, rotZ = 0.0, type = "straight", direction = "front", angle = 0}
