local function calculate_adjusted_height_and_distance(start_obj, sub_start_fragment, player_ped)
    local player_coords = ENTITY.GET_ENTITY_COORDS(player_ped, true)
    local player_ground_z = getHeightFromJson(player_coords.x, player_coords.y)
    local start_coords = ENTITY.GET_ENTITY_COORDS(start_obj, true)
    local distance = MISC.GET_DISTANCE_BETWEEN_COORDS(player_coords.x, player_coords.y, player_ground_z, start_coords.x, start_coords.y, start_coords.z, true)
    return  distance
end


local function rotate_offset(offset, rotation)
    local radZ = math.rad(rotation.z)
    local cosZ = math.cos(radZ)
    local sinZ = math.sin(radZ)
    
    local rotated_offset = {}
    rotated_offset.x = offset.x * cosZ - offset.y * sinZ
    rotated_offset.y = offset.x * sinZ + offset.y * cosZ
    rotated_offset.z = offset.z  
    
    return rotated_offset
end

local function ptfx_at_entity(entity, effect, offset, scale_ptfx)
    local entity_pos = ENTITY.GET_ENTITY_COORDS(entity, true)
    local entity_rot = ENTITY.GET_ENTITY_ROTATION(entity, 2)  

    local rotated_offset = rotate_offset(offset, entity_rot)
    
    local x = entity_pos.x + rotated_offset.x
    local y = entity_pos.y + rotated_offset.y
    local z = entity_pos.z + rotated_offset.z

    if type(x) ~= "number" or type(y) ~= "number" or type(z) ~= "number" then
        util.toast("Invalid coordinates for particle effect")
        return
    end

    STREAMING.REQUEST_NAMED_PTFX_ASSET(effect.asset)
    while not STREAMING.HAS_NAMED_PTFX_ASSET_LOADED(effect.asset) do
        util.yield(0)
    end
    GRAPHICS.USE_PARTICLE_FX_ASSET(effect.asset)
    GRAPHICS.START_NETWORKED_PARTICLE_FX_NON_LOOPED_AT_COORD(
        effect.effect,
        x, y, z,  
        0.0, 0.0, 0.0,  
        scale_ptfx, 
        false, false, false  
    )
end

local function trigger_start_confetti(entity)
    local offset1 = {x = -70.0, y = 10.0, z = 0.0}  
    local offset2 = {x = -70.0, y = -10.0, z = 0.0}  
   
    ptfx_at_entity(entity, start_ptfx, offset1, start_scale)
    ptfx_at_entity(entity, start_ptfx, offset2, start_scale)
end

local function trigger_end_confetti(entity)
    local offset1 = {x = 30.0, y = 10.0, z = 0.0}  
    local offset2 = {x = 30.0, y = -10.0, z = 0.0}  
    
    ptfx_at_entity(entity, end_ptfx, offset1, end_scale)
    ptfx_at_entity(entity, end_ptfx, offset2, end_scale)
end


local function update_best_score(new_time, player_name)
    local score_display_objects = {num_1, num_2, num_3, num_4, num_5, num_6}
    best_race_time = new_time
    best_player_name = player_name
    local time_str = string.format("%06.3f", new_time):gsub("%.", "")  

   
    while #time_str < 5 do
        time_str = "0" .. time_str
    end
    while #time_str < 6 do
        time_str = "0" .. time_str
    end

    for i = 1, 6 do
        local char = time_str:sub(i, i)
        if char then
            print(char)
            local display_obj = score_display_objects[i]
            if display_obj then
                entities.delete_by_handle(display_obj)
            end
            util.request_model(util.joaat("prop_mk_num_" .. char))
            local new_obj = entities.create_object(util.joaat("prop_mk_num_" .. char), v3(0.0, 0.0, 0.0))
            networked_entity(new_obj)
            table.insert(objects, new_obj)
            local sub_space = 0
            if i > 3 then 
                sub_space = 1
            end
            ENTITY.ATTACH_ENTITY_TO_ENTITY(new_obj, panneau_score_entity, 0, 0.5, (-3.0 + (i - 1) * 1.0) + sub_space, 0.3, -90.0, -90.0, 0.0, false, false, true, false, 2, true, 0)
            ENTITY.FREEZE_ENTITY_POSITION(new_obj, true)
            score_display_objects[i] = new_obj
        end
    end

    num_1, num_2, num_3, num_4, num_5, num_6 = table.unpack(score_display_objects)

    util.toast("New high score: " .. string.format("%.3f", new_time) .. " by " .. player_name .. "!")
end


local function rotate_point(point, rotation)
    local rad_x = math.rad(rotation.x)
    local rad_y = math.rad(rotation.y)
    local rad_z = math.rad(rotation.z)

    local cos_x = math.cos(rad_x)
    local sin_x = math.sin(rad_x)
    local cos_y = math.cos(rad_y)
    local sin_y = math.sin(rad_y)
    local cos_z = math.cos(rad_z)
    local sin_z = math.sin(rad_z)

 
    local x_new = point.x * cos_z - point.y * sin_z
    local y_new = point.x * sin_z + point.y * cos_z

 
    local z_new = point.z * cos_y - x_new * sin_y
    x_new = point.z * sin_y + x_new * cos_y

    local final_y = y_new * cos_x - z_new * sin_x
    local final_z = y_new * sin_x + z_new * cos_x
    local final_x = x_new

    return {x = final_x, y = final_y, z = final_z}
end

local function is_player_near_entity(player_ped, entity, padding)
    local player_position = ENTITY.GET_ENTITY_COORDS(player_ped, true)
    local entity_position = ENTITY.GET_ENTITY_COORDS(entity, true)

    local min = memory.alloc(24)
    local max = memory.alloc(24)
    local position = ENTITY.GET_ENTITY_COORDS(entity, true)
    local rotation = ENTITY.GET_ENTITY_ROTATION(entity, 2)

    MISC.GET_MODEL_DIMENSIONS(ENTITY.GET_ENTITY_MODEL(entity), min, max)

    local min_vec = min:readVector3()
    local max_vec = max:readVector3()

    min_vec.x = min_vec.x - padding
    min_vec.y = min_vec.y - padding
    min_vec.z = min_vec.z - padding

    max_vec.x = max_vec.x + padding
    max_vec.y = max_vec.y + padding
    max_vec.z = max_vec.z + padding

    local corners = {
        rotate_point({x = min_vec.x, y = min_vec.y, z = min_vec.z}, rotation),
        rotate_point({x = min_vec.x, y = min_vec.y, z = max_vec.z}, rotation),
        rotate_point({x = min_vec.x, y = max_vec.y, z = min_vec.z}, rotation),
        rotate_point({x = min_vec.x, y = max_vec.y, z = max_vec.z}, rotation),
        rotate_point({x = max_vec.x, y = min_vec.y, z = min_vec.z}, rotation),
        rotate_point({x = max_vec.x, y = min_vec.y, z = max_vec.z}, rotation),
        rotate_point({x = max_vec.x, y = max_vec.y, z = min_vec.z}, rotation),
        rotate_point({x = max_vec.x, y = max_vec.y, z = max_vec.z}, rotation)
    }

    local function is_point_inside_entity(point)
        local relative_point = {
            x = point.x - entity_position.x,
            y = point.y - entity_position.y,
            z = point.z - entity_position.z
        }

        local rotated_point = rotate_point(relative_point, {x = -rotation.x, y = -rotation.y, z = -rotation.z})

        return (rotated_point.x >= min_vec.x and rotated_point.x <= max_vec.x) and
               (rotated_point.y >= min_vec.y and rotated_point.y <= max_vec.y) and
               (rotated_point.z >= min_vec.z and rotated_point.z <= (max_vec.z + 5.0))
    end

    if is_point_inside_entity(player_position) then
        return true
    end

    return false
end

local function check_player_passed_start()
    
    local player_peds = players.list()
    local current_time = os.clock()  
    for _, player_id in ipairs(player_peds) do
        local player_ped = PLAYER.GET_PLAYER_PED(player_id)
        if is_player_near_entity(player_ped, start_entity, 0.0) then  
            if not players_passed_start[player_id] then
                players_passed_start[player_id] = true
                players_start_pass_time[player_id] = current_time  
                util.toast("The player" .. player_id .. " passed the starting fragment !")
            elseif players_ended_race[player_id] and (current_time - (players_end_time[player_id] or 0) >= 2) then
                players_passed_start[player_id] = true
                players_started_race[player_id] = nil
                players_ended_race[player_id] = nil
                players_start_pass_time[player_id] = current_time  
                util.toast("The player" .. player_id .. " start the race again !")
            end
        end
    end
end

local function check_player_started_race()
    local current_time = os.clock()  
    for player_id, _ in pairs(players_passed_start) do
        if not players_started_race[player_id] then
            local player_ped = PLAYER.GET_PLAYER_PED(player_id)
            if is_player_near_entity(player_ped, first_fragment_entity, 0.0) then  
             
                if not players_end_time[player_id] or (current_time - players_end_time[player_id] >= 2) then
                    if (current_time - (players_start_pass_time[player_id] or 0) >= 2) then
                        players_end_time[player_id] = nil
                        players_started_race[player_id] = true
                        players_start_time[player_id] = current_time 
                        util.toast("The player " .. player_id .. " has started the race !")
                        trigger_start_confetti(start_entity) 
                    end
                end
            end
        end
    end
end


local function check_player_ended_race()
    local current_time = os.clock()  
    for player_id, _ in pairs(players_started_race) do
        if not players_ended_race[player_id] then
            local player_ped = PLAYER.GET_PLAYER_PED(player_id)
            local player_name = PLAYER.GET_PLAYER_NAME(player_id)
     
            if is_player_near_entity(player_ped, end_fragment_entity, 0.0) then  
                players_ended_race[player_id] = true
                players_end_time[player_id] = current_time  

                local race_time = current_time - (players_start_time[player_id] or current_time)
                local race_time_float = tonumber(string.format("%.3f", race_time)) 

                if not best_race_time or race_time_float < best_race_time then
                    best_race_time = race_time_float
                    best_player_name = player_name
                    if best_score_option then
                        update_best_score(race_time_float, player_name)
                    end
                    util.toast("New best time: " .. string.format("%.3f", best_race_time) .. " seconds by " .. best_player_name .. "!")
                end

                util.toast("The player " .. player_name .. " finished the race in " .. string.format("%.3f", race_time_float) .. " seconds !")

                local message = "You completed the race in " .. string.format("%.3f", race_time_float) .. " seconds!\nPosition yourself on the target to be teleported back to the start."
                chat.send_targeted_message(player_id, players.user_ped(), message, true)

                trigger_end_confetti(end_fragment_entity)
            end
        end
    end
end


local function check_player_target_teleporter()
    for player_id, _ in pairs(players_started_race) do
        if players_ended_race[player_id] then
            local player_ped = PLAYER.GET_PLAYER_PED(player_id)
            if is_player_near_entity(player_ped, target_end_fragment_entity, 1.0) then 
                local track_teleporter_position = ENTITY.GET_ENTITY_COORDS(jump_track_teleporter, true)
                local first_fragment_entity_position = ENTITY.GET_ENTITY_COORDS(first_fragment_entity, true)

                local direction = {
                    x = first_fragment_entity_position.x - track_teleporter_position.x,
                    y = first_fragment_entity_position.y - track_teleporter_position.y,
                    z = first_fragment_entity_position.z - track_teleporter_position.z
                }

                local length = math.sqrt(direction.x^2 + direction.y^2 + direction.z^2)
                direction.x = direction.x / length
                direction.y = direction.y / length
                direction.z = direction.z / length

                local teleport_x = track_teleporter_position.x + direction.x
                local teleport_y = track_teleporter_position.y + direction.y
                local teleport_z = track_teleporter_position.z + direction.z

                local heading = math.deg(math.atan2(direction.y, direction.x)) + 210
                players.teleport_3d(player_id, teleport_x, teleport_y, teleport_z + 10)
                ENTITY.SET_ENTITY_HEADING(player_ped, heading)

                util.toast("Teleport requested for the player" .. PLAYER.GET_PLAYER_NAME(player_id))
            end
        end
    end
end


local function create_vehicle_on_ramp(ramp_entity)
 
    if last_vehicle then
        local driver = VEHICLE.GET_PED_IN_VEHICLE_SEAT(last_vehicle, -1)
        if not ENTITY.DOES_ENTITY_EXIST(driver) then
            entities.delete_by_handle(last_vehicle)
            last_vehicle = nil
        end
    end

    local random_model = vehicle_models[math.random(#vehicle_models)]

    util.request_model(util.joaat(random_model))

    local ramp_coords = ENTITY.GET_ENTITY_COORDS(ramp_entity, true)
    local ramp_heading = ENTITY.GET_ENTITY_HEADING(ramp_entity) + 90

    local min = memory.alloc(24)
    local max = memory.alloc(24)
    MISC.GET_MODEL_DIMENSIONS(ENTITY.GET_ENTITY_MODEL(ramp_entity), min, max)
    local min_vec = min:readVector3()
    local max_vec = max:readVector3()

    local center_coords = {
        x = (min_vec.x + max_vec.x) / 2,
        y = (min_vec.y + max_vec.y) / 2,
        z = (min_vec.z + max_vec.z) / 2
    }

    local offset = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(ramp_entity, center_coords.x, center_coords.y, center_coords.z)

    local direction_x = math.cos(math.rad(ramp_heading + 90))
    local direction_y = math.sin(math.rad(ramp_heading + 90))

    local extra_offset_distance = 15.0  
    local adjusted_coords = {
        x = offset.x + direction_x * extra_offset_distance,
        y = offset.y + direction_y * extra_offset_distance,
        z = offset.z
    }

    local vehicle = VEHICLE.CREATE_VEHICLE(util.joaat(random_model), adjusted_coords.x, adjusted_coords.y, adjusted_coords.z, ramp_heading, true, false)

    ENTITY.SET_ENTITY_COORDS(vehicle, adjusted_coords.x, adjusted_coords.y, adjusted_coords.z, false, false, false, true)
    ENTITY.SET_ENTITY_HEADING(vehicle, ramp_heading)

    table.insert(objects, vehicle)
    last_vehicle = vehicle

end

local function check_player_option_choiceCar()
    for player_id, _ in pairs(players_passed_start) do
        local player_ped = PLAYER.GET_PLAYER_PED(player_id)
        if is_player_near_entity(player_ped, choice_car_option_entity, 1.0) and choice_command_timer <= 0.0 then
            local player_name = players.get_name(player_id, false)
            choice_command_timer = 3000  
             
            if jump_track_teleporter then
                util.toast("Spawn car requested for the player " .. player_name)
                create_vehicle_on_ramp(jump_track_teleporter)
            end

            if not hide_choice_logo then
                ENTITY.SET_ENTITY_VISIBLE(choice_car_option_entity, false, false)
                hide_choice_logo = true
                choice_logo_timer = 3000  
            end
        end
    end

    if hide_choice_logo and choice_logo_timer > 0 then
        choice_logo_timer = choice_logo_timer - 100 
        if choice_logo_timer <= 0 then
            ENTITY.SET_ENTITY_VISIBLE(choice_car_option_entity, true, true)
            hide_choice_logo = false
        end
    end

    if choice_command_timer > 0 then
        choice_command_timer = choice_command_timer - 100
    end
end

