local function build_race_track_straight_line(start_obj, adjusted_max_fragement)
    tg_report_state("build_straight_start")
    tg_debug("BUILD", "straight start_obj=" .. tg_handle(start_obj) .. " max=" .. tostring(adjusted_max_fragement))
    local first_attachment = {id=3, parent = "stt_prop_race_start_line_03", child = "stt_prop_track_straight_bar_m", x = -79.41, y = 0.0, z = -0.05, rotX = 0.0, rotY = 0.0, rotZ = 180.0, type = "straight", direction = "front", angle = 0}
    local first_obj = attach_object(start_obj, first_attachment.child, first_attachment.x, first_attachment.y, first_attachment.z, first_attachment.rotX, first_attachment.rotY, first_attachment.rotZ)
    current_fragment = first_attachment.child
    parent_direction = first_attachment.direction

    first_fragment_entity = first_obj

    table.insert(valid_fragments_stack, {fragment = current_fragment, direction = parent_direction})

    util.yield(100)

    local max_fragments = adjusted_max_fragement

    for i = 2, max_fragments do
        if not start_entity then
            starting_fail = true
            return
        end
        local attachment = {model = "stt_prop_track_straight_bar_m", x = 53.00, y = 0.0, z = 0.0, rotX = 0.0, rotY = 0.0, rotZ = 0.0, type = "straight", direction = "front", angle = 0}

        local parent_obj = objects[#objects]
        local new_obj = attach_object(parent_obj, attachment.model, attachment.x, attachment.y, attachment.z, attachment.rotX, attachment.rotY, attachment.rotZ)

        current_fragment = attachment.model
        parent_direction = attachment.direction

        table.insert(valid_fragments_stack, {fragment = current_fragment, direction = parent_direction})
        if i == max_fragments then
            build_end_track(objects[#objects], current_fragment, parent_direction)
        end
        util.yield(100)
    end
end


local function display_race_performance()
    
    local current_time = util.current_time_millis() / 1000 
    if current_time - last_display_time < 5 then
        return 
    end

    last_display_time = current_time

    local performance_message = "Race performance results:\n"
    for player_id, end_time in pairs(players_end_time) do
        local start_time = players_start_time[player_id]
        if start_time and end_time then
            local race_time = end_time - start_time
            local race_time_float = tonumber(string.format("%.3f", race_time)) 
            local player_name = PLAYER.GET_PLAYER_NAME(player_id)
            performance_message = performance_message .. "" .. player_name .. " : " .. race_time_float .. " seconds\n"
        end
    end

    if best_race_time and best_player_name then
        performance_message = performance_message .. "Best race time: " .. best_race_time .. " seconds by " .. best_player_name .. "\n"
    end

    if performance_message ~= "Race performance results:\n" then
        util.toast(performance_message)
        chat.send_message(performance_message , false , true , true )
    else
        util.toast("No result.")
    end
end


