-- one build stage with start / done debug lines. returns true and the stage's results
local function tg_stage(name, fn)
    tg_debug("BUILD", "stage_start=" .. tostring(name))
    local a, b, c = fn()
    tg_debug("BUILD", "stage_ok=" .. tostring(name))
    return true, a, b, c
end

local function tg_safe_set_visible(feature, visible, label)
    menu.set_visible(feature, visible)
end

local function tg_safe_set_value(feature, value, label)
    menu.set_value(feature, value)
end

start_creat = menu.action(root_menu, "Build the race track", {}, "Create a racing circuit with track objects.", function()
    tg_report_state("build_clicked")

    local ok_clear = tg_stage("clear_race_track_start", function() clear_race_track("start") end)
    if not ok_clear then return end

    tg_safe_set_visible(start_creat, false, "start_creat")
    tg_safe_set_visible(mode_select, false, "mode_select")

    local adjusted_max_fragement = tonumber(value_adjusted) or tonumber(current_max_fragement) or 30
    if speed_car_option then adjusted_max_fragement = adjusted_max_fragement - 3 end
    if repair_car_option then adjusted_max_fragement = adjusted_max_fragement - 3 end
    if choice_car_option then adjusted_max_fragement = adjusted_max_fragement - 4 end
    if best_score_option then adjusted_max_fragement = adjusted_max_fragement - 10 end
    if adjusted_max_fragement < 1 then adjusted_max_fragement = 1 end
    tg_debug("BUILD", "adjusted_max_fragement=" .. tostring(adjusted_max_fragement) .. " mode=" .. tostring(construction_mode) .. " clean=" .. tostring(clean_pool_option) .. " spawn=" .. tostring(choice_car_option) .. " speed=" .. tostring(speed_car_option) .. " repair=" .. tostring(repair_car_option) .. " best=" .. tostring(best_score_option))

    if clean_pool_option then
        local ok_clean = tg_stage("clean_pool", function() clean_pool() end)
        if not ok_clean then
            tg_warn("BUILD", "clean_pool failed; continuing was blocked for safety")
            return
        end
    else
        tg_debug("BUILD", "clean_pool skipped because option is OFF")
    end

    local ok_base, start_obj, new_adjusted_max_fragement = tg_stage("build_base_track", function() return build_base_track() end)
    if not ok_base or not start_obj or start_obj == 0 then
        tg_error("[BUILD] build_base_track failed or returned no start object; aborting full generator")
        tg_report_state("build_base_failed")
        tg_safe_set_visible(start_creat, true, "start_creat_restore")
        tg_safe_set_visible(mode_select, true, "mode_select_restore")
        return
    end

    adjusted_max_fragement = adjusted_max_fragement + (tonumber(new_adjusted_max_fragement) or 0)
    tg_safe_set_visible(max_fragMenu, false, "max_fragMenu")
    tg_safe_set_visible(delete_menu, true, "delete_menu")
    tg_safe_set_visible(readMaxFragMenu, true, "readMaxFragMenu")
    tg_safe_set_value(readMaxFragMenu, adjusted_max_fragement, "readMaxFragMenu")

    local ok_track, track = tg_stage("build_race_track_" .. tostring(construction_mode), function()
        if construction_mode == "default" then
            return build_race_track_default(start_obj, adjusted_max_fragement)
        elseif construction_mode == "drift" then
            return build_race_track_drift(start_obj, adjusted_max_fragement)
        elseif construction_mode == "straight" then
            return build_race_track_straight_line(start_obj, adjusted_max_fragement)
        end
        return nil
    end)
    if not ok_track then
        tg_error("[BUILD] track generation stage failed; leaving any spawned test/base objects for inspection")
        return
    end

    local ok_tint = tg_stage("apply_tint", function() apply_tint_to_objects(current_tint) end)
    if not ok_tint then tg_warn("BUILD", "Tint stage failed but build may still exist") end

    if not starting_fail then
        util.toast("The racing circuit has been successfully created!")
        tg_report_state("build_success")
    else
        util.toast("The racing circuit has failed!")
        tg_report_state("build_failed_flag")
    end
end)

