local function trigger_top_depart(entity)
    
    local current_time = util.current_time_millis() / 1000 
    if current_time - last_trigger_time < 10 then
        return 
    end

    last_trigger_time = current_time

    local offset1 = {x = -53.0, y = -10.0, z = 0.0} 
    local offset2 = {x = -53.0, y = 10.0, z = 0.0}

    util.request_model(util.joaat("prop_flatscreen_overlay"))
    util.request_model(util.joaat("sr_prop_sr_track_jumpwall"))
    util.request_model(util.joaat("prop_mk_num_0"))
    util.request_model(util.joaat("prop_mk_num_1"))
    util.request_model(util.joaat("prop_mk_num_2"))
    util.request_model(util.joaat("prop_mk_num_3"))
    util.request_model(util.joaat("prop_mk_num_4"))
    util.request_model(util.joaat("prop_mk_num_5"))

    local flatscreen = entities.create_object(util.joaat("prop_flatscreen_overlay"), v3(0.0, 0.0, 0.0))
    networked_entity(flatscreen)
    local stop_sign = entities.create_object(util.joaat("sr_prop_sr_track_jumpwall"), v3(0.0, 0.0, 0.0))
    networked_entity(stop_sign)
    
    local numbers = {
        entities.create_object(util.joaat("prop_mk_num_0"), v3(0.0, 0.0, 0.0)),
        entities.create_object(util.joaat("prop_mk_num_1"), v3(0.0, 0.0, 0.0)),
        entities.create_object(util.joaat("prop_mk_num_2"), v3(0.0, 0.0, 0.0)),
        entities.create_object(util.joaat("prop_mk_num_3"), v3(0.0, 0.0, 0.0)),
        entities.create_object(util.joaat("prop_mk_num_4"), v3(0.0, 0.0, 0.0)),
        entities.create_object(util.joaat("prop_mk_num_5"), v3(0.0, 0.0, 0.0))
    }
    
    ENTITY.ATTACH_ENTITY_TO_ENTITY(flatscreen, start_entity, 0, -51.0, 0.0, 4.4, 0.0, 90.0, 90.0, false, false, true, false, 2, true, 0)
    ENTITY.FREEZE_ENTITY_POSITION(flatscreen, true)
    ENTITY.SET_ENTITY_VISIBLE(flatscreen, true, true)
    ENTITY.SET_ENTITY_COLLISION(flatscreen, false, false)

    for i, number in ipairs(numbers) do
        util.yield()
        networked_entity(number)
        ENTITY.SET_ENTITY_VISIBLE(number, false, false)
        util.yield()
        ENTITY.ATTACH_ENTITY_TO_ENTITY(number, flatscreen, 0, 0.5, -0.1, 0.0, 0.0, -90.0, 0.0, false, false, true, false, 2, true, 0)
        ENTITY.FREEZE_ENTITY_POSITION(number, true)
        ENTITY.SET_ENTITY_COLLISION(number, false, false)
    end
    
    ENTITY.ATTACH_ENTITY_TO_ENTITY(stop_sign, start_entity, 0, -48.3, 0.0, 0.05, 0.0, 0.0, 180.0, false, false, true, false, 2, true, 0)
    ENTITY.FREEZE_ENTITY_POSITION(stop_sign, true)
    ENTITY.SET_ENTITY_VISIBLE(stop_sign, true, true)
    ENTITY.SET_ENTITY_COLLISION(stop_sign, true, true)
    apply_tint_to_entity(stop_sign, current_tint)
  
    for i = 6, 1, -1 do
        ENTITY.SET_ENTITY_VISIBLE(numbers[i], true, true)
        if i == 6 then 
            util.yield(1000)
        end
        util.yield(1000)
        entities.delete_by_handle(numbers[i])
        if i > 1 then
            ENTITY.SET_ENTITY_VISIBLE(numbers[i-1], true, true)
        end
        if i == 2 then 
            entities.delete_by_handle(stop_sign)
            ptfx_at_entity(entity, start_ptfx, offset1, start_scale)
            ptfx_at_entity(entity, start_ptfx, offset2, start_scale)
        end
    end
    entities.delete_by_handle(flatscreen)
end

