        menu.action(TG_UI_TUBE_GROUP, "Hybrid: Random All", {}, "Every section, tube shape and prop switched on for one build, random segments (your Custom picks are kept).", function()
            tg_hybrid_random_all()
        end)

        menu.action(TG_UI_TOOLS_GROUP, "Clear Track / Test Objects", {}, "Prime-safe clear/delete TrackMatic spawned objects.", function()
            tg_generation_cancel("prime_safe_clear_button_pressed")
            clear_race_track("prime_safe_clear")
            tg_report_state("prime_safe_clear_done")
        end)

        tg_prime_diag("TRACK_SAVE_SAFE_UI_DONE", "grouped sections registered; custom dropdown marker added; no scan performed during init")

        tg_prime_diag("PRIME_SAFE_BUTTONS_DONE", "manual essential button registration finished")
        tg_log("[PRIME_SAFE][TAB] Registering TrackMatic tab after safe buttons.")

        tg_prime_diag("PRIME_SAFE_TAB_BEGIN", "before clean ClickGUI tab registration in safe mode")
        __tg_prime_tab_ok, __tg_prime_tab_err = tg_register_clickgui_tab("prime_safe_tail")
        tg_prime_diag("PRIME_SAFE_TAB_DONE", "native-safe tab register ok=" .. tostring(__tg_prime_tab_ok) .. " err=" .. tostring(__tg_prime_tab_err))
        if __tg_prime_tab_ok then
            tg_log("[PRIME_SAFE][TAB_DONE] TrackMatic tab registered with native-job action isolation.")
        else
            tg_error("[PRIME_SAFE][TAB_ERROR] clean tab registration failed: " .. tostring(__tg_prime_tab_err))
        end

        tg_log("[PRIME_SAFE][NEXT] If the tab appears, we can re-add legacy groups one at a time.")
        return
    end

    tg_prime_diag("TAIL_LEGACY_PTFX_BEGIN", "about to create PTFX menu.list root")

