end)

if TG_PRIME_REGISTER_TICKS == false then
    tg_prime_diag("TICK_REGISTER_SKIPPED", "TG_PRIME_REGISTER_TICKS=false; skipping main runtime tick handler")
else
    tg_prime_diag("TICK_REGISTER_BEGIN", "registering main runtime tick handler")
util.create_tick_handler(function()
        if not TG_PRIME_DIAG_FIRST_MAIN_TICK then TG_PRIME_DIAG_FIRST_MAIN_TICK = true; tg_prime_diag("TICK_MAIN_FIRST", "main tick entered") end

        local is_online = util.is_session_started()
        if is_online and not was_online then
            total_max_fragement = 60
            current_max_fragement = total_max_fragement
            menu.set_max_value(max_fragMenu, total_max_fragement)
            menu.set_value(max_fragMenu, current_max_fragement)
            clear_race_track()
        elseif not is_online and was_online then
            total_max_fragement = 80
            current_max_fragement = total_max_fragement / 2
            menu.set_max_value(max_fragMenu, total_max_fragement)
            menu.set_value(max_fragMenu, current_max_fragement)
            clear_race_track()
        end
        was_online = is_online
    
        if start_entity then
            if ENTITY.DOES_ENTITY_EXIST(start_entity) then
                check_player_passed_start()
                check_player_started_race()
                check_player_ended_race()
                check_player_target_teleporter()
                if choice_car_option then
                    check_player_option_choiceCar()
                end
                if repair_car_option then
                    check_player_option_repair()
                end
                if speed_car_option then
                    check_player_option_speed()
                end
            else
                util.toast("The start fragment seems to have been deleted :(\nRemoved all fragments !")
                clear_race_track("end")
                menu.set_visible(max_fragMenu, true)
                menu.set_visible(readMaxFragMenu, false)
                menu.set_value(readMaxFragMenu, 0)
                menu.trigger_commands("deletTrack")    
            end
        end
        util.yield(100) 
end)
end

if TG_PRIME_REGISTER_TICKS == false then
    tg_prime_diag("TICK_REGISTER_SKIPPED", "TG_PRIME_REGISTER_TICKS=false; skipping networked-object update tick handler")
else
tg_prime_diag("TICK_REGISTER_BEGIN", "registering networked-object update tick handler")
util.create_tick_handler(function()
    if not TG_PRIME_DIAG_FIRST_NET_TICK then TG_PRIME_DIAG_FIRST_NET_TICK = true; tg_prime_diag("TICK_NET_FIRST", "networked-object tick entered") end
    if start_entity then
        if #objects > 1 then
            update_networked_objects()
        end
    end
    util.yield(1000) 
end)
end

local function onScriptStop()
    tg_report_state("script_stop")
    if start_entity then
            menu.trigger_commands("deletTrack")
          
    end
end

util.on_stop(onScriptStop)

-- v0.2.3 ClickGUI tab registration. This is intentionally done after all Stand-style menu calls
-- finish creating FeatureMgr features, so the tab can render every queued feature safely.
tg_prime_diag("CLICKGUI_BEGIN", "before clean ClickGUI TrackMatic registration")
local ok, err = tg_register_clickgui_tab("legacy_tail")
if ok then
    tg_prime_diag("CLICKGUI_DONE", "clean ClickGUI registration succeeded")
    tg_log("[DEBUG][MENU] ClickGUI tab registered with native-job action isolation: TrackMatic")
else
    tg_prime_diag("CLICKGUI_ERROR", "clean ClickGUI registration failed err=" .. tostring(err))
