-- ═══════════════════════════════════════════════════════════════════════════════════
-- trackmatic v2.3.11 | quiet console / actionable build and game receipts
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_PM_LOG_CONTEXT = nil
TG_PM_LOG_SEQUENCE = 0

function tg_pm_bool(v) return v and "ON" or "OFF" end
function tg_pm_label(name)
    return tostring(name or ""):match("^(.-)##") or tostring(name or "")
end
function tg_pm_lookup(map, key, field)
    local found = map and map[key]
    if type(found) == "table" then return tostring(found[field or "name"] or key or "-") end
    return tostring(found or key or "-")
end
function tg_pm_radius(tab)
    local id = ({Tubes="tubes",Track="creator",Parkour="parkour",Hybrid="hybrid",Lab="lab"})[tab]
    local r = id and TG_RS_RADIUS and TG_RS_RADIUS[id] or nil
    if r == nil then return nil end
    return r == 0 and "Unlimited" or tostring(r) .. "m"
end
function tg_pm_limit(tab)
    local id = ({Tubes="tubes",Track="creator",Parkour="parkour",Hybrid="hybrid",Lab="lab"})[tab]
    if not id or not tg_rs_limit then return nil end
    return tonumber(tg_rs_limit(id))
end
function tg_pm_count_on(t)
    local n=0
    for _,enabled in pairs(t or {}) do if enabled then n=n+1 end end
    return n
end
function tg_pm_config(tab, label)
    local p={}
    local function add(k,v)
        if v ~= nil and tostring(v) ~= "" then p[#p+1]=k .. "=" .. tostring(v) end
    end
    local course=tg_pm_label(label)
    if tab=="Lab" then
        if tostring(label):find("##air",1,true) then course="Air Race"
        elseif tostring(label):find("##park",1,true) then course="Stunt Park"
        elseif tostring(label):find("##arena",1,true) then course="Arena Gauntlet" end
    end
    add("course",course)
    if course=="RANDOM" then add("selection","Random All") end
    if tab=="Games" or tg_pm_label(label):lower():find("game",1,true) then
        local mode=tg_pm_label(label):gsub("^Start Game:%s*",""):gsub("^Minigame:%s*","")
        if mode=="START GAME" and TG_AR and TG_AR_GAMES and TG_AR_GAMES[TG_AR.sel] then
            mode=TG_AR_GAMES[TG_AR.sel].name or TG_AR.sel
        end
        add("mode",mode)
    elseif tab=="Tubes" then
        local s=TG_TUBER_SEL or {}
        add("style",tg_pm_lookup(TG_TUBER_TYPES,s.style))
        add("size",tg_pm_lookup(TG_TUBER_SIZE_NAMES,s.size,nil))
        add("pieces",tg_pm_lookup(TG_TUBER_PIECES_NAMES,s.pieces,nil))
        add("pieceTypes",s.modmode or "style")
        if s.modmode=="mine" then add("selectedTypes",tg_pm_count_on(s.mods)) end
        add("colour",tg_pm_lookup(TG_PK_COLOUR_NAMES,s.colour,nil))
        if s.colour=="single" then add("colourIndex",s.colour_index) end
        add("oneWay",tg_pm_bool(s.oneway))
        add("acrossMap",tg_pm_bool(s.across))
        add("skin",s.skin)
    elseif tab=="Track" then
        local s=TG_CR or {}
        add("style",tg_pm_lookup(TG_CR_STYLES,s.style))
        add("variant",s.var and s.var[s.style] or "random")
        add("shape",s.shape)
        add("loop",tg_pm_bool(s.loop))
        add("ramp",tg_pm_bool(s.ramp))
        add("jumps",tg_pm_bool(s.jumps))
        add("hills",tg_pm_bool(s.hills))
        add("barriers",tg_pm_bool(s.barriers))
        add("decor",tg_pm_bool(s.decor))
    elseif tab=="Parkour" then
        local s=TG_PK_SEL or {}
        add("style",tg_pm_lookup(TG_PK_STYLES,s.style))
        add("gaps",tg_pm_lookup(TG_PK_DIFFS,s.difficulty))
        add("colour",tg_pm_lookup(TG_PK_COLOUR_NAMES,s.colour,nil))
        if s.colour=="single" then add("colourIndex",s.colour_index) end
        add("respawn",tg_pm_bool(TG_PK_RESPAWN))
    elseif tab=="Hybrid" then
        local s=TG_HY_SEL or {}
        add("mix",tg_pm_lookup(TG_HY_MIXES,s.mix))
        add("length",tg_pm_lookup(TG_HY_LENGTHS,s.length))
        add("gaps",tg_pm_lookup(TG_PK_DIFFS,s.difficulty))
        add("sections",tg_pm_count_on(s.sections))
        add("tubeShapes",tg_pm_count_on(s.shapes))
        add("props",tg_pm_count_on(s.props))
        add("colour",tg_pm_lookup(TG_PK_COLOUR_NAMES,s.colour,nil))
    elseif tab=="Lab" then
        local s=TG_LAB or {}
        add("park",tg_pm_lookup(TG_LAB_PARKS,s.park))
        add("altitude",s.air_alt)
        add("animation",tg_pm_bool(s.animate))
    elseif tab=="Saved" then
        local i=TG_TRACK_SAVE_SELECTED_INDEX or 1
        if tg_pm_label(label):lower():find("load",1,true) then
            add("file",TG_TRACK_SAVE_NAMES and TG_TRACK_SAVE_NAMES[i] or "none")
        else
            add("currentObjects",objects and #objects or 0)
        end
    elseif tab=="Home" then
        add("preset",tg_pm_label(label))
    end
    add("objectLimit",tg_pm_limit(tab))
    add("radius",tg_pm_radius(tab))
    return table.concat(p," | ")
end
function tg_pm_kind(tab,label)
    label=tg_pm_label(label)
    local l=label:lower()
    if (l:find("start game",1,true)==1 or l:find("minigame:",1,true)==1 or
        (tab=="Games" and l:find("play",1,true)==1)) then return "GAME_SUMMARY" end
    if (tab=="Saved" or tab=="Home") and (l:find("save current",1,true)==1 or l:find("load selected",1,true)==1) then
        return "SAVE_SUMMARY"
    end
    if tab=="Home" and (l:find("smart random loop",1,true)==1 or l:find("planned loop",1,true)==1) then
        return "BUILD_SUMMARY"
    end
    if tab=="Tubes" or tab=="Track" or tab=="Parkour" or tab=="Hybrid" or tab=="Lab" or tab=="Home" then
        if l:find("build",1,true)==1 or l:find("random",1,true)==1 or l:find("generate",1,true)==1 then
            return "BUILD_SUMMARY"
        end
    end
    return nil
end
function tg_pm_emit(kind,what,body)
    if kind=="BUILD_SUMMARY" then kind="BUILD" end
    tg_log("["..kind.."] "..what.." | "..tostring(body or ""))
end
function tg_pm_begin(kind,tab,label)
    TG_PM_LOG_SEQUENCE=(TG_PM_LOG_SEQUENCE or 0)+1
    local ctx={id=TG_PM_LOG_SEQUENCE,kind=kind,tab=tab,label=tg_pm_label(label),done=false,
        started=util.current_time_millis() or 0,
        originalCount=objects and #objects or 0, originalBudget=TG_RS_BUILD}
    TG_PM_LOG_CONTEXT=ctx
    if kind=="BUILD_SUMMARY" and tg_tt_log_start then
        local line=tg_tt_log_start(tab,label)
        if line then ctx.tt_type=line:match("^Type=(.-) |"); tg_pm_emit(kind,"START",line); return ctx end
    end
    tg_pm_emit(kind,"START", "tab="..tostring(tab).." | "..tg_pm_config(tab,label))
    return ctx
end
function tg_pm_finish(ctx,status,msg)
    if not ctx or ctx.done then return end
    ctx.done=true
    local b=(TG_RS_BUILD ~= ctx.originalBudget) and (TG_RS_BUILD or {}) or {}
    local now=util.current_time_millis() or 0
    local total=objects and #objects or 0
    local parts={"tab="..tostring(ctx.tab),"course="..tostring(ctx.label),"status="..tostring(status or "complete"),
        "objects="..tostring(total)}
    if b.label and b.planned and b.planned>0 then parts[#parts+1]="planned="..tostring(b.planned) end
    if b.label and (b.spawned or 0)>0 then parts[#parts+1]="placed="..tostring(b.spawned) end
    if b.label and (b.failed or 0)>0 then parts[#parts+1]="failed="..tostring(b.failed) end
    if b.full then parts[#parts+1]="objectBudget=FULL" end
    if ctx.tab=="Tubes" and TG_TUBER_LAST then
        parts[#parts+1]="builtStyle="..tg_pm_lookup(TG_TUBER_TYPES,TG_TUBER_LAST)
    elseif ctx.tab=="Parkour" and type(TG_PK_LAST)=="table" and TG_PK_LAST.islands then
        parts[#parts+1]="islands="..tostring(TG_PK_LAST.islands)
    elseif ctx.tab=="Hybrid" and type(TG_HY_LAST)=="table" and type(TG_HY_LAST.counts)=="table" then
        local m=TG_HY_LAST.counts
        parts[#parts+1]=string.format("sections=%d,jumps=%d,tubes=%d",m.sections or 0,m.jumps or 0,m.tubes or 0)
    elseif ctx.tab=="Track" and TG_CR and type(TG_CR.last)=="table" then
        local last=TG_CR.last
        if last.style then parts[#parts+1]="builtStyle="..tostring(last.style) end
        if last.variant then parts[#parts+1]="builtVariant="..tostring(last.variant) end
        if type(last.plans)=="table" then parts[#parts+1]="pieces="..tostring(#last.plans) end
    elseif ctx.tab=="Lab" and TG_LAB and type(TG_LAB.last)=="table" and TG_LAB.last.park then
        parts[#parts+1]="builtPark="..tostring(TG_LAB.last.park)
    end
    if now>ctx.started and ctx.started>0 then parts[#parts+1]="elapsed="..string.format("%.1fs",(now-ctx.started)/1000) end
    if msg and msg~="" then parts[#parts+1]="result="..tostring(msg) end
    if ctx.kind=="BUILD_SUMMARY" and tg_tt_log_end then
        local line=tg_tt_log_end(ctx,status,msg,b,total,now)
        if line then parts={line} end
    end
    tg_pm_emit(ctx.kind,"END",table.concat(parts," | "))
    if TG_PM_LOG_CONTEXT==ctx then TG_PM_LOG_CONTEXT=nil end
end
if tg_rs_progress_done and not TG_PM_PROGRESS_LOG_HOOK then
    TG_PM_PROGRESS_LOG_HOOK=true
    local before=tg_rs_progress_done
    tg_rs_progress_done=function(msg)
        local rv=before(msg)
        local ctx=TG_PM_LOG_CONTEXT
        if ctx then
            local b=(TG_RS_BUILD ~= ctx.originalBudget) and (TG_RS_BUILD or {}) or {}
            tg_pm_finish(ctx,b.full and "budget-full" or "complete",msg)
        end
        return rv
    end
end
if tg_rs_progress_fail and not TG_PM_PROGRESS_FAIL_HOOK then
    TG_PM_PROGRESS_FAIL_HOOK=true
    local before=tg_rs_progress_fail
    tg_rs_progress_fail=function(msg)
        local rv=before(msg)
        local ctx=TG_PM_LOG_CONTEXT
        if ctx then tg_pm_finish(ctx,"failed",msg) end
        return rv
    end
end
if tg_ui_queue_action and not TG_PM_UI_LOG_HOOK then
    TG_PM_UI_LOG_HOOK=true
    local before=tg_ui_queue_action
    tg_ui_queue_action=function(label,cb)
        local tab=(TG_RS_NEXT_TAB or TG_UI_ACTIVE_TAB or "Home")
        local kind=tg_pm_kind(tab,label)
        if kind and type(cb)=="function" then
            local orig=cb
            cb=function(...)
                local ctx=tg_pm_begin(kind,tab,label)
                local r=orig(...)
                if tg_rs_cancelled() then
                    tg_pm_finish(ctx,"cancelled","stopped by Clear Track")
                    return r
                end
                -- Creator and Stunt Park enqueue planning into a separate script job.
                -- Their progress callbacks, not this outer click, report completion.
                local async=(tab=="Track" or (tab=="Lab" and ctx.label:lower():find("stunt park",1,true)))
                local p=TG_RS_PROG or {}
                if not ctx.done and not async and p.done_at and p.done_at>=ctx.started then
                    tg_pm_finish(ctx,p.failed and "failed" or "complete",p.msg)
                elseif not ctx.done and not async and not p.queued then
                    -- Synchronous games, save/load and local builders need a receipt even
                    -- if they did not use the shared progress HUD.
                    tg_pm_finish(ctx,r==false and "failed" or "complete",nil)
                end
                return r
            end
        end
        return before(label,cb)
    end
end

