TG_TT_DEF_BY = {}
function tg_tt_index_defs()
    for kind, list in pairs(TG_TT_DEFS) do
        TG_TT_DEF_BY[kind] = {}
        for _, d in ipairs(list) do TG_TT_DEF_BY[kind][d.id] = d end
    end
end
tg_tt_index_defs()

-- tube module -> tuner group
TG_TT_MODGROUP = {
    loop = "loop", loopr = "loop", dloop = "loop", bigloop = "loop", cobra = "loop",
    helixup = "spiral", helixdn = "spiral", spiral = "spiral", wideul = "spiral", wideur = "spiral",
    cork = "cork", corkr = "cork", barrel = "cork",
    sbendl = "snake", sbendr = "snake", zigzag = "snake", chicl = "snake", chicr = "snake",
    sweepl = "snake", sweepr = "snake", wave = "snake", kink = "snake", longsweep = "snake",
    twist = "twist", diags = "twist", diags2 = "twist", knot = "twist", pretzel = "twist", bankl = "twist", bankr = "twist",
    climb = "climb", stepup = "climb", sclimb = "climb", climbturn = "climb", hump = "climb", camel = "climb",
    drop = "drop", stepdn = "drop", dropturn = "drop", dip = "drop",
    hairl = "curve", hairr = "curve", cornl = "curve", cornr = "curve",
    tunnel = "straight", longtunnel = "straight",
    overpass = "overpass",
}
TG_TT_SHARE_GROUPS = { "loop", "spiral", "cork", "snake", "twist", "straight", "curve" }
TG_TT_INJECT = {
    loop = { "loop", "dloop", "bigloop", "cobra" },
    spiral = { "helixup", "helixdn", "spiral", "wideul" },
    cork = { "cork", "corkr", "barrel" },
    snake = { "sbendl", "zigzag", "chicl", "sweepl", "wave", "kink" },
    twist = { "twist", "diags", "knot", "bankl" },
    straight = { "tunnel", "longtunnel" },
    curve = { "hairl", "cornl" },
    overpass = { "overpass" },
}

function tg_tt_tube_group(e)
    local id = e[3]
    if type(id) == "string" then
        id = id:gsub("_m$", "")
        return TG_TT_MODGROUP[id] or "other"
    end
    local steps = e[1]
    if type(steps) ~= "table" or #steps ~= 1 then return "other" end
    local pc = TG_TUBEP_PIECES and TG_TUBEP_PIECES[steps[1][1]]
    if not pc then return "other" end
    if pc.kind == "straight" then return "straight" end
    if steps[1][2] == "wdiag" then return "twist" end
    return "curve"
end

-- ---------------------------------------------------------------- course keys / presets
function tg_tt_default_allowed()
    local a = {}
    for k in pairs(TG_TUBER_DEFAULT_KEYS or {}) do a[k] = true end
    return a
end
TG_TT_TUBE_INFO = TG_TT_TUBE_INFO or {}
function tg_tt_tube_info(style)
    if not style or style == "random" then return nil end
    local rt = TG_TUBER_TYPES and TG_TUBER_TYPES[style]
    if not rt then return nil end
    local c = TG_TT_TUBE_INFO[style]
    if c then return c end
    local rules = (TG_TT_ORIG_RULES or tg_tr_build_rules)(rt, rt.family, tg_tt_default_allowed(), nil, nil)
    local W, tot = {}, 0.0
    for _, e in ipairs(rules.menu or {}) do
        local g = tg_tt_tube_group(e)
        W[g] = (W[g] or 0.0) + (e[2] or 0.0)
        tot = tot + (e[2] or 0.0)
    end
    local share = {}
    for _, g in ipairs(TG_TT_SHARE_GROUPS) do share[g] = (tot > 0) and tg_tt_round(100.0 * (W[g] or 0.0) / tot) or 0 end
    local fam = (TG_TUBER_FAMILIES and TG_TUBER_FAMILIES[rt.family or "std"]) or { scale = 1.0 }
    local sc = fam.scale or 1.0
    local P = {
        curve = share.curve, straight = share.straight, steep = 50, smooth = 50, sizevar = 0,
        height = tg_tt_clamp(tg_tt_round(320.0 * math.max(1.0, math.min(sc * 0.6, 2.0))), 20, 500),
        loop = share.loop, maxloops = 10, spiral = share.spiral, cork = share.cork, snake = share.snake, twist = share.twist,
        wrap = 0, objwrap = 0, maxwraps = 3, wrapdist = 15, near = 0, weave = 0, sky = 0,
        ovcount = 0, ovheight = 30, climb = 50, drop = 50, random = 50,
    }
    c = { kind = "tubes", style = style, name = rt.name or style, preset = P, share = share, weights = W, total = tot,
          avail = { sizevar = false, objwrap = false },
          reason = { sizevar = "Tube sizes don't join together - pick one Size above.",
                     objwrap = "Height data sees buildings and terrain only - props can't be targeted." } }
    TG_TT_TUBE_INFO[style] = c
    return c
end

function tg_tt_track_mode(cat)
    local st = TG_CR_STYLES and TG_CR_STYLES[cat]
    if not st then return nil end
    if st.loop or (TG_CR and TG_CR.loop and cat ~= "hybrid") then return "loop" end
    return "sprint"
end
-- feature weight defaults used by tg_cr_features (road family)
function tg_tt_feat_w(F, key, drift)
    local base = ({ chic = drift and 0 or 3, s15 = 3, s5 = 2, s30 = 2, esses = drift and 3 or 0, kick = drift and 2 or 0, hill = drift and 0 or 3, jump = 0 })[key] or 0
    local v = F and F[key]
    if v == nil then return base end
    return v
end
function tg_tt_loop_turns(shape)
    if shape == "oval" then return { 180 } elseif shape == "rect" then return { 90 } elseif shape == "hex" then return { 60 }
    elseif shape == "oct" then return { 45 } end
    return { 180, 90, 60, 45 }
end
function tg_tt_track_info(cat, vid)
    local st = TG_CR_STYLES and TG_CR_STYLES[cat]
    if not st or cat == "wipeout" or cat == "hybrid" or not vid or vid == "random" then return nil end
    if not (TG_CR_VARIANTS and TG_CR_VARIANTS[cat]) then return nil end
    local V = tg_cr_variant(cat, vid)
    if type(V) ~= "table" or V.id ~= vid then return nil end
    local mode = tg_tt_track_mode(cat)
    local fam, drift = st.fam, st.drift == true
    local loop = (mode == "loop")
    local sl = ({ long = 75, mixed = 50, short = 25 })[V.straight or "mixed"] or 50
    local P = {
        sharp = 5, smooth = 50, maxh = tg_tt_clamp(tg_tt_round(V.hmax or st.hmax or 120), 10, 300),
        hill = loop and 50 or tg_tt_clamp(tg_tt_round(50 * (V.updown or 1.0)), 0, 100),
        incline = 30, scurve = 50, hairpin = loop and 50 or tg_tt_clamp(tg_tt_round(50 * (V.hair or 1.0)), 0, 100),
        drift = 50, snake = 50, bwrap = 0, ovcount = 0, ovclear = 30, straight = sl,
        turnfreq = tg_tt_clamp(tg_tt_round(50 * (V.twist or 1.0)), 0, 100),
        slen = ({ long = 7, mixed = 4, short = 2 })[V.straight or "mixed"] or 4,
        closure = 0, sym = 0, variety = 50,
        complexity = loop and tg_tt_clamp(tg_tt_round(100 * (V.feat_p or (drift and 0.5 or 0.3))), 0, 100) or 50,
        random = 50,
    }
    if loop and fam == "road" then
        local S, T = 0, 0
        for _, k in ipairs({ "chic", "s15", "s5", "s30", "esses", "kick", "hill", "jump" }) do
            local w = tg_tt_feat_w(V.feats, k, drift)
            T = T + w
            if k == "s5" or k == "s15" or k == "s30" or k == "esses" then S = S + w end
        end
        P.scurve = (T > 0) and tg_tt_round(100 * S / T) or 0
    end
    local A, R = {}, {}
    local function off(id, why) A[id] = false; R[id] = why end
    if loop then
        off("turnfreq", "Loop corners are set by the loop shape.")
        off("maxh", "Loops stay near the ground - use Hill Bias / Maximum Incline.")
        off("bwrap", "Loops are a fixed shape - they can't bend round buildings.")
        off("ovcount", "Loops don't cross themselves."); off("ovclear", "Loops don't cross themselves.")
        off("closure", "Loops always close.")
        off("random", "Loop pieces are already drawn at random.")
        if fam ~= "road" then
            off("scurve", "Sky loop features are fixed - road loops only.")
            off("snake", "Sky loop features are fixed - road loops only.")
            off("drift", "Road loops only.")
            off("variety", "Sky loop features are fixed - road loops only.")
        end
        if drift then off("snake", "Drift loops have no chicanes.") end
        if drift then off("hill", "Drift loops are flat by design.") elseif not (TG_CR and TG_CR.hills) then off("hill", "Turn on Hills below.") end
        local shape = (TG_CR and TG_CR.shape ~= "auto" and TG_CR.shape) or V.shape or "auto"
        local turns = tg_tt_loop_turns(shape)
        local cfam = drift and "drift" or fam
        local multi, has180 = false, false
        for _, t in ipairs(turns) do
            local sets = (TG_CR_CORNERS[cfam] and TG_CR_CORNERS[cfam][t]) or (TG_CR_CORNERS[fam] and TG_CR_CORNERS[fam][t]) or {}
            if #sets > 1 then multi = true end
            if t == 180 then has180 = true end
        end
        if not multi then off("sharp", "This loop shape has one corner type."); off("smooth", "This loop shape has one corner type.") end
        if not has180 then off("hairpin", "Hairpins are the ends of Oval loops - pick Oval shape.") end
    else
        off("sym", "Symmetry applies to loops only.")
        if fam ~= "road" then off("drift", "Road courses only.") end
        if TG_CR and (TG_CR.oneway or TG_CR.across) then off("closure", "One Way / Across Map is on.") end
    end
    return { kind = "track", cat = cat, vid = vid, V = V, st = st, mode = mode, fam = fam, drift = drift,
             name = tostring(st.name) .. " / " .. tostring(V.name or vid), preset = P, avail = A, reason = R }
end

-- course key + info for the current UI selection
function tg_tt_course(kind, a, b)
    if kind == "parkour" then
        local info = tg_tt_parkour_info(a)
        if not info then return nil, nil, "Pick a course type to tune (Random has no fixed preset)." end
        return "parkour:" .. a, info
    end
    if kind == "hybrid" then
        local info = tg_tt_hybrid_info(a)
        if not info then return nil, nil, "Pick Balanced, Tube Heavy, Parkour Heavy, Prop Party or Custom to tune (Random mixes have no fixed preset)." end
        return "hybrid:" .. a, info
    end
    if kind == "tubes" then
        local info = tg_tt_tube_info(a)
        if not info then return nil, nil, "Pick a course style to tune (Random has no fixed preset)." end
        return "tubes:" .. a, info
    end
    local info = tg_tt_track_info(a, b)
    if not info then
        if a == "wipeout" or a == "hybrid" or a == "random" then return nil, nil, "Tuner covers Circuit, Drift, Stunt, Sky, Sky Loop, Wide Sky and Downhill." end
        return nil, nil, "Pick a course style to tune (Random has no fixed preset)."
    end
    return "track:" .. a .. ":" .. b, info
end
function tg_tt_vals(kind, ck, info)
    local v, custom = {}, false
    local st = TG_TT.store[ck] or {}
    for _, d in ipairs(TG_TT_DEFS[kind]) do
        local p = info.preset[d.id] or d.lo
        local x = st[d.id]
        if x ~= nil and info.avail[d.id] ~= false then
            x = tg_tt_clamp(x, d.lo, d.hi)
            if x ~= p then custom = true end
            v[d.id] = x
        else
            v[d.id] = p
        end
    end
    return v, custom
end
function tg_tt_set(ck, info, id, x)
    local st = TG_TT.store[ck] or {}
    if x == info.preset[id] then st[id] = nil else st[id] = x end
    if next(st) == nil then TG_TT.store[ck] = nil else TG_TT.store[ck] = st end
    tg_tt_dirty()
end

-- ---------------------------------------------------------------- persistence
function tg_tt_path()
    if not tg_tm_prefs_path then return nil end
    local _, dir = tg_tm_prefs_path()
    if not dir then return nil end
    return dir .. "\\tuner_settings.cfg", dir
end
function tg_tt_load()
    if TG_TT.loaded then return end
    TG_TT.loaded = true
    local path = tg_tt_path()
    if not path then return end
    local raw = tg_file_read(path)
    if type(raw) ~= "string" or #raw > 262144 then return end
    local n = 0
    for line in raw:gmatch("[^\r\n]+") do
        local ck, id, val
        local s1, i1, v1 = line:match("^tubes:([%w_]+):([%w_]+)=(%-?%d+)$")
        if s1 then ck, id, val = "tubes:" .. s1, i1, v1
            if not TG_TT_DEF_BY.tubes[id] then ck = nil end
        else
            local c2, s2, i2, v2 = line:match("^track:([%w_]+):([%w_]+):([%w_]+)=(%-?%d+)$")
            if c2 then
                ck, id, val = "track:" .. c2 .. ":" .. s2, i2, v2
                if not TG_TT_DEF_BY.track[id] then ck = nil end
            end
        end
        if not s1 and not ck then
            local k3, s3, i3, v3 = line:match("^(%a+):([%w_]+):([%w_]+)=(%-?%d+)$")
            if (k3 == "parkour" or k3 == "hybrid") and TG_TT_DEF_BY[k3] and TG_TT_DEF_BY[k3][i3] then ck, id, val = k3 .. ":" .. s3, i3, v3 end
        end
        if ck and n < 20000 then
            local kk = ck:match("^(%a+):")
            local d = TG_TT_DEF_BY[kk][id]
            TG_TT.store[ck] = TG_TT.store[ck] or {}
            TG_TT.store[ck][id] = tg_tt_clamp(tonumber(val), d.lo, d.hi)
            n = n + 1
        end
    end
end
function tg_tt_save()
    local path, dir = tg_tt_path()
    if not path then return false end
    local lines = { "format=trackmatic_tuner_v1" }
    local keys = {}
    for ck in pairs(TG_TT.store) do keys[#keys + 1] = ck end
    table.sort(keys)
    for _, ck in ipairs(keys) do
        local ids = {}
        for id in pairs(TG_TT.store[ck]) do ids[#ids + 1] = id end
        table.sort(ids)
        for _, id in ipairs(ids) do lines[#lines + 1] = ck .. ":" .. id .. "=" .. tostring(math.floor(TG_TT.store[ck][id])) end
    end
    lines[#lines + 1] = ""
    local data = table.concat(lines, "\n")
    FileMgr.CreateDir(dir)
    local ok_write = tg_file_write(path, data)
    if ok_write then TG_TT.dirty = false end
    return ok_write
end
function tg_tt_dirty() TG_TT.dirty = true; TG_TT.changed_at = tg_tt_now() end
function tg_tt_flush(force)
    if not TG_TT.dirty then return end
    if force or tg_tt_now() - (TG_TT.changed_at or 0) >= 800 then tg_tt_save() end
end
tg_tt_load()

-- ---------------------------------------------------------------- tubes: rules + planner hooks
function tg_tt_tube_runtime(v, info, custom)
    local TT = { v = v, custom = custom }
    if not custom then return TT end
    TT.rk = v.random / 50.0
    TT.pitch_ok = 15.0 + (v.steep - 50) * 0.3
    TT.pitch_k = tg_tt_clamp(1.0 + (v.smooth - 50) / 50.0, 0.2, 2.5)
    TT.maxloops = (v.maxloops < 10) and v.maxloops or nil
    TT.hlim = (v.height ~= info.preset.height) and v.height or nil
    if v.climb ~= 50 or v.drop ~= 50 then TT.updn = (v.climb - v.drop) / 100.0 * 0.6; TT.updn_s = (v.climb - v.drop) / 100.0 * 1.5 end
    TT.wrap, TT.near, TT.weave, TT.sky = v.wrap, v.near, v.weave, v.sky
    TT.maxwraps, TT.wrapdist = v.maxwraps, v.wrapdist
    TT.ovn, TT.ovh = v.ovcount, v.ovheight
    TT.env = (v.wrap > 0 or v.near > 0 or v.weave > 0 or v.sky > 0)
    return TT
end
function tg_tt_allowed_flags(allowed)
    if not allowed then return nil end
    local f = {}
    for k in pairs(allowed) do f[k] = true end
    if allowed.gap or allowed.jmp then f.__gapjump = true end
    if allowed.fn1 or allowed.fn2 then f.__fn = true end
    return f
end
function tg_tt_inject(rules, g, weight, pre, allowed)
    local added = {}
    local flags = tg_tt_allowed_flags(allowed)
    if g == "loop" and TG_TUBEP_PIECES[pre .. "crn2"] then
        added[#added + 1] = { { { pre .. "s", 0 }, { pre .. "crn", 90 }, { pre .. "crn", 90 }, { pre .. "crn2", 0 }, { pre .. "crn2", 180 }, { pre .. "crn", 90 }, { pre .. "crn", 90 } }, 1, "loop" }
    end
    for _, id in ipairs(TG_TT_INJECT[g] or {}) do
        local mod = TG_TUBE_MODULE_BY_ID and TG_TUBE_MODULE_BY_ID[id]
        if mod and tg_tm_template then
            local a = tg_tm_template(mod, pre, flags, false)
            local b = tg_tm_template(mod, pre, flags, true)
            if a then added[#added + 1] = { a, 1, id } end
            if b then added[#added + 1] = { b, 1, id .. "_m" } end
        end
    end
    if g == "straight" then
        for _, k in ipairs({ "xs", "s", "m" }) do if TG_TUBEP_PIECES[pre .. k] then added[#added + 1] = { { { pre .. k, 0 } }, 1 } end end
    elseif g == "curve" then
        for _, k in ipairs({ "crn", "c30", "c15" }) do if TG_TUBEP_PIECES[pre .. k] then added[#added + 1] = { { { pre .. k, "wside" } }, 1 } end end
    elseif g == "twist" then
        for _, k in ipairs({ "crn2", "c30" }) do if TG_TUBEP_PIECES[pre .. k] then added[#added + 1] = { { { pre .. k, "wdiag" } }, 1 } end end
    end
    if #added == 0 then return 0 end
    for _, e in ipairs(added) do
        e[2] = weight / #added
        e.ttg = g
        table.insert(rules.menu, e)
    end
    return weight
end
-- reweight the real menu: changed groups get exactly their slider share of the picks
function tg_tt_apply_tube_rules(rules, TT, info, pre, allowed)
    local v = TT.v
    local W, tot = {}, 0.0
    for _, e in ipairs(rules.menu) do
        e.ttg = e.ttg or tg_tt_tube_group(e)
        W[e.ttg] = (W[e.ttg] or 0.0) + e[2]
        tot = tot + e[2]
    end
    if tot <= 0 then return end
    local changed, sum_s, w_unch = {}, 0.0, tot
    for _, g in ipairs(TG_TT_SHARE_GROUPS) do
        if v[g] ~= info.preset[g] then
            changed[g] = v[g] / 100.0
            sum_s = sum_s + v[g] / 100.0
            w_unch = w_unch - (W[g] or 0.0)
        end
    end
    if next(changed) then
        if sum_s > 0.95 then
            for g, s in pairs(changed) do changed[g] = s * 0.95 / sum_s end
            sum_s = 0.95
        end
        local T2 = (w_unch > 0.001) and (w_unch / (1.0 - sum_s)) or tot
        for g, s in pairs(changed) do
            local want = s * T2
            if (W[g] or 0.0) > 0 then
                local m = want / W[g]
                for _, e in ipairs(rules.menu) do if e.ttg == g then e[2] = e[2] * m end end
            elseif want > 0 then
                tg_tt_inject(rules, g, want, pre, allowed)
            end
        end
    end
    -- climb / drop pieces follow the climb / drop sliders; overpass count adds the overpass piece
    local kc, kd = v.climb / 50.0, v.drop / 50.0
    for _, e in ipairs(rules.menu) do
        if e.ttg == "climb" then e[2] = e[2] * kc elseif e.ttg == "drop" then e[2] = e[2] * kd end
        if e.ttg == "overpass" and v.ovcount > 0 then e[2] = e[2] * (1.0 + v.ovcount * 0.5) end
    end
    if v.ovcount > 0 and (W.overpass or 0) == 0 then tg_tt_inject(rules, "overpass", tot * 0.012 * v.ovcount, pre, allowed) end
    -- smoothness: gentle vs sharp single bends; steepness: vertical bends
    local fs = tg_tt_clamp(1.0 - (v.smooth - 50) / 60.0, 0.15, 2.0)
    local fg = tg_tt_clamp(1.0 + (v.smooth - 50) / 60.0, 0.15, 2.0)
    local fv = tg_tt_clamp(v.steep / 50.0, 0.0, 2.5)
    for _, e in ipairs(rules.menu) do
        local steps = e[1]
        if type(steps) == "table" and #steps == 1 and not e[3] then
            local pc = TG_TUBEP_PIECES[steps[1][1]]
            if pc and pc.kind == "bend" then
                if v.smooth ~= 50 then e[2] = e[2] * (((pc.angle or 90) >= 45) and fs or fg) end
                if v.steep ~= 50 and steps[1][2] == "wvert" then e[2] = e[2] * fv end
            end
        end
    end
    -- never leave an empty menu
    local left = 0.0
    for _, e in ipairs(rules.menu) do left = left + e[2] end
    if left <= 0 then for _, e in ipairs(rules.menu) do e[2] = 1.0 end end
end

function tg_tt_tube_begin(TT, ctx, opts, start)
    TT.ctx = ctx
    if TT.hlim and ctx.floor_z then ctx.ceil_z = ctx.floor_z + TT.hlim end
    TT.env_ok = nil
    if TT.env then
        if TG_WORLD_OBSTACLE_AVOIDANCE == false and not TT.pv then TT.env_ok = false; TT.env_why = "Avoid Buildings is OFF"
        elseif not tg_rs_height then TT.env_ok = false; TT.env_why = "no height data"
        else TT.env_ok = true end
    end
end
function tg_tt_count(plans, key)
    local n = 0
    for _, p in ipairs(plans) do if p.tt_meta and p.tt_meta[key] then n = n + 1 end end
    return n
end
function tg_tt_last_side(plans)
    for i = #plans, math.max(1, #plans - 6), -1 do
        local m = plans[i].tt_meta
        if m and m.side and m.side ~= 0 then return m.side end
    end
    return 0
end
function tg_tt_tube_allow(TT, entry, plans)
    if TT.pv and tg_tt_pv_stale(TT.pv) then return false end
    if TT.maxloops and entry.ttg == "loop" and tg_tt_count(plans, "loop") >= TT.maxloops then return false end
    return true
end
function tg_tt_tube_score(TT, entry, cand, plans, ctx, score, homing)
    local meta = { loop = (entry.ttg == "loop"), g = entry.ttg }
    if not TT.custom then return score, meta end
    local last = cand[#cand]
    local smp = last.samples or {}
    local M = smp[math.max(1, math.floor(#smp / 2))] or last.next.P
    -- climb / drop: prefer candidates that end higher / lower
    if TT.updn_s and not homing then score = score - TT.updn_s * (last.next.P.z - plans[#plans].next.P.z) end
    -- environment: building wrap / near miss / weaving / sky bridge (bounded: <= 7 cached height lookups)
    if TT.env and TT.env_ok then
        -- standard tubes are checked against the height map everywhere; other sizes only near you
        local hm_ok = ctx.heightmap or TT.pv
        if not hm_ok and TG_RS_NEAR and TG_RS_NEAR.P then
            local dx, dy = M.x - TG_RS_NEAR.P.x, M.y - TG_RS_NEAR.P.y
            hm_ok = (dx * dx + dy * dy) < (TG_RS_NEAR.r or 220) ^ 2
        end
        if hm_ok and (ctx.world or TT.pv) then
            local D = last.next.D
            local hl = math.sqrt(D.x * D.x + D.y * D.y)
            local lx, ly = 0.0, 0.0
            if hl > 0.05 then lx, ly = -D.y / hl, D.x / hl end
            local tr = ctx.tube_radius or 7.5
            local safe = tr + (tonumber(TG_WORLD_OBSTACLE_MARGIN or 2.5) or 2.5) + 8.0
            local function tall(side, dist)
                local h = tg_rs_height(M.x + lx * side * dist, M.y + ly * side * dist)
                return h ~= nil and h > M.z - tr * 0.5
            end
            if hl > 0.05 then
                -- too close to a building for the coarse height map: never reward, drop it
                if tall(1, safe) or tall(-1, safe) then return nil, meta end
                if TT.wrap > 0 or TT.weave > 0 then
                    local wd = safe + (TT.wrapdist or 15)
                    local bl, br = tall(1, wd), tall(-1, wd)
                    if bl or br then
                        meta.side = (bl and br) and 0 or (bl and 1 or -1)
                        local D0 = plans[#plans].next.D
                        local cz = D0.x * D.y - D0.y * D.x
                        local turn = (cz > 0.05) and 1 or ((cz < -0.05) and -1 or 0)
                        if TT.wrap > 0 and not homing and turn ~= 0 and (meta.side == 0 or turn == meta.side)
                           and tg_tt_count(plans, "wrap") < (TT.maxwraps or 3) then
                            meta.wrap = true
                            score = score - TT.wrap * 1.2
                        end
                        if TT.weave > 0 and not homing and meta.side ~= 0 and tg_tt_last_side(plans) == -meta.side then score = score - TT.weave * 0.8 end
                    end
                end
                if TT.near > 0 and not homing and (tall(1, safe + 12.0) or tall(-1, safe + 12.0)) then
                    meta.near = true
                    score = score - TT.near * 0.8
                end
            end
            if TT.sky > 0 and not homing then
                local g = tg_rs_height(M.x, M.y)
                if g then score = score - TT.sky * math.min(1.0, math.max(0.0, M.z - g) / 120.0) end
            end
        end
    end
    -- overpass: passes over / under an earlier piece by Overpass Height (fits() keeps the clearance)
    if (TT.ovn or 0) > 0 and not homing and tg_tt_count(plans, "ov") < TT.ovn then
        local H = TT.ovh or 30
        local cl = (ctx.clearance or 24.0) * 0.9
        local cl2 = cl * cl
        local hit = false
        for si = 1, #smp, 2 do
            local q = smp[si]
            for i = 1, #plans - 3 do
                local ps = plans[i].samples or {}
                for j = 1, #ps, 3 do
                    local r = ps[j]
                    local dx, dy = q.x - r.x, q.y - r.y
                    if dx * dx + dy * dy < cl2 and math.abs(q.z - r.z) >= H then hit = true; break end
                end
                if hit then break end
            end
            if hit then break end
        end
        if hit then meta.ov = true; score = score - 150.0 end
    end
    return score, meta
end
function tg_tt_tube_stats(plans, start)
    local s = { pieces = #plans, loops = 0, wraps = 0, near = 0, ov = 0, maxh = 0 }
    local z0 = (start and start.P and start.P.z) or ((plans[1] and plans[1].next and plans[1].next.P.z) or 0)
    for _, p in ipairs(plans) do
        local m = p.tt_meta
        if m then
            if m.loop then s.loops = s.loops + 1 end
            if m.wrap then s.wraps = s.wraps + 1 end
            if m.near then s.near = s.near + 1 end
            if m.ov then s.ov = s.ov + 1 end
        end
        if p.next and p.next.P then s.maxh = math.max(s.maxh, p.next.P.z - z0) end
    end
    return s
end

-- rules wrapper: classify every entry, attach the tuner; reweight only when customised
TG_TT_ORIG_RULES = TG_TT_ORIG_RULES or tg_tr_build_rules
function tg_tr_build_rules(rt, fam_key, allowed, loops, modset)
    local rules = TG_TT_ORIG_RULES(rt, fam_key, allowed, loops, modset)
    tg_tt_attach_tube_rules(rules, rt, fam_key, allowed)
    return rules
end
function tg_tt_attach_tube_rules(rules, rt, fam_key, allowed)
    for _, e in ipairs(rules.menu) do e.ttg = tg_tt_tube_group(e) end
    local style = nil
    for k, v in pairs(TG_TUBER_TYPES or {}) do if v == rt then style = k; break end end
    local info = style and tg_tt_tube_info(style)
    if not info then return end
    local v, custom = tg_tt_vals("tubes", "tubes:" .. style, info)
    local TT = tg_tt_tube_runtime(v, info, custom)
    TT.style = style
    if custom then
        local fam = (TG_TUBER_FAMILIES and TG_TUBER_FAMILIES[fam_key or rt.family]) or {}
        tg_tt_apply_tube_rules(rules, TT, info, fam.prefix or "", allowed)
    end
    rules.tt = TT
    TG_TT_BUILD = { kind = "tubes", style = style, v = v, custom = custom, info = info, stats = nil }
end
TG_TT_ORIG_VSIGN = TG_TT_ORIG_VSIGN or tg_tco_vertical_sign
function tg_tco_vertical_sign(state)
    local ctx = TG_TCO_CTX
    local TT = ctx and ctx.tt
    if not (TT and TT.updn) then return TG_TT_ORIG_VSIGN(state) end
    local pitch = math.deg(math.asin(math.max(-1.0, math.min(1.0, state.D.z))))
    if pitch > 12.0 then return -1.0 end
    if pitch < -12.0 then return 1.0 end
    local up = 0.5
    if ctx.floor_z and ctx.ceil_z then
        local h = (state.P.z - ctx.floor_z) / math.max(1.0, ctx.ceil_z - ctx.floor_z)
        up = 0.75 - h * 1.1
    end
    up = tg_tt_clamp(up + TT.updn, 0.05, 0.95)
    return (math.random() < up) and 1.0 or -1.0
end
TG_TT_ORIG_PLAN = TG_TT_ORIG_PLAN or tg_tco_plan_course
function tg_tco_plan_course(start, rules, ctx, opts)
    local plans, why = TG_TT_ORIG_PLAN(start, rules, ctx, opts)
    if plans and rules and rules.tt and not rules.tt.pv and TG_TT_BUILD and TG_TT_BUILD.kind == "tubes" then
        TG_TT_BUILD.stats = tg_tt_tube_stats(plans, start)
    end
    return plans, why
end

-- ---------------------------------------------------------------- track: style overlay + scoring hooks
function tg_tt_track_overlay(info, v, custom, pv)
    local V = info.V
    local O = {}
    for k, x in pairs(V) do O[k] = x end
    local tt = { mode = info.mode, custom = custom, pv = pv, d = {} }
    O.tt = tt
    if not custom then return O end
    local P = info.preset
    local function ch(id) return v[id] ~= P[id] and info.avail[id] ~= false end
    local function ratio(id, base)
        if P[id] > 0 then return (base or 1.0) * v[id] / P[id] end
        return v[id] / 50.0
    end
    if ch("slen") then O.straight = (v.slen >= 6) and "long" or ((v.slen <= 3) and "short" or "mixed") end
    tt.incline = ch("incline") and v.incline or nil
    if info.mode == "sprint" then
        if ch("turnfreq") then O.twist = ratio("turnfreq", V.twist or 1.0) end
        if ch("hill") then O.updown = ratio("hill", V.updown or 1.0) end
        if ch("hairpin") then O.hair = math.max(0.05, ratio("hairpin", V.hair or 1.0)) end
        if ch("maxh") then O.hmax = v.maxh end
        if ch("complexity") then O.fx = (V.fx or 1.0) * v.complexity / 50.0; O.jumps = (V.jumps or 1.0) * v.complexity / 50.0 end
        local function d(id) return ch(id) and (v[id] - P[id]) / 50.0 or 0.0 end
        tt.d = { straight = d("straight"), smooth = d("smooth"), snake = d("snake"), scurve = d("scurve"), variety = d("variety"),
                 drift = d("drift"), hairpin = d("hairpin"), complexity = d("complexity"), sharp = ch("sharp") and (v.sharp - 5) / 5.0 or 0.0 }
        tt.slen = ch("slen") and v.slen or nil
        tt.rk = ch("random") and v.random / 50.0 or nil
        tt.bwrap = v.bwrap
        tt.ovn, tt.ovc = v.ovcount, v.ovclear
        tt.closure = ch("closure") and v.closure or nil
    else
        local fp = V.feat_p or (info.drift and 0.5 or 0.3)
        if ch("complexity") then fp = tg_tt_clamp(v.complexity / 100.0, 0.02, 0.95) end
        if ch("straight") then fp = tg_tt_clamp(fp * (1.0 - (v.straight - P.straight) / 80.0), 0.02, 0.95) end
        if fp ~= (V.feat_p or (info.drift and 0.5 or 0.3)) then O.feat_p = fp; tt.featp_floor = math.min(0.45, fp) end
        if info.fam == "road" then
            local F = {}
            for _, k in ipairs({ "chic", "s15", "s5", "s30", "esses", "kick", "hill", "jump" }) do F[k] = tg_tt_feat_w(V.feats, k, info.drift) end
            local touched = false
            if ch("scurve") then
                touched = true
                if P.scurve > 0 then for _, k in ipairs({ "s5", "s15", "s30", "esses" }) do F[k] = F[k] * v.scurve / P.scurve end
                else F.s15 = v.scurve / 20.0 end
            end
            if ch("snake") then touched = true; F.chic = F.chic * v.snake / 50.0 end
            if ch("drift") and info.drift then touched = true; F.kick = F.kick * v.drift / 50.0 end
            if ch("variety") then
                touched = true
                local e = tg_tt_clamp(1.0 - (v.variety - 50) / 100.0, 0.3, 1.7)
                for k, w in pairs(F) do if w > 0 then F[k] = w ^ e end end
            end
            if touched then O.feats = F end
            if ch("hill") then tt.hill_k = v.hill / 50.0 end
        elseif ch("hill") then
            O.hillw = (V.hillw or 1.0) * v.hill / 50.0
        end
        if tt.incline and O.hills then O.hills = { math.min(O.hills[1] or 0, tt.incline), math.min(O.hills[2] or 0, tt.incline) } end
        if ch("sym") then tt.sym = v.sym end
        tt.sw = { sharp = ch("sharp") and (v.sharp - 5) / 5.0 or 0.0, smooth = ch("smooth") and (v.smooth - 50) / 50.0 or 0.0,
                  hair = ch("hairpin") and (v.hairpin / 50.0) ^ 2 or 1.0, drift = ch("drift") and (v.drift / 50.0) ^ 2 or 1.0 }
        tt.setw_on = (tt.sw.sharp ~= 0 or tt.sw.smooth ~= 0 or tt.sw.hair ~= 1.0 or tt.sw.drift ~= 1.0)
    end
    return O
end
function tg_tt_is_drift_model(m)
    m = tostring(m or "")
    return m:find("l_b", 1, true) ~= nil or m:find("_135", 1, true) ~= nil or m:find("bend_m", 1, true) ~= nil
        or m:find("bend_bar_m", 1, true) ~= nil or (m:find("chicane", 1, true) ~= nil and m:find("_02", 1, true) ~= nil)
end
-- loop corner sets: sharper = fewer pieces per corner, smoother = more
function tg_tt_cr_setw(tt, set)
    local sw = tt.sw or {}
    local n = math.max(1, #set)
    local w = 1.0
    if (sw.sharp or 0) ~= 0 then w = w * n ^ (-sw.sharp) end
    if (sw.smooth or 0) ~= 0 then w = w * n ^ (sw.smooth) end
    local first = tg_cr_item(set[1])
    if (sw.hair or 1.0) ~= 1.0 and tostring(first):find("180d", 1, true) then w = w * math.max(0.02, sw.hair) end
    if (sw.drift or 1.0) ~= 1.0 and tg_tt_is_drift_model(first) then w = w * math.max(0.02, sw.drift) end
    return w
end
function tg_tt_cr_score(tt, state, p, s, score, placed)
    if tt.pv and tg_tt_pv_stale(tt.pv) then return score end
    if not tt.custom or tt.mode ~= "sprint" then return score end
    local d = tt.d or {}
    local pc = TG_CR_P[p.model]
    local turn = (p.rev and -1 or 1) * ((pc and pc.turn) or 0)
    local at = math.abs(turn)
    local k = p.k
    if state.tt_n ~= state.n then
        state.tt_n = state.n
        local lm = state.last_model and TG_CR_P[state.last_model]
        state.tt_run = (lm and lm.k == "straight") and ((state.tt_run or 0) + 1) or 0
    end
    if (d.straight or 0) ~= 0 and k == "straight" then score = score + d.straight * 0.8 end
    if tt.slen and k == "straight" then
        local run = state.tt_run or 0
        if run < tt.slen then score = score + 0.5 else score = score - 0.8 * (run - tt.slen + 1) end
    end
    if at > 1 then
        local sgn = (turn > 0) and 1 or -1
        local alt = state.last_turn_sign and state.last_turn_sign ~= sgn
        if (d.sharp or 0) ~= 0 then score = score + d.sharp * (math.min(at, 180) / 90.0 - 0.5) end
        if (d.smooth or 0) ~= 0 then score = score - d.smooth * 0.6 * math.min(2.0, at / 90.0) end
        if (d.snake or 0) ~= 0 and alt then score = score + d.snake * 0.7 end
        if (d.scurve or 0) ~= 0 and at <= 31 and alt then score = score + d.scurve * 0.8 end
        if (d.drift or 0) ~= 0 and tg_tt_is_drift_model(p.model) then score = score + d.drift * 1.2 end
        if (d.hairpin or 0) ~= 0 and at > 170 then score = score + d.hairpin * 1.0 end
    end
    if (d.complexity or 0) ~= 0 and k ~= "straight" then score = score + d.complexity * 0.5 end
    local pitch = math.abs(tg_cr_pitch_of(p.next.R))
    if tt.incline and pitch > tt.incline + 0.5 then score = score - 3.0 - (pitch - tt.incline) * 0.3 end
    if (d.smooth or 0) > 0 and pitch > 1.0 then score = score - d.smooth * pitch * 0.02 end
    if (d.variety or 0) ~= 0 and p.model == state.last_model then score = score - d.variety * 0.6 end
    if tt.closure and state.returning and state.goal then
        local to = tg_cr_flat(tg_tp_sub(state.goal, p.next.P))
        local f = tg_cr_flat(p.next.R.X)
        if tg_tp_len(to) > 1 and tg_tp_len(f) > 0.1 then score = score + (tt.closure / 100.0) * tg_tp_dot(tg_tp_norm(to), tg_tp_norm(f)) end
    end
    -- building wrap: run alongside buildings (bounded: 4 cached height lookups)
    if (tt.bwrap or 0) > 0 and tg_rs_height and (TG_WORLD_OBSTACLE_AVOIDANCE ~= false or tt.pv) then
        local P = p.next.P
        local Y = p.next.R.Y
        local hl = math.sqrt(Y.x * Y.x + Y.y * Y.y)
        if hl > 0.05 then
            local yx, yy = Y.x / hl, Y.y / hl
            local half = (p.w or 12.0) * 0.5 + (tonumber(TG_WORLD_OBSTACLE_MARGIN or 2.5) or 2.5)
            local function tall(side, dist)
                local h = tg_rs_height(P.x + yx * side * dist, P.y + yy * side * dist)
                return h ~= nil and h > P.z + 3.0
            end
            if tall(1, half + 4.0) or tall(-1, half + 4.0) then score = score - 6.0
            elseif tall(1, half + 14.0) or tall(-1, half + 14.0) then p.tt_wrap = true; score = score + tt.bwrap / 100.0 * 1.5 end
        end
    end
    -- overpass: crossing over / under an earlier deck (tg_cr_clear keeps decks apart)
    if (tt.ovn or 0) > 0 and type(placed) == "table" then
        local n = 0
        for _, q in ipairs(placed) do if q.tt_ov then n = n + 1 end end
        if n < tt.ovn then
            local H = tt.ovc or 30
            local hit = false
            local ps = p.samples or {}
            for i = 1, #ps, 2 do
                local a = ps[i]
                for j = 1, #placed - 3 do
                    local q = placed[j]
                    local lim = ((q.w or 12) + (p.w or 12)) * 0.5
                    for jj = 1, #(q.samples or {}), 2 do
                        local b = q.samples[jj]
                        local dx, dy = a.x - b.x, a.y - b.y
                        if dx * dx + dy * dy < lim * lim and math.abs(a.z - b.z) >= H then hit = true; break end
                    end
                    if hit then break end
                end
                if hit then break end
            end
            if hit then p.tt_ov = true; score = score + 2.5 end
        end
    end
    return score
end
-- remember the list each candidate is checked against (read at the top of the scorer)
TG_TT_ORIG_CR_CLEAR = TG_TT_ORIG_CR_CLEAR or tg_cr_clear
function tg_cr_clear(plan, placed, skip_arc)
    TG_TT_CR_LASTPLACED = placed
    return TG_TT_ORIG_CR_CLEAR(plan, placed, skip_arc)
end
-- the build resolves its style through here: attach the tuned style (customised Course Types only)
TG_TT_ORIG_CR_RESOLVE = TG_TT_ORIG_CR_RESOLVE or tg_cr_resolve
function tg_cr_resolve(cat_in)
    local cat, V = TG_TT_ORIG_CR_RESOLVE(cat_in)
    TG_TT_BUILD = nil
    return cat, tg_tt_cr_overlay(cat_in, cat, V) or V
end
-- the tuned course style (nil when this Course Type isn't customised)
function tg_tt_cr_overlay(cat_in, cat, V)
    if cat_in ~= cat or type(V) ~= "table" then return nil end
    local sel = (TG_CR and TG_CR.var or {})[cat]
    if not sel or sel ~= V.id then return nil end
    local info = tg_tt_track_info(cat, V.id)
    if not info then return nil end
    local v, custom = tg_tt_vals("track", "track:" .. cat .. ":" .. V.id, info)
    TG_TT_BUILD = { kind = "track", cat = cat, vid = V.id, v = v, custom = custom, info = info }
    return tg_tt_track_overlay(info, v, custom, nil)
end
TG_TT_ORIG_CR_SPRINT = TG_TT_ORIG_CR_SPRINT or tg_cr_plan_sprint
function tg_cr_plan_sprint(S, budget, sock0, home, label)
    local tt = S and S.V and S.V.tt
    if tt and tt.closure and not S.return_home and not (TG_CR and (TG_CR.oneway or TG_CR.across)) then
        S.return_home = (math.random() * 100.0 < tt.closure)
    end
    return TG_TT_ORIG_CR_SPRINT(S, budget, sock0, home, label)
end

-- ---------------------------------------------------------------- live preview (queued job, memory only)
-- a build is "busy" only while it is really working: the progress HUD flags can stay set after a
-- build ends (v2.4.1 waited forever), so they only count while they were touched in the last 8 s
function tg_tt_busy()
    local now = tg_tt_now()
    local p = TG_RS_PROG
    if p and (p.active == true or p.queued) and not p.done_at and (now - (tonumber(p.touched) or 0)) < 8000 then return true end
    if TG_CR_IN_JOB == true and (now - (TG_TT_CR_JOB_T or now)) < 120000 then return true end
    return (now - (TG_TT_BUILD_T or 0)) < 3000
end
-- a build that starts makes any running preview give way at its next step
TG_TT_ORIG_BUILD_START = TG_TT_ORIG_BUILD_START or tg_rs_build_start
function tg_rs_build_start(label)
    TG_TT_BUILD_T = tg_tt_now()
    if TG_CR_IN_JOB then TG_TT_CR_JOB_T = TG_TT_BUILD_T end
    return TG_TT_ORIG_BUILD_START(label)
end
-- the preview job never reacts to (or clears) a build cancel: only the build jobs do.
-- inside a preview job "cancelled" means the preview went stale (a newer request, or a build started)
TG_TT_ORIG_CHECK_CANCEL = TG_TT_ORIG_CHECK_CANCEL or tg_rs_check_cancel
function tg_rs_check_cancel()
    local P = TG_TT_PV
    if P.co and P.co_ok and coroutine.running() == P.co then
        return P.cur_gen ~= nil and tg_tt_pv_stale(P.cur_gen)
    end
    local H = TG_TT_HV
    if H and H.co and H.co_ok and coroutine.running() == H.co then return tg_tt_pv_stale("hover") end
    return TG_TT_ORIG_CHECK_CANCEL()
end
-- true when a preview should give way: a build is busy, or (live preview) a newer request replaced it
function tg_tt_pv_stale(gen)
    if gen == "hover" then return tg_tt_busy() end
    return gen ~= TG_TT_PV.gen or tg_tt_busy()
end
TG_TT_TRICK_GROUPS = { spiral = true, cork = true, twist = true, snake = true }
function tg_tt_meta_tag(m)
    if not m then return nil end
    if m.ov then return "overpass" end
    if m.wrap then return "wrap" end
    if m.near then return "near" end
    if m.loop or m.g == "loop" then return "loop" end
    if TG_TT_TRICK_GROUPS[m.g or ""] then return "trick" end
    return nil
end
function tg_tt_pv_points_tubes(plans)
    local pts = {}
    if plans[1] and plans[1].samples and plans[1].samples[1] then
        local q = plans[1].samples[1]; pts[1] = { x = q.x, y = q.y, z = q.z }
    end
    local tag = nil
    for _, p in ipairs(plans) do
        -- the tag sits on an entry's first piece and covers the rest of that entry
        if p.tt_meta then tag = tg_tt_meta_tag(p.tt_meta) elseif p == plans[1] then tag = nil end
        local s = p.samples or {}
        if #s >= 5 then local q = s[math.floor(#s / 2) + 1]; pts[#pts + 1] = { x = q.x, y = q.y, z = q.z, tag = tag } end
        pts[#pts + 1] = { x = p.next.P.x, y = p.next.P.y, z = p.next.P.z, tag = tag }
    end
    return pts
end
function tg_tt_pv_tubes(req)
    local rt = TG_TUBER_TYPES[req.a]
    local fam_key = req.fam
    local fam = TG_TUBER_FAMILIES[fam_key] or TG_TUBER_FAMILIES.std
    local scale = fam.scale or 1.0
    local pre = fam.prefix or ""
    local allowed = tg_tt_default_allowed()
    local rules = TG_TT_ORIG_RULES(rt, fam_key, allowed, nil, nil)
    for _, e in ipairs(rules.menu) do e.ttg = tg_tt_tube_group(e) end
    local TT = tg_tt_tube_runtime(req.v, req.info, req.custom)
    TT.pv = req.gen
    if req.custom then tg_tt_apply_tube_rules(rules, TT, req.info, pre, allowed) end
    rules.tt = TT
    local pos, heading = tg_get_local_position_heading("tuner_preview")
    heading = tonumber(heading or 0.0) or 0.0
    local fx, fy = calculate_new_position({ x = 0.0, y = 0.0, z = 0.0 }, heading, 1.0, 0.0, 0.0)
    local F = tg_tp_norm(tg_tp_v(fx, fy, 0.0))
    local Zw = tg_tp_v(0.0, 0.0, 1.0)
    local L = tg_tp_norm(tg_tp_cross(Zw, F))
    local th = math.rad(TG_TUBER_ENTRY_PITCH or 8.0)
    local ground = pos.z - 1.0
    local lift = ((TG_TUBER_FLOOR_R or 8.74) - (TG_TUBER_ENTRY_SINK or 0.5)) * scale
    local clearance = (TG_TUBEP_CLEARANCE or 24.0) * scale
    local sg = tg_tp_add(tg_tp_v(pos.x, pos.y, ground + lift), tg_tp_mul(F, (TG_TUBER_ENTRY_DIST or 40.0) + (scale - 1.0) * 15.0))
    local eg = tg_tp_add(sg, tg_tp_mul(L, math.max(45.0, clearance * 1.7)))
    local Ds = tg_tp_norm(tg_tp_add(tg_tp_mul(F, math.cos(th)), tg_tp_mul(Zw, math.sin(th))))
    local De = tg_tp_norm(tg_tp_add(tg_tp_mul(F, -math.cos(th)), tg_tp_mul(Zw, -math.sin(th))))
    local Us = tg_tp_norm(tg_tp_sub(Zw, tg_tp_mul(Ds, tg_tp_dot(Zw, Ds))))
    local Ue = tg_tp_norm(tg_tp_sub(Zw, tg_tp_mul(De, tg_tp_dot(Zw, De))))
    local start, home = { P = sg, D = Ds, U = Us }, { P = eg, D = De, U = Ue }
    local ctx = { clearance = clearance, scale = scale, tube_radius = (TG_TUBECO_TUBE_RADIUS or 7.5) * scale,
                  world = false, heightmap = false, open = true }
    ctx.floor_z = math.min(sg.z, eg.z) - 1.5
    ctx.ceil_z = math.max(sg.z, eg.z) + 320.0 * math.max(1.0, math.min(scale * 0.6, 2.0))
    local limit = tg_rs_limit("tubes")
    local tmin, tmax = tg_tr_target_range(rt, fam_key, limit)
    local tuned = (TG_TUBER_SIZE_TARGETS[fam_key] or { 0, 56 })[2]
    local grow = math.max(1.0, math.sqrt(tmax / tuned))
    local opts = { lead = { { pre .. "xs", 0 } }, home = home, approach = 200.0, min = tmin, max = tmax, max_objects = limit - 2,
                   max_radius = (TG_TUBECO_MAX_RADIUS or 700.0) * math.min(scale, 3.7) * ((fam_key == "std") and (rt.radius or 1.0) or 1.0) * grow }
    ctx.ceil_z = ctx.ceil_z + (grow - 1.0) * 160.0 * math.min(scale, 2.0)
    local user_r = tg_rs_radius("tubes") or nil
    if user_r then
        ctx.user_r = user_r; ctx.rc = { x = pos.x, y = pos.y }
        opts.max_radius = math.min(opts.max_radius, math.max(80.0, user_r - 45.0 - 12.0 * scale))
    end
    local plans, why
    for attempt = 1, 3 do
        if tg_tt_pv_stale(req.gen) then return nil, "stale" end
        math.randomseed(req.seed + attempt * 7919)
        plans, why = TG_TT_ORIG_PLAN(start, rules, ctx, opts)
        if plans then break end
        util.yield(0)
    end
    if not plans then return nil, "No valid course at these settings here (" .. tostring(why) .. ")" end
    local st = tg_tt_tube_stats(plans, start)
    local notes = {}
    if TT.env and TT.wrap and TT.wrap > 0 and st.wraps == 0 then notes[#notes + 1] = "No valid building wrap available" end
    if TT.env and TG_WORLD_OBSTACLE_AVOIDANCE == false then notes[#notes + 1] = "Building wrap needs Avoid Buildings ON to build" end
    if (TT.ovn or 0) > 0 and st.ov < TT.ovn then notes[#notes + 1] = string.format("Overpasses %d of %d", st.ov, TT.ovn) end
    return { points = tg_tt_pv_points_tubes(plans), stats = st, notes = notes }
end
-- the track loop description, as the build makes it
function tg_tt_pv_loop_L(cat, st, V)
    local L = { fam = st.fam, drift = st.drift, V = V, shape = (TG_CR.shape ~= "auto" and TG_CR.shape) or V.shape or "auto",
                feat_p = V.feat_p, straight = V.straight, corners = V.corners }
    local hi = (V.hills and V.hills[2]) or 6
    if cat == "circuit" then L.elev = 3; L.elev_k = 2; L.elev_a = math.max(6.0, math.min(9.0, hi + 3))
    elseif cat == "drift" then L.elev = 2; L.elev_a = 5.0; L.elev_k = 2
    elseif cat == "skyloop" or cat == "widesky" then L.elev = ((V.hillw or 1) >= 1.5) and 2 or 1 end
    if L.fam == "road" and not st.drift then
        local f = {}
        for k2, v2 in pairs(V.feats or {}) do f[k2] = v2 end
        f.hill = math.max(f.hill or 0, 4) * 1.5 * ((V.tt and V.tt.hill_k) or 1.0)
        local vv = {}
        for k2, v2 in pairs(V) do vv[k2] = v2 end
        vv.feats = f
        local lo2, hi2 = 4, 8
        if vv.hills then lo2, hi2 = math.max(4, vv.hills[1] or 4), math.max(8, vv.hills[2] or 8) end
        if V.tt and V.tt.incline then lo2, hi2 = math.min(lo2, V.tt.incline), math.min(hi2, V.tt.incline) end
        vv.hills = { lo2, hi2 }
        L.V = vv
        L.feat_p = math.max(L.feat_p or 0.3, (V.tt and V.tt.featp_floor) or 0.45)
    end
    return L
end
function tg_tt_pv_track(req)
    local info = req.info
    local cat, st = info.cat, info.st
    local V = tg_tt_track_overlay(info, req.v, req.custom, req.gen)
    local tt = V.tt
    local pos, heading = tg_get_local_position_heading("tuner_preview")
    heading = tonumber(heading or 0.0) or 0.0
    local fx, fy = calculate_new_position({ x = 0.0, y = 0.0, z = 0.0 }, heading, 1.0, 0.0, 0.0)
    local D = tg_tp_norm(tg_tp_v(fx, fy, 0.0))
    local P0 = tg_tp_add(tg_tp_v(pos.x, pos.y, pos.z - 0.9), tg_tp_mul(D, 14.0))
    local sock = { P = P0, R = { X = D, Y = tg_tp_norm(tg_tp_cross(tg_tp_v(0, 0, 1), D)), Z = tg_tp_v(0, 0, 1) } }
    local limit = tg_rs_limit("creator")
    local budget = TG_CR.decor and math.max(8, math.floor(limit * 0.86)) or limit
    local plans = nil
    if info.mode == "loop" then
        local L = tg_tt_pv_loop_L(cat, st, V)
        for attempt = 1, 8 do
            if tg_tt_pv_stale(req.gen) then return nil, "stale" end
            math.randomseed(req.seed + attempt * 7919)
            local steps = tg_cr_loop_recipe(L, budget, (attempt % 2) == 0)
            if steps then
                local pl, gap, hd = tg_cr_run_steps(sock, steps, true)
                if pl and #pl > 0 and gap < 0.6 and hd < 1.0 then plans = pl; break end
            end
            util.yield(0)
        end
        if not plans then return nil, "No closed loop at these settings" end
    else
        math.randomseed(req.seed)
        local fam = st.fam
        local state = { home = sock.P, radius = 650.0, same_turns = 0, V = V, fam = fam, learned = st.learned,
                        hmin = V.hmin or st.hmin or 0.0, hmax = V.hmax or st.hmax or 120.0,
                        rise = (fam ~= "road") and (V.rise or 4.0) or nil, downhill = st.downhill or V.downhill, n = 0 }
        if TG_CR_RADIUS and TG_CR_RADIUS.r then state.radius = math.min(state.radius, TG_CR_RADIUS.r * 0.55) end
        local ret = tt.closure and not (TG_CR.oneway or TG_CR.across) and (math.random() * 100.0 < tt.closure)
        if st.downhill or V.downhill then
            local cl = V.climb or { 70, 160 }
            state.climb_to = cl[1] + math.random() * math.max(0, (cl[2] or cl[1]) - cl[1])
            state.rise = state.rise or 6.0
        else
            local amp = V.prof_amp or (math.max(20.0, math.min(80.0, (state.hmax or 120.0) * 0.5)) * math.max(0.7, math.min(1.8, (V.updown or 1.0) * 1.3)))
            local per = 7 + math.random(0, 6)
            local base = state.hmin or 0.0
            state.prof_amp = amp
            state.profile = function(n, left)
                if n < 2 then return 0.0 end
                local t = math.max(0.0, base) + state.prof_amp * (0.5 - 0.5 * math.cos(2.0 * math.pi * (n - 2) / per))
                if state.rise and state.rise > 0 then t = math.min(t, state.rise * (n - 1)) end
                if left and left < 8 then t = t * math.max(0.0, (left - 2) / 6.0) end
                return t
            end
            state.hinge = 6.0 + math.random() * 4.0
        end
        state.ref_ground = sock.P.z
        local first = tg_cr_place(sock, TG_CR_START[fam], false, 0, 0)
        if not first then return nil, "Start piece unavailable" end
        plans = { first }
        local s = first.next
        local back = 0
        local t_end = tg_tt_now() + 6000
        while #plans < budget and tg_tt_now() < t_end do
            if tg_tt_pv_stale(req.gen) then return nil, "stale" end
            state.n = #plans
            state.left = budget - #plans
            if ret then
                if not state.returning and #plans >= math.max(8, math.floor(budget * 0.45)) then state.returning = true; state.goal = sock.P end
                if state.returning and tg_tp_len(tg_cr_flat(tg_tp_sub(sock.P, s.P))) < 80.0 and #plans >= 10 then break end
            end
            local scored = {}
            for _, c in ipairs(tg_cr_sprint_candidates(state, s)) do
                local p = tg_cr_place(s, c.m, c.rev, 0, c.hp or 0)
                if p and tg_cr_clear(p, plans) then
                    state.cw = c.w
                    p.k = c.k
                    scored[#scored + 1] = { p = p, sc = tg_cr_score_candidate(state, p, s) }
                end
            end
            table.sort(scored, function(x, y) return x.sc > y.sc end)
            local chosen = nil
            for i = 1, math.min(5, #scored) do
                local c = scored[i]
                local look = tg_cr_place(c.p.next, TG_CR_STRAIGHTS[fam][2], false, 0, 0)
                local tmp = {}
                for j = 1, #plans do tmp[j] = plans[j] end
                tmp[#tmp + 1] = c.p
                if look and tg_cr_clear(look, tmp) then chosen = c.p; break end
            end
            if chosen then
                plans[#plans + 1] = chosen
                s = chosen.next
                local turn = (chosen.rev and -1 or 1) * ((TG_CR_P[chosen.model] and TG_CR_P[chosen.model].turn) or 0)
                if math.abs(turn) > 1 then
                    local sgn = (turn > 0) and 1 or -1
                    if state.last_turn_sign == sgn then state.same_turns = state.same_turns + 1 else state.same_turns = 1 end
                    state.last_turn_sign = sgn
                end
                state.last_model = chosen.model
                if math.abs(tg_cr_pitch_of(chosen.next.R)) > 1.0 then state.tilted = (state.tilted or 0) + 1 else state.tilted = 0 end
                if math.abs(turn) > 170 then state.since_hairpin = 0 else state.since_hairpin = (state.since_hairpin or 99) + 1 end
            else
                back = back + 1
                if back > 25 or #plans <= 2 then break end
                table.remove(plans)
                s = plans[#plans].next
            end
            util.yield(0)
        end
        if #plans < 4 then return nil, "No valid course at these settings" end
    end
    local pts = { { x = plans[1].inP.x, y = plans[1].inP.y, z = plans[1].inP.z } }
    local s = { pieces = #plans, wraps = 0, ov = 0, maxh = 0 }
    local z0 = plans[1].inP.z
    for _, p in ipairs(plans) do
        if p.next and p.next.P then
            local tag = nil
            if p.tt_ov then tag = "overpass" elseif p.tt_wrap then tag = "wrap" else tag = tg_gc_model_tag(p.model) end
            pts[#pts + 1] = { x = p.next.P.x, y = p.next.P.y, z = p.next.P.z, tag = tag }
            s.maxh = math.max(s.maxh, p.next.P.z - z0)
        end
        if p.tt_wrap then s.wraps = s.wraps + 1 end
        if p.tt_ov then s.ov = s.ov + 1 end
    end
    local notes = {}
    if info.mode == "loop" then notes[#notes + 1] = "Loop shape only - ground and buildings are checked at build"
    else notes[#notes + 1] = "Jumps and ramps are added at build" end
    if (tt.bwrap or 0) > 0 and s.wraps == 0 then notes[#notes + 1] = "No valid building wrap available" end
    if (tt.ovn or 0) > 0 and s.ov < tt.ovn then notes[#notes + 1] = string.format("Overpasses %d of %d", s.ov, tt.ovn) end
    return { points = pts, stats = s, notes = notes }
end
function tg_tt_pv_run(req)
    local P = TG_TT_PV
    P.running = true
    local co, ismain = coroutine.running()
    P.co, P.co_ok = co, (co ~= nil and ismain ~= true)
    P.cur_gen = req.gen
    local res, why = tg_tt_pv_dispatch(req)
    local stale = tg_tt_pv_stale(req.gen)
    P.co, P.co_ok = nil, false
    math.randomseed(((os.time and os.time()) or 1) + (TG_TUBEP_SEED_BUMP or 0) + 104729)
    P.running = false
    if req.gen ~= P.gen then return end                       -- stale: a newer request replaced it
    if stale then
        P.want = nil                                          -- gave way to a build: ask again later
        return
    end
    local e = { key = req.key, kind = req.kind, at = tg_tt_now() }
    if type(res) == "table" then
        e.points, e.stats, e.notes = res.points, res.stats, res.notes
    else
        e.points, e.fail = {}, tostring(why or "Preview failed")
    end
    P.cache[req.key] = e
    P.order[#P.order + 1] = req.key
    while #P.order > TG_TT_CACHE_MAX do
        local old = table.remove(P.order, 1)
        if old ~= req.key then P.cache[old] = nil end
    end
    P.last[req.kind] = e
end
-- everything that changes the planned course goes in the key (shared by the tuner preview and hovers)
function tg_tt_pv_extra(kind)
    if kind == "tubes" then return tostring(TG_TUBER_SEL and TG_TUBER_SEL.size) end
    if kind == "parkour" then return tostring(TG_PK_SEL and TG_PK_SEL.difficulty) end
    if kind == "hybrid" then
        local h = TG_HY_SEL or {}
        local ck = tg_hp_checksum_selection or function() return "" end
        return tostring(h.length) .. tostring(h.difficulty) .. ck(h.sections) .. ck(h.shapes) .. ck(h.props)
    end
    return tostring(TG_CR and TG_CR.shape) .. tostring(TG_CR and TG_CR.hills) .. tostring(TG_CR and TG_CR.loop)
end
function tg_tt_pv_key(kind, ck, v, extra)
    local lk = ({ tubes = "tubes", track = "creator", parkour = "parkour", hybrid = "hybrid" })[kind] or "creator"
    local parts = { kind, ck, extra or "", tostring(TG_CR and TG_CR.decor), tostring(tg_rs_limit(lk)), tostring(TG_WORLD_OBSTACLE_AVOIDANCE) }
    for _, d in ipairs(TG_TT_DEFS[kind]) do parts[#parts + 1] = tostring(v[d.id]) end
    return table.concat(parts, "|")
end
function tg_tt_pv_request(kind, ck, info, v, custom, extra)
    local P = TG_TT_PV
    local key = tg_tt_pv_key(kind, ck, v, extra)
    if P.cache[key] then P.want = nil; return P.cache[key], false end
    local now = tg_tt_now()
    if not P.want or P.want.key ~= key then
        P.gen = P.gen + 1
        P.want = { key = key, at = now + 400, gen = P.gen }
    end
    if P.running and (now - (P.run_t or now)) > 30000 then P.running = false end
    if not P.running and not (TG_TT_HV and TG_TT_HV.running) and now >= P.want.at and not tg_tt_busy() then
        local req = { kind = kind, key = key, gen = P.gen, info = info, v = v, custom = custom,
                      seed = (tg_hp_hash(ck)) or 12345 }
        if kind == "tubes" then
            req.a = info.style
            local sz = TG_TUBER_SEL and TG_TUBER_SEL.size
            req.fam = (sz and sz ~= "random" and TG_TUBER_FAMILIES[sz]) and sz or ((TG_TUBER_TYPES[info.style] or {}).family or "std")
        end
        P.running = true
        P.run_t = now
        Script.QueueJob(function() tg_tt_pv_run(req) end)
        P.want.at = now + 1e9                                 -- queued; a new key makes a new request
    end
    return P.last[kind], true
end

-- ---------------------------------------------------------------- UI (render callback: no yields)
function tg_tt_info_icon(text)
    ImGui.SameLine()
    ImGui.TextDisabled("(i)")
    if ImGui.IsItemHovered() then
        if tg_ui_tooltip() then ImGui.Text(tostring(text)); ImGui.EndTooltip() end
    end
end
function tg_tt_cursor()
    local x, y = 0, 0
    local xx, yy = ImGui.GetCursorScreenPos()
    if xx then x, y = xx, yy or 0 end
    return x, y
end
function tg_tt_preview_ui(kind, ck, info, v, custom)
    ImGui.TextColored(0.80, 0.54, 1.0, 1.0, "Live Preview")
    local e, pending = tg_tt_pv_request(kind, ck, info, v, custom, tg_tt_pv_extra(kind))
    local w = 560
    local avail = ImGui.GetContentRegionAvail()
    if type(avail) == "number" then w = math.max(260, math.min(760, avail - 12)) end
    local h = math.max(180, math.min(360, tonumber((TG_GRAPH_VIEW or {}).hover_height) or 230))
    local x, y = tg_tt_cursor()
    ImGui.Dummy(w, h)
    ImGui.AddRectFilled(x, y, x + w, y + h, 13, 18, 29, 244, 5)
    local shown = e and e.points and #e.points >= 2
    if shown and tg_graph_draw_route then tg_graph_draw_route(e.points, x, y, w, h) end
    if pending then ImGui.AddText(x + 10, y + h - 22, tg_tt_busy() and "Waiting for the build to finish..." or "Updating preview...", 255, 210, 120, 230)
    elseif not shown then ImGui.AddText(x + 10, y + h - 22, "No preview", 200, 200, 210, 200) end
    if e and not pending then
        if e.fail then
            ImGui.TextColored(1.0, 0.62, 0.30, 1.0, tostring(e.fail))
        elseif e.stats then
            local s = e.stats
            local line = string.format("%d pieces | max %.0f m up", s.pieces or 0, s.maxh or 0)
            if kind == "tubes" then line = line .. string.format(" | %d loops | %d wraps | %d overpasses", s.loops or 0, s.wraps or 0, s.ov or 0)
            elseif kind == "parkour" then line = line .. string.format(" | %d islands | %d jumps | longest gap %.0f m | %d props", s.islands or 0, s.jumps or 0, s.gap or 0, s.props or 0)
            elseif kind == "hybrid" then line = line .. string.format(" | %d sections | %d jumps | %d tube pieces | %d props", s.islands or 0, s.jumps or 0, s.tubes or 0, s.props or 0)
            else line = line .. string.format(" | %d wraps | %d overpasses", s.wraps or 0, s.ov or 0) end
            ImGui.Text(line)
        end
        local notes = { "Preview approximated - no spawning, no collision probes" }
        for _, n in ipairs((e and e.notes) or {}) do notes[#notes + 1] = n end
        ImGui.TextDisabled(table.concat(notes, " | "))
    end
    local n = tg_ui_push_button_colors(false, "Refresh") or 0
    local c = ImGui.Button("Refresh Preview##tt_pv_" .. kind, tg_pm_button_width("Refresh Preview", 150) or 150, 26)
    tg_ui_pop_colors(n)
    if c then
        local P = TG_TT_PV
        for k2, e2 in pairs(P.cache) do if e2.kind == kind then P.cache[k2] = nil end end
        P.want = nil
    end
    ImGui.TextDisabled("Planned from where you stand - Refresh after moving.")
    if tg_gc_settings_ui then
        local oc = ImGui.CollapsingHeader("Preview Colours##tt_gc_" .. kind)
        if oc then tg_gc_settings_ui("tt_" .. kind) end
    end
end
-- sliders for one group (inside a collapsible header)
function tg_tt_ui_group(kind, ck, info, v, g, width)
    for _, d in ipairs(TG_TT_DEFS[kind]) do
        if d.group == g then
            local label = d.name .. (d.unit or "")
            local dynwhy = info.dyn_off and info.dyn_off[d.id]
            if info.avail[d.id] == false or dynwhy then
                ImGui.TextDisabled("  " .. label .. ": unavailable")
                tg_tt_info_icon(tostring(dynwhy or info.reason[d.id] or "Not available for this course type."))
            else
                local cur = v[d.id]
                local p = info.preset[d.id]
                if d.names then label = d.name .. ": " .. tostring(d.names[cur - d.lo + 1] or cur) end
                ImGui.PushItemWidth(width)
                local nv = ImGui.SliderInt(label .. ((cur ~= p) and "  *" or "") .. "###tt_" .. kind .. "_" .. d.id, cur, d.lo, d.hi)
                ImGui.PopItemWidth()
                if type(nv) == "number" then
                    nv = tg_tt_clamp(math.floor(nv + 0.5), d.lo, d.hi)
                    if nv ~= cur then tg_tt_set(ck, info, d.id, nv); v[d.id] = nv end
                end
                local pd = d.names and tostring(d.names[p - d.lo + 1] or p) or (tostring(p) .. (d.unit and d.unit:gsub("[()]", "") or ""))
                tg_tt_info_icon(d.tip .. "\nCourse default: " .. pd)
            end
        end
    end
end
-- left column: status line + one collapsible header per group (closed by default)
function tg_tt_ui_left(kind, ck, info, v, custom)
    if custom then
        ImGui.TextColored(0.80, 0.54, 1.0, 1.0, "Tuning: Custom")
        ImGui.SameLine()
        local n = tg_ui_push_button_colors(false, "Restore") or 0
        local r = ImGui.Button("Restore Course Defaults##tt_rs_" .. kind, tg_pm_button_width("Restore Course Defaults", 200) or 200, 24)
        tg_ui_pop_colors(n)
        if r then
            TG_TT.store[ck] = nil
            tg_tt_dirty()
            for k2, x in pairs(tg_tt_vals(kind, ck, info)) do v[k2] = x end
        end
    else
        ImGui.TextDisabled("Tuning: Course defaults (" .. tostring(info.name) .. ")")
    end
    if kind == "track" then
        ImGui.TextDisabled((info.mode == "loop") and "Loop course" or "Point-to-point course")
    end
    local avail = 420
    local a = ImGui.GetContentRegionAvail()
    if type(a) == "number" then avail = a end
    -- slider + its label + the (i) must fit the column: no truncated labels
    local width = math.floor(math.max(120, math.min(230, avail - 190)))
    local dyn = (info.dyn and info.dyn(v)) or {}
    info.dyn_off = dyn
    for gi, g in ipairs(TG_TT_GROUPS_BY[kind] or TG_TT_GROUPS) do
        local changed, live = 0, 0
        for _, d in ipairs(TG_TT_DEFS[kind]) do
            if d.group == g and info.avail[d.id] ~= false and not dyn[d.id] then
                live = live + 1
                if v[d.id] ~= info.preset[d.id] then changed = changed + 1 end
            end
        end
        local title = g .. ((changed > 0) and string.format("  (%d changed)", changed) or "") .. ((live == 0) and "  (unavailable)" or "")
        local opened = ImGui.CollapsingHeader(title .. "###tt_grp_" .. kind .. "_" .. gi)
        if opened then tg_tt_ui_group(kind, ck, info, v, g, width) end
    end
end
-- two columns: sliders left (own scroll area, the same height as the preview card), preview right
function tg_tt_ui_columns(kind, ck, info, v, custom)
    ImGui.TableNextRow()
    ImGui.TableSetColumnIndex(0)
    local ph = math.max(180, math.min(360, tonumber((TG_GRAPH_VIEW or {}).hover_height) or 230))
    local pane_h = ph + 120
    -- (id, width, height, border) - the same form Startup uses. EndChild is due after every BeginChild
    if ImGui.BeginChild("##tt_left_" .. kind, 0, pane_h, true) ~= false then tg_tt_ui_left(kind, ck, info, v, custom) end
    ImGui.EndChild()
    ImGui.TableSetColumnIndex(1)
    v, custom = tg_tt_vals(kind, ck, info)
    tg_tt_preview_ui(kind, ck, info, v, custom)
end
function tg_tt_ui_body(kind, a, b)
    tg_tt_load()
    if not ImGui.CollapsingHeader("Tuner Settings##tt_hdr_" .. kind) then tg_tt_flush(false); return end
    local ck, info, why = tg_tt_course(kind, a, b)
    if not ck then
        ImGui.TextDisabled("  " .. tostring(why))
        return
    end
    local v, custom = tg_tt_vals(kind, ck, info)
    -- two columns when there's room: sliders left, live preview right
    local total = 900
    total = ImGui.GetContentRegionAvail() or total
    local cols = false
    if total >= 720 then
        local flags = ImGuiTableFlags.SizingStretchSame
        if ImGui.BeginTable("TM_TunerColumns_" .. kind, 2, flags) == true then cols = true end
    end
    if cols then
        tg_tt_ui_columns(kind, ck, info, v, custom); ImGui.EndTable()
    else
        tg_tt_ui_left(kind, ck, info, v, custom)
        v, custom = tg_tt_vals(kind, ck, info)
        ImGui.Separator()
        tg_tt_preview_ui(kind, ck, info, v, custom)
    end
    tg_tt_flush(false)
end
function tg_tt_ui(kind, a, b)
    tg_tt_ui_body(kind, a, b)
end

-- ---------------------------------------------------------------- concise BUILD log lines
TG_TT_LOG_KEYS = {
    tubes = { { "loop", "LoopBias" }, { "maxloops", "MaxLoops" }, { "spiral", "SpiralBias" }, { "cork", "CorkscrewBias" }, { "snake", "SnakeBias" },
              { "twist", "TwistBias" }, { "curve", "CurveBias" }, { "straight", "StraightBias" }, { "wrap", "WrapBias" }, { "maxwraps", "MaxWraps" },
              { "wrapdist", "WrapDist" }, { "near", "NearMiss" }, { "weave", "Weaving" }, { "sky", "SkyBridge" }, { "ovcount", "Overpasses" },
              { "ovheight", "OverpassH" }, { "height", "HeightLimit" }, { "climb", "Climb" }, { "drop", "Drop" }, { "steep", "Steepness" },
              { "smooth", "Smoothness" }, { "random", "Randomness" } },
    track = { { "straight", "Straightaway" }, { "turnfreq", "TurnFreq" }, { "sharp", "Sharpness" }, { "scurve", "SCurve" }, { "hairpin", "Hairpin" },
              { "drift", "DriftCorner" }, { "smooth", "Smoothness" }, { "snake", "Snake" }, { "maxh", "MaxHeight" }, { "hill", "Hill" },
              { "incline", "MaxIncline" }, { "bwrap", "WrapBias" }, { "ovcount", "Overpasses" }, { "ovclear", "OverpassClear" },
              { "closure", "Closure" }, { "sym", "Symmetry" }, { "variety", "Variety" }, { "complexity", "Complexity" },
              { "slen", "StraightLen" }, { "random", "Randomness" } },
}
function tg_tt_tuning_text(kind, ck, info)
    local v, custom = tg_tt_vals(kind, ck, info)
    local parts = {}
    local first = ({ tubes = "loop", track = "straight", parkour = "islands", hybrid = "segs" })[kind]
    local keys = TG_TT_LOG_KEYS[kind]
    if not keys then
        keys = {}
        for _, d in ipairs(TG_TT_DEFS[kind]) do keys[#keys + 1] = { d.id, (d.name:gsub("(%a)(%w*)", function(x, y) return x:upper() .. y end):gsub("[^%w]", "")) } end
    end
    for _, k in ipairs(keys) do
        if k[1] == first or v[k[1]] ~= info.preset[k[1]] then parts[#parts + 1] = k[2] .. "=" .. tostring(v[k[1]]) end
    end
    return "Tuning=" .. (custom and "Custom" or "Default") .. " | " .. table.concat(parts, " | ")
end
function tg_tt_log_start(tab, label)
    local course = tg_pm_label(label) or tostring(label)
    if tab == "Tubes" then
        local style = TG_TUBER_SEL and TG_TUBER_SEL.style
        local ck, info = tg_tt_course("tubes", style)
        local name = (TG_TUBER_TYPES[style] or {}).name or tostring(style)
        local line = "Type=Tubes/" .. tostring(name) .. " | Pieces=" .. tostring(tg_pm_limit(tab) or "?")
        if ck then line = line .. " | " .. tg_tt_tuning_text("tubes", ck, info) end
        return line
    elseif tab == "Track" then
        local cat = TG_CR and TG_CR.style
        local vid = (TG_CR and TG_CR.var or {})[cat] or "random"
        local ck, info = tg_tt_course("track", cat, vid)
        local line = "Type=Track/" .. tostring((TG_CR_STYLES[cat] or {}).name or cat) .. "/" .. tostring(vid) .. " | Pieces=" .. tostring(tg_pm_limit(tab) or "?")
        if ck then line = line .. " | " .. tg_tt_tuning_text("track", ck, info) end
        return line
    end
    if tab == "Parkour" then
        local style = TG_PK_SEL and TG_PK_SEL.style
        local ck, info = tg_tt_course("parkour", style)
        local line = "Type=Parkour/" .. tostring((TG_PK_STYLES[style] or {}).name or style) .. " | Pieces=" .. tostring(tg_pm_limit(tab) or "?")
        if ck then line = line .. " | " .. tg_tt_tuning_text("parkour", ck, info) end
        return line
    elseif tab == "Hybrid" then
        local mix = TG_HY_SEL and TG_HY_SEL.mix
        local ck, info = tg_tt_course("hybrid", mix)
        local line = "Type=Hybrid/" .. tostring((TG_HY_MIXES[mix] or {}).name or mix) .. " | Pieces=" .. tostring(tg_pm_limit(tab) or "?")
        if ck then line = line .. " | " .. tg_tt_tuning_text("hybrid", ck, info) end
        return line
    end
    return "Type=" .. tostring(tab) .. "/" .. tostring(course) .. " | Pieces=" .. tostring(tg_pm_limit(tab) or "-")
end
function tg_tt_log_end(ctx, status, msg, b, total, now)
    local parts = { "Type=" .. tostring(ctx.tt_type or (tostring(ctx.tab) .. "/" .. tostring(ctx.label))), "Status=" .. tostring(status or "complete") }
    if b and b.planned and b.planned > 0 then parts[#parts + 1] = "Pieces=" .. tostring(b.spawned or 0) .. "/" .. tostring(b.planned)
    else parts[#parts + 1] = "Objects=" .. tostring(total or 0) end
    local T = TG_TT_BUILD
    if ctx.tab == "Tubes" and T and T.kind == "tubes" and T.stats then
        local s = T.stats
        parts[#parts + 1] = string.format("Loops=%d | Wraps=%d | NearMiss=%d | Overpasses=%d | MaxHeight=%.0fm", s.loops, s.wraps, s.near, s.ov, s.maxh)
        parts[#parts + 1] = "Tuning=" .. (T.custom and "Custom" or "Default")
    elseif (ctx.tab == "Parkour" or ctx.tab == "Hybrid") and type(TG_PK_LAST) == "table" then
        local m = TG_PK_LAST
        local big = 0
        for _, j in ipairs(m.jumps or {}) do big = math.max(big, j.gap or 0) end
        if ctx.tab == "Parkour" then parts[#parts + 1] = string.format("Islands=%s | Jumps=%d | LongestGap=%.0fm | Props=%d", tostring(m.islands), #(m.jumps or {}), big, #(m.props or {}))
        else
            local c = m.counts or {}
            parts[#parts + 1] = string.format("Sections=%d | Jumps=%d | Tubes=%d | LongestGap=%.0fm | Props=%d", c.sections or 0, c.jumps or 0, c.tubes or 0, big, #(m.props or {}))
        end
        parts[#parts + 1] = "Tuning=" .. (m.tune and "Custom" or "Default")
    elseif ctx.tab == "Track" and TG_CR and type(TG_CR.last) == "table" and type(TG_CR.last.plans) == "table" then
        local w, o, mh, z0 = 0, 0, 0, nil
        for _, p in ipairs(TG_CR.last.plans) do
            if p.tt_wrap then w = w + 1 end
            if p.tt_ov then o = o + 1 end
            local P = p.next and p.next.P
            if P then z0 = z0 or P.z; mh = math.max(mh, P.z - z0) end
        end
        parts[#parts + 1] = string.format("Wraps=%d | Overpasses=%d | MaxHeight=%.0fm", w, o, mh)
        if T and T.kind == "track" then parts[#parts + 1] = "Tuning=" .. (T.custom and "Custom" or "Default") end
    end
    if b and (b.failed or 0) > 0 then parts[#parts + 1] = "Failed=" .. tostring(b.failed) end
    if b and b.full then parts[#parts + 1] = "ObjectBudget=FULL" end
    if now and ctx.started and now > ctx.started and ctx.started > 0 then parts[#parts + 1] = string.format("Time=%.1fs", (now - ctx.started) / 1000) end
    if msg and msg ~= "" then parts[#parts + 1] = "Result=" .. tostring(msg) end
    return table.concat(parts, " | ")
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v2.4.2 | graph colours that mean something
--   Grey by default; turn on highlights for the things you care about. Applies to the tuner
--   preview, the hover previews and the Saved/Live 3D graph. Saved with the graph settings.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_GC_PALETTE = {
    { "Grey", 150, 156, 172 }, { "Purple", 200, 120, 255 }, { "Yellow", 255, 205, 40 }, { "Orange", 255, 140, 40 },
    { "Red", 255, 70, 70 }, { "Pink", 255, 100, 190 }, { "Cyan", 60, 220, 230 }, { "Blue", 80, 150, 255 },
    { "Green", 90, 225, 120 }, { "White", 240, 240, 245 },
}
-- order = priority when a piece is more than one thing
TG_GC_CATS = {
    { id = "overpass", name = "Overpasses", col = 3, tip = "Pieces that cross over or under the course." },
    { id = "wrap", name = "Building wraps", col = 9, tip = "Pieces that curl round a building." },
    { id = "near", name = "Near misses", col = 5, tip = "Pieces that pass a building at the closest safe distance." },
    { id = "loop", name = "Loops", col = 2, tip = "Loop-the-loops (tuner preview), loop pieces (saved courses)." },
    { id = "trick", name = "Tricks", col = 6, tip = "Spirals, corkscrews, twists and S-bends (tuner preview)." },
    { id = "hairpin", name = "Hairpins & drift", col = 8, tip = "180 deg turns, U-turns and drift corners." },
    { id = "climb", name = "Climbs", col = 4, tip = "Sections rising more than ~10 deg." },
    { id = "drop", name = "Drops", col = 7, tip = "Sections falling more than ~10 deg." },
}
TG_GC = TG_GC or { mode = "highlights", base = 1, on = {}, col = {} }
function tg_gc_init_defaults()
    for _, c in ipairs(TG_GC_CATS) do
        if TG_GC.on[c.id] == nil then TG_GC.on[c.id] = true end
        if TG_GC.col[c.id] == nil then TG_GC.col[c.id] = c.col end
    end
end
tg_gc_init_defaults()
TG_GC_MODES = { { "highlights", "Highlights" }, { "height", "Height" }, { "rainbow", "Rainbow" } }

function tg_gc_rgb(i)
    local p = TG_GC_PALETTE[i] or TG_GC_PALETTE[1]
    return p[2], p[3], p[4]
end
-- what a saved / live piece is, from its model name
function tg_gc_model_tag(m)
    m = tostring(m or ""):lower()
    if m == "" then return nil end
    if m:find("loop", 1, true) then return "loop" end
    if m:find("180d", 1, true) or m:find("uturn", 1, true) or m:find("_135", 1, true) or m:find("l_b", 1, true) then return "hairpin" end
    return nil
end
function tg_gc_tag(a, b)
    local t = b.tag or (b.model and tg_gc_model_tag(b.model))
    if t and TG_GC.on[t] then return t end
    local dx, dy, dz = (b.x or 0) - (a.x or 0), (b.y or 0) - (a.y or 0), (b.z or 0) - (a.z or 0)
    local h = math.sqrt(dx * dx + dy * dy)
    if math.abs(dz) > 0.18 * math.max(h, 0.5) and math.abs(dz) > 1.0 then
        local g = (dz > 0) and "climb" or "drop"
        if TG_GC.on[g] then return g end
    end
    return nil
end
function tg_gc_seg_color(a, b, i, n, minz, maxz)
    local mode = TG_GC.mode
    if mode == "rainbow" then return nil end
    if mode == "height" then
        local t = ((((a.z or 0) + (b.z or 0)) * 0.5) - (minz or 0)) / math.max(1.0, (maxz or 1) - (minz or 0))
        t = math.max(0.0, math.min(1.0, t))
        return math.floor(70 + 185 * t), math.floor(110 + 95 * t), math.floor(200 - 160 * t)
    end
    local tag = tg_gc_tag(a, b)
    if tag then return tg_gc_rgb(TG_GC.col[tag]) end
    return tg_gc_rgb(TG_GC.base)
end
-- small legend along the bottom of a graph: only what is switched on and actually on this route
function tg_gc_legend(pieces, bx, by, bw, bh)
    if TG_GC.mode == "height" then
        ImGui.AddText(bx + 8, by + bh - 22, "Low", 70, 110, 200, 235)
        ImGui.AddText(bx + 44, by + bh - 22, "-> High", 255, 205, 40, 235)
        return
    end
    if TG_GC.mode ~= "highlights" then return end
    local seen = {}
    for i = 2, #pieces do
        local t = tg_gc_tag(pieces[i - 1], pieces[i])
        if t then seen[t] = true end
    end
    local x = bx + 8
    for _, c in ipairs(TG_GC_CATS) do
        if seen[c.id] then
            local r, g, b = tg_gc_rgb(TG_GC.col[c.id])
            if x + #c.name * 7 > bx + bw - 8 then break end
            ImGui.AddText(x, by + bh - 22, c.name, r, g, b, 240)
            x = x + #c.name * 7 + 14
        end
    end
end
-- saved with graph_and_obstacles.cfg (whitelisted keys)
function tg_gc_prefs_text()
    local out = { "gc_mode=" .. tostring(TG_GC.mode), "gc_base=" .. tostring(TG_GC.base) }
    for _, c in ipairs(TG_GC_CATS) do
        out[#out + 1] = "gc_on_" .. c.id .. "=" .. (TG_GC.on[c.id] and "1" or "0")
        out[#out + 1] = "gc_col_" .. c.id .. "=" .. tostring(TG_GC.col[c.id])
    end
    return table.concat(out, "\n")
end
function tg_gc_prefs_apply(kv)
    if kv.gc_mode == "highlights" or kv.gc_mode == "height" or kv.gc_mode == "rainbow" then TG_GC.mode = kv.gc_mode end
    local function col(v, d)
        v = tonumber(v)
        if v and v >= 1 and v <= #TG_GC_PALETTE then return math.floor(v) end
        return d
    end
    TG_GC.base = col(kv.gc_base, TG_GC.base)
    for _, c in ipairs(TG_GC_CATS) do
        local on = kv["gc_on_" .. c.id]
        if on == "1" then TG_GC.on[c.id] = true elseif on == "0" then TG_GC.on[c.id] = false end
        TG_GC.col[c.id] = col(kv["gc_col_" .. c.id], TG_GC.col[c.id])
    end
end
-- colour swatch button: click to step through the palette
function tg_gc_swatch(id, idx)
    local r, g, b = tg_gc_rgb(idx)
    local n = 0
    ImGui.PushStyleColor(ImGuiCol.Button, r / 255, g / 255, b / 255, 1.0); n = n + 1
    ImGui.PushStyleColor(ImGuiCol.ButtonHovered, r / 255, g / 255, b / 255, 0.85); n = n + 1
    ImGui.PushStyleColor(ImGuiCol.ButtonActive, r / 255, g / 255, b / 255, 0.7); n = n + 1
    local c = ImGui.Button("##gcsw_" .. id, 26, 22)
    if n > 0 then tg_ui_pop_colors(n) end
    if ImGui.IsItemHovered() and tg_ui_tooltip() then
        ImGui.Text((TG_GC_PALETTE[idx] or TG_GC_PALETTE[1])[1] .. " - click for the next colour"); ImGui.EndTooltip()
    end
    if c then return (idx % #TG_GC_PALETTE) + 1 end
    return nil
end
function tg_gc_settings_ui(sfx)
    sfx = tostring(sfx or "x")
    local changed = false
    ImGui.Text("Course colours")
    for i, m in ipairs(TG_GC_MODES) do
        if i > 1 then ImGui.SameLine() end
        local n = tg_ui_push_button_colors(TG_GC.mode == m[1], m[2]) or 0
        local c = ImGui.Button(m[2] .. "##gcm_" .. m[1] .. "_" .. sfx, tg_pm_button_width(m[2], 100) or 100, 24)
        tg_ui_pop_colors(n)
        if c and TG_GC.mode ~= m[1] then TG_GC.mode = m[1]; changed = true end
    end
    if TG_GC.mode == "highlights" then
        local nb = tg_gc_swatch("base_" .. sfx, TG_GC.base)
        if nb then TG_GC.base = nb; changed = true end
        ImGui.SameLine()
        ImGui.Text("Everything else")
        for _, c in ipairs(TG_GC_CATS) do
            local nc = tg_gc_swatch(c.id .. "_" .. sfx, TG_GC.col[c.id])
            if nc then TG_GC.col[c.id] = nc; changed = true end
            ImGui.SameLine()
            local on = TG_GC.on[c.id] == true
            local label = c.name .. (on and ": ON" or ": OFF")
            local n = tg_ui_push_button_colors(on, label) or 0
            local b = ImGui.Button(label .. "##gcon_" .. c.id .. "_" .. sfx, tg_pm_button_width(label, 170) or 170, 22)
            tg_ui_pop_colors(n)
            if b then TG_GC.on[c.id] = not on; changed = true end
            tg_tt_info_icon(c.tip)
        end
        local n = tg_ui_push_button_colors(false, "All") or 0
        local a = ImGui.Button("All on##gcall_" .. sfx, 80, 22)
        ImGui.SameLine()
        local z = ImGui.Button("All off##gcnone_" .. sfx, 80, 22)
        ImGui.SameLine()
        local r = ImGui.Button("Default colours##gcdef_" .. sfx, 140, 22)
        tg_ui_pop_colors(n)
        if a then for _, c in ipairs(TG_GC_CATS) do TG_GC.on[c.id] = true end; changed = true end
        if z then for _, c in ipairs(TG_GC_CATS) do TG_GC.on[c.id] = false end; changed = true end
        if r then TG_GC.base = 1; for _, c in ipairs(TG_GC_CATS) do TG_GC.col[c.id] = c.col end; changed = true end
    elseif TG_GC.mode == "height" then
        ImGui.TextDisabled("Blue = low, yellow = high.")
    else
        ImGui.TextDisabled("Rainbow = the old colours (start to finish).")
    end
    if changed and tg_tm_prefs_dirty then tg_tm_prefs_dirty() end
end
-- the graph prefs were read before this section existed: read them once more for the colour keys
TG_TM_PREFS_LOADED = false
tg_tm_prefs_load()

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v2.4.3 | hover previews use the real planner for tubes styles and track course styles
--   First hover shows the quick sketch ("planning..."), then the planned course with the same
--   highlights as the Live Preview. Memory only, one job at a time, gives way to builds and to
--   the tuner preview. Uses each course type's saved tuner values.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_TT_HV = TG_TT_HV or { cache = {}, order = {}, running = false, want = nil }
TG_TT_HV_MAX = 40
function tg_tt_hv_run(req)
    local H = TG_TT_HV
    local co, ismain = coroutine.running()
    H.co, H.co_ok = co, (co ~= nil and ismain ~= true)
    local res, why = tg_tt_pv_dispatch(req)
    local stale = tg_tt_pv_stale("hover")
    H.co, H.co_ok = nil, false
    math.randomseed(((os.time and os.time()) or 1) + (TG_TUBEP_SEED_BUMP or 0) + 130363)
    H.running = false
    if stale then
        H.want = nil
        return
    end
    local e = { key = req.key, kind = req.kind, at = tg_tt_now() }
    if type(res) == "table" then e.points, e.stats, e.notes = res.points, res.stats, res.notes
    else e.points, e.fail = {}, tostring(why or "no course") end
    H.cache[req.key] = e
    H.order[#H.order + 1] = req.key
    while #H.order > TG_TT_HV_MAX do
        local old = table.remove(H.order, 1)
        if old ~= req.key then H.cache[old] = nil end
    end
end
-- returns the planned entry when ready, otherwise schedules it and returns nil
function tg_tt_hv_get(kind, a, b)
    local ck, info = tg_tt_course(kind, a, b)
    if not ck then return nil end
    local v, custom = tg_tt_vals(kind, ck, info)
    local extra = tg_tt_pv_extra(kind)
    local key = tg_tt_pv_key(kind, ck, v, extra)
    local hit = TG_TT_PV.cache[key] or TG_TT_HV.cache[key]
    if hit then return hit, info end
    local H = TG_TT_HV
    local now = tg_tt_now()
    if H.running and (now - (H.run_t or now)) > 30000 then H.running = false end
    if not H.want or H.want.key ~= key then H.want = { key = key, at = now + 250 } end
    if not H.running and not TG_TT_PV.running and now >= H.want.at and not tg_tt_busy() then
        local req = { kind = kind, key = key, gen = "hover", info = info, v = v, custom = custom,
                      seed = (tg_hp_hash(ck)) or 12345 }
        if kind == "tubes" then
            req.a = info.style
            local sz = TG_TUBER_SEL and TG_TUBER_SEL.size
            req.fam = (sz and sz ~= "random" and TG_TUBER_FAMILIES[sz]) and sz or ((TG_TUBER_TYPES[info.style] or {}).family or "std")
        end
        H.running, H.run_t = true, now
        Script.QueueJob(function() tg_tt_hv_run(req) end)
        H.want.at = now + 1e9
    end
    return nil, info
end
-- which hovered buttons have a real planned course
function tg_tt_hv_target(kind, id, value)
    if kind == "tubes" and id == "tstyle" and value ~= "random" and value ~= "allmix" then return "tubes", value end
    if kind == "track" and tostring(id):find("crvar_", 1, true) == 1 then return "track", tostring(id):sub(7), value end
    if kind == "track" and id == "crstyle" then return "track", value, ((TG_CR and TG_CR.var) or {})[value] or "random" end
    if kind == "parkour" and id == "pkstyle" and value ~= "random" then return "parkour", value end
    if kind == "hybrid" and id == "hymix" and value ~= "random" and value ~= "allmix" then return "hybrid", value end
    return nil
end
TG_TT_ORIG_HP_FROM_BUTTON = TG_TT_ORIG_HP_FROM_BUTTON or tg_hp_from_button
function tg_hp_from_button(id, value, label)
    if not TG_HP_ENABLED then return end
    local kind = tg_hp_kind(id, value)
    if not kind then return end
    local hovered = ImGui.IsItemHovered()
    if not hovered then return end
    local k2, a, b = tg_tt_hv_target(kind, id, value)
    if not k2 then return TG_TT_ORIG_HP_FROM_BUTTON(id, value, label) end
    TG_HP_LAST = { kind = kind, id = id, value = value, label = label }
    local e = tg_tt_hv_get(k2, a, b)
    if e and e.points and #e.points >= 2 then
        local s = e.stats or {}
        local src = "real planner, same as Build"
        if k2 == "tubes" then src = src .. string.format(" | %d loops, %d wraps, %d overpasses", s.loops or 0, s.wraps or 0, s.ov or 0)
        elseif k2 == "parkour" then src = src .. string.format(" | %d islands, %d jumps, longest gap %.0f m", s.islands or 0, s.jumps or 0, s.gap or 0)
        elseif k2 == "hybrid" then src = src .. string.format(" | %d sections, %d jumps, %d tube pieces", s.islands or 0, s.jumps or 0, s.tubes or 0)
        else src = src .. string.format(" | %d wraps, %d overpasses", s.wraps or 0, s.ov or 0) end
        tg_hp_render_tip({ pieces = e.points, name = tostring(label or value), kind = kind, source = src })
        return
    end
    -- not planned yet (or no course fits here): the quick sketch, clearly labelled
    local entry = tg_hp_entry(kind, id, value, label)
    if entry then
        local copy = {}
        for k3, v3 in pairs(entry) do copy[k3] = v3 end
        if e and e.fail then copy.source = "sketch (no planned course here: " .. tostring(e.fail) .. ")"
        else copy.source = "sketch - planning the real course..." end
        tg_hp_render_tip(copy)
    end
end

