tg_tt_index_defs()

function tg_tt_tile_len(k)
    if k == "" or k == nil then return 0 end
    local pc = TG_PK_PIECES and (TG_PK_PIECES[k] or TG_PK_PIECES["n" .. k])
    return (pc and pc.len) or 0
end
function tg_tt_avg_len(list)
    local s, n = 0, 0
    for _, k in ipairs(list or {}) do s = s + tg_tt_tile_len(k); n = n + 1 end
    return (n > 0) and tg_tt_round(s / n) or 0
end
-- nearest real tiles for a length (run-ups may be "" = none)
function tg_tt_pk_keys(len, allow_none)
    local opts = { { "s", 17.67 }, { "m", 53 }, { "lm", 106 }, { "l", 159 } }
    if allow_none then table.insert(opts, 1, { "", 0 }) end
    table.sort(opts, function(a, b) return math.abs(a[2] - len) < math.abs(b[2] - len) end)
    local a, b = opts[1], opts[2]
    -- in between two tiles: mix them in proportion
    local da, db = math.abs(a[2] - len), math.abs(b[2] - len)
    if da < 1 then return { a[1] } end
    local na = tg_tt_round(4 * db / (da + db))
    local out = {}
    for i = 1, 4 do out[i] = (i <= na) and a[1] or b[1] end
    return out
end

function tg_tt_parkour_info(style)
    if not style or style == "random" then return nil end
    local st = TG_PK_STYLES and TG_PK_STYLES[style]
    if not st then return nil end
    local mode = st.turn_mode or (st.alternate and "alternate") or "random"
    local pat = 1
    for i, m in ipairs(TG_TT_PK_MODES) do if m == mode then pat = i end end
    local n90, nt = 0, 0
    for _, b in ipairs(st.turns or {}) do nt = nt + 1; if b == "b90" then n90 = n90 + 1 end end
    local r = st.rise or { 3, 6 }
    local P = {
        islands = tg_tt_round((st.islands[1] + st.islands[2]) / 2), start_h = tg_tt_round(st.start_h or 26),
        leash = tg_tt_round(TG_PK_LEASH or 1400), climb_p = tg_tt_round(100 * (st.up_p or 0)), climb_h = tg_tt_clamp(tg_tt_round(r[2]), 1, 8),
        curve = 100, gap0 = tg_tt_round(st.gap[1]), gap1 = tg_tt_round(st.gap[2]), grand = 1,
        drop0 = tg_tt_round(st.drop[1]), drop1 = tg_tt_round(st.drop[2]), kick = tg_tt_round((st.kick or { "m", 6 })[2]), kgrow = 20,
        ramp_p = st.ramps and tg_tt_round(100 * (st.ramp_p or 1.0)) or 0, ramp_gap = 125,
        runup = tg_tt_avg_len(st.run), landlen = tg_tt_clamp(tg_tt_avg_len(st.land), 17, 159),
        turn_p = (st.turns and #st.turns > 0) and tg_tt_round(100 * (st.turn or 0)) or 0,
        sharp = (nt > 0) and tg_tt_round(100 * n90 / nt) or 50, pattern = pat, wobble = tg_tt_round(st.jitter or 6),
        lateral = tg_tt_round(st.lateral or 0), rails = (st.rails ~= false) and 1 or 0,
        boost_p = tg_tt_round(100 * (st.boost_p or 0)), gate_p = tg_tt_round(100 * (st.gate_p or 0)), balls_p = tg_tt_round(100 * (st.balls_p or 0)),
        pins = (st.pins == "once") and 1 or ((st.pins == "final") and 2 or 0), coffset = 0, cstep = 1, accent = 0,
    }
    for _, d in ipairs(TG_TT_DEFS.parkour) do P[d.id] = tg_tt_clamp(P[d.id], d.lo, d.hi) end
    local A, R = {}, {}
    if st.mix_all then
        local why = "Random All borrows each island from another course type."
        for _, id in ipairs({ "climb_p", "climb_h", "gap0", "gap1", "drop0", "drop1", "kick", "ramp_p", "runup", "landlen", "turn_p", "sharp", "pattern", "wobble", "lateral", "rails", "boost_p", "gate_p", "balls_p", "pins" }) do A[id] = false; R[id] = why end
    end
    local info = { kind = "parkour", style = style, st = st, name = st.name or style, preset = P, avail = A, reason = R }
    info.dyn = function(v)
        local off = {}
        if v.turn_p == 0 then off.sharp = "Turn Chance is 0."; off.pattern = "Turn Chance is 0." end
        if v.climb_p == 0 then off.climb_h = "Climb Jump Chance is 0." end
        if v.ramp_p == 0 then off.ramp_gap = "Stunt Ramp Chance is 0." end
        if v.ramp_p >= 100 and v.climb_p < 100 then off.kick = "Every jump uses a stunt ramp."; off.kgrow = "Every jump uses a stunt ramp." end
        return off
    end
    return info
end
function tg_tt_hybrid_info(mix)
    local m = TG_HY_MIXES and TG_HY_MIXES[mix]
    if not m or not m.tube then return nil end
    local lenp = (TG_HY_LENGTHS and TG_HY_LENGTHS[(TG_HY_SEL or {}).length or "medium"]) or { segs = { 6, 8 } }
    local P = {
        segs = tg_tt_round((lenp.segs[1] + lenp.segs[2]) / 2), w_tube = tg_tt_round(100 * m.tube), w_jump = tg_tt_round(100 * m.jump),
        w_prop = tg_tt_round(100 * m.prop), base_w = 30, ["repeat"] = 70, climb_back = 34, leash = tg_tt_round(TG_HY_LEASH or 1400),
        g0 = 12, g1 = 20, grand = 1, jdrop = 5, hop = 100, ddepth = 11, uheight = 6, ramp_gap = 125, kick = 7,
        preboost = 40, stunt_p = 45, balls = 3, tyres = 4, tube_exit = 3, land = 3, wobble = 6, start_bonus = 0,
        rpitch = tg_tt_round(TG_PK_RAMP_PITCH or 10), curve = 100, coffset = 0, cstep = 1, tube_accent = 0,
    }
    for _, d in ipairs(TG_TT_DEFS.hybrid) do P[d.id] = tg_tt_clamp(P[d.id], d.lo, d.hi) end
    return { kind = "hybrid", mix = mix, name = m.name or mix, preset = P, avail = {}, reason = {} }
end

-- the tuned values a planner run uses: set right before the call, taken at its first line
TG_TT_NEXT = TG_TT_NEXT or {}
function tg_tt_take(kind)
    local t = TG_TT_NEXT[kind]
    TG_TT_NEXT[kind] = nil
    return t or nil
end
function tg_tt_pk_runtime(info, v, custom)
    if not custom then return nil end
    local st, P = info.st, info.preset
    local function ch(id) return v[id] ~= P[id] and info.avail[id] ~= false end
    local O = {}
    for k, x in pairs(st) do O[k] = x end
    if ch("islands") then O.islands = { math.max(2, v.islands - 1), v.islands + 1 } end
    if ch("start_h") then O.start_h = v.start_h end
    if ch("climb_p") then O.up_p = (v.climb_p > 0) and (v.climb_p / 100.0) or nil end
    if ch("climb_h") then O.rise = { math.max(1.0, v.climb_h * 0.5), v.climb_h } end
    if ch("gap0") or ch("gap1") then O.gap = { v.gap0, math.max(v.gap0, v.gap1) } end
    if ch("drop0") or ch("drop1") then O.drop = { v.drop0, v.drop1 } end
    if ch("kick") then O.kick = { (st.kick or { "m" })[1], v.kick } end
    if ch("ramp_p") then
        if v.ramp_p > 0 then O.ramps = st.ramps or { "a", "b" }; O.ramp_p = v.ramp_p / 100.0 else O.ramps = nil end
    end
    if ch("runup") then O.run = tg_tt_pk_keys(v.runup, true) end
    if ch("landlen") then O.land = tg_tt_pk_keys(v.landlen, false) end
    if ch("turn_p") then
        O.turn = v.turn_p / 100.0
        if v.turn_p > 0 and not (st.turns and #st.turns > 0) then O.turns = { "b45", "b90" } end
    end
    if ch("sharp") and v.turn_p > 0 then
        local n90 = tg_tt_round(v.sharp / 10)
        local L = {}
        for i = 1, 10 do L[i] = (i <= n90) and "b90" or "b45" end
        O.turns = L
    end
    if ch("pattern") then O.turn_mode = TG_TT_PK_MODES[v.pattern]; O.alternate = nil end
    if ch("wobble") then O.jitter = v.wobble end
    if ch("lateral") then O.lateral = (v.lateral > 0) and v.lateral or nil end
    if ch("rails") then O.rails = (v.rails == 1) end
    if ch("boost_p") then O.boost_p = (v.boost_p > 0) and (v.boost_p / 100.0) or nil end
    if ch("gate_p") then O.gate_p = (v.gate_p > 0) and (v.gate_p / 100.0) or nil end
    if ch("balls_p") then O.balls_p = (v.balls_p > 0) and (v.balls_p / 100.0) or nil end
    if ch("pins") then
        if v.pins == 1 then O.pins = "once" elseif v.pins == 2 then O.pins = "final" else O.pins = nil end
    end
    local T = { st = O }
    if ch("leash") then T.leash = v.leash end
    if ch("curve") then T.curve = v.curve / 100.0 end
    if ch("grand") then T.grand = v.grand end
    if ch("kgrow") then T.kgrow = v.kgrow / 100.0 end
    if ch("ramp_gap") then T.ramp_gap = v.ramp_gap / 100.0 end
    if ch("coffset") then T.coffset = v.coffset end
    if ch("cstep") then T.cstep = v.cstep end
    if v.accent > 0 then T.accent = v.accent end
    return T
end
function tg_tt_ball_ys(n)
    return ({ { 0.0 }, { -4.0, 4.0 }, { -6.0, 0.0, 6.0 }, { -7.5, -2.5, 2.5, 7.5 }, { -8.0, -4.0, 0.0, 4.0, 8.0 } })[n] or { -6.0, 0.0, 6.0 }
end
function tg_tt_hy_runtime(info, v, custom)
    if not custom then return nil end
    local P = info.preset
    local function ch(id) return v[id] ~= P[id] end
    local T = {}
    if ch("segs") then T.segs = v.segs end
    if ch("w_tube") or ch("w_jump") or ch("w_prop") then T.mixw = { v.w_tube / 100.0, v.w_jump / 100.0, v.w_prop / 100.0 } end
    if ch("base_w") then T.base_w = v.base_w / 100.0 end
    if ch("repeat") then T.repeat_k = math.max(0.01, 1.0 - v["repeat"] / 100.0) end
    if ch("climb_back") then T.climb_back = v.climb_back end
    if ch("leash") then T.leash = v.leash end
    if ch("g0") or ch("g1") then T.g0 = v.g0; T.g1 = math.max(v.g0, v.g1) end
    if ch("grand") then T.grand = v.grand end
    if ch("jdrop") then T.jdrop = v.jdrop end
    if ch("hop") then T.hop_k = v.hop / 100.0 end
    if ch("ddepth") then T.ddepth = v.ddepth end
    if ch("uheight") then T.uheight = v.uheight end
    if ch("ramp_gap") then T.ramp_gap = v.ramp_gap / 100.0 end
    if ch("kick") then T.kick_k = v.kick / 7.0 end
    if ch("preboost") then T.preboost = v.preboost / 100.0 end
    if ch("stunt_p") then T.stunt_p = v.stunt_p / 100.0 end
    if ch("balls") then T.ball_ys = tg_tt_ball_ys(v.balls) end
    if ch("tyres") then T.tyres = v.tyres end
    if ch("tube_exit") then T.tube_exit = TG_TT_TILE_KEYS[v.tube_exit] end
    if ch("land") then T.land = TG_TT_TILE_KEYS[v.land] end
    if ch("wobble") then T.wobble = v.wobble end
    if ch("start_bonus") then T.start_bonus = v.start_bonus end
    if ch("rpitch") then T.rpitch = v.rpitch end
    if ch("curve") then T.curve = v.curve / 100.0 end
    if ch("coffset") then T.coffset = v.coffset end
    if ch("cstep") then T.cstep = v.cstep end
    if v.tube_accent > 0 then T.tube_accent = v.tube_accent end
    return T
end
-- spawn colours: kicker / tube accents, offset and step on the chosen colour mode
function tg_tt_tint(T, plan, tint)
    if not T then return tint end
    if T.accent and plan.kicker then return T.accent end
    if T.tube_accent and plan.is_tube then return T.tube_accent end
    if tint and (T.coffset or T.cstep) then tint = (((tint - 1) * (T.cstep or 1)) + (T.coffset or 0)) % 15 + 1 end
    return tint
end
-- builds: hand the planner the tuned values of the SELECTED course type (customised only)
TG_TT_ORIG_PK_PLAN = TG_TT_ORIG_PK_PLAN or tg_pk_plan_course
function tg_pk_plan_course(style_key, diff_key)
    TG_TT_NEXT.parkour = tg_tt_pk_build_tune(style_key)
    return TG_TT_ORIG_PK_PLAN(style_key, diff_key)
end
-- tuned values of the selected parkour style (nil for any other style)
function tg_tt_pk_build_tune(style_key)
    if style_key ~= (TG_PK_SEL and TG_PK_SEL.style) then return nil end
    local info = tg_tt_parkour_info(style_key)
    if not info then return nil end
    local v, custom = tg_tt_vals("parkour", "parkour:" .. style_key, info)
    return tg_tt_pk_runtime(info, v, custom)
end
TG_TT_ORIG_HY_PLAN = TG_TT_ORIG_HY_PLAN or tg_hy_plan_course
function tg_hy_plan_course()
    TG_TT_NEXT.hybrid = tg_tt_hy_build_tune()
    return TG_TT_ORIG_HY_PLAN()
end
-- tuned values of the selected hybrid mix
function tg_tt_hy_build_tune()
    local mix = TG_HY_SEL and TG_HY_SEL.mix
    local info = tg_tt_hybrid_info(mix)
    if not info then return nil end
    local v, custom = tg_tt_vals("hybrid", "hybrid:" .. mix, info)
    return tg_tt_hy_runtime(info, v, custom)
end
-- previews never run collision probes (builds always do)
TG_TT_ORIG_LINE_PROBE = TG_TT_ORIG_LINE_PROBE or tg_world_obstacle_line_probe
if TG_TT_ORIG_LINE_PROBE then
    function tg_world_obstacle_line_probe(...)
        local co = coroutine.running()
        local P, H = TG_TT_PV, TG_TT_HV
        if co and ((P.co_ok and co == P.co) or (H and H.co_ok and co == H.co)) then return false, nil, nil, "preview" end
        return TG_TT_ORIG_LINE_PROBE(...)
    end
end

-- preview points for island / hybrid courses, tagged for the course colours
function tg_tt_pv_points_pk(plans)
    local pts = {}
    for i, p in ipairs(plans) do
        local tag = nil
        local pc = p.key and TG_PK_PIECES and TG_PK_PIECES[p.key]
        if p.is_tube then tag = "tube" elseif p.kicker then tag = "kicker" elseif pc and pc.kind == "bend" then tag = "corner" end
        local e = p.entry or (p.samples and p.samples[1])
        if e and (i == 1 or p.tt_gap) then pts[#pts + 1] = { x = e.x, y = e.y, z = e.z, tag = p.tt_gap and "gap" or nil } end
        if p.is_tube and p.samples and #p.samples >= 5 then
            local q = p.samples[math.floor(#p.samples / 2) + 1]
            pts[#pts + 1] = { x = q.x, y = q.y, z = q.z, tag = tag }
        end
        if p.next and p.next.P then pts[#pts + 1] = { x = p.next.P.x, y = p.next.P.y, z = p.next.P.z, tag = tag } end
    end
    return pts
end
function tg_tt_pv_islands(req, plan_fn, T, kind)
    local plans, meta
    for attempt = 1, 4 do
        if tg_tt_pv_stale(req.gen) then return nil, "stale" end
        math.randomseed(req.seed + attempt * 7919)
        if TG_HYS then TG_HYS.rand_props, TG_HYS.pins_used = nil, nil end
        TG_TT_NEXT[kind] = T
        plans, meta = plan_fn()
        TG_TT_NEXT[kind] = nil
        if plans then break end
        util.yield(0)
    end
    if not plans then return nil, "No valid course at these settings here (" .. tostring(meta) .. ")" end
    local z0 = plans[1] and plans[1].entry and plans[1].entry.z or 0
    local st = { pieces = #plans, jumps = #(meta.jumps or {}), props = #(meta.props or {}), maxh = 0, gap = 0, tubes = 0,
                 islands = meta.islands or (meta.counts and meta.counts.sections) or 0 }
    for _, p in ipairs(plans) do
        if p.next and p.next.P then st.maxh = math.max(st.maxh, p.next.P.z - z0) end
        if p.is_tube then st.tubes = st.tubes + 1 end
    end
    for _, j in ipairs(meta.jumps or {}) do st.gap = math.max(st.gap, j.gap or 0) end
    return { points = tg_tt_pv_points_pk(plans), stats = st, notes = { "Props are placed at build" } }
end
function tg_tt_pv_parkour(req)
    TG_PK_MAX_OBJECTS = tg_rs_limit("parkour")
    local T = tg_tt_pk_runtime(req.info, req.v, req.custom)
    local style, diff = req.info.style, (TG_PK_SEL and TG_PK_SEL.difficulty) or "normal"
    return tg_tt_pv_islands(req, function() return TG_TT_ORIG_PK_PLAN(style, diff) end, T, "parkour")
end
function tg_tt_pv_hybrid(req)
    TG_HY_MAX_OBJECTS = tg_rs_limit("hybrid")
    local T = tg_tt_hy_runtime(req.info, req.v, req.custom)
    -- a hovered mix that isn't the selected one: plan with its section weights (the selection is never touched)
    if req.info.mix ~= (TG_HY_SEL and TG_HY_SEL.mix) and not (T and T.mixw) then
        local m = TG_HY_MIXES[req.info.mix]
        T = T or {}
        T.mixw = { m.tube, m.jump, m.prop }
    end
    return tg_tt_pv_islands(req, function() return TG_TT_ORIG_HY_PLAN() end, T, "hybrid")
end
function tg_tt_pv_dispatch(req)
    if req.kind == "tubes" then return tg_tt_pv_tubes(req) end
    if req.kind == "parkour" then return tg_tt_pv_parkour(req) end
    if req.kind == "hybrid" then return tg_tt_pv_hybrid(req) end
    return tg_tt_pv_track(req)
end

-- new highlight colours for island courses
function tg_gc_add_island_cats()
for _, c in ipairs({
    { id = "gap", name = "Jump gaps", col = 10, tip = "The flight from a lip to its landing (Parkour / Hybrid)." },
    { id = "kicker", name = "Kickers & ramps", col = 3, tip = "Take-off tiles and stunt-ramp decks (Parkour / Hybrid)." },
    { id = "tube", name = "Tube sections", col = 2, tip = "Tube pieces inside Hybrid courses." },
    { id = "corner", name = "Corners", col = 8, tip = "Flat corner tiles (Parkour / Hybrid)." },
}) do
    local have = false
    for _, e in ipairs(TG_GC_CATS) do if e.id == c.id then have = true end end
    if not have then table.insert(TG_GC_CATS, c) end
end
end
tg_gc_add_island_cats()
