-- ═══════════════════════════════════════════════════════════════════════════════════
-- v2.6.0 | drift: point-to-point drift runs in the track tab (between circuit and drift loop)
--   90 presets (18 hand-made + 4 variations each). Mostly curves: the planner's road pieces with
--   preset-level drift knobs - alternating turns, drift corners (tight 90s / 135s / kick chicanes),
--   flowing 15-45 deg sweepers, hairpins, short straight runs, flat decks or downhill touge runs.
--   Arrow tyres on the outside of every corner (the Drift Loop decor), no speed pads, no jumps.
-- ═══════════════════════════════════════════════════════════════════════════════════
-- extra score for a drift preset's candidate piece (bounded: no world lookups)
function tg_cr_drift_score(V, state, p, score)
    local pc = TG_CR_P[p.model]
    local turn = (p.rev and -1 or 1) * ((pc and pc.turn) or 0)
    local at = math.abs(turn)
    if state.dr_n ~= state.n then
        state.dr_n = state.n
        local lm = state.last_model and TG_CR_P[state.last_model]
        state.dr_run = (lm and lm.k == "straight") and ((state.dr_run or 0) + 1) or 0
    end
    if at > 1 then
        local sgn = (turn > 0) and 1 or -1
        if V.alt and state.last_turn_sign and state.last_turn_sign ~= sgn then score = score + V.alt end
        if V.dc and tg_tt_is_drift_model(p.model) then score = score + V.dc end
        if V.sweep and at >= 14 and at <= 46 then score = score + V.sweep end
        if V.hairb and at > 170 then score = score + V.hairb end
    elseif p.k == "straight" then
        if V.maxrun and (state.dr_run or 0) >= V.maxrun then score = score - 1.5 * ((state.dr_run or 0) - V.maxrun + 1)
        elseif V.straightb then score = score + V.straightb end
    end
    if V.flatk and V.flatk > 0 then score = score - math.abs(tg_cr_pitch_of(p.next.R)) * V.flatk end
    return score
end
function tg_cr_register_drift_runs()
    if not (TG_CR_STYLES and TG_CR_VARIANTS and TG_CR_DRIFT_RUNS) then return end
    TG_CR_STYLES.driftrun = { name = "Drift", fam = "road", loop = false, learned = "drift", drift = true, hmin = 0.0, hmax = 25.0,
        desc = "Point-to-point drift runs packed with curves: esses, kicks, hairpins and sweepers, arrow tyres on every apex.",
        maps = "Ultimate Drift Track, Spindrift and touge-style downhill runs" }
    TG_CR_VARIANTS.driftrun = TG_CR_DRIFT_RUNS
    local function after(list, key, new)
        for _, k in ipairs(list) do if k == new then return end end
        for i, k in ipairs(list) do if k == key then table.insert(list, i + 1, new); return end end
        table.insert(list, new)
    end
    after(TG_CR_STYLE_ORDER, "circuit", "driftrun")
    after(TG_CR_CAT_ORDER, "circuit", "driftrun")
    after(TG_CR_CAT_MENU, "circuit", "driftrun")
    if TG_CR_CAT_NAMES then TG_CR_CAT_NAMES.driftrun = "Drift"; TG_CR_CAT_NAMES.drift = "Drift Loop" end
    if TG_CR and TG_CR.var and TG_CR.var.driftrun == nil then TG_CR.var.driftrun = "random" end
end
tg_cr_register_drift_runs()

