-- ═══════════════════════════════════════════════════════════════════════════════════
-- v2.10.0 | auto start marker (icon only)
--   After a course build: a yellow flag icon + GPS line to the start on your map. No props, no effects.
--   Map icons only show for you. Switch: Home tab, under Track Ramp. OFF by default, saved with the graph settings.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_SM = TG_SM or { blips = {} }
TG_SM.blips = TG_SM.blips or {}
TG_SM.auto = (TG_SM.auto == true)
TG_SM_H = {
    ADD_BLIP_FOR_COORD = 0x5A039BB0BCA604B6, SET_BLIP_SPRITE = 0xDF735600A4696DAF, SET_BLIP_COLOUR = 0x03D7FB09E75D6B7E,
    SET_BLIP_SCALE = 0xD38744167B2FA257, SET_BLIP_AS_SHORT_RANGE = 0xBE8BE4FE60E27B72, SET_BLIP_DISPLAY = 0x9029B2F3DA924928,
    SET_BLIP_ALPHA = 0x45FF974EEE1C8734, SET_BLIP_ROUTE = 0x4F7D8A9BFB0B43E9, SET_BLIP_ROUTE_COLOUR = 0x837155CD2F63DA09,
    BEGIN_BLIP_NAME = 0xF9113A30DE5C6670, ADD_TEXT_STR = 0x6C188BE134E074AA, END_BLIP_NAME = 0xBC38B49BCB83BC9B,
    SET_BLIP_PRIORITY = 0xAE9FC9EF6A9FAC79, SET_BLIP_HIGH_DETAIL = 0xE2590BC29220CEBB,
}
-- where the course starts: the latest build's start, else where you stand
function tg_sm_start()
    local tubes_like = { ["Tube Race"] = true, ["Parkour"] = true, ["Hybrid"] = true }
    local t = TG_TUBEC_TIMER
    local r = TG_CR_RUN
    local P, D = nil, nil
    if r and r.tp and r.tp.P and not tubes_like[TG_SM_LAST_LABEL or ""] then
        P = r.tp.P
        local psi = r.tp.psi or 0
        D = { x = math.cos(psi), y = math.sin(psi), z = 0 }
    elseif t and t.P then
        P = t.drive_spot or t.P
        D = t.drive_dir or t.D
    end
    if not P then
        local pos = tg_get_local_position_heading("start_marker")
        P, D = { x = pos.x, y = pos.y, z = pos.z }, { x = 0, y = 1, z = 0 }
    end
    local g = (tg_tr_ground_z(P.x, P.y, P.z)) or P.z
    if g > P.z + 30 or g < P.z - 60 then g = P.z end
    return { x = P.x, y = P.y, z = g }, D or { x = 0, y = 1, z = 0 }
end
TG_SM_ORIG_BUILD_START = TG_SM_ORIG_BUILD_START or tg_rs_build_start
function tg_rs_build_start(label)
    TG_SM_LAST_LABEL = label
    return TG_SM_ORIG_BUILD_START(label)
end
function tg_sm_is_course_label(label)
    label = tostring(label or "")
    if label == "Tube Race" or label == "Parkour" or label == "Hybrid" then return true end
    for _, st in pairs(TG_CR_STYLES or {}) do if st.name == label then return true end end
    return false
end
-- removes the flag icon(s) and GPS line
function tg_sm_clear()
    for _, b in ipairs(TG_SM.blips) do
        tg_tn_void(TG_SM_H.SET_BLIP_ROUTE, b, false)
        tg_tn_void(TG_SM_H.SET_BLIP_ALPHA, b, 0)
        tg_tn_void(TG_SM_H.SET_BLIP_DISPLAY, b, 0)
    end
    TG_SM.blips = {}
end
function tg_sm_auto_run()
    util.yield(1500)                                   -- builders arm their start right after "done"
    tg_sm_clear()
    local P = tg_sm_start()
    TG_SM.P = P
    local b = tg_tn_int(TG_SM_H.ADD_BLIP_FOR_COORD, P.x + 0.0, P.y + 0.0, P.z + 0.0)
    if not b or b == 0 then return end
    tg_tn_void(TG_SM_H.SET_BLIP_SPRITE, b, 38)                -- race flag
    tg_tn_void(TG_SM_H.SET_BLIP_COLOUR, b, 5)                 -- yellow
    tg_tn_void(TG_SM_H.SET_BLIP_SCALE, b, 1.2)
    tg_tn_void(TG_SM_H.SET_BLIP_AS_SHORT_RANGE, b, false)    -- stays on the minimap edge when far away
    tg_tn_void(TG_SM_H.SET_BLIP_DISPLAY, b, 2)               -- pause map and minimap
    tg_tn_void(TG_SM_H.SET_BLIP_PRIORITY, b, 12)
    tg_tn_void(TG_SM_H.SET_BLIP_HIGH_DETAIL, b, true)
    tg_tn_void(TG_SM_H.BEGIN_BLIP_NAME, "STRING")
    tg_tn_void(TG_SM_H.ADD_TEXT_STR, "TrackMatic Start")
    tg_tn_void(TG_SM_H.END_BLIP_NAME, b)
    tg_tn_void(TG_SM_H.SET_BLIP_ROUTE, b, true)               -- GPS line
    tg_tn_void(TG_SM_H.SET_BLIP_ROUTE_COLOUR, b, 5)
    table.insert(TG_SM.blips, b)
end
TG_SM_ORIG_DONE = TG_SM_ORIG_DONE or tg_rs_progress_done
function tg_rs_progress_done(msg)
    local rv = TG_SM_ORIG_DONE(msg)
    if TG_SM.auto and tg_sm_is_course_label(TG_SM_LAST_LABEL) then
        TG_SM_LAST_LABEL = nil                         -- once per build
        Script.QueueJob(tg_sm_auto_run)
    end
    return rv
end
-- Home tab row (under Track Ramp)
function tg_sm_home_row()
    tg_rs_toggle_row("Auto Start Marker", TG_SM.auto, function()
        TG_SM.auto = not TG_SM.auto
        if not TG_SM.auto then tg_sm_clear() end
        tg_tm_prefs_dirty()
    end)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- v2.10.0 | colour for track and lab (default / #1-#15 / rainbow / random), like tubes
--   Default keeps each style's own colours, so untouched builds look exactly as before.
-- ═══════════════════════════════════════════════════════════════════════════════════
TG_CC_ORDER = { "off", "single", "rainbow", "random" }
TG_CR.colour = TG_CR.colour or "off"
TG_CR.colour_index = TG_CR.colour_index or 1
TG_LAB.colour = TG_LAB.colour or "off"
TG_LAB.colour_index = TG_LAB.colour_index or 1
function tg_cc_colour_row(id, sel, title)
    local colours = {}
    for _, k in ipairs(TG_CC_ORDER) do
        table.insert(colours, { k, (k == "single") and ("#" .. tostring(sel.colour_index)) or ((TG_PK_COLOUR_NAMES and TG_PK_COLOUR_NAMES[k]) or k) })
    end
    table.insert(colours, { "next", ">" })
    tg_ui_choice_row(title or "Colour", id, colours, sel.colour, function(v)
        if v == "next" then sel.colour_index = (sel.colour_index % 15) + 1; sel.colour = "single" else sel.colour = v end
        tg_tm_prefs_dirty()
    end, 5, 90)
end
-- colour index for piece i (nil = keep the style's own colour)
function tg_cc_tint(sel, i)
    local m = sel and sel.colour
    if m == "single" then return sel.colour_index or 1 end
    if m == "rainbow" then return ((i or 1) % 15) + 1 end
    if m == "random" then return math.random(1, 15) end
    return nil
end
-- Track: every category (circuit, sprint, drift, loops, hybrid ...) picks its piece colours here
TG_CC_ORIG_CR_TINT = TG_CC_ORIG_CR_TINT or tg_cr_tint_for
function tg_cr_tint_for(tint, i)
    local c = tg_cc_tint(TG_CR, i)
    if c then return c end
    return TG_CC_ORIG_CR_TINT(tint, i)
end
-- Lab: air race gates, stunt park pieces, arena gauntlet
TG_CC_ORIG_LAB_PLACE = TG_CC_ORIG_LAB_PLACE or tg_lab_place
function tg_lab_place(model, P, yaw, mode, label)
    local obj = TG_CC_ORIG_LAB_PLACE(model, P, yaw, mode, label)
    if obj then
        local c = tg_cc_tint(TG_LAB, tonumber(tostring(label or ""):match("(%d+)$")))
        if c then tg_pk_tint(obj, c) end
    end
    return obj
end
TG_CC_ORIG_CR_SPAWN = TG_CC_ORIG_CR_SPAWN or tg_cr_spawn_obj
function tg_cr_spawn_obj(model, o, pitch, roll, yaw, label, dynamic, tint)
    if tint == nil and tostring(label or ""):find("lab_park", 1, true) == 1 then
        tint = tg_cc_tint(TG_LAB, tonumber(tostring(label):match("(%d+)$")))
    end
    return TG_CC_ORIG_CR_SPAWN(model, o, pitch, roll, yaw, label, dynamic, tint)
end
TG_CC_ORIG_ARENA = TG_CC_ORIG_ARENA or tg_lab_arena_build
function tg_lab_arena_build()
    if (TG_LAB.colour or "off") == "off" or not TG_HY_SEL then return TG_CC_ORIG_ARENA() end
    local sel = TG_HY_SEL
    local km, ki = sel.colour, sel.colour_index
    sel.colour, sel.colour_index = TG_LAB.colour, TG_LAB.colour_index
    local r = TG_CC_ORIG_ARENA()
    sel.colour, sel.colour_index = km, ki
    return r
end

-- saved with the graph prefs (new key: everyone starts with the start marker OFF)
TG_SM_ORIG_GC_TEXT = TG_SM_ORIG_GC_TEXT or tg_gc_prefs_text
function tg_gc_prefs_text()
    return TG_SM_ORIG_GC_TEXT() .. "\nstart_marker=" .. (TG_SM.auto and "1" or "0")
        .. "\ncr_colour=" .. tostring(TG_CR.colour) .. "\ncr_colour_i=" .. tostring(TG_CR.colour_index)
        .. "\nlab_colour=" .. tostring(TG_LAB.colour) .. "\nlab_colour_i=" .. tostring(TG_LAB.colour_index)
end
TG_SM_ORIG_GC_APPLY = TG_SM_ORIG_GC_APPLY or tg_gc_prefs_apply
function tg_gc_prefs_apply(kv)
    TG_SM_ORIG_GC_APPLY(kv)
    if kv.start_marker == "0" then TG_SM.auto = false elseif kv.start_marker == "1" then TG_SM.auto = true end
    local modes = { off = true, single = true, rainbow = true, random = true }
    if modes[kv.cr_colour or ""] then TG_CR.colour = kv.cr_colour end
    if modes[kv.lab_colour or ""] then TG_LAB.colour = kv.lab_colour end
    local ci, li = tonumber(kv.cr_colour_i), tonumber(kv.lab_colour_i)
    if ci and ci >= 1 and ci <= 15 then TG_CR.colour_index = math.floor(ci) end
    if li and li >= 1 and li <= 15 then TG_LAB.colour_index = math.floor(li) end
end
TG_TM_PREFS_LOADED = false
tg_tm_prefs_load()